bool GLContext::readPixels(GLint x, GLint y, GLsizei width, GLsizei height, GLenum format, GLenum type, void* pixels) {
    // GL 4.6 §18.3.1: when GL_PIXEL_PACK_BUFFER is bound, `pixels` is
    // a BYTE OFFSET into the bound PBO, and offset 0 is perfectly
    // legal (CTS `buffer_storage.map_persistent_read_pixels` passes
    // offset=0 repeatedly). Only treat a null `pixels` as INVALID_VALUE
    // when no PBO is bound — otherwise it's an offset, not a pointer.
    const bool packPBOBound = impl_->state->boundBuffer(GL_PIXEL_PACK_BUFFER) != 0;
    if (pixels == nullptr && !packPBOBound) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (width < 0 || height < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (width == 0 || height == 0) {
        return true;
    }

    // When a PBO is bound, resolve the offset into the shadow byte
    // buffer so the downstream readback paths (readFramebufferPixels,
    // readFBOColorNative) can write into the PBO's shadow memory.
    // Note: `requiredBytes` passed to resolvePackPBO is the MAXIMUM
    // bytes the native readback could produce — we use bytesPerPixel
    // of the requested format × width × height. This is the full
    // RGBA equivalent when readback falls back to the converter path.
    if (packPBOBound) {
        const std::size_t packBytes = static_cast<std::size_t>(width) *
            static_cast<std::size_t>(height) * std::max<std::size_t>(bytesPerPixel(format, type), 1);
        const std::size_t typeBytes = std::max<std::size_t>(bytesPerComponent(type), 1);
        auto [packDest, packOk] = impl_->resolvePackPBO(pixels, packBytes, typeBytes);
        if (!packOk) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        pixels = packDest;
    }

    if (impl_->state->boundReadFramebuffer() != 0) {
        // Widen FBO readback acceptance to match GL 4.6 §18.3.2. The
        // single-component formats (GL_GREEN / GL_BLUE / GL_ALPHA) and
        // their _INTEGER variants were missing, which made
        // KHR-GL46.packed_pixels tests see "valid format used but
        // glReadPixels failed" on combos the spec explicitly permits.
        const bool isColorReadback =
            (format == GL_RED || format == GL_GREEN || format == GL_BLUE
             || format == GL_RG || format == GL_RGB || format == GL_RGBA
             || format == GL_BGR || format == GL_BGRA
             || format == GL_RED_INTEGER || format == GL_GREEN_INTEGER
             || format == GL_BLUE_INTEGER
             || format == GL_RG_INTEGER || format == GL_RGB_INTEGER
             || format == GL_RGBA_INTEGER
             || format == GL_BGR_INTEGER || format == GL_BGRA_INTEGER);
        // GL 4.6 Table 18.2 — GL_DEPTH_COMPONENT readback accepts any
        // scalar type (byte/short/int/half/float and unsigned variants).
        // The packed depth-stencil types (GL_UNSIGNED_INT_24_8 and
        // GL_FLOAT_32_UNSIGNED_INT_24_8_REV) are NOT compatible with
        // GL_DEPTH_COMPONENT — they require format=GL_DEPTH_STENCIL,
        // and rejecting them here surfaces the INVALID_OPERATION CTS
        // expects (`packed_pixels.rectangle.depth_component16_format
        // _depth_component` checks for the rejection explicitly).
        const bool isDepthReadback = (format == GL_DEPTH_COMPONENT
            && (type == GL_UNSIGNED_BYTE || type == GL_BYTE
                || type == GL_UNSIGNED_SHORT || type == GL_SHORT
                || type == GL_UNSIGNED_INT || type == GL_INT
                || type == GL_FLOAT || type == GL_HALF_FLOAT));
        // Detect the cross-class spec violation: a depth/stencil/depth-
        // stencil format paired with a type that is otherwise valid for
        // some other class. Without this check the fall-through at line
        // 7917 raises INVALID_ENUM, but Table 18.2 says the right error
        // is INVALID_OPERATION.
        const bool isDepthStencilPackedType = (type == GL_UNSIGNED_INT_24_8
            || type == GL_FLOAT_32_UNSIGNED_INT_24_8_REV);
        if (format == GL_DEPTH_COMPONENT && isDepthStencilPackedType) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        if (format == GL_STENCIL_INDEX && isDepthStencilPackedType) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL_DEPTH_STENCIL readback is also accepted by the spec with
        // the two depth-stencil packed types.
        const bool isDepthStencilReadback = (format == GL_DEPTH_STENCIL
            && (type == GL_UNSIGNED_INT_24_8
                || type == GL_FLOAT_32_UNSIGNED_INT_24_8_REV));
        // GL 4.6 Table 8.3: GL_STENCIL_INDEX accepts any scalar type
        // (byte/short/int/float and their variants). Narrowing to only
        // GL_UNSIGNED_BYTE fails CTS framebuffers_clear which reads
        // stencil as GL_INT.
        const bool isStencilReadback = (format == GL_STENCIL_INDEX
            && (type == GL_UNSIGNED_BYTE || type == GL_BYTE
                || type == GL_UNSIGNED_SHORT || type == GL_SHORT
                || type == GL_UNSIGNED_INT || type == GL_INT
                || type == GL_FLOAT || type == GL_HALF_FLOAT));
        if (!isColorReadback && !isDepthReadback && !isStencilReadback
            && !isDepthStencilReadback) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
        // Sprint 9 Phase 2 (CKPT102): GL 4.6 §16.1 — depth/stencil read
        // formats require the FBO to have the corresponding attachment.
        // CTS packed_pixels.* tests assert "Invalid format used but
        // glReadPixels succeeded" when reading GL_DEPTH_STENCIL from an
        // FBO whose color attachment is RGBA8. The 804 such "invalid
        // format succeeded" failures across the packed_pixels suite all
        // share this gap.
        if (isDepthReadback || isStencilReadback || isDepthStencilReadback) {
            const GLuint fbName = impl_->state->boundReadFramebuffer();
            const GLFramebufferObject* fb = impl_->objects->framebuffers().get(fbName);
            bool hasDepth = false, hasStencil = false;
            if (fb != nullptr) {
                auto attachmentLive = [&](GLenum point) -> bool {
                    auto it = fb->attachments.find(point);
                    return it != fb->attachments.end() &&
                           it->second.kind != GLFramebufferAttachment::Kind::None &&
                           it->second.object != 0;
                };
                if (attachmentLive(GL_DEPTH_ATTACHMENT) ||
                    attachmentLive(GL_DEPTH_STENCIL_ATTACHMENT)) {
                    hasDepth = true;
                }
                if (attachmentLive(GL_STENCIL_ATTACHMENT) ||
                    attachmentLive(GL_DEPTH_STENCIL_ATTACHMENT)) {
                    hasStencil = true;
                }
            }
            if (isDepthReadback && !hasDepth) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            if (isStencilReadback && !hasStencil) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            if (isDepthStencilReadback && !(hasDepth && hasStencil)) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
        }
        // Format+type compatibility (Table 18.2). Rejects packed types
        // with incompatible base formats, and float types with integer
        // formats. Was previously silent → CTS flagged "invalid format
        // used but glReadPixels succeeded" on many combos.
        if (isColorReadback && !isFormatTypeCompatible_extern(format, type)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL 4.6 §18.3.2: *_INTEGER output formats require the color
        // buffer's internal format to be integer too. Otherwise
        // GL_INVALID_OPERATION. Resolve the bound read-FBO attachment's
        // internal format and check its integer-ness.
        const bool formatIsInteger = (format == GL_RED_INTEGER
            || format == GL_GREEN_INTEGER || format == GL_BLUE_INTEGER
            || format == GL_RG_INTEGER || format == GL_RGB_INTEGER
            || format == GL_RGBA_INTEGER
            || format == GL_BGR_INTEGER || format == GL_BGRA_INTEGER);
        if (isColorReadback) {
            const GLuint fbName = impl_->state->boundReadFramebuffer();
            const GLFramebufferObject* fb = impl_->objects->framebuffers().get(fbName);
            bool fboIsInteger = false;
            if (fb != nullptr) {
                const GLFramebufferAttachment* att = impl_->framebufferAttachment(*fb, fb->readBuffer);
                GLenum internalFormat = 0;
                if (att != nullptr) {
                    if (att->kind == GLFramebufferAttachment::Kind::Renderbuffer) {
                        if (auto* rb = impl_->objects->renderbuffers().get(att->object)) {
                            internalFormat = rb->internalFormat;
                        }
                    } else if (att->kind == GLFramebufferAttachment::Kind::Texture) {
                        if (auto* tex = impl_->objects->textures().get(att->object)) {
                            internalFormat = tex->desc.internalFormat;
                        }
                    }
                }
                switch (internalFormat) {
                    case GL_R8I: case GL_R8UI: case GL_R16I: case GL_R16UI:
                    case GL_R32I: case GL_R32UI:
                    case GL_RG8I: case GL_RG8UI: case GL_RG16I: case GL_RG16UI:
                    case GL_RG32I: case GL_RG32UI:
                    case GL_RGB8I: case GL_RGB8UI: case GL_RGB16I: case GL_RGB16UI:
                    case GL_RGB32I: case GL_RGB32UI:
                    case GL_RGBA8I: case GL_RGBA8UI: case GL_RGBA16I: case GL_RGBA16UI:
                    case GL_RGBA32I: case GL_RGBA32UI:
                    case GL_RGB10_A2UI:
                        fboIsInteger = true;
                        break;
                    default: break;
                }
            }
            // GL 4.6 §18.3.2: format and the FBO's attachment must agree
            // on integer-ness. Integer format needs integer FBO; non-
            // integer format needs non-integer FBO.
            if (formatIsInteger != fboIsInteger) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
        }
        // Flush the GPU before FBO readback — the render encoder may still
        // be open from a prior draw, and the texture data won't be CPU-
        // visible until the command buffer is committed and completed.
        if (impl_->frameGraph != nullptr) {
            impl_->frameGraph->flushForReadback();
        }
        if (isDepthStencilReadback) {
            const std::size_t pixelCount =
                static_cast<std::size_t>(width) *
                static_cast<std::size_t>(height);
            std::vector<GLfloat> depthStage(pixelCount);
            std::vector<std::uint8_t> stencilStage(pixelCount);
            if (!impl_->readFramebufferPixels(GL_DEPTH_COMPONENT, x, y,
                                              width, height,
                                              depthStage.data()) ||
                !impl_->readFramebufferPixels(GL_STENCIL_INDEX, x, y,
                                              width, height,
                                              stencilStage.data())) {
                pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                return false;
            }

            auto clamp01 = [](float v) {
                return v < 0.0f ? 0.0f : (v > 1.0f ? 1.0f : v);
            };
            const std::size_t dstPixelBytes = bytesPerPixel(format, type);
            const auto& packStore = impl_->state->pixelStore();
            const bool packSwapBytes = (packStore.packSwapBytes == GL_TRUE);
            const std::size_t dstRowStridePixels = packStore.packRowLength > 0
                ? static_cast<std::size_t>(packStore.packRowLength)
                : static_cast<std::size_t>(width);
            const std::size_t dstRowBytes = alignByteCount(
                dstRowStridePixels * dstPixelBytes, packStore.packAlignment);
            auto* outBytes = static_cast<std::uint8_t*>(pixels)
                + static_cast<std::size_t>(packStore.packSkipRows) * dstRowBytes
                + static_cast<std::size_t>(packStore.packSkipPixels) * dstPixelBytes;
            if (type == GL_FLOAT_32_UNSIGNED_INT_24_8_REV) {
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const std::size_t i =
                            static_cast<std::size_t>(row) *
                            static_cast<std::size_t>(width) +
                            static_cast<std::size_t>(col);
                        std::uint8_t* dst = outBytes
                            + static_cast<std::size_t>(row) * dstRowBytes
                            + static_cast<std::size_t>(col) * dstPixelBytes;
                        const float d = depthStage[i];
                        const std::uint32_t stencilSlot =
                            static_cast<std::uint32_t>(stencilStage[i]);
                        std::memcpy(dst, &d, 4);
                        std::memcpy(dst + 4, &stencilSlot, 4);
                        if (packSwapBytes) {
                            Impl::swapPixelStoreBytes(dst, dstPixelBytes);
                        }
                    }
                }
            } else {
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const std::size_t i =
                            static_cast<std::size_t>(row) *
                            static_cast<std::size_t>(width) +
                            static_cast<std::size_t>(col);
                        std::uint8_t* dst = outBytes
                            + static_cast<std::size_t>(row) * dstRowBytes
                            + static_cast<std::size_t>(col) * dstPixelBytes;
                        const float d = clamp01(depthStage[i]);
                        const std::uint32_t depth24 =
                            Impl::packReadbackBits(static_cast<double>(d),
                                                   0x00FFFFFFu, false);
                        const std::uint32_t packed =
                            (depth24 << 8) | static_cast<std::uint32_t>(stencilStage[i]);
                        std::memcpy(dst, &packed, 4);
                        if (packSwapBytes) {
                            Impl::swapPixelStoreBytes(dst, dstPixelBytes);
                        }
                    }
                }
            }
            return true;
        }
        if (isDepthReadback || isStencilReadback) {
            // readFramebufferPixels writes 1 byte per stencil value or 4
            // bytes per depth float. When the caller requests a wider
            // GL type (e.g. GL_STENCIL_INDEX + GL_INT), expand in place:
            // read the narrow data into a staging buffer, then splat
            // into the destination.
            const std::size_t pixelCount =
                static_cast<std::size_t>(width) *
                static_cast<std::size_t>(height);
            const std::size_t dstPixelBytes =
                std::max<std::size_t>(bytesPerComponent(type), 1);
            const auto& packStore = impl_->state->pixelStore();
            const bool packSwapBytes = (packStore.packSwapBytes == GL_TRUE);
            const std::size_t dstRowStridePixels = packStore.packRowLength > 0
                ? static_cast<std::size_t>(packStore.packRowLength)
                : static_cast<std::size_t>(width);
            const std::size_t dstRowBytes = alignByteCount(
                dstRowStridePixels * dstPixelBytes, packStore.packAlignment);
            auto* outBytes = static_cast<std::uint8_t*>(pixels)
                + static_cast<std::size_t>(packStore.packSkipRows) * dstRowBytes
                + static_cast<std::size_t>(packStore.packSkipPixels) * dstPixelBytes;
            if (isStencilReadback) {
                std::vector<std::uint8_t> stage(pixelCount);
                if (!impl_->readFramebufferPixels(format, x, y, width, height,
                                                  stage.data())) {
                    pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                    return false;
                }
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const std::size_t i =
                            static_cast<std::size_t>(row) *
                            static_cast<std::size_t>(width) +
                            static_cast<std::size_t>(col);
                        std::uint8_t* slot = outBytes
                            + static_cast<std::size_t>(row) * dstRowBytes
                            + static_cast<std::size_t>(col) * dstPixelBytes;
                        // Little-endian write: low byte holds the stencil
                        // value, high bytes are zero. All scalar GL types
                        // at bpc >= 2 read the stencil as its LSB.
                        std::memset(slot, 0, dstPixelBytes);
                        slot[0] = stage[i];
                        if (packSwapBytes) {
                            Impl::swapPixelStoreBytes(slot, dstPixelBytes);
                        }
                    }
                }
                return true;
            }
            if (isDepthReadback) {
                // readDepthAttachmentPixels writes 4-byte GLfloat per pixel.
                // When the caller requests a narrower or wider integer type
                // (e.g. GL_UNSIGNED_SHORT for DEPTH_COMPONENT16 readback), we
                // would overflow / underwrite the caller buffer. Stage to
                // floats then convert per GL 4.6 §18.2.10.
                std::vector<GLfloat> stage(pixelCount);
                if (!impl_->readFramebufferPixels(format, x, y, width, height,
                                                  stage.data())) {
                    pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                    return false;
                }
                auto clamp01 = [](float v) {
                    return v < 0.0f ? 0.0f : (v > 1.0f ? 1.0f : v);
                };
                for (GLsizei row = 0; row < height; ++row) {
                    for (GLsizei col = 0; col < width; ++col) {
                        const std::size_t i =
                            static_cast<std::size_t>(row) *
                            static_cast<std::size_t>(width) +
                            static_cast<std::size_t>(col);
                        const float d = clamp01(stage[i]);
                        std::uint8_t* out = outBytes
                            + static_cast<std::size_t>(row) * dstRowBytes
                            + static_cast<std::size_t>(col) * dstPixelBytes;
                        switch (type) {
                            case GL_UNSIGNED_BYTE: {
                                const std::uint8_t v =
                                    static_cast<std::uint8_t>(d * 255.0f + 0.5f);
                                std::memcpy(out, &v, 1);
                                break;
                            }
                            case GL_BYTE: {
                                const std::int8_t v =
                                    static_cast<std::int8_t>(d * 127.0f + 0.5f);
                                std::memcpy(out, &v, 1);
                                break;
                            }
                            case GL_UNSIGNED_SHORT: {
                                const std::uint16_t v =
                                    static_cast<std::uint16_t>(d * 65535.0f + 0.5f);
                                std::memcpy(out, &v, 2);
                                break;
                            }
                            case GL_SHORT: {
                                const std::int16_t v =
                                    static_cast<std::int16_t>(d * 32767.0f + 0.5f);
                                std::memcpy(out, &v, 2);
                                break;
                            }
                            case GL_UNSIGNED_INT: {
                                const std::uint32_t v = static_cast<std::uint32_t>(
                                    static_cast<double>(d) * 4294967295.0 + 0.5);
                                std::memcpy(out, &v, 4);
                                break;
                            }
                            case GL_INT: {
                                const std::int32_t v = static_cast<std::int32_t>(
                                    static_cast<double>(d) * 2147483647.0 + 0.5);
                                std::memcpy(out, &v, 4);
                                break;
                            }
                            case GL_FLOAT: {
                                std::memcpy(out, &d, 4);
                                break;
                            }
                            case GL_HALF_FLOAT: {
                                // IEEE-754 binary16 encoding (round-to-nearest,
                                // ties-to-even via the rounding-bias trick).
                                std::uint32_t f;
                                std::memcpy(&f, &d, 4);
                                const std::uint32_t sign = (f >> 16) & 0x8000;
                                std::int32_t exp = static_cast<std::int32_t>((f >> 23) & 0xFF) - 127 + 15;
                                std::uint32_t mant = f & 0x7FFFFF;
                                std::uint16_t h;
                                if (exp <= 0) {
                                    h = static_cast<std::uint16_t>(sign);
                                } else if (exp >= 31) {
                                    h = static_cast<std::uint16_t>(sign | 0x7C00);
                                } else {
                                    h = static_cast<std::uint16_t>(
                                        sign | (static_cast<std::uint32_t>(exp) << 10) | (mant >> 13));
                                }
                                std::memcpy(out, &h, 2);
                                break;
                            }
                            default:
                                break;
                        }
                        if (packSwapBytes) {
                            Impl::swapPixelStoreBytes(out, dstPixelBytes);
                        }
                    }
                }
                return true;
            }
        }
        // Try native-format readback first (preserves full precision for
        // R32F, RGBA32F, integer formats, etc.).
        if (impl_->readFBOColorNative(x, y, width, height, format, type, pixels)) {
            return true;
        }
        // Color readback: read RGBA8 internally, then convert to requested format/type
        if (format == GL_RGBA && type == GL_UNSIGNED_BYTE) {
            const std::size_t directPixelCount =
                static_cast<std::size_t>(width) * static_cast<std::size_t>(height);
            std::vector<std::uint8_t> directRGBA8(directPixelCount * 4u);
            if (!impl_->readFramebufferPixels(format, x, y, width, height, directRGBA8.data())) {
                pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
                return false;
            }
            const auto& packStore = impl_->state->pixelStore();
            const std::size_t dstPixelBytes = 4u;
            const std::size_t dstRowStridePixels = packStore.packRowLength > 0
                ? static_cast<std::size_t>(packStore.packRowLength)
                : static_cast<std::size_t>(width);
            const std::size_t dstRowBytes = alignByteCount(
                dstRowStridePixels * dstPixelBytes, packStore.packAlignment);
            auto* dest = static_cast<std::uint8_t*>(pixels)
                + static_cast<std::size_t>(packStore.packSkipRows) * dstRowBytes
                + static_cast<std::size_t>(packStore.packSkipPixels) * dstPixelBytes;
            for (GLsizei row = 0; row < height; ++row) {
                const auto* srcRow = directRGBA8.data()
                    + static_cast<std::size_t>(row) * static_cast<std::size_t>(width) * dstPixelBytes;
                auto* dstRow = dest + static_cast<std::size_t>(row) * dstRowBytes;
                std::memcpy(dstRow, srcRow, static_cast<std::size_t>(width) * dstPixelBytes);
            }
            return true;
        }
        // For non-RGBA8 color readback, read as RGBA8 into temp buffer, then convert
        const std::size_t pixelCount = static_cast<std::size_t>(width) * static_cast<std::size_t>(height);
        std::vector<std::uint8_t> rgba8(pixelCount * 4);
        if (!impl_->readFramebufferPixels(GL_RGBA, x, y, width, height, rgba8.data())) {
            pushError(GL_INVALID_FRAMEBUFFER_OPERATION);
            return false;
        }
        // Convert RGBA8 to the requested format/type
        const std::size_t components = componentCountForFormat(format);
        const std::size_t bpc = bytesPerComponent(type);
        if (components == 0) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
        if (isPackedPixelType(type)) {
            const std::size_t packedBpp = bytesPerPixel(format, type);
            if (packedBpp == 0) {
                pushError(GL_INVALID_ENUM);
                return false;
            }
            const auto& packStore = impl_->state->pixelStore();
            const bool packSwapBytes = (packStore.packSwapBytes == GL_TRUE);
            const std::size_t dstRowStridePixels = packStore.packRowLength > 0
                ? static_cast<std::size_t>(packStore.packRowLength)
                : static_cast<std::size_t>(width);
            const std::size_t dstRowBytes = alignByteCount(
                dstRowStridePixels * packedBpp, packStore.packAlignment);
            auto* dest = static_cast<std::uint8_t*>(pixels)
                + static_cast<std::size_t>(packStore.packSkipRows) * dstRowBytes
                + static_cast<std::size_t>(packStore.packSkipPixels) * packedBpp;

            const bool formatIsBGR = (format == GL_BGR || format == GL_BGR_INTEGER);
            const bool formatIsBGRA = (format == GL_BGRA || format == GL_BGRA_INTEGER);
            const bool formatIsGreen = (format == GL_GREEN || format == GL_GREEN_INTEGER);
            const bool formatIsBlue = (format == GL_BLUE || format == GL_BLUE_INTEGER);
            const bool formatIsAlpha = (format == GL_ALPHA);
            auto getComponent = [&](const double* vals4, int glCompIndex) -> double {
                if (formatIsBGR) {
                    static const int map[3] = {2, 1, 0};
                    return glCompIndex < 3 ? vals4[map[glCompIndex]] : 1.0;
                }
                if (formatIsBGRA) {
                    static const int map[4] = {2, 1, 0, 3};
                    return glCompIndex < 4 ? vals4[map[glCompIndex]] : 1.0;
                }
                if (formatIsGreen) return glCompIndex == 0 ? vals4[1] : 0.0;
                if (formatIsBlue) return glCompIndex == 0 ? vals4[2] : 0.0;
                if (formatIsAlpha) return glCompIndex == 0 ? vals4[3] : 0.0;
                return vals4[glCompIndex];
            };
            auto packUN = [](double v, unsigned bits) -> std::uint32_t {
                if (v < 0.0) v = 0.0;
                if (v > 1.0) v = 1.0;
                const double maxVal = static_cast<double>((1u << bits) - 1u);
                return static_cast<std::uint32_t>(v * maxVal + 0.5);
            };

            for (GLsizei row = 0; row < height; ++row) {
                for (GLsizei col = 0; col < width; ++col) {
                    const std::size_t srcIndex =
                        (static_cast<std::size_t>(row) * static_cast<std::size_t>(width)
                         + static_cast<std::size_t>(col)) * 4u;
                    double vals[4] = {
                        static_cast<double>(rgba8[srcIndex + 0]) / 255.0,
                        static_cast<double>(rgba8[srcIndex + 1]) / 255.0,
                        static_cast<double>(rgba8[srcIndex + 2]) / 255.0,
                        static_cast<double>(rgba8[srcIndex + 3]) / 255.0
                    };
                    auto d = [&](int i) { return getComponent(vals, i); };
                    std::uint8_t* dst = dest
                        + static_cast<std::size_t>(row) * dstRowBytes
                        + static_cast<std::size_t>(col) * packedBpp;
                    switch (type) {
                        case GL_UNSIGNED_BYTE_3_3_2: {
                            const std::uint32_t r = packUN(d(0), 3);
                            const std::uint32_t g = packUN(d(1), 3);
                            const std::uint32_t b = packUN(d(2), 2);
                            dst[0] = static_cast<std::uint8_t>((r << 5) | (g << 2) | b);
                            break;
                        }
                        case GL_UNSIGNED_BYTE_2_3_3_REV: {
                            const std::uint32_t r = packUN(d(0), 3);
                            const std::uint32_t g = packUN(d(1), 3);
                            const std::uint32_t b = packUN(d(2), 2);
                            dst[0] = static_cast<std::uint8_t>((b << 6) | (g << 3) | r);
                            break;
                        }
                        case GL_UNSIGNED_SHORT_5_6_5: {
                            std::uint16_t v = static_cast<std::uint16_t>(
                                (packUN(d(0), 5) << 11) | (packUN(d(1), 6) << 5) | packUN(d(2), 5));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_SHORT_5_6_5_REV: {
                            std::uint16_t v = static_cast<std::uint16_t>(
                                (packUN(d(2), 5) << 11) | (packUN(d(1), 6) << 5) | packUN(d(0), 5));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_SHORT_4_4_4_4: {
                            std::uint16_t v = static_cast<std::uint16_t>(
                                (packUN(d(0), 4) << 12) | (packUN(d(1), 4) << 8)
                                | (packUN(d(2), 4) << 4) | packUN(d(3), 4));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_SHORT_4_4_4_4_REV: {
                            std::uint16_t v = static_cast<std::uint16_t>(
                                (packUN(d(3), 4) << 12) | (packUN(d(2), 4) << 8)
                                | (packUN(d(1), 4) << 4) | packUN(d(0), 4));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_SHORT_5_5_5_1: {
                            std::uint16_t v = static_cast<std::uint16_t>(
                                (packUN(d(0), 5) << 11) | (packUN(d(1), 5) << 6)
                                | (packUN(d(2), 5) << 1) | packUN(d(3), 1));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_SHORT_1_5_5_5_REV: {
                            std::uint16_t v = static_cast<std::uint16_t>(
                                (packUN(d(3), 1) << 15) | (packUN(d(2), 5) << 10)
                                | (packUN(d(1), 5) << 5) | packUN(d(0), 5));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_INT_8_8_8_8: {
                            std::uint32_t v = (packUN(d(0), 8) << 24) | (packUN(d(1), 8) << 16)
                                | (packUN(d(2), 8) << 8) | packUN(d(3), 8);
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_INT_8_8_8_8_REV: {
                            std::uint32_t v = (packUN(d(3), 8) << 24) | (packUN(d(2), 8) << 16)
                                | (packUN(d(1), 8) << 8) | packUN(d(0), 8);
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_INT_10_10_10_2: {
                            std::uint32_t v = (packUN(d(0), 10) << 22) | (packUN(d(1), 10) << 12)
                                | (packUN(d(2), 10) << 2) | packUN(d(3), 2);
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_INT_2_10_10_10_REV: {
                            std::uint32_t v = (packUN(d(3), 2) << 30) | (packUN(d(2), 10) << 20)
                                | (packUN(d(1), 10) << 10) | packUN(d(0), 10);
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_INT_10F_11F_11F_REV: {
                            std::uint32_t v = packUF_10F11F11F_REV(d(0), d(1), d(2));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_INT_5_9_9_9_REV: {
                            std::uint32_t v = packUF_5_9_9_9_REV(d(0), d(1), d(2));
                            std::memcpy(dst, &v, sizeof(v));
                            break;
                        }
                        default:
                            std::memset(dst, 0, packedBpp);
                            break;
                    }
                    if (packSwapBytes) {
                        Impl::swapPixelStoreBytes(dst, packedBpp);
                    }
                }
            }
            return true;
        }
        if (bpc == 0) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
        const auto& packStore = impl_->state->pixelStore();
        const bool packSwapBytes = (packStore.packSwapBytes == GL_TRUE);
        const std::size_t dstPixelBytes = components * bpc;
        const std::size_t dstRowStridePixels = packStore.packRowLength > 0
            ? static_cast<std::size_t>(packStore.packRowLength)
            : static_cast<std::size_t>(width);
        const std::size_t dstRowBytes = alignByteCount(
            dstRowStridePixels * dstPixelBytes, packStore.packAlignment);
        auto* dest = static_cast<std::uint8_t*>(pixels)
            + static_cast<std::size_t>(packStore.packSkipRows) * dstRowBytes
            + static_cast<std::size_t>(packStore.packSkipPixels) * dstPixelBytes;
        for (GLsizei row = 0; row < height; ++row) {
            for (GLsizei col = 0; col < width; ++col) {
                const std::size_t i =
                    static_cast<std::size_t>(row) * static_cast<std::size_t>(width)
                    + static_cast<std::size_t>(col);
                const std::uint8_t r = rgba8[i * 4 + 0];
                const std::uint8_t g = rgba8[i * 4 + 1];
                const std::uint8_t b = rgba8[i * 4 + 2];
                const std::uint8_t a = rgba8[i * 4 + 3];
                std::uint8_t src[4] = { r, g, b, a };
                if (format == GL_BGR || format == GL_BGR_INTEGER) {
                    src[0] = b; src[1] = g; src[2] = r;
                } else if (format == GL_BGRA || format == GL_BGRA_INTEGER) {
                    src[0] = b; src[1] = g; src[2] = r; src[3] = a;
                }
                std::uint8_t* dstPixelBase = dest
                    + static_cast<std::size_t>(row) * dstRowBytes
                    + static_cast<std::size_t>(col) * dstPixelBytes;
                for (std::size_t c = 0; c < components; ++c) {
                    const float normalized = static_cast<float>(src[c]) / 255.0f;
                    std::uint8_t* dstP = dstPixelBase + c * bpc;
                    switch (type) {
                        case GL_UNSIGNED_BYTE:
                            dstP[0] = src[c];
                            break;
                        case GL_BYTE: {
                            const std::int8_t v = static_cast<std::int8_t>(src[c] * 127 / 255);
                            std::memcpy(dstP, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_SHORT: {
                            const std::uint16_t v = static_cast<std::uint16_t>(src[c] * 257);
                            std::memcpy(dstP, &v, sizeof(v));
                            break;
                        }
                        case GL_SHORT: {
                            const std::int16_t v = static_cast<std::int16_t>(src[c] * 32767 / 255);
                            std::memcpy(dstP, &v, sizeof(v));
                            break;
                        }
                        case GL_UNSIGNED_INT: {
                            const std::uint32_t v = static_cast<std::uint32_t>(src[c]) * 16843009u;
                            std::memcpy(dstP, &v, sizeof(v));
                            break;
                        }
                        case GL_INT: {
                            const std::int32_t v =
                                static_cast<std::int32_t>(static_cast<double>(src[c]) * 2147483647.0 / 255.0);
                            std::memcpy(dstP, &v, sizeof(v));
                            break;
                        }
                        case GL_FLOAT:
                            std::memcpy(dstP, &normalized, sizeof(normalized));
                            break;
                        case GL_HALF_FLOAT: {
                            // Simple float-to-half conversion
                            std::uint32_t fbits;
                            std::memcpy(&fbits, &normalized, sizeof(fbits));
                            std::uint32_t sign = (fbits >> 16) & 0x8000;
                            std::int32_t exp = ((fbits >> 23) & 0xFF) - 127 + 15;
                            std::uint32_t mant = (fbits >> 13) & 0x3FF;
                            std::uint16_t half;
                            if (exp <= 0) half = static_cast<std::uint16_t>(sign);
                            else if (exp >= 31) half = static_cast<std::uint16_t>(sign | 0x7C00);
                            else half = static_cast<std::uint16_t>(sign | (exp << 10) | mant);
                            std::memcpy(dstP, &half, sizeof(half));
                            break;
                        }
                        default:
                            dstP[0] = src[c];
                            break;
                    }
                    if (packSwapBytes) {
                        Impl::swapPixelStoreBytes(dstP, bpc);
                    }
                }
            }
        }
        return true;
    }

    // Default framebuffer readback — widen format/type acceptance
    impl_->encodePendingWork();
    if (format == GL_RGBA && type == GL_UNSIGNED_BYTE) {
        if (impl_->frameGraph == nullptr || !impl_->frameGraph->copyRGBA8Pixels(x, y, width, height, pixels)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        return true;
    }
    // For non-RGBA8 default framebuffer reads, read RGBA8 and convert
    if (componentCountForFormat(format) == 0) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    const std::size_t pixelCount = static_cast<std::size_t>(width) * static_cast<std::size_t>(height);
    std::vector<std::uint8_t> rgba8(pixelCount * 4);
    if (impl_->frameGraph == nullptr || !impl_->frameGraph->copyRGBA8Pixels(x, y, width, height, rgba8.data())) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Simple RGBA8 → requested format conversion (same as FBO path above)
    const std::size_t components = componentCountForFormat(format);
    const std::size_t bpc = bytesPerComponent(type);
    if (components == 0 || bpc == 0) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    auto* dest = static_cast<std::uint8_t*>(pixels);
    for (std::size_t i = 0; i < pixelCount; ++i) {
        std::uint8_t src[4] = { rgba8[i*4], rgba8[i*4+1], rgba8[i*4+2], rgba8[i*4+3] };
        if (format == GL_BGR || format == GL_BGR_INTEGER) {
            std::swap(src[0], src[2]);
        } else if (format == GL_BGRA || format == GL_BGRA_INTEGER) {
            std::swap(src[0], src[2]);
        }
        for (std::size_t c = 0; c < components; ++c) {
            const float normalized = static_cast<float>(src[c]) / 255.0f;
            switch (type) {
                case GL_UNSIGNED_BYTE:
                    dest[i * components + c] = src[c];
                    break;
                case GL_FLOAT:
                    reinterpret_cast<float*>(dest)[i * components + c] = normalized;
                    break;
                case GL_UNSIGNED_SHORT:
                    reinterpret_cast<std::uint16_t*>(dest)[i * components + c] =
                        static_cast<std::uint16_t>(src[c] * 257);
                    break;
                case GL_UNSIGNED_INT:
                    reinterpret_cast<std::uint32_t*>(dest)[i * components + c] =
                        static_cast<std::uint32_t>(src[c]) * 16843009u;
                    break;
                default:
                    dest[i * components + c] = src[c];
                    break;
            }
        }
    }
    return true;
}

bool GLContext::queryBoolean(GLenum pname, GLboolean* data) {
    if (data == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname == GL_DEBUG_GROUP_STACK_DEPTH || pname == GL_DEBUG_NEXT_LOGGED_MESSAGE_LENGTH) {
        GLint integerValue = 0;
        if (!queryInteger(pname, &integerValue)) {
            return false;
        }
        *data = integerValue != 0 ? GL_TRUE : GL_FALSE;
        return true;
    }
    // Transform feedback state — gluStateReset queries these via getBooleanv;
    // returning GL_INVALID_ENUM here aborts the reset and bleeds state across
    // CTS tests (active/paused/binding all default to GL_FALSE/0 since we
    // don't yet support TF execution).
    // CKPT85: route through per-bound-object getters so the
    // glGetIntegerv result reflects the currently-bound TF object's
    // state (the test inspectXFBState semantic). Pre-CKPT85 these
    // read the global flag, which lagged behind glBindTransformFeedback.
    if (pname == GL_TRANSFORM_FEEDBACK_ACTIVE) {
        *data = isTransformFeedbackActive() ? GL_TRUE : GL_FALSE;
        return true;
    }
    if (pname == GL_TRANSFORM_FEEDBACK_PAUSED) {
        *data = isTransformFeedbackPaused() ? GL_TRUE : GL_FALSE;
        return true;
    }
    if (pname == GL_TRANSFORM_FEEDBACK_BINDING) {
        *data = impl_->boundTransformFeedbackId != 0 ? GL_TRUE : GL_FALSE;
        return true;
    }
    // GL 4.4 §10.3.5 ARB_tessellation_shader: implementation-defined
    // boolean indicating whether glPrimitiveRestartIndex applies to
    // GL_PATCHES. We don't support tess + primitive-restart mixing
    // yet — return GL_FALSE so CTS `primitive_restart` skips the
    // GL_PATCHES branch instead of raising INVALID_ENUM and aborting.
    if (pname == GL_PRIMITIVE_RESTART_FOR_PATCHES_SUPPORTED) {
        *data = GL_FALSE;
        return true;
    }
    if (impl_->state->queryBoolean(pname, data)) {
        return true;
    }
    GLint integerData[4] = {};
    if (impl_->capabilities != nullptr && impl_->capabilities->queryInteger(pname, integerData)) {
        data[0] = integerData[0] != 0 ? GL_TRUE : GL_FALSE;
        if (pname == GL_MAX_VIEWPORT_DIMS) {
            data[1] = integerData[1] != 0 ? GL_TRUE : GL_FALSE;
        }
        return true;
    }
    pushError(GL_INVALID_ENUM);
    return false;
}

bool GLContext::queryInteger(GLenum pname, GLint* data) {
    if (data == nullptr) {
        // Phase 8X Group 4d follow-up⁴ §6c — capture the pname so BAR can
        // name the steady-state firer instead of seeing a bare
        // <internal@GLContext.mm:LINE> entry. The internal call-site tag
        // is still synthesised (functionName left empty) so the file:line
        // breadcrumb survives.
        char pnameBuf[48];
        std::snprintf(pnameBuf, sizeof(pnameBuf),
            "queryInteger: pname=0x%04X data=nullptr",
            static_cast<unsigned>(pname));
        pushError(GL_INVALID_VALUE, "", pnameBuf);
        return false;
    }
    if (pname == GL_DEBUG_GROUP_STACK_DEPTH) {
        *data = static_cast<GLint>(impl_->debugGroupStack.size());
        return true;
    }
    if (pname == GL_DEBUG_NEXT_LOGGED_MESSAGE_LENGTH) {
        *data = impl_->debugMessages.empty()
            ? 0
            : static_cast<GLint>(impl_->debugMessages.front().message.size() + 1);
        return true;
    }
    if (pname == GL_READ_BUFFER) {
        const GLuint framebufferName = impl_->state->boundReadFramebuffer();
        const GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
        *data = static_cast<GLint>(framebufferName != 0 && framebuffer != nullptr ? framebuffer->readBuffer : impl_->state->readBuffer());
        return true;
    }
    if (pname == GL_DRAW_BUFFER || (pname >= GL_DRAW_BUFFER0 && pname <= GL_DRAW_BUFFER7)) {
        const GLuint index = pname == GL_DRAW_BUFFER ? 0u : static_cast<GLuint>(pname - GL_DRAW_BUFFER0);
        const GLuint framebufferName = impl_->state->boundDrawFramebuffer();
        const GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
        *data = static_cast<GLint>(framebufferName != 0 && framebuffer != nullptr ? framebuffer->drawBuffers[index] : impl_->state->drawBuffer(index));
        return true;
    }
    if (pname == GL_TRANSFORM_FEEDBACK_ACTIVE) {
        // CKPT85: per-bound-object query (see queryBool path above).
        *data = isTransformFeedbackActive() ? GL_TRUE : GL_FALSE;
        return true;
    }
    if (pname == GL_TRANSFORM_FEEDBACK_PAUSED) {
        *data = isTransformFeedbackPaused() ? GL_TRUE : GL_FALSE;
        return true;
    }
    if (pname == GL_TRANSFORM_FEEDBACK_BINDING) {
        *data = static_cast<GLint>(impl_->boundTransformFeedbackId);
        return true;
    }
    // GL 4.6 §22.3 — per-context MSAA sample state. `glGetIntegerv`
    // with these pnames queries the CURRENT read framebuffer's
    // sample configuration. Without MSAA infrastructure we advertise
    // zero samples on both default and user FBOs. CTS
    // `framebuffer_blit.scissor_blit` calls `getIntegerv(
    // GL_SAMPLE_BUFFERS)` to decide whether to verify cleared
    // colours (skipped if MSAA); our returning INVALID_ENUM aborted
    // the entire test before the scissor code ran.
    if (pname == GL_SAMPLE_BUFFERS) {
        *data = 0;
        return true;
    }
    if (pname == GL_SAMPLES) {
        *data = 0;
        return true;
    }
    // GL 4.6 §18.3: GL_IMPLEMENTATION_COLOR_READ_{TYPE,FORMAT} report
    // the implementation-preferred format/type pair for glReadPixels
    // on the current read framebuffer. Resolve from the bound read
    // FBO's color attachment; default framebuffer yields RGBA +
    // UNSIGNED_BYTE. Several CTS paths (notably the DSA
    // textures_buffer_* fuzz tests) drain these queries as part of
    // glReadPixels error-reporting, and a bare GL_INVALID_ENUM here
    // poisons the test's subsequent `gl.getError()` check.
    if (pname == GL_IMPLEMENTATION_COLOR_READ_TYPE
        || pname == GL_IMPLEMENTATION_COLOR_READ_FORMAT) {
        GLenum fmt = GL_RGBA;
        GLenum type = GL_UNSIGNED_BYTE;
        const GLuint fbName = impl_->state->boundReadFramebuffer();
        if (fbName != 0) {
            if (const GLFramebufferObject* fb = impl_->objects->framebuffers().get(fbName)) {
                const GLFramebufferAttachment* att = impl_->framebufferAttachment(*fb, fb->readBuffer);
                GLenum ifmt = 0;
                if (att != nullptr) {
                    if (att->kind == GLFramebufferAttachment::Kind::Renderbuffer) {
                        if (auto* rb = impl_->objects->renderbuffers().get(att->object)) {
                            ifmt = rb->internalFormat;
                        }
                    } else if (att->kind == GLFramebufferAttachment::Kind::Texture) {
                        if (auto* tex = impl_->objects->textures().get(att->object)) {
                            ifmt = tex->desc.internalFormat;
                        }
                    }
                }
                // Map internal format → (preferred read format, type).
                // Follows GL 4.6 Table 18.2's "valid combinations"
                // diagonal: integer formats yield *_INTEGER / matching
                // integer type; snorm/unorm yield base + BYTE/UBYTE;
                // float yields base + FLOAT.
                switch (ifmt) {
                    case GL_R8I:      fmt = GL_RED_INTEGER;  type = GL_BYTE;          break;
                    case GL_R8UI:     fmt = GL_RED_INTEGER;  type = GL_UNSIGNED_BYTE; break;
                    case GL_R16I:     fmt = GL_RED_INTEGER;  type = GL_SHORT;         break;
                    case GL_R16UI:    fmt = GL_RED_INTEGER;  type = GL_UNSIGNED_SHORT;break;
                    case GL_R32I:     fmt = GL_RED_INTEGER;  type = GL_INT;           break;
                    case GL_R32UI:    fmt = GL_RED_INTEGER;  type = GL_UNSIGNED_INT;  break;
                    case GL_RG8I:     fmt = GL_RG_INTEGER;   type = GL_BYTE;          break;
                    case GL_RG8UI:    fmt = GL_RG_INTEGER;   type = GL_UNSIGNED_BYTE; break;
                    case GL_RG16I:    fmt = GL_RG_INTEGER;   type = GL_SHORT;         break;
                    case GL_RG16UI:   fmt = GL_RG_INTEGER;   type = GL_UNSIGNED_SHORT;break;
                    case GL_RG32I:    fmt = GL_RG_INTEGER;   type = GL_INT;           break;
                    case GL_RG32UI:   fmt = GL_RG_INTEGER;   type = GL_UNSIGNED_INT;  break;
                    case GL_RGB8I:    fmt = GL_RGB_INTEGER;  type = GL_BYTE;          break;
                    case GL_RGB8UI:   fmt = GL_RGB_INTEGER;  type = GL_UNSIGNED_BYTE; break;
                    case GL_RGB16I:   fmt = GL_RGB_INTEGER;  type = GL_SHORT;         break;
                    case GL_RGB16UI:  fmt = GL_RGB_INTEGER;  type = GL_UNSIGNED_SHORT;break;
                    case GL_RGB32I:   fmt = GL_RGB_INTEGER;  type = GL_INT;           break;
                    case GL_RGB32UI:  fmt = GL_RGB_INTEGER;  type = GL_UNSIGNED_INT;  break;
                    case GL_RGBA8I:   fmt = GL_RGBA_INTEGER; type = GL_BYTE;          break;
                    case GL_RGBA8UI:  fmt = GL_RGBA_INTEGER; type = GL_UNSIGNED_BYTE; break;
                    case GL_RGBA16I:  fmt = GL_RGBA_INTEGER; type = GL_SHORT;         break;
                    case GL_RGBA16UI: fmt = GL_RGBA_INTEGER; type = GL_UNSIGNED_SHORT;break;
                    case GL_RGBA32I:  fmt = GL_RGBA_INTEGER; type = GL_INT;           break;
                    case GL_RGBA32UI: fmt = GL_RGBA_INTEGER; type = GL_UNSIGNED_INT;  break;
                    case GL_RGB10_A2UI: fmt = GL_RGBA_INTEGER; type = GL_UNSIGNED_INT_2_10_10_10_REV; break;
                    case GL_R16F: case GL_RG16F: case GL_RGB16F: case GL_RGBA16F:
                    case GL_R32F: case GL_RG32F: case GL_RGB32F: case GL_RGBA32F:
                        fmt = GL_RGBA; type = GL_FLOAT; break;
                    case GL_R8: case GL_R16: case GL_RG8: case GL_RG16:
                    case GL_RGB8: case GL_RGB16: case GL_RGBA8: case GL_RGBA16:
                    case GL_SRGB8: case GL_SRGB8_ALPHA8:
                    default:
                        fmt = GL_RGBA; type = GL_UNSIGNED_BYTE; break;
                }
            }
        }
        *data = static_cast<GLint>(pname == GL_IMPLEMENTATION_COLOR_READ_TYPE ? type : fmt);
        return true;
    }
    if (impl_->state->queryInteger(pname, data)) {
        return true;
    }
    if (impl_->capabilities == nullptr || !impl_->capabilities->queryInteger(pname, data)) {
        // Phase 8X Group 4d follow-up⁴ §6c — name the unknown pname in
        // the diagnostic ring so BAR can see WHICH enum its widget code
        // is querying. The previous bare `pushError(GL_INVALID_ENUM)`
        // produced a steady stream of untagged errorLog entries that
        // BAR-side tooling could only count, not act on.
        char pnameBuf[48];
        std::snprintf(pnameBuf, sizeof(pnameBuf),
            "queryInteger: pname=0x%04X unknown",
            static_cast<unsigned>(pname));
        pushError(GL_INVALID_ENUM, "", pnameBuf);
        return false;
    }
    return true;
}

bool GLContext::queryInteger64(GLenum pname, GLint64* data) {
    if (data == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname == GL_DEBUG_GROUP_STACK_DEPTH || pname == GL_DEBUG_NEXT_LOGGED_MESSAGE_LENGTH) {
        GLint integerValue = 0;
        if (!queryInteger(pname, &integerValue)) {
            return false;
        }
        *data = static_cast<GLint64>(integerValue);
        return true;
    }
    if (impl_->state->queryInteger64(pname, data)) {
        return true;
    }
    if (impl_->capabilities == nullptr || !impl_->capabilities->queryInteger64(pname, data)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    return true;
}

bool GLContext::queryIntegerIndexed(GLenum pname, GLuint index, GLint* data) {
    // Indexed integer query (glGetIntegeri_v). Phase 8X Landing C 3a. Used
    // primarily for compute work-group count/size tuples where the GL spec
    // defines separate per-dimension values addressed by index 0/1/2.
    //
    // We still honour the bound-buffer index queries that live on the state
    // tracker (indexed buffer bindings, array-drawbuffer state). Capability
    // caps flow through GLCapabilities::queryIntegerIndexed which knows
    // about the x/y/z compute tuples and also serves scalar caps at
    // index 0 for GL-spec leniency.
    if (data == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.3+ separated-format per-binding-point VAO state (§10.3.8).
    // `GL_VERTEX_BINDING_{STRIDE,DIVISOR,BUFFER,OFFSET}` are indexed by
    // binding point. CTS `vertex_attrib_binding.basic-state*` queries
    // all four; the 64-bit OFFSET form goes through queryInteger64Indexed.
    switch (pname) {
        case GL_VERTEX_BINDING_STRIDE:
        case GL_VERTEX_BINDING_DIVISOR:
        case GL_VERTEX_BINDING_BUFFER:
        case GL_VERTEX_BINDING_OFFSET: {
            GLVertexArrayObject* vao = impl_->currentVertexArray();
            if (vao == nullptr || index >= vao->bindingPoints.size()) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            const auto& bp = vao->bindingPoints[index];
            if (pname == GL_VERTEX_BINDING_STRIDE)      *data = static_cast<GLint>(bp.stride);
            else if (pname == GL_VERTEX_BINDING_DIVISOR) *data = static_cast<GLint>(bp.divisor);
            else if (pname == GL_VERTEX_BINDING_BUFFER)  *data = static_cast<GLint>(bp.buffer);
            else                                         *data = static_cast<GLint>(bp.offset);
            return true;
        }
        // GL 4.2+ image load/store per-image-unit state (§8.26.1).
        // `index` is an image unit index in [0, MAX_IMAGE_UNITS).
        // CTS `multi_bind.functional_bind_image_textures` exercises
        // all six per-unit pnames after glBindImageTextures() calls.
        case GL_IMAGE_BINDING_NAME:
        case GL_IMAGE_BINDING_LEVEL:
        case GL_IMAGE_BINDING_LAYERED:
        case GL_IMAGE_BINDING_LAYER:
        case GL_IMAGE_BINDING_ACCESS:
        case GL_IMAGE_BINDING_FORMAT: {
            if (index >= impl_->imageBindings.size()) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            const auto& ib = impl_->imageBindings[index];
            if (pname == GL_IMAGE_BINDING_NAME)         *data = static_cast<GLint>(ib.texture);
            else if (pname == GL_IMAGE_BINDING_LEVEL)   *data = ib.level;
            else if (pname == GL_IMAGE_BINDING_LAYERED) *data = ib.layered ? GL_TRUE : GL_FALSE;
            else if (pname == GL_IMAGE_BINDING_LAYER)   *data = ib.layer;
            else if (pname == GL_IMAGE_BINDING_ACCESS)  *data = static_cast<GLint>(ib.access);
            else                                        *data = static_cast<GLint>(ib.format);
            return true;
        }
        // GL 4.4+ per-texture-unit bindings for all sampler targets.
        // Indexed by texture-unit number in [0, MAX_COMBINED_TEXTURE_IMAGE_UNITS).
        // The non-indexed form of these queries returns the binding on
        // the currently active texture unit; the indexed form lets the
        // caller pick any unit without switching glActiveTexture first.
        // Used by CTS `multi_bind.functional_bind_textures`.
        case GL_TEXTURE_BINDING_1D:
        case GL_TEXTURE_BINDING_2D:
        case GL_TEXTURE_BINDING_3D:
        case GL_TEXTURE_BINDING_1D_ARRAY:
        case GL_TEXTURE_BINDING_2D_ARRAY:
        case GL_TEXTURE_BINDING_RECTANGLE:
        case GL_TEXTURE_BINDING_CUBE_MAP:
        case GL_TEXTURE_BINDING_CUBE_MAP_ARRAY:
        case GL_TEXTURE_BINDING_BUFFER:
        case GL_TEXTURE_BINDING_2D_MULTISAMPLE:
        case GL_TEXTURE_BINDING_2D_MULTISAMPLE_ARRAY:
        case GL_SAMPLER_BINDING: {
            // Map binding pname to the texture target being queried.
            GLenum target = 0;
            switch (pname) {
                case GL_TEXTURE_BINDING_1D:                    target = GL_TEXTURE_1D; break;
                case GL_TEXTURE_BINDING_2D:                    target = GL_TEXTURE_2D; break;
                case GL_TEXTURE_BINDING_3D:                    target = GL_TEXTURE_3D; break;
                case GL_TEXTURE_BINDING_1D_ARRAY:              target = GL_TEXTURE_1D_ARRAY; break;
                case GL_TEXTURE_BINDING_2D_ARRAY:              target = GL_TEXTURE_2D_ARRAY; break;
                case GL_TEXTURE_BINDING_RECTANGLE:             target = GL_TEXTURE_RECTANGLE; break;
                case GL_TEXTURE_BINDING_CUBE_MAP:              target = GL_TEXTURE_CUBE_MAP; break;
                case GL_TEXTURE_BINDING_CUBE_MAP_ARRAY:        target = GL_TEXTURE_CUBE_MAP_ARRAY; break;
                case GL_TEXTURE_BINDING_BUFFER:                target = GL_TEXTURE_BUFFER; break;
                case GL_TEXTURE_BINDING_2D_MULTISAMPLE:        target = GL_TEXTURE_2D_MULTISAMPLE; break;
                case GL_TEXTURE_BINDING_2D_MULTISAMPLE_ARRAY:  target = GL_TEXTURE_2D_MULTISAMPLE_ARRAY; break;
                case GL_SAMPLER_BINDING:                       target = GL_SAMPLER_BINDING; break;
            }
            if (pname == GL_SAMPLER_BINDING) {
                *data = static_cast<GLint>(impl_->state->boundSampler(index));
            } else {
                *data = static_cast<GLint>(impl_->state->boundTextureOnUnit(index, target));
            }
            return true;
        }
        // GL 4.1+ per-viewport arrays. CTS
        // `viewport_array.scissor_api` / `viewport_api` query
        // GL_VIEWPORT and GL_SCISSOR_BOX via glGetIntegeri_v — both
        // are spec-legal. Route through the state tracker's float
        // indexed query + cast. DEPTH_RANGE is float-only per
        // Table 22.5, so stays handled by queryFloatIndexed.
        case GL_VIEWPORT:
        case GL_SCISSOR_BOX: {
            // GL 4.1 §13.6.1: index >= MAX_VIEWPORTS raises
            // INVALID_VALUE (not INVALID_ENUM).
            if (static_cast<GLint64>(index) >= queryMaxViewports(impl_->capabilities.get())) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            GLfloat fdata[4] = {};
            if (!impl_->state->queryFloatIndexed(pname, index, fdata)) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            data[0] = static_cast<GLint>(fdata[0]);
            data[1] = static_cast<GLint>(fdata[1]);
            data[2] = static_cast<GLint>(fdata[2]);
            data[3] = static_cast<GLint>(fdata[3]);
            return true;
        }
    }
    if (impl_->capabilities != nullptr
        && impl_->capabilities->queryIntegerIndexed(pname, index, data)) {
        return true;
    }
    // Indexed buffer-binding state: BINDING / START / SIZE for all four
    // indexed targets. Lives on the state tracker, not the cap layer.
    IndexedBufferPname ibp;
    if (lookupIndexedBufferPname(pname, ibp)) {
        const auto b = impl_->state->indexedBufferBinding(ibp.target, index);
        switch (ibp.field) {
            case IndexedBufferPname::Buffer: *data = static_cast<GLint>(b.buffer); break;
            case IndexedBufferPname::Offset: *data = static_cast<GLint>(b.offset); break;
            case IndexedBufferPname::Size:   *data = static_cast<GLint>(b.size);   break;
        }
        return true;
    }
    // Fall back to the scalar state tracker path for state that has a
    // per-index representation (buffer binding stacks) — match the existing
    // queryInteger behaviour when no indexed handler exists.
    if (index == 0 && impl_->state->queryInteger(pname, data)) {
        return true;
    }
    pushError(GL_INVALID_ENUM);
    return false;
}

bool GLContext::queryInteger64Indexed(GLenum pname, GLuint index, GLint64* data) {
    if (data == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.3+ separated-format — same per-binding queries as the
    // 32-bit form. `GL_VERTEX_BINDING_OFFSET` in particular is
    // documented as the 64-bit target since offsets can exceed
    // 2^31. Served directly from the VAO binding-point state.
    switch (pname) {
        case GL_VERTEX_BINDING_STRIDE:
        case GL_VERTEX_BINDING_DIVISOR:
        case GL_VERTEX_BINDING_BUFFER:
        case GL_VERTEX_BINDING_OFFSET: {
            GLVertexArrayObject* vao = impl_->currentVertexArray();
            if (vao == nullptr || index >= vao->bindingPoints.size()) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            const auto& bp = vao->bindingPoints[index];
            if (pname == GL_VERTEX_BINDING_STRIDE)      *data = static_cast<GLint64>(bp.stride);
            else if (pname == GL_VERTEX_BINDING_DIVISOR) *data = static_cast<GLint64>(bp.divisor);
            else if (pname == GL_VERTEX_BINDING_BUFFER)  *data = static_cast<GLint64>(bp.buffer);
            else                                         *data = static_cast<GLint64>(bp.offset);
            return true;
        }
    }
    if (impl_->capabilities != nullptr
        && impl_->capabilities->queryInteger64Indexed(pname, index, data)) {
        return true;
    }
    IndexedBufferPname ibp;
    if (lookupIndexedBufferPname(pname, ibp)) {
        const auto b = impl_->state->indexedBufferBinding(ibp.target, index);
        switch (ibp.field) {
            case IndexedBufferPname::Buffer: *data = static_cast<GLint64>(b.buffer); break;
            case IndexedBufferPname::Offset: *data = static_cast<GLint64>(b.offset); break;
            case IndexedBufferPname::Size:   *data = static_cast<GLint64>(b.size);   break;
        }
        return true;
    }
    if (index == 0 && impl_->state->queryInteger64(pname, data)) {
        return true;
    }
    pushError(GL_INVALID_ENUM);
    return false;
}

bool GLContext::queryFloat(GLenum pname, GLfloat* data) {
    if (data == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname == GL_DEBUG_GROUP_STACK_DEPTH || pname == GL_DEBUG_NEXT_LOGGED_MESSAGE_LENGTH) {
        GLint integerValue = 0;
        if (!queryInteger(pname, &integerValue)) {
            return false;
        }
        *data = static_cast<GLfloat>(integerValue);
        return true;
    }
    if (impl_->state->queryFloat(pname, data)) {
        return true;
    }
    if (impl_->capabilities != nullptr && impl_->capabilities->queryFloat(pname, data)) {
        return true;
    }
    // GL spec: glGetFloatv must return any integer state cast to float
    // (e.g. GL_SHADER_STORAGE_BUFFER_BINDING). Fall through to the
    // integer path and cast. Note: we do NOT call queryInteger() here
    // because that pushes GL_INVALID_ENUM on miss — instead probe
    // state + caps directly.
    GLint intData[4] = {};
    if (impl_->state->queryInteger(pname, intData)) {
        *data = static_cast<GLfloat>(intData[0]);
        return true;
    }
    if (impl_->capabilities != nullptr && impl_->capabilities->queryInteger(pname, intData)) {
        *data = static_cast<GLfloat>(intData[0]);
        if (pname == GL_MAX_VIEWPORT_DIMS) {
            data[1] = static_cast<GLfloat>(intData[1]);
        }
        return true;
    }
    pushError(GL_INVALID_ENUM);
    return false;
}

bool GLContext::queryDouble(GLenum pname, GLdouble* data) {
    if (data == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname == GL_DEBUG_GROUP_STACK_DEPTH || pname == GL_DEBUG_NEXT_LOGGED_MESSAGE_LENGTH) {
        GLint integerValue = 0;
        if (!queryInteger(pname, &integerValue)) {
            return false;
        }
        *data = static_cast<GLdouble>(integerValue);
        return true;
    }
    if (impl_->state->queryDouble(pname, data)) {
        return true;
    }
    GLfloat floatData[4] = {};
    if (impl_->capabilities != nullptr && impl_->capabilities->queryFloat(pname, floatData)) {
        data[0] = static_cast<GLdouble>(floatData[0]);
        if (pname == GL_MAX_VIEWPORT_DIMS) {
            data[1] = static_cast<GLdouble>(floatData[1]);
        }
        return true;
    }
    // GL spec: glGetDoublev must return any integer state cast to
    // double (e.g. GL_SHADER_STORAGE_BUFFER_BINDING). Probe the
    // state-tracker integer path first, then caps. Don't call
    // queryInteger() directly because it pushes GL_INVALID_ENUM
    // on miss, which would fire before our own pushError below.
    GLint intData[4] = {};
    if (impl_->state->queryInteger(pname, intData)) {
        data[0] = static_cast<GLdouble>(intData[0]);
        return true;
    }
    if (impl_->capabilities != nullptr && impl_->capabilities->queryInteger(pname, intData)) {
        data[0] = static_cast<GLdouble>(intData[0]);
        if (pname == GL_MAX_VIEWPORT_DIMS) {
            data[1] = static_cast<GLdouble>(intData[1]);
        }
        return true;
    }
    pushError(GL_INVALID_ENUM);
    return false;
}

void GLContext::setEnabled(GLenum cap, bool enabled) {
    if (enabled) {
        impl_->state->enable(cap);
    } else {
        impl_->state->disable(cap);
    }
}

bool GLContext::isEnabled(GLenum cap) const {
    return impl_->state->isEnabled(cap);
}

void GLContext::setDebugCallback(GLDEBUGPROC callback, const void* userParam) {
    impl_->debugCallback = callback;
    impl_->debugUserParam = userParam;
}

void GLContext::emitDebugMessage(
    GLenum source,
    GLenum type,
    GLuint id,
    GLenum severity,
    std::string_view message
) {
    impl_->enqueueDebugMessage({source, type, id, severity, std::string(message)});
}

void GLContext::setDebugMessageControl(
    GLenum source,
    GLenum type,
    GLenum severity,
    GLsizei count,
    const GLuint* ids,
    GLboolean enabled
) {
    DebugControlRule rule;
    rule.source = source;
    rule.type = type;
    rule.severity = severity;
    rule.enabled = enabled == GL_TRUE;
    rule.hasIds = count > 0;
    for (GLsizei index = 0; index < count; ++index) {
        rule.ids.insert(ids[index]);
    }
    impl_->debugControlRules.push_back(std::move(rule));
}

void GLContext::insertDebugMessage(
    GLenum source,
    GLenum type,
    GLuint id,
    GLenum severity,
    std::string_view message
) {
    emitDebugMessage(source, type, id, severity, message);
}

GLuint GLContext::getDebugMessageLog(
    GLuint count,
    GLsizei bufSize,
    GLenum* sources,
    GLenum* types,
    GLuint* ids,
    GLenum* severities,
    GLsizei* lengths,
    GLchar* messageLog
) {
    if (bufSize < 0) {
        pushError(GL_INVALID_VALUE);
        return 0;
    }

    GLuint delivered = 0;
    GLsizei usedBytes = 0;
    while (delivered < count && !impl_->debugMessages.empty()) {
        const DebugMessageRecord& message = impl_->debugMessages.front();
        const GLsizei requiredBytes = static_cast<GLsizei>(message.message.size() + 1);
        if (messageLog != nullptr && usedBytes + requiredBytes > bufSize) {
            break;
        }

        if (sources != nullptr) {
            sources[delivered] = message.source;
        }
        if (types != nullptr) {
            types[delivered] = message.type;
        }
        if (ids != nullptr) {
            ids[delivered] = message.id;
        }
        if (severities != nullptr) {
            severities[delivered] = message.severity;
        }
        if (lengths != nullptr) {
            lengths[delivered] = requiredBytes;
        }
        if (messageLog != nullptr) {
            std::memcpy(messageLog + usedBytes, message.message.c_str(), static_cast<std::size_t>(requiredBytes));
            usedBytes += requiredBytes;
        }

        impl_->debugMessages.pop_front();
        ++delivered;
    }
    return delivered;
}

void GLContext::pushDebugGroup(GLenum source, GLuint id, std::string_view message) {
    if (impl_->debugGroupStack.size() >= kMaxDebugGroupDepth) {
        pushError(GL_STACK_OVERFLOW);
        return;
    }
    DebugMessageRecord record{source, GL_DEBUG_TYPE_PUSH_GROUP, id, GL_DEBUG_SEVERITY_NOTIFICATION, std::string(message)};
    impl_->debugGroupStack.push_back(record);
    impl_->enqueueDebugMessage(record);
}

bool GLContext::popDebugGroup() {
    if (impl_->debugGroupStack.empty()) {
        pushError(GL_STACK_UNDERFLOW);
        return false;
    }
    DebugMessageRecord record = impl_->debugGroupStack.back();
    impl_->debugGroupStack.pop_back();
    record.type = GL_DEBUG_TYPE_POP_GROUP;
    impl_->enqueueDebugMessage(std::move(record));
    return true;
}

void GLContext::setObjectLabel(GLenum identifier, GLuint name, std::string_view label) {
    const std::uint64_t key = objectLabelKey(identifier, name);
    if (label.empty()) {
        impl_->objectLabels.erase(key);
        return;
    }
    impl_->objectLabels[key] = trimDebugMessage(label);
}

void GLContext::getObjectLabel(GLenum identifier, GLuint name, GLsizei bufSize, GLsizei* length, GLchar* label) {
    if (bufSize < 0) {
        pushError(GL_INVALID_VALUE);
        return;
    }
    const auto found = impl_->objectLabels.find(objectLabelKey(identifier, name));
    const std::string_view value = found == impl_->objectLabels.end() ? std::string_view{} : std::string_view(found->second);
    copyLabelString(value, bufSize, length, label);
}

void GLContext::setObjectPtrLabel(const void* ptr, std::string_view label) {
    if (label.empty()) {
        impl_->pointerLabels.erase(ptr);
        return;
    }
    impl_->pointerLabels[ptr] = trimDebugMessage(label);
}

void GLContext::getObjectPtrLabel(const void* ptr, GLsizei bufSize, GLsizei* length, GLchar* label) {
    if (bufSize < 0) {
        pushError(GL_INVALID_VALUE);
        return;
    }
    const auto found = impl_->pointerLabels.find(ptr);
    const std::string_view value = found == impl_->pointerLabels.end() ? std::string_view{} : std::string_view(found->second);
    copyLabelString(value, bufSize, length, label);
}

bool GLContext::getPointer(GLenum pname, void** params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    switch (pname) {
        case GL_DEBUG_CALLBACK_FUNCTION:
            *params = reinterpret_cast<void*>(impl_->debugCallback);
            return true;
        case GL_DEBUG_CALLBACK_USER_PARAM:
            *params = const_cast<void*>(impl_->debugUserParam);
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::genBuffers(GLsizei count, GLuint* buffers) {
    if (count < 0 || (count > 0 && buffers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        buffers[index] = impl_->objects->buffers().reserveName();
    }
    return true;
}

bool GLContext::deleteBuffers(GLsizei count, const GLuint* buffers) {
    if (count < 0 || (count > 0 && buffers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = buffers[index];
        if (name == 0) {
            continue;
        }
        if (GLBufferObject* object = impl_->objects->buffers().get(name); object != nullptr) {
            impl_->releaseBufferStorage(*object);
        }
        if (impl_->objects->buffers().erase(name)) {
            impl_->state->deleteBufferBindings(name);
            impl_->deleteBufferReferencesFromVertexArrays(name);
            impl_->objects->deferDelete("buffer " + std::to_string(name));
        }
    }
    return true;
}

bool GLContext::isBuffer(GLuint buffer) const {
    const GLBufferObject* object = impl_->objects->buffers().get(buffer);
    return object != nullptr && object->instantiated;
}

bool GLContext::bindBuffer(GLenum target, GLuint buffer) {
    if (buffer == 0) {
        impl_->state->bindBuffer(target, 0);
        if (target == GL_ELEMENT_ARRAY_BUFFER) {
            if (GLVertexArrayObject* vertexArray = impl_->currentVertexArray(); vertexArray != nullptr) {
                vertexArray->elementArrayBuffer = 0;
            }
        }
        return true;
    }
    GLBufferObject* object = impl_->objects->buffers().get(buffer);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    object->instantiated = true;
    impl_->state->bindBuffer(target, buffer);
    if (target == GL_ELEMENT_ARRAY_BUFFER) {
        if (GLVertexArrayObject* vertexArray = impl_->currentVertexArray(); vertexArray != nullptr) {
            vertexArray->elementArrayBuffer = buffer;
        }
    }
    return true;
}

bool GLContext::bindBufferRange(GLenum target, GLuint index, GLuint buffer, GLintptr offset, GLsizeiptr size) {
    // GL 4.6 §6.1.1 validation order — the offset/size/alignment
    // checks apply regardless of whether `buffer == 0`. CTS
    // `shader_storage_buffer_object.negative-api-bind` plants
    // `glBindBufferRange(GL_SHADER_STORAGE_BUFFER, 0, 0, 31, 0)`
    // with offset=31 against OFFSET_ALIGNMENT=32 and expects
    // INVALID_VALUE; previously we short-circuited the buffer==0
    // case to "success" and skipped the alignment check.
    if (offset < 0 || size < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    {
        GLint64 alignment = 1;
        auto queryAlignment = [this](GLenum pname) -> GLint64 {
            GLint64 v = 1;
            if (impl_->capabilities != nullptr) {
                impl_->capabilities->queryInteger64(pname, &v);
            }
            return v;
        };
        switch (target) {
            case GL_UNIFORM_BUFFER:
                alignment = queryAlignment(GL_UNIFORM_BUFFER_OFFSET_ALIGNMENT);
                break;
            case GL_SHADER_STORAGE_BUFFER:
                alignment = queryAlignment(GL_SHADER_STORAGE_BUFFER_OFFSET_ALIGNMENT);
                break;
            case GL_ATOMIC_COUNTER_BUFFER:
            case GL_TRANSFORM_FEEDBACK_BUFFER:
                alignment = 4;
                break;
            default:
                break;
        }
        if (alignment > 1 && (offset % alignment) != 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        // XFB: size must also be a multiple of 4.
        if (target == GL_TRANSFORM_FEEDBACK_BUFFER && (size % 4) != 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    if (buffer == 0) {
        impl_->state->bindIndexedBuffer(target, index, 0, 0, 0);
        // Spec: bind* with buffer == 0 also resets the generic target binding.
        impl_->state->bindBuffer(target, 0);
        return true;
    }
    GLBufferObject* object = impl_->objects->buffers().get(buffer);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    object->instantiated = true;
    impl_->state->bindIndexedBuffer(target, index, buffer, offset, size);
    // Spec (4.6 §6.1.1): BindBufferRange additionally binds buffer to the generic
    // buffer binding point specified by target. Without this the generic UBO/SSBO
    // bindings would silently desync from the indexed table after a per-index bind.
    impl_->state->bindBuffer(target, buffer);
    return true;
}

bool GLContext::bindBufferBase(GLenum target, GLuint index, GLuint buffer) {
    if (buffer != 0) {
        GLBufferObject* object = impl_->objects->buffers().get(buffer);
        if (object == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        object->instantiated = true;
    }
    // GL 4.6 §6.1.1: bindBufferBase = bindBufferRange with offset=0
    // and size = sizeof(buffer). The buffer size is resolved at
    // draw time, not bind time — otherwise a subsequent bufferData
    // resize leaves the binding reporting a stale length. Sentinel
    // value 0 means "whole buffer, live size"; consumers
    // (writeTessTFAndUpdateCounters, primFits, …) already fall back
    // to the live `GLBufferObject::shadowBytes.size()` when
    // rangeSize==0.
    impl_->state->bindIndexedBuffer(target, index, buffer, 0, 0);
    // Spec (4.6 §6.1.1): BindBufferBase also binds buffer to the generic target.
    impl_->state->bindBuffer(target, buffer);
    return true;
}

bool GLContext::bufferData(GLenum target, GLsizeiptr size, const void* data, GLenum usage) {
    // GL 4.4 §6.2: usage must be one of the 9 accepted tokens.
    switch (usage) {
        case GL_STREAM_DRAW: case GL_STREAM_READ: case GL_STREAM_COPY:
        case GL_STATIC_DRAW: case GL_STATIC_READ: case GL_STATIC_COPY:
        case GL_DYNAMIC_DRAW: case GL_DYNAMIC_READ: case GL_DYNAMIC_COPY:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    if (size < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.2: BUFFER_IMMUTABLE_STORAGE=TRUE rejects bufferData
    // regardless of storage flags. CTS
    // `direct_state_access.buffers_errors` asserts INVALID_OPERATION.
    if (object->immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (object->mapped) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!impl_->replaceBufferStorage(*object, size, data, usage)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

bool GLContext::bufferSubData(GLenum target, GLintptr offset, GLsizeiptr size, const void* data) {
    if (offset < 0 || size < 0 || (size > 0 && data == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.3: bufferSubData is legal on a mapped buffer as
    // long as the write region doesn't overlap the mapped region
    // — unless the mapping uses MAP_PERSISTENT_BIT, in which case
    // any overlap is also legal. CTS `buffer_storage.
    // map_persistent_buffer_sub_data` exercises both cases: the
    // persistent-map section expects all sub-writes to succeed,
    // the non-persistent-map section expects INVALID_OPERATION
    // only for writes that cross the mapped extent.
    if (object->mapped && (object->mapAccessFlags & GL_MAP_PERSISTENT_BIT) == 0) {
        const GLintptr mapStart = object->mapOffset;
        const GLintptr mapEnd = mapStart + static_cast<GLintptr>(object->mapLength);
        const GLintptr opStart = offset;
        const GLintptr opEnd = offset + static_cast<GLintptr>(size);
        const bool overlaps = (opStart < mapEnd) && (opEnd > mapStart);
        if (overlaps) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    // GL 4.4 §6.2 / §6.3: immutable-storage buffers require the
    // GL_DYNAMIC_STORAGE_BIT flag to accept {Named,}BufferSubData writes.
    // CTS `buffer_storage.errors` asserts INVALID_OPERATION when a
    // glBufferStorage-created buffer without DYNAMIC_STORAGE_BIT takes
    // a subsequent glBufferSubData or glNamedBufferSubData.
    if (object->immutable && !(object->storageFlags & GL_DYNAMIC_STORAGE_BIT)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (offset > object->size || size > object->size - offset) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (size > 0) {
        std::memcpy(
            object->shadowBytes.data() + static_cast<std::size_t>(offset),
            data,
            static_cast<std::size_t>(size)
        );
        impl_->syncMetalFromShadow(*object, offset, size);
        // ADV-10: invalidate cached index expansion on data change.
        ++object->indexExpansionGeneration;
    }
    return true;
}

bool GLContext::copyBufferSubData(
    GLenum readTarget,
    GLenum writeTarget,
    GLintptr readOffset,
    GLintptr writeOffset,
    GLsizeiptr size
) {
    if (readOffset < 0 || writeOffset < 0 || size < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint readName = impl_->state->boundBuffer(readTarget);
    const GLuint writeName = impl_->state->boundBuffer(writeTarget);
    GLBufferObject* readObject = impl_->objects->buffers().get(readName);
    GLBufferObject* writeObject = impl_->objects->buffers().get(writeName);
    if (readName == 0 || writeName == 0 || readObject == nullptr || writeObject == nullptr
        || !readObject->instantiated || !writeObject->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §6.3: mapped source or destination raises INVALID_OPERATION
    // *unless* the buffer was mapped with GL_MAP_PERSISTENT_BIT. Persistent
    // mapping keeps the memory addressable across draws, so copyBufferSubData
    // is allowed to proceed.
    const auto isNonPersistentMapped = [](const GLBufferObject* obj) {
        return obj->mapped && (obj->mapAccessFlags & GL_MAP_PERSISTENT_BIT) == 0;
    };
    if (isNonPersistentMapped(readObject) || isNonPersistentMapped(writeObject)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (readOffset > readObject->size || size > readObject->size - readOffset
        || writeOffset > writeObject->size || size > writeObject->size - writeOffset) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (readName == writeName) {
        const GLintptr readEnd = readOffset + size;
        const GLintptr writeEnd = writeOffset + size;
        if (size > 0 && readOffset < writeEnd && writeOffset < readEnd) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    if (size > 0) {
        const std::uint8_t* readBytes = impl_->readableBufferContents(*readObject);
        if (readBytes == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        std::memcpy(
            writeObject->shadowBytes.data() + static_cast<std::size_t>(writeOffset),
            readBytes + static_cast<std::size_t>(readOffset),
            static_cast<std::size_t>(size)
        );
        impl_->syncMetalFromShadow(*writeObject, writeOffset, size);
    }
    return true;
}

// --------------------------------------------------------------------------
// Vacuous-pass detector — instrumentation for distinguishing GENUINE_PASS
// from VACUOUS_PASS in CTS tessellation_shader.* runs. Activated by
// APPGL_DETECTOR_TF=1. Logs a structured stderr line on every
// GL_TRANSFORM_FEEDBACK_BUFFER read-back (mapBufferRange / getBufferSubData)
// with a count of non-zero bytes in the data the caller will see.
//
// Pair with deqp-builtin `tcuTestSessionExecutor.cpp` "Test case '<name>'.."
// stdout marker — combine streams via 2>&1 and feed `tools/detector_classify.py`
// to bucket each test into GENUINE_PASS / VACUOUS_PASS / GENUINE_FAIL.
namespace {
struct VacuousPassDetector {
    bool enabled = false;
    VacuousPassDetector() {
        const char* v = std::getenv("APPGL_DETECTOR_TF");
        enabled = (v != nullptr && v[0] != '\0' && v[0] != '0');
    }
};
inline bool detectorEnabled() {
    static const VacuousPassDetector det;
    return det.enabled;
}
inline void logTFReadback(GLenum target,
                          GLuint buffer,
                          GLintptr offset,
                          GLsizeiptr length,
                          const std::uint8_t* bytes) {
    if (!detectorEnabled()) return;
    static std::atomic<unsigned> seqCounter{0};
    const unsigned seq = seqCounter.fetch_add(1, std::memory_order_relaxed);
    std::size_t nonzero = 0;
    std::ptrdiff_t firstNonzero = -1;
    if (bytes != nullptr) {
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(length); ++i) {
            if (bytes[i] != 0) {
                ++nonzero;
                if (firstNonzero < 0) firstNonzero = i;
            }
        }
    }
    std::fprintf(stderr,
        "APPGL_DETECTOR tf_read seq=%u target=0x%X buf=%u offset=%lld length=%lld "
        "nonzero_bytes=%zu first_nonzero_offset=%td\n",
        seq,
        static_cast<unsigned int>(target),
        static_cast<unsigned int>(buffer),
        static_cast<long long>(offset),
        static_cast<long long>(length),
        nonzero,
        firstNonzero);
    // T4C byte-decode helper: when APPGL_DETECTOR_TF_DUMP=<dir> is set,
    // write the raw bytes of each TF read to <dir>/tf_<seq>.bin so a
    // post-processor can decode against the expected varying layout
    // (CTS test source) and pinpoint per-vertex / per-stride / per-type
    // mismatches.  Cached path lookup so per-read cost is one strcmp.
    if (bytes != nullptr && length > 0) {
        const char* dumpDir = std::getenv("APPGL_DETECTOR_TF_DUMP");
        if (dumpDir != nullptr && dumpDir[0] != '\0') {
            char path[512];
            std::snprintf(path, sizeof(path), "%s/tf_%05u.bin", dumpDir, seq);
            if (FILE* f = std::fopen(path, "wb")) {
                std::fwrite(bytes, 1, static_cast<std::size_t>(length), f);
                std::fclose(f);
            }
        }
    }
}
}  // namespace

bool GLContext::getBufferSubData(GLenum target, GLintptr offset, GLsizeiptr size, void* data) {
    if (offset < 0 || size < 0 || (size > 0 && data == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.3: glGet{Named,}BufferSubData is legal on a mapped
    // buffer only when the mapping uses GL_MAP_PERSISTENT_BIT. CTS
    // `direct_state_access.buffers_errors` covers both directions.
    if (object->mapped && (object->mapAccessFlags & GL_MAP_PERSISTENT_BIT) == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (offset > object->size || size > object->size - offset) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (size > 0) {
        const std::uint8_t* bytes = impl_->readableBufferContents(*object);
        if (bytes == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        std::memcpy(data, bytes + static_cast<std::size_t>(offset), static_cast<std::size_t>(size));
        if (target == GL_TRANSFORM_FEEDBACK_BUFFER) {
            logTFReadback(target, name, offset, size,
                          static_cast<const std::uint8_t*>(data));
        }
    }
    return true;
}

void* GLContext::mapBuffer(GLenum target, GLenum access) {
    GLbitfield flags = 0;
    if (!legacyMapAccessToFlags(access, &flags)) {
        pushError(GL_INVALID_ENUM);
        return nullptr;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated || object->mapped || object->size <= 0) {
        pushError(GL_INVALID_OPERATION);
        return nullptr;
    }
    void* pointer = mapBufferRange(target, 0, object->size, flags);
    if (pointer != nullptr) {
        object->mapAccess = access;
    }
    return pointer;
}

void* GLContext::mapBufferRange(GLenum target, GLintptr offset, GLsizeiptr length, GLbitfield access) {
    if (offset < 0 || length < 0) {
        pushError(GL_INVALID_VALUE);
        return nullptr;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated || object->mapped) {
        pushError(GL_INVALID_OPERATION);
        return nullptr;
    }
    // GL 4.4 §6.3.1 spec-order:
    //   INVALID_OPERATION is generated if any bit among MAP_READ_BIT,
    //   MAP_WRITE_BIT, MAP_PERSISTENT_BIT, MAP_COHERENT_BIT is set in
    //   access but not in the buffer's storage flags (for immutable
    //   buffers). For non-immutable buffers, the legacy rule is that
    //   MAP_READ_BIT / MAP_WRITE_BIT must both be settable (they are by
    //   default). PERSISTENT / COHERENT only exist on immutable buffers
    //   with the matching storage-flag set.
    //
    // Check storage-flag compatibility BEFORE the syntactic-access
    // check below — CTS `buffer_storage.errors` expects
    // INVALID_OPERATION on `access=PERSISTENT, storage=DYNAMIC_STORAGE`
    // (storage mismatch) to win over INVALID_VALUE from "access has
    // no READ/WRITE".
    if (object->immutable) {
        const GLbitfield storage = object->storageFlags;
        if ((access & GL_MAP_READ_BIT) && !(storage & GL_MAP_READ_BIT)) {
            pushError(GL_INVALID_OPERATION);
            return nullptr;
        }
        if ((access & GL_MAP_WRITE_BIT) && !(storage & GL_MAP_WRITE_BIT)) {
            pushError(GL_INVALID_OPERATION);
            return nullptr;
        }
        if ((access & GL_MAP_PERSISTENT_BIT) &&
            !(storage & GL_MAP_PERSISTENT_BIT)) {
            pushError(GL_INVALID_OPERATION);
            return nullptr;
        }
        if ((access & GL_MAP_COHERENT_BIT) &&
            !(storage & GL_MAP_COHERENT_BIT)) {
            pushError(GL_INVALID_OPERATION);
            return nullptr;
        }
    }
    if (!isSupportedMapBufferRangeAccess(access)) {
        pushError(GL_INVALID_OPERATION);
        return nullptr;
    }
    if (length == 0 || object->size <= 0) {
        pushError(GL_INVALID_OPERATION);
        return nullptr;
    }
    if (offset > object->size || length > object->size - offset) {
        pushError(GL_INVALID_VALUE);
        return nullptr;
    }

    std::uint8_t* contents = impl_->mutableBufferContents(*object);
    if (contents == nullptr) {
        pushError(GL_OUT_OF_MEMORY);
        return nullptr;
    }

    object->mapped = true;
    object->mapAccess = legacyMapAccessFromFlags(access);
    object->mapAccessFlags = access;
    object->mapOffset = offset;
    object->mapLength = length;
    object->mapPointer = contents + static_cast<std::size_t>(offset);
    if (target == GL_TRANSFORM_FEEDBACK_BUFFER && (access & GL_MAP_READ_BIT)) {
        logTFReadback(target, name, offset, length,
                      static_cast<const std::uint8_t*>(object->mapPointer));
    }
    return object->mapPointer;
}

GLboolean GLContext::unmapBuffer(GLenum target) {
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated || !object->mapped) {
        pushError(GL_INVALID_OPERATION);
        return GL_FALSE;
    }
    if (mapAccessWrites(object->mapAccessFlags)) {
        impl_->syncShadowFromMetal(*object, object->mapOffset, object->mapLength);
    }
    resetBufferMapping(*object);
    return GL_TRUE;
}

bool GLContext::flushMappedBufferRange(GLenum target, GLintptr offset, GLsizeiptr length) {
    if (offset < 0 || length < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated || !object->mapped
        || (object->mapAccessFlags & GL_MAP_FLUSH_EXPLICIT_BIT) == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (offset > object->mapLength || length > object->mapLength - offset) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (mapAccessWrites(object->mapAccessFlags)) {
        impl_->syncShadowFromMetal(*object, object->mapOffset + offset, length);
    }
    return true;
}

bool GLContext::getBufferParameterInteger(GLenum target, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLint64 value = 0;
    if (!getBufferParameterInteger64(target, pname, &value)) {
        return false;
    }
    *params = static_cast<GLint>(value);
    return true;
}

bool GLContext::getBufferParameterInteger64(GLenum target, GLenum pname, GLint64* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    switch (pname) {
        case GL_BUFFER_SIZE:
            *params = object->size;
            return true;
        case GL_BUFFER_USAGE:
            *params = object->usage;
            return true;
        case GL_BUFFER_ACCESS:
            *params = object->mapAccess;
            return true;
        case GL_BUFFER_ACCESS_FLAGS:
            *params = object->mapped ? object->mapAccessFlags : 0;
            return true;
        case GL_BUFFER_MAPPED:
            *params = object->mapped ? GL_TRUE : GL_FALSE;
            return true;
        case GL_BUFFER_MAP_OFFSET:
            *params = object->mapped ? object->mapOffset : 0;
            return true;
        case GL_BUFFER_MAP_LENGTH:
            *params = object->mapped ? object->mapLength : 0;
            return true;
        case GL_BUFFER_IMMUTABLE_STORAGE:
            *params = object->immutable ? GL_TRUE : GL_FALSE;
            return true;
        case GL_BUFFER_STORAGE_FLAGS:
            *params = static_cast<GLint64>(object->storageFlags);
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getBufferPointer(GLenum target, GLenum pname, void** params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname != GL_BUFFER_MAP_POINTER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    const GLuint name = impl_->state->boundBuffer(target);
    GLBufferObject* object = impl_->objects->buffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    *params = object->mapped ? object->mapPointer : nullptr;
    return true;
}

bool GLContext::genVertexArrays(GLsizei count, GLuint* arrays) {
    if (count < 0 || (count > 0 && arrays == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = impl_->objects->vertexArrays().reserveName();
        arrays[index] = name;
        if (GLVertexArrayObject* object = impl_->objects->vertexArrays().get(name); object != nullptr) {
            impl_->objects->initializeVertexArray(*object);
        }
    }
    return true;
}

bool GLContext::deleteVertexArrays(GLsizei count, const GLuint* arrays) {
    if (count < 0 || (count > 0 && arrays == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = arrays[index];
        if (name == 0) {
            continue;
        }
        if (GLVertexArrayObject* object = impl_->objects->vertexArrays().get(name); object != nullptr) {
            impl_->releaseVertexDescriptor(*object);
        }
        if (impl_->objects->vertexArrays().erase(name)) {
            if (impl_->state->boundVertexArray() == name) {
                impl_->state->bindVertexArray(0);
                impl_->state->bindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0);
            }
            impl_->objects->deferDelete("vertex array " + std::to_string(name));
        }
    }
    return true;
}

bool GLContext::isVertexArray(GLuint array) const {
    const GLVertexArrayObject* object = impl_->objects->vertexArrays().get(array);
    return object != nullptr && object->instantiated;
}

bool GLContext::bindVertexArray(GLuint array) {
    if (array == 0) {
        impl_->state->bindVertexArray(0);
        impl_->state->bindBuffer(GL_ELEMENT_ARRAY_BUFFER, 0);
        return true;
    }
    GLVertexArrayObject* object = impl_->vertexArray(array);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    object->instantiated = true;
    impl_->state->bindVertexArray(array);
    impl_->state->bindBuffer(GL_ELEMENT_ARRAY_BUFFER, object->elementArrayBuffer);
    return true;
}

bool GLContext::enableVertexAttribArray(GLuint index, bool enabled) {
    // Use the default VAO fallback when no user VAO is bound (matches
    // real-driver behaviour; CTS `get_uniform_tests.gl_get_uniform`
    // and other gl3c* tests call enableVertexAttribArray without
    // first binding a VAO and expect the call to succeed).
    GLVertexArrayObject* vertexArray = impl_->currentVertexArrayOrDefault();
    if (vertexArray == nullptr || index >= vertexArray->attributes.size()) {
        pushError(index >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    vertexArray->attributes[index].enabled = enabled;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexAttribPointer(
    GLuint index,
    GLint size,
    GLenum type,
    GLboolean normalized,
    GLsizei stride,
    const void* pointer
) {
    if (size < 1 || size > 4 || stride < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §10.3 technically requires a user-bound VAO for
    // glVertexAttribPointer, but real drivers (NVIDIA, AMD, Mesa)
    // fall back to an implicit "default VAO" — same accommodation
    // already used by glEnableVertexAttribArray (iter 109). Routing
    // through currentVertexArrayOrDefault avoids spurious errors
    // when apps call the attribute-setup sequence without an explicit
    // glBindVertexArray. CTS `draw_indirect.negative-noVAO-*` rely
    // on the setup NOT leaking an INVALID_OPERATION that their
    // subcase-end glGetError check would then trip on.
    GLVertexArrayObject* vertexArray = impl_->currentVertexArrayOrDefault();
    if (vertexArray == nullptr || index >= vertexArray->attributes.size()) {
        pushError(index >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    const GLuint buffer = impl_->state->boundBuffer(GL_ARRAY_BUFFER);
    if (buffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    auto& attribute = vertexArray->attributes[index];
    attribute.size = size;
    attribute.type = type;
    attribute.normalized = normalized;
    attribute.stride = stride;
    attribute.pointer = reinterpret_cast<std::uintptr_t>(pointer);
    attribute.buffer = buffer;
    attribute.integer = false;
    attribute.longData = false;
    // GL 4.6 §10.3.8: glVertexAttribPointer is defined as
    // glVertexAttribFormat(index, size, type, normalized, 0) +
    // glVertexAttribBinding(index, index) +
    // glBindVertexBuffer(index, buffer, (GLintptr)pointer, stride).
    // Mirror the binding-point state so subsequent queries of
    // GL_VERTEX_BINDING_{BUFFER,OFFSET,STRIDE} and
    // GL_VERTEX_ATTRIB_ARRAY_BUFFER_BINDING route correctly through
    // the binding path.
    attribute.bindingIndex = index;
    attribute.relativeOffset = 0;
    if (index < vertexArray->bindingPoints.size()) {
        auto& bp = vertexArray->bindingPoints[index];
        bp.buffer = buffer;
        bp.offset = static_cast<GLintptr>(attribute.pointer);
        // GL 4.6 §10.3.8: glVertexAttribPointer(stride=0) means "tight
        // pack using size*sizeof(type)" — not the VAO default (16).
        // The binding-point stride propagates to
        // `MetalVertexDescriptor.layouts[slot].stride`; writing 16
        // for a small (e.g. size=2 FLOAT = 8-byte) attribute makes
        // Metal fetch every other vertex and zero-fills intermediate
        // ones.
        GLsizei effStride = stride;
        if (effStride <= 0) {
            auto byteSize = [](GLenum t) -> GLsizei {
                switch (t) {
                    case GL_BYTE: case GL_UNSIGNED_BYTE: return 1;
                    case GL_SHORT: case GL_UNSIGNED_SHORT: case GL_HALF_FLOAT: return 2;
                    case GL_FIXED:
                    case GL_FLOAT: case GL_INT: case GL_UNSIGNED_INT: return 4;
                    case GL_DOUBLE: return 8;
                    default: return 4;
                }
            };
            effStride = static_cast<GLsizei>(size) * byteSize(type);
            if (effStride <= 0) effStride = 16;
        }
        bp.stride = effStride;
    }
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexAttribIPointer(GLuint index, GLint size, GLenum type, GLsizei stride, const void* pointer) {
    if (size < 1 || size > 4 || stride < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Same rationale as vertexAttribPointer — route through the
    // default-VAO fallback so apps that set up attributes without
    // an explicit glBindVertexArray don't queue an INVALID_OPERATION.
    GLVertexArrayObject* vertexArray = impl_->currentVertexArrayOrDefault();
    if (vertexArray == nullptr || index >= vertexArray->attributes.size()) {
        pushError(index >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    const GLuint buffer = impl_->state->boundBuffer(GL_ARRAY_BUFFER);
    if (buffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    auto& attribute = vertexArray->attributes[index];
    attribute.size = size;
    attribute.type = type;
    attribute.normalized = GL_FALSE;
    attribute.stride = stride;
    attribute.pointer = reinterpret_cast<std::uintptr_t>(pointer);
    attribute.buffer = buffer;
    attribute.integer = true;
    attribute.longData = false;
    // Same spec-equivalence as glVertexAttribPointer (GL 4.6 §10.3.8).
    attribute.bindingIndex = index;
    attribute.relativeOffset = 0;
    if (index < vertexArray->bindingPoints.size()) {
        auto& bp = vertexArray->bindingPoints[index];
        bp.buffer = buffer;
        bp.offset = static_cast<GLintptr>(attribute.pointer);
        // CKPT100 fix: glVertexAttribIPointer(stride=0) means "tight pack
        // using size*sizeof(type)" per GL 4.6 §10.3.8 — not the
        // VAO-default 16. The hardcoded 16 fallback caused
        // KHR-GL46.direct_state_access.vertex_arrays_element_buffer to
        // fail: 1-component GL_INT attribute with stride=0 should fetch
        // every 4 bytes; with stride forced to 16, slot N reads
        // out-of-range past the 12-byte buffer for N≥1, returning
        // zeros. Mirror the byte-size compute already in
        // glVertexAttribPointer for symmetry.
        GLsizei effStride = stride;
        if (effStride <= 0) {
            auto byteSize = [](GLenum t) -> GLsizei {
                switch (t) {
                    case GL_BYTE: case GL_UNSIGNED_BYTE: return 1;
                    case GL_SHORT: case GL_UNSIGNED_SHORT: return 2;
                    case GL_INT: case GL_UNSIGNED_INT: return 4;
                    default: return 4;
                }
            };
            effStride = static_cast<GLsizei>(size) * byteSize(type);
            if (effStride <= 0) effStride = 16;
        }
        bp.stride = effStride;
    }
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexAttribDivisor(GLuint index, GLuint divisor) {
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr || index >= vertexArray->attributes.size()) {
        pushError(index >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §10.3.8: `glVertexAttribDivisor(N, D)` is defined as
    // `glVertexBindingDivisor(N, D)` + `glVertexAttribBinding(N, N)`.
    // The divisor lives on the binding point, not the attribute —
    // CTS `vertex_attrib_binding.basic-state4` asserts that a
    // subsequent `glVertexBindingDivisor(N, new)` overwrites the
    // same state.
    if (index < vertexArray->bindingPoints.size()) {
        vertexArray->bindingPoints[index].divisor = divisor;
    }
    vertexArray->attributes[index].bindingIndex = index;
    // Mirror into the legacy field too so the
    // `markVertexDescriptorDirty` + draw-time fetch still sees the
    // value when the attribute was set via glVertexAttribPointer
    // rather than separated-format calls.
    vertexArray->attributes[index].divisor = divisor;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

// --- GL 4.3: Separated vertex format (ARB_vertex_attrib_binding) ---

bool GLContext::bindVertexBuffer(GLuint bindingindex, GLuint buffer, GLintptr offset, GLsizei stride) {
    if (stride < 0 || offset < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.4 §10.3.1: stride must be ≤ GL_MAX_VERTEX_ATTRIB_STRIDE.
    {
        GLint64 maxStride = 2048;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger64(
                GL_MAX_VERTEX_ATTRIB_STRIDE, &maxStride);
        }
        if (stride > static_cast<GLsizei>(maxStride)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §10.3.1: bindingindex must be < GL_MAX_VERTEX_ATTRIB_BINDINGS.
    // Our VAO's bindingPoints vector is sized to MAX_VERTEX_ATTRIBS (32)
    // which is larger than MAX_VERTEX_ATTRIB_BINDINGS (16), so the
    // size-based check let binding indices in [16, 32) through. CTS
    // `vertex_attrib_binding.negative-bindVertexBuffer` plants
    // bindingindex=17 and asserts INVALID_VALUE.
    GLint64 maxBindings = 16;
    if (impl_->capabilities != nullptr) {
        impl_->capabilities->queryInteger64(
            GL_MAX_VERTEX_ATTRIB_BINDINGS, &maxBindings);
    }
    if (bindingindex >= static_cast<GLuint>(maxBindings)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (bindingindex >= vertexArray->bindingPoints.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Buffer 0 is valid (unbinds the binding point).
    if (buffer != 0 && !impl_->objects->buffers().contains(buffer)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    auto& bp = vertexArray->bindingPoints[bindingindex];
    bp.buffer = buffer;
    bp.offset = offset;
    bp.stride = stride;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexAttribFormat(GLuint attribindex, GLint size, GLenum type, GLboolean normalized, GLuint relativeoffset) {
    // GL 4.4 §10.3.8: type must be one of the accepted tokens.
    // Reject unknown types with INVALID_ENUM. CTS
    // `direct_state_access.vertex_arrays_attribute_format_errors`
    // goes through the DSA entry path which skips the legacy wrapper's
    // type check, so this needs to live at the context level.
    switch (type) {
        case GL_BYTE: case GL_UNSIGNED_BYTE:
        case GL_SHORT: case GL_UNSIGNED_SHORT:
        case GL_INT: case GL_UNSIGNED_INT:
        case GL_HALF_FLOAT: case GL_FLOAT: case GL_DOUBLE:
        case GL_FIXED:
        case GL_INT_2_10_10_10_REV:
        case GL_UNSIGNED_INT_2_10_10_10_REV:
        case GL_UNSIGNED_INT_10F_11F_11F_REV:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    // GL 4.4 §10.3.8: size ∈ {1, 2, 3, 4, GL_BGRA}.
    const bool sizeIsBgra = (size == static_cast<GLint>(GL_BGRA));
    if (!sizeIsBgra && (size < 1 || size > 4)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // When size is GL_BGRA: type must be GL_UNSIGNED_BYTE,
    // GL_INT_2_10_10_10_REV, or GL_UNSIGNED_INT_2_10_10_10_REV, and
    // normalized must be GL_TRUE. Violations raise INVALID_OPERATION.
    // CTS `vertex_attrib_binding.negative-vertexAttribFormat` plants
    // `size=GL_BGRA, type=GL_FLOAT, normalized=GL_TRUE` and asserts
    // INVALID_OPERATION.
    if (sizeIsBgra) {
        const bool typeOk = (type == GL_UNSIGNED_BYTE ||
                             type == GL_INT_2_10_10_10_REV ||
                             type == GL_UNSIGNED_INT_2_10_10_10_REV);
        if (!typeOk || normalized != GL_TRUE) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    // GL 4.4 §10.3.8: packed types (2_10_10_10_REV variants) require
    // size = 4 or GL_BGRA. Otherwise INVALID_OPERATION. CTS
    // `vertex_attrib_binding.negative-vertexAttribFormat` exercises
    // `size=3, type=GL_INT_2_10_10_10_REV, normalized=GL_FALSE` and
    // asserts INVALID_OPERATION.
    if ((type == GL_INT_2_10_10_10_REV ||
         type == GL_UNSIGNED_INT_2_10_10_10_REV) &&
        !sizeIsBgra && size != 4) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §10.3.8: UNSIGNED_INT_10F_11F_11F_REV is a 3-channel
    // packed float — size must be 3. CTS
    // `vertex_arrays_attribute_format_errors` plants a size != 3 with
    // this type and expects INVALID_OPERATION.
    if (type == GL_UNSIGNED_INT_10F_11F_11F_REV && size != 3) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §10.3.8: relativeoffset must be <=
    // GL_MAX_VERTEX_ATTRIB_RELATIVE_OFFSET. Out-of-range is
    // INVALID_VALUE. CTS plants relativeoffset=2057 with the cap
    // at 2047.
    {
        GLint64 maxRelOffset = 2047;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger64(
                GL_MAX_VERTEX_ATTRIB_RELATIVE_OFFSET, &maxRelOffset);
        }
        if (relativeoffset > static_cast<GLuint>(maxRelOffset)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr || attribindex >= vertexArray->attributes.size()) {
        pushError(attribindex >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    auto& attribute = vertexArray->attributes[attribindex];
    attribute.size = size;
    attribute.type = type;
    attribute.normalized = normalized;
    attribute.relativeOffset = relativeoffset;
    attribute.integer = false;
    attribute.longData = false;
    attribute.useSeparatedFormat = true;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexAttribIFormat(GLuint attribindex, GLint size, GLenum type, GLuint relativeoffset) {
    // GL 4.4 §10.3.8: integer vertex attrib types — byte / short / int,
    // signed or unsigned. Everything else (including packed floats
    // like UNSIGNED_INT_10F_11F_11F_REV and UNSIGNED_INT_2_10_10_10_REV)
    // is rejected with INVALID_ENUM. CTS
    // `vertex_arrays_attribute_format_errors` plants a
    // UNSIGNED_INT_10F_11F_11F_REV type and asserts INVALID_ENUM.
    switch (type) {
        case GL_BYTE: case GL_UNSIGNED_BYTE:
        case GL_SHORT: case GL_UNSIGNED_SHORT:
        case GL_INT: case GL_UNSIGNED_INT:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    if (size < 1 || size > 4) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.4 §10.3.8: relativeoffset > MAX_VERTEX_ATTRIB_RELATIVE_OFFSET
    // is INVALID_VALUE.
    {
        GLint64 maxRelOffset = 2047;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger64(
                GL_MAX_VERTEX_ATTRIB_RELATIVE_OFFSET, &maxRelOffset);
        }
        if (relativeoffset > static_cast<GLuint>(maxRelOffset)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr || attribindex >= vertexArray->attributes.size()) {
        pushError(attribindex >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    auto& attribute = vertexArray->attributes[attribindex];
    attribute.size = size;
    attribute.type = type;
    attribute.normalized = GL_FALSE;
    attribute.relativeOffset = relativeoffset;
    attribute.integer = true;
    attribute.longData = false;
    attribute.useSeparatedFormat = true;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexAttribLFormat(GLuint attribindex, GLint size, GLenum type, GLuint relativeoffset) {
    if (size < 1 || size > 4) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_DOUBLE) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.4 §10.3.8: relativeoffset > MAX_VERTEX_ATTRIB_RELATIVE_OFFSET
    // is INVALID_VALUE.
    {
        GLint64 maxRelOffset = 2047;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger64(
                GL_MAX_VERTEX_ATTRIB_RELATIVE_OFFSET, &maxRelOffset);
        }
        if (relativeoffset > static_cast<GLuint>(maxRelOffset)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr || attribindex >= vertexArray->attributes.size()) {
        pushError(attribindex >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    auto& attribute = vertexArray->attributes[attribindex];
    attribute.size = size;
    attribute.type = type;
    attribute.normalized = GL_FALSE;
    attribute.relativeOffset = relativeoffset;
    attribute.integer = false;
    attribute.longData = true;
    attribute.useSeparatedFormat = true;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexAttribBinding(GLuint attribindex, GLuint bindingindex) {
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §10.3.1: attribindex must be < MAX_VERTEX_ATTRIBS,
    // bindingindex must be < MAX_VERTEX_ATTRIB_BINDINGS. The
    // bindingPoints vector is sized to MAX_VERTEX_ATTRIBS (32),
    // wider than MAX_VERTEX_ATTRIB_BINDINGS (16), so the size-
    // based check lets binding indices in [16, 32) through.
    GLint64 maxBindings = 16;
    if (impl_->capabilities != nullptr) {
        impl_->capabilities->queryInteger64(
            GL_MAX_VERTEX_ATTRIB_BINDINGS, &maxBindings);
    }
    if (attribindex >= vertexArray->attributes.size() ||
        bindingindex >= static_cast<GLuint>(maxBindings) ||
        bindingindex >= vertexArray->bindingPoints.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    vertexArray->attributes[attribindex].bindingIndex = bindingindex;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::vertexBindingDivisor(GLuint bindingindex, GLuint divisor) {
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLint64 maxBindings = 16;
    if (impl_->capabilities != nullptr) {
        impl_->capabilities->queryInteger64(
            GL_MAX_VERTEX_ATTRIB_BINDINGS, &maxBindings);
    }
    if (bindingindex >= static_cast<GLuint>(maxBindings) ||
        bindingindex >= vertexArray->bindingPoints.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    vertexArray->bindingPoints[bindingindex].divisor = divisor;
    // Mirror into the legacy per-attribute `divisor` for every
    // attribute currently routed to this binding — keeps the
    // legacy draw-time path in sync. `GL_VERTEX_ATTRIB_ARRAY_DIVISOR`
    // queries read from the binding point directly (below), so this
    // mirror isn't what drives the query result; it just keeps the
    // MetalVertexDescriptorBuilder's `attribute.divisor` field
    // accurate for draws that use the legacy attribute-fields path.
    for (auto& a : vertexArray->attributes) {
        if (a.bindingIndex == bindingindex) {
            a.divisor = divisor;
        }
    }
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::getVertexAttribInteger(GLuint index, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr || index >= vertexArray->attributes.size()) {
        pushError(index >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    const auto& attribute = vertexArray->attributes[index];
    switch (pname) {
        case GL_VERTEX_ATTRIB_ARRAY_ENABLED:
            params[0] = attribute.enabled ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_SIZE:
            params[0] = attribute.size;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_STRIDE:
            params[0] = attribute.stride;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_TYPE:
            params[0] = static_cast<GLint>(attribute.type);
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_NORMALIZED:
            params[0] = attribute.normalized;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_BUFFER_BINDING:
            // GL 4.6 §10.3.8: returns the buffer bound to the
            // *binding point* used by this attribute, not the raw
            // legacy `attribute.buffer` field. For
            // glVertexAttribPointer the two coincide because it
            // implicitly sets binding=index and binds the current
            // GL_ARRAY_BUFFER to that binding point.
            if (attribute.bindingIndex < vertexArray->bindingPoints.size()) {
                params[0] = static_cast<GLint>(
                    vertexArray->bindingPoints[attribute.bindingIndex].buffer);
            } else {
                params[0] = static_cast<GLint>(attribute.buffer);
            }
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_INTEGER:
            params[0] = attribute.integer ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_DIVISOR:
            // Per-attribute divisor query — always returns the
            // divisor of the binding point the attribute uses.
            // `glVertexAttribDivisor` / `glVertexBindingDivisor`
            // write the same state slot per GL 4.6 §10.3.8, so the
            // lookup needs to route through the binding index.
            if (attribute.bindingIndex < vertexArray->bindingPoints.size()) {
                params[0] = static_cast<GLint>(
                    vertexArray->bindingPoints[attribute.bindingIndex].divisor);
            } else {
                params[0] = static_cast<GLint>(attribute.divisor);
            }
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_LONG:
            params[0] = attribute.longData ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_BINDING:
            // GL 4.3 separated-format binding index; default = attribute index.
            params[0] = static_cast<GLint>(attribute.bindingIndex);
            return true;
        case GL_VERTEX_ATTRIB_RELATIVE_OFFSET:
            // GL 4.3 separated-format relative offset within the binding.
            params[0] = static_cast<GLint>(attribute.relativeOffset);
            return true;
        case GL_CURRENT_VERTEX_ATTRIB:
            params[0] = 0;
            params[1] = 0;
            params[2] = 0;
            params[3] = 1;
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getVertexAttribFloat(GLuint index, GLenum pname, GLfloat* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname == GL_CURRENT_VERTEX_ATTRIB) {
        params[0] = 0.0f;
        params[1] = 0.0f;
        params[2] = 0.0f;
        params[3] = 1.0f;
        return true;
    }

    GLint values[4] = {};
    if (!getVertexAttribInteger(index, pname, values)) {
        return false;
    }
    params[0] = static_cast<GLfloat>(values[0]);
    return true;
}

bool GLContext::getVertexAttribPointer(GLuint index, GLenum pname, void** pointer) {
    if (pointer == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname != GL_VERTEX_ATTRIB_ARRAY_POINTER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr || index >= vertexArray->attributes.size()) {
        pushError(index >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    *pointer = reinterpret_cast<void*>(vertexArray->attributes[index].pointer);
    return true;
}

// --- GL 4.1: Double-precision vertex attributes (Group 12) ---

bool GLContext::vertexAttribLPointer(GLuint index, GLint size, GLenum type, GLsizei stride, const void* pointer) {
    // GL spec: type must be GL_DOUBLE for glVertexAttribLPointer.
    if (size < 1 || size > 4 || stride < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_DOUBLE) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLVertexArrayObject* vertexArray = impl_->currentVertexArray();
    if (vertexArray == nullptr || index >= vertexArray->attributes.size()) {
        pushError(index >= static_cast<GLuint>(impl_->objects->maxVertexAttribs()) ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    const GLuint buffer = impl_->state->boundBuffer(GL_ARRAY_BUFFER);
    if (buffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    auto& attribute = vertexArray->attributes[index];
    attribute.size = size;
    attribute.type = type;
    attribute.normalized = GL_FALSE;
    attribute.stride = stride;
    attribute.pointer = reinterpret_cast<std::uintptr_t>(pointer);
    attribute.buffer = buffer;
    attribute.integer = false;
    attribute.longData = true;
    markVertexDescriptorDirty(*vertexArray);
    impl_->state->markDirty(DirtyBit::VertexInput);
    return true;
}

bool GLContext::setVertexAttribLImmediate(GLuint index, GLint count, const GLdouble* values) {
    // Immediate vertex attributes are per-context state (not per-VAO).
    if (index >= impl_->kMaxImmediateDoubleAttribs) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    auto& slot = impl_->immediateDoubleAttribs[index];
    slot[0] = count >= 1 ? values[0] : 0.0;
    slot[1] = count >= 2 ? values[1] : 0.0;
    slot[2] = count >= 3 ? values[2] : 0.0;
    slot[3] = count >= 4 ? values[3] : 1.0;
    return true;
}

bool GLContext::getVertexAttribLdv(GLuint index, GLenum pname, GLdouble* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (pname == GL_CURRENT_VERTEX_ATTRIB) {
        // Return the stored per-context immediate double values (lossless).
        if (index >= impl_->kMaxImmediateDoubleAttribs) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        const auto& slot = impl_->immediateDoubleAttribs[index];
        params[0] = slot[0];
        params[1] = slot[1];
        params[2] = slot[2];
        params[3] = slot[3];
        return true;
    }
    // For non-CURRENT_VERTEX_ATTRIB pnames, delegate to the integer getter and widen.
    GLint values[4] = {};
    if (!getVertexAttribInteger(index, pname, values)) {
        return false;
    }
    params[0] = static_cast<GLdouble>(values[0]);
    return true;
}

bool GLContext::activeTexture(GLenum texture) {
    // Must match GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS (80) in GLCapabilities.
    // CTS state reset iterates that cap — a stricter gate breaks state reset.
    if (texture < GL_TEXTURE0 || texture >= GL_TEXTURE0 + 80) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    impl_->state->setActiveTextureUnit(texture - GL_TEXTURE0);
    return true;
}

bool GLContext::genTextures(GLsizei count, GLuint* textures) {
    if (count < 0 || (count > 0 && textures == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        textures[index] = impl_->objects->textures().reserveName();
    }
    return true;
}

bool GLContext::deleteTextures(GLsizei count, const GLuint* textures) {
    if (count < 0 || (count > 0 && textures == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = textures[index];
        if (name == 0) {
            continue;
        }
        if (GLTextureObject* object = impl_->objects->textures().get(name); object != nullptr) {
            impl_->releaseTextureStorage(*object);
        }
        if (impl_->objects->textures().erase(name)) {
            impl_->state->deleteTextureBindings(name);
            impl_->deleteTextureReferencesFromFramebuffers(name);
            // GL 4.6 §5.1.2 — deleting a texture also clears any image
            // unit binding that referenced it. CTS
            // `shader_image_load_store.basic-api-bind` asserts that
            // glGetIntegeri_v(IMAGE_BINDING_NAME) returns 0 after
            // glDeleteTextures for the previously-bound name.
            for (auto& ib : impl_->imageBindings) {
                if (ib.texture == name) {
                    ib.texture = 0;
                    ib.level = 0;
                    ib.layered = GL_FALSE;
                    ib.layer = 0;
                }
            }
            impl_->objects->deferDelete("texture " + std::to_string(name));
        }
    }
    return true;
}

bool GLContext::isTexture(GLuint texture) const {
    const GLTextureObject* object = impl_->objects->textures().get(texture);
    return object != nullptr && object->instantiated;
}

bool GLContext::bindTexture(GLenum target, GLuint texture) {
    if (!isTextureTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (texture == 0) {
        impl_->state->bindTexture(target, 0);
        return true;
    }
    GLTextureObject* object = impl_->objects->textures().get(texture);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (object->target != 0 && object->target != target) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    object->target = target;
    object->desc.target = target;
    object->instantiated = true;
    impl_->state->bindTexture(target, texture);
    return true;
}

bool GLContext::texImage(
    GLenum target,
    GLint level,
    GLint internalformat,
    GLsizei width,
    GLsizei height,
    GLsizei depth,
    GLint border,
    GLenum format,
    GLenum type,
    const void* pixels
) {
    if (!isTextureTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (level < 0 || width < 0 || height < 0 || depth < 0 || border != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isSupportedInternalTextureFormat(*impl_->capabilities, static_cast<GLenum>(internalformat)) || componentCountForFormat(format) == 0) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if ((target == GL_TEXTURE_1D && (height != 1 || depth != 1))
        || (target == GL_TEXTURE_2D && depth != 1)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLenum internalFormatEnum = static_cast<GLenum>(internalformat);
    if (target == GL_TEXTURE_3D &&
        (isDepthFormat(internalFormatEnum) ||
         isStencilFormat(internalFormatEnum) ||
         isTexture3DRGTCFormat(internalFormatEnum))) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §8.5 — GL_TEXTURE_CUBE_MAP_ARRAY storage must be
    // square (width == height) with depth a multiple of 6.
    if (target == GL_TEXTURE_CUBE_MAP_ARRAY) {
        if (width != height) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if ((depth % 6) != 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    // Enforce GL_MAX_TEXTURE_SIZE/GL_MAX_3D_TEXTURE_SIZE before reaching
    // Metal (which asserts on oversize dims).
    if (impl_->capabilities != nullptr) {
        GLint maxTex = 0, max3D = 0, maxLayers = 0;
        impl_->capabilities->queryInteger(GL_MAX_TEXTURE_SIZE, &maxTex);
        impl_->capabilities->queryInteger(GL_MAX_3D_TEXTURE_SIZE, &max3D);
        impl_->capabilities->queryInteger(GL_MAX_ARRAY_TEXTURE_LAYERS, &maxLayers);
        if (maxTex > 0 && (width > maxTex || height > maxTex)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if (target == GL_TEXTURE_3D && max3D > 0 && (width > max3D || height > max3D || depth > max3D)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if ((target == GL_TEXTURE_2D_ARRAY || target == GL_TEXTURE_1D_ARRAY ||
             target == GL_TEXTURE_CUBE_MAP_ARRAY) &&
            maxLayers > 0 && depth > maxLayers) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }

    GLTextureObject* object = impl_->currentTexture(target);
    // CTS state reset (gluStateReset.cpp) calls texImage{2,3}D with size 0x0
    // on targets where no user texture is bound (default texture, name=0).
    // Per OpenGL 4.6 §8.5, such calls are valid — they either modify the
    // default texture object or are treated as a no-op when dims are 0.
    // Silently accept to keep state reset from throwing.
    if (object == nullptr) {
        return true;
    }
    if (!object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (object->desc.immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    GLTextureImageLevel image;
    image.desc.target = target;
    image.desc.internalFormat = static_cast<GLenum>(internalformat);
    image.desc.sourceFormat = format;
    image.desc.sourceType = type;
    image.desc.width = width;
    image.desc.height = target == GL_TEXTURE_1D ? 1 : height;
    // GL_TEXTURE_3D and the array targets all carry layer/depth count in `depth`.
    image.desc.depth = (target == GL_TEXTURE_3D
                        || target == GL_TEXTURE_2D_ARRAY
                        || target == GL_TEXTURE_CUBE_MAP_ARRAY) ? depth : 1;
    // Mirror depth → layers for array targets. Parallel to the
    // texStorage3D path (line ~8180). Without this, a
    // glFramebufferTextureLayer(layer = N) on a texImage3D-allocated
    // TEXTURE_2D_ARRAY returned GL_INVALID_VALUE for every N >= 1
    // because the framebufferTexture layer-bounds check consults
    // desc.layers (which defaulted to 1), not desc.depth.
    // Fixes `geometry_shader.layered_framebuffer.stencil_support`.
    image.desc.layers = (target == GL_TEXTURE_2D_ARRAY
                          || target == GL_TEXTURE_1D_ARRAY
                          || target == GL_TEXTURE_CUBE_MAP_ARRAY)
        ? depth : 1;
    image.desc.levels = std::max<GLsizei>(object->desc.levels, level + 1);
    image.defined = true;
    // Resolve pixels against GL_PIXEL_UNPACK_BUFFER if one is bound.
    // Without this, passing an offset (as CTS does after binding a PBO)
    // would SIGSEGV when we treat the offset as a raw pointer. See
    // Impl::resolveUnpackPBO — returns (nullptr, false) for any PBO
    // validation failure (range / alignment / mapped), and the caller
    // pushes GL_INVALID_OPERATION per GL 4.6 §8.5.
    const std::size_t pxBytes = bytesPerPixel(format, type);
    const std::size_t typeBytes = isPackedPixelType(type)
        ? pxBytes : bytesPerComponent(type);
    const std::size_t requiredBytes = static_cast<std::size_t>(
        image.desc.width) * static_cast<std::size_t>(image.desc.height)
        * static_cast<std::size_t>(image.desc.depth) * pxBytes;
    auto [resolvedPixels, pboOk] = impl_->resolveUnpackPBO(
        pixels, requiredBytes, typeBytes > 0 ? typeBytes : 1);
    if (!pboOk) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!impl_->buildRGBA8Upload(image.desc.width, image.desc.height, image.desc.depth, format, type, resolvedPixels, image.rgba8)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Also build native-format data for non-RGBA8 internal formats.
    impl_->buildNativeUpload(
        static_cast<GLenum>(internalformat),
        image.desc.width, image.desc.height, image.desc.depth,
        format, type, resolvedPixels, image.nativeData, image.nativeBpp);

    if (level == 0 || !object->levels.contains(0)) {
        object->desc = image.desc;
    }
    object->desc.levels = std::max<GLsizei>(object->desc.levels, level + 1);
    image.desc.levels = object->desc.levels;
    object->levels[level] = std::move(image);
    // Track cube-face definition for cube-completeness checking at
    // glGenerateMipmap time. Only level-0 face definitions count toward
    // cube completeness (GL 4.6 §8.17).
    if (level == 0) {
        const int faceIdx = Impl::cubeFaceIndexForTarget(target);
        if (faceIdx >= 0) {
            object->cubeFacesDefined |= static_cast<std::uint8_t>(1u << faceIdx);
        }
    }
    if (!impl_->replaceMetalTexture(*object, impl_->state->boundTexture(target))) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

bool GLContext::texSubImage(
    GLenum target,
    GLint level,
    GLint xoffset,
    GLint yoffset,
    GLint zoffset,
    GLsizei width,
    GLsizei height,
    GLsizei depth,
    GLenum format,
    GLenum type,
    const void* pixels
) {
    if (!isTextureTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (level < 0 || xoffset < 0 || yoffset < 0 || zoffset < 0 || width < 0 || height < 0 || depth < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (componentCountForFormat(format) == 0) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // Type validation — unknown / unsupported type enums must produce
    // GL_INVALID_ENUM (GL 4.6 §8.4.4 / §8.5, Table 8.7). Without this,
    // the test's m_type_invalid case saw GL_INVALID_OPERATION from
    // the downstream buildRGBA8Upload failure.
    if (!isPackedPixelType(type) && bytesPerComponent(type) == 0) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // Format / type compatibility (GL 4.6 Table 8.7). Packed types
    // constrain the format they can appear with. A format like GL_RG
    // with type GL_UNSIGNED_BYTE_3_3_2 should produce
    // GL_INVALID_OPERATION per spec — our impl previously silently
    // accepted the combination and proceeded to upload junk.
    if (!isFormatTypeCompatible_extern(format, type)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    GLTextureObject* object = impl_->currentTexture(target);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Level bounds vs MAX_TEXTURE_SIZE must yield INVALID_VALUE, not
    // INVALID_OPERATION (GL 4.6 §8.5: "level is greater than log2 max,
    // where max is MAX_TEXTURE_SIZE"). Distinct from "level defined?"
    // which we check below — an out-of-range level index is invalid
    // before we even look at the map.
    if (impl_->capabilities != nullptr) {
        GLint maxTex = 0;
        impl_->capabilities->queryInteger(GL_MAX_TEXTURE_SIZE, &maxTex);
        if (maxTex > 0) {
            int maxLevel = 0;
            for (GLint dim = maxTex; dim > 1; dim >>= 1) ++maxLevel;
            if (level > maxLevel) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
        }
    }
    auto levelIt = object->levels.find(level);
    if (levelIt == object->levels.end() || !levelIt->second.defined) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLTextureImageLevel& image = levelIt->second;
    if (xoffset > image.desc.width || width > image.desc.width - xoffset
        || yoffset > image.desc.height || height > image.desc.height - yoffset
        || zoffset > image.desc.depth || depth > image.desc.depth - zoffset) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // Resolve pixels against GL_PIXEL_UNPACK_BUFFER if bound (see
    // texImage for rationale). CTS DSA textures_subimage_errors SIGSEGV
    // was rooted here — the test binds a PBO, passes a byte-offset as
    // the `pixels` argument, and expects GL_INVALID_OPERATION for
    // out-of-range / mapped / unaligned conditions. Without PBO
    // resolution we dereferenced the offset as a raw pointer and
    // crashed.
    //
    // The null-pixels check is DEFERRED until after PBO resolution —
    // with a PBO bound, pixels==nullptr is the offset 0, which is
    // valid (and even expected for "read from start of buffer").
    // Without a PBO, nullptr with non-zero dimensions is INVALID_VALUE.
    const std::size_t pxBytes = bytesPerPixel(format, type);
    const std::size_t typeBytes = isPackedPixelType(type)
        ? pxBytes : bytesPerComponent(type);
    const std::size_t requiredBytes = static_cast<std::size_t>(width)
        * static_cast<std::size_t>(height) * static_cast<std::size_t>(depth)
        * pxBytes;
    auto [resolvedPixels, pboOk] = impl_->resolveUnpackPBO(
        pixels, requiredBytes, typeBytes > 0 ? typeBytes : 1);
    if (!pboOk) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const bool pboBound = impl_->state->boundBuffer(GL_PIXEL_UNPACK_BUFFER) != 0;
    if (!pboBound && width > 0 && height > 0 && depth > 0 && resolvedPixels == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    std::vector<std::uint8_t> upload;
    if (!impl_->buildRGBA8Upload(width, height, depth, format, type, resolvedPixels, upload)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    for (GLsizei z = 0; z < depth; ++z) {
        for (GLsizei y = 0; y < height; ++y) {
            const std::size_t sourceOffset =
                (static_cast<std::size_t>(z) * static_cast<std::size_t>(height) + static_cast<std::size_t>(y))
                * static_cast<std::size_t>(width) * 4u;
            const std::size_t destOffset =
                ((static_cast<std::size_t>(z + zoffset) * static_cast<std::size_t>(image.desc.height)
                    + static_cast<std::size_t>(y + yoffset))
                    * static_cast<std::size_t>(image.desc.width)
                    + static_cast<std::size_t>(xoffset))
                * 4u;
            std::memcpy(
                image.rgba8.data() + destOffset,
                upload.data() + sourceOffset,
                static_cast<std::size_t>(width) * 4u
            );
        }
    }

    // Also update native-format data when present.
    if (image.nativeBpp > 0 && !image.nativeData.empty()) {
        std::vector<std::uint8_t> nativeUpload;
        std::size_t nativeBpp = 0;
        if (impl_->buildNativeUpload(image.desc.internalFormat,
                width, height, depth, format, type, resolvedPixels,
                nativeUpload, nativeBpp) && nativeBpp == image.nativeBpp) {
            for (GLsizei z = 0; z < depth; ++z) {
                for (GLsizei y = 0; y < height; ++y) {
                    const std::size_t srcOff =
                        (static_cast<std::size_t>(z) * static_cast<std::size_t>(height)
                         + static_cast<std::size_t>(y))
                        * static_cast<std::size_t>(width) * nativeBpp;
                    const std::size_t dstOff =
                        ((static_cast<std::size_t>(z + zoffset) * static_cast<std::size_t>(image.desc.height)
                          + static_cast<std::size_t>(y + yoffset))
                         * static_cast<std::size_t>(image.desc.width)
                         + static_cast<std::size_t>(xoffset))
                        * nativeBpp;
                    std::memcpy(
                        image.nativeData.data() + dstOff,
                        nativeUpload.data() + srcOff,
                        static_cast<std::size_t>(width) * nativeBpp);
                }
            }
        }
    }

    // Phase 8X Group 4d follow-up¹¹ — §Secondary per-subregion
    // fingerprint. Fires at most once per distinct
    // `(texName, xoffset, yoffset, width, height)` so Recoil's
    // glyph streaming (one sub-image call per glyph rect) gets
    // fingerprinted at the first update to each distinct
    // rectangle without flooding the log on repeat updates to
    // the same rectangle.
    //
    // The hash runs on the channel-fill-expanded RGBA8 `upload`
    // vector — that's the same representation the outer texture's
    // level-0 byte store uses, so BAR can cross-reference it
    // against the native-GL-path fingerprint BAR computes on the
    // post-channel-fill RGBA8.
    //
    // Unlike `replaceMetalTexture`'s log, this fires unconditionally
    // (not gated on texName !=0) because by the time we reach this
    // point the object pointer is valid and we know the bound
    // texture name is non-zero (currentTexture returned a concrete
    // object).
    const GLuint subTexName = impl_->state->boundTexture(target);
    if (subTexName != 0 && depth == 1) {
        Impl::SubImageRegionKey key{subTexName, xoffset, yoffset, width, height};
        if (impl_->loggedSubImageRegions.insert(key).second) {
            const std::uint8_t* subBytes = upload.data();
            const std::size_t subByteCount = upload.size();
            auto fnv1a = [](const std::uint8_t* p, std::size_t n) {
                std::uint32_t h = 0x811c9dc5u;
                for (std::size_t i = 0; i < n; ++i) {
                    h ^= p[i];
                    h *= 0x01000193u;
                }
                return h;
            };
            const std::uint32_t subHash = subByteCount ? fnv1a(subBytes, subByteCount) : 0;
            std::uint32_t nonzeroCount = 0;
            for (std::size_t i = 0; i < subByteCount; ++i) {
                if (subBytes[i] != 0) { ++nonzeroCount; }
            }
            char hexPeek[64] = {0};
            const std::size_t peekLen = std::min<std::size_t>(subByteCount, 16);
            for (std::size_t i = 0; i < peekLen; ++i) {
                std::snprintf(hexPeek + i * 3, sizeof(hexPeek) - i * 3,
                              "%02X ", subBytes[i]);
            }
            if (peekLen > 0) { hexPeek[peekLen * 3 - 1] = '\0'; }
            APPGL_LOG(TEXTURE, @"[GL] texSubImage first-call texName=%u target=0x%04X level=%d"
                  @" subregion=[%d,%d,%d,%d] sourceFormat=0x%04X sourceType=0x%04X"
                  @" rgba8Bytes=%zu fnv1a=0x%08X nonzero=%u peek16=[%s]",
                  subTexName,
                  static_cast<unsigned>(target),
                  level,
                  xoffset, yoffset, width, height,
                  static_cast<unsigned>(format),
                  static_cast<unsigned>(type),
                  subByteCount,
                  subHash,
                  nonzeroCount,
                  hexPeek);
        }
    }

    if (!impl_->replaceMetalTexture(*object, impl_->state->boundTexture(target))) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

// Sprint 17 Day 7+ Bank-Group-E: 4×4-block compressed-texture upload.
//
// Pre-fix `glCompressedTexImage2D` was a drop-data stub at
// AppGLGroup8.cpp:528 — only desc.width/height/internalFormat were
// recorded; no Metal texture allocated, no bytes uploaded. CTS
// `direct_state_access.textures_get_image` (compressed sub-test)
// uploads BC7 (16 bytes) via this path then reads it back via
// glGetCompressedTextureImage; pre-fix readback returned zeros.
//
// Implementation strategy:
// 1. Look up MTLPixelFormat from caps (already populated for BPTC +
//    RGTC at GLCapabilities.mm:524-537 when supportsBC).
// 2. Allocate MTLTexture with that format + width/height + level
//    count (single mipLevel for now; multi-level arrives via
//    compressedTexSubImage on subsequent calls).
// 3. Upload via replaceRegion:mipmapLevel:withBytes:bytesPerRow: with
//    block-aware byte counts ((W+3)/4)*bytesPerBlock per row of
//    blocks).
// 4. Stash MTLTexture pointer on the GLTextureObject so subsequent
//    sample / readback paths see it.
//
// 4×4-block BPTC + RGTC family: BC1/BC4 = 8 bytes/block;
// BC2/BC3/BC5/BC6H/BC7 = 16 bytes/block. Other compressed formats
// (ETC2 / EAC / ASTC) deferred to Bank-Group-E follow-up.
bool GLContext::compressedTexImage(GLenum target, GLint level,
                                   GLenum internalformat,
                                   GLsizei width, GLsizei height,
                                   GLsizei depth,
                                   GLsizei imageSize, const void* data) {
    if (level < 0 || width <= 0 || height <= 0 || depth <= 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTextureObject* object = impl_->currentTexture(target);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!object->instantiated) {
        // First bind via glBindTexture should have set instantiated.
        // Synthesise one here so the caller path stays defensive.
        object->instantiated = true;
    }
    // Sprint 17 Day 9+ Bank-Group-E narrow-gate (regression-debt #3):
    // record dimensions UNCONDITIONALLY for any valid level/width/
    // height before format-specific dispatch. Pre-narrow `dcba5cd`
    // the dimension-recording happened later in the BC-format arm
    // only; non-BC formats (ETC2 / EAC / ASTC) hit the default arm
    // and returned true WITHOUT setting desc, leaving subsequent
    // glGetCompressedTextureSubImage validation comparing
    // `xoffset+width > texW=0` and pushing GL_INVALID_VALUE — CTS
    // `get_texture_sub_image.errors_test` uses GL_COMPRESSED_RGB8_ETC2
    // and expected GL_INVALID_OPERATION on bufSize-too-small.
    object->target = target;
    object->desc.target = target;
    object->desc.width = width;
    object->desc.height = (target == GL_TEXTURE_1D) ? 1 : height;
    object->desc.depth = depth;
    object->desc.internalFormat = internalformat;
    if (impl_->capabilities == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    auto fmtCap = impl_->capabilities->format(internalformat);
    if (!fmtCap.has_value() || !fmtCap->compressed) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    const MTLPixelFormat pf = static_cast<MTLPixelFormat>(fmtCap->metalPixelFormat);
    NSUInteger bytesPerBlock = 0;
    switch (pf) {
        case MTLPixelFormatBC1_RGBA:
        case MTLPixelFormatBC1_RGBA_sRGB:
        case MTLPixelFormatBC4_RUnorm:
        case MTLPixelFormatBC4_RSnorm:
            bytesPerBlock = 8;
            break;
        case MTLPixelFormatBC2_RGBA:
        case MTLPixelFormatBC2_RGBA_sRGB:
        case MTLPixelFormatBC3_RGBA:
        case MTLPixelFormatBC3_RGBA_sRGB:
        case MTLPixelFormatBC5_RGUnorm:
        case MTLPixelFormatBC5_RGSnorm:
        case MTLPixelFormatBC6H_RGBFloat:
        case MTLPixelFormatBC6H_RGBUfloat:
        case MTLPixelFormatBC7_RGBAUnorm:
        case MTLPixelFormatBC7_RGBAUnorm_sRGB:
            bytesPerBlock = 16;
            break;
        default:
            // Other compressed formats (ETC2 / EAC / ASTC) — fall back
            // to the legacy drop-data path. Caller already recorded
            // dimensions in AppGLGroup8.cpp:528.
            return true;
    }
    id<MTLDevice> mtlDevice = impl_->device;
    if (mtlDevice == nil) {
        // No Metal device — silently accept; downstream sampling /
        // readback will hit the no-MTLTexture branch.
        return true;
    }
    // Record dimensions on the GL texture object so subsequent queries
    // (glGetCompressedTextureSubImage bounds, glGetTexLevelParameter)
    // see the right values.
    object->target = target;
    object->desc.target = target;
    object->desc.width = width;
    object->desc.height = (target == GL_TEXTURE_1D) ? 1 : height;
    object->desc.depth = depth;
    object->desc.internalFormat = internalformat;
    // Allocate Metal texture if missing OR if format/size changed.
    id<MTLTexture> existing = (__bridge id<MTLTexture>)object->metalTexture;
    bool needAlloc = (existing == nil) ||
                     existing.pixelFormat != pf ||
                     existing.width != static_cast<NSUInteger>(width) ||
                     existing.height != static_cast<NSUInteger>(height);
    if (needAlloc) {
        MTLTextureDescriptor* desc = [[MTLTextureDescriptor alloc] init];
        desc.textureType = (target == GL_TEXTURE_2D)
            ? MTLTextureType2D
            : MTLTextureType2D;  // 1D / 3D BC are unusual; default 2D
        desc.pixelFormat = pf;
        desc.width = static_cast<NSUInteger>(width);
        desc.height = static_cast<NSUInteger>(height);
        desc.depth = 1;
        desc.mipmapLevelCount = static_cast<NSUInteger>(level + 1);
        desc.usage = MTLTextureUsageShaderRead;
        desc.storageMode = MTLStorageModeShared;
        id<MTLTexture> newTex = [mtlDevice newTextureWithDescriptor:desc];
        if (newTex == nil) {
            pushError(GL_OUT_OF_MEMORY);
            return false;
        }
        if (object->metalTexture != nullptr) {
            releaseRetainedMetalObject(object->metalTexture);
        }
        object->metalTexture = transferRetainedMetalObject(newTex);
        existing = newTex;
    }
    // Upload payload (if provided). Block-aware bytesPerRow.
    if (data != nullptr && imageSize > 0) {
        const NSUInteger blocksX = (static_cast<NSUInteger>(width) + 3) / 4;
        const NSUInteger bytesPerRow = blocksX * bytesPerBlock;
        MTLRegion region = MTLRegionMake2D(
            0, 0,
            static_cast<NSUInteger>(width),
            static_cast<NSUInteger>(height));
        [existing replaceRegion:region
                    mipmapLevel:static_cast<NSUInteger>(level)
                      withBytes:data
                    bytesPerRow:bytesPerRow];
    }
    return true;
}

bool GLContext::texStorage(
    GLenum target,
    GLsizei levels,
    GLenum internalformat,
    GLsizei width,
    GLsizei height,
    GLsizei depth
) {
    if (!isTextureTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (levels < 1 || width < 1 || height < 1 || depth < 1) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §8.17 — GL_TEXTURE_CUBE_MAP_ARRAY storage must have
    // width == height (cube faces are square) AND depth a multiple
    // of 6 (cube has 6 faces per layer). CTS
    // texture_cube_map_array.tex3D_validation exercises both.
    if (target == GL_TEXTURE_CUBE_MAP_ARRAY) {
        if (width != height) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if ((depth % 6) != 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    // GL 4.6 §8.19 — for immutable storage, `levels` must not exceed
    // floor(log2(max(width, height[, depth]))) + 1. Apply to the
    // cube-map-array path explicitly; other targets have the same
    // cap but the Metal allocator historically clamped levels down,
    // so CTS didn't fire this error on them.
    if (target == GL_TEXTURE_CUBE_MAP_ARRAY) {
        const GLsizei maxDim = std::max(width, height);
        GLsizei maxLevels = 1;
        for (GLsizei d = maxDim; d > 1; d >>= 1) ++maxLevels;
        if (levels > maxLevels) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    // GL 4.6 §8.19 + Metal reality: oversize textures must be rejected before
    // reaching MTLTextureDescriptor (which asserts rather than errors).
    // KHR-GL46.direct_state_access.textures_storage_errors etc. try 32768+
    // deliberately. Pull caps from GLCapabilities and enforce here.
    if (impl_->capabilities != nullptr) {
        GLint maxTex = 0, max3D = 0, maxLayers = 0;
        impl_->capabilities->queryInteger(GL_MAX_TEXTURE_SIZE, &maxTex);
        impl_->capabilities->queryInteger(GL_MAX_3D_TEXTURE_SIZE, &max3D);
        impl_->capabilities->queryInteger(GL_MAX_ARRAY_TEXTURE_LAYERS, &maxLayers);
        if (maxTex > 0 && (width > maxTex || height > maxTex)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if (target == GL_TEXTURE_3D && max3D > 0 && (width > max3D || height > max3D || depth > max3D)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if ((target == GL_TEXTURE_2D_ARRAY || target == GL_TEXTURE_1D_ARRAY ||
             target == GL_TEXTURE_CUBE_MAP_ARRAY) &&
            maxLayers > 0 && depth > maxLayers) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    if (!isSupportedInternalTextureFormat(*impl_->capabilities, internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }

    // GL 4.6 §8.19 / Khronos bug 11239: compressed internal formats
    // are NOT valid on TEXTURE_3D (RGTC1/RGTC2/BPTC were never
    // specified to have a 3D block form). Other targets
    // (TEXTURE_2D / TEXTURE_2D_ARRAY / TEXTURE_CUBE_MAP[_ARRAY])
    // accept them. CTS `texture_storage.compressed_data` walks the
    // RGTC set against each target and expects INVALID_OPERATION
    // for the TEXTURE_3D combinations.
    if (target == GL_TEXTURE_3D) {
        switch (internalformat) {
            case GL_COMPRESSED_RED_RGTC1:
            case GL_COMPRESSED_SIGNED_RED_RGTC1:
            case GL_COMPRESSED_RG_RGTC2:
            case GL_COMPRESSED_SIGNED_RG_RGTC2:
            case GL_COMPRESSED_RGBA_BPTC_UNORM:
            case GL_COMPRESSED_SRGB_ALPHA_BPTC_UNORM:
            case GL_COMPRESSED_RGB_BPTC_SIGNED_FLOAT:
            case GL_COMPRESSED_RGB_BPTC_UNSIGNED_FLOAT:
                pushError(GL_INVALID_OPERATION);
                return false;
            default:
                break;
        }
    }

    GLTextureObject* object = impl_->currentTexture(target);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (object->desc.immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    object->desc.target = target;
    object->desc.internalFormat = internalformat;
    object->desc.width = width;
    object->desc.height = (target == GL_TEXTURE_1D) ? 1 : height;
    object->desc.depth = (target == GL_TEXTURE_3D
                          || target == GL_TEXTURE_2D_ARRAY
                          || target == GL_TEXTURE_CUBE_MAP_ARRAY) ? depth : 1;
    // Mirror depth into `layers` for the array targets — framebuffer-
    // texture-layer validation consults this field when deciding
    // whether an attach-layer is in range. Without it, attaching a
    // layer of a glTexStorage3D-allocated GL_TEXTURE_2D_ARRAY raised
    // GL_INVALID_VALUE on every layer > 0 (the default value of 1).
    object->desc.layers = (target == GL_TEXTURE_2D_ARRAY
                          || target == GL_TEXTURE_1D_ARRAY
                          || target == GL_TEXTURE_CUBE_MAP_ARRAY)
        ? depth : 1;
    object->desc.levels = levels;
    object->desc.immutable = true;
    object->target = target;
    // Sprint 17 Day 8+ FANTASTIC #9 cube fix — texStorage* on a cube
    // target allocates all 6 faces' immutable storage in a single call
    // (GL 4.6 §8.19). Mark `cubeFacesDefined` complete here so the
    // cube-completeness check in `getTextureImage` (line ~35913) and
    // `generateMipmap` (line ~13371) accept the texture without
    // requiring a per-face `glTexImage2D` after `glTexStorage2D`.
    // CTS `shading_language_420pack.binding_images_texture_type_cube`
    // creates a cube via texStorage2D, fills via compute imageStore,
    // reads back via glGetTexImage; pre-fix the readback raised
    // GL_INVALID_OPERATION because cubeFacesDefined was never set.
    if (target == GL_TEXTURE_CUBE_MAP) {
        object->cubeFacesDefined = 0x3F;
    }

    // Pre-create ALL levels [0, levels-1] per GL 4.6 §8.19: "All
    // [immutable storage] images are created by this function."
    // A subsequent glTexSubImage2D on level >= 1 must find the level
    // entry present — the old path only populated level 0 and
    // CTS texture_storage.compressed_data flunked on level 1+
    // texSubImage2D calls with GL_INVALID_OPERATION.
    //
    // Native-format backing is allocated per-level for non-RGBA8
    // internal formats (compressed, packed, integer, depth, …).
    MTLPixelFormat nativeFmt = metalRenderbufferFormat(internalformat);
    auto nativeInfo = (nativeFmt != MTLPixelFormatInvalid &&
                       nativeFmt != MTLPixelFormatRGBA8Unorm)
        ? Impl::nativeFormatInfo(nativeFmt)
        : Impl::NativeFormatInfo{};
    for (GLsizei lvl = 0; lvl < levels; ++lvl) {
        GLTextureImageLevel image;
        image.desc = object->desc;
        image.desc.width = std::max(1, width >> lvl);
        image.desc.height = (target == GL_TEXTURE_1D)
            ? 1 : std::max(1, height >> lvl);
        image.desc.depth = (target == GL_TEXTURE_3D)
            ? std::max(1, depth >> lvl)
            : object->desc.depth;  // array / cube depth doesn't scale
        image.defined = true;
        const std::size_t lvlPixels =
            static_cast<std::size_t>(image.desc.width)
            * static_cast<std::size_t>(image.desc.height)
            * static_cast<std::size_t>(image.desc.depth);
        image.rgba8.resize(lvlPixels * 4u, 0);
        if (nativeInfo.channels > 0 && nativeInfo.bytesPerPixel > 0) {
            image.nativeBpp =
                static_cast<std::size_t>(nativeInfo.bytesPerPixel);
            image.nativeData.resize(lvlPixels * image.nativeBpp, 0);
        }
        object->levels[lvl] = std::move(image);
    }

    if (!impl_->replaceMetalTexture(*object, impl_->state->boundTexture(target))) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

bool GLContext::texStorageMultisample(
    GLenum target,
    GLsizei samples,
    GLenum internalformat,
    GLsizei width,
    GLsizei height,
    GLsizei depth,
    GLboolean fixedsamplelocations
) {
    if (target != GL_TEXTURE_2D_MULTISAMPLE && target != GL_TEXTURE_2D_MULTISAMPLE_ARRAY) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (samples < 1 || width < 1 || height < 1 || depth < 1) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Enforce GL_MAX_TEXTURE_SIZE / array layers before reaching Metal
    // (which asserts on oversize). CTS textures_storage_multisample_errors
    // deliberately calls this with max_texture_size*2.
    if (impl_->capabilities != nullptr) {
        GLint maxTex = 0, maxLayers = 0;
        impl_->capabilities->queryInteger(GL_MAX_TEXTURE_SIZE, &maxTex);
        impl_->capabilities->queryInteger(GL_MAX_ARRAY_TEXTURE_LAYERS, &maxLayers);
        if (maxTex > 0 && (width > maxTex || height > maxTex)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if (target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY &&
            maxLayers > 0 && depth > maxLayers) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    if (!isSupportedInternalTextureFormat(*impl_->capabilities, internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // Metal only supports specific sample counts (typically 1, 2, 4, 8).
    // Unsupported values trigger MTLTextureDescriptor validation abort if
    // we pass them through. Check via MTLDevice.supportsTextureSampleCount.
    {
        id<MTLDevice> mtlDevice = impl_->device;
        if (mtlDevice != nil && samples > 1 && ![mtlDevice supportsTextureSampleCount:static_cast<NSUInteger>(samples)]) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }

    GLTextureObject* object = impl_->currentTexture(target);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (object->desc.immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // Clamp sample count to Metal maximum (typically 4 on Apple Silicon).
    GLsizei clampedSamples = std::min<GLsizei>(samples, 4);

    object->desc.target = target;
    object->desc.internalFormat = internalformat;
    object->desc.width = width;
    object->desc.height = height;
    object->desc.depth = (target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY) ? depth : 1;
    // framebufferTextureLayer consults desc.layers (not desc.depth) when
    // validating the layer argument — mirror depth into layers for the
    // multisample-array target. Without this, CTS DSA
    // `textures_storage_multisample_3d_*` fails framebufferTextureLayer
    // with INVALID_VALUE and raises IE via its outer catch().
    object->desc.layers = (target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY)
        ? depth : 1;
    object->desc.levels = 1;
    object->desc.samples = clampedSamples;
    object->desc.immutable = true;
    object->target = target;

    // Create a base-level entry for Metal texture creation.
    GLTextureImageLevel baseLevel;
    baseLevel.desc = object->desc;
    baseLevel.defined = true;
    const std::size_t byteCount = static_cast<std::size_t>(width) * static_cast<std::size_t>(height) * static_cast<std::size_t>(object->desc.depth) * 4u;
    baseLevel.rgba8.resize(byteCount, 0);
    object->levels[0] = std::move(baseLevel);

    if (!impl_->replaceMetalTexture(*object, impl_->state->boundTexture(target))) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

// GL 4.6 Table 8.12 — sized internal formats allowed for
// GL_TEXTURE_BUFFER. Unsized formats (GL_RGBA, GL_RED, etc.) are
// rejected with INVALID_ENUM per §8.9.
static bool isValidBufferTextureSizedFormat(GLenum fmt) {
    switch (fmt) {
        // R
        case GL_R8: case GL_R8I: case GL_R8UI:
        case GL_R16: case GL_R16I: case GL_R16UI: case GL_R16F:
        case GL_R32I: case GL_R32UI: case GL_R32F:
        // RG
        case GL_RG8: case GL_RG8I: case GL_RG8UI:
        case GL_RG16: case GL_RG16I: case GL_RG16UI: case GL_RG16F:
        case GL_RG32I: case GL_RG32UI: case GL_RG32F:
        // RGB (only 32-bit variants)
        case GL_RGB32I: case GL_RGB32UI: case GL_RGB32F:
        // RGBA
        case GL_RGBA8: case GL_RGBA8I: case GL_RGBA8UI:
        case GL_RGBA16: case GL_RGBA16I: case GL_RGBA16UI: case GL_RGBA16F:
        case GL_RGBA32I: case GL_RGBA32UI: case GL_RGBA32F:
            return true;
        default:
            return false;
    }
}

bool GLContext::texBufferRange(
    GLenum target,
    GLenum internalformat,
    GLuint buffer,
    GLintptr offset,
    GLsizeiptr size
) {
    if (target != GL_TEXTURE_BUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §8.9: buffer-texture internalformat must be a sized
    // internal format from Table 8.12. Unsized base formats (e.g.
    // GL_RED) and others raise INVALID_ENUM.
    if (!isValidBufferTextureSizedFormat(internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (offset < 0 || size <= 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §8.9: offset must be a multiple of
    // GL_TEXTURE_BUFFER_OFFSET_ALIGNMENT. We advertise 16.
    {
        GLint64 alignment = 16;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger64(
                GL_TEXTURE_BUFFER_OFFSET_ALIGNMENT, &alignment);
        }
        if ((offset % alignment) != 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }

    GLTextureObject* object = impl_->currentTexture(target);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §8.9: if `buffer` is non-zero it must name an
    // existing buffer object. Otherwise INVALID_OPERATION.
    if (buffer != 0) {
        GLBufferObject* checkBuf = impl_->objects->buffers().get(buffer);
        if (checkBuf == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // offset + size must be <= buffer's current size.
        if (static_cast<GLsizeiptr>(offset) + size > checkBuf->size) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }

    // Record the buffer-texture binding state.
    object->desc.target = target;
    object->desc.internalFormat = internalformat;
    object->desc.sourceBuffer = buffer;
    object->desc.bufferOffset = offset;
    object->desc.bufferSize = size;
    object->desc.immutable = true;
    object->target = target;

    // Create the Metal MTLTexture view over the source MTLBuffer using
    // `MTLTextureType::textureBuffer` (Metal 2.1+). This gives
    // `texture_buffer<T>` samplerBuffer access in MSL, which CTS
    // `direct_state_access.textures_buffer_*` uses via isamplerBuffer /
    // usamplerBuffer / samplerBuffer. Without this, the texture slot
    // was nil at draw time, the fragment shader sampled zero, and the
    // test threw an InternalError when `glGetProgramInfoLog` emitted
    // and the surrounding `catch(...)` converted the throw into IE.
    GLBufferObject* bufObj = impl_->objects->buffers().get(buffer);
    if (bufObj != nullptr && bufObj->metalBuffer != nullptr) {
        id<MTLBuffer> mtlBuffer = (__bridge id<MTLBuffer>)bufObj->metalBuffer;
        MTLPixelFormat pf = metalRenderbufferFormat(internalformat);
        if (pf != MTLPixelFormatInvalid) {
            MTLTextureDescriptor* desc = [[MTLTextureDescriptor alloc] init];
            desc.textureType = MTLTextureTypeTextureBuffer;
            desc.pixelFormat = pf;
            // Metal texture-buffer width counts TEXELS, not bytes.
            const NSUInteger bpp = [&](MTLPixelFormat p) -> NSUInteger {
                auto info = Impl::nativeFormatInfo(p);
                return static_cast<NSUInteger>(info.bytesPerPixel);
            }(pf);
            if (bpp > 0) {
                const NSUInteger byteLen = static_cast<NSUInteger>(size);
                const NSUInteger texelCount = byteLen / bpp;
                // Metal asserts on width=0 or when offset+byteLen exceeds
                // the buffer length. Skip Metal-side creation under those
                // degenerate conditions — CTS `textures_buffer_range_errors`
                // deliberately passes them and only reads the pushed GL
                // error afterwards.
                if (texelCount > 0 &&
                    static_cast<NSUInteger>(offset) + byteLen <= mtlBuffer.length) {
                    desc.width = texelCount;
                    desc.height = 1;
                    desc.depth = 1;
                    desc.mipmapLevelCount = 1;
                    desc.arrayLength = 1;
                    desc.resourceOptions = mtlBuffer.resourceOptions;
                    desc.usage = MTLTextureUsageShaderRead;
                    id<MTLTexture> tex = [mtlBuffer newTextureWithDescriptor:desc
                                                                      offset:static_cast<NSUInteger>(offset)
                                                                 bytesPerRow:byteLen];
                    // Release any prior metalTexture before retaining the new one.
                    if (object->metalTexture != nullptr) {
                        releaseRetainedMetalObject(object->metalTexture);
                        object->metalTexture = nullptr;
                    }
                    if (tex != nil) {
                        object->metalTexture = transferRetainedMetalObject(tex);
                    }
                }
            }
        }
    }
    return true;
}

bool GLContext::texParameterInteger(GLenum target, GLenum pname, const GLint* params) {
    // GL 4.6 §8.10 target-aware validation runs FIRST — before the
    // "default texture" accommodation — so spec-violating
    // combinations (MS+sampler-pname, BUFFER+sampler-pname, negative
    // base-level) surface the spec-correct error even when no user
    // texture is bound to `target`. Moving this check up is safe for
    // CTS's gluStateReset because its reset sequence never touches
    // the buffer / MS targets with disallowed pnames.
    if (params != nullptr) {
        // (a) Negative BASE_LEVEL / MAX_LEVEL → INVALID_VALUE.
        if ((pname == GL_TEXTURE_BASE_LEVEL || pname == GL_TEXTURE_MAX_LEVEL)
            && params[0] < 0) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        // (a') GL_ARB_texture_filter_anisotropic — MAX_ANISOTROPY
        // must be >= 1. Values below 1 → INVALID_VALUE.
        if (pname == GL_TEXTURE_MAX_ANISOTROPY && params[0] < 1) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        // (b) GL 4.6 §8.10 — for TEXTURE_2D_MULTISAMPLE,
        // TEXTURE_2D_MULTISAMPLE_ARRAY, and TEXTURE_BUFFER, most
        // sampler-state pnames are INVALID_ENUM. Allowed pnames on
        // these targets are the storage-state queries and the
        // "layout" pnames: BASE_LEVEL, MAX_LEVEL, SWIZZLE_*,
        // DEPTH_STENCIL_TEXTURE_MODE. Buffer textures also forbid
        // base/max-level updates (they have no mipmap chain).
        const bool isMSTarget = (target == GL_TEXTURE_2D_MULTISAMPLE ||
                                 target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY);
        const bool isBufferTarget = (target == GL_TEXTURE_BUFFER);
        const bool isSamplerPname = (
            pname == GL_TEXTURE_MIN_FILTER || pname == GL_TEXTURE_MAG_FILTER ||
            pname == GL_TEXTURE_WRAP_S || pname == GL_TEXTURE_WRAP_T ||
            pname == GL_TEXTURE_WRAP_R || pname == GL_TEXTURE_MIN_LOD ||
            pname == GL_TEXTURE_MAX_LOD || pname == GL_TEXTURE_LOD_BIAS ||
            pname == GL_TEXTURE_COMPARE_MODE || pname == GL_TEXTURE_COMPARE_FUNC ||
            pname == GL_TEXTURE_BORDER_COLOR || pname == GL_TEXTURE_MAX_ANISOTROPY);
        if (isMSTarget && isSamplerPname) {
            // GL 4.6 §8.10 table 23.18 — multisample targets reject
            // every sampler-state pname with INVALID_ENUM (not
            // INVALID_OPERATION). CTS
            // `texture_border_clamp.texparameteri_errors` exercises
            // the full (target × pname) matrix and dispatches on the
            // expected error code.
            pushError(GL_INVALID_ENUM);
            return false;
        }
        // Buffer textures reject every sampler-state pname AND the
        // level pnames (they have no mipmap chain). Per GL 4.6 §8.9
        // these are INVALID_ENUM for buffer texture targets.
        if (isBufferTarget &&
            (isSamplerPname || pname == GL_TEXTURE_BASE_LEVEL ||
             pname == GL_TEXTURE_MAX_LEVEL)) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
        // (c) BASE_LEVEL != 0 on MULTISAMPLE → INVALID_OPERATION.
        if (isMSTarget && pname == GL_TEXTURE_BASE_LEVEL && params[0] != 0) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // (d) RECTANGLE-target restrictions.
        if (target == GL_TEXTURE_RECTANGLE) {
            // RECTANGLE BASE_LEVEL must be 0.
            if (pname == GL_TEXTURE_BASE_LEVEL && params[0] != 0) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            // RECTANGLE wrap modes can't be MIRROR_CLAMP_TO_EDGE,
            // MIRRORED_REPEAT, or REPEAT.
            if ((pname == GL_TEXTURE_WRAP_S || pname == GL_TEXTURE_WRAP_T ||
                 pname == GL_TEXTURE_WRAP_R) &&
                (params[0] == GL_REPEAT || params[0] == GL_MIRRORED_REPEAT ||
                 params[0] == GL_MIRROR_CLAMP_TO_EDGE)) {
                pushError(GL_INVALID_ENUM);
                return false;
            }
            // RECTANGLE MIN_FILTER must be NEAREST or LINEAR.
            if (pname == GL_TEXTURE_MIN_FILTER &&
                params[0] != GL_NEAREST && params[0] != GL_LINEAR) {
                pushError(GL_INVALID_ENUM);
                return false;
            }
        }
        // (e) Scalar setter on non-scalar pname → INVALID_ENUM.
        // BORDER_COLOR and SWIZZLE_RGBA take 4 components. The scalar
        // glTexParameteri/f variants (not Iiv/fv) should reject these.
        // This check is done in the wrapper's dim-sensitive path; at
        // the context level we accept both by treating the single-element
        // params pointer as a 4-element array for these pnames — the
        // wrapper's 1-element buffer would then read garbage for indices
        // 1..3. Punt this check to the runtime wrappers — those know
        // whether the scalar or vector entry point was called.
    }

    GLTextureObject* object = impl_->currentTexture(target);
    // OpenGL 4.6 §8.10: when no user texture is bound to `target`, the
    // parameters are applied to the "default texture object" for that
    // target. CTS state reset (gluStateReset.cpp) relies on this: it
    // binds name=0 and then calls texParameteri to reset swizzle/levels.
    // If we generate GL_INVALID_OPERATION here, the reset throws and
    // subsequent state (notably glDepthMask(GL_TRUE)) never runs, causing
    // state bleed between tests. Silently accept the parameter instead.
    if (object == nullptr) {
        return true;
    }
    if (!object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!setTextureParameterInteger(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    // Phase 8X Group 4d follow-up⁷ — the filter/wrap/lod/compare state
    // on the texture now feeds an MTLSamplerState cached on the object
    // (see GLTextureObject.metalSampler). Flip the dirty flag so the
    // next draw rebuilds it from the mutated params. Unconditional
    // because the GL parameter names that affect sampling are a
    // superset of the fields in GLTextureParameters (setTextureParameter
    // already filters out unknown names by returning false above), and
    // swizzle/border changes also require a rebuild via the descriptor.
    object->samplerDirty = true;
    // Swizzle changes invalidate the cached texture view.
    if (pname == GL_TEXTURE_SWIZZLE_R || pname == GL_TEXTURE_SWIZZLE_G ||
        pname == GL_TEXTURE_SWIZZLE_B || pname == GL_TEXTURE_SWIZZLE_A ||
        pname == GL_TEXTURE_SWIZZLE_RGBA) {
        object->swizzleDirty = true;
    }
    return true;
}

bool GLContext::texParameterUnsignedInteger(GLenum target, GLenum pname, const GLuint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLint converted[4] = {
        static_cast<GLint>(params[0]),
        0,
        0,
        0
    };
    if (pname == GL_TEXTURE_BORDER_COLOR || pname == GL_TEXTURE_SWIZZLE_RGBA) {
        converted[1] = static_cast<GLint>(params[1]);
        converted[2] = static_cast<GLint>(params[2]);
        converted[3] = static_cast<GLint>(params[3]);
    }
    return texParameterInteger(target, pname, converted);
}

bool GLContext::texParameterFloat(GLenum target, GLenum pname, const GLfloat* params) {
    // GL 4.6 §8.10 target-aware validation runs FIRST — see
    // texParameterInteger for the rationale.
    if (params != nullptr) {
        if ((pname == GL_TEXTURE_BASE_LEVEL || pname == GL_TEXTURE_MAX_LEVEL)
            && params[0] < 0.0f) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        // GL_ARB_texture_filter_anisotropic — MAX_ANISOTROPY must be
        // >= 1.0; values below 1.0 raise INVALID_VALUE. CTS
        // `texture_filter_anisotropic.queries` exercises the bound.
        if (pname == GL_TEXTURE_MAX_ANISOTROPY && params[0] < 1.0f) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        const bool isMSTarget = (target == GL_TEXTURE_2D_MULTISAMPLE ||
                                 target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY);
        const bool isBufferTarget = (target == GL_TEXTURE_BUFFER);
        const bool isSamplerPname = (
            pname == GL_TEXTURE_MIN_FILTER || pname == GL_TEXTURE_MAG_FILTER ||
            pname == GL_TEXTURE_WRAP_S || pname == GL_TEXTURE_WRAP_T ||
            pname == GL_TEXTURE_WRAP_R || pname == GL_TEXTURE_MIN_LOD ||
            pname == GL_TEXTURE_MAX_LOD || pname == GL_TEXTURE_LOD_BIAS ||
            pname == GL_TEXTURE_COMPARE_MODE || pname == GL_TEXTURE_COMPARE_FUNC ||
            pname == GL_TEXTURE_BORDER_COLOR || pname == GL_TEXTURE_MAX_ANISOTROPY);
        // GL 4.6 §8.10 — MS target + sampler pname is INVALID_OPERATION
        // (core spec wording). Buffer target + sampler/level pname is
        // INVALID_ENUM (buffer textures have no filter/mipmap state).
        if (isMSTarget && isSamplerPname) {
            // GL 4.6 §8.10 table 23.18 — multisample targets reject
            // every sampler-state pname with INVALID_ENUM (not
            // INVALID_OPERATION). CTS
            // `texture_border_clamp.texparameteri_errors` exercises
            // the full (target × pname) matrix and dispatches on the
            // expected error code.
            pushError(GL_INVALID_ENUM);
            return false;
        }
        if (isBufferTarget &&
            (isSamplerPname || pname == GL_TEXTURE_BASE_LEVEL ||
             pname == GL_TEXTURE_MAX_LEVEL)) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
        if (isMSTarget && pname == GL_TEXTURE_BASE_LEVEL && params[0] != 0.0f) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        if (target == GL_TEXTURE_RECTANGLE) {
            if (pname == GL_TEXTURE_BASE_LEVEL && params[0] != 0.0f) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            const GLint asInt = static_cast<GLint>(params[0]);
            if ((pname == GL_TEXTURE_WRAP_S || pname == GL_TEXTURE_WRAP_T ||
                 pname == GL_TEXTURE_WRAP_R) &&
                (asInt == GL_REPEAT || asInt == GL_MIRRORED_REPEAT ||
                 asInt == GL_MIRROR_CLAMP_TO_EDGE)) {
                pushError(GL_INVALID_ENUM);
                return false;
            }
            if (pname == GL_TEXTURE_MIN_FILTER &&
                asInt != GL_NEAREST && asInt != GL_LINEAR) {
                pushError(GL_INVALID_ENUM);
                return false;
            }
        }
    }

    GLTextureObject* object = impl_->currentTexture(target);
    // See comment in texParameterInteger — default-texture params are a
    // no-op to keep CTS state reset from throwing.
    if (object == nullptr) {
        return true;
    }
    if (!object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!setTextureParameterFloat(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    // Phase 8X Group 4d follow-up⁷ — see texParameterInteger for the
    // rationale; float params update the same GLTextureParameters
    // fields (lod clamps, border color) so the cached sampler must
    // rebuild on the next draw.
    object->samplerDirty = true;
    return true;
}

bool GLContext::getTexParameterInteger(GLenum target, GLenum pname, GLint* params) {
    GLTextureObject* object = impl_->currentTexture(target);
    // OpenGL 4.6 §8.11: querying the default texture is valid — return the
    // GL spec's initial parameter values. CTS texture_swizzle.intial_state
    // (note CTS typo "intial") deletes and rebinds the same texture name
    // in a loop, so subsequent iterations bind name=0 and query defaults.
    if (object == nullptr) {
        // Default texture's storage state is all-zero (no storage ever
        // committed), so the storage-property queries below also route
        // through the object-less path.
        switch (pname) {
            case GL_TEXTURE_IMMUTABLE_FORMAT:
            case GL_TEXTURE_IMMUTABLE_LEVELS:
            case GL_TEXTURE_VIEW_MIN_LEVEL:
            case GL_TEXTURE_VIEW_MIN_LAYER:
            case GL_TEXTURE_VIEW_NUM_LEVELS:
            case GL_TEXTURE_VIEW_NUM_LAYERS:
                if (params) *params = 0;
                return true;
            case GL_TEXTURE_TARGET:
                if (params) *params = static_cast<GLint>(target);
                return true;
        }
        const GLTextureParameters defaults;
        if (!getTextureParameterInteger(defaults, pname, params)) {
            pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
            return false;
        }
        return true;
    }
    // GL 4.6 §8.11 storage-state queries live on the texture object
    // (desc.immutable / desc.levels / view-slice range / target).
    // Handle these at the caller — the per-params helper only sees
    // `GLTextureParameters` which is the sampler-state struct.
    switch (pname) {
        case GL_TEXTURE_IMMUTABLE_FORMAT:
            if (params) *params = object->desc.immutable ? GL_TRUE : GL_FALSE;
            return true;
        case GL_TEXTURE_IMMUTABLE_LEVELS:
            if (params) *params = object->desc.levels;
            return true;
        case GL_TEXTURE_VIEW_MIN_LEVEL:
        case GL_TEXTURE_VIEW_MIN_LAYER:
            if (params) *params = 0;
            return true;
        case GL_TEXTURE_VIEW_NUM_LEVELS:
            if (params) *params = object->desc.levels;
            return true;
        case GL_TEXTURE_VIEW_NUM_LAYERS:
            if (params) *params = object->desc.layers > 0 ? object->desc.layers : 1;
            return true;
        case GL_TEXTURE_TARGET:
            if (params) *params = static_cast<GLint>(object->target != 0 ? object->target : target);
            return true;
        // GL 4.6 §8.26.2 / ARB_shader_image_load_store — for textures
        // allocated by the GL (not views), the image-format compat
        // type is BY_SIZE. Views have a different (BY_CLASS) value
        // but we don't currently support texture views, so always
        // report BY_SIZE. CTS shader_image_load_store.basic-api-texParam
        // asserts this for glTexImage2D-allocated textures.
        case GL_IMAGE_FORMAT_COMPATIBILITY_TYPE:
            if (params) *params = static_cast<GLint>(GL_IMAGE_FORMAT_COMPATIBILITY_BY_SIZE);
            return true;
    }
    if (!getTextureParameterInteger(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    return true;
}

bool GLContext::getTexParameterUnsignedInteger(GLenum target, GLenum pname, GLuint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLint values[4] = {};
    if (!getTexParameterInteger(target, pname, values)) {
        return false;
    }
    params[0] = static_cast<GLuint>(values[0]);
    if (pname == GL_TEXTURE_BORDER_COLOR || pname == GL_TEXTURE_SWIZZLE_RGBA) {
        params[1] = static_cast<GLuint>(values[1]);
        params[2] = static_cast<GLuint>(values[2]);
        params[3] = static_cast<GLuint>(values[3]);
    }
    return true;
}

bool GLContext::getTexParameterFloat(GLenum target, GLenum pname, GLfloat* params) {
    // Storage-state / enum-valued pnames (GL 4.6 §8.11) that only
    // the integer getter handles — route through that path and
    // convert to float, instead of letting the per-params float
    // helper's default reinterpret return garbage. CTS
    // shader_image_load_store.basic-api-texParam hits this path.
    switch (pname) {
        case GL_TEXTURE_IMMUTABLE_FORMAT:
        case GL_TEXTURE_IMMUTABLE_LEVELS:
        case GL_TEXTURE_VIEW_MIN_LEVEL:
        case GL_TEXTURE_VIEW_MIN_LAYER:
        case GL_TEXTURE_VIEW_NUM_LEVELS:
        case GL_TEXTURE_VIEW_NUM_LAYERS:
        case GL_TEXTURE_TARGET:
        case GL_IMAGE_FORMAT_COMPATIBILITY_TYPE: {
            GLint ival = 0;
            if (!getTexParameterInteger(target, pname, &ival)) {
                return false;
            }
            if (params) *params = static_cast<GLfloat>(ival);
            return true;
        }
    }
    GLTextureObject* object = impl_->currentTexture(target);
    // Default texture query returns spec defaults (see getTexParameterInteger).
    if (object == nullptr) {
        const GLTextureParameters defaults;
        if (!getTextureParameterFloat(defaults, pname, params)) {
            pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
            return false;
        }
        return true;
    }
    if (!getTextureParameterFloat(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    return true;
}

bool GLContext::generateMipmap(GLenum target) {
    if (!isTextureTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLTextureObject* object = impl_->currentTexture(target);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §8.17: GL_INVALID_OPERATION if target is GL_TEXTURE_CUBE_MAP
    // (or CUBE_MAP_ARRAY) and the texture is not cube complete — i.e. at
    // least one of the six faces is missing a level-0 definition.
    // Checked by KHR-GL46.direct_state_access.textures_generate_mipmap_errors.
    // Level-0 face coverage is the minimum viable check: a stricter read
    // of the spec also requires matching face dimensions and format, but
    // all six faces going through the same single-target bindTexture +
    // same-size texImage2D path in practice means face-count is the
    // signal that distinguishes complete from incomplete.
    const GLenum normalized = Impl::normalizeTextureBindingTarget(target);
    if (normalized == GL_TEXTURE_CUBE_MAP && object->cubeFacesDefined != 0x3F) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!impl_->generateMipmaps(*object)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    return true;
}

bool GLContext::pixelStore(GLenum pname, GLint value) {
    impl_->state->setPixelStore(pname, value);
    return true;
}

bool GLContext::genRenderbuffers(GLsizei count, GLuint* renderbuffers) {
    if (count < 0 || (count > 0 && renderbuffers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        renderbuffers[index] = impl_->objects->renderbuffers().reserveName();
    }
    return true;
}

bool GLContext::deleteRenderbuffers(GLsizei count, const GLuint* renderbuffers) {
    if (count < 0 || (count > 0 && renderbuffers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = renderbuffers[index];
        if (name == 0) {
            continue;
        }
        if (GLRenderbufferObject* object = impl_->objects->renderbuffers().get(name); object != nullptr) {
            impl_->releaseRenderbufferStorage(*object);
        }
        if (impl_->objects->renderbuffers().erase(name)) {
            impl_->state->deleteRenderbufferBinding(name);
            impl_->deleteRenderbufferReferencesFromFramebuffers(name);
            impl_->objects->deferDelete("renderbuffer " + std::to_string(name));
        }
    }
    return true;
}

bool GLContext::isRenderbuffer(GLuint renderbuffer) const {
    const GLRenderbufferObject* object = impl_->objects->renderbuffers().get(renderbuffer);
    return object != nullptr && object->instantiated;
}

bool GLContext::bindRenderbuffer(GLenum target, GLuint renderbuffer) {
    if (target != GL_RENDERBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (renderbuffer != 0) {
        GLRenderbufferObject* object = impl_->objects->renderbuffers().get(renderbuffer);
        if (object == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        object->instantiated = true;
    }
    impl_->state->bindRenderbuffer(renderbuffer);
    return true;
}

bool GLContext::renderbufferStorage(GLenum target, GLenum internalformat, GLsizei width, GLsizei height, GLsizei samples) {
    if (target != GL_RENDERBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (width < 0 || height < 0 || samples < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §9.2.4: INVALID_VALUE if width or height exceeds
    // GL_MAX_RENDERBUFFER_SIZE (matches Metal's texture size ceiling).
    if (impl_->capabilities != nullptr) {
        GLint maxRB = 0;
        impl_->capabilities->queryInteger(GL_MAX_RENDERBUFFER_SIZE, &maxRB);
        if (maxRB > 0 && (width > maxRB || height > maxRB)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    if (!isSupportedRenderbufferFormat(internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // RC-D18: Validate samples against GL_MAX_SAMPLES.
    //
    // GL 4.6 §9.2.4 (and the DSA glNamedRenderbufferStorageMultisample
    // entry) specify GL_INVALID_OPERATION — NOT GL_INVALID_VALUE — when
    // samples > MAX_SAMPLES. This is checked by
    // KHR-GL46.direct_state_access.renderbuffers_storage_multisample_errors.
    // Previously we returned GL_INVALID_VALUE here; the test happened to
    // pass anyway because the `supportsTextureSampleCount:` check below
    // preempted it when our advertised MAX_SAMPLES exceeded what Metal
    // could actually deliver. Correct both the primary check's error code
    // and the preempting behaviour now that MAX_SAMPLES matches Metal.
    //
    // Also normalise samples <= 1 to 0: a single sample is logically
    // non-multisample and avoids Metal rejecting sampleCount == 1 for
    // MTLTextureType2DMultisample on some GPU families.
    if (samples <= 1) {
        samples = 0;
    } else {
        GLint maxSamples = 0;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(GL_MAX_SAMPLES, &maxSamples);
        }
        if (maxSamples > 0 && samples > maxSamples) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // Metal's MTLDevice only supports a subset of sample counts (typically
        // 1, 2, 4, 8). Passing unsupported values (e.g. samples=5) causes
        // MTLTextureDescriptor validation to assert rather than return an
        // error. Validate against the Metal device's reported support to
        // surface the failure as GL_INVALID_OPERATION instead of abort.
        id<MTLDevice> mtlDevice = impl_->device;
        if (mtlDevice != nil && ![mtlDevice supportsTextureSampleCount:static_cast<NSUInteger>(samples)]) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    const GLuint name = impl_->state->boundRenderbuffer();
    GLRenderbufferObject* object = impl_->objects->renderbuffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!impl_->replaceRenderbufferStorage(*object, internalformat, width, height, samples)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

bool GLContext::getRenderbufferParameterInteger(GLenum target, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (target != GL_RENDERBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    const GLuint name = impl_->state->boundRenderbuffer();
    const GLRenderbufferObject* object = impl_->objects->renderbuffers().get(name);
    if (name == 0 || object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    const auto componentSize = [&](GLenum component) -> GLint {
        if (!object->storageDefined) {
            return 0;
        }
        switch (component) {
            case GL_RED:
            case GL_GREEN:
            case GL_BLUE:
                return isColorFormat(object->internalFormat) ? 8 : 0;
            case GL_ALPHA:
                return object->internalFormat == GL_RGBA || object->internalFormat == GL_RGBA8 ? 8 : 0;
            case GL_DEPTH:
                if (object->internalFormat == GL_DEPTH_COMPONENT16) {
                    return 16;
                }
                if (object->internalFormat == GL_DEPTH_COMPONENT24 || object->internalFormat == GL_DEPTH24_STENCIL8) {
                    return 24;
                }
                return isDepthFormat(object->internalFormat) ? 32 : 0;
            case GL_STENCIL:
                return isStencilFormat(object->internalFormat) ? 8 : 0;
            default:
                return 0;
        }
    };

    switch (pname) {
        case GL_RENDERBUFFER_WIDTH:
            params[0] = object->width;
            return true;
        case GL_RENDERBUFFER_HEIGHT:
            params[0] = object->height;
            return true;
        case GL_RENDERBUFFER_INTERNAL_FORMAT:
            params[0] = static_cast<GLint>(object->internalFormat);
            return true;
        case GL_RENDERBUFFER_RED_SIZE:
            params[0] = componentSize(GL_RED);
            return true;
        case GL_RENDERBUFFER_GREEN_SIZE:
            params[0] = componentSize(GL_GREEN);
            return true;
        case GL_RENDERBUFFER_BLUE_SIZE:
            params[0] = componentSize(GL_BLUE);
            return true;
        case GL_RENDERBUFFER_ALPHA_SIZE:
            params[0] = componentSize(GL_ALPHA);
            return true;
        case GL_RENDERBUFFER_DEPTH_SIZE:
            params[0] = componentSize(GL_DEPTH);
            return true;
        case GL_RENDERBUFFER_STENCIL_SIZE:
            params[0] = componentSize(GL_STENCIL);
            return true;
        case GL_RENDERBUFFER_SAMPLES:
            params[0] = object->samples;
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::genFramebuffers(GLsizei count, GLuint* framebuffers) {
    if (count < 0 || (count > 0 && framebuffers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        framebuffers[index] = impl_->objects->framebuffers().reserveName();
    }
    return true;
}

bool GLContext::deleteFramebuffers(GLsizei count, const GLuint* framebuffers) {
    if (count < 0 || (count > 0 && framebuffers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = framebuffers[index];
        if (name == 0) {
            continue;
        }
        if (impl_->objects->framebuffers().erase(name)) {
            impl_->state->deleteFramebufferBindings(name);
            impl_->objects->deferDelete("framebuffer " + std::to_string(name));
        }
    }
    return true;
}

bool GLContext::isFramebuffer(GLuint framebuffer) const {
    const GLFramebufferObject* object = impl_->objects->framebuffers().get(framebuffer);
    return object != nullptr && object->instantiated;
}

bool GLContext::bindFramebuffer(GLenum target, GLuint framebuffer) {
    if (target != GL_FRAMEBUFFER && target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (framebuffer != 0) {
        GLFramebufferObject* object = impl_->objects->framebuffers().get(framebuffer);
        if (object == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        object->instantiated = true;
    }
    if (target == GL_FRAMEBUFFER || target == GL_DRAW_FRAMEBUFFER) {
        impl_->state->bindDrawFramebuffer(framebuffer);
    }
    if (target == GL_FRAMEBUFFER || target == GL_READ_FRAMEBUFFER) {
        impl_->state->bindReadFramebuffer(framebuffer);
    }
    return true;
}

GLenum GLContext::checkFramebufferStatus(GLenum target) const {
    if (target != GL_FRAMEBUFFER && target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_ENUM);
        return 0;
    }
    const GLuint name = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    if (name == 0) {
        return impl_->frameGraph != nullptr && impl_->frameGraph->hasValidAttachments()
            ? GL_FRAMEBUFFER_COMPLETE
            : GL_FRAMEBUFFER_UNDEFINED;
    }
    const GLFramebufferObject* object = impl_->objects->framebuffers().get(name);
    if (object == nullptr || !object->instantiated) {
        // RC-D18: Per the GL spec, glCheckFramebufferStatus only generates
        // GL_INVALID_ENUM (for an invalid target). An incomplete or
        // non-existent framebuffer is signalled via the return value, not
        // via the error queue. Pushing GL_INVALID_OPERATION here was leaking
        // a stale error into subsequent calls.
        return GL_FRAMEBUFFER_UNDEFINED;
    }
    return impl_->framebufferStatus(*object);
}

bool GLContext::framebufferTexture(GLenum target, GLenum attachment, GLenum textarget, GLuint texture, GLint level, GLint layer, bool layered) {
    if (target != GL_FRAMEBUFFER && target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (textarget != 0 && !isTextureTarget(textarget)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §9.2.8: attachment enum shape check split from MAX-range
    // check. Unrecognised attachment → INVALID_ENUM; color-attachment-
    // shaped but >= MAX_COLOR_ATTACHMENTS → INVALID_OPERATION. See
    // framebuffers_texture_attachment_errors.
    if (!isFramebufferAttachmentEnum(attachment)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (isColorAttachmentEnum(attachment) && !isColorAttachment(attachment)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (level < 0 || layer < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint framebufferName = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
    if (framebufferName == 0 || framebuffer == nullptr || !framebuffer->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    if (texture == 0) {
        framebuffer->attachments.erase(attachment);
        return true;
    }

    // Invalid-texture-name error code differs per entry-point variant
    // (GL 4.6 §9.2.8):
    //  - glFramebufferTexture / glNamedFramebufferTexture (layered=true):
    //    INVALID_VALUE when texture is non-zero but not a valid name.
    //  - glFramebufferTextureLayer / glNamedFramebufferTextureLayer
    //    (layered=false here): INVALID_OPERATION for the same case.
    // The not-instantiated case stays INVALID_OPERATION for both.
    const GLTextureObject* textureObject = impl_->objects->textures().get(texture);
    if (textureObject == nullptr) {
        pushError(layered ? GL_INVALID_VALUE : GL_INVALID_OPERATION);
        return false;
    }
    if (!textureObject->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §9.2.8 / §8.18.1 textarget-vs-texture-target validation:
    // glFramebufferTexture2D with a cube-map face textarget
    // (GL_TEXTURE_CUBE_MAP_POSITIVE_X..NEGATIVE_Z) is valid when the
    // texture is a cube map. The face textarget specifies WHICH face
    // to attach; the texture's actual `target` is GL_TEXTURE_CUBE_MAP
    // (NOT the face enum). Sprint 17 Day 2 (CKPT237) [Probe E]:
    // pre-fix, a direct comparison `obj_target != textarget` rejected
    // every cube-map-face attach with GL_INVALID_OPERATION even though
    // the texture WAS a cube map. Surfaced post-Probe-C by
    // KHR-GL46.geometry_shader.layered_rendering.layered_rendering
    // iter-0 (CUBEMAP); pre-existing bug masked by the upstream
    // h2DM-5b crash that Probe C resolved (Item 14 cascade-uncovers
    // pattern).
    {
        const bool isCubeFaceTextarget =
            textarget == GL_TEXTURE_CUBE_MAP_POSITIVE_X ||
            textarget == GL_TEXTURE_CUBE_MAP_NEGATIVE_X ||
            textarget == GL_TEXTURE_CUBE_MAP_POSITIVE_Y ||
            textarget == GL_TEXTURE_CUBE_MAP_NEGATIVE_Y ||
            textarget == GL_TEXTURE_CUBE_MAP_POSITIVE_Z ||
            textarget == GL_TEXTURE_CUBE_MAP_NEGATIVE_Z;
        const bool textargetMatchesObj =
            textureObject->target == textarget ||
            (isCubeFaceTextarget &&
             textureObject->target == GL_TEXTURE_CUBE_MAP);
        if (textarget != 0 && !textargetMatchesObj) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    // GL 4.6 §9.2.8 attachability rules on texture target.
    //
    // - GL_TEXTURE_BUFFER is never attachable to a framebuffer (it's
    //   backed by a buffer object, not image storage). Applies to every
    //   entry point (FramebufferTexture / FramebufferTexture2D /
    //   FramebufferTextureLayer).
    // - The single-layer variant (FramebufferTextureLayer and
    //   NamedFramebufferTextureLayer) additionally rejects non-layered
    //   targets: TEXTURE_RECTANGLE, TEXTURE_2D, TEXTURE_CUBE_MAP, etc.
    //   — layer indexing is only meaningful for 3D / array /
    //   multisample-array.
    // - TEXTURE_2D_MULTISAMPLE is accepted by FramebufferTexture
    //   (layered attachment; sample-level layering) but not by
    //   FramebufferTextureLayer because there's no "layer" concept on
    //   single-sample MS (vs MS array).
    //
    // The Layer variant is identified by `textarget == 0 && !layered`
    // (callers: glFramebufferTextureLayer, glNamedFramebufferTextureLayer).
    // glFramebufferTexture{1,2,3}D pass a non-zero textarget and are
    // already bounded by the textarget-vs-object-target match check
    // above, so they must not be swept up in the layer-attachable check.
    if (textureObject->target == GL_TEXTURE_BUFFER) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const bool isLayerVariant = (!layered && textarget == 0);
    if (isLayerVariant) {
        const bool isLayerAttachableTarget =
            textureObject->target == GL_TEXTURE_3D ||
            textureObject->target == GL_TEXTURE_2D_ARRAY ||
            textureObject->target == GL_TEXTURE_1D_ARRAY ||
            textureObject->target == GL_TEXTURE_CUBE_MAP_ARRAY ||
            textureObject->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
        if (!isLayerAttachableTarget) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    // Spec: GL_INVALID_VALUE if level is greater than the texture's effective max level.
    // Immutable textures pin a hard ceiling at desc.levels - 1; mutable textures fall back
    // on the highest defined level via desc.levels (initialized to 1 by texImage).
    {
        const GLsizei maxLevel = std::max<GLsizei>(textureObject->desc.levels, 1);
        if (level >= maxLevel) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    // GL 4.6 §9.2.8 — `glFramebufferTextureLayer` layer validation.
    // - Negative layer: INVALID_VALUE (handled at layer<0 branch above).
    // - `layer >= GL_MAX_3D_TEXTURE_SIZE` for 3D target: INVALID_VALUE.
    // - `layer >= GL_MAX_ARRAY_TEXTURE_LAYERS` for array target:
    //   INVALID_VALUE.
    // - `layer >= 6 * GL_MAX_CUBE_MAP_TEXTURE_SIZE` for cube-map-array:
    //   INVALID_VALUE.
    // - `layer` within the implementation cap but >= the specific
    //   texture's own layer count: attach succeeds, FB is incomplete.
    //
    // Used to reject `layer >= desc.layers` unconditionally, which
    // flunks CTS `texture_cube_map_array.fbo_incompleteness.*` (expects
    // the attach to succeed so it can verify FB status goes to
    // INCOMPLETE_ATTACHMENT). Now only the implementation-cap check
    // fires — this still catches the DSA `framebuffers_texture_
    // attachment_errors` case (which uses `GL_MAX_ARRAY_TEXTURE_LAYERS`
    // as the invalid layer value).
    if (!layered && impl_->capabilities != nullptr) {
        GLint maxForTarget = 0;
        switch (textureObject->target) {
            case GL_TEXTURE_3D:
                impl_->capabilities->queryInteger(GL_MAX_3D_TEXTURE_SIZE, &maxForTarget);
                break;
            case GL_TEXTURE_2D_ARRAY:
            case GL_TEXTURE_1D_ARRAY:
            case GL_TEXTURE_2D_MULTISAMPLE_ARRAY:
                impl_->capabilities->queryInteger(GL_MAX_ARRAY_TEXTURE_LAYERS, &maxForTarget);
                break;
            case GL_TEXTURE_CUBE_MAP_ARRAY: {
                // GL 4.6 Khronos man page: "layer is larger than
                // MAX_CUBE_MAP_TEXTURE_SIZE - 1". Despite the
                // `6 × MAX` formulation that appears in §3.8.3, the
                // actual CTS DSA test compares against
                // MAX_CUBE_MAP_TEXTURE_SIZE directly (not × 6).
                impl_->capabilities->queryInteger(GL_MAX_CUBE_MAP_TEXTURE_SIZE, &maxForTarget);
                break;
            }
            default:
                break;
        }
        if (maxForTarget > 0 && layer >= maxForTarget) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    if (attachment == GL_DEPTH_ATTACHMENT && !isDepthFormat(textureObject->desc.internalFormat)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (attachment == GL_STENCIL_ATTACHMENT && !isStencilFormat(textureObject->desc.internalFormat)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (isColorAttachment(attachment) && !isColorFormat(textureObject->desc.internalFormat)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    GLFramebufferAttachment stored;
    stored.kind = GLFramebufferAttachment::Kind::Texture;
    stored.object = texture;
    stored.level = level;
    // Sprint 17 Day 2 (CKPT237) [Probe G — cascade Sub-bug A]: when
    // glFramebufferTexture2D is called with a cube-map face textarget
    // (GL_TEXTURE_CUBE_MAP_POSITIVE_X..NEGATIVE_Z), the runtime
    // wrapper passes layer=0 because per GL 4.6 §9.2.8 the cube face
    // is encoded in textarget, not in layer. Pre-fix: stored.layer
    // was set to 0 for ALL cube-face attachments, losing the
    // face-index information; downstream consumers
    // (`resolveFBOColorTarget` populating `fboColorSlices` /
    // `readColorAttachmentPixels` computing `metalSlice`) saw layer=0
    // for every face and routed Metal slice 0 (POSITIVE_X coincidence)
    // for any face. Surfaced post-Probe-E during cascade
    // investigation (Probe F) as the architecturally-clean Sub-bug A
    // localization (Item 14 cascade pattern).
    //
    // Fix: derive stored.layer from textarget when it's a cube-face
    // enum via the existing `cubeFaceIndexForTarget` helper (returns
    // 0..5 for POSITIVE_X..NEGATIVE_Z, -1 otherwise). Non-cube-face
    // call sites fall through to the caller-supplied layer (existing
    // semantics preserved).
    {
        const int cubeFaceIdx = Impl::cubeFaceIndexForTarget(textarget);
        stored.layer = (cubeFaceIdx >= 0)
            ? static_cast<GLint>(cubeFaceIdx)
            : layer;
    }
    stored.textureTarget = textarget == 0 ? textureObject->target : textarget;
    // GL 4.6 §9.4.1 defines GL_FRAMEBUFFER_ATTACHMENT_LAYERED as
    // true only when the attachment was made with FramebufferTexture
    // *and* the texture target is one of the layered kinds
    // (2D_ARRAY / 3D / CUBE_MAP / CUBE_MAP_ARRAY / 2D_MULTISAMPLE_
    // ARRAY / 1D_ARRAY). A FramebufferTexture on a plain 2D texture
    // still attaches the whole texture, but per spec the query
    // returns FALSE because the attachment has a single layer.
    // Previously we stored the raw `layered` flag from the caller
    // (true for FramebufferTexture, false for FramebufferTextureLayer)
    // without consulting the target, so
    // `geometry_shader.layered_fbo.layered_fbo_attachments` saw
    // TRUE for the 2D / MS / depth attachments where the spec says
    // FALSE.
    const bool targetIsLayered =
        textureObject->target == GL_TEXTURE_1D_ARRAY ||
        textureObject->target == GL_TEXTURE_2D_ARRAY ||
        textureObject->target == GL_TEXTURE_2D_MULTISAMPLE_ARRAY ||
        textureObject->target == GL_TEXTURE_3D ||
        textureObject->target == GL_TEXTURE_CUBE_MAP ||
        textureObject->target == GL_TEXTURE_CUBE_MAP_ARRAY;
    stored.layered = layered && targetIsLayered;
    framebuffer->attachments[attachment] = stored;
    // Sprint 17 Day 1 (CKPT236) [A.2 narrow gate]: the binding-time
    // `wasRenderedTo` set originally added by Sprint 16 Day 17
    // (CKPT226) was over-broad — DSA multisample storage tests +
    // texture_barrier tests bind their textures as colour
    // attachments but do NOT render via the viewport-flipped Metal
    // write path, so unconditionally Y-flipping their readback
    // regresses 58 tests (54 DSA + 4 TB). The flag is now set in the
    // draw-encoding path (`encodeEmulatedGsDraw` and siblings) only
    // when `routeViewportIndex == true` — the precise condition
    // under which the GPU writes Y-flipped Metal-storage rows.
    return true;
}

bool GLContext::framebufferRenderbuffer(GLenum target, GLenum attachment, GLenum renderbuffertarget, GLuint renderbuffer) {
    if (target != GL_FRAMEBUFFER && target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (renderbuffertarget != GL_RENDERBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §9.2.8 splits attachment validation into two error classes:
    // an unrecognised enum → INVALID_ENUM; a color-attachment-shaped
    // enum >= MAX_COLOR_ATTACHMENTS → INVALID_OPERATION.
    if (!isFramebufferAttachmentEnum(attachment)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (isColorAttachmentEnum(attachment) && !isColorAttachment(attachment)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLuint framebufferName = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
    if (framebufferName == 0 || framebuffer == nullptr || !framebuffer->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    if (renderbuffer == 0) {
        framebuffer->attachments.erase(attachment);
        return true;
    }

    const GLRenderbufferObject* renderbufferObject = impl_->objects->renderbuffers().get(renderbuffer);
    if (renderbufferObject == nullptr || !renderbufferObject->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (attachment == GL_DEPTH_ATTACHMENT && renderbufferObject->storageDefined && !isDepthFormat(renderbufferObject->internalFormat)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (attachment == GL_STENCIL_ATTACHMENT && renderbufferObject->storageDefined && !isStencilFormat(renderbufferObject->internalFormat)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (isColorAttachment(attachment) && renderbufferObject->storageDefined && !isColorFormat(renderbufferObject->internalFormat)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    GLFramebufferAttachment stored;
    stored.kind = GLFramebufferAttachment::Kind::Renderbuffer;
    stored.object = renderbuffer;
    framebuffer->attachments[attachment] = stored;
    return true;
}

bool GLContext::blitFramebuffer(GLint srcX0, GLint srcY0, GLint srcX1, GLint srcY1, GLint dstX0, GLint dstY0, GLint dstX1, GLint dstY1, GLbitfield mask, GLenum filter) {
    if (filter != GL_NEAREST && filter != GL_LINEAR) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    const GLbitfield kSupportedMask = GL_COLOR_BUFFER_BIT | GL_DEPTH_BUFFER_BIT | GL_STENCIL_BUFFER_BIT;
    if ((mask & ~kSupportedMask) != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!impl_->blitFramebuffer(srcX0, srcY0, srcX1, srcY1, dstX0, dstY0, dstX1, dstY1, mask, filter)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    return true;
}

bool GLContext::getFramebufferAttachmentParameterInteger(GLenum target, GLenum attachment, GLenum pname, GLint* params) const {
    if (params == nullptr) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_VALUE);
        return false;
    }
    if (target != GL_FRAMEBUFFER && target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_ENUM);
        return false;
    }

    const GLuint framebufferName = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();

    // Default FB has its own attachment enum set per GL 4.6 §9.2.3:
    //   {FRONT_LEFT, FRONT_RIGHT, BACK_LEFT, BACK_RIGHT, DEPTH, STENCIL}
    // plus the standard COLOR_ATTACHMENTi / DEPTH_ATTACHMENT /
    // STENCIL_ATTACHMENT / DEPTH_STENCIL_ATTACHMENT subset (COLOR_ATTACHMENT0
    // aliases FRONT_LEFT per §9.2.9). framebuffers_get_attachment_parameters
    // queries the default set.
    const bool isDefaultFbAttachment = (attachment == GL_FRONT_LEFT
        || attachment == GL_FRONT_RIGHT
        || attachment == GL_BACK_LEFT
        || attachment == GL_BACK_RIGHT
        || attachment == GL_DEPTH
        || attachment == GL_STENCIL);
    if (framebufferName == 0) {
        if (!isDefaultFbAttachment && !isFramebufferAttachmentEnum(attachment)) {
            const_cast<GLContext*>(this)->pushError(GL_INVALID_ENUM);
            return false;
        }
        // On the default FB all requested attachments behave as if
        // implementation-provided: return GL_FRAMEBUFFER_DEFAULT for
        // OBJECT_TYPE, 0 for NAME/LEVEL/LAYER, and fixed component sizes
        // and component type for the color/depth/stencil queries so the
        // DSA cross-check against the legacy path agrees.
        const bool isColorAttachment = (attachment == GL_FRONT_LEFT
            || attachment == GL_FRONT_RIGHT
            || attachment == GL_BACK_LEFT
            || attachment == GL_BACK_RIGHT
            || (attachment >= GL_COLOR_ATTACHMENT0 && attachment < GL_COLOR_ATTACHMENT0 + 8));
        const bool isDepthSlot = (attachment == GL_DEPTH || attachment == GL_DEPTH_ATTACHMENT);
        const bool isStencilSlot = (attachment == GL_STENCIL || attachment == GL_STENCIL_ATTACHMENT);
        switch (pname) {
            case GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE:
                params[0] = GL_FRAMEBUFFER_DEFAULT;
                return true;
            case GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME:
            case GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL:
            case GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LAYER:
                params[0] = 0;
                return true;
            case GL_FRAMEBUFFER_ATTACHMENT_RED_SIZE:
            case GL_FRAMEBUFFER_ATTACHMENT_GREEN_SIZE:
            case GL_FRAMEBUFFER_ATTACHMENT_BLUE_SIZE:
                params[0] = isColorAttachment ? 8 : 0;
                return true;
            case GL_FRAMEBUFFER_ATTACHMENT_ALPHA_SIZE:
                params[0] = isColorAttachment ? 8 : 0;
                return true;
            case GL_FRAMEBUFFER_ATTACHMENT_DEPTH_SIZE:
                params[0] = isDepthSlot ? 24 : 0;
                return true;
            case GL_FRAMEBUFFER_ATTACHMENT_STENCIL_SIZE:
                params[0] = isStencilSlot ? 8 : 0;
                return true;
            case GL_FRAMEBUFFER_ATTACHMENT_COMPONENT_TYPE:
                if (isColorAttachment) { params[0] = GL_UNSIGNED_NORMALIZED; return true; }
                if (isDepthSlot)       { params[0] = GL_UNSIGNED_NORMALIZED; return true; }
                if (isStencilSlot)     { params[0] = GL_UNSIGNED_INT;        return true; }
                params[0] = GL_NONE;
                return true;
            case GL_FRAMEBUFFER_ATTACHMENT_COLOR_ENCODING:
                params[0] = isColorAttachment ? GL_LINEAR : GL_NONE;
                return true;
            default:
                const_cast<GLContext*>(this)->pushError(GL_INVALID_ENUM);
                return false;
        }
    }

    // User FB path. Attachment enum validation splits shape/range so
    // COLOR_ATTACHMENTm with m >= MAX_COLOR_ATTACHMENTS returns
    // INVALID_OPERATION rather than INVALID_ENUM (matches
    // framebuffers_get_attachment_parameter_errors).
    if (!isFramebufferAttachmentEnum(attachment)) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_ENUM);
        return false;
    }
    if (isColorAttachmentEnum(attachment) && !isColorAttachment(attachment)) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_OPERATION);
        return false;
    }

    const GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
    if (framebuffer == nullptr || !framebuffer->instantiated) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_OPERATION);
        return false;
    }
    auto sameFramebufferImage = [](const GLFramebufferAttachment& a,
                                   const GLFramebufferAttachment& b) {
        if (a.kind != b.kind || a.object != b.object) return false;
        if (a.kind == GLFramebufferAttachment::Kind::Texture) {
            return a.level == b.level &&
                   a.layer == b.layer &&
                   a.textureTarget == b.textureTarget &&
                   a.layered == b.layered;
        }
        return true;
    };

    GLFramebufferAttachment attachmentState;
    if (attachment == GL_DEPTH_STENCIL_ATTACHMENT) {
        const auto direct = framebuffer->attachments.find(GL_DEPTH_STENCIL_ATTACHMENT);
        if (direct != framebuffer->attachments.end()) {
            attachmentState = direct->second;
        } else {
            const auto depthIt = framebuffer->attachments.find(GL_DEPTH_ATTACHMENT);
            const auto stencilIt = framebuffer->attachments.find(GL_STENCIL_ATTACHMENT);
            const bool haveDepth = depthIt != framebuffer->attachments.end()
                && depthIt->second.kind != GLFramebufferAttachment::Kind::None
                && depthIt->second.object != 0;
            const bool haveStencil = stencilIt != framebuffer->attachments.end()
                && stencilIt->second.kind != GLFramebufferAttachment::Kind::None
                && stencilIt->second.object != 0;
            if (haveDepth && haveStencil) {
                if (!sameFramebufferImage(depthIt->second, stencilIt->second)) {
                    const_cast<GLContext*>(this)->pushError(GL_INVALID_OPERATION);
                    return false;
                }
                attachmentState = depthIt->second;
            }
        }
    } else {
        const auto found = framebuffer->attachments.find(attachment);
        attachmentState = found == framebuffer->attachments.end()
            ? GLFramebufferAttachment{} : found->second;
    }
    const auto attachmentInfo = impl_->framebufferAttachmentInfo(attachmentState);

    // GL 4.6 §9.2.3: when the attachment object type is GL_NONE, only
    // FRAMEBUFFER_ATTACHMENT_OBJECT_NAME and
    // FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE are valid pnames. Anything
    // else → INVALID_OPERATION. Additionally
    // FRAMEBUFFER_ATTACHMENT_COMPONENT_TYPE with
    // DEPTH_STENCIL_ATTACHMENT → INVALID_OPERATION (a depth-stencil
    // attachment has two component types, so asking for one makes no
    // sense).
    const bool objectIsNone = (attachmentState.kind == GLFramebufferAttachment::Kind::None);
    if (objectIsNone
        && pname != GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME
        && pname != GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (pname == GL_FRAMEBUFFER_ATTACHMENT_COMPONENT_TYPE
        && attachment == GL_DEPTH_STENCIL_ATTACHMENT) {
        const_cast<GLContext*>(this)->pushError(GL_INVALID_OPERATION);
        return false;
    }

    switch (pname) {
        case GL_FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE:
            params[0] = attachmentState.kind == GLFramebufferAttachment::Kind::Texture
                ? GL_TEXTURE
                : (attachmentState.kind == GLFramebufferAttachment::Kind::Renderbuffer ? GL_RENDERBUFFER : GL_NONE);
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_OBJECT_NAME:
            params[0] = static_cast<GLint>(attachmentState.object);
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL:
        case GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LAYER:
        case GL_FRAMEBUFFER_ATTACHMENT_LAYERED:
            // GL 4.6 §9.2.3: these pnames are only valid when
            // FRAMEBUFFER_ATTACHMENT_OBJECT_TYPE is GL_TEXTURE. For a
            // renderbuffer attachment they generate INVALID_ENUM.
            // (The ObjectType==None case is already handled above.)
            if (attachmentState.kind != GLFramebufferAttachment::Kind::Texture) {
                const_cast<GLContext*>(this)->pushError(GL_INVALID_ENUM);
                return false;
            }
            if (pname == GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LEVEL) {
                params[0] = attachmentState.level;
            } else if (pname == GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_LAYER) {
                params[0] = attachmentState.layer;
            } else {
                params[0] = attachmentState.layered ? GL_TRUE : GL_FALSE;
            }
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_RED_SIZE:
            params[0] = attachmentInfo.complete && isColorFormat(attachmentInfo.internalFormat) ? 8 : 0;
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_GREEN_SIZE:
            params[0] = attachmentInfo.complete && isColorFormat(attachmentInfo.internalFormat) ? 8 : 0;
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_BLUE_SIZE:
            params[0] = attachmentInfo.complete && isColorFormat(attachmentInfo.internalFormat) ? 8 : 0;
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_ALPHA_SIZE:
            params[0] = attachmentInfo.complete && (attachmentInfo.internalFormat == GL_RGBA || attachmentInfo.internalFormat == GL_RGBA8) ? 8 : 0;
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_DEPTH_SIZE:
            if (!attachmentInfo.complete || !isDepthFormat(attachmentInfo.internalFormat)) {
                params[0] = 0;
            } else if (attachmentInfo.internalFormat == GL_DEPTH_COMPONENT16) {
                params[0] = 16;
            } else if (attachmentInfo.internalFormat == GL_DEPTH_COMPONENT32 ||
                       attachmentInfo.internalFormat == GL_DEPTH_COMPONENT32F ||
                       attachmentInfo.internalFormat == GL_DEPTH32F_STENCIL8) {
                params[0] = 32;
            } else {
                params[0] = 24;
            }
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_STENCIL_SIZE:
            params[0] = attachmentInfo.complete && isStencilFormat(attachmentInfo.internalFormat) ? 8 : 0;
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_COMPONENT_TYPE:
            // GL 4.6 §9.2.3: the component type of the color/depth data.
            // For UNORM color formats and fixed-point depth the answer is
            // GL_UNSIGNED_NORMALIZED; stencil is GL_UNSIGNED_INT. CTS
            // framebuffers_get_attachment_parameters cross-checks legacy
            // vs DSA and expects matching values on user FBOs.
            if (!attachmentInfo.complete) {
                params[0] = GL_NONE;
            } else if (attachmentInfo.internalFormat == GL_DEPTH_COMPONENT32F ||
                       attachmentInfo.internalFormat == GL_DEPTH32F_STENCIL8) {
                params[0] = GL_FLOAT;
            } else if (isStencilFormat(attachmentInfo.internalFormat)
                       && !isDepthFormat(attachmentInfo.internalFormat)
                       && !isColorFormat(attachmentInfo.internalFormat)) {
                params[0] = GL_UNSIGNED_INT;
            } else {
                params[0] = GL_UNSIGNED_NORMALIZED;
            }
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_COLOR_ENCODING:
            // Only meaningful for color attachments; GL_LINEAR for plain
            // RGBA8 / RGBA16 / …, GL_SRGB for *_SRGB_* formats, GL_NONE
            // otherwise.
            if (!attachmentInfo.complete) {
                params[0] = GL_NONE;
            } else if (!isColorFormat(attachmentInfo.internalFormat)) {
                params[0] = GL_LINEAR;
            } else {
                const GLenum fmt = attachmentInfo.internalFormat;
                params[0] = (fmt == GL_SRGB || fmt == GL_SRGB8
                             || fmt == GL_SRGB_ALPHA || fmt == GL_SRGB8_ALPHA8
                             || fmt == GL_COMPRESSED_SRGB || fmt == GL_COMPRESSED_SRGB_ALPHA)
                             ? GL_SRGB : GL_LINEAR;
            }
            return true;
        case GL_FRAMEBUFFER_ATTACHMENT_TEXTURE_CUBE_MAP_FACE:
            // Not tracked on the attachment state yet. Default to 0 so
            // the query doesn't raise INVALID_ENUM for implementations
            // that attached a non-cube texture (spec allows 0 there).
            params[0] = 0;
            return true;
        default:
            const_cast<GLContext*>(this)->pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::drawBuffer(GLenum buffer) {
    // glDrawBuffer (singular) has looser rules than glDrawBuffers: on
    // the default framebuffer it also accepts the combined tokens
    // (FRONT, BACK, LEFT, RIGHT, FRONT_AND_BACK). Route through the
    // single-buffer validator rather than forwarding to the plural
    // form which would reject combined tokens.
    const GLuint framebufferName = impl_->state->boundDrawFramebuffer();
    if (framebufferName == 0) {
        // Default framebuffer — accepts every §17.4.1 single-target
        // token including the combined ones.
        if (!isDefaultFramebufferBuffer(buffer)) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
        return impl_->state->setDrawBuffers(1, &buffer);
    }
    GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
    if (framebuffer == nullptr || !framebuffer->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // User FBO — only NONE and COLOR_ATTACHMENTi tokens accepted.
    // Combined tokens are a recognized enum shape but invalid here.
    if (buffer == GL_NONE) {
        framebuffer->drawBuffers.fill(GL_NONE);
        framebuffer->drawBuffers[0] = GL_NONE;
        return true;
    }
    if (isColorAttachmentEnum(buffer)) {
        if (!isColorAttachment(buffer)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        framebuffer->drawBuffers.fill(GL_NONE);
        framebuffer->drawBuffers[0] = buffer;
        return true;
    }
    // `buffer` is a recognized default-FB token (FRONT, BACK, etc.) —
    // not legal on a user FBO per §17.4.1.
    if (isDefaultFramebufferBuffer(buffer)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    pushError(GL_INVALID_ENUM);
    return false;
}

bool GLContext::drawBuffers(GLsizei count, const GLenum* buffers) {
    if (count < 0 || count > 8 || (count > 0 && buffers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint framebufferName = impl_->state->boundDrawFramebuffer();
    if (framebufferName == 0) {
        // Default framebuffer, plural variant. Per GL 4.6 §17.4.1:
        //  - Valid in bufs: NONE, FRONT_LEFT/RIGHT, BACK_LEFT/RIGHT,
        //    BACK (must be alone).
        //  - COLOR_ATTACHMENTi on default framebuffer → INVALID_OPERATION
        //    (recognised enum shape but wrong FB kind).
        //  - FRONT, FRONT_AND_BACK, LEFT, RIGHT, etc. → INVALID_ENUM
        //    (accepted on singular glDrawBuffer but not the plural).
        //  - Anything else → INVALID_ENUM.
        for (GLsizei i = 0; i < count; ++i) {
            const GLenum b = buffers[i];
            const bool isSingleDefault = (b == GL_NONE || b == GL_FRONT_LEFT ||
                b == GL_FRONT_RIGHT || b == GL_BACK_LEFT || b == GL_BACK_RIGHT ||
                b == GL_BACK);
            if (!isSingleDefault) {
                if (isColorAttachmentEnum(b)) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
                pushError(GL_INVALID_ENUM);
                return false;
            }
            // BACK, if present, must be the sole entry.
            if (b == GL_BACK && count != 1) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
        }
        // Duplicate check: no non-NONE token may appear twice.
        for (GLsizei i = 0; i < count; ++i) {
            if (buffers[i] == GL_NONE) continue;
            for (GLsizei j = i + 1; j < count; ++j) {
                if (buffers[j] == buffers[i]) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
            }
        }
        return impl_->state->setDrawBuffers(count, buffers);
    }

    GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
    if (framebuffer == nullptr || !framebuffer->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // User FBO (plural). CTS distinguishes two classes of invalid
    // tokens per GL 4.6 §17.4.1's prose and examples:
    //   - Combined tokens: FRONT, LEFT, RIGHT, FRONT_AND_BACK — never
    //     valid in the plural form on ANY framebuffer → INVALID_ENUM.
    //   - Single-target default-FB tokens: FRONT_LEFT, FRONT_RIGHT,
    //     BACK_LEFT, BACK_RIGHT, BACK — valid for default FB but wrong
    //     for a user FBO → INVALID_OPERATION.
    //   - COLOR_ATTACHMENTi with i >= MAX → INVALID_OPERATION.
    //   - Unrecognised enum → INVALID_OPERATION (matches the test's
    //     "anything other than NONE or COLOR_ATTACHMENTn" clause).
    auto isCombinedDefaultFBToken = [](GLenum b) {
        return b == GL_FRONT || b == GL_LEFT || b == GL_RIGHT ||
               b == GL_FRONT_AND_BACK;
    };
    auto isSingleDefaultFBToken = [](GLenum b) {
        return b == GL_FRONT_LEFT || b == GL_FRONT_RIGHT ||
               b == GL_BACK_LEFT  || b == GL_BACK_RIGHT  || b == GL_BACK;
    };
    for (GLsizei i = 0; i < count; ++i) {
        const GLenum b = buffers[i];
        if (b == GL_NONE) continue;
        if (isColorAttachmentEnum(b)) {
            if (!isColorAttachment(b)) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            continue;
        }
        if (isCombinedDefaultFBToken(b)) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
        if (isSingleDefaultFBToken(b)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // Truly unrecognised enum (e.g. GL_TRUE = 1, random garbage):
        // INVALID_ENUM per §17.4.1's "not an accepted value".
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // Duplicate check.
    for (GLsizei i = 0; i < count; ++i) {
        if (buffers[i] == GL_NONE) continue;
        for (GLsizei j = i + 1; j < count; ++j) {
            if (buffers[j] == buffers[i]) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
        }
    }
    framebuffer->drawBuffers.fill(GL_NONE);
    for (GLsizei index = 0; index < count; ++index) {
        framebuffer->drawBuffers[static_cast<std::size_t>(index)] = buffers[index];
    }
    return true;
}

bool GLContext::readBuffer(GLenum buffer) {
    const GLuint framebufferName = impl_->state->boundReadFramebuffer();
    if (framebufferName == 0) {
        // Default framebuffer: accepts §17.4.1 default-FB tokens plus
        // NONE. Anything else — including COLOR_ATTACHMENTi — is
        // INVALID_OPERATION when the enum is recognised but
        // inappropriate for the target, INVALID_ENUM when unrecognised.
        if (isDefaultFramebufferBuffer(buffer)) {
            return impl_->state->setReadBuffer(buffer);
        }
        if (isColorAttachmentEnum(buffer)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLFramebufferObject* framebuffer = impl_->objects->framebuffers().get(framebufferName);
    if (framebuffer == nullptr || !framebuffer->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // User FBO: NONE or COLOR_ATTACHMENTi (where i < MAX).
    if (buffer == GL_NONE) {
        framebuffer->readBuffer = buffer;
        return true;
    }
    if (isColorAttachmentEnum(buffer)) {
        if (!isColorAttachment(buffer)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        framebuffer->readBuffer = buffer;
        return true;
    }
    if (isDefaultFramebufferBuffer(buffer)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    pushError(GL_INVALID_ENUM);
    return false;
}

bool GLContext::genSamplers(GLsizei count, GLuint* samplers) {
    if (count < 0 || (count > 0 && samplers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = impl_->objects->samplers().reserveName();
        samplers[index] = name;
        if (GLSamplerObject* object = impl_->objects->samplers().get(name); object != nullptr) {
            object->instantiated = true;
            (void)impl_->rebuildSamplerState(*object);
        }
    }
    return true;
}

bool GLContext::deleteSamplers(GLsizei count, const GLuint* samplers) {
    if (count < 0 || (count > 0 && samplers == nullptr)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    for (GLsizei index = 0; index < count; ++index) {
        const GLuint name = samplers[index];
        if (name == 0) {
            continue;
        }
        if (GLSamplerObject* object = impl_->objects->samplers().get(name); object != nullptr) {
            impl_->releaseSamplerState(*object);
        }
        if (impl_->objects->samplers().erase(name)) {
            impl_->state->deleteSamplerBindings(name);
            impl_->objects->deferDelete("sampler " + std::to_string(name));
        }
    }
    return true;
}

bool GLContext::isSampler(GLuint sampler) const {
    const GLSamplerObject* object = impl_->objects->samplers().get(sampler);
    return object != nullptr && object->instantiated;
}

bool GLContext::bindSampler(GLuint unit, GLuint sampler) {
    // Must match GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS (80) in GLCapabilities.
    if (unit >= 80) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (sampler != 0 && !isSampler(sampler)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    impl_->state->bindSampler(unit, sampler);
    return true;
}

bool GLContext::samplerParameterInteger(GLuint sampler, GLenum pname, const GLint* params) {
    GLSamplerObject* object = impl_->objects->samplers().get(sampler);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!setTextureParameterInteger(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    object->dirty = true;
    if (!impl_->rebuildSamplerState(*object)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

bool GLContext::samplerParameterUnsignedInteger(GLuint sampler, GLenum pname, const GLuint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLint converted[4] = {
        static_cast<GLint>(params[0]),
        0,
        0,
        0
    };
    if (pname == GL_TEXTURE_BORDER_COLOR || pname == GL_TEXTURE_SWIZZLE_RGBA) {
        converted[1] = static_cast<GLint>(params[1]);
        converted[2] = static_cast<GLint>(params[2]);
        converted[3] = static_cast<GLint>(params[3]);
    }
    return samplerParameterInteger(sampler, pname, converted);
}

bool GLContext::samplerParameterFloat(GLuint sampler, GLenum pname, const GLfloat* params) {
    GLSamplerObject* object = impl_->objects->samplers().get(sampler);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!setTextureParameterFloat(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    object->dirty = true;
    if (!impl_->rebuildSamplerState(*object)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    return true;
}

bool GLContext::getSamplerParameterInteger(GLuint sampler, GLenum pname, GLint* params) {
    const GLSamplerObject* object = impl_->objects->samplers().get(sampler);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!getTextureParameterInteger(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    return true;
}

bool GLContext::getSamplerParameterUnsignedInteger(GLuint sampler, GLenum pname, GLuint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLint values[4] = {};
    if (!getSamplerParameterInteger(sampler, pname, values)) {
        return false;
    }
    params[0] = static_cast<GLuint>(values[0]);
    if (pname == GL_TEXTURE_BORDER_COLOR || pname == GL_TEXTURE_SWIZZLE_RGBA) {
        params[1] = static_cast<GLuint>(values[1]);
        params[2] = static_cast<GLuint>(values[2]);
        params[3] = static_cast<GLuint>(values[3]);
    }
    return true;
}

bool GLContext::getSamplerParameterFloat(GLuint sampler, GLenum pname, GLfloat* params) {
    const GLSamplerObject* object = impl_->objects->samplers().get(sampler);
    if (object == nullptr || !object->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (!getTextureParameterFloat(object->params, pname, params)) {
        pushError(params == nullptr ? GL_INVALID_VALUE : GL_INVALID_ENUM);
        return false;
    }
    return true;
}

namespace {

// Strip a source-location file path down to its basename for the
// `<internal@<file>:<line>>` ring-buffer tag emitted by pushError() when no
// explicit functionName was supplied. The full path (e.g. "<redacted-other-user-home>/
// appgl-runtime/src/context/GLContext.mm") is unhelpful in the BAR-side log
// — only the trailing filename matters for naming the call site, and a path
// prefix would also leak the local build environment into the diagnostic
// stream.
std::string sourceLocationBasename(const char* path) {
    if (path == nullptr) {
        return std::string("?");
    }
    std::string_view view(path);
    const std::size_t slash = view.find_last_of('/');
    if (slash != std::string_view::npos) {
        view.remove_prefix(slash + 1);
    }
    return std::string(view);
}

// Translate a raw GL error enum into its canonical spec name. Used as a
// fallback message when pushError() is invoked from a deep call site that
// doesn't supply its own description — without this, ring-buffer records
// would land as `{function: "<internal@GLContext.mm:1234>", errorEnum: 1282,
// message: ""}` and external diagnostics tooling has nothing to render. With
// it, the same record reads `{... message: "GL_INVALID_OPERATION (raised
// internally; tag is the source location)"}` so the message is at least the
// spec name even when the call site doesn't supply richer text.
const char* glErrorEnumName(GLenum error) {
    switch (error) {
        case GL_NO_ERROR:                       return "GL_NO_ERROR";
        case GL_INVALID_ENUM:                   return "GL_INVALID_ENUM";
        case GL_INVALID_VALUE:                  return "GL_INVALID_VALUE";
        case GL_INVALID_OPERATION:              return "GL_INVALID_OPERATION";
        case GL_INVALID_FRAMEBUFFER_OPERATION:  return "GL_INVALID_FRAMEBUFFER_OPERATION";
        case GL_OUT_OF_MEMORY:                  return "GL_OUT_OF_MEMORY";
        case GL_STACK_UNDERFLOW:                return "GL_STACK_UNDERFLOW";
        case GL_STACK_OVERFLOW:                 return "GL_STACK_OVERFLOW";
        default:                                return nullptr;
    }
}

std::string defaultErrorMessage(GLenum error, bool internalCallSite) {
    const char* name = glErrorEnumName(error);
    std::string base;
    if (name != nullptr) {
        base.assign(name);
    } else {
        char buf[32];
        std::snprintf(buf, sizeof(buf), "GLenum 0x%04X", static_cast<unsigned>(error));
        base.assign(buf);
    }
    if (internalCallSite) {
        base.append(" (raised internally; tag is the source location)");
    }
    return base;
}

// ─────────────────────────────────────────────────────────────────────────────
// Phase 8X Group 4d follow-up³ — translated-draw fall-through instrumentation.
//
// The translated-draw path in glDrawArrays / glDrawArraysInstanced /
// glDrawElements has a chain of guards that can silently fall through to the
// solid-color fallback (or to a no-op for the instanced path). For BAR's
// select-menu corpus we observe `pipelineCache: {hits:0, misses:0}` despite
// `hasTranslatedPipeline=1`, which means encodeTranslatedDraw is never being
// reached — one of these guards is firing for every draw without naming
// itself in any log surface.
//
// `reportTranslatedFallbackOnce` emits a single NSLog line per (program, gate)
// pair, gated by a per-program bitmask in GLProgramObject. The shape of the
// line matches BAR's grep-aggregation request:
//
//   [GL] drawArrays-fallback: program=5 gate=shadowBytes-empty vao=3 vbo=7 attrCount=2
//
// `program` and `gate` are the two grep-by fields. `vao`, `vbo`, and
// `attrCount` are bonus context for cross-referencing against the
// objectStore dump in the live diagnostic JSON.
//
// The bitmask is per-program and per-gate, so a real game scene that pulls
// in 200 distinct shader programs with 5 fall-through gates between them
// produces at most 1000 log lines — actually far fewer in practice, because
// the same gate is usually firing for every draw of the same program.
// ─────────────────────────────────────────────────────────────────────────────

enum class TranslatedFallbackGate : std::uint32_t {
    EmptyAttributes  = 1u << 0,  // VAO has no enabled attributes
    NullVBO          = 1u << 1,  // attribute 0's buffer name doesn't resolve
    ShadowBytesEmpty = 1u << 2,  // VBO has no CPU-side shadow (likely glBufferStorage)
    OffsetOverflow   = 1u << 3,  // first vertex offset overruns the shadow
    EncodeFailed     = 1u << 4,  // encodeTranslatedDraw returned false
};

const char* translatedFallbackGateName(TranslatedFallbackGate gate) {
    switch (gate) {
        case TranslatedFallbackGate::EmptyAttributes:  return "empty-attributes";
        case TranslatedFallbackGate::NullVBO:          return "null-vbo";
        case TranslatedFallbackGate::ShadowBytesEmpty: return "shadowBytes-empty";
        case TranslatedFallbackGate::OffsetOverflow:   return "offset-overflow";
        case TranslatedFallbackGate::EncodeFailed:     return "encode-failed";
    }
    return "unknown";
}

// Returns true when the bit was newly set (i.e., the NSLog actually fired
// on this call). Callers chain the diagnostic-ring push on the same edge so
// the heavier "pipeline-build" ShaderTranslationRecord write happens once
// per (program, gate) pair too, rather than every draw.
bool reportTranslatedFallbackOnce(GLProgramObject* program,
                                  GLuint programName,
                                  TranslatedFallbackGate gate,
                                  const char* siteName,
                                  GLuint vaoName,
                                  std::size_t attrCount,
                                  GLuint vboName,
                                  std::size_t shadowBytesSize) {
    if (program == nullptr || siteName == nullptr) {
        return false;
    }
    const std::uint32_t bit = static_cast<std::uint32_t>(gate);
    if ((program->translatedFallbackGatesReported & bit) != 0) {
        return false;
    }
    program->translatedFallbackGatesReported |= bit;
    APPGL_LOG(DRAW, @"[GL] %s-fallback: program=%u gate=%s vao=%u vbo=%u attrCount=%zu shadowBytes=%zu",
          siteName,
          static_cast<unsigned>(programName),
          translatedFallbackGateName(gate),
          static_cast<unsigned>(vaoName),
          static_cast<unsigned>(vboName),
          attrCount,
          shadowBytesSize);
    return true;
}

// Phase 8X Group 4d follow-up⁴ — record a pipeline-build failure in the
// shader-translation diagnostic ring so BAR-side tooling can see Metal's
// rejection text in the same JSON channel it already parses for compile
// and link records.
//
// `errorText` carries the stage tag + NSError description that
// MetalFrameGraph::encodeTranslatedDraw populated into
// TranslatedDrawInfo::pipelineBuildErrorOut on the failing path. The
// stage tag is the first colon-separated token (e.g. "vertex-library:
// program_source: error: ..."), so BAR can grep-aggregate by stage even
// though the record carries the full text.
//
// Called from the EncodeFailed branch in each draw entry point AFTER
// reportTranslatedFallbackOnce has already gated the NSLog. We use a
// SEPARATE per-program bit because the diagnostic-ring record is a
// heavier-weight signal than the NSLog and we don't want to lose it in a
// world where the gate bit was set by a non-failure code path. In
// practice both bits track each other exactly today — the separation is
// future-proofing.
void recordPipelineBuildFailureOnce(GLProgramObject* program,
                                    GLuint programName,
                                    const std::string& errorText) {
    if (program == nullptr || errorText.empty()) {
        return;
    }
    // Reuse the EncodeFailed bit as the gate. The reportTranslatedFallbackOnce
    // call above sets it; this function only fires when that gate just
    // transitioned from clear to set on this draw. Concretely: if the
    // caller invokes both helpers in order on the same draw, the NSLog
    // fires once and the diagnostic record fires once. Subsequent draws
    // that hit the same failure path skip both, because the bit is already
    // set. (We don't need a separate guard here — the reportTranslated
    // call above already set the bit when the diagnostic record was
    // worth writing.)
    //
    // Phase 8X Group 4d follow-up⁵ — §6b: populate `mslPreview` with the
    // failing stage's MSL (up to 1024 bytes) so BAR can inspect the
    // actual `main0_out` / `main0_in` struct definitions inline in the
    // diagnostic ring without having to dump intermediate files. For
    // `pipeline-state` failures (where both stages are involved in the
    // varying-mismatch verdict) we pack the vertex MSL first and the
    // fragment MSL second, separated by a marker. The 1024-byte cap is
    // big enough to include the full `main0_out`/`main0_in` structs plus
    // the start of `main0()`, which is where varyings are usually
    // declared in SPIRV-Cross's emit order.
    constexpr std::size_t kMslPreviewBudget = 1024;
    auto previewOf = [](const std::string& msl) -> std::string {
        if (msl.size() <= kMslPreviewBudget) {
            return msl;
        }
        return msl.substr(0, kMslPreviewBudget) + "\n…[truncated]";
    };

    std::string preview;
    // Stage tag is the first token of errorText, separated by ": ".
    // (See the recordBuildFailure lambda in MetalFrameGraph.mm.)
    if (errorText.rfind("vertex-library", 0) == 0 ||
        errorText.rfind("vertex-function", 0) == 0) {
        preview = previewOf(program->vertexMSL);
    } else if (errorText.rfind("fragment-library", 0) == 0 ||
               errorText.rfind("fragment-function", 0) == 0) {
        preview = previewOf(program->fragmentMSL);
    } else if (errorText.rfind("pipeline-state", 0) == 0) {
        // Both stages are implicated in the varying interface match;
        // pack each into half the budget so BAR can see both `main0_out`
        // (vertex) and `main0_in` (fragment) inline.
        constexpr std::size_t kHalf = kMslPreviewBudget / 2;
        const std::string& vs = program->vertexMSL;
        const std::string& fs = program->fragmentMSL;
        preview = "// === vertex ===\n";
        preview += (vs.size() <= kHalf) ? vs : (vs.substr(0, kHalf) + "\n…[truncated]\n");
        preview += "\n// === fragment ===\n";
        preview += (fs.size() <= kHalf) ? fs : (fs.substr(0, kHalf) + "\n…[truncated]");
    }

    Runtime::ShaderTranslationRecord record;
    record.id = "program-" + std::to_string(programName);
    record.stage = "pipeline-build";
    record.sourceHash = program->vertexSourceHash;  // primary stage for raster programs
    record.vertexSourceHash = program->vertexSourceHash;
    record.fragmentSourceHash = program->fragmentSourceHash;
    record.glslangLog = errorText;
    record.mslPreview = std::move(preview);
    record.success = false;
    Runtime::shared().recordShaderTranslation(std::move(record));
}

}  // namespace

void GLContext::pushError(GLenum error,
                          std::string_view functionName,
                          std::string_view message,
                          std::source_location loc) {
    // Mirror the raised error into BOTH surfaces:
    //  * The per-context enum queue drained by glGetError() — the
    //    engine-facing GL contract requires a FIFO of pure enums.
    //  * The runtime ring buffer drained by appglLiveDiagnosticsJSON —
    //    external tooling wants the function name and human-readable
    //    message, which the raw enum queue doesn't carry.
    // Call sites that don't know the function name (e.g. deep inside
    // GLContext.mm) leave functionName empty; we then synthesise a tag
    // from std::source_location captured at the call site, formatted as
    //   `<internal@<basename>:<line>>`
    // so external diagnostics tooling can name the call site directly
    // (Phase 8X Group 4d follow-up §3a — BAR's ask for a file:line
    // breadcrumb on the steady-state untagged GL_INVALID_ENUM entries).
    // When the message is also empty, default-fill it with the canonical
    // GL spec name for the enum so external tooling has at least the
    // error class to render — empty-message records dropped on the floor
    // were unactionable for downstream consumers (BAR worker feedback,
    // Phase 8X Group 4c handoff §2c).
    // Cap the error queue small enough that CTS's bounded drain loops
    // can always clear it. gluStateReset (framework/opengl/
    // gluStateReset.cpp:38) uses MAX_ERROR_COUNT = 10 iterations and
    // aborts the whole sweep if the queue still has entries after
    // that. An unbounded queue plus tests that push many errors per
    // test (packed_pixels format cascade, cull_distance pipeline-
    // build, DSA texture_buffer_* sequence) will always overflow.
    //
    // 4 is a comfortable compromise: enough to see a handful of
    // transient errors from a single bad call site, small enough to
    // leave 6 drain iterations as headroom under CTS's bound. The GL
    // contract only guarantees glGetError returns *an* error when one
    // is pending; there's no FIFO depth guarantee.
    if (impl_->errors.size() >= 4) {
        impl_->errors.pop_front();
    }
    impl_->errors.push_back(error);
    static const bool s_trErr = (std::getenv("APPGL_TRACE_GL_ERR") != nullptr);
    if (s_trErr) {
        std::fprintf(stderr, "[GL_ERR] 0x%X (%.*s) at %s:%d msg='%.*s'\n",
            error, (int)functionName.size(), functionName.data(),
            loc.file_name(), loc.line(),
            (int)message.size(), message.data());
    }
    Runtime::ErrorRecord record;
    const bool internalCallSite = functionName.empty();
    if (internalCallSite) {
        std::string tag("<internal@");
        tag.append(sourceLocationBasename(loc.file_name()));
        tag.append(":");
        tag.append(std::to_string(loc.line()));
        tag.append(">");
        record.function = std::move(tag);
    } else {
        record.function = std::string(functionName);
    }
    record.errorEnum = error;
    if (message.empty()) {
        record.message = defaultErrorMessage(error, internalCallSite);
    } else {
        record.message = std::string(message);
    }
    Runtime::shared().recordError(std::move(record));
}

GLenum GLContext::popError() {
    if (impl_->errors.empty()) {
        return GL_NO_ERROR;
    }
    const GLenum error = impl_->errors.front();
    impl_->errors.pop_front();
    return error;
}

const GLubyte* GLContext::getString(GLenum name) {
    switch (name) {
        case GL_VENDOR:
            return reinterpret_cast<const GLubyte*>(impl_->vendorString.c_str());
        case GL_RENDERER:
            return reinterpret_cast<const GLubyte*>(impl_->rendererString.c_str());
        case GL_VERSION:
            return reinterpret_cast<const GLubyte*>(impl_->versionString.c_str());
        case GL_SHADING_LANGUAGE_VERSION:
            return reinterpret_cast<const GLubyte*>(impl_->shadingLanguageVersion.c_str());
        case GL_EXTENSIONS:
            return reinterpret_cast<const GLubyte*>(impl_->extensionsString.c_str());
        default:
            pushError(GL_INVALID_ENUM);
            return nullptr;
    }
}

const std::string& GLContext::rendererString() const {
    return impl_->rendererString;
}

void GLContext::setClaimedVersionString(std::string value) {
    // In Phase 8X Landing C the runtime switched to a declarative
    // claimed-version constant ("4.6 AppGL core" — see
    // CoverageStore::claimedVersion). The only empty-string path that
    // can still reach us is someone calling this method directly with
    // an empty argument; fall through to the same declarative constant
    // so the GL_VERSION string never regresses to a "bootstrap" suffix
    // engines parse as a GL3 context.
    impl_->versionString = value.empty() ? "4.6 AppGL core" : std::move(value);
}

GLCapabilities& GLContext::capabilities() {
    return *impl_->capabilities;
}

GLObjectStore& GLContext::objects() {
    return *impl_->objects;
}

GLStateTracker& GLContext::state() {
    return *impl_->state;
}

MatrixStateMirror& GLContext::matrixState() {
    return impl_->matrixState;
}

const MatrixStateMirror& GLContext::matrixState() const {
    return impl_->matrixState;
}

// Phase 8X Group 4d follow-up¹⁷ — immediate-mode entry points.
//
// See the block comment in GLContext.h alongside the declarations for
// the rationale. These five methods form a small state machine that
// captures `{position, color, texcoord}` tuples between glBegin/glEnd
// and drains them to a built-in Metal pipeline on glEnd. State lives
// in `impl_->immediate`. `currentColor` / `currentTexcoord` are
// per-vertex registers updated by glColor*/glTexCoord* without
// emitting a vertex; only glVertex* pushes into the capture vector.

void GLContext::beginImmediate(GLenum mode) {
    switch (mode) {
        case GL_TRIANGLES:
        case GL_TRIANGLE_STRIP:
        case GL_TRIANGLE_FAN:
        case GL_QUADS:
        case GL_LINES:
        case GL_LINE_STRIP:
        case GL_LINE_LOOP:
        case GL_POINTS:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return;
    }
    if (impl_->immediate.active) {
        // Nested glBegin is invalid in the GL spec.
        pushError(GL_INVALID_OPERATION);
        return;
    }
    impl_->immediate.active = true;
    impl_->immediate.mode = mode;
    impl_->immediate.vertices.clear();
}

void GLContext::immediateVertex(float x, float y, float z, float w) {
    if (!impl_->immediate.active) {
        // glVertex* outside glBegin/glEnd is silently ignored per GL 1.x.
        // (The function exists but does nothing when not inside a begin/end pair.)
        return;
    }
    Impl::ImmediateModeVertex v;
    v.position[0] = x;
    v.position[1] = y;
    v.position[2] = z;
    v.position[3] = w;
    v.color[0] = impl_->immediate.currentColor[0];
    v.color[1] = impl_->immediate.currentColor[1];
    v.color[2] = impl_->immediate.currentColor[2];
    v.color[3] = impl_->immediate.currentColor[3];
    v.texcoord[0] = impl_->immediate.currentTexcoord[0];
    v.texcoord[1] = impl_->immediate.currentTexcoord[1];
    impl_->immediate.vertices.push_back(v);
}

void GLContext::immediateColor(float r, float g, float b, float a) {
    // Per GL 1.x spec, glColor* is valid outside begin/end and simply
    // updates the current color register; it's read by the next glVertex*
    // inside a begin/end pair.
    impl_->immediate.currentColor[0] = r;
    impl_->immediate.currentColor[1] = g;
    impl_->immediate.currentColor[2] = b;
    impl_->immediate.currentColor[3] = a;
}

void GLContext::immediateTexCoord(unsigned int unit, float s, float t, float /*r*/, float /*q*/) {
    // Only texture unit 0 is captured for the built-in immediate-mode
    // pipeline (Chobby/Chili UI only uses unit 0). Multi-texturing on
    // other units is silently ignored — this matches the single-
    // sampler pipeline we build in MetalFrameGraph.
    if (unit != 0) {
        return;
    }
    impl_->immediate.currentTexcoord[0] = s;
    impl_->immediate.currentTexcoord[1] = t;
}

void GLContext::endImmediate() {
    if (!impl_->immediate.active) {
        pushError(GL_INVALID_OPERATION);
        return;
    }
    impl_->immediate.active = false;

    const GLenum mode = impl_->immediate.mode;
    auto& captured = impl_->immediate.vertices;
    if (captured.empty()) {
        return;
    }
    if (impl_->frameGraph == nullptr) {
        return;
    }

    // GL_QUADS → GL_TRIANGLES CPU-side expansion. Metal core has no
    // quads primitive, so every 4 captured vertices become 6 output
    // vertices using the canonical {0,1,2, 0,2,3} fan pattern.
    std::vector<Impl::ImmediateModeVertex> expanded;
    const Impl::ImmediateModeVertex* drawVerts = captured.data();
    std::size_t drawCount = captured.size();
    GLenum drawMode = mode;
    if (mode == GL_QUADS) {
        const std::size_t quads = captured.size() / 4;
        expanded.reserve(quads * 6);
        for (std::size_t q = 0; q < quads; ++q) {
            const Impl::ImmediateModeVertex& v0 = captured[q * 4 + 0];
            const Impl::ImmediateModeVertex& v1 = captured[q * 4 + 1];
            const Impl::ImmediateModeVertex& v2 = captured[q * 4 + 2];
            const Impl::ImmediateModeVertex& v3 = captured[q * 4 + 3];
            expanded.push_back(v0);
            expanded.push_back(v1);
            expanded.push_back(v2);
            expanded.push_back(v0);
            expanded.push_back(v2);
            expanded.push_back(v3);
        }
        drawVerts = expanded.data();
        drawCount = expanded.size();
        drawMode = GL_TRIANGLES;
    }

    // Ensure any pending clear is flushed before the encode.
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Resolve the texture bound to unit 0 GL_TEXTURE_2D, if any.
    // The textured pipeline samples it; the untextured pipeline ignores
    // the slot entirely.
    void* metalTexture = nullptr;
    const GLuint texName = impl_->state->boundTextureOnUnit(0, GL_TEXTURE_2D);
    if (texName != 0) {
        GLTextureObject* tex = impl_->objects->textures().get(texName);
        if (tex != nullptr && tex->metalTexture != nullptr) {
            metalTexture = tex->metalTexture;
        }
    }

    // Build the MVP from the matrix mirror (proj · modelview); the
    // immediate-mode vertex shader applies it to each captured position.
    const Matrix4 mvp = impl_->matrixState.modelViewProjection();

    ImmediateDrawInfo info;
    info.mode = drawMode;
    info.vertices = drawVerts;
    info.vertexCount = drawCount;
    info.vertexStride = sizeof(Impl::ImmediateModeVertex);
    info.mvp = mvp;
    info.metalTexture = metalTexture;

    const bool ok = impl_->frameGraph->encodeImmediateModeDraw(info);
    if (!ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glEnd: MetalFrameGraph failed to encode immediate-mode draw"
        );
    }
}

GLContext::PipelineCacheMetrics GLContext::pipelineCacheMetrics() const {
    PipelineCacheMetrics result;
    if (impl_->frameGraph) {
        auto m = impl_->frameGraph->pipelineCacheMetrics();
        result.hits = m.hits;
        result.misses = m.misses;
        // Phase 8X Group 4d follow-up⁴ — forward the new build counters.
        result.buildAttempts = m.buildAttempts;
        result.buildFailures = m.buildFailures;
        result.cumulativeBuildMillis = m.cumulativeBuildMillis;
    }
    return result;
}

void GLContext::resetPipelineCacheMetrics() {
    if (impl_->frameGraph) {
        impl_->frameGraph->resetPipelineCacheMetrics();
    }
}

std::uint64_t GLContext::metalAllocatedBytes() const {
    if (impl_->frameGraph) {
        return impl_->frameGraph->metalAllocatedBytes();
    }
    return 0;
}

bool GLContext::isTransformFeedbackActive() const {
    // Sprint 8 #9-B (CKPT85): per-TF-object active-state tracking.
    // GL 4.6 §13.2.2 mandates that begin/end/pause/resume validation is
    // against the CURRENTLY-BOUND TF object's state, not a global flag.
    // The global `impl_->transformFeedbackActive` is the legacy mirror
    // that gets last-written by setTransformFeedbackActive — but when
    // glBindTransformFeedback switches the bound object, the global
    // flag still reflects the OLD object's state. Reading per-bound-
    // object state correctly distinguishes "is THIS TF object active?"
    // from "is ANY TF active?".
    //
    // Default object 0 (the implicit context-wide TF) has no backing
    // GLTransformFeedbackObject — its state lives in the global flag.
    // This is the single semantic the global flag still owns.
    //
    // CTS `transform_feedback.draw_xfb_test` exercises this exact
    // scenario: bind(A), begin, pause, bind(B), begin should succeed
    // (B is its own state, A is paused-active). Pre-CKPT85 the global
    // flag returned A's active=true even after B was bound, blocking
    // the begin on B with INVALID_OPERATION.
    const GLuint tfId = impl_->boundTransformFeedbackId;
    if (tfId != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfId)) {
            return tf->active;
        }
    }
    return impl_->transformFeedbackActive;
}

// CKPT119 (Sprint 11 Phase 1 1b — Cluster F shader_image_size): create
// a single-mip texture view at `level` and cache it on the binding.
// See forward-declaration earlier in Impl class for rationale.
void* GLContext::Impl::resolveImageMetalTextureImpl(GLTextureObject* texObj,
                                                    GLuint texName,
                                                    GLint level,
                                                    void*& cachedView,
                                                    GLuint& cachedTex,
                                                    GLint& cachedLev) {
    if (texObj == nullptr || texObj->metalTexture == nullptr) return nullptr;
    if (level == 0) {
        return texObj->metalTexture;
    }
    (void)texName;  // reserved for future per-binding diagnostics
    if (cachedView != nullptr && cachedTex == texName && cachedLev == level) {
        return cachedView;
    }
    id<MTLTexture> baseTex = (__bridge id<MTLTexture>)texObj->metalTexture;
    if (baseTex == nil) return nullptr;
    const NSUInteger maxLevels = baseTex.mipmapLevelCount;
    if (static_cast<NSUInteger>(level) >= maxLevels) {
        return texObj->metalTexture;
    }
    NSRange levelRange = NSMakeRange(static_cast<NSUInteger>(level), 1);
    // CKPT119: per-textureType slice range. Metal asserts:
    // - Cube / CubeArray: slice range must be multiple of 6
    // - 2DArray / 1DArray: slice range = arrayLength
    // - 2D / 2DMS / 3D / 1D: slice range = 1 (default)
    NSUInteger sliceCount = std::max<NSUInteger>(baseTex.arrayLength, 1);
    switch (baseTex.textureType) {
        case MTLTextureTypeCube:
            sliceCount = 6;
            break;
        case MTLTextureTypeCubeArray:
            sliceCount = 6 * std::max<NSUInteger>(baseTex.arrayLength, 1);
            break;
        default:
            break;
    }
    NSRange sliceRange = NSMakeRange(0, sliceCount);
    id<MTLTexture> levelView = [baseTex newTextureViewWithPixelFormat:baseTex.pixelFormat
                                                          textureType:baseTex.textureType
                                                               levels:levelRange
                                                               slices:sliceRange];
    if (levelView == nil) return texObj->metalTexture;
    if (cachedView != nullptr) {
        releaseRetainedMetalObject(cachedView);
    }
    cachedView = transferRetainedMetalObject(levelView);
    cachedTex = texName;
    cachedLev = level;
    return cachedView;
}

bool GLContext::Impl::isTfActiveOnBoundImpl() const {
    if (boundTransformFeedbackId != 0) {
        if (auto* tf = objects->transformFeedbacks().get(boundTransformFeedbackId)) {
            return tf->active;
        }
    }
    return transformFeedbackActive;
}

bool GLContext::Impl::isTfPausedOnBoundImpl() const {
    if (boundTransformFeedbackId != 0) {
        if (auto* tf = objects->transformFeedbacks().get(boundTransformFeedbackId)) {
            return tf->paused;
        }
    }
    return transformFeedbackPaused;
}

void GLContext::Impl::updatePrimitiveCountersForNonGsDraw(
    GLenum mode, GLsizei vertexCount, GLsizei instanceCount,
    GLsizei restartSkipCount)
{
    if (vertexCount <= 0 || instanceCount <= 0) return;
    // GL 4.6 §10.1: post-decomposition primitive count for non-GS
    // draws. Strip/loop topologies produce (count - {1,2}) primitives;
    // list topologies produce count / verts-per-prim. Quads aren't a
    // core-GL primitive (patches aren't counted here — those go
    // through TES anyway).
    //
    // GL 4.6 §22.3 — when primitive-restart is active, the restart
    // index is NOT a submitted vertex nor a primitive boundary vertex
    // for count purposes. For list-type primitives this is exactly
    // `submittedN / verts-per-prim`. Strip/fan/adjacency topologies
    // with restart indices in the middle need per-subsequence math —
    // those tests exercise lists in this iter, the strip path is
    // TODO for later.
    std::size_t prims = 0;
    const std::size_t n = static_cast<std::size_t>(vertexCount);
    const std::size_t submittedRaw = (n > static_cast<std::size_t>(restartSkipCount))
        ? (n - static_cast<std::size_t>(restartSkipCount)) : 0;
    switch (mode) {
        case GL_POINTS:                   prims = submittedRaw; break;
        case GL_LINES:                    prims = submittedRaw / 2; break;
        case GL_LINE_STRIP:               prims = (submittedRaw >= 2) ? submittedRaw - 1 : 0; break;
        case GL_LINE_LOOP:                prims = (submittedRaw >= 2) ? submittedRaw : 0; break;
        case GL_TRIANGLES:                prims = submittedRaw / 3; break;
        case GL_TRIANGLE_STRIP:
        case GL_TRIANGLE_FAN:             prims = (submittedRaw >= 3) ? submittedRaw - 2 : 0; break;
        case GL_LINES_ADJACENCY:          prims = submittedRaw / 4; break;
        case GL_LINE_STRIP_ADJACENCY:     prims = (submittedRaw >= 4) ? submittedRaw - 3 : 0; break;
        case GL_TRIANGLES_ADJACENCY:      prims = submittedRaw / 6; break;
        case GL_TRIANGLE_STRIP_ADJACENCY: prims = (submittedRaw >= 6) ? (submittedRaw - 4) / 2 : 0; break;
        case GL_PATCHES: {
            // GL 4.6 §10.1: PRIMITIVES_SUBMITTED for GL_PATCHES is
            // vertexCount / GL_PATCH_VERTICES. CTS
            // `pipeline_statistics_query_tests_ARB.functional_tess_
            // queries` sets PATCH_VERTICES=3 and draws 7 indices,
            // expecting PRIMITIVES_SUBMITTED to report 2 (EXACT_MATCH).
            // The TCS_PATCHES / TES_INVOCATIONS counters are EQUAL_OR_
            // GREATER in that test — any non-zero count lets them
            // pass. A pure synthetic "1" satisfies the lower-bound
            // queries but fails the exact-match one, hence this path.
            const GLint pv = state ? state->tessellationState().patchVertices : 3;
            prims = (pv > 0) ? (submittedRaw / static_cast<std::size_t>(pv)) : 0;
            break;
        }
        default: break;
    }
    prims *= static_cast<std::size_t>(instanceCount);
    const std::size_t vertsTotal = submittedRaw * static_cast<std::size_t>(instanceCount);
    const bool tfActive = transformFeedbackActive;
    // GL 4.6 §22.1 / §22.3 — advance pipeline-stats counters for
    // every active query whose target tracks one of the per-draw
    // quantities. FS_INVOCATIONS is gated on whether rasterizer-
    // discard is off (discard skips the FS); we don't mask on
    // per-fragment coverage yet — advancing by at least 1 is enough
    // to satisfy the EQUAL_OR_GREATER check in CTS
    // pipeline_statistics_query_tests_ARB.functional_*_invocations.
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
                q.result += static_cast<GLuint64>(prims);
                if (std::getenv("APPGL_DUMP_TESOUT")) {
                    std::fprintf(stderr,
                        "APPGL_DETECTOR nongs_q_update PRIMITIVES_GENERATED "
                        "+= %zu (mode=0x%04X vertexCount=%d patchVerts=%d) "
                        "-> q.result=%llu\n",
                        prims, mode, (int)vertexCount,
                        state ? state->tessellationState().patchVertices : 0,
                        (unsigned long long)q.result);
                }
                break;
            case GL_PRIMITIVES_SUBMITTED:
            case GL_CLIPPING_INPUT_PRIMITIVES:
            case GL_CLIPPING_OUTPUT_PRIMITIVES:
                q.result += static_cast<GLuint64>(prims);
                break;
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                // Sprint 17 Day 9+ regression-debt #5 (R7): when TF is
                // active for a non-GS draw, `writeGsXfbAndCheckDiscard`
                // already credited this query with the buffer-cap-
                // aware `primsWritten`. Crediting the submitted prim
                // count here would double-count and over-report,
                // regressing CTS `transform_feedback.query_vertex_*_
                // test` whose TF buffer fits fewer prims than the
                // draw submits. Leave TFB_WRITTEN to writeGsXfb when
                // TF is active.
                break;
            case GL_VERTICES_SUBMITTED:
            case GL_VERTEX_SHADER_INVOCATIONS:
                q.result += static_cast<GLuint64>(vertsTotal);
                break;
            case GL_FRAGMENT_SHADER_INVOCATIONS:
                // Lower-bound credit — real per-pixel count isn't
                // tracked. At least one fragment ran when a primitive
                // was drawn. Sufficient for EQUAL_OR_GREATER tests.
                if (prims > 0) q.result += 1;
                break;
            default:
                break;
        }
    });
}

GLsizei GLContext::Impl::countRestartIndices(GLenum type, const void* indices,
                                             GLsizei count) const
{
    if (count <= 0 || !state->isEnabled(GL_PRIMITIVE_RESTART)) return 0;
    // Resolve the source bytes. When GL_ELEMENT_ARRAY_BUFFER is bound,
    // `indices` is a byte offset into that buffer; when it's not,
    // `indices` is a raw client pointer.
    const std::uint8_t* base = nullptr;
    const GLuint ebo = state->boundBuffer(GL_ELEMENT_ARRAY_BUFFER);
    if (ebo != 0) {
        const GLBufferObject* buf = objects->buffers().get(ebo);
        if (buf == nullptr || buf->metalBuffer == nullptr) return 0;
        id<MTLBuffer> mtl = (__bridge id<MTLBuffer>)buf->metalBuffer;
        const void* ptr = [mtl contents];
        if (ptr == nullptr) return 0;
        base = reinterpret_cast<const std::uint8_t*>(ptr) +
               reinterpret_cast<std::uintptr_t>(indices);
    } else {
        base = reinterpret_cast<const std::uint8_t*>(indices);
    }
    if (base == nullptr) return 0;

    const GLuint restart = state->primitiveRestartIndex();
    GLsizei occurrences = 0;
    switch (type) {
        case GL_UNSIGNED_BYTE: {
            const std::uint8_t* idx = base;
            const std::uint8_t r = static_cast<std::uint8_t>(restart & 0xFF);
            for (GLsizei i = 0; i < count; ++i) if (idx[i] == r) ++occurrences;
            break;
        }
        case GL_UNSIGNED_SHORT: {
            const std::uint16_t* idx = reinterpret_cast<const std::uint16_t*>(base);
            const std::uint16_t r = static_cast<std::uint16_t>(restart & 0xFFFF);
            for (GLsizei i = 0; i < count; ++i) if (idx[i] == r) ++occurrences;
            break;
        }
        case GL_UNSIGNED_INT: {
            const std::uint32_t* idx = reinterpret_cast<const std::uint32_t*>(base);
            const std::uint32_t r = static_cast<std::uint32_t>(restart);
            for (GLsizei i = 0; i < count; ++i) if (idx[i] == r) ++occurrences;
            break;
        }
        default: break;
    }
    return occurrences;
}

// Phase 3B.5 [metal-tess-TF]: TF writer + counter bump for the Metal
// tess-as-compute path. Sibling to `writeGsXfbAndCheckDiscard` (the
// CPU-interpreter equivalent) but sources its per-vertex bytes from
// the Metal compute-dispatch output buffer + `program.tessEvalOutputLayout`
// rather than the CPU interpreter's flat-float vector.
//
// Called unconditionally after a Phase-3B-tier Metal tess encode —
// the caller passes `totalVerts > 0` only when TF is actually active
// and the dispatch chain produced output.
void GLContext::Impl::writeTessTFAndUpdateCounters(
    GLProgramObject& program,
    const std::uint8_t* tesOutBytes,
    std::uint32_t totalVerts,
    std::size_t perVertexSlotBytes,
    GLenum topology)
{
    // Primitive count derived from topology + vertex count.
    auto vertsPerPrim = [](GLenum topo) -> std::size_t {
        switch (topo) {
            case GL_POINTS:    return 1;
            case GL_LINES:
            case GL_LINE_STRIP:
            case GL_LINE_LOOP: return 2;
            case GL_TRIANGLES:
            case GL_TRIANGLE_STRIP:
            case GL_TRIANGLE_FAN: return 3;
            default:           return 3;  // tess default = triangles
        }
    };
    const std::size_t vpp = vertsPerPrim(topology);
    const std::size_t primsGenerated = (vpp > 0) ? (totalVerts / vpp) : 0;
    std::size_t primsWritten = 0;

    // Helper: write `bytes` length bytes to (buffer, bufOffset).
    // Mirrors writeToBuffer in writeGsXfbAndCheckDiscard.
    auto writeToBuffer = [this](GLuint bufferName, std::size_t bufOffset,
                                const std::uint8_t* src, std::size_t bytes) {
        if (bufferName == 0 || bytes == 0) return;
        GLBufferObject* buf = objects->buffers().get(bufferName);
        if (buf == nullptr) return;
        if (bufOffset + bytes > buf->shadowBytes.size()) return;
        std::memcpy(buf->shadowBytes.data() + bufOffset, src, bytes);
        if (buf->metalBuffer != nullptr) {
            id<MTLBuffer> mb = (__bridge id<MTLBuffer>)buf->metalBuffer;
            std::uint8_t* mc = static_cast<std::uint8_t*>([mb contents]);
            if (mc != nullptr) {
                std::memcpy(mc + bufOffset, src, bytes);
            }
        }
    };

    // TF plumbing only runs when the program has varyings recorded
    // and TF is active. Counter updates always run (PRIMITIVES_
    // GENERATED tracks every draw regardless).
    const bool doTF = transformFeedbackActive &&
                      !program.transformFeedbackVaryingNames.empty() &&
                      tesOutBytes != nullptr &&
                      totalVerts > 0 &&
                      program.tessEvalOutputLayout.structSize > 0;

    if (doTF) {
        const bool interleaved =
            (program.transformFeedbackBufferMode == GL_INTERLEAVED_ATTRIBS);
        const auto& tfNames = program.transformFeedbackVaryingNames;
        const auto& layout = program.tessEvalOutputLayout;

        // Resolve each TF varying to a (struct-offset, byte-size) pair
        // inside the TES output struct. Names must match the SPIRV-
        // Cross-emitted member names. `gl_Position` special-cases.
        struct TfSource { std::size_t offset = 0; std::size_t bytes = 0; };
        std::vector<TfSource> sources(tfNames.size());
        for (std::size_t i = 0; i < tfNames.size(); ++i) {
            const std::string& name = tfNames[i];
            for (const auto& m : layout.members) {
                if (m.name == name ||
                    (name == "gl_Position" && m.isBuiltIn &&
                     m.builtIn == spv::BuiltInPosition)) {
                    sources[i] = {m.offset, m.glPackedBytes > 0 ? m.glPackedBytes : m.size};
                    break;
                }
            }
        }

        if (interleaved) {
            auto binding = state->indexedBufferBinding(
                GL_TRANSFORM_FEEDBACK_BUFFER, 0u);
            std::size_t cursor = static_cast<std::size_t>(binding.offset);
            const std::size_t rangeSize =
                static_cast<std::size_t>(binding.size);
            const std::size_t nPrim = (vpp > 0) ? (totalVerts / vpp) : 0;
            // Per-primitive bytes = sum of varying sizes × vpp.
            std::size_t perVertexBytes = 0;
            for (const auto& s : sources) perVertexBytes += s.bytes;
            const std::size_t perPrimBytes = perVertexBytes * vpp;
            for (std::size_t p = 0; p < nPrim; ++p) {
                GLBufferObject* buf = binding.buffer != 0
                    ? objects->buffers().get(binding.buffer) : nullptr;
                const std::size_t capacity = buf == nullptr
                    ? 0
                    : ((rangeSize > 0)
                        ? (static_cast<std::size_t>(binding.offset) + rangeSize)
                        : buf->shadowBytes.size());
                if (cursor + perPrimBytes > capacity) {
                    break;  // GL 4.6 §13.2: drop this + remaining
                }
                for (std::size_t vi = 0; vi < vpp; ++vi) {
                    const std::size_t vIdx = p * vpp + vi;
                    const std::uint8_t* vertBase =
                        tesOutBytes + vIdx * perVertexSlotBytes;
                    for (const auto& s : sources) {
                        writeToBuffer(binding.buffer, cursor,
                                      vertBase + s.offset, s.bytes);
                        cursor += s.bytes;
                    }
                }
                ++primsWritten;
            }
        } else {
            // GL_SEPARATE_ATTRIBS — one varying per TF binding.
            struct SepBinding {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t perVertexBytes = 0;
                std::size_t perPrimBytes = 0;
                bool truncated = false;
            };
            std::vector<SepBinding> binds(sources.size());
            for (std::size_t i = 0; i < sources.size(); ++i) {
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                binds[i].buffer     = b.buffer;
                binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                binds[i].rangeSize  = static_cast<std::size_t>(b.size);
                binds[i].cursor     = binds[i].baseOffset;
                binds[i].perVertexBytes = sources[i].bytes;
                binds[i].perPrimBytes   = sources[i].bytes * vpp;
            }
            const std::size_t nPrim = (vpp > 0) ? (totalVerts / vpp) : 0;
            for (std::size_t p = 0; p < nPrim; ++p) {
                bool allFit = true;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    GLBufferObject* buf = binds[i].buffer != 0
                        ? objects->buffers().get(binds[i].buffer) : nullptr;
                    const std::size_t capacity = buf == nullptr
                        ? 0
                        : ((binds[i].rangeSize > 0)
                            ? (binds[i].baseOffset + binds[i].rangeSize)
                            : buf->shadowBytes.size());
                    if (binds[i].truncated ||
                        binds[i].cursor + binds[i].perPrimBytes > capacity) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& b : binds) b.truncated = true;
                    continue;
                }
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    for (std::size_t vi = 0; vi < vpp; ++vi) {
                        const std::size_t vIdx = p * vpp + vi;
                        const std::uint8_t* vertBase =
                            tesOutBytes + vIdx * perVertexSlotBytes;
                        writeToBuffer(binds[i].buffer, binds[i].cursor,
                                      vertBase + sources[i].offset,
                                      sources[i].bytes);
                        binds[i].cursor += binds[i].perVertexBytes;
                    }
                }
                ++primsWritten;
            }
        }
    } else if (transformFeedbackActive) {
        primsWritten = primsGenerated;
    }

    // Accumulate counts — mirror the writeGsXfbAndCheckDiscard path.
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
                q.result += static_cast<GLuint64>(primsGenerated);
                if (std::getenv("APPGL_DUMP_TESOUT")) {
                    std::fprintf(stderr,
                        "APPGL_DETECTOR tess_q_update PRIMITIVES_GENERATED "
                        "+= %zu (totalVerts=%u vpp=%zu topology=0x%04X) "
                        "-> q.result=%llu\n",
                        primsGenerated, (unsigned)totalVerts, vpp,
                        topology,
                        (unsigned long long)q.result);
                }
                break;
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                if (transformFeedbackActive) {
                    q.result += static_cast<GLuint64>(primsWritten);
                }
                break;
            default: break;
        }
    });
    // Sprint 8 #9-C (CKPT68): accumulate vertex count on the bound TF
    // object so glDrawTransformFeedback{,Instanced}{,Stream} can use it
    // as the equivalent drawArrays `count` parameter (per GL 4.6
    // §10.5: "count is set to the number of vertices captured during
    // the most recent EndTransformFeedback").
    //
    // CKPT85: per-bound-object check. Pre-CKPT85 the global flag could
    // be false even when the bound TF object was active (e.g. after a
    // bind+end of a different object), causing the accumulator to skip.
    if (isTfActiveOnBoundImpl()) {
        const GLuint tfName = boundTransformFeedbackId;
        if (tfName != 0) {
            if (auto* tf = objects->transformFeedbacks().get(tfName)) {
                // CKPT94 #9-C foundation: tess-stage TF writes always
                // go to stream 0 (no `EmitStreamVertex` in TES). Day 23
                // adds GS-emul per-stream routing via the array.
                tf->capturedVertexCount[0] += static_cast<GLsizei>(primsWritten * vpp);
            }
        }
    }
}

// Sprint 15 Q3-Option-B Phase 3a [metal-tf-vs]: TF writer + counter
// bump for the VS-as-compute path. Sister of `writeTessTFAndUpdateCounters`
// (which sources tess-as-compute output) — this one sources its
// per-vertex bytes from the VS-as-compute Metal dispatch output buffer +
// `program.vsTfOutputLayout` / `program.vsTfResolvedSources` (both
// populated at link time by the Phase 2 reflection block).
//
// Called from drawArrays / drawElements VS-only-TF gate when the GPU
// compute dispatch (`MetalFrameGraph::encodeVsTfComputeDraw`) succeeds.
// Mirrors the interleaved + separate-attribs branches of the tess-TF
// writer; since VS-only-TF has no concept of "primitive vs vertex"
// asymmetry (the VS runs once per vertex and TF writes are per-vertex),
// this writer flattens the topology computation accordingly.
void GLContext::Impl::writeVsTfFromComputeOutput(
    GLProgramObject& program,
    const std::uint8_t* vsOutBytes,
    std::uint32_t totalVerts,
    std::size_t perVertexSlotBytes,
    GLenum topology)
{
    if (vsOutBytes == nullptr || totalVerts == 0 ||
        perVertexSlotBytes == 0) {
        return;
    }
    // Primitive count derived from topology + vertex count (same logic
    // used by the tess-TF writer; needed for query counter updates).
    auto vertsPerPrim = [](GLenum topo) -> std::size_t {
        switch (topo) {
            case GL_POINTS:                   return 1;
            case GL_LINES:
            case GL_LINE_STRIP:
            case GL_LINE_LOOP:                return 2;
            case GL_TRIANGLES:
            case GL_TRIANGLE_STRIP:
            case GL_TRIANGLE_FAN:             return 3;
            case GL_LINES_ADJACENCY:
            case GL_LINE_STRIP_ADJACENCY:     return 4;
            case GL_TRIANGLES_ADJACENCY:
            case GL_TRIANGLE_STRIP_ADJACENCY: return 6;
            default:                          return 1;
        }
    };
    const std::size_t vpp = vertsPerPrim(topology);
    const std::size_t primsGenerated = (vpp > 0) ? (totalVerts / vpp) : 0;
    std::size_t primsWritten = 0;

    // Helper: write `bytes` length bytes to (buffer, bufOffset).
    // Mirrors writeToBuffer in writeTessTFAndUpdateCounters.
    auto writeToBuffer = [this](GLuint bufferName, std::size_t bufOffset,
                                const std::uint8_t* src, std::size_t bytes) {
        if (bufferName == 0 || bytes == 0) return;
        GLBufferObject* buf = objects->buffers().get(bufferName);
        if (buf == nullptr) return;
        if (bufOffset + bytes > buf->shadowBytes.size()) return;
        std::memcpy(buf->shadowBytes.data() + bufOffset, src, bytes);
        if (buf->metalBuffer != nullptr) {
            id<MTLBuffer> mb = (__bridge id<MTLBuffer>)buf->metalBuffer;
            std::uint8_t* mc = static_cast<std::uint8_t*>([mb contents]);
            if (mc != nullptr) {
                std::memcpy(mc + bufOffset, src, bytes);
            }
        }
    };

    const bool doTF =
        transformFeedbackActive &&
        !program.transformFeedbackVaryingNames.empty() &&
        !program.vsTfResolvedSources.empty();

    if (doTF) {
        const bool interleaved =
            (program.transformFeedbackBufferMode == GL_INTERLEAVED_ATTRIBS);
        const auto& sources = program.vsTfResolvedSources;

        if (interleaved) {
            auto binding = state->indexedBufferBinding(
                GL_TRANSFORM_FEEDBACK_BUFFER, 0u);
            std::size_t cursor = static_cast<std::size_t>(binding.offset);
            const std::size_t rangeSize =
                static_cast<std::size_t>(binding.size);
            std::size_t perVertexBytes = 0;
            for (const auto& s : sources) perVertexBytes += s.bytes;
            for (std::uint32_t v = 0; v < totalVerts; ++v) {
                GLBufferObject* buf = binding.buffer != 0
                    ? objects->buffers().get(binding.buffer) : nullptr;
                const std::size_t capacity = buf == nullptr
                    ? 0
                    : ((rangeSize > 0)
                        ? (static_cast<std::size_t>(binding.offset) + rangeSize)
                        : buf->shadowBytes.size());
                if (cursor + perVertexBytes > capacity) {
                    break;  // GL 4.6 §13.2: drop this + remaining
                }
                const std::uint8_t* vertBase =
                    vsOutBytes + static_cast<std::size_t>(v) * perVertexSlotBytes;
                for (const auto& s : sources) {
                    writeToBuffer(binding.buffer, cursor,
                                  vertBase + s.offset, s.bytes);
                    cursor += s.bytes;
                }
            }
            // Primitives written = full primitives that fit; partial
            // primitives at the end count as non-written (matches
            // GL 4.6 §13.2 truncation semantics).
            primsWritten = (cursor - static_cast<std::size_t>(binding.offset))
                / (perVertexBytes * vpp);
            if (primsWritten > primsGenerated) primsWritten = primsGenerated;
        } else {
            // GL_SEPARATE_ATTRIBS — one varying per TF binding.
            struct SepBinding {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t bytes = 0;
                bool truncated = false;
            };
            std::vector<SepBinding> binds(sources.size());
            for (std::size_t i = 0; i < sources.size(); ++i) {
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                binds[i].buffer     = b.buffer;
                binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                binds[i].rangeSize  = static_cast<std::size_t>(b.size);
                binds[i].cursor     = binds[i].baseOffset;
                binds[i].bytes      = sources[i].bytes;
            }
            std::size_t writtenVerts = 0;
            for (std::uint32_t v = 0; v < totalVerts; ++v) {
                bool allFit = true;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    GLBufferObject* buf = binds[i].buffer != 0
                        ? objects->buffers().get(binds[i].buffer) : nullptr;
                    const std::size_t capacity = buf == nullptr
                        ? 0
                        : ((binds[i].rangeSize > 0)
                            ? (binds[i].baseOffset + binds[i].rangeSize)
                            : buf->shadowBytes.size());
                    if (binds[i].truncated ||
                        binds[i].cursor + binds[i].bytes > capacity) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& b : binds) b.truncated = true;
                    break;
                }
                const std::uint8_t* vertBase =
                    vsOutBytes + static_cast<std::size_t>(v) * perVertexSlotBytes;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    writeToBuffer(binds[i].buffer, binds[i].cursor,
                                  vertBase + sources[i].offset,
                                  sources[i].bytes);
                    binds[i].cursor += binds[i].bytes;
                }
                ++writtenVerts;
            }
            primsWritten = (vpp > 0) ? (writtenVerts / vpp) : 0;
        }
    } else if (transformFeedbackActive) {
        primsWritten = primsGenerated;
    }

    // Accumulate counts — mirror the writeTessTFAndUpdateCounters path.
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
                q.result += static_cast<GLuint64>(primsGenerated);
                break;
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                if (transformFeedbackActive) {
                    q.result += static_cast<GLuint64>(primsWritten);
                }
                break;
            default: break;
        }
    });
    if (isTfActiveOnBoundImpl()) {
        const GLuint tfName = boundTransformFeedbackId;
        if (tfName != 0) {
            if (auto* tf = objects->transformFeedbacks().get(tfName)) {
                // VS-only-TF writes always go to stream 0 (no
                // EmitStreamVertex equivalent in VS).
                tf->capturedVertexCount[0] += static_cast<GLsizei>(primsWritten * vpp);
            }
        }
    }
}

// CKPT162 (Sprint 14 Day 9): flush pendingImageWrites captured during
// GS interpreter execution to their bound Metal textures via
// replaceRegion:. Called once per emulated GS draw, before the
// XFB-and-discard check, so subsequent glGetTexImage / FS samples on
// the destination images see the GS-emitted data.
void GLContext::Impl::flushPendingImageWritesForStage(
    const std::vector<appgl::PendingImageWrite>& writes,
    const ShaderReflection* reflection,
    const std::vector<std::uint32_t>& spirv,
    GLProgramObject& program)
{
    if (writes.empty() || reflection == nullptr || spirv.empty()) return;
    // Walk SPIR-V vars to map varId -> reflection storage-image entry
    // (mirror of buildStorageImageMap's matching).
    const auto vars = appgl::collectSamplerVarsFromSpirv(
        spirv.data(), spirv.size());
    for (const auto& pw : writes) {
        // Find SPIR-V var matching pw.arrayVarId.
        const appgl::SamplerVarInfo* matchingVar = nullptr;
        for (const auto& v : vars) {
            if (v.varId == pw.arrayVarId) { matchingVar = &v; break; }
        }
        if (matchingVar == nullptr) continue;
        // Find reflection storage-image entry by name.
        const ShaderReflection::ResourceBinding* imgRefl = nullptr;
        for (const auto& si : reflection->storageImages) {
            if (si.name == matchingVar->name) {
                imgRefl = &si;
                break;
            }
            constexpr const char* kPrefix = "_appgl_";
            constexpr std::size_t kPrefixLen = 7;
            if (matchingVar->name.compare(0, kPrefixLen, kPrefix) == 0 &&
                si.name == matchingVar->name.substr(kPrefixLen)) {
                imgRefl = &si;
                break;
            }
        }
        if (imgRefl == nullptr) continue;
        // Resolve effective unit: layout binding default + element index,
        // optionally overridden by glUniform1i (mirror of
        // buildStorageImageMap's logic).
        std::string lookupName = matchingVar->name;
        constexpr const char* kPrefix = "_appgl_";
        constexpr std::size_t kPrefixLen = 7;
        if (lookupName.compare(0, kPrefixLen, kPrefix) == 0) {
            lookupName = lookupName.substr(kPrefixLen);
        }
        GLuint effUnit = imgRefl->glBinding +
                          static_cast<GLuint>(pw.elementIdx);
        for (const auto& uinfo : program.uniforms) {
            if (uinfo.name != lookupName) continue;
            auto uvIt = program.uniformValues.find(uinfo.location);
            if (uvIt != program.uniformValues.end() &&
                pw.elementIdx <
                    static_cast<std::uint32_t>(uvIt->second.ints.size())) {
                if (uvIt->second.ints[pw.elementIdx] >= 0) {
                    effUnit = static_cast<GLuint>(
                        uvIt->second.ints[pw.elementIdx]);
                }
            }
            break;
        }
        if (effUnit >= kMaxImageUnits) continue;
        const auto& ib = imageBindings[effUnit];
        if (ib.texture == 0) continue;
        GLTextureObject* texObj = objects->textures().get(ib.texture);
        if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
        id<MTLTexture> mtlTex = (__bridge id<MTLTexture>)texObj->metalTexture;
        if (mtlTex.width == 0 || mtlTex.height == 0) continue;
        // Encode the texel into a small native-format buffer per the
        // stored internalFormat. Initial format set covers the cases
        // CTS shader_image_size + shader_image_load_store actually use
        // for g_result and friends.
        std::uint8_t buf[16] = {};
        std::size_t texelBytes = 0;
        switch (pw.internalFormat) {
            case GL_RGBA32I:
            case GL_RGBA32UI:
            case GL_RGBA32F: {
                std::memcpy(buf,      &pw.value[0], 4);
                std::memcpy(buf + 4,  &pw.value[1], 4);
                std::memcpy(buf + 8,  &pw.value[2], 4);
                std::memcpy(buf + 12, &pw.value[3], 4);
                texelBytes = 16;
                break;
            }
            case GL_R32I:
            case GL_R32UI:
            case GL_R32F: {
                std::memcpy(buf, &pw.value[0], 4);
                texelBytes = 4;
                break;
            }
            case GL_RGBA8:
            case GL_RGBA8UI:
            case GL_RGBA8I: {
                buf[0] = static_cast<std::uint8_t>(pw.value[0] & 0xFF);
                buf[1] = static_cast<std::uint8_t>(pw.value[1] & 0xFF);
                buf[2] = static_cast<std::uint8_t>(pw.value[2] & 0xFF);
                buf[3] = static_cast<std::uint8_t>(pw.value[3] & 0xFF);
                texelBytes = 4;
                break;
            }
            default:
                continue;  // Format not in the initial sync-back set.
        }
        if (texelBytes == 0) continue;
        // Bound the coord to the texture extent. Defensive — shaders
        // that compute out-of-range coords spec-wise no-op the store.
        if (pw.coord[0] < 0 ||
            static_cast<NSUInteger>(pw.coord[0]) >= mtlTex.width) continue;
        if (pw.coord[1] < 0 ||
            static_cast<NSUInteger>(pw.coord[1]) >= mtlTex.height) continue;
        const NSUInteger sliceLayer =
            static_cast<NSUInteger>(std::max(0, pw.coord[2]));
        MTLRegion region = MTLRegionMake2D(
            static_cast<NSUInteger>(pw.coord[0]),
            static_cast<NSUInteger>(pw.coord[1]),
            1, 1);
        @try {
            [mtlTex replaceRegion:region
                      mipmapLevel:0
                            slice:sliceLayer
                        withBytes:buf
                      bytesPerRow:texelBytes
                    bytesPerImage:texelBytes];
        } @catch (NSException* exc) {
            // Private-storage textures or array-target mismatches
            // can throw; ignore — the test will fail value-check at
            // glGetTexImage time, which surfaces a clearer signal
            // than a runtime abort.
        }
        if (std::getenv("APPGL_TRACE_GS_EMUL_TEX")) {
            std::fprintf(stderr,
                "[GS-img] flush: var=%u elem=%u unit=%u tex=%u "
                "coord=(%d,%d,%d) bytes=%zu fmt=0x%X\n",
                pw.arrayVarId, pw.elementIdx, effUnit, ib.texture,
                pw.coord[0], pw.coord[1], pw.coord[2], texelBytes,
                pw.internalFormat);
        }
    }
}

bool GLContext::Impl::writeGsXfbAndCheckDiscard(
    GLProgramObject& program, const appgl::EmulatedDraw& ed)
{
    // CKPT162 (Sprint 14 Day 9): flush captured imageStore writes from
    // the GS interpreter to the bound Metal textures. Done before the
    // XFB capture / rasterizer-discard handling so subsequent reads
    // (glGetTexImage / FS samples) see the GS-emitted data on either
    // branch.
    if (!ed.pendingImageWrites.empty()) {
        flushPendingImageWritesForStage(
            ed.pendingImageWrites,
            &program.geometryReflection,
            program.geometrySpirv,
            program);
    }
    // Vertices-per-primitive for the emulator's *expanded*
    // topology. Strip outputs were decomposed to list form in
    // `emulateGeometryDraw`, so ed.topology is one of GL_POINTS /
    // GL_LINES / GL_TRIANGLES (plus adjacency variants, which count
    // the same for primitive-count purposes after decomposition).
    auto vertsPerPrim = [](GLenum topo) -> std::size_t {
        switch (topo) {
            case GL_POINTS:                   return 1;
            case GL_LINES:
            case GL_LINE_STRIP:
            case GL_LINE_LOOP:                return 2;
            case GL_TRIANGLES:
            case GL_TRIANGLE_STRIP:
            case GL_TRIANGLE_FAN:             return 3;
            case GL_LINES_ADJACENCY:
            case GL_LINE_STRIP_ADJACENCY:     return 4;
            case GL_TRIANGLES_ADJACENCY:
            case GL_TRIANGLE_STRIP_ADJACENCY: return 6;
            default:                          return 1;
        }
    };
    const std::size_t vpp = vertsPerPrim(ed.topology);
    const std::size_t primsGenerated = (vpp > 0) ? (ed.vertexCount / vpp) : 0;
    std::size_t primsWritten = 0;
    // Sprint 8 #9-C (CKPT96) — per-stream tracking for multi-stream
    // GS+TF. Populated by the INTERLEAVED multi-slot branch when
    // any output varying carries DecorationStream != 0; the count-
    // credit block at the end of the function uses this to credit
    // per-stream slots of GLTransformFeedbackObject::
    // capturedVertexCount, replacing the CKPT95 streamVertexCounts
    // fallback when truncation-aware tracking is available.
    std::array<std::size_t,
               GLTransformFeedbackObject::kMaxTransformFeedbackStreams>
        primsWrittenByStream{};
    bool primsWrittenByStreamValid = false;

    // When transform feedback is active and the program has TF
    // varyings configured, the emulator's expanded vertex data is
    // the canonical source of truth for what the GS emitted. Write
    // those values into the bound TF buffers before any Metal
    // encode — Metal has no native GS and would capture garbage
    // otherwise.
    //
    // GL_SEPARATE_ATTRIBS (default for CTS adjacency +
    // primitive_counter tests): each TF varying goes to its own
    // indexed TF binding (buffer 0, 1, …).
    // GL_INTERLEAVED_ATTRIBS: all TF varyings concatenated per
    // vertex into a single buffer at index 0.
    // Built-in `gl_Position` captures from the EmulatedVertex
    // position field.
    if (transformFeedbackActive && !program.transformFeedbackVaryingNames.empty()) {
        const std::size_t fpv = ed.floatsPerVertex;
        const std::size_t vCount = ed.vertexCount;
        const auto& tfNames = program.transformFeedbackVaryingNames;
        const bool interleaved =
            (program.transformFeedbackBufferMode == GL_INTERLEAVED_ATTRIBS);

        struct TfSource {
            std::size_t offset = 0;
            std::size_t count = 0;
            std::size_t scalarBytes = sizeof(float);
        };
        std::vector<TfSource> sources(tfNames.size());
        for (std::size_t i = 0; i < tfNames.size(); ++i) {
            const std::string& name = tfNames[i];
            if (name == "gl_Position") {
                sources[i] = {0, 4, sizeof(float)};
                continue;
            }
            std::size_t off = 4;   // skip position
            for (std::size_t k = 0; k < ed.varyingNames.size(); ++k) {
                if (ed.varyingNames[k] == name) {
                    const std::size_t scalarBytes =
                        (k < ed.varyingScalarByteSize.size() &&
                         k < ed.varyingBaseType.size() &&
                         ed.varyingBaseType[k] == 0 &&
                         ed.varyingScalarByteSize[k] == sizeof(double))
                            ? sizeof(double) : sizeof(float);
                    sources[i] = {off, ed.varyingWidths[k], scalarBytes};
                    break;
                }
                off += ed.varyingWidths[k];
            }
        }

        auto writeToBuffer = [this](GLuint bufferName, std::size_t bufOffset,
                                    const float* src, std::size_t count,
                                    std::size_t scalarBytes) {
            if (bufferName == 0 || count == 0) return;
            GLBufferObject* buf = objects->buffers().get(bufferName);
            if (buf == nullptr) return;
            const std::size_t bytes = count * scalarBytes;
            if (bufOffset + bytes > buf->shadowBytes.size()) return;
            std::vector<std::uint8_t> converted;
            const void* writePtr = src;
            if (scalarBytes == sizeof(double)) {
                converted.resize(bytes);
                for (std::size_t i = 0; i < count; ++i) {
                    const double d = static_cast<double>(src[i]);
                    std::memcpy(converted.data() + i * sizeof(double),
                                &d, sizeof(d));
                }
                writePtr = converted.data();
            }
            // Update both the shadow bytes AND the Metal buffer
            // contents. `mutableBufferContents` (the backing for
            // `glMapBufferRange`) prefers the Metal buffer when one
            // is allocated; writing only to `shadowBytes` leaves
            // the readback staring at uninitialised Metal memory.
            std::memcpy(buf->shadowBytes.data() + bufOffset, writePtr, bytes);
            if (buf->metalBuffer != nullptr) {
                id<MTLBuffer> mb = (__bridge id<MTLBuffer>)buf->metalBuffer;
                std::uint8_t* mc = static_cast<std::uint8_t*>([mb contents]);
                if (mc != nullptr) {
                    std::memcpy(mc + bufOffset, writePtr, bytes);
                }
            }
        };

        // Checks whether a range `[cursor .. cursor + size)` fits
        // inside the given buffer binding, considering both the
        // indexed-binding size (if non-zero) and the actual backing
        // storage. Used to implement GL 4.6 §13.2 "if the bytes
        // required for a primitive are not available, TF ends for
        // that primitive and every subsequent primitive".
        auto primFits = [this](GLenum target, GLuint binding, GLuint bufferName,
                               std::size_t cursor, std::size_t rangeStart,
                               std::size_t rangeSize, std::size_t needBytes) -> bool {
            (void)target;
            (void)binding;
            if (bufferName == 0 || needBytes == 0) return false;
            GLBufferObject* buf = objects->buffers().get(bufferName);
            if (buf == nullptr) return false;
            const std::size_t capacity = (rangeSize > 0)
                ? (rangeStart + rangeSize) : buf->shadowBytes.size();
            return cursor + needBytes <= capacity;
        };

        // Primitive-aware TF write. Each primitive consumes
        // `vpp` vertices; we advance the per-buffer cursor by
        // exactly that many vertex strides, and only commit the
        // write if the full primitive fits. As soon as one
        // primitive doesn't fit, all subsequent primitives are
        // also dropped (per GL 4.6 §13.2), and we stop
        // incrementing `primsWritten`.
        if (interleaved) {
            // Sprint 8 #9-C (CKPT96) — INTERLEAVED branch rebuilt to
            // honour `gl_NextBuffer` markers (advance to BO[N+1]) AND
            // per-stream DecorationStream filtering for multi-stream GS.
            //
            // Each TfBufSlot holds a contiguous run of TfSources whose
            // bytes interleave into one GL_TRANSFORM_FEEDBACK_BUFFER
            // binding. `gl_NextBuffer` between two varyings creates a
            // new slot bound to the next indexed binding. Per-buffer
            // stream ownership is captured from the first non-builtin
            // varying's DecorationStream (gl_Position is always stream 0
            // and doesn't claim ownership; gl_NextBuffer-only buffers
            // inherit the default stream 0). Emitted vertices contribute
            // to a slot iff the vertex's stream tag matches the slot's
            // owner stream — for single-stream GS programs this short-
            // circuits to "every vertex contributes to every slot",
            // preserving CKPT95-and-earlier semantics byte-identical.
            //
            // Per-prim truncation per GL 4.6 §13.2: a primitive counts
            // as written iff every matching slot has room for
            // `slot.perVertexBytes * vpp` at its current cursor. Any
            // matching slot's truncation marks the primitive truncated
            // (and every subsequent same-stream primitive thereafter).
            // Different streams have independent truncation tracking
            // through `slot.truncated` per slot.
            struct TfBufSlot {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t perVertexBytes = 0;
                std::vector<TfSource> srcList;
                std::uint32_t stream = 0;
                bool truncated = false;
            };
            std::vector<TfBufSlot> slots;
            auto bindNextSlot = [&](GLuint idx) -> TfBufSlot& {
                slots.emplace_back();
                TfBufSlot& sl = slots.back();
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, idx);
                sl.buffer = b.buffer;
                sl.baseOffset = static_cast<std::size_t>(b.offset);
                sl.rangeSize = static_cast<std::size_t>(b.size);
                sl.cursor = sl.baseOffset;
                return sl;
            };
            bindNextSlot(0);
            GLuint slotBindIdx = 0;
            for (std::size_t i = 0; i < tfNames.size(); ++i) {
                const std::string& name = tfNames[i];
                if (name == "gl_NextBuffer") {
                    ++slotBindIdx;
                    bindNextSlot(slotBindIdx);
                    continue;
                }
                TfSource src;
                if (name == "gl_Position") {
                    src = {0, 4, sizeof(float)};   // stream 0 (built-in)
                } else {
                    std::size_t off = 4;
                    bool found = false;
                    for (std::size_t k = 0; k < ed.varyingNames.size(); ++k) {
                        if (ed.varyingNames[k] == name) {
                            const std::size_t scalarBytes =
                                (k < ed.varyingScalarByteSize.size() &&
                                 k < ed.varyingBaseType.size() &&
                                 ed.varyingBaseType[k] == 0 &&
                                 ed.varyingScalarByteSize[k] == sizeof(double))
                                    ? sizeof(double) : sizeof(float);
                            src = {off, ed.varyingWidths[k], scalarBytes};
                            // First non-builtin varying claims the
                            // slot's stream (the spec requires all
                            // varyings in the same buffer share a
                            // stream; we honour that by taking the
                            // first observed and ignoring later ones).
                            if (slots.back().stream == 0 &&
                                k < ed.varyingStreams.size() &&
                                ed.varyingStreams[k] != 0) {
                                slots.back().stream = ed.varyingStreams[k];
                            }
                            found = true;
                            break;
                        }
                        off += ed.varyingWidths[k];
                    }
                    if (!found) {
                        // CKPT111 (Sprint 10 Phase 2 Day 2): handle
                        // gl_SkipComponents{1,2,3,4} per GL 4.6 §7.3.1.1
                        // — advance the slot cursor by N floats without
                        // writing any data, leaving N components of
                        // existing buffer contents untouched. The CTS
                        // capture_special_interleaved_test layout is
                        //   variable_1 + skip4 + variable_2 + nextBuffer +
                        //   variable_3 + skip4 + variable_4
                        // so variable_2 lands at offset 8 floats (not 4)
                        // in BO0. Encoded as a TfSource with
                        // offset = SIZE_MAX (skip sentinel) and count = N.
                        if (name.size() == 18 &&
                            name.compare(0, 17, "gl_SkipComponents") == 0 &&
                            name[17] >= '1' && name[17] <= '4') {
                            src = {static_cast<std::size_t>(-1),
                                   static_cast<std::size_t>(name[17] - '0'),
                                   sizeof(float)};
                        } else {
                            // Unknown varying name — treat as zero-byte
                            // skip (mirrors prior behaviour for unmatched
                            // sources).
                            src = {0, 0, sizeof(float)};
                        }
                    }
                }
                slots.back().srcList.push_back(src);
                slots.back().perVertexBytes += src.count * src.scalarBytes;
            }

            bool anyMultiStream = false;
            for (const auto& s : slots) {
                if (s.stream != 0) { anyMultiStream = true; break; }
            }
            auto slotMatchesPrim = [&](const TfBufSlot& s,
                                       std::uint32_t pstream) -> bool {
                if (!anyMultiStream) return true;
                return s.stream == pstream;
            };

            const std::size_t nPrim = (vpp > 0) ? (vCount / vpp) : 0;
            for (std::size_t p = 0; p < nPrim; ++p) {
                const std::size_t firstV = p * vpp;
                const std::uint32_t pstream =
                    (firstV < ed.vertexStreams.size())
                        ? ed.vertexStreams[firstV] : 0u;

                bool allFit = true;
                for (auto& sl : slots) {
                    if (!slotMatchesPrim(sl, pstream)) continue;
                    if (sl.truncated) { allFit = false; break; }
                    const std::size_t needBytes = sl.perVertexBytes * vpp;
                    if (needBytes == 0) continue;
                    if (!primFits(GL_TRANSFORM_FEEDBACK_BUFFER, 0,
                                  sl.buffer, sl.cursor, sl.baseOffset,
                                  sl.rangeSize, needBytes)) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& sl : slots) {
                        if (slotMatchesPrim(sl, pstream)) sl.truncated = true;
                    }
                    continue;
                }

                for (std::size_t vi = 0; vi < vpp; ++vi) {
                    const std::size_t v = p * vpp + vi;
                    const float* vertexBase =
                        ed.expandedVertexData.data() + v * fpv;
                    for (auto& sl : slots) {
                        if (!slotMatchesPrim(sl, pstream)) continue;
                        for (const auto& src : sl.srcList) {
                            if (src.count == 0) continue;
                            // CKPT111: gl_SkipComponentsN sentinel —
                            // advance cursor without writing.
                            if (src.offset == static_cast<std::size_t>(-1)) {
                                sl.cursor += src.count * src.scalarBytes;
                                continue;
                            }
                            writeToBuffer(sl.buffer, sl.cursor,
                                          vertexBase + src.offset, src.count,
                                          src.scalarBytes);
                            sl.cursor += src.count * src.scalarBytes;
                        }
                    }
                }
                ++primsWritten;
                if (pstream < primsWrittenByStream.size()) {
                    ++primsWrittenByStream[pstream];
                }
            }
            primsWrittenByStreamValid = true;
        } else {
            // GL_SEPARATE_ATTRIBS — each source writes to its own
            // TF binding. A primitive counts as "written" iff all
            // sources fit their per-primitive slice. Track fit per
            // binding so we count once per primitive regardless of
            // how many varyings it captures.
            struct SepBinding {
                GLuint buffer = 0;
                std::size_t baseOffset = 0;
                std::size_t rangeSize = 0;
                std::size_t cursor = 0;
                std::size_t perVertexBytes = 0;
                std::size_t perPrimBytes = 0;
                bool truncated = false;
            };
            std::vector<SepBinding> binds(sources.size());
            for (std::size_t i = 0; i < sources.size(); ++i) {
                auto b = state->indexedBufferBinding(
                    GL_TRANSFORM_FEEDBACK_BUFFER, static_cast<GLuint>(i));
                binds[i].buffer     = b.buffer;
                binds[i].baseOffset = static_cast<std::size_t>(b.offset);
                binds[i].rangeSize  = static_cast<std::size_t>(b.size);
                binds[i].cursor     = binds[i].baseOffset;
                binds[i].perVertexBytes = sources[i].count * sources[i].scalarBytes;
                binds[i].perPrimBytes   = binds[i].perVertexBytes * vpp;
            }
            const std::size_t nPrim = (vpp > 0) ? (vCount / vpp) : 0;
            for (std::size_t p = 0; p < nPrim; ++p) {
                // Check all bindings fit this primitive. If any
                // is already truncated or wouldn't fit, mark them
                // all truncated from here on (this primitive and
                // every subsequent are dropped).
                bool allFit = true;
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    if (binds[i].truncated ||
                        !primFits(GL_TRANSFORM_FEEDBACK_BUFFER,
                                  static_cast<GLuint>(i), binds[i].buffer,
                                  binds[i].cursor, binds[i].baseOffset,
                                  binds[i].rangeSize, binds[i].perPrimBytes)) {
                        allFit = false;
                        break;
                    }
                }
                if (!allFit) {
                    for (auto& b : binds) b.truncated = true;
                    continue;
                }
                for (std::size_t i = 0; i < sources.size(); ++i) {
                    for (std::size_t vi = 0; vi < vpp; ++vi) {
                        const std::size_t v = p * vpp + vi;
                        const float* vertexBase = ed.expandedVertexData.data() + v * fpv;
                        writeToBuffer(binds[i].buffer, binds[i].cursor,
                                      vertexBase + sources[i].offset,
                                      sources[i].count,
                                      sources[i].scalarBytes);
                        binds[i].cursor += binds[i].perVertexBytes;
                    }
                }
                ++primsWritten;
            }
        }
    } else if (transformFeedbackActive) {
        // TF active with no recorded varyings — still count
        // primitives written (implementations typically count
        // PRIMITIVES_WRITTEN against the TF mode). For us the
        // simplest correct behaviour is "everything the GS
        // emitted" when no buffer constraint applies.
        primsWritten = primsGenerated;
    }

    // Accumulate counts into any active occlusion / primitive
    // queries. GL 4.6 §4.2.1 says these counters sum across draw
    // calls during a single query scope. Per-target accumulation
    // is what CTS primitive_queries.* test.
    //
    // We only touch the queries the emulator can answer
    // definitively: PRIMITIVES_GENERATED counts every primitive
    // the GS emitted (regardless of TF state);
    // TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN counts the subset that
    // fit into the bound TF buffers. Other query targets
    // (SAMPLES_PASSED, TIME_ELAPSED, …) stay on the synthetic-1
    // fallback path — the legacy behaviour.
    //
    // Sprint 17 Day 7+ Bank-Group-G: gate the PRIMITIVES_GENERATED
    // update on `gsPresent`. The non-GS VS-only-TF path
    // (`emulateVsOnlyDrawForTf` → `writeGsXfbAndCheckDiscard`)
    // leaves `ed.topology` at the user's draw mode (e.g.
    // GL_TRIANGLE_STRIP) rather than decomposed-to-list
    // (GL_TRIANGLES) like the GS-emul path does, so the
    // `primsGenerated = ed.vertexCount / vpp` arithmetic above gives
    // the wrong count for strip topologies (4/3 = 1, not 4-2 = 2).
    // For non-GS draws, `updatePrimitiveCountersForNonGsDraw` does
    // the strip-aware math at the drawArrays/drawElements call site.
    //
    // Sprint 17 Day 9+ regression-debt #5 (R7): the
    // TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN update must NOT share
    // that gate. `primsWritten` was incremented per-primitive above
    // by the buffer-cap-aware iteration (one increment iff the
    // primitive's bytes fit in every TF binding), so it carries the
    // GL 4.6 §22.3-required "subset that fit into the bound TF
    // buffers" semantic regardless of stage shape. With the gate
    // present this credit was lost on the VS-only-TF path, and
    // `updatePrimitiveCountersForNonGsDraw`'s fallback credits the
    // submitted (uncapped) prim count — so CTS
    // `transform_feedback.query_vertex_{interleaved,separate}_test`
    // (which sizes the TF buffer to fit only 3 of the 4 submitted
    // POINTS) regressed (extracted 4 vs expected 3). The non-GS
    // sister gate at `updatePrimitiveCountersForNonGsDraw`'s
    // TFB_WRITTEN case skips when `transformFeedbackActive` to
    // avoid double-counting against the credit issued here.
    objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active) return;
        switch (q.target) {
            case GL_PRIMITIVES_GENERATED:
                if (program.gsPresent) {
                    q.result += static_cast<GLuint64>(primsGenerated);
                }
                break;
            case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
                if (transformFeedbackActive) {
                    q.result += static_cast<GLuint64>(primsWritten);
                }
                break;
            case GL_GEOMETRY_SHADER_INVOCATIONS:
                // GL 4.6 §22.3 — counts once per GS invocation. CTS
                // `pipeline_statistics_query_tests_ARB.functional_
                // geometry_shader_queries` uses EQUAL_OR_GREATER ≥ 1.
                // The emulator runs the GS once per input primitive,
                // so any non-zero output means at least one invocation
                // happened. Credit 1 per call — the exact invocation
                // count would need input-primitive tracking in
                // EmulatedDraw (future win).
                if (ed.vertexCount > 0) q.result += 1;
                break;
            case GL_GEOMETRY_SHADER_PRIMITIVES_EMITTED:
                // GL 4.6 §22.3 — counts every EmitVertex + EndPrimitive
                // pair the GS executed. Maps directly to primsGenerated
                // (the emulator's expanded-output primitive count).
                q.result += static_cast<GLuint64>(primsGenerated);
                break;
            default:
                break;
        }
    });

    // Sprint 8 #9-C (CKPT68): accumulate vertex count on the bound TF
    // object — see writeTessTFAndUpdateCounters for full rationale.
    // CKPT85: per-bound-object check (see writeTessTFAndUpdateCounters).
    // CKPT94 #9-C foundation: per-stream array — slot [0] credited on
    // single-stream paths.
    // CKPT95 #9-C extension: GS emul now exposes per-stream vertex tags
    // via ed.streamVertexCounts (post-expansion totals). When the GS
    // uses OpEmitStreamVertex(N), credit stream N's slot directly.
    // For single-stream GS (no streams ≠ 0 used), streamVertexCounts[0]
    // == primsWritten*vpp and streams 1..3 are zero — matches CKPT94
    // single-stream behaviour byte-for-byte.
    //
    // Per GL 4.6 §13.2 the count we credit is the number of vertices
    // actually written to TF buffers, which currently equals
    // `primsWritten * vpp` when GS-emul writes the entire expanded
    // payload (Day 24 / CKPT96 lands per-stream BO routing that
    // filters writes per-stream; until then the byte payload still
    // carries every emitted vertex through to BO[0]/BO[1] as before
    // and only the per-stream COUNT semantic shifts here).
    if (isTfActiveOnBoundImpl()) {
        const GLuint tfName = boundTransformFeedbackId;
        if (tfName != 0) {
            if (auto* tf = objects->transformFeedbacks().get(tfName)) {
                bool hasMultiStream = false;
                for (std::size_t s = 1; s < ed.streamVertexCounts.size(); ++s) {
                    if (ed.streamVertexCounts[s] != 0) { hasMultiStream = true; break; }
                }
                if (hasMultiStream && primsWrittenByStreamValid) {
                    // CKPT96: INTERLEAVED multi-stream path tracked per-
                    // stream prim writes truncation-aware. Use those
                    // directly — gives the spec-correct count for each
                    // stream including partial-truncation cases.
                    for (std::size_t s = 0;
                         s < primsWrittenByStream.size() &&
                         s < GLTransformFeedbackObject::kMaxTransformFeedbackStreams;
                         ++s) {
                        tf->capturedVertexCount[s] +=
                            static_cast<GLsizei>(primsWrittenByStream[s] * vpp);
                    }
                } else if (hasMultiStream) {
                    // CKPT95 fallback path (SEPARATE_ATTRIBS multi-
                    // stream, or any non-INTERLEAVED multi-stream
                    // route): credit each slot from interpreter
                    // streamVertexCounts; truncation is approximated
                    // by scaling each stream by writtenVerts/totalVerts.
                    const std::size_t writtenVerts = primsWritten * vpp;
                    const std::size_t totalVerts = ed.vertexCount;
                    if (totalVerts == 0 || writtenVerts == totalVerts) {
                        for (std::size_t s = 0; s < ed.streamVertexCounts.size()
                                              && s < GLTransformFeedbackObject::kMaxTransformFeedbackStreams;
                             ++s) {
                            tf->capturedVertexCount[s] +=
                                static_cast<GLsizei>(ed.streamVertexCounts[s]);
                        }
                    } else if (totalVerts > 0) {
                        for (std::size_t s = 0; s < ed.streamVertexCounts.size()
                                              && s < GLTransformFeedbackObject::kMaxTransformFeedbackStreams;
                             ++s) {
                            const std::size_t scaled =
                                ed.streamVertexCounts[s] * writtenVerts / totalVerts;
                            tf->capturedVertexCount[s] += static_cast<GLsizei>(scaled);
                        }
                    }
                } else {
                    // Single-stream GS — preserve CKPT94 byte-identical
                    // behaviour at slot [0].
                    tf->capturedVertexCount[0] +=
                        static_cast<GLsizei>(primsWritten * vpp);
                }
            }
        }
    }

    // Rasterizer-discard early-out. With GL_RASTERIZER_DISCARD
    // enabled the Metal draw would fail ("RasterizationEnabled is
    // false but the vertex shader's return type is not void") and
    // produce no output anyway — skip the encode entirely.
    return state->isEnabled(GL_RASTERIZER_DISCARD);
}

void GLContext::setTransformFeedbackActive(bool active) {
    impl_->transformFeedbackActive = active;
    // Mirror the active flag onto the currently-bound TF object so
    // DSA `glGetTransformFeedbackiv(xfb, GL_TRANSFORM_FEEDBACK_ACTIVE)`
    // returns the correct per-object state. CTS
    // `direct_state_access.xfb_functional` queries the per-TF-object
    // active/paused state via DSA after glBeginTransformFeedback and
    // expects GL_TRUE on the bound object.
    const GLuint tfName = impl_->boundTransformFeedbackId;
    if (tfName != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfName)) {
            tf->active = active;
            if (!active) {
                tf->paused = false;
            }
        }
    }
}

bool GLContext::isTransformFeedbackPaused() const {
    // CKPT85: same per-TF-object reading as isTransformFeedbackActive.
    // Default object 0 still uses the global flag.
    const GLuint tfId = impl_->boundTransformFeedbackId;
    if (tfId != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfId)) {
            return tf->paused;
        }
    }
    return impl_->transformFeedbackPaused;
}

void GLContext::setTransformFeedbackPaused(bool paused) {
    impl_->transformFeedbackPaused = paused;
    const GLuint tfName = impl_->boundTransformFeedbackId;
    if (tfName != 0) {
        if (auto* tf = impl_->objects->transformFeedbacks().get(tfName)) {
            tf->paused = paused;
        }
    }
}

GLenum GLContext::transformFeedbackPrimitiveMode() const {
    return impl_->transformFeedbackPrimitiveMode;
}

void GLContext::setTransformFeedbackPrimitiveMode(GLenum mode) {
    impl_->transformFeedbackPrimitiveMode = mode;
}

GLuint GLContext::boundTransformFeedback() const {
    return impl_->boundTransformFeedbackId;
}

void GLContext::setBoundTransformFeedback(GLuint id) {
    impl_->boundTransformFeedbackId = id;
}

GLuint GLContext::boundDrawFramebuffer() const {
    return impl_->state->boundDrawFramebuffer();
}

// ============================================================================
// Phase A Group 6 — Shaders and Programs
// ============================================================================

namespace {

bool isValidShaderStage(GLenum stage) {
    switch (stage) {
        case GL_VERTEX_SHADER:
        case GL_FRAGMENT_SHADER:
        case GL_GEOMETRY_SHADER:
        case GL_TESS_CONTROL_SHADER:
        case GL_TESS_EVALUATION_SHADER:
        case GL_COMPUTE_SHADER:
            return true;
        default:
            return false;
    }
}

void copyStringToBuffer(const std::string& source, GLsizei bufSize, GLsizei* length, GLchar* dest) {
    if (dest == nullptr || bufSize <= 0) {
        if (length != nullptr) {
            *length = 0;
        }
        return;
    }
    const GLsizei copyLen = std::min<GLsizei>(static_cast<GLsizei>(source.size()), bufSize - 1);
    std::memcpy(dest, source.data(), static_cast<std::size_t>(copyLen));
    dest[copyLen] = '\0';
    if (length != nullptr) {
        *length = copyLen;
    }
}

void appendDeclarationsAsUniforms(
    std::vector<GLProgramUniformInfo>& out,
    const std::vector<GLShaderDeclaration>& decls
) {
    for (const auto& decl : decls) {
        const auto existing = std::find_if(out.begin(), out.end(),
            [&](const GLProgramUniformInfo& u) { return u.name == decl.name; });
        if (existing != out.end()) {
            // Phase 8X Group 4d follow-up¹⁵ — when the same uniform is
            // declared in two stages (e.g. vertex + fragment both declare
            // `uniform vec4 ucolor = vec4(1.0);`) honour whichever stage
            // carries a populated default. If the first stage to declare
            // the uniform had no initializer (or the stage order happens
            // to land the defaulted copy second) we still want that default
            // to win over an empty shadow.
            if (existing->defaultFloats.empty() && !decl.defaultFloats.empty()) {
                existing->defaultFloats = decl.defaultFloats;
            }
            if (existing->defaultInts.empty() && !decl.defaultInts.empty()) {
                existing->defaultInts = decl.defaultInts;
            }
            if (existing->defaultUints.empty() && !decl.defaultUints.empty()) {
                existing->defaultUints = decl.defaultUints;
            }
            // RC-D06 / RC-D08: if the second stage carries an explicit
            // location or binding that the first stage lacked, adopt it.
            if (existing->explicitLocation < 0 && decl.explicitLocation >= 0) {
                existing->explicitLocation = decl.explicitLocation;
            }
            if (existing->explicitBinding < 0 && decl.explicitBinding >= 0) {
                existing->explicitBinding = decl.explicitBinding;
            }
            if (existing->explicitOffset < 0 && decl.explicitOffset >= 0) {
                existing->explicitOffset = decl.explicitOffset;
            }
            // GS-max-combined-texture-units fix: when the same uniform
            // array is declared with different sizes across stages
            // (CTS `max_combined_texture_units` declares
            // `usampler2D sampler[VS_UNITS]` / `[GS_UNITS]` / `[FS_UNITS]`
            // where VS=48, GS=1, FS=31 via a per-stage split of
            // MAX_COMBINED_TEXTURE_IMAGE_UNITS between stages — the
            // linked program must cover queries up to
            // sampler[VS_UNITS-1]=47, so arraySize must be 48). Take
            // the max and OR isArray across stages. GLSL 4.6 technically
            // flags differing array sizes as a link error, but most
            // drivers relax and use the maximum; CTS tests assume
            // that behaviour.
            if (decl.arraySize > existing->arraySize) {
                existing->arraySize = decl.arraySize;
            }
            if (decl.isArray) {
                existing->isArray = true;
            }
            continue;
        }
        GLProgramUniformInfo info;
        info.name = decl.name;
        info.type = decl.type;
        info.arraySize = decl.arraySize > 0 ? decl.arraySize : 1;
        info.isArray = decl.isArray;
        info.location = -1;  // assigned below in link-time location pass
        info.explicitLocation = decl.explicitLocation;
        info.explicitBinding = decl.explicitBinding;
        info.explicitOffset = decl.explicitOffset;
        info.defaultFloats = decl.defaultFloats;
        info.defaultInts = decl.defaultInts;
        info.defaultUints = decl.defaultUints;
        out.push_back(std::move(info));
    }
}

}  // namespace

GLuint GLContext::createShader(GLenum stage) {
    if (!isValidShaderStage(stage)) {
        pushError(GL_INVALID_ENUM);
        return 0;
    }
    // GL 4.6 §7.1: shaders and programs share a single name pool.
    // CTS `get_uniform_tests.gl_get_uniform` passes a shader handle
    // to `glGetUniform*` and expects INVALID_OPERATION — it uses
    // the numeric ID to discriminate, so if a shader and program
    // both had the same ID (separate table `nextId_` counters)
    // the discriminator broke.
    const GLuint id = impl_->objects->reserveSharedShaderProgramName();
    GLShaderObject* shader = impl_->objects->shaders().insertAt(id);
    if (shader != nullptr) {
        shader->stage = stage;
    }
    return id;
}

bool GLContext::deleteShader(GLuint shader) {
    if (shader == 0) {
        return true;
    }
    GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr) {
        // Lenient no-op for unknown shader names (see deleteProgram for the
        // same tradeoff — CTS helper classes double-delete on error paths
        // and treat any queued error as a destructor throw).
        return true;
    }
    // Spec: a shader still attached to one or more programs is *flagged for
    // deletion* but not erased from the object store. The actual erase is
    // performed by detachShader / deleteProgram once the attachment count
    // reaches zero. (See `struct GLShaderObject` in GLObjectStore.h for the
    // BAR-side rationale — engines using RAII deleters call glDeleteShader
    // between glAttachShader and glLinkProgram, and the eager-erase Phase A
    // behaviour was masking every real compile result with the dummy
    // "attached shader is not compiled" link-log.)
    object->deleteRequested = true;
    if (object->attachmentCount == 0) {
        impl_->objects->shaders().erase(shader);
    }
    return true;
}

bool GLContext::isShader(GLuint shader) const {
    // Spec: glIsShader returns GL_FALSE for a shader name that has been
    // marked for deletion, even if the underlying object is still resident
    // because of outstanding program attachments. The object store still
    // holds the name (so the link path can resolve it) but the public
    // identity of the shader is gone the moment glDeleteShader runs.
    const GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr) {
        return false;
    }
    return !object->deleteRequested;
}

bool GLContext::shaderSource(GLuint shader, GLsizei count, const GLchar* const* strings, const GLint* length) {
    GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    std::string concatenated;
    for (GLsizei i = 0; i < count; ++i) {
        if (strings == nullptr || strings[i] == nullptr) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if (length != nullptr && length[i] >= 0) {
            concatenated.append(strings[i], static_cast<std::size_t>(length[i]));
        } else {
            concatenated.append(strings[i]);
        }
    }
    object->source = std::move(concatenated);
    object->compiled = false;
    object->compileLog.clear();
    object->declaredUniforms.clear();
    object->declaredInputs.clear();
    object->declaredOutputs.clear();
    // GL_ARB_gl_spirv / GL 4.6 §7.2: glShaderSource clears
    // GL_SPIR_V_BINARY_ARB back to FALSE. Also drop any previously
    // loaded SPIR-V binary so the glslang path takes over cleanly.
    object->isSpirvBinary = false;
    object->spirv.clear();
    return true;
}

bool GLContext::compileShader(GLuint shader) {
    GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // GL_ARB_gl_spirv / GL 4.6 §7.2: "It is an error to call
    // `CompileShader` on a shader object whose `SPIR_V_BINARY_ARB`
    // state is TRUE." Such shaders must instead be finalized via
    // `glSpecializeShader`. Report INVALID_OPERATION and leave the
    // shader's state unchanged (keep `isSpirvBinary` true so a
    // subsequent glSpecializeShader still works).
    if (object->isSpirvBinary) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // Clear any prior compile state so a re-compile of the same shader ID
    // starts from a clean slate (matches the GL spec, which allows source
    // replacement followed by another glCompileShader call).
    object->compiled = false;
    object->compileLog.clear();
    object->spirv.clear();
    object->declaredUniforms.clear();
    object->declaredInputs.clear();
    object->declaredOutputs.clear();

    // Diagnostic-ring tag and source hash used by the compile-stage record
    // pushed at the bottom of this function on both success and failure.
    // Hash uses std::hash<std::string> for cheapness — it isn't a
    // cryptographic identity, just a per-source key BAR can compare across
    // log samples to tell whether two compile attempts saw the same source.
    const std::string shaderTag = "shader-" + std::to_string(shader);
    auto compileSourceHash = [](const std::string& s) -> std::string {
        std::size_t h = std::hash<std::string>{}(s);
        char buf[18];
        std::snprintf(buf, sizeof(buf), "%016zx", h);
        return buf;
    };

    if (object->source.empty()) {
        object->compileLog = "shader source is empty";
        Runtime::shared().recordShaderTranslation({
            shaderTag, "compile", "", "", "", object->compileLog, "", false
        });
        return false;
    }

    const std::string sourceHash = compileSourceHash(object->source);

    // 1. Compat-shader rewrite. Glslang's SPIR-V backend rejects
    //    `#version NNN compatibility` outright and rejects every
    //    fixed-function `gl_*` matrix identifier even in compat mode.
    //    The rewriter downgrades the version directive to `core` and
    //    synthesizes `appgl_*` uniforms (paired with `#define`s) for any
    //    referenced matrix builtin. Non-compat shaders that don't
    //    reference any legacy identifier come back unchanged.
    //
    //    Both passes (the lightweight scanner and the real glslang
    //    compile) operate on the rewritten source so the synthesized
    //    uniforms get picked up by the scanner and end up in
    //    declaredUniforms — which linkProgram lifts into
    //    programObject->uniforms with normal sequential locations.
    CompatShaderRewriteResult rewrite =
        rewriteCompatShader(object->source, object->stage);
    // GLSL 4.00 subroutines are unsupported by glslang's SPIR-V
    // backend ("feature not yet implemented"). Rewrite subroutine
    // syntax into plain GLSL that compiles — enough for CTS
    // `program_interface_query.subroutines-*` which only queries
    // the introspection tables (never actually draws).
    //   `subroutine TYPE NAME ( ... ) ;`                 → commented out
    //   `subroutine uniform TYPE NAME [ ... ] ;`          → commented out
    //   `subroutine ( TYPE_LIST ) RETTYPE FN ( ... ) { ... }`
    //                                                      → `RETTYPE FN ( ... ) { ... }`
    //   `UNIFNAME ( ... )` call sites (where UNIFNAME was a
    //     subroutine uniform)                              → `FIRST_IMPL_NAME ( ... )`
    // The real link-time `scanSubroutineDeclarations` then re-reads
    // the ORIGINAL (unrewritten) source so `resourceSubroutines*`
    // tables still reflect the user's declarations.
    auto rewriteSubroutinesForSpirv = [](const std::string& in) -> std::string {
        // Strip comments for analysis but rewrite the original text
        // so we don't accidentally erase legitimate code.
        // Collect subroutine-uniform name → first compatible impl.
        // We do a two-pass line-based rewrite.
        std::unordered_map<std::string, std::string> uniformToImpl;
        std::unordered_map<std::string, std::vector<std::string>> typeToImpls;
        std::unordered_map<std::string, std::string> uniformToType;
        // Sprint 17 Day 7+ Bank-Group-C dynamic-dispatch (v1):
        // capture subroutine-type prototype return-type + raw param
        // text. v1 covers void-return parameterless subroutines
        // (CTS viewport_index_subroutine — `subroutine void
        // indexSetter();`). Other shapes fall back to static
        // FIRST_IMPL_NAME substitution (current pre-Sprint-17
        // behavior; non-regressing for sister tests).
        std::unordered_map<std::string, std::string> typeReturn;
        std::unordered_map<std::string, std::string> typeParams;
        // Capture each subroutine impl's body text so v1 dispatch can
        // INLINE `{body}` at call sites instead of emitting an
        // OpFunctionCall. The GS-emul interpreter (SPIR-V CPU
        // executor at GeometryShaderEmulator.cpp `isSupportedGsOpcode`)
        // does not support OpFunctionCall (opcode 57), so a static
        // FIRST_IMPL_NAME like `four()` only worked when glslang
        // happened to inline it across stages. Once we emit a real
        // dispatch shape (`if (sel) four(); else five();`) glslang
        // keeps the OpFunctionCall and the emul rejects the GS. To
        // preserve GS-emul compatibility we inline impl body text
        // directly at the dispatch site.
        std::unordered_map<std::string, std::string> implBody;
        // Subroutine type-prototype names (e.g. the `T` in
        // `subroutine void T();`) — emit a dummy `int T;` after
        // stripping so glslang's reserved-identifier validator
        // catches `subroutine void namespace(…);` style tests.
        std::vector<std::string> subTypeNames;
        // First pass: scan for subroutine type + impl + uniform.
        std::size_t p = 0;
        auto isIdent = [](unsigned char c) {
            return std::isalnum(c) || c == '_';
        };
        auto skipWs = [&](std::size_t& pp) {
            while (pp < in.size() && std::isspace(static_cast<unsigned char>(in[pp]))) ++pp;
        };
        auto readWord = [&](std::size_t& pp) -> std::string {
            skipWs(pp);
            std::size_t s = pp;
            while (pp < in.size() && isIdent(static_cast<unsigned char>(in[pp]))) ++pp;
            return in.substr(s, pp - s);
        };
        // GLSL `subroutine` is a keyword only at declaration position.
        // CTS `CommonBugs.CommonBug_ReservedNames` plants it as a
        // function-parameter name (`void foo(int subroutine) { ... }`)
        // and expects the compile to fail. Our rewrite used to strip
        // `subroutine → next `;`` blindly which deleted the closing
        // paren, function body, and whatever followed — breaking the
        // spec-mandated reserved-keyword check. Guard: `subroutine`
        // only counts as a keyword when the previous non-whitespace
        // character is a statement boundary (`;`, `{`, `}`, or start-
        // of-file). In argument lists, after `(`, after `,`, etc., it
        // is an identifier use that glslang will correctly reject.
        auto isDeclPos = [&](std::size_t pos) {
            std::size_t q = pos;
            while (q > 0) {
                unsigned char c = static_cast<unsigned char>(in[q - 1]);
                if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                    --q;
                } else {
                    return c == ';' || c == '{' || c == '}';
                }
            }
            return true;  // start of source
        };
        const std::string kw = "subroutine";
        while ((p = in.find(kw, p)) != std::string::npos) {
            const bool lb = (p == 0) || !isIdent(static_cast<unsigned char>(in[p-1]));
            const bool rb = (p + kw.size() < in.size()) && !isIdent(static_cast<unsigned char>(in[p+kw.size()]));
            if (!lb || !rb || !isDeclPos(p)) { p += kw.size(); continue; }
            std::size_t q = p + kw.size();
            skipWs(q);
            if (q < in.size() && in[q] == '(') {
                // Impl: subroutine(TYPE,...) RETTYPE FN(...)
                ++q;
                std::vector<std::string> typeList;
                while (q < in.size() && in[q] != ')') {
                    skipWs(q);
                    std::string t = readWord(q);
                    if (!t.empty()) typeList.push_back(std::move(t));
                    skipWs(q);
                    if (q < in.size() && in[q] == ',') ++q;
                }
                if (q < in.size()) ++q;  // skip ')'
                (void)readWord(q);   // return type
                std::string fnName = readWord(q);
                if (!fnName.empty()) {
                    for (const auto& t : typeList) {
                        typeToImpls[t].push_back(fnName);
                    }
                }
                // Sprint 17 Day 7+ Bank-Group-C: capture impl body
                // text for v1 inline dispatch. Walk past `(params)`
                // then capture matched `{body}`.
                skipWs(q);
                if (q < in.size() && in[q] == '(') {
                    int pd2 = 1;
                    ++q;
                    while (q < in.size() && pd2 > 0) {
                        if (in[q] == '(') ++pd2;
                        else if (in[q] == ')') --pd2;
                        ++q;
                    }
                }
                skipWs(q);
                if (q < in.size() && in[q] == '{' && !fnName.empty()) {
                    const std::size_t bodyStart = q + 1;
                    int bd = 1;
                    ++q;
                    while (q < in.size() && bd > 0) {
                        if (in[q] == '{') ++bd;
                        else if (in[q] == '}') --bd;
                        if (bd > 0) ++q;
                    }
                    const std::size_t bodyEnd = q;
                    implBody[fnName] = in.substr(bodyStart, bodyEnd - bodyStart);
                    if (q < in.size()) ++q;  // past `}`
                }
                p = q;
                continue;
            }
            std::string next = readWord(q);
            if (next == "uniform") {
                std::string typeName = readWord(q);
                std::string uniName = readWord(q);
                if (!uniName.empty() && !typeName.empty()) {
                    uniformToType[uniName] = typeName;
                }
                p = q;
                continue;
            }
            // Subroutine type prototype: `subroutine RETTYPE NAME (…);`.
            // `next` was the return type; the next word is the type
            // name (the subroutine-type identifier). Collect it so
            // the rewritten source preserves the reserved-keyword
            // check on the type name too.
            std::string typeProtoName = readWord(q);
            if (!typeProtoName.empty()) {
                subTypeNames.push_back(typeProtoName);
                // Sprint 17 Day 7+ Bank-Group-C v1 dispatch: capture
                // return type + raw param text from `(...)` to
                // detect v1-eligibility (void-return + no-params).
                typeReturn[typeProtoName] = next;
                skipWs(q);
                std::size_t paramsStart = q;
                if (q < in.size() && in[q] == '(') {
                    int pd = 1;
                    ++q;
                    while (q < in.size() && pd > 0) {
                        if (in[q] == '(') ++pd;
                        else if (in[q] == ')') --pd;
                        ++q;
                    }
                    typeParams[typeProtoName] =
                        in.substr(paramsStart, q - paramsStart);
                }
            }
            p = q;
        }
        // Resolve each uniform to its first compatible impl.
        for (auto& kv : uniformToType) {
            auto it = typeToImpls.find(kv.second);
            if (it != typeToImpls.end() && !it->second.empty()) {
                uniformToImpl[kv.first] = it->second.front();
            }
        }
        // Sprint 17 Day 7+ Bank-Group-C: compute v1-eligibility per
        // subroutine uniform. v1 covers void-return parameterless
        // subroutines (covers CTS viewport_index_subroutine). Other
        // shapes fall back to static FIRST_IMPL_NAME at call sites.
        // Additionally require ALL impls of the subroutine type to
        // have captured `{body}` text — v1 inlines bodies at the call
        // site to avoid OpFunctionCall (unsupported by GS-emul).
        std::unordered_map<std::string, bool> uniformIsV1Eligible;
        for (const auto& kv : uniformToType) {
            const std::string& tname = kv.second;
            auto retIt = typeReturn.find(tname);
            auto parIt = typeParams.find(tname);
            if (retIt == typeReturn.end() || parIt == typeParams.end()) continue;
            const std::string& ret = retIt->second;
            // Strip whitespace from params for comparison.
            std::string p = parIt->second;
            p.erase(std::remove_if(p.begin(), p.end(),
                [](unsigned char c) { return std::isspace(c); }), p.end());
            const bool voidRet = (ret == "void");
            const bool noParams = (p == "()" || p == "(void)");
            // All impls must have captured body for inline dispatch.
            bool allBodiesCaptured = true;
            auto tiIt = typeToImpls.find(tname);
            if (tiIt == typeToImpls.end() || tiIt->second.empty()) {
                allBodiesCaptured = false;
            } else {
                for (const auto& impl : tiIt->second) {
                    if (implBody.find(impl) == implBody.end()) {
                        allBodiesCaptured = false;
                        break;
                    }
                }
            }
            uniformIsV1Eligible[kv.first] = voidRet && noParams && allBodiesCaptured;
        }
        // Collect unique subroutine-uniform names so we can append a
        // dummy `int <NAME>;` declaration for each, preserving the
        // GLSL reserved-identifier check. CTS
        // `CommonBugs.CommonBug_ReservedNames` expects compile to
        // fail when a subroutine uniform name is a reserved
        // keyword (`namespace`, `using`, …).  If we simply comment
        // out the subroutine line, glslang never sees the reserved
        // name and accepts the program — regression. The dummy
        // declaration pushes the name through glslang's identifier
        // validator.
        std::vector<std::string> subUniNames;
        {
            std::unordered_set<std::string> seenNames;
            for (const auto& kv : uniformToType) {
                if (seenNames.insert(kv.first).second) {
                    subUniNames.push_back(kv.first);
                }
            }
        }

        // Second pass: rewrite.
        std::string out;
        out.reserve(in.size() + 64);
        std::size_t i = 0;
        while (i < in.size()) {
            // Find `subroutine` word at this position?
            if (i + kw.size() <= in.size() && in.compare(i, kw.size(), kw) == 0) {
                const bool lb = (i == 0) || !isIdent(static_cast<unsigned char>(in[i-1]));
                const bool rb = (i + kw.size() < in.size()) && !isIdent(static_cast<unsigned char>(in[i+kw.size()]));
                if (lb && rb && isDeclPos(i)) {
                    std::size_t q = i + kw.size();
                    skipWs(q);
                    if (q < in.size() && in[q] == '(') {
                        // Impl — strip `subroutine(LIST)` prefix. Walk past ')'.
                        int pd = 1; ++q;
                        while (q < in.size() && pd > 0) {
                            if (in[q] == '(') ++pd;
                            else if (in[q] == ')') --pd;
                            ++q;
                        }
                        i = q;  // skip the whole `subroutine(LIST)`
                        continue;
                    }
                    // Type prototype or uniform: delete to end of
                    // statement (next `;`).
                    const std::size_t semi = in.find(';', q);
                    if (semi != std::string::npos) {
                        i = semi + 1;
                        continue;
                    }
                    // No semicolon found — skip just the keyword.
                    i = q;
                    continue;
                }
            }
            // Rewrite call sites for subroutine uniform names.
            if (isIdent(static_cast<unsigned char>(in[i]))) {
                std::size_t s = i;
                while (s < in.size() && isIdent(static_cast<unsigned char>(in[s]))) ++s;
                std::string word = in.substr(i, s - i);
                // Consider as a subroutine-uniform call site only
                // when followed by a '(' (possibly after whitespace)
                // OR `[subscript](`. Array subroutine uniforms like
                // `subroutine uniform b_t b[3]` get called as
                // `b[0]()`, `b[1]()`, etc. — all elements share the
                // same subroutine type so all rewrite to the same
                // impl.
                std::size_t t = s;
                skipWs(t);
                // Walk past `[...]` if present (array subscript).
                std::size_t afterSubscript = t;
                if (t < in.size() && in[t] == '[') {
                    int bd = 1;
                    afterSubscript = t + 1;
                    while (afterSubscript < in.size() && bd > 0) {
                        if (in[afterSubscript] == '[') ++bd;
                        else if (in[afterSubscript] == ']') --bd;
                        ++afterSubscript;
                    }
                }
                std::size_t tt = afterSubscript;
                skipWs(tt);
                auto it = uniformToImpl.find(word);
                if (it != uniformToImpl.end() && tt < in.size() && in[tt] == '(') {
                    // Sprint 17 Day 7+ Bank-Group-C: v1-eligible (void
                    // return, no params) + statement-position call site
                    // → emit inline if-else dispatch chain consuming
                    // `(args);`. Otherwise fall back to static
                    // FIRST_IMPL_NAME emission and let `(args)` flow
                    // naturally (current behavior).
                    auto v1It = uniformIsV1Eligible.find(word);
                    if (v1It != uniformIsV1Eligible.end() && v1It->second) {
                        // Walk past matched `(args)`.
                        std::size_t q = tt + 1;
                        int pd = 1;
                        while (q < in.size() && pd > 0) {
                            if (in[q] == '(') ++pd;
                            else if (in[q] == ')') --pd;
                            ++q;
                        }
                        // Statement-position check: next non-ws must
                        // be `;`. If not, fall back to static.
                        std::size_t r = q;
                        while (r < in.size() &&
                               std::isspace(static_cast<unsigned char>(in[r]))) ++r;
                        if (r < in.size() && in[r] == ';') {
                            // Consume `;` too.
                            std::size_t consumeEnd = r + 1;
                            // Look up impls for this uniform.
                            auto utIt = uniformToType.find(word);
                            std::vector<std::string> impls;
                            if (utIt != uniformToType.end()) {
                                auto tiIt = typeToImpls.find(utIt->second);
                                if (tiIt != typeToImpls.end()) impls = tiIt->second;
                            }
                            if (impls.empty()) {
                                // No impls — degenerate; fall through to static.
                                out.append(it->second);
                                i = afterSubscript;
                                continue;
                            }
                            // Sprint 17 Day 7+ Bank-Group-C: emit
                            // INLINE body text per branch (not
                            // function calls) — avoids OpFunctionCall
                            // which the GS-emul interpreter rejects.
                            // v1-eligibility above guarantees every
                            // impl has captured body text.
                            auto bodyOf = [&](const std::string& nm) -> const std::string& {
                                auto bIt = implBody.find(nm);
                                static const std::string kEmpty;
                                return bIt == implBody.end() ? kEmpty : bIt->second;
                            };
                            if (impls.size() == 1) {
                                out.append("{");
                                out.append(bodyOf(impls[0]));
                                out.append("}");
                            } else {
                                out.append("if (_appgl_sub_");
                                out.append(word);
                                out.append(" == 0u) {");
                                out.append(bodyOf(impls[0]));
                                out.append("}");
                                for (std::size_t k = 1; k + 1 < impls.size(); ++k) {
                                    out.append(" else if (_appgl_sub_");
                                    out.append(word);
                                    out.append(" == ");
                                    out.append(std::to_string(k));
                                    out.append("u) {");
                                    out.append(bodyOf(impls[k]));
                                    out.append("}");
                                }
                                out.append(" else {");
                                out.append(bodyOf(impls.back()));
                                out.append("}");
                            }
                            i = consumeEnd;
                            continue;
                        }
                        // Not statement-position: fall through to static.
                    }
                    // Skip the identifier + optional [subscript]
                    // entirely and emit the impl name. The call's
                    // `(...)` then follows naturally.
                    out.append(it->second);
                    i = afterSubscript;
                    continue;
                }
                out.append(word);
                i = s;
                continue;
            }
            out.push_back(in[i]);
            ++i;
        }
        // Append a plain `int <NAME>;` declaration for each
        // stripped subroutine uniform so glslang's reserved-
        // identifier validator still sees the name verbatim.
        // Otherwise `subroutine uniform T namespace;` would slip
        // through silently (keyword-level stripped), regressing
        // CTS `CommonBugs.CommonBug_ReservedNames` which checks
        // that each reserved word triggers a compile error.
        if (!subUniNames.empty() || !subTypeNames.empty()) {
            out.append("\n// appgl: reserved-name validation stubs\n");
            for (const auto& n : subUniNames) {
                out.append("int ");
                out.append(n);
                out.append(";\n");
            }
            std::unordered_set<std::string> seenTypes;
            for (const auto& n : subTypeNames) {
                if (!seenTypes.insert(n).second) continue;
                // Don't re-emit if it's also a uniform name.
                if (std::find(subUniNames.begin(), subUniNames.end(), n) != subUniNames.end()) continue;
                out.append("int ");
                out.append(n);
                out.append(";\n");
            }
        }
        // Sprint 17 Day 7+ Bank-Group-C: emit synthetic dispatch
        // uniforms for v1-eligible subroutine uniforms. The link-time
        // `processSubroutineDispatchUniforms` lambda walks every
        // stage's `_DefaultUniforms` reflection for these, registers
        // their default-block locations into
        // `subroutineDispatchUniformLocations`, and
        // `glUniformSubroutinesuiv` writes the selected subroutine
        // index into `_appgl_sub_<UNI>`. The inline if-else chain
        // emitted at call sites then branches to the selected impl.
        //
        // CRITICAL: the synthetic uniform declarations must precede
        // `main()` in lexical order — call sites in `main()` reference
        // `_appgl_sub_<UNI>` and GLSL requires identifier declaration
        // before use even at global scope (glslang's parser is single-
        // pass on globals). Inject the header right after the
        // `#version`/`#extension` block at the top of the rewritten
        // output rather than appending at the end.
        std::string synthHeader;
        for (const auto& n : subUniNames) {
            auto it = uniformIsV1Eligible.find(n);
            if (it == uniformIsV1Eligible.end() || !it->second) continue;
            if (synthHeader.empty()) {
                synthHeader = "// appgl: subroutine dynamic-dispatch uniforms (v1)\n";
            }
            synthHeader += "uniform uint _appgl_sub_";
            synthHeader += n;
            synthHeader += ";\n";
        }
        if (!synthHeader.empty()) {
            // Find injection point: end of last contiguous `#version`/
            // `#extension`/`#pragma` line at the top of `out`. Skip
            // initial whitespace, then scan forward across consecutive
            // preprocessor-directive lines so the synthesized header
            // lands AFTER all extension enables (e.g.
            // GL_ARB_geometry_shader4 / viewport_array) but BEFORE any
            // user code.
            std::size_t injectAt = 0;
            while (injectAt < out.size() &&
                   std::isspace(static_cast<unsigned char>(out[injectAt]))) {
                ++injectAt;
            }
            while (injectAt < out.size() && out[injectAt] == '#') {
                std::size_t lineEnd = out.find('\n', injectAt);
                if (lineEnd == std::string::npos) {
                    injectAt = out.size();
                    break;
                }
                injectAt = lineEnd + 1;
                // Skip whitespace + blank lines between directives.
                while (injectAt < out.size() &&
                       (out[injectAt] == ' ' || out[injectAt] == '\t' ||
                        out[injectAt] == '\r' || out[injectAt] == '\n')) {
                    ++injectAt;
                }
            }
            out.insert(injectAt, synthHeader);
        }
        return out;
    };
    // Apply to the compat-rewritten source.
    std::string afterSubRewrite = rewriteSubroutinesForSpirv(
        rewrite.didRewrite ? rewrite.source : object->source);
    const bool didSubRewrite =
        afterSubRewrite.size() != (rewrite.didRewrite ? rewrite.source : object->source).size();
    const std::string baseCompileSource =
        didSubRewrite ? afterSubRewrite
                       : (rewrite.didRewrite ? rewrite.source : object->source);
    std::string after420packImplicitRewrite =
        rewrite420packImplicitConversionsForSpirv(baseCompileSource);
    const std::string& compileSource =
        (after420packImplicitRewrite != baseCompileSource)
            ? after420packImplicitRewrite
            : baseCompileSource;

    // 2. Lightweight scanner pass. Still needed for declared attribute inputs
    //    so the vertex-input binding path (glBindAttribLocation /
    //    layout(location=...)) can be resolved without going through
    //    SPIRV-Cross reflection. The scanner's uniform output is now
    //    secondary — link time pulls UBO members from SPIR-V reflection
    //    directly so interface blocks are visible even though the scanner
    //    ignores them.
    GLSLReflectionResult reflection = reflectGLSL(compileSource, object->stage);

    // Reverse-map compat shader renames so GL queries report original names.
    // The shader source uses `_appgl_sampler` (so glslang accepts it), but
    // the GL API must expose the original `sampler` name to applications.
    if (rewrite.didRewrite) {
        auto reverseRename = [](std::string& s) {
            const std::string from = "_appgl_sampler";
            const std::string to = "sampler";
            std::string::size_type pos = 0;
            while ((pos = s.find(from, pos)) != std::string::npos) {
                s.replace(pos, from.size(), to);
                pos += to.size();
            }
        };
        for (auto& decl : reflection.uniforms) {
            reverseRename(decl.name);
        }
        for (auto& decl : reflection.inputs) {
            reverseRename(decl.name);
        }
        for (auto& decl : reflection.outputs) {
            reverseRename(decl.name);
        }
    }

    // GL 4.6 §4.3.9: `atomic_uint` uniforms may not be declared
    // as an unsized array. CTS
    // `shader_atomic_counters.negative-unsized-array` plants
    // `uniform atomic_uint arr[];` in a fragment shader and
    // expects COMPILE_STATUS = FALSE. Glslang accepts the
    // declaration (perhaps treating it as a runtime-sized
    // "last-member" array), so we reject it here before the
    // glslang pass.
    for (const auto& decl : reflection.uniforms) {
        if (decl.type == GL_UNSIGNED_INT_ATOMIC_COUNTER &&
            decl.isArray && decl.arraySize <= 0) {
            object->compileLog =
                "ERROR: atomic_uint uniform '" + decl.name +
                "' cannot be declared as an unsized array (GL 4.6 §4.3.9).";
            object->compiled = false;
            object->spirv.clear();
            Runtime::shared().recordShaderTranslation({
                shaderTag, "compile", "", "", "", object->compileLog, "", false
            });
            return true;  // entry point completed; compile
                         // verdict visible via getShaderiv(COMPILE_STATUS).
        }
    }

    // GLSL 4.60 §3.5: the `#` preprocessing operator (stringification)
    // is not allowed in GLSL. CTS
    // `shaders.preprocessor.basic.stringification_{vertex,fragment}`
    // plants
    //   `#define VEC4_STRING_PARAM(a, b, c, d) vec4(#a, #b, c, d)`
    // and asserts COMPILE_STATUS = FALSE. glslang under
    // `setEnvInputVulkanRulesRelaxed()` accepts the construct.
    // Scan each `#define` directive for a `#<identifier>` token
    // in its replacement text and reject at compile time.
    {
        const std::string& src = object->source;
        std::size_t pos = 0;
        while ((pos = src.find("#define", pos)) != std::string::npos) {
            // Make sure we're at a line start (preceded only by
            // whitespace on the same line). A comment containing
            // "#define" inside should be ignored.
            std::size_t lineStart = pos;
            while (lineStart > 0 && src[lineStart - 1] != '\n') --lineStart;
            bool onlyWsBefore = true;
            for (std::size_t i = lineStart; i < pos; ++i) {
                if (src[i] != ' ' && src[i] != '\t') { onlyWsBefore = false; break; }
            }
            if (!onlyWsBefore) { pos += 7; continue; }
            // Find end of directive line (handle line continuations \).
            std::size_t lineEnd = pos;
            while (lineEnd < src.size()) {
                if (src[lineEnd] == '\\' && lineEnd + 1 < src.size() && src[lineEnd + 1] == '\n') {
                    lineEnd += 2; // continuation
                    continue;
                }
                if (src[lineEnd] == '\n') break;
                ++lineEnd;
            }
            // Scan the body for `#<identifier>` (stringification).
            // Skip past `#define` itself (7 chars).
            // Token paste `##<identifier>` is allowed in GLSL, only
            // single-`#` stringification is the disallowed operator.
            for (std::size_t i = pos + 7; i + 1 < lineEnd; ++i) {
                if (src[i] != '#') continue;
                // `##` is token-paste, valid in GLSL. Skip past both.
                if (i + 1 < lineEnd && src[i + 1] == '#') {
                    ++i;  // skip the second #; for loop will ++i past it
                    continue;
                }
                // Single `#` followed by identifier-start is the
                // disallowed stringification operator.
                const unsigned char nx = static_cast<unsigned char>(src[i + 1]);
                if (std::isalpha(nx) || nx == '_') {
                    object->compileLog =
                        "ERROR: GLSL does not allow the `#` preprocessing "
                        "operator in macro replacement lists "
                        "(GLSL 4.60 §3.5).";
                    object->compiled = false;
                    object->spirv.clear();
                    Runtime::shared().recordShaderTranslation({
                        shaderTag, "compile", "", "", "", object->compileLog, "", false
                    });
                    return true;
                }
            }
            pos = lineEnd;
        }
    }

    // GL 4.6 §11.1.3.2 (ClipDistance) / §E.2.1 deprecated gl_ClipVertex:
    // A vertex shader must not write to BOTH `gl_ClipVertex` and any
    // element of `gl_ClipDistance[]`. The spec describes this as
    // undefined behaviour, but the CTS treats it as a compile error
    // (clip_distance.negative asserts COMPILE_STATUS = FALSE on such a
    // shader). Detect the pattern by source-text scan — we look for
    // the `gl_ClipVertex` assignment target and any `gl_ClipDistance`
    // reference in the same shader body.
    if (object->stage == GL_VERTEX_SHADER) {
        // Scan the ORIGINAL GLSL, not the rewritten form — CompatShader-
        // Rewrite renames `gl_ClipVertex` to `appgl_ClipVertex` before
        // this point, so the post-rewrite scan would miss the pattern.
        const std::string& src = object->source;
        auto findWordBoundary = [&](const char* needle) {
            std::size_t pos = 0;
            const std::size_t nlen = std::strlen(needle);
            while ((pos = src.find(needle, pos)) != std::string::npos) {
                const bool leftBoundary = (pos == 0) ||
                    !(std::isalnum(static_cast<unsigned char>(src[pos - 1])) || src[pos - 1] == '_');
                const std::size_t end = pos + nlen;
                const bool rightBoundary = (end >= src.size()) ||
                    !(std::isalnum(static_cast<unsigned char>(src[end])) || src[end] == '_');
                if (leftBoundary && rightBoundary) return true;
                pos = end;
            }
            return false;
        };
        const bool usesClipVertex   = findWordBoundary("gl_ClipVertex");
        const bool usesClipDistance = findWordBoundary("gl_ClipDistance");
        if (usesClipVertex && usesClipDistance) {
            object->compileLog =
                "ERROR: vertex shader must not write to both "
                "gl_ClipVertex and gl_ClipDistance[] in the same "
                "stage (GL 4.6 §11.1.3.2).";
            object->compiled = false;
            object->spirv.clear();
            Runtime::shared().recordShaderTranslation({
                shaderTag, "compile", "", "", "", object->compileLog, "", false
            });
            return true;
        }
    }

    object->declaredUniforms = std::move(reflection.uniforms);
    object->declaredInputs = std::move(reflection.inputs);
    object->declaredOutputs = std::move(reflection.outputs);

    // 3. Real glslang compile. This is the authoritative verdict that
    //    glGetShaderiv(GL_COMPILE_STATUS) and glGetShaderInfoLog now
    //    surface to the engine — the scanner result above only shapes the
    //    explicit-location metadata, not the compile status.
    //
    //    Version 330 matches what linkProgram used to pass in the old
    //    "compile at link time" path. Engines that target 4.x cores still
    //    use #version 330 / 410 / 460 in their source headers; glslang
    //    respects the in-source directive, so the integer passed here is
    //    only the fallback when the source has no #version line.

    // 3a. Pre-glslang validation: GLSL 4.60 §4.1.8 forbids all qualifiers
    //     except precision (highp/mediump/lowp) on struct members.
    //     Glslang under Vulkan-relaxed rules silently accepts some
    //     forbidden qualifiers (layout(shared), shared, coherent, ...).
    //     We enforce the rule ourselves so
    //     `shaders.negative.non_precision_qualifiers_in_struct_members`
    //     sees the compile-time failure it expects.
    {
        std::string validationError;
        if (!validateStructMemberQualifiers(compileSource, validationError)) {
            object->compileLog = std::move(validationError);
            Runtime::shared().recordShaderTranslation({
                shaderTag, "compile", sourceHash, "", "", object->compileLog, "", false
            });
            return false;
        }
    }

    // 3b. Tess-eval primitive-mode injection: GL 4.6 §11.2.3 requires
    //     tess-eval shaders to declare `layout(triangles/quads/isolines)
    //     in;` — but the rule is a LINK-time check, not compile-time.
    //     Glslang's per-shader `TProgram::link` raises it anyway during
    //     our compileGLSL pipeline, which would surface as a compile
    //     error and flunk CTS
    //     `tessellation_shader.compilation_and_linking_errors.
    //     te_lacking_primitive_mode_declaration`.
    //
    //     If the user's tess-eval source lacks the directive, inject a
    //     default `layout(triangles) in;` into the glslang-visible
    //     `compileSource` (NOT `object->source`, which stays as the
    //     user's unmodified text). Compile then succeeds. At real link
    //     time, `linkProgram` inspects `tessEvalShader->source`
    //     (original) and fails the link with the spec-correct error.
    if (object->stage == GL_TESS_EVALUATION_SHADER) {
        auto stripComments = [](const std::string& in) {
            std::string out;
            out.reserve(in.size());
            for (std::size_t i = 0; i < in.size(); ) {
                if (i + 1 < in.size() && in[i] == '/' && in[i + 1] == '/') {
                    while (i < in.size() && in[i] != '\n') { ++i; }
                } else if (i + 1 < in.size() && in[i] == '/' && in[i + 1] == '*') {
                    i += 2;
                    while (i + 1 < in.size() && !(in[i] == '*' && in[i + 1] == '/')) ++i;
                    if (i + 1 < in.size()) i += 2;
                } else {
                    out.push_back(in[i]);
                    ++i;
                }
            }
            return out;
        };
        const std::string clean = stripComments(compileSource);
        auto findPrimMode = [&](const std::string& tok) -> bool {
            std::size_t pos = 0;
            while (pos < clean.size()) {
                std::size_t lp = clean.find("layout", pos);
                if (lp == std::string::npos) return false;
                bool leftOk = (lp == 0) ||
                    !(std::isalnum(static_cast<unsigned char>(clean[lp - 1])) ||
                      clean[lp - 1] == '_');
                bool rightOk = (lp + 6 >= clean.size()) ||
                    !(std::isalnum(static_cast<unsigned char>(clean[lp + 6])) ||
                      clean[lp + 6] == '_');
                if (!leftOk || !rightOk) { pos = lp + 1; continue; }
                std::size_t op = clean.find('(', lp);
                if (op == std::string::npos) return false;
                std::size_t cp = clean.find(')', op);
                if (cp == std::string::npos) return false;
                std::string inner = clean.substr(op + 1, cp - op - 1);
                std::size_t tp = inner.find(tok);
                while (tp != std::string::npos) {
                    bool lOk = (tp == 0) ||
                        !(std::isalnum(static_cast<unsigned char>(inner[tp - 1])) ||
                          inner[tp - 1] == '_');
                    bool rOk = (tp + tok.size() >= inner.size()) ||
                        !(std::isalnum(static_cast<unsigned char>(inner[tp + tok.size()])) ||
                          inner[tp + tok.size()] == '_');
                    if (lOk && rOk) return true;
                    tp = inner.find(tok, tp + 1);
                }
                pos = cp + 1;
            }
            return false;
        };
        const bool hasPrimMode = findPrimMode("triangles") ||
                                 findPrimMode("quads") ||
                                 findPrimMode("isolines");
        if (!hasPrimMode) {
            // Inject after the `#version` line so the directive is
            // placed in a legal spot (GLSL requires `#version` to
            // precede all non-preprocessor tokens).
            std::string injected = compileSource;
            std::size_t insertAt = 0;
            std::size_t vp = injected.find("#version");
            if (vp != std::string::npos) {
                std::size_t eol = injected.find('\n', vp);
                insertAt = (eol == std::string::npos)
                    ? injected.size() : eol + 1;
            }
            injected.insert(insertAt, "layout(triangles) in;\n");
            // Compile the injected copy directly and stash on the
            // shader for SPIR-V generation.
            ShaderTranslator translatorTmp;
            std::string compileLogTmp;
            std::vector<std::uint32_t> spirvTmp = translatorTmp.compileGLSL(
                injected, object->stage, 330, &compileLogTmp);
            object->compileLog = std::move(compileLogTmp);
            if (spirvTmp.empty()) {
                Runtime::shared().recordShaderTranslation({
                    shaderTag, "compile", sourceHash, "", "",
                    object->compileLog, "", false
                });
                return false;
            }
            object->spirv = std::move(spirvTmp);
            object->compiled = true;
            Runtime::shared().recordShaderTranslation({
                shaderTag, "compile", sourceHash, "", "", "", "", true
            });
            return true;
        }
    }

    ShaderTranslator translator;
    std::string compileLog;
    std::vector<std::uint32_t> spirv =
        translator.compileGLSL(compileSource, object->stage, 330, &compileLog);

    object->compileLog = std::move(compileLog);
    if (spirv.empty()) {
        // Glslang failed. compileLog contains the real diagnostic text,
        // which getShaderInfoLog will now return verbatim. Push the failure
        // to the diagnostic ring as a compile-stage record so BAR sees the
        // glslang log directly without having to wait for a downstream
        // glLinkProgram lift. (Pre-Group-4d the only path was via
        // linkProgram's "attached shader is not compiled" branch, which
        // could not survive the eager-erase shader lifetime bug — see
        // GLObjectStore.h::GLShaderObject for the full story.)
        Runtime::shared().recordShaderTranslation({
            shaderTag, "compile", sourceHash, "", "", object->compileLog, "", false
        });
        return false;
    }

    object->spirv = std::move(spirv);
    object->compiled = true;
    // Push a positive compile-stage record. mslPreview is intentionally
    // empty here — MSL transpilation runs at link time, not compile time —
    // but the presence of the record (with success=true and a stable
    // sourceHash) is enough for BAR-side observation to confirm the compat
    // rewriter / glslang pipeline ran end-to-end on this shader.
    Runtime::shared().recordShaderTranslation({
        shaderTag, "compile", sourceHash, "", "", "", "", true
    });
    return true;
}

bool GLContext::getShaderiv(GLuint shader, GLenum pname, GLint* params) {
    GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    switch (pname) {
        case GL_SHADER_TYPE:
            *params = static_cast<GLint>(object->stage);
            return true;
        case GL_DELETE_STATUS:
            *params = object->deleteRequested ? GL_TRUE : GL_FALSE;
            return true;
        case GL_COMPILE_STATUS:
            *params = object->compiled ? GL_TRUE : GL_FALSE;
            return true;
        case GL_INFO_LOG_LENGTH:
            *params = static_cast<GLint>(object->compileLog.size() + (object->compileLog.empty() ? 0 : 1));
            return true;
        case GL_SHADER_SOURCE_LENGTH:
            *params = static_cast<GLint>(object->source.size() + (object->source.empty() ? 0 : 1));
            return true;
        case 0x91B1:   // GL_COMPLETION_STATUS_KHR / _ARB
            // Our compile path is synchronous — every compile finishes
            // before glCompileShader returns, so completion is always
            // true. Matches GL_ARB/KHR_parallel_shader_compile spec
            // "If this query is called before a call to glCompileShader,
            // the implementation shall return GL_TRUE" — and after the
            // synchronous compile, it's trivially complete.
            *params = GL_TRUE;
            return true;
        case 0x9552:   // GL_SPIR_V_BINARY_ARB
            // GL_ARB_gl_spirv — TRUE if the shader's last-seen source
            // was a SPIR-V binary via glShaderBinary(); cleared back to
            // FALSE on any subsequent glShaderSource(). Gates the
            // validity of glSpecializeShader on this object.
            *params = object->isSpirvBinary ? GL_TRUE : GL_FALSE;
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getShaderInfoLog(GLuint shader, GLsizei bufSize, GLsizei* length, GLchar* infoLog) {
    GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    copyStringToBuffer(object->compileLog, bufSize, length, infoLog);
    return true;
}

bool GLContext::getShaderSource(GLuint shader, GLsizei bufSize, GLsizei* length, GLchar* source) {
    GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    copyStringToBuffer(object->source, bufSize, length, source);
    return true;
}

GLuint GLContext::createProgram() {
    // GL 4.6 §7.1 shared shader/program name pool (see createShader).
    const GLuint id = impl_->objects->reserveSharedShaderProgramName();
    impl_->objects->programs().insertAt(id);
    return id;
}

bool GLContext::deleteProgram(GLuint program) {
    if (program == 0) {
        return true;
    }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        // Lenient no-op for unknown program names. Spec (GL 4.6 §7.3) says
        // GL_INVALID_VALUE, but CTS tests (e.g. clip_distance.functional)
        // double-delete program ids and treat error queue leakage as
        // destructor-throws — a single errored delete aborts the entire
        // sweep. NVIDIA's driver is similarly lenient. Applications that
        // legitimately track program names won't hit this path.
        return true;
    }
    object->deleteRequested = true;
    // GL 4.6 §7.3: a program object currently in use is NOT erased
    // immediately. It stays alive (and in use) until it is no longer
    // part of any context's current state. The actual erase happens
    // when the currently-bound program changes (via glUseProgram of a
    // different name, including 0).
    //
    // This matters because CTS helper classes (e.g. ClipDistance::
    // Utility::Program, CullDistance::Utility::Program) wrap GL
    // programs in RAII, and their `bool useAsShaderInput(Program ...)`
    // helpers take the Program argument BY VALUE. The copy's
    // destructor runs at call-return while the program is still
    // current — if we erase on delete, the subsequent draw sees
    // programName=N in `state->currentProgram()` but programs().get(N)
    // returns nullptr, the translated-pipeline branch skips, and the
    // draw silently no-ops. CTS's clip_distance.functional and
    // cull_distance.functional_* suites (~400 tests) all trip on
    // this — "vertex unexpectedly clipped" is actually "nothing
    // rendered because no program was bound by draw time."
    //
    // Defer both the state-clear and the object-store erase. When a
    // different program takes over in `useProgram`, that call finishes
    // the deletion for any delete-requested predecessor.
    if (impl_->state->currentProgram() == program) {
        // Live — defer actual erase until a different program becomes
        // current. `useProgram` finalises the deletion at that point.
        return true;
    }
    // Inline helper: decrement shader attachment counts (mirrors the
    // synthetic-detach that deleteProgram has always performed) and
    // erase the program. Used from both the immediate-erase path (not
    // currently bound) and the deferred-erase path (`useProgram` when
    // replacing a delete-requested program).
    std::vector<GLuint> attached = object->attachedShaders;
    for (GLuint shaderId : attached) {
        GLShaderObject* shaderObject = impl_->objects->shaders().get(shaderId);
        if (shaderObject == nullptr) {
            continue;
        }
        if (shaderObject->attachmentCount > 0) {
            --shaderObject->attachmentCount;
        }
        if (shaderObject->deleteRequested && shaderObject->attachmentCount == 0) {
            impl_->objects->shaders().erase(shaderId);
        }
    }
    impl_->objects->programs().erase(program);
    return true;
}

bool GLContext::isProgram(GLuint program) const {
    return impl_->objects->programs().contains(program);
}

bool GLContext::attachShader(GLuint program, GLuint shader) {
    GLProgramObject* programObject = impl_->objects->programs().get(program);
    GLShaderObject* shaderObject = impl_->objects->shaders().get(shader);
    if (programObject == nullptr || shaderObject == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (std::find(programObject->attachedShaders.begin(), programObject->attachedShaders.end(), shader) !=
        programObject->attachedShaders.end()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    programObject->attachedShaders.push_back(shader);
    // See `GLShaderObject::attachmentCount` in GLObjectStore.h. This counter
    // is the entire reason the deferred-erase path works: it pins the shader
    // object in the store across the (engine-scope) glDeleteShader call so
    // glLinkProgram can still see the compiled SPIR-V and the real
    // compileLog when something fails.
    ++shaderObject->attachmentCount;
    return true;
}

bool GLContext::detachShader(GLuint program, GLuint shader) {
    GLProgramObject* programObject = impl_->objects->programs().get(program);
    if (programObject == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    auto it = std::find(programObject->attachedShaders.begin(), programObject->attachedShaders.end(), shader);
    if (it == programObject->attachedShaders.end()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    programObject->attachedShaders.erase(it);
    // Mirror the attach-time increment, then perform the deferred erase if
    // both conditions are now met (delete was requested earlier and this was
    // the last live attachment). The shader object pointer must be looked up
    // *before* the potential erase, otherwise the dereference of a stale
    // entry would race with the table mutation.
    GLShaderObject* shaderObject = impl_->objects->shaders().get(shader);
    if (shaderObject != nullptr) {
        if (shaderObject->attachmentCount > 0) {
            --shaderObject->attachmentCount;
        }
        if (shaderObject->deleteRequested && shaderObject->attachmentCount == 0) {
            impl_->objects->shaders().erase(shader);
        }
    }
    return true;
}

// ── GLSL source parsing helpers for UBO metadata recovery ──
//
// SPIRV-Cross loses certain GLSL-level metadata when emitting SPIR-V for
// uniform blocks. Two known gaps:
//
// 1. Instance names: SPIRV-Cross's `ubo.name` == type name for both
//    instanced (`uniform B { ... } b;`) and non-instanced (`uniform B { ... };`)
//    blocks. We parse the GLSL source for `} instanceName;` to recover this.
//
// 2. Bool types: SPIR-V represents `bool` in interface blocks as `uint`
//    (OpTypeBool cannot appear in storage interfaces). We scan the block
//    body for `bool`/`bvec2`/`bvec3`/`bvec4` member declarations to
//    restore the original GL type.

// Find the body of `uniform <blockName> { ... }` in GLSL source.
// Returns (bodyStart, bodyEnd) — the byte range INSIDE the braces, or
// (npos, npos) if not found.
static std::pair<std::size_t, std::size_t>
findBlockBody(const std::string& source, const std::string& blockName) {
    // Try `uniform <block>` (UBO), `buffer <block>` (SSBO), and
    // `out <block>` (interface-block varyings like
    // `out Color { ... } vs_color;`). A block type name is scoped
    // per-keyword so the first match of any combination is correct.
    const std::array<std::string, 3> tokens = {
        std::string("uniform ") + blockName,
        std::string("buffer ") + blockName,
        std::string("out ") + blockName,
    };
    for (const auto& token : tokens) {
        std::size_t pos = 0;
        while (pos < source.size()) {
            pos = source.find(token, pos);
            if (pos == std::string::npos) break;
            std::size_t end = pos + token.size();
            if (end < source.size() &&
                (std::isalnum(static_cast<unsigned char>(source[end])) || source[end] == '_')) {
                pos = end;
                continue;
            }
            std::size_t bracePos = source.find('{', end);
            if (bracePos == std::string::npos) break;
            int depth = 1;
            std::size_t cur = bracePos + 1;
            while (cur < source.size() && depth > 0) {
                if (source[cur] == '{') ++depth;
                else if (source[cur] == '}') --depth;
                ++cur;
            }
            // cur is right after the closing '}'. Body is [bracePos+1, cur-2].
            return {bracePos + 1, cur - 1};
        }
    }
    return {std::string::npos, std::string::npos};
}

// Strip line + block comments from GLSL source. Used as input to the
// layout(binding=N) scanner below so that commented-out layout
// qualifiers don't get matched.
static std::string stripGlslComments(const std::string& source) {
    std::string s;
    s.reserve(source.size());
    for (std::size_t i = 0; i < source.size(); ) {
        if (i + 1 < source.size() && source[i] == '/' && source[i + 1] == '/') {
            while (i < source.size() && source[i] != '\n') ++i;
        } else if (i + 1 < source.size() && source[i] == '/' && source[i + 1] == '*') {
            i += 2;
            while (i + 1 < source.size() && !(source[i] == '*' && source[i + 1] == '/')) ++i;
            if (i + 1 < source.size()) i += 2;
        } else {
            s += source[i];
            ++i;
        }
    }
    return s;
}

// Parse `layout(binding = N) ... uniform <sampler|image>Type <name>[...];`
// declarations out of the comment-stripped GLSL source. Returns a map
// from sampler uniform name to its explicit binding index.
//
// This is the source-of-truth for "did the user write layout(binding)"
// because glslang auto-assigns DecorationBinding on every sampler
// variable regardless of whether the GLSL had an explicit qualifier —
// see bd73acc / 9c496f4 where the previous attempts relied on
// SPIRV-Cross's `has_decoration(id, DecorationBinding)` and that
// returned true for both auto-assigned and user-declared bindings,
// which wrecked pixelstoragemodes (samplers without explicit bindings
// got shifted to non-zero units).
//
// Parser approach: bespoke scan rather than <regex> for determinism
// and to avoid C++ regex overhead. Handles:
//   layout(binding = 5) uniform sampler2D foo;
//   layout(binding=5) uniform sampler2D foo;
//   layout(binding = 5, location = 2) uniform sampler2D foo;
//   layout(location = 2, binding = 5) uniform highp sampler2D foo;
//   layout(binding=5) uniform sampler2D foo[3];
// Does NOT handle macro-expanded names, preprocessor conditionals that
// leave declarations out, or GLSL #version gates — if those ever matter
// we add them in a follow-up.
static std::unordered_map<std::string, GLuint>
parseExplicitSamplerBindings(const std::string& rawSource) {
    std::unordered_map<std::string, GLuint> result;
    const std::string s = stripGlslComments(rawSource);

    auto isIdentChar = [](char c) -> bool {
        return std::isalnum(static_cast<unsigned char>(c)) || c == '_';
    };

    // Sprint 8 B Cluster F F1 (CKPT73): scan for `#define NAME VALUE`
    // directives (integer-constant style only) so `layout(binding=NAME)`
    // can be resolved against the macro table. CTS layout_binding.*
    // binding_integer_constant tests use exactly this shape:
    //   #define INT_CONST 7
    //   layout(binding=INT_CONST) uniform sampler2D s;
    // Pre-fix: parser saw 'INT_CONST' as non-numeric → bail → no binding.
    // Limited to integer-literal #defines (no expression evaluation;
    // no nested macro substitution) — covers CTS shape.
    std::unordered_map<std::string, long> defineTable;
    {
        std::size_t p = 0;
        while (p < s.size()) {
            const auto hashPos = s.find('#', p);
            if (hashPos == std::string::npos) break;
            // Word-boundary on left.
            if (hashPos > 0 && isIdentChar(s[hashPos - 1])) {
                p = hashPos + 1;
                continue;
            }
            std::size_t after = hashPos + 1;
            while (after < s.size() && (s[after] == ' ' || s[after] == '\t')) ++after;
            if (after + 6 <= s.size() && s.compare(after, 6, "define") == 0 &&
                (after + 6 >= s.size() || !isIdentChar(s[after + 6]))) {
                std::size_t cur = after + 6;
                while (cur < s.size() && (s[cur] == ' ' || s[cur] == '\t')) ++cur;
                const std::size_t nameStart = cur;
                while (cur < s.size() && isIdentChar(s[cur])) ++cur;
                if (cur > nameStart) {
                    std::string name = s.substr(nameStart, cur - nameStart);
                    while (cur < s.size() && (s[cur] == ' ' || s[cur] == '\t')) ++cur;
                    char* endp = nullptr;
                    const long val = std::strtol(s.c_str() + cur, &endp, 0);
                    if (endp != s.c_str() + cur && val >= 0) {
                        defineTable[name] = val;
                    }
                }
            }
            p = hashPos + 1;
        }
    }
    auto skipWhitespace = [&](std::size_t& i) {
        while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
    };

    std::size_t pos = 0;
    while (pos < s.size()) {
        const auto layoutPos = s.find("layout", pos);
        if (layoutPos == std::string::npos) break;

        // Word boundary before / after "layout".
        if (layoutPos > 0 && isIdentChar(s[layoutPos - 1])) {
            pos = layoutPos + 1;
            continue;
        }
        std::size_t after = layoutPos + 6;
        skipWhitespace(after);
        if (after >= s.size() || s[after] != '(') {
            pos = layoutPos + 1;
            continue;
        }

        // Find matching ')'.
        int depth = 0;
        std::size_t closeIdx = after;
        for (; closeIdx < s.size(); ++closeIdx) {
            if (s[closeIdx] == '(') ++depth;
            else if (s[closeIdx] == ')') {
                if (--depth == 0) break;
            }
        }
        if (closeIdx >= s.size()) {
            pos = layoutPos + 1;
            continue;
        }
        const std::string body = s.substr(after + 1, closeIdx - after - 1);

        // Extract `binding = N` from the layout body. Word-boundary
        // match so `decl_binding` or similar doesn't trigger.
        int binding = -1;
        std::size_t bPos = 0;
        while ((bPos = body.find("binding", bPos)) != std::string::npos) {
            if (bPos > 0 && isIdentChar(body[bPos - 1])) {
                bPos += 1;
                continue;
            }
            std::size_t eqPos = bPos + 7;
            while (eqPos < body.size() && std::isspace(static_cast<unsigned char>(body[eqPos]))) ++eqPos;
            if (eqPos < body.size() && body[eqPos] == '=') {
                ++eqPos;
                while (eqPos < body.size() && std::isspace(static_cast<unsigned char>(body[eqPos]))) ++eqPos;
                char* endp = nullptr;
                // Sprint 8 B Cluster F F1 (CKPT73): GLSL §4.3 integer
                // literal syntax follows C — `0` prefix = octal, `0x`
                // prefix = hex, otherwise decimal. CTS layout_binding.*
                // exercises `layout(binding=047)` (octal 047 = decimal
                // 39). Use strtol base 0 to auto-detect octal/hex/dec
                // per the GLSL spec. Pre-fix: decimal-only parse turned
                // 047 into 47, breaking `layout_binding.sampler2D_*` etc.
                const long val = std::strtol(body.c_str() + eqPos, &endp, 0);
                if (endp != body.c_str() + eqPos && val >= 0) {
                    binding = static_cast<int>(val);
                } else {
                    // Try resolving as a #define identifier (CTS
                    // binding_integer_constant tests use this shape).
                    std::size_t idStart = eqPos;
                    while (idStart < body.size() &&
                           std::isspace(static_cast<unsigned char>(body[idStart]))) ++idStart;
                    std::size_t idEnd = idStart;
                    while (idEnd < body.size() && isIdentChar(body[idEnd])) ++idEnd;
                    if (idEnd > idStart) {
                        std::string ident = body.substr(idStart, idEnd - idStart);
                        auto dIt = defineTable.find(ident);
                        if (dIt != defineTable.end()) {
                            binding = static_cast<int>(dIt->second);
                        }
                    }
                }
            }
            break;
        }

        if (binding >= 0) {
            // Scan post-`)` for `[memory-qual]* [uniform]? [memory-qual]* [precision]? sampler-type name`.
            //
            // Sprint 8 B Cluster F F1 Day 8 (CKPT80): GL §4.10 image
            // memory qualifiers (`readonly`, `writeonly`, `coherent`,
            // `volatile`, `restrict`) can appear in any order around
            // `uniform`. CTS layout_binding.image2D_* generates
            // `layout(binding=3, rgba8) readonly uniform image2D image0;`
            // — `readonly` is BEFORE `uniform`. Pre-CKPT80 parser only
            // accepted `uniform [precision]? type name` and bailed when
            // the next token after `)` was `readonly`. Now we loop
            // skipping any combination of memory/precision/uniform
            // qualifiers until we hit the actual type token.
            std::size_t cur = closeIdx + 1;
            skipWhitespace(cur);
            const char* const skippableQualifiers[] = {
                "uniform",
                "highp", "mediump", "lowp",
                "readonly", "writeonly", "coherent", "volatile", "restrict",
            };
            bool advanced = true;
            while (advanced) {
                advanced = false;
                for (const char* kw : skippableQualifiers) {
                    const std::size_t klen = std::strlen(kw);
                    if (cur + klen <= s.size() &&
                        s.compare(cur, klen, kw) == 0 &&
                        (cur + klen >= s.size() || !isIdentChar(s[cur + klen]))) {
                        cur += klen;
                        skipWhitespace(cur);
                        advanced = true;
                        break;
                    }
                }
            }
            // Read the type name (must contain "sampler" / "image" /
            // case-insensitive `Sampler`).
            const std::size_t typeStart = cur;
            while (cur < s.size() && isIdentChar(s[cur])) ++cur;
            const std::string typeName = s.substr(typeStart, cur - typeStart);
            // Sprint 8 B Cluster F F1 (CKPT73): also recognise
            // `atomic_uint` as an opaque uniform type for binding
            // resolution. CTS layout_binding.atomic_uint_* exercises
            // `layout(binding=N) uniform atomic_uint cnt;` which the
            // GL 4.2 §7.6 spec puts in the same `layout(binding=N)`
            // family as samplers and images.
            const bool isOpaqueType =
                typeName.find("sampler") != std::string::npos ||
                typeName.find("Sampler") != std::string::npos ||
                typeName.find("image") != std::string::npos ||
                typeName.find("Image") != std::string::npos ||
                typeName == "atomic_uint";
            if (isOpaqueType) {
                skipWhitespace(cur);
                const std::size_t nameStart = cur;
                while (cur < s.size() && isIdentChar(s[cur])) ++cur;
                if (cur > nameStart) {
                    std::string name = s.substr(nameStart, cur - nameStart);
                    result[std::move(name)] = static_cast<GLuint>(binding);
                }
            }
        }

        pos = closeIdx + 1;
    }
    return result;
}

static bool glslBlockHasInstanceName(const std::string& source,
                                      const std::string& blockName) {
    auto [bodyStart, bodyEnd] = findBlockBody(source, blockName);
    if (bodyStart == std::string::npos) return false;
    // bodyEnd points at the '}'. Skip whitespace after it.
    std::size_t cur = bodyEnd + 1;
    while (cur < source.size() &&
           (source[cur] == ' ' || source[cur] == '\t' ||
            source[cur] == '\n' || source[cur] == '\r')) {
        ++cur;
    }
    return cur < source.size() && (std::isalpha(source[cur]) || source[cur] == '_');
}

// If an interface block `layout(...) uniform <blockName> { ... } <inst>[N];`
// is declared with an instance name, return the instance name; otherwise
// return an empty string. Used by the PIQ reflection path to gate the
// per-instance active flag on whether the stage's source actually
// references a specific `<inst>[i]` element.
static std::string glslBlockInstanceName(const std::string& source,
                                          const std::string& blockName) {
    auto [bodyStart, bodyEnd] = findBlockBody(source, blockName);
    if (bodyStart == std::string::npos) return {};
    std::size_t cur = bodyEnd + 1;
    while (cur < source.size() &&
           (source[cur] == ' ' || source[cur] == '\t' ||
            source[cur] == '\n' || source[cur] == '\r')) {
        ++cur;
    }
    if (cur >= source.size() ||
        !(std::isalpha(static_cast<unsigned char>(source[cur])) || source[cur] == '_')) {
        return {};
    }
    std::size_t identStart = cur;
    while (cur < source.size() &&
           (std::isalnum(static_cast<unsigned char>(source[cur])) || source[cur] == '_')) {
        ++cur;
    }
    return source.substr(identStart, cur - identStart);
}

// Walk the source for `<instance>[N]` tokens (word-bounded on the left
// side so we don't match inside longer identifiers). Returns the set of
// integer indices used — for a block declared as `} e[4];`, an FS body
// that reads `e[0]` and `e[2]` returns `{0, 2}`. Block elements at
// indices not in this set are spec-correctly "inactive" with respect to
// that stage.
static std::set<int> glslActiveInstanceIndices(const std::string& source,
                                                const std::string& instanceName) {
    std::set<int> used;
    if (instanceName.empty()) return used;
    const std::size_t ilen = instanceName.size();
    std::size_t pos = 0;
    while ((pos = source.find(instanceName, pos)) != std::string::npos) {
        const bool leftBoundary = (pos == 0) ||
            !(std::isalnum(static_cast<unsigned char>(source[pos - 1])) || source[pos - 1] == '_');
        const std::size_t after = pos + ilen;
        const bool openBracket = after < source.size() && source[after] == '[';
        if (leftBoundary && openBracket) {
            // Walk to matching ']' capturing a pure-digit index.
            std::size_t idxStart = after + 1;
            // Skip leading whitespace inside the brackets.
            while (idxStart < source.size() &&
                   (source[idxStart] == ' ' || source[idxStart] == '\t')) {
                ++idxStart;
            }
            std::size_t idxEnd = idxStart;
            while (idxEnd < source.size() &&
                   std::isdigit(static_cast<unsigned char>(source[idxEnd]))) {
                ++idxEnd;
            }
            if (idxEnd > idxStart) {
                // Following character must close the bracket (allow
                // trailing whitespace before `]`).
                std::size_t tail = idxEnd;
                while (tail < source.size() &&
                       (source[tail] == ' ' || source[tail] == '\t')) {
                    ++tail;
                }
                if (tail < source.size() && source[tail] == ']') {
                    int value = static_cast<int>(std::stoi(
                        source.substr(idxStart, idxEnd - idxStart)));
                    used.insert(value);
                }
            }
        }
        pos += ilen;
    }
    return used;
}

// GL 4.0 subroutine declarations (GLSL 4.00+, §4.4.4).  A focused source-
// text scanner: the main GLSLReflection only handles `uniform` / `in` /
// `out` / `attribute` / `varying`, which miss every subroutine form.
// Three GLSL shapes to distinguish (case-sensitive keyword `subroutine`):
//
//   subroutine <rettype> <typeName> ( <params> ) ;
//         → subroutine type prototype (non-resource; we only record the
//           type name for later compatibility lookup).
//   subroutine uniform <typeName> <uniName> [ [<N>] ] ;
//         → subroutine uniform (becomes a GL_*_SUBROUTINE_UNIFORM
//           resource).
//   subroutine ( <typeList> ) <rettype> <funcName> ( <params> ) { ... }
//         → subroutine implementation (becomes a GL_*_SUBROUTINE resource).
//           The type list names all subroutine types this impl is
//           compatible with — drives GL_COMPATIBLE_SUBROUTINES on the
//           matching uniform entries.
//
// Results: per stage, fills `outImpls` (subroutine implementations) and
// `outUniforms` (subroutine uniforms with their activeVariables populated
// with the indices of compatible impls).  Best-effort parser — the scanner
// assumes a well-formed shader and stops at the first `}` at top-level to
// bound function bodies. Not exhaustive vs. arbitrary GLSL but covers CTS
// `program_interface_query.subroutines-*`.
static void scanSubroutineDeclarations(
    const std::string& sourceIn,
    std::vector<GLProgramResourceEntry>& outImpls,
    std::vector<GLProgramResourceEntry>& outUniforms) {
    // Strip comments first so keyword matches inside strings / comments
    // don't trip the scanner.
    auto strip = [](const std::string& s) {
        std::string out;
        out.reserve(s.size());
        for (std::size_t i = 0; i < s.size();) {
            if (i + 1 < s.size() && s[i] == '/' && s[i + 1] == '/') {
                while (i < s.size() && s[i] != '\n') ++i;
            } else if (i + 1 < s.size() && s[i] == '/' && s[i + 1] == '*') {
                i += 2;
                while (i + 1 < s.size() && !(s[i] == '*' && s[i + 1] == '/')) ++i;
                if (i + 1 < s.size()) i += 2;
            } else {
                out += s[i++];
            }
        }
        return out;
    };
    const std::string src = strip(sourceIn);

    auto isIdentChar = [](unsigned char c) {
        return std::isalnum(c) || c == '_';
    };
    auto skipWs = [&](std::size_t& p) {
        while (p < src.size() && std::isspace(static_cast<unsigned char>(src[p]))) ++p;
    };
    auto readIdent = [&](std::size_t& p) -> std::string {
        skipWs(p);
        const std::size_t start = p;
        while (p < src.size() && isIdentChar(static_cast<unsigned char>(src[p]))) ++p;
        return src.substr(start, p - start);
    };

    // Map: compatibility-type name → list of impl-resource indices.
    std::unordered_map<std::string, std::vector<GLint>> typeToImpls;
    // Parallel to outUniforms: the subroutine-type name each uniform
    // points at (resolved to activeVariables after the main scan).
    std::vector<std::string> pendingUniformTypes;

    const std::string kw = "subroutine";
    std::size_t pos = 0;
    while ((pos = src.find(kw, pos)) != std::string::npos) {
        const bool leftBoundary = (pos == 0) ||
            !isIdentChar(static_cast<unsigned char>(src[pos - 1]));
        const bool rightBoundary = (pos + kw.size() < src.size()) &&
            !isIdentChar(static_cast<unsigned char>(src[pos + kw.size()]));
        if (!leftBoundary || !rightBoundary) {
            pos += kw.size();
            continue;
        }
        // Check for a preceding `layout(location = N)` qualifier on
        // the subroutine-uniform declaration. GL 4.2
        // `layout(location=N) subroutine uniform ...` lets the app
        // pin the subroutine-uniform location. Walk backwards from
        // `pos` past whitespace and inspect the balanced
        // `layout(...)` block if present.
        GLint explicitLocation = -1;
        {
            std::size_t back = pos;
            while (back > 0 && std::isspace(static_cast<unsigned char>(src[back - 1]))) --back;
            if (back > 0 && src[back - 1] == ')') {
                // Find matching '('.
                int pd = 1;
                std::size_t bp = back - 1;
                while (bp > 0 && pd > 0) {
                    --bp;
                    if (src[bp] == ')') ++pd;
                    else if (src[bp] == '(') --pd;
                }
                if (pd == 0 && bp >= 6) {
                    std::size_t lp = bp;
                    while (lp > 0 && std::isspace(static_cast<unsigned char>(src[lp - 1]))) --lp;
                    if (lp >= 6 && src.compare(lp - 6, 6, "layout") == 0) {
                        // Parse "location = N" inside the parens.
                        std::size_t inner = bp + 1;
                        std::size_t innerEnd = back - 1;
                        std::string content = src.substr(inner, innerEnd - inner);
                        std::size_t loc = content.find("location");
                        if (loc != std::string::npos) {
                            std::size_t eq = content.find('=', loc);
                            if (eq != std::string::npos) {
                                std::size_t nb = eq + 1;
                                while (nb < content.size() &&
                                       std::isspace(static_cast<unsigned char>(content[nb]))) ++nb;
                                std::size_t ne = nb;
                                while (ne < content.size() &&
                                       (std::isdigit(static_cast<unsigned char>(content[ne])) ||
                                        content[ne] == 'x' || content[ne] == 'X')) ++ne;
                                if (ne > nb) {
                                    explicitLocation = static_cast<GLint>(
                                        std::strtol(content.substr(nb, ne - nb).c_str(), nullptr, 0));
                                }
                            }
                        }
                    }
                }
            }
        }
        std::size_t p = pos + kw.size();
        skipWs(p);

        // Three shapes: `uniform`, `(`, or plain identifier.
        if (p < src.size() && src[p] == '(') {
            // Subroutine implementation: `subroutine ( typeList ) rettype name() { ... }`.
            ++p;  // skip '('
            std::vector<std::string> typeList;
            while (p < src.size() && src[p] != ')') {
                skipWs(p);
                if (p < src.size() && src[p] == ')') break;
                std::string t = readIdent(p);
                if (!t.empty()) typeList.push_back(std::move(t));
                skipWs(p);
                if (p < src.size() && src[p] == ',') ++p;
            }
            if (p < src.size() && src[p] == ')') ++p;
            // Parse rettype and function name.
            std::string retType = readIdent(p);
            (void)retType;
            std::string fnName = readIdent(p);
            if (fnName.empty()) { pos = p; continue; }
            // Skip past the parameter list ( ... ) and find the body {.
            skipWs(p);
            if (p < src.size() && src[p] == '(') {
                int pd = 1; ++p;
                while (p < src.size() && pd > 0) {
                    if (src[p] == '(') ++pd;
                    else if (src[p] == ')') --pd;
                    ++p;
                }
            }
            // Push impl entry.
            GLProgramResourceEntry entry;
            entry.name = fnName;
            entry.type = 0;           // subroutines have no scalar type
            entry.location = -1;      // not location-addressable
            entry.arraySize = 1;
            const GLint implIdx = static_cast<GLint>(outImpls.size());
            outImpls.push_back(std::move(entry));
            // Register this impl as compatible with each type in the list.
            for (const auto& t : typeList) {
                typeToImpls[t].push_back(implIdx);
            }
            pos = p;
            continue;
        }

        // Check for `uniform` keyword.
        std::string next = readIdent(p);
        if (next == "uniform") {
            // Subroutine uniform: `subroutine uniform <typeName> <uniName> [ [N] ] ;`.
            std::string typeName = readIdent(p);
            std::string uniName = readIdent(p);
            if (uniName.empty() || typeName.empty()) { pos = p; continue; }
            GLint arraySize = 1;
            bool isArray = false;
            skipWs(p);
            if (p < src.size() && src[p] == '[') {
                ++p;
                skipWs(p);
                const std::size_t nStart = p;
                while (p < src.size() &&
                       std::isdigit(static_cast<unsigned char>(src[p]))) ++p;
                if (p > nStart) {
                    arraySize = std::atoi(src.substr(nStart, p - nStart).c_str());
                }
                skipWs(p);
                if (p < src.size() && src[p] == ']') ++p;
                isArray = true;
            }
            GLProgramResourceEntry entry;
            // GL 4.6 §7.3.1: array uniforms (including subroutine
            // array uniforms) report the canonical "[0]" suffix.
            entry.name = isArray ? (uniName + "[0]") : uniName;
            entry.type = 0;  // subroutine uniforms have no scalar type
            // GL 4.2 `layout(location=N) subroutine uniform …` pins
            // the uniform's location. Fall back to sequential
            // assignment when no explicit location is given.
            entry.location = explicitLocation >= 0
                ? explicitLocation
                : static_cast<GLint>(outUniforms.size());
            entry.arraySize = arraySize;
            entry.isArray = isArray;
            outUniforms.push_back(std::move(entry));
            // Record the subroutine-type name for post-scan
            // resolution into activeVariables (compatible-subroutine
            // indices).
            pendingUniformTypes.push_back(typeName);
            pos = p;
            continue;
        }

        // Otherwise: subroutine type prototype — e.g. `subroutine vec4 a_t();`.
        // `next` is the return-type word. Read the type name next.
        std::string typeName = readIdent(p);
        (void)typeName;
        // No action — types are resolved via `subroutine uniform <type> …`
        // and `subroutine(<type>) …` matches.
        pos = p;
    }

    // Second pass: resolve each subroutine uniform's compatibleSubroutines
    // list from `typeToImpls` using the sibling `pendingUniformTypes`.
    for (std::size_t u = 0; u < pendingUniformTypes.size() && u < outUniforms.size(); ++u) {
        const std::string& typeName = pendingUniformTypes[u];
        auto it = typeToImpls.find(typeName);
        if (it != typeToImpls.end()) {
            outUniforms[u].activeVariables = it->second;
        }
    }
}

// Search a code region for "boolType name" where boolType is bool/bvec2/3/4.
// Returns the GL_BOOL* enum, or 0 if not found.
static GLenum searchForBoolType(std::string_view body, std::string_view name) {
    struct BoolMapping { const char* keyword; GLenum type; };
    static const BoolMapping mappings[] = {
        {"bvec4", GL_BOOL_VEC4},
        {"bvec3", GL_BOOL_VEC3},
        {"bvec2", GL_BOOL_VEC2},
        {"bool",  GL_BOOL},
    };
    for (const auto& m : mappings) {
        std::string pattern = std::string(m.keyword) + " " + std::string(name);
        auto fpos = body.find(pattern);
        if (fpos != std::string_view::npos) {
            std::size_t afterPattern = fpos + pattern.size();
            if (afterPattern >= body.size() ||
                body[afterPattern] == ';' || body[afterPattern] == '[' ||
                body[afterPattern] == ' ' || body[afterPattern] == '\n' ||
                body[afterPattern] == '\r') {
                return m.type;
            }
        }
    }
    return 0;
}

// Detect bool/bvec member types that SPIR-V represents as uint/uvec.
// Returns the correct GL_BOOL* type, or 0 if the member is not a bool type.
//
// For direct block members (no dots in name), we search within the block body.
// For nested struct members ("s.c"), we resolve through the struct chain:
// find the struct type name for each prefix component, then search the
// innermost struct body for the leaf name.
// Strip single-line comments ("// ...") from GLSL source. This prevents
// member-name searches from matching inside comments like "// unused in
// vertex shader" where a stray " i" would be misidentified as a declaration.
static std::string stripGLSLComments(std::string_view src) {
    std::string out;
    out.reserve(src.size());
    for (std::size_t i = 0; i < src.size(); ++i) {
        if (i + 1 < src.size() && src[i] == '/' && src[i+1] == '/') {
            // Skip to end of line
            while (i < src.size() && src[i] != '\n') ++i;
            if (i < src.size()) out += '\n';
        } else {
            out += src[i];
        }
    }
    return out;
}

static GLenum detectBoolMemberType(const std::string& source,
                                    const std::string& blockName,
                                    const std::string& memberName) {
    // Work on a comment-stripped copy to avoid false matches in comments.
    const std::string cleanSource = stripGLSLComments(source);

    // Split by dots first: "a[0].inner.c" → ["a[0]", "inner", "c"]
    // Array indices are stripped per-component in the traversal loop,
    // NOT up front (to preserve the dot-separated structure).
    std::vector<std::string> parts;
    std::size_t start = 0;
    while (start < memberName.size()) {
        auto dot = memberName.find('.', start);
        if (dot == std::string::npos) {
            parts.push_back(memberName.substr(start));
            break;
        }
        parts.push_back(memberName.substr(start, dot - start));
        start = dot + 1;
    }
    if (parts.empty()) return 0;

    // Strip array suffixes from each part: "a[0]" → "a"
    for (auto& p : parts) {
        auto bracketPos = p.find('[');
        if (bracketPos != std::string::npos) {
            p = p.substr(0, bracketPos);
        }
    }

    // For direct members (single part), search the block body.
    if (parts.size() == 1) {
        auto [bodyStart, bodyEnd] = findBlockBody(cleanSource, blockName);
        if (bodyStart == std::string::npos) return 0;
        std::string_view body(cleanSource.data() + bodyStart, bodyEnd - bodyStart);
        return searchForBoolType(body, parts[0]);
    }

    // For nested members, traverse the struct chain.
    // Start with the block body, find the type of each prefix, then
    // search the struct definition for the next component.
    auto [bodyStart, bodyEnd] = findBlockBody(cleanSource, blockName);
    if (bodyStart == std::string::npos) return 0;
    std::string_view searchBody(cleanSource.data() + bodyStart, bodyEnd - bodyStart);

    for (std::size_t i = 0; i < parts.size() - 1; ++i) {
        // Find the type name for part[i] in the current body.
        // Pattern: "<TypeName> <partName>" or "<TypeName> <partName>[...]"
        // We need to extract the type name that precedes the member name.
        const std::string& partName = parts[i];
        // Search for " partName" (with space before) to find declarations.
        // Require a word boundary after the name (;, [, space, newline)
        // to avoid matching "i" inside "ivec4" etc.
        std::string needle = " " + partName;
        std::string_view::size_type pos = std::string_view::npos;
        {
            std::string_view::size_type searchFrom = 0;
            while (searchFrom < searchBody.size()) {
                auto candidate = searchBody.find(needle, searchFrom);
                if (candidate == std::string_view::npos) break;
                std::size_t afterName = candidate + needle.size();
                if (afterName >= searchBody.size() ||
                    searchBody[afterName] == ';' || searchBody[afterName] == '[' ||
                    searchBody[afterName] == ' ' || searchBody[afterName] == '\n' ||
                    searchBody[afterName] == '\r' || searchBody[afterName] == '\t') {
                    pos = candidate;
                    break;
                }
                searchFrom = candidate + 1;
            }
        }
        if (pos == std::string_view::npos) return 0;
        // Walk backwards from the match to find the type name.
        // Skip whitespace backwards, then collect identifier chars.
        auto typeEnd = pos;
        while (typeEnd > 0 && searchBody[typeEnd - 1] == ' ') --typeEnd;
        auto typeStart = typeEnd;
        while (typeStart > 0 && (std::isalnum(searchBody[typeStart - 1]) || searchBody[typeStart - 1] == '_')) --typeStart;
        std::string typeName(searchBody.substr(typeStart, typeEnd - typeStart));
        if (typeName.empty()) return 0;
        // Find the struct definition for this type.
        std::string structToken = "struct " + typeName;
        auto structPos = cleanSource.find(structToken);
        if (structPos == std::string::npos) return 0;
        auto bracePos = cleanSource.find('{', structPos);
        if (bracePos == std::string::npos) return 0;
        int depth = 1;
        auto cur = bracePos + 1;
        while (cur < cleanSource.size() && depth > 0) {
            if (cleanSource[cur] == '{') ++depth;
            else if (cleanSource[cur] == '}') --depth;
            ++cur;
        }
        searchBody = std::string_view(cleanSource.data() + bracePos + 1, cur - bracePos - 2);
    }

    // Search the final body for the leaf member name.
    return searchForBoolType(searchBody, parts.back());
}

bool GLContext::linkProgram(GLuint program) {
    GLProgramObject* programObject = impl_->objects->programs().get(program);
    if (programObject == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // Phase 8X Group 4d follow-up²³ — link-path crash-site instrumentation.
    // The fw²² smoke identified Spring's Sky shader (program 28) SIGABRT'ing
    // between the `compileGLSLProgram` NSLog and the final `linkProgram`
    // NSLog. All Metal pipeline work (`newLibraryWithSource`,
    // `newRenderPipelineStateWithDescriptor`) lives in `MetalFrameGraph.mm`
    // and is only reached at draw time — so the only work between those two
    // log lines is glslang cross-stage link + SPIRV-Cross spirvToMSL/reflect.
    // These markers bracket each sub-step so BAR's crash handler can tell
    // which one is the last to run before abort. Each marker is followed by
    // an explicit `fflush(stderr)` to survive the libunwind double-abort that
    // fw²² verification §5.3 documented (`fsync(STDERR_FILENO)` Spring-side
    // fix is separate and still deferred).
    APPGL_LOG(SHADER, @"[GL] linkProgram-begin program=%u", program);
    fflush(stderr);

    programObject->uniforms.clear();
    programObject->attributes.clear();
    programObject->uniformValues.clear();
    programObject->linkLog.clear();
    programObject->linked = false;

    // RC-D09: Clear resource tables from any previous link so stale
    // introspection data never survives a failed re-link.
    programObject->resourceUniforms.clear();
    programObject->resourceUniformBlocks.clear();
    programObject->resourceInputs.clear();
    programObject->resourceOutputs.clear();
    programObject->resourceStorageBlocks.clear();
    programObject->resourceAtomicCounterBuffers.clear();
    programObject->resourceBufferVariables.clear();
    programObject->resourceTransformFeedbackVaryings.clear();
    programObject->resourceTransformFeedbackBuffers.clear();
    programObject->ssboBindingRemap.clear();
    programObject->samplerExplicitBindings.clear();

    // Small helper used in several diagnostic-recording sites below.
    const std::string programTag = "program-" + std::to_string(program);
    auto quickHash = [](const std::string& s) -> std::string {
        std::size_t h = std::hash<std::string>{}(s);
        char buf[18];
        std::snprintf(buf, sizeof(buf), "%016zx", h);
        return buf;
    };

    if (programObject->attachedShaders.empty()) {
        programObject->linkLog = "no shaders attached";
        Runtime::shared().recordShaderTranslation({
            programTag, "link", "", "", "", programObject->linkLog, "", false
        });
        return false;
    }

    // Classify the attached stages. Pointers stay null when a stage isn't
    // present. Everything downstream dispatches on which pointers are set
    // rather than re-scanning the attached list.
    GLShaderObject* vertexShader = nullptr;
    GLShaderObject* fragmentShader = nullptr;
    GLShaderObject* computeShader = nullptr;
    GLShaderObject* geometryShader = nullptr;
    GLShaderObject* tessControlShader = nullptr;
    GLShaderObject* tessEvalShader = nullptr;
    int shaderCount = 0;

    for (GLuint shaderId : programObject->attachedShaders) {
        GLShaderObject* shaderObject = impl_->objects->shaders().get(shaderId);
        // Under deferred-erase semantics (see GLObjectStore.h::GLShaderObject)
        // a nullptr lookup here is essentially unreachable from real engine
        // code — glAttachShader rejects unknown IDs upfront, the attachment
        // count keeps the shader resident across glDeleteShader, and a
        // detach pulls the ID out of attachedShaders before the maybe-erase
        // pass. The check is left for defence in depth. The remaining real
        // failure mode is `!shaderObject->compiled`, which now reliably
        // carries the real glslang `compileLog` text through to the
        // diagnostic ring (the upstream `compileShader` call also pushes a
        // `stage: "compile"` record with the same log, but the link-time
        // record makes the failure visible at the program level too).
        if (shaderObject == nullptr || !shaderObject->compiled) {
            programObject->linkLog = "attached shader is not compiled";
            const std::string log = shaderObject
                ? shaderObject->compileLog
                : programObject->linkLog;
            Runtime::shared().recordShaderTranslation({
                programTag, "link", "", "", "", log, "", false
            });
            return false;
        }
        ++shaderCount;
        switch (shaderObject->stage) {
            case GL_VERTEX_SHADER:          vertexShader = shaderObject; break;
            case GL_FRAGMENT_SHADER:        fragmentShader = shaderObject; break;
            case GL_COMPUTE_SHADER:         computeShader = shaderObject; break;
            case GL_GEOMETRY_SHADER:        geometryShader = shaderObject; break;
            case GL_TESS_CONTROL_SHADER:    tessControlShader = shaderObject; break;
            case GL_TESS_EVALUATION_SHADER: tessEvalShader = shaderObject; break;
            default: break;
        }
        appendDeclarationsAsUniforms(programObject->uniforms, shaderObject->declaredUniforms);

        // GL 4.2 §7.6: harvest `layout(binding = N)` from the original
        // GLSL source across every attached shader. The map is used at
        // draw-time to substitute the declared unit for any sampler
        // uniform the application hasn't explicitly glUniform1i'd.
        // Later-stage declarations override earlier ones if names
        // collide — safe in practice because the same sampler name in
        // multiple stages must refer to the same resource by GL's
        // cross-stage interface rules.
        auto stageBindings = parseExplicitSamplerBindings(shaderObject->source);
        for (auto& [name, binding] : stageBindings) {
            programObject->samplerExplicitBindings[name] = binding;
        }
    }

    // Build the vertex attribute table from the scanner's declared inputs
    // on the vertex stage. The scanner-driven path honours
    // glBindAttribLocation requests (via requestedAttribLocations) which
    // SPIRV-Cross reflection cannot see, so we keep it as the authoritative
    // source for attribute locations.
    GLuint nextAttribLocation = 0;
    if (vertexShader != nullptr) {
        for (const auto& input : vertexShader->declaredInputs) {
            GLProgramAttributeInfo attrib;
            attrib.name = input.name;
            attrib.type = input.type;
            attrib.arraySize = input.arraySize;
            attrib.isArray = input.isArray;
            if (input.explicitLocation >= 0) {
                attrib.location = input.explicitLocation;
            } else {
                auto requested = programObject->requestedAttribLocations.find(input.name);
                if (requested != programObject->requestedAttribLocations.end()) {
                    attrib.location = static_cast<GLint>(requested->second);
                } else {
                    attrib.location = static_cast<GLint>(nextAttribLocation);
                }
            }
            // GL 4.6 §11.1.1: array vertex inputs consume arraySize
            // consecutive attribute locations (one per element). SPIRV-
            // Cross's MSL backend expands the array into individual
            // `[[attribute(N)]]` slots so each element needs its own
            // location. Advance `nextAttribLocation` by the full size so
            // the NEXT input lands AFTER the array, not on top of its
            // second element. CTS cull_distance tests have
            //   in float clipdistance_data[1];
            //   in float culldistance_data[8];
            //   in vec2 position;
            // and expect position at MSL attribute(9), not (2). Before
            // this fix, getAttribLocation("position")=2 collided with
            // culldistance_data[1]'s MSL slot.
            const GLuint slotCount = std::max<GLint>(1, input.arraySize);
            if (static_cast<GLuint>(attrib.location) + slotCount > nextAttribLocation) {
                nextAttribLocation = static_cast<GLuint>(attrib.location) + slotCount;
            }
            programObject->attributes.push_back(std::move(attrib));
        }
    }

    // Stage combination must be one of:
    //   - Compute-only                          (1x GL_COMPUTE_SHADER)
    //   - Vertex + Fragment                     (standard raster pipeline)
    //   - Vertex + Geometry + Fragment          (geometry path; emulation gap
    //                                            flagged in translator block)
    //   - Vertex + TessControl + TessEval + F   (tess path, same story)
    //   - Vertex-only / Fragment-only           (separable via
    //                                            glCreateShaderProgramv)
    // Anything else bails. The "unknown combination" branch also records a
    // diagnostic so BAR sees why the program didn't link.
    enum class ProgramKind {
        Unknown,
        Compute,
        VertexFragment,
        VertexGeometryFragment,
        VertexTessellationFragment,
        VertexOnly,
        FragmentOnly,
        GeometryOnly,
        TessControlOnly,
        TessEvalOnly,
        // Sprint 15 Day 18 (CKPT191) — VS+GS no-FS combination.
        // CTS `shader_image_load_store.basic-allTargets-{loadStore,atomic}GS`
        // and SILS GS sister tests build programs with only VS+GS and enable
        // GL_RASTERIZER_DISCARD; image writes happen in the GS body, no
        // rasterisation. Previously rejected as ProgramKind::Unknown at link
        // (see CKPT164 for prior characterization). This kind translates VS
        // standalone, runs GS detection / CPU emulation setup, and lets the
        // existing nil-fragmentFunction + rasterizationEnabled=NO pipeline
        // path handle the no-FS draw — same shape that ProgramKind::VertexOnly
        // relies on for SSBO-VS tests.
        VertexGeometry,
        // Separable multi-stage combination that doesn't match any
        // of the above — accepted only when GL_PROGRAM_SEPARABLE is
        // set. The program is linked for introspection; the actual
        // stage code is surfaced via the pipeline object when the
        // caller issues a draw.
        Separable,
    };
    // Set hasTessellation early — any attached TCS or TES counts, even
    // when the ProgramKind path doesn't specifically handle tess (e.g.
    // 5-stage VS+TCS+TES+GS+FS programs land on VertexGeometryFragment
    // today but still have tess shaders in play). The draw-time GS-
    // topology gate in drawArrays/Instanced/ElementsInstanced queries
    // this flag to suppress the draw-mode compat check for any program
    // with a tess stage (GS reads TES output, not the raw draw mode).
    if (tessControlShader != nullptr || tessEvalShader != nullptr) {
        programObject->hasTessellation = true;
    }

    ProgramKind kind = ProgramKind::Unknown;
    if (computeShader != nullptr && shaderCount == 1) {
        kind = ProgramKind::Compute;
    } else if (vertexShader != nullptr && fragmentShader != nullptr &&
               tessControlShader == nullptr && tessEvalShader == nullptr &&
               geometryShader == nullptr && computeShader == nullptr) {
        kind = ProgramKind::VertexFragment;
    } else if (vertexShader != nullptr && fragmentShader != nullptr &&
               geometryShader != nullptr && computeShader == nullptr) {
        kind = ProgramKind::VertexGeometryFragment;
    } else if (vertexShader != nullptr && geometryShader != nullptr &&
               fragmentShader == nullptr && computeShader == nullptr &&
               tessControlShader == nullptr && tessEvalShader == nullptr) {
        // Sprint 15 Day 18 (CKPT191) — VS+GS no-FS path. CTS SILS GS tests
        // build VS+GS-only programs with GL_RASTERIZER_DISCARD; image writes
        // happen in the GS body. Previously rejected as Unknown at link
        // (CKPT164 prior characterization).
        kind = ProgramKind::VertexGeometry;
    } else if (vertexShader != nullptr && fragmentShader != nullptr &&
               tessEvalShader != nullptr &&
               computeShader == nullptr) {
        // GL 4.6 §11.2.3: tess-eval is the required tess stage;
        // tess-control is OPTIONAL. A program with VS + TES + FS
        // (no TCS) is a valid combination — the app drives the
        // tessellation factors via `glPatchParameterfv(
        // GL_PATCH_DEFAULT_{INNER,OUTER}_LEVEL, ...)` instead of
        // through a TCS. CTS `tessellation_shader.single.
        // max_patch_vertices` builds one such program and expects
        // link to succeed. The downstream `quickHash(
        // tessControlShader->source)` call in the VTF branch is
        // now null-guarded so TCS-less programs don't deref null.
        kind = ProgramKind::VertexTessellationFragment;
    } else if (vertexShader != nullptr && fragmentShader == nullptr &&
               computeShader == nullptr && geometryShader == nullptr &&
               tessControlShader == nullptr && tessEvalShader == nullptr) {
        kind = ProgramKind::VertexOnly;
    } else if (fragmentShader != nullptr && vertexShader == nullptr &&
               computeShader == nullptr && geometryShader == nullptr &&
               tessControlShader == nullptr && tessEvalShader == nullptr) {
        kind = ProgramKind::FragmentOnly;
    } else if (geometryShader != nullptr && shaderCount == 1) {
        // Separable geometry-only program — used with glProgramPipeline +
        // glUseProgramStages(GL_GEOMETRY_SHADER_BIT). CTS
        // `separable_programs_tf.geometry_active` constructs one per stage
        // and links them independently. Translate to MSL for reflection so
        // the link succeeds; draw-time GS emulation is handled by the
        // VertexGeometryFragment path when the combined pipeline runs.
        kind = ProgramKind::GeometryOnly;
    } else if (tessControlShader != nullptr && shaderCount == 1) {
        kind = ProgramKind::TessControlOnly;
    } else if (tessEvalShader != nullptr && shaderCount == 1) {
        kind = ProgramKind::TessEvalOnly;
    }

    // GL 4.1 §7.3: a separable program can skip otherwise-
    // required stages — the program pipeline object will fill
    // them in at bind. Treat any still-Unknown stage combination
    // as valid-on-separable, and conversely reject stage-only
    // kinds (GeometryOnly / TessControlOnly / TessEvalOnly) when
    // the program is not marked separable, matching the
    // `linking.incomplete_program_objects` negative-run
    // expectations (FS:NO, GS:YES, non-separable must fail).
    if (kind == ProgramKind::Unknown && programObject->separable) {
        kind = ProgramKind::Separable;
    }
    // Non-separable programs with *only* a GS / TCS / TES stage
    // are invalid for rendering — the driver has nothing to feed
    // the missing stages at draw time. VS-only and FS-only stay
    // valid even without separable: VS-only is the canonical
    // transform-feedback-only program (CTS
    // `shader_storage_buffer_object.basic-*-vs` tests build one
    // and read back via glMapBuffer without ever rasterising),
    // and FS-only is accepted by GL implementations for
    // pipeline-composition flows we don't need to block here.
    // `linking.incomplete_program_objects` only tests GS ±
    // FS / VS combinations, so narrowing to the middle-stage
    // kinds keeps that test passing while un-regressing the
    // SSBO-VS and pipeline-statistics-VS tests that my prior
    // broader rejection caught.
    if (!programObject->separable &&
        (kind == ProgramKind::GeometryOnly ||
         kind == ProgramKind::TessControlOnly ||
         kind == ProgramKind::TessEvalOnly)) {
        programObject->linkLog = "incomplete non-separable program: missing required stage(s)";
        Runtime::shared().recordShaderTranslation({
            programTag, "link", "", "", "", programObject->linkLog, "", false
        });
        return false;
    }
    if (kind == ProgramKind::Unknown) {
        programObject->linkLog = "program has no supported shader stage combination";
        Runtime::shared().recordShaderTranslation({
            programTag, "link", "", "", "", programObject->linkLog, "", false
        });
        return false;
    }

    // Precompute the per-stage source hashes that get stamped onto every
    // link/vertex/fragment-stage record below. This is BAR's §4 ask #1 — the
    // diagnostic ring is bounded, and a search-back from a per-stage record to
    // its predecessor compile-stage record can fail when the ring wraps and
    // evicts the compile entry first. Carrying both hashes on every link-stage
    // record makes the mapping ring-eviction-proof.
    //
    // Empty for stages that don't exist (compute-only programs leave both
    // empty, vertex-only programs leave fragment empty, etc.).
    const std::string linkVertexHash =
        (vertexShader != nullptr) ? quickHash(vertexShader->source) : std::string();
    const std::string linkFragmentHash =
        (fragmentShader != nullptr) ? quickHash(fragmentShader->source) : std::string();

    // Phase 8X Group 4d follow-up⁴ — cache the source hashes on the program
    // object so the draw-time pipeline-build failure path (encodeTranslatedDraw
    // returning false from one of the Metal failure sites) can stamp them onto
    // the diagnostic ring without having to re-walk the attached shader list.
    // The link record path above and the failure record path below both pull
    // from the same canonical strings.
    programObject->vertexSourceHash = linkVertexHash;
    programObject->fragmentSourceHash = linkFragmentHash;

    // Assign uniform locations and seed default values.
    //
    // RC-D06: honour explicit `layout(location=N)` qualifiers from the GLSL
    // source.  CTS tests declare `layout(location=5) uniform float myUniform;`
    // and expect `glGetUniformLocation` to return 5.  The old code assigned
    // dense sequential locations starting from 0 regardless of any explicit
    // qualifier, which made those tests get -1.
    //
    // Two-pass approach:
    //   Pass 1 — assign explicit locations (those with explicitLocation >= 0).
    //            Track which locations are occupied so pass 2 can skip them.
    //   Pass 2 — assign auto-incremented locations for the rest, skipping
    //            any slot already claimed by an explicit location.
    //
    // Phase 8X Group 4d follow-up¹⁵ — if the GLSL source carried a default
    // initializer (`uniform vec4 ucolor = vec4(1.0);`), the scanner has
    // populated `uniform.defaultFloats` / `defaultInts` / `defaultUints` with
    // the parsed constant. Seed from that when present; otherwise fall back
    // to the historical zero-seed.

    // Collect the set of locations claimed by explicit layout qualifiers so
    // the auto-assignment pass can skip over them.
    std::unordered_set<GLint> reservedLocations;
    for (const auto& uniform : programObject->uniforms) {
        if (uniform.explicitLocation >= 0) {
            const GLint slots = std::max<GLint>(uniform.arraySize, 1);
            for (GLint s = 0; s < slots; ++s) {
                reservedLocations.insert(uniform.explicitLocation + s);
            }
        }
    }

    // Helper: find the next auto-location that doesn't collide with any
    // explicitly reserved slot.
    GLint nextLocation = 0;
    auto advancePastReserved = [&]() {
        while (reservedLocations.count(nextLocation)) {
            ++nextLocation;
        }
    };

    for (auto& uniform : programObject->uniforms) {
        // GL 4.6 §7.6.1: atomic counter uniforms have no uniform
        // location and cannot be used with any glUniform* function.
        // CTS `program_interface_query.atomic-counters` asserts
        // `glGetProgramResourceLocation(GL_UNIFORM, "a")` returns -1.
        if (uniform.type == GL_UNSIGNED_INT_ATOMIC_COUNTER) {
            uniform.location = -1;
        } else if (uniform.explicitLocation >= 0) {
            uniform.location = uniform.explicitLocation;
        } else {
            advancePastReserved();
            uniform.location = nextLocation;
        }
        const GLint components = glslComponentCount(uniform.type) * std::max<GLint>(uniform.arraySize, 1);
        const std::size_t componentCount = static_cast<std::size_t>(components);
        GLProgramUniformValue value;
        value.type = uniform.type;
        value.arraySize = uniform.arraySize;
        switch (uniform.type) {
            case GL_INT:
            case GL_INT_VEC2:
            case GL_INT_VEC3:
            case GL_INT_VEC4:
            case GL_BOOL:
            case GL_BOOL_VEC2:
            case GL_BOOL_VEC3:
            case GL_BOOL_VEC4:
            case GL_SAMPLER_1D:
            case GL_SAMPLER_2D:
            case GL_SAMPLER_3D:
            case GL_SAMPLER_CUBE:
            case GL_SAMPLER_1D_ARRAY:
            case GL_SAMPLER_2D_ARRAY:
            case GL_SAMPLER_1D_SHADOW:
            case GL_SAMPLER_2D_SHADOW:
            case GL_SAMPLER_1D_ARRAY_SHADOW:
            case GL_SAMPLER_2D_ARRAY_SHADOW:
            case GL_SAMPLER_CUBE_SHADOW:
            case GL_SAMPLER_2D_RECT:
            case GL_SAMPLER_2D_RECT_SHADOW:
            case GL_SAMPLER_BUFFER:
            case GL_SAMPLER_2D_MULTISAMPLE:
            case GL_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY_SHADOW:
            case GL_INT_SAMPLER_1D:
            case GL_INT_SAMPLER_2D:
            case GL_INT_SAMPLER_3D:
            case GL_INT_SAMPLER_CUBE:
            case GL_INT_SAMPLER_1D_ARRAY:
            case GL_INT_SAMPLER_2D_ARRAY:
            case GL_INT_SAMPLER_2D_RECT:
            case GL_INT_SAMPLER_BUFFER:
            case GL_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_1D:
            case GL_UNSIGNED_INT_SAMPLER_2D:
            case GL_UNSIGNED_INT_SAMPLER_3D:
            case GL_UNSIGNED_INT_SAMPLER_CUBE:
            case GL_UNSIGNED_INT_SAMPLER_1D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_RECT:
            case GL_UNSIGNED_INT_SAMPLER_BUFFER:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_CUBE_MAP_ARRAY:
                if (uniform.defaultInts.size() == componentCount) {
                    value.ints = uniform.defaultInts;
                } else {
                    value.ints.assign(componentCount, 0);
                }
                break;
            case GL_UNSIGNED_INT:
            case GL_UNSIGNED_INT_VEC2:
            case GL_UNSIGNED_INT_VEC3:
            case GL_UNSIGNED_INT_VEC4:
                if (uniform.defaultUints.size() == componentCount) {
                    value.uints = uniform.defaultUints;
                } else {
                    value.uints.assign(componentCount, 0u);
                }
                break;
            default:
                if (uniform.defaultFloats.size() == componentCount) {
                    value.floats = uniform.defaultFloats;
                } else {
                    value.floats.assign(componentCount, 0.0f);
                }
                break;
        }
        // Atomic-counter uniforms have no uniform location and no
        // entry in the `glUniform*`-addressable uniformValues map.
        if (uniform.location >= 0) {
            programObject->uniformValues[uniform.location] = std::move(value);
        }
        // Only advance the auto-location counter for non-explicit uniforms
        // that actually took a location. Explicit-location uniforms occupy
        // their declared slots (already recorded in reservedLocations) and
        // must not shift the counter, and atomic_uint uniforms never take
        // a slot at all.
        if (uniform.explicitLocation < 0 &&
            uniform.type != GL_UNSIGNED_INT_ATOMIC_COUNTER) {
            nextLocation += std::max<GLint>(uniform.arraySize, 1);
        }
    }

    // GL 4.6 §7.6.1 uniform location validation: verify that every
    // uniform's resolved location (and every slot it occupies for
    // array uniforms) is < GL_MAX_UNIFORM_LOCATIONS, and that no two
    // uniforms collide on the same location. CTS
    // `explicit_uniform_location.uniform-loc-negative-link-*`:
    //   - `reused1` — two uniforms declared with the same
    //     `layout(location=N)` in the same stage.
    //   - `reused2` — two uniforms declared at the same explicit
    //     location across two different stages (cross-stage
    //     collision — they have different names so
    //     `appendDeclarationsAsUniforms` does not merge them).
    //   - `max-location` — a single uniform at
    //     `location = GL_MAX_UNIFORM_LOCATIONS`; the valid range is
    //     `[0, MAX-1]`, so this must fail.
    //   - `max-num-of-locations` — an array uniform of size MAX at
    //     location 0 plus an implicit-location uniform that
    //     auto-assigns to MAX (overflowing).
    // All four must set `GL_LINK_STATUS=FALSE`.
    {
        GLint maxUnifLoc = 1024;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(GL_MAX_UNIFORM_LOCATIONS, &maxUnifLoc);
        }
        std::unordered_set<GLint> occupiedLocations;
        occupiedLocations.reserve(programObject->uniforms.size() * 2);
        for (const auto& uniform : programObject->uniforms) {
            if (uniform.location < 0) continue;  // atomic counters, etc.
            const GLint slots = std::max<GLint>(uniform.arraySize, 1);
            for (GLint s = 0; s < slots; ++s) {
                const GLint loc = uniform.location + s;
                if (loc >= maxUnifLoc) {
                    programObject->linkLog = "uniform '" + uniform.name
                        + "' location " + std::to_string(loc)
                        + " exceeds GL_MAX_UNIFORM_LOCATIONS="
                        + std::to_string(maxUnifLoc);
                    programObject->linked = false;
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", programObject->linkLog, "", false
                    });
                    return false;
                }
                if (!occupiedLocations.insert(loc).second) {
                    programObject->linkLog = "uniform '" + uniform.name
                        + "' location " + std::to_string(loc)
                        + " collides with another uniform";
                    programObject->linked = false;
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", programObject->linkLog, "", false
                    });
                    return false;
                }
            }
        }
    }

    // GL 4.2 §7.6: for any sampler uniform declared with
    // `layout(binding = N)` in the GLSL source, seed its integer value
    // to N. Subsequent glUniform1i calls override this. For arrays,
    // element i gets N+i (spec says consecutive binding points).
    // Populated after the main uniform-init loop so all uniformValues
    // entries exist and we only need to overwrite the sampler ones.
    // Harmless on programs with no explicit bindings — the map is empty.
    if (!programObject->samplerExplicitBindings.empty()) {
        for (const auto& uinfo : programObject->uniforms) {
            auto it = programObject->samplerExplicitBindings.find(uinfo.name);
            if (it == programObject->samplerExplicitBindings.end()) continue;
            auto valIt = programObject->uniformValues.find(uinfo.location);
            if (valIt == programObject->uniformValues.end()) continue;
            auto& v = valIt->second;
            const GLint arraySize = std::max<GLint>(uinfo.arraySize, 1);
            v.ints.assign(static_cast<std::size_t>(arraySize), 0);
            for (GLint i = 0; i < arraySize; ++i) {
                v.ints[static_cast<std::size_t>(i)] =
                    static_cast<GLint>(it->second) + i;
            }
        }
    }

    // Cache synthesized fixed-function matrix uniform locations. The
    // compat-shader rewriter (CompatShaderRewrite.h) prepends `appgl_*`
    // uniform declarations into the rewritten source for every legacy
    // matrix identifier referenced by the original compat-profile
    // shader. Those synthesized uniforms flowed through the scanner
    // above and now have real GL locations in `programObject->uniforms`.
    // Caching them once here means the per-draw matrix push is an O(1)
    // index lookup into `uniformValues` instead of a string scan over
    // the uniform table on every frame.
    {
        namespace SUN = appgl::SynthesizedUniformNames;
        auto findLocByName = [&](const char* name) -> GLint {
            for (const auto& u : programObject->uniforms) {
                if (u.name == name) {
                    return u.location;
                }
            }
            return -1;
        };
        // gl_TextureMatrix expands to `appgl_TextureMatrix[8]`; the
        // scanner records the array under its base name with arraySize
        // populated, so the lookup matches the bare base name.
        programObject->synthesizedMatrixSlots = GLSynthesizedMatrixSlots{};
        programObject->synthesizedMatrixSlots.modelView =
            findLocByName(SUN::kModelViewMatrix);
        programObject->synthesizedMatrixSlots.projection =
            findLocByName(SUN::kProjectionMatrix);
        programObject->synthesizedMatrixSlots.modelViewProjection =
            findLocByName(SUN::kModelViewProjectionMatrix);
        programObject->synthesizedMatrixSlots.modelViewInverse =
            findLocByName(SUN::kModelViewMatrixInverse);
        programObject->synthesizedMatrixSlots.projectionInverse =
            findLocByName(SUN::kProjectionMatrixInverse);
        programObject->synthesizedMatrixSlots.modelViewProjectionInverse =
            findLocByName(SUN::kModelViewProjectionMatrixInverse);
        programObject->synthesizedMatrixSlots.normal =
            findLocByName(SUN::kNormalMatrix);
        programObject->synthesizedMatrixSlots.texture =
            findLocByName(SUN::kTextureMatrix);
    }

    // ─── Transform feedback link-time validation ───────────────────────
    // GL 4.6 §11.1.2.1: the linker must reject programs whose transform
    // feedback configuration is invalid. The four cases the CTS
    // linking_errors_test expects:
    //   1) TF varyings specified but no vertex/geometry shader present.
    //   2) A TF varying name doesn't match any output of the last
    //      vertex-processing stage.
    //   3) The same output variable is captured more than once in
    //      SEPARATE_ATTRIBS mode (or in INTERLEAVED_ATTRIBS w/o
    //      gl_NextBuffer separation).
    //   4) Total component count exceeds the implementation limit.
    if (!programObject->transformFeedbackVaryingNames.empty()) {
        // (1) No vertex-processing stage.
        // The "last vertex-processing stage" determines the capturable outputs:
        //   GS > TES > VS (in priority order).
        // For SEPARABLE programs, a TCS-only stage is a valid last-
        // vertex-processing stage — the program pipeline at bind time
        // determines the downstream chain. GL 4.6 §11.1.2.1 permits
        // capturing TCS outputs when a separable TCS program is the
        // final vertex stage in the pipeline. CTS
        // `tessellation_shader.single.xfb_captures_data_from_correct_
        // stage` builds four separable programs (one per
        // VS/TCS/TES/GS stage) with TF varyings and expects each to
        // link. Previous behaviour rejected TCS-only at link time
        // because xfbStage was null.
        const GLShaderObject* xfbStage = geometryShader
            ? geometryShader
            : (tessEvalShader ? tessEvalShader
                              : (vertexShader ? vertexShader
                                              : (programObject->separable ? tessControlShader : nullptr)));
        if (xfbStage == nullptr) {
            programObject->linkLog = "transform feedback varyings specified but no vertex/geometry shader";
            Runtime::shared().recordShaderTranslation({
                programTag, "link", "", "", "", programObject->linkLog, "", false
            });
            return false;
        }

        // Build lookup of outputs from the last vertex-processing stage.
        // Track both type and array-size so TF varyings that capture a
        // whole array (`out float b[2]` captured by varying name "b")
        // can report GL_ARRAY_SIZE correctly, and array-element captures
        // (`b[0]` / `b[1]`) can strip the subscript, validate the index,
        // and report size 1. CTS
        // `program_interface_query.transform-feedback-types` asserts
        // both shapes.
        struct OutputInfo { GLenum type = 0; GLint arraySize = 1; bool isArray = false; };
        std::unordered_map<std::string, OutputInfo> outputTypeMap;
        for (const auto& decl : xfbStage->declaredOutputs) {
            OutputInfo info;
            info.type = decl.type;
            info.arraySize = decl.arraySize > 0 ? decl.arraySize : 1;
            info.isArray = decl.isArray;
            outputTypeMap[decl.name] = info;
        }
        // Built-in outputs that are always available for capture.
        outputTypeMap["gl_Position"]     = OutputInfo{GL_FLOAT_VEC4, 1, false};
        outputTypeMap["gl_PointSize"]    = OutputInfo{GL_FLOAT, 1, false};
        outputTypeMap["gl_ClipDistance"] = OutputInfo{GL_FLOAT, 1, false};

        // GL 4.6 §11.1.2.1 — TFB varyings inside named interface blocks
        // are referenced as either `BlockType.member` or
        // `instance.member`. Our GLSL scanner can't see block members
        // (braceDepth > 0 skips them to avoid parsing function bodies),
        // so do a focused source-text scan here to build synthetic
        // outputTypeMap entries. CTS `vertex_attrib_binding.basic-
        // input*` uses `"StageData.attrib[0]"` through `"StageData.
        // attrib[15]"` — without this, glTransformFeedbackVaryings
        // rejects the program at link time.
        {
            const std::string& src = xfbStage->source;
            const std::string outKw = "out ";
            std::size_t scanPos = 0;
            while ((scanPos = src.find(outKw, scanPos)) != std::string::npos) {
                const bool leftBoundary = (scanPos == 0) ||
                    !(std::isalnum(static_cast<unsigned char>(src[scanPos - 1])) ||
                      src[scanPos - 1] == '_');
                if (!leftBoundary) { scanPos += outKw.size(); continue; }
                std::size_t p = scanPos + outKw.size();
                while (p < src.size() && (src[p] == ' ' || src[p] == '\t')) { ++p; }
                const std::size_t nameStart = p;
                while (p < src.size() &&
                       (std::isalnum(static_cast<unsigned char>(src[p])) || src[p] == '_')) { ++p; }
                const std::string blockName(src, nameStart, p - nameStart);
                if (blockName.empty() || blockName == "gl_PerVertex") {
                    scanPos += outKw.size();
                    continue;
                }
                while (p < src.size() &&
                       (src[p] == ' ' || src[p] == '\t' || src[p] == '\n' || src[p] == '\r')) { ++p; }
                if (p >= src.size() || src[p] != '{') {
                    scanPos += outKw.size();
                    continue;
                }
                const std::size_t bodyStart = p + 1;
                int depth = 1;
                ++p;
                while (p < src.size() && depth > 0) {
                    if (src[p] == '{') ++depth;
                    else if (src[p] == '}') --depth;
                    ++p;
                }
                if (depth != 0) { scanPos += outKw.size(); continue; }
                std::string body(src, bodyStart, p - 1 - bodyStart);
                // Split body on `;`, parse each member.
                std::size_t bp = 0;
                while (bp < body.size()) {
                    auto semi = body.find(';', bp);
                    if (semi == std::string::npos) break;
                    std::string member = body.substr(bp, semi - bp);
                    bp = semi + 1;
                    // Strip whitespace + precision/interpolation quals.
                    auto isWS = [](char c) { return c == ' ' || c == '\t' || c == '\n' || c == '\r'; };
                    std::size_t mp = 0;
                    while (mp < member.size() && isWS(member[mp])) ++mp;
                    member = member.substr(mp);
                    // Tokenize. Format: [quals...] type name[,name...];
                    std::vector<std::string> toks;
                    std::string cur;
                    for (char c : member) {
                        if (isWS(c) || c == ',' || c == '[' || c == ']') {
                            if (!cur.empty()) { toks.push_back(cur); cur.clear(); }
                            if (c == ',' || c == '[' || c == ']') toks.emplace_back(1, c);
                        } else {
                            cur.push_back(c);
                        }
                    }
                    if (!cur.empty()) toks.push_back(cur);
                    // Drop quals until we hit a known type. Only the
                    // types that show up as XFB-capture interface-block
                    // members in CTS need to be recognised here;
                    // anything else stays out of outputTypeMap and the
                    // link-time check falls back to the spec-correct
                    // "not found" path. Keep in sync with the larger
                    // typeTable() in GLSLReflection.cpp.
                    auto typeFromKeyword = [](const std::string& k) -> GLenum {
                        if (k == "float") return GL_FLOAT;
                        if (k == "vec2")  return GL_FLOAT_VEC2;
                        if (k == "vec3")  return GL_FLOAT_VEC3;
                        if (k == "vec4")  return GL_FLOAT_VEC4;
                        if (k == "int")   return GL_INT;
                        if (k == "ivec2") return GL_INT_VEC2;
                        if (k == "ivec3") return GL_INT_VEC3;
                        if (k == "ivec4") return GL_INT_VEC4;
                        if (k == "uint")  return GL_UNSIGNED_INT;
                        if (k == "uvec2") return GL_UNSIGNED_INT_VEC2;
                        if (k == "uvec3") return GL_UNSIGNED_INT_VEC3;
                        if (k == "uvec4") return GL_UNSIGNED_INT_VEC4;
                        if (k == "double") return GL_DOUBLE;
                        if (k == "dvec2") return GL_DOUBLE_VEC2;
                        if (k == "dvec3") return GL_DOUBLE_VEC3;
                        if (k == "dvec4") return GL_DOUBLE_VEC4;
                        if (k == "mat2")  return GL_FLOAT_MAT2;
                        if (k == "mat3")  return GL_FLOAT_MAT3;
                        if (k == "mat4")  return GL_FLOAT_MAT4;
                        return 0;
                    };
                    std::size_t ti = 0;
                    GLenum memberType = 0;
                    while (ti < toks.size()) {
                        GLenum t = typeFromKeyword(toks[ti]);
                        if (t != 0) { memberType = t; ++ti; break; }
                        ++ti;
                    }
                    if (memberType == 0) continue;
                    // Names: collect identifiers (with optional [N]).
                    while (ti < toks.size()) {
                        if (!std::isalpha(static_cast<unsigned char>(toks[ti][0])) &&
                            toks[ti][0] != '_') { ++ti; continue; }
                        std::string name = toks[ti++];
                        GLint arraySize = 1;
                        bool isArray = false;
                        if (ti < toks.size() && toks[ti] == "[") {
                            ++ti;
                            if (ti < toks.size()) {
                                arraySize = static_cast<GLint>(std::strtol(toks[ti].c_str(), nullptr, 10));
                                ++ti;
                            }
                            if (ti < toks.size() && toks[ti] == "]") ++ti;
                            isArray = true;
                        }
                        OutputInfo info;
                        info.type = memberType;
                        info.arraySize = arraySize > 0 ? arraySize : 1;
                        info.isArray = isArray;
                        outputTypeMap[blockName + "." + name] = info;
                        // Skip past `,`
                        if (ti < toks.size() && toks[ti] == ",") ++ti;
                    }
                }
                scanPos = p;
            }
        }

        // Special interleaved-mode names that are NOT real varyings:
        auto isSpecialName = [](const std::string& n) {
            return n == "gl_NextBuffer" ||
                   n == "gl_SkipComponents1" || n == "gl_SkipComponents2" ||
                   n == "gl_SkipComponents3" || n == "gl_SkipComponents4";
        };

        // Helper: component count for a GL type.
        auto glTypeComponents = [](GLenum t) -> GLsizei {
            switch (t) {
                case GL_FLOAT: case GL_INT: case GL_UNSIGNED_INT: case GL_BOOL:
                case GL_DOUBLE:
                    return 1;
                case GL_FLOAT_VEC2: case GL_INT_VEC2: case GL_UNSIGNED_INT_VEC2:
                case GL_BOOL_VEC2: case GL_DOUBLE_VEC2:
                    return 2;
                case GL_FLOAT_VEC3: case GL_INT_VEC3: case GL_UNSIGNED_INT_VEC3:
                case GL_BOOL_VEC3: case GL_DOUBLE_VEC3:
                    return 3;
                case GL_FLOAT_VEC4: case GL_INT_VEC4: case GL_UNSIGNED_INT_VEC4:
                case GL_BOOL_VEC4: case GL_DOUBLE_VEC4:
                    return 4;
                case GL_FLOAT_MAT2: case GL_DOUBLE_MAT2:   return 4;
                case GL_FLOAT_MAT3: case GL_DOUBLE_MAT3:   return 9;
                case GL_FLOAT_MAT4: case GL_DOUBLE_MAT4:   return 16;
                case GL_FLOAT_MAT2x3: case GL_DOUBLE_MAT2x3: return 6;
                case GL_FLOAT_MAT2x4: case GL_DOUBLE_MAT2x4: return 8;
                case GL_FLOAT_MAT3x2: case GL_DOUBLE_MAT3x2: return 6;
                case GL_FLOAT_MAT3x4: case GL_DOUBLE_MAT3x4: return 12;
                case GL_FLOAT_MAT4x2: case GL_DOUBLE_MAT4x2: return 8;
                case GL_FLOAT_MAT4x3: case GL_DOUBLE_MAT4x3: return 12;
                default: return 1;
            }
        };

        // (2) Validate each varying name and resolve types.
        programObject->resourceTransformFeedbackVaryings.clear();
        std::unordered_set<std::string> seenNames;
        GLsizei totalComponents = 0;
        GLenum bufMode = programObject->transformFeedbackBufferMode;

        // When the scanner has populated output declarations for the
        // last vertex-processing stage, we can validate varying names
        // and resolve types.  When it hasn't (e.g. older scanner gap),
        // skip the name check and use GL_FLOAT as the fallback type.
        const bool haveOutputDecls = !outputTypeMap.empty() ||
            !xfbStage->declaredOutputs.empty();

        for (const auto& varyName : programObject->transformFeedbackVaryingNames) {
            if (isSpecialName(varyName)) {
                // GL 4.6 §7.3.1.1: `gl_NextBuffer` / `gl_SkipComponentsN`
                // still count as active resources in the
                // TRANSFORM_FEEDBACK_VARYING interface — name preserved,
                // TYPE = GL_NONE (0), ARRAY_SIZE = 0 for gl_NextBuffer and
                // N for gl_SkipComponentsN. CTS
                // `program_interface_query.transform-feedback-built-in`
                // queries NAME/TYPE/ARRAY_SIZE against exactly these
                // markers. They are excluded from `glGetProgramResourceIndex`
                // lookups (handled at query time) and from duplicate /
                // component-count checks here.
                GLint skipSize = 0;
                // "gl_SkipComponents1".."4" are all 18 chars long.
                if (varyName.size() == 18 && varyName.compare(0, 17, "gl_SkipComponents") == 0) {
                    char last = varyName.back();
                    if (last >= '1' && last <= '4') {
                        skipSize = last - '0';
                    }
                }
                GLProgramResourceEntry entry;
                entry.name = varyName;
                entry.type = GL_NONE;
                entry.arraySize = skipSize;
                // Mark as an array so GL_ARRAY_SIZE returns the raw
                // marker-count (0 for gl_NextBuffer, N for
                // gl_SkipComponentsN) instead of clamping to 1.
                entry.isArray = true;
                programObject->resourceTransformFeedbackVaryings.push_back(std::move(entry));
                continue;
            }

            GLenum resolvedType = GL_FLOAT; // fallback
            GLint resolvedArraySize = 1;
            bool captureIsArrayElement = false;
            // Array-element capture: `b[0]` / `b[1]` reference a single
            // element of `out float b[2]`. Strip the trailing `[N]`
            // subscript and look up the base name; size is 1 per GL 4.6
            // §11.1.2.1.
            std::string lookupName = varyName;
            {
                const auto bracket = varyName.rfind('[');
                if (bracket != std::string::npos && !varyName.empty() &&
                    varyName.back() == ']') {
                    const std::string idxStr =
                        varyName.substr(bracket + 1, varyName.size() - bracket - 2);
                    if (!idxStr.empty() &&
                        std::all_of(idxStr.begin(), idxStr.end(),
                                    [](char c) { return std::isdigit(static_cast<unsigned char>(c)); })) {
                        lookupName = varyName.substr(0, bracket);
                        captureIsArrayElement = true;
                    }
                }
            }
            if (haveOutputDecls) {
                auto it = outputTypeMap.find(lookupName);
                if (it == outputTypeMap.end()) {
                    programObject->linkLog = "transform feedback varying '" + varyName +
                        "' is not an output of the last vertex-processing stage";
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", programObject->linkLog, "", false
                    });
                    return false;
                }
                resolvedType = it->second.type;
                // Whole-array capture → report the declared array size.
                // Single-element capture → report 1.
                resolvedArraySize = (captureIsArrayElement || !it->second.isArray)
                    ? 1 : it->second.arraySize;
            }

            // (3) Duplicate check (applies to both interleaved and separate).
            if (!seenNames.insert(varyName).second) {
                programObject->linkLog = "transform feedback varying '" + varyName +
                    "' is captured more than once";
                Runtime::shared().recordShaderTranslation({
                    programTag, "link", "", "", "", programObject->linkLog, "", false
                });
                return false;
            }

            totalComponents += glTypeComponents(resolvedType) * resolvedArraySize;

            GLProgramResourceEntry entry;
            entry.name = varyName;
            entry.type = resolvedType;
            entry.arraySize = resolvedArraySize;
            programObject->resourceTransformFeedbackVaryings.push_back(std::move(entry));
        }

        // (4) Component limit check.
        // GL_MAX_TRANSFORM_FEEDBACK_INTERLEAVED_COMPONENTS = 64 (our reported value)
        // GL_MAX_TRANSFORM_FEEDBACK_SEPARATE_COMPONENTS = 4
        // GL_MAX_TRANSFORM_FEEDBACK_SEPARATE_ATTRIBS = 4
        if (bufMode == GL_INTERLEAVED_ATTRIBS) {
            constexpr GLsizei kMaxInterleavedComponents = 64;
            if (totalComponents > kMaxInterleavedComponents) {
                programObject->linkLog = "transform feedback exceeds GL_MAX_TRANSFORM_FEEDBACK_INTERLEAVED_COMPONENTS";
                programObject->resourceTransformFeedbackVaryings.clear();
                Runtime::shared().recordShaderTranslation({
                    programTag, "link", "", "", "", programObject->linkLog, "", false
                });
                return false;
            }
        } else if (bufMode == GL_SEPARATE_ATTRIBS) {
            constexpr GLsizei kMaxSeparateComponents = 4;
            constexpr GLsizei kMaxSeparateAttribs = 4;
            GLsizei attribCount = static_cast<GLsizei>(programObject->resourceTransformFeedbackVaryings.size());
            if (attribCount > kMaxSeparateAttribs) {
                programObject->linkLog = "transform feedback exceeds GL_MAX_TRANSFORM_FEEDBACK_SEPARATE_ATTRIBS";
                programObject->resourceTransformFeedbackVaryings.clear();
                Runtime::shared().recordShaderTranslation({
                    programTag, "link", "", "", "", programObject->linkLog, "", false
                });
                return false;
            }
            for (const auto& res : programObject->resourceTransformFeedbackVaryings) {
                if (glTypeComponents(res.type) > kMaxSeparateComponents) {
                    programObject->linkLog = "transform feedback varying '" + res.name +
                        "' exceeds GL_MAX_TRANSFORM_FEEDBACK_SEPARATE_COMPONENTS";
                    programObject->resourceTransformFeedbackVaryings.clear();
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", programObject->linkLog, "", false
                    });
                    return false;
                }
            }
        }
    } else {
        // No TF varyings — clear any stale resolved data from a previous link.
        programObject->resourceTransformFeedbackVaryings.clear();
    }
    // ─── End transform feedback link-time validation ─────────────────

    // ─── Stage-to-stage varying type match (GL 4.6 §7.4.1) ────────────
    //
    // Each `out` variable in one stage must be consumed by an `in`
    // variable of the same name, type, and qualifiers in the next
    // vertex-processing stage (or in the fragment stage). glslang
    // catches in-stage mismatches during compilation, but it doesn't
    // see the cross-stage picture — two separately-compiled
    // shaders can disagree on the type of a shared varying and
    // glslang happily produces a SPIR-V for each. The spec
    // requires the link to fail in that case (`linking.vs_gs_
    // variable_type_mismatch` asserts the failure path).
    //
    // Walks each consecutive stage pair and compares by name. Built-
    // ins (`gl_Position` etc.) and transform-feedback-only names
    // (`gl_NextBuffer`, `gl_SkipComponents*`) are skipped; glslang
    // already enforces their types. Unmatched-name inputs are
    // treated as "only declared in the consumer" and ignored —
    // trying to catch "sink with no source" here would false-
    // positive against legitimate patterns where a VS output is
    // unused in the next stage.
    {
        struct StagePair {
            const GLShaderObject* producer = nullptr;
            const char*           producerName = "";
            const GLShaderObject* consumer = nullptr;
            const char*           consumerName = "";
        };
        std::vector<StagePair> pairs;
        if (vertexShader != nullptr) {
            const GLShaderObject* next = tessControlShader
                ? tessControlShader
                : (tessEvalShader ? tessEvalShader
                                  : (geometryShader ? geometryShader
                                                    : fragmentShader));
            const char* nextName = tessControlShader ? "tess-control"
                : (tessEvalShader ? "tess-eval"
                : (geometryShader ? "geometry" : "fragment"));
            if (next != nullptr) {
                pairs.push_back({vertexShader, "vertex", next, nextName});
            }
        }
        if (tessControlShader != nullptr && tessEvalShader != nullptr) {
            pairs.push_back({tessControlShader, "tess-control", tessEvalShader, "tess-eval"});
        }
        if (tessEvalShader != nullptr) {
            const GLShaderObject* next = geometryShader ? geometryShader : fragmentShader;
            const char* nextName = geometryShader ? "geometry" : "fragment";
            if (next != nullptr) {
                pairs.push_back({tessEvalShader, "tess-eval", next, nextName});
            }
        }
        if (geometryShader != nullptr && fragmentShader != nullptr) {
            pairs.push_back({geometryShader, "geometry", fragmentShader, "fragment"});
        }

        bool varyingMismatch = false;
        std::string mismatchMsg;
        for (const auto& pair : pairs) {
            std::unordered_map<std::string, GLenum> producerOut;
            for (const auto& decl : pair.producer->declaredOutputs) {
                producerOut[decl.name] = decl.type;
            }
            for (const auto& decl : pair.consumer->declaredInputs) {
                // Skip built-ins / gl_in gl_out blocks — glslang
                // handles those. User varyings never start with
                // "gl_".
                if (decl.name.compare(0, 3, "gl_") == 0) continue;
                auto it = producerOut.find(decl.name);
                if (it == producerOut.end()) continue;   // unmatched; not our check
                if (it->second != decl.type) {
                    varyingMismatch = true;
                    mismatchMsg = std::string("varying '") + decl.name + "' type mismatch: "
                        + std::string(pair.producerName) + " stage outputs type 0x" +
                        [&]{ char b[12]; std::snprintf(b, sizeof(b), "%04x", it->second); return std::string(b); }()
                        + ", " + std::string(pair.consumerName) + " stage inputs type 0x" +
                        [&]{ char b[12]; std::snprintf(b, sizeof(b), "%04x", decl.type); return std::string(b); }();
                    break;
                }
            }
            if (varyingMismatch) break;
        }
        if (varyingMismatch) {
            programObject->linkLog = mismatchMsg;
            programObject->linked = false;
            Runtime::shared().recordShaderTranslation({
                programTag, "link", "", "", "", programObject->linkLog, "", false
            });
            return false;
        }
    }
    // ─── End stage-to-stage varying type check ───────────────────────

    // ─── Cross-stage uniform type consistency (GL 4.6 §7.4.1) ────────
    //
    // When two stages declare a uniform with the same name, the types
    // must match. CTS `shader_image_load_store.negative-linkErrors`
    // attaches a VS with `uniform image1D g_image` and an FS with
    // `uniform image2D g_image` and expects the link to fail with a
    // type mismatch diagnostic. Our varying check above walks inputs
    // vs outputs; uniforms are a separate namespace and need their
    // own pass.
    //
    // We iterate every (shader_A, shader_B) pair and look for same-
    // named entries in `declaredUniforms` with mismatched types.
    {
        std::vector<const GLShaderObject*> attachedStages;
        if (vertexShader != nullptr)       attachedStages.push_back(vertexShader);
        if (tessControlShader != nullptr)  attachedStages.push_back(tessControlShader);
        if (tessEvalShader != nullptr)     attachedStages.push_back(tessEvalShader);
        if (geometryShader != nullptr)     attachedStages.push_back(geometryShader);
        if (fragmentShader != nullptr)     attachedStages.push_back(fragmentShader);
        if (computeShader != nullptr)      attachedStages.push_back(computeShader);

        bool uniformMismatch = false;
        std::string mismatchMsg;
        struct SeenUniform { GLenum type; GLenum imageFormat; };
        std::unordered_map<std::string, SeenUniform> seenUniforms;
        for (const GLShaderObject* stage : attachedStages) {
            if (uniformMismatch) break;
            for (const auto& u : stage->declaredUniforms) {
                // Skip built-ins and synthesized compat-rewrite
                // uniforms (appgl_ModelViewMatrix etc.).
                if (u.name.compare(0, 3, "gl_") == 0) continue;
                if (u.name.compare(0, 6, "appgl_") == 0) continue;
                auto it = seenUniforms.find(u.name);
                if (it == seenUniforms.end()) {
                    seenUniforms[u.name] = {u.type, u.imageFormat};
                } else if (it->second.type != u.type) {
                    uniformMismatch = true;
                    mismatchMsg = std::string("uniform '") + u.name +
                        "' type mismatch across stages: seen type 0x" +
                        [&]{ char b[12]; std::snprintf(b, sizeof(b), "%04x", it->second.type); return std::string(b); }()
                        + ", new type 0x" +
                        [&]{ char b[12]; std::snprintf(b, sizeof(b), "%04x", u.type); return std::string(b); }();
                    break;
                } else if (it->second.imageFormat != 0 && u.imageFormat != 0 &&
                           it->second.imageFormat != u.imageFormat) {
                    // GL 4.6 §4.4.8.2: if both stages specify a
                    // layout(IMAGE_FORMAT) qualifier, they must agree.
                    // Unspecified on either side is silently allowed
                    // (the other side's spec wins).
                    uniformMismatch = true;
                    mismatchMsg = std::string("image uniform '") + u.name +
                        "' layout format mismatch across stages: seen 0x" +
                        [&]{ char b[12]; std::snprintf(b, sizeof(b), "%04x", it->second.imageFormat); return std::string(b); }()
                        + ", new 0x" +
                        [&]{ char b[12]; std::snprintf(b, sizeof(b), "%04x", u.imageFormat); return std::string(b); }();
                    break;
                }
            }
        }
        if (uniformMismatch) {
            programObject->linkLog = mismatchMsg;
            programObject->linked = false;
            Runtime::shared().recordShaderTranslation({
                programTag, "link", "", "", "", programObject->linkLog, "", false
            });
            return false;
        }
    }
    // ─── End cross-stage uniform type consistency check ──────────────

    // ─── Tess-eval primitive-mode layout (GL 4.6 §11.2.3) ────────────
    //
    // A tessellation evaluation shader MUST specify exactly one of
    // `layout(triangles)`, `layout(quads)`, or `layout(isolines)` as
    // its input primitive mode. The spec says this is a LINK-time
    // error (not compile-time), and CTS
    // `tessellation_shader.compilation_and_linking_errors.
    // te_lacking_primitive_mode_declaration` expects compile to
    // succeed and link to fail for a tess-eval shader that lacks the
    // directive.
    //
    // Glslang's `TProgram::link` happens to raise the error at
    // single-stage compile (we work around that in
    // `ShaderTranslator::compileGLSL`). So we have to re-check the
    // rule here at actual program link time.
    if (tessEvalShader != nullptr) {
        const std::string& src = tessEvalShader->source;
        // Strip comments so `// layout(triangles)` doesn't satisfy
        // the check. Reuse a lightweight copy here — the scan is
        // per-link, so cost is negligible.
        auto strip = [](const std::string& in) {
            std::string out;
            out.reserve(in.size());
            for (std::size_t i = 0; i < in.size(); ) {
                if (i + 1 < in.size() && in[i] == '/' && in[i + 1] == '/') {
                    while (i < in.size() && in[i] != '\n') { ++i; }
                } else if (i + 1 < in.size() && in[i] == '/' && in[i + 1] == '*') {
                    i += 2;
                    while (i + 1 < in.size() && !(in[i] == '*' && in[i + 1] == '/')) ++i;
                    if (i + 1 < in.size()) i += 2;
                } else {
                    out.push_back(in[i]);
                    ++i;
                }
            }
            return out;
        };
        const std::string clean = strip(src);
        // We need a `layout(...)` directive with one of the three
        // primitive-mode tokens, followed by an `in` keyword (not
        // specifically required by the spec — `layout(triangles)
        // in;` is the canonical form, but `layout(triangles);` and
        // `layout(triangles) in;` are both legal). We only need to
        // see the token inside a `layout(...)` paren; spec also
        // permits `layout(triangles, equal_spacing, ccw) in;` with
        // multiple qualifiers.
        auto hasPrimMode = [&](const std::string& tok) -> bool {
            std::size_t pos = 0;
            while (pos < clean.size()) {
                std::size_t lp = clean.find("layout", pos);
                if (lp == std::string::npos) return false;
                // word-boundary
                bool leftOk = (lp == 0) ||
                    !(std::isalnum(static_cast<unsigned char>(clean[lp - 1])) ||
                      clean[lp - 1] == '_');
                bool rightOk = (lp + 6 >= clean.size()) ||
                    !(std::isalnum(static_cast<unsigned char>(clean[lp + 6])) ||
                      clean[lp + 6] == '_');
                if (!leftOk || !rightOk) { pos = lp + 1; continue; }
                std::size_t op = clean.find('(', lp);
                if (op == std::string::npos) return false;
                std::size_t cp = clean.find(')', op);
                if (cp == std::string::npos) return false;
                std::string inner = clean.substr(op + 1, cp - op - 1);
                // Tokenize inner and check for tok as a complete word.
                std::size_t tp = inner.find(tok);
                while (tp != std::string::npos) {
                    bool lOk = (tp == 0) ||
                        !(std::isalnum(static_cast<unsigned char>(inner[tp - 1])) ||
                          inner[tp - 1] == '_');
                    bool rOk = (tp + tok.size() >= inner.size()) ||
                        !(std::isalnum(static_cast<unsigned char>(inner[tp + tok.size()])) ||
                          inner[tp + tok.size()] == '_');
                    if (lOk && rOk) return true;
                    tp = inner.find(tok, tp + 1);
                }
                pos = cp + 1;
            }
            return false;
        };
        const bool ok = hasPrimMode("triangles") ||
                        hasPrimMode("quads") ||
                        hasPrimMode("isolines");
        if (!ok) {
            programObject->linkLog =
                "ERROR: Linking tessellation evaluation stage: "
                "At least one shader must specify an input layout primitive";
            programObject->linked = false;
            Runtime::shared().recordShaderTranslation({
                programTag, "link", "", "", "", programObject->linkLog, "", false
            });
            return false;
        }
    }
    // ─── End tess-eval primitive-mode check ──────────────────────────

    // ─── Tess-control output patch vertex count (GL 4.6 §11.2.1) ─────
    //
    // TCS specifies output patch vertex count via
    // `layout(vertices = N) out;` where `N ∈ [1, MAX_PATCH_VERTICES]`.
    // A value of 0 or > MAX_PATCH_VERTICES is a LINK-time error.
    // CTS `tessellation_shader.compilation_and_linking_errors.
    // tc_invalid_output_patch_vertex_count` tests both 0 and 33 (above
    // the 32 limit) and expects link to fail.
    //
    // Glslang catches 0 at parse time (raises "vertices : must be
    // greater than 0") so that subcase fails at compile, which is
    // what the test expects ("Compilation failed as allowed"). The 33
    // subcase compiles fine (glslang accepts values up to INT_MAX)
    // and we need to fail it here at link time.
    if (tessControlShader != nullptr) {
        const std::string& src = tessControlShader->source;
        auto strip = [](const std::string& in) {
            std::string out;
            out.reserve(in.size());
            for (std::size_t i = 0; i < in.size(); ) {
                if (i + 1 < in.size() && in[i] == '/' && in[i + 1] == '/') {
                    while (i < in.size() && in[i] != '\n') { ++i; }
                } else if (i + 1 < in.size() && in[i] == '/' && in[i + 1] == '*') {
                    i += 2;
                    while (i + 1 < in.size() && !(in[i] == '*' && in[i + 1] == '/')) ++i;
                    if (i + 1 < in.size()) i += 2;
                } else {
                    out.push_back(in[i]);
                    ++i;
                }
            }
            return out;
        };
        const std::string clean = strip(src);
        // Search for `layout ( ... vertices <ws>*=<ws>* N ...)`.
        std::size_t pos = 0;
        int verticesN = -1;
        while (pos < clean.size()) {
            std::size_t lp = clean.find("layout", pos);
            if (lp == std::string::npos) break;
            bool leftOk = (lp == 0) ||
                !(std::isalnum(static_cast<unsigned char>(clean[lp - 1])) ||
                  clean[lp - 1] == '_');
            bool rightOk = (lp + 6 >= clean.size()) ||
                !(std::isalnum(static_cast<unsigned char>(clean[lp + 6])) ||
                  clean[lp + 6] == '_');
            if (!leftOk || !rightOk) { pos = lp + 1; continue; }
            std::size_t op = clean.find('(', lp);
            if (op == std::string::npos) break;
            std::size_t cp = clean.find(')', op);
            if (cp == std::string::npos) break;
            std::string inner = clean.substr(op + 1, cp - op - 1);
            // Search for `vertices` token inside inner.
            std::size_t vp = inner.find("vertices");
            while (vp != std::string::npos) {
                bool lOk = (vp == 0) ||
                    !(std::isalnum(static_cast<unsigned char>(inner[vp - 1])) ||
                      inner[vp - 1] == '_');
                std::size_t after = vp + 8;
                bool rOk = (after >= inner.size()) ||
                    !(std::isalnum(static_cast<unsigned char>(inner[after])) ||
                      inner[after] == '_');
                if (lOk && rOk) {
                    // Skip whitespace and '='
                    while (after < inner.size() &&
                           std::isspace(static_cast<unsigned char>(inner[after]))) ++after;
                    if (after < inner.size() && inner[after] == '=') {
                        ++after;
                        while (after < inner.size() &&
                               std::isspace(static_cast<unsigned char>(inner[after]))) ++after;
                        // Read integer literal
                        std::size_t ns = after;
                        while (after < inner.size() &&
                               std::isdigit(static_cast<unsigned char>(inner[after]))) ++after;
                        if (after > ns) {
                            verticesN = std::atoi(inner.substr(ns, after - ns).c_str());
                            break;
                        }
                    }
                }
                vp = inner.find("vertices", vp + 1);
            }
            if (verticesN >= 0) break;
            pos = cp + 1;
        }

        if (verticesN > 0) {
            const int maxPatchVertices = 32;  // matches GLCapabilities
            if (verticesN > maxPatchVertices) {
                programObject->linkLog =
                    "ERROR: Linking tessellation control stage: "
                    "layout(vertices=" + std::to_string(verticesN) +
                    ") exceeds GL_MAX_PATCH_VERTICES (" +
                    std::to_string(maxPatchVertices) + ")";
                programObject->linked = false;
                Runtime::shared().recordShaderTranslation({
                    programTag, "link", "", "", "", programObject->linkLog, "", false
                });
                return false;
            }
        }
    }
    // ─── End tess-control patch vertex count check ───────────────────

    // ─── gl_PerVertex block re-declaration consistency (GL 4.6 §7.4.1)
    //
    // When two or more stages redeclare the built-in `gl_PerVertex`
    // interface block, the redeclarations must agree on their
    // member list. CTS `CommonBugs.CommonBug_PerVertexValidation`
    // builds separable programs where VS/GS/TCS/TES declare
    // mismatching `gl_PerVertex { ... }` blocks (e.g. VS with
    // `gl_Position + gl_PointSize`, GS with just `gl_Position`)
    // and asserts the link fails.
    //
    // We don't fully parse the GLSL; the check is a coarse
    // member-name scan of each stage's source looking for a
    // top-level `out gl_PerVertex { ... };` block. If at least
    // two stages redeclare the block, the sorted member-name
    // sets must match exactly.
    {
        auto extractPerVertexMembers = [](const std::string& src) -> std::set<std::string> {
            std::set<std::string> members;
            // Find `out gl_PerVertex` or `in gl_PerVertex`
            // followed by `{` — whichever comes first.
            static const char* kTokens[] = { "out gl_PerVertex", "in gl_PerVertex" };
            std::size_t pos = std::string::npos;
            for (const char* tok : kTokens) {
                std::size_t p = src.find(tok);
                if (p != std::string::npos && (pos == std::string::npos || p < pos)) {
                    pos = p;
                }
            }
            if (pos == std::string::npos) return members;
            std::size_t open = src.find('{', pos);
            if (open == std::string::npos) return members;
            std::size_t close = src.find('}', open);
            if (close == std::string::npos) return members;
            // Scan the body for member declarations. Each is
            // `<qualifiers?> <type> <name> [array]?;`. We strip
            // qualifiers and array suffixes and keep the
            // `<name>` token immediately before `;`.
            std::string body = src.substr(open + 1, close - open - 1);
            std::size_t p = 0;
            while (p < body.size()) {
                std::size_t semi = body.find(';', p);
                if (semi == std::string::npos) break;
                std::string stmt = body.substr(p, semi - p);
                p = semi + 1;
                // Strip whitespace + everything inside `[`.
                auto lb = stmt.find('[');
                if (lb != std::string::npos) stmt.resize(lb);
                // Right-most token of what's left is the name.
                std::size_t rend = stmt.size();
                while (rend > 0 && std::isspace(static_cast<unsigned char>(stmt[rend - 1]))) --rend;
                std::size_t rstart = rend;
                while (rstart > 0) {
                    const char c = stmt[rstart - 1];
                    if (std::isalnum(static_cast<unsigned char>(c)) || c == '_') {
                        --rstart;
                    } else {
                        break;
                    }
                }
                if (rstart < rend) {
                    members.insert(stmt.substr(rstart, rend - rstart));
                }
            }
            return members;
        };
        struct StageSource { const std::string* src; const char* name; };
        std::vector<StageSource> stages;
        if (vertexShader      != nullptr) stages.push_back({&vertexShader->source,      "vertex"});
        if (tessControlShader != nullptr) stages.push_back({&tessControlShader->source, "tess-control"});
        if (tessEvalShader    != nullptr) stages.push_back({&tessEvalShader->source,    "tess-eval"});
        if (geometryShader    != nullptr) stages.push_back({&geometryShader->source,    "geometry"});
        std::vector<std::pair<const char*, std::set<std::string>>> redeclarations;
        for (const auto& s : stages) {
            auto members = extractPerVertexMembers(*s.src);
            if (!members.empty()) redeclarations.emplace_back(s.name, std::move(members));
        }
        if (redeclarations.size() >= 2) {
            for (std::size_t i = 1; i < redeclarations.size(); ++i) {
                if (redeclarations[i].second != redeclarations[0].second) {
                    programObject->linkLog = std::string("gl_PerVertex block redeclaration mismatch between ")
                        + redeclarations[0].first + " and " + redeclarations[i].first + " stages";
                    programObject->linked = false;
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", programObject->linkLog, "", false
                    });
                    return false;
                }
            }
        }
    }
    // ─── End gl_PerVertex consistency check ─────────────────────────

    // ─── Per-stage atomic-counter / atomic-counter-buffer limits ────
    //
    // GL 4.6 §7.6.3 + Table 23.66: each shader stage has its own cap
    // on the number of atomic-counter uniforms it may declare
    // (MAX_{VERTEX,FRAGMENT,GEOMETRY,...}_ATOMIC_COUNTERS) and
    // on the number of distinct atomic-counter buffers the stage
    // can bind to (the `*_ATOMIC_COUNTER_BUFFERS` counterpart).
    // `linking.more_ACs_in_GS_than_supported` +
    // `linking.more_ACBs_in_GS_than_supported` query the GS caps,
    // create a GS that overshoots by one, and assert link failure.
    // We already advertise `MAX_GEOMETRY_ATOMIC_COUNTERS = 0`,
    // which simplifies the check to "if the GS source declares
    // any `atomic_uint` uniform, the link must fail" — but
    // implement the general form for future when the cap lifts.
    if (geometryShader != nullptr) {
        std::size_t gsAtomicCounters = 0;
        std::unordered_set<GLint> gsAtomicBindings;
        for (const auto& decl : geometryShader->declaredUniforms) {
            if (decl.type != GL_UNSIGNED_INT_ATOMIC_COUNTER) continue;
            const std::size_t cnt = (decl.arraySize > 0)
                ? static_cast<std::size_t>(decl.arraySize) : 1;
            gsAtomicCounters += cnt;
            if (decl.explicitBinding >= 0) {
                gsAtomicBindings.insert(decl.explicitBinding);
            }
        }
        GLint maxAtomic = 0, maxAtomicBufs = 0;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(GL_MAX_GEOMETRY_ATOMIC_COUNTERS, &maxAtomic);
            impl_->capabilities->queryInteger(GL_MAX_GEOMETRY_ATOMIC_COUNTER_BUFFERS, &maxAtomicBufs);
        }
        if (static_cast<GLint>(gsAtomicCounters) > maxAtomic) {
            programObject->linkLog = "geometry shader atomic-counter count "
                + std::to_string(gsAtomicCounters) + " exceeds MAX_GEOMETRY_ATOMIC_COUNTERS="
                + std::to_string(maxAtomic);
            programObject->linked = false;
            Runtime::shared().recordShaderTranslation({
                programTag, "link", "", "", "", programObject->linkLog, "", false
            });
            return false;
        }
        if (static_cast<GLint>(gsAtomicBindings.size()) > maxAtomicBufs) {
            programObject->linkLog = "geometry shader atomic-counter-buffer count "
                + std::to_string(gsAtomicBindings.size())
                + " exceeds MAX_GEOMETRY_ATOMIC_COUNTER_BUFFERS="
                + std::to_string(maxAtomicBufs);
            programObject->linked = false;
            Runtime::shared().recordShaderTranslation({
                programTag, "link", "", "", "", programObject->linkLog, "", false
            });
            return false;
        }
    }
    // ─── End AC / ACB limits check ──────────────────────────────────

    // ─── Subroutine uniform location validation (GL 4.6 §7.9) ───
    //
    // CTS `explicit_uniform_location.subroutine-loc-negative-link-*`
    // asserts that glLinkProgram sets GL_LINK_STATUS=FALSE when
    // any of the following appears in a subroutine uniform
    // declaration (per stage, independently):
    //   (a) Two `layout(location=N)` subroutine uniforms collide
    //       on the same location (or overlapping array ranges).
    //   (b) A `layout(location=N)` subroutine uniform's base
    //       location, or any location its array occupies, is
    //       >= GL_MAX_SUBROUTINE_UNIFORM_LOCATIONS.
    //   (c) The linked program's total subroutine-uniform
    //       location count (sum of arraySizes + implicit) in
    //       any stage exceeds GL_MAX_SUBROUTINE_UNIFORM_LOCATIONS.
    //
    // Parse `layout(location=K) subroutine uniform TYPE NAME [N];`
    // declarations straight from each attached shader's source.
    // We can't rely on `resourceSubroutineUniforms[]` here because
    // that table is populated *after* `linked = true` (see the
    // resource-introspection block below). This parse is
    // intentionally lightweight — just locations, array sizes,
    // and layout pins — and mirrors the full scanner in
    // `scanSubroutineDeclarations` for the pieces it needs.
    {
        GLint maxSrUnifLoc = 1024;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(
                GL_MAX_SUBROUTINE_UNIFORM_LOCATIONS, &maxSrUnifLoc);
        }
        // Per-stage parse. Returns false + sets linkLog on first
        // spec violation (so the link fails with a descriptive
        // message).
        auto stripComments = [](const std::string& s) {
            std::string out;
            out.reserve(s.size());
            for (std::size_t i = 0; i < s.size();) {
                if (i + 1 < s.size() && s[i] == '/' && s[i + 1] == '/') {
                    while (i < s.size() && s[i] != '\n') ++i;
                } else if (i + 1 < s.size() && s[i] == '/' && s[i + 1] == '*') {
                    i += 2;
                    while (i + 1 < s.size() && !(s[i] == '*' && s[i + 1] == '/')) ++i;
                    if (i + 1 < s.size()) i += 2;
                } else {
                    out += s[i++];
                }
            }
            return out;
        };
        auto isIdentCh = [](unsigned char c) {
            return std::isalnum(c) || c == '_';
        };
        auto validateStage = [&](const std::string& sourceIn) -> bool {
            const std::string src = stripComments(sourceIn);
            std::unordered_set<GLint> usedLocations;
            std::size_t totalLocations = 0;
            const std::string kw = "subroutine";
            std::size_t pos = 0;
            while ((pos = src.find(kw, pos)) != std::string::npos) {
                const bool lb = (pos == 0) ||
                    !isIdentCh(static_cast<unsigned char>(src[pos - 1]));
                const bool rb = (pos + kw.size() < src.size()) &&
                    !isIdentCh(static_cast<unsigned char>(src[pos + kw.size()]));
                if (!lb || !rb) { pos += kw.size(); continue; }
                // Walk backward for `layout(location=K)` qualifier.
                GLint explicitLoc = -1;
                {
                    std::size_t back = pos;
                    while (back > 0 && std::isspace(
                        static_cast<unsigned char>(src[back - 1]))) --back;
                    if (back > 0 && src[back - 1] == ')') {
                        int pd = 1;
                        std::size_t bp = back - 1;
                        while (bp > 0 && pd > 0) {
                            --bp;
                            if (src[bp] == ')') ++pd;
                            else if (src[bp] == '(') --pd;
                        }
                        if (pd == 0 && bp >= 6) {
                            std::size_t lp = bp;
                            while (lp > 0 && std::isspace(
                                static_cast<unsigned char>(src[lp - 1]))) --lp;
                            if (lp >= 6 && src.compare(lp - 6, 6, "layout") == 0) {
                                std::string content = src.substr(
                                    bp + 1, (back - 1) - (bp + 1));
                                std::size_t loc = content.find("location");
                                if (loc != std::string::npos) {
                                    std::size_t eq = content.find('=', loc);
                                    if (eq != std::string::npos) {
                                        std::size_t nb = eq + 1;
                                        while (nb < content.size() &&
                                               std::isspace(static_cast<unsigned char>(content[nb]))) ++nb;
                                        std::size_t ne = nb;
                                        while (ne < content.size() &&
                                               (std::isdigit(static_cast<unsigned char>(content[ne])) ||
                                                content[ne] == 'x' || content[ne] == 'X')) ++ne;
                                        if (ne > nb) {
                                            explicitLoc = static_cast<GLint>(
                                                std::strtol(content.substr(nb, ne - nb).c_str(),
                                                            nullptr, 0));
                                        }
                                    }
                                }
                            }
                        }
                    }
                }
                std::size_t p = pos + kw.size();
                while (p < src.size() && std::isspace(static_cast<unsigned char>(src[p]))) ++p;
                // Only `subroutine uniform …` shapes consume locations.
                if (p + 7 <= src.size() && src.compare(p, 7, "uniform") == 0 &&
                    (p + 7 == src.size() || !isIdentCh(static_cast<unsigned char>(src[p + 7])))) {
                    p += 7;
                    while (p < src.size() && std::isspace(static_cast<unsigned char>(src[p]))) ++p;
                    // Skip TYPE word.
                    while (p < src.size() && isIdentCh(static_cast<unsigned char>(src[p]))) ++p;
                    while (p < src.size() && std::isspace(static_cast<unsigned char>(src[p]))) ++p;
                    // Skip NAME word.
                    while (p < src.size() && isIdentCh(static_cast<unsigned char>(src[p]))) ++p;
                    while (p < src.size() && std::isspace(static_cast<unsigned char>(src[p]))) ++p;
                    // Optional `[N]` array subscript.
                    GLint arraySize = 1;
                    if (p < src.size() && src[p] == '[') {
                        ++p;
                        while (p < src.size() && std::isspace(
                            static_cast<unsigned char>(src[p]))) ++p;
                        const std::size_t nStart = p;
                        while (p < src.size() && std::isdigit(
                            static_cast<unsigned char>(src[p]))) ++p;
                        if (p > nStart) {
                            arraySize = std::atoi(src.substr(nStart, p - nStart).c_str());
                            if (arraySize < 1) arraySize = 1;
                        }
                    }
                    totalLocations += static_cast<std::size_t>(arraySize);
                    // (c) total-across-stage location cap.
                    if (static_cast<GLint>(totalLocations) > maxSrUnifLoc) {
                        programObject->linkLog =
                            "subroutine-uniform location count exceeds "
                            "GL_MAX_SUBROUTINE_UNIFORM_LOCATIONS="
                            + std::to_string(maxSrUnifLoc);
                        return false;
                    }
                    if (explicitLoc >= 0) {
                        // (b) explicit location must be < max, for
                        // all array-consumed locations.
                        for (GLint k = 0; k < arraySize; ++k) {
                            const GLint slot = explicitLoc + k;
                            if (slot >= maxSrUnifLoc) {
                                programObject->linkLog =
                                    "subroutine uniform location "
                                    + std::to_string(slot)
                                    + " >= GL_MAX_SUBROUTINE_UNIFORM_LOCATIONS="
                                    + std::to_string(maxSrUnifLoc);
                                return false;
                            }
                            // (a) duplicate-location check.
                            if (!usedLocations.insert(slot).second) {
                                programObject->linkLog =
                                    "subroutine uniform location "
                                    + std::to_string(slot)
                                    + " is reused across two declarations";
                                return false;
                            }
                        }
                    }
                }
                pos = p;
            }
            return true;
        };
        for (GLuint shaderId : programObject->attachedShaders) {
            GLShaderObject* sh = impl_->objects->shaders().get(shaderId);
            if (sh == nullptr) continue;
            if (!validateStage(sh->source)) {
                programObject->linked = false;
                Runtime::shared().recordShaderTranslation({
                    programTag, "link", "", "", "", programObject->linkLog, "", false
                });
                return false;
            }
        }
    }
    // ─── End subroutine uniform location validation ───

    // ─── GL 4.6 §7.4.2 cross-stage uniform-block matching ───
    // For each uniform block declared in multiple stages, the
    // instance-name presence must match. `uniform Data { ... };`
    // (no instance) in one stage and `uniform Data { ... } d;`
    // (with instance) in another is a link error.
    //
    // Members of no-instance-name blocks are promoted to the
    // default-uniform scope; their names must not collide with
    // other global uniforms nor with members of other no-instance-
    // name blocks that happen to have the same member name.
    //
    // CTS `shaders.uniform_block.common.name_matching` plants all
    // of these cases and expects link to fail on each mismatch.
    {
        // Scan `uniform <Name> { ... } [instance]?;` in a source.
        // Returns { blockName, hasInstance, memberIdentifiers }.
        struct BlockDecl {
            std::string blockName;
            bool hasInstance = false;
            std::vector<std::string> memberNames;
        };
        auto findUniformBlocks = [](const std::string& src) -> std::vector<BlockDecl> {
            std::vector<BlockDecl> blocks;
            std::size_t pos = 0;
            while (pos < src.size()) {
                // Locate the "uniform" keyword at a word boundary.
                std::size_t kw = src.find("uniform", pos);
                if (kw == std::string::npos) break;
                if (kw > 0) {
                    unsigned char prev = static_cast<unsigned char>(src[kw - 1]);
                    if (std::isalnum(prev) || prev == '_') {
                        pos = kw + 7;
                        continue;
                    }
                }
                std::size_t after = kw + 7;
                if (after < src.size()) {
                    unsigned char nx = static_cast<unsigned char>(src[after]);
                    if (std::isalnum(nx) || nx == '_') {
                        pos = after;
                        continue;
                    }
                }
                // Skip whitespace/newlines to the type / block-name token.
                while (after < src.size() && std::isspace(static_cast<unsigned char>(src[after]))) ++after;
                if (after >= src.size()) break;
                // Capture the identifier.
                std::size_t nameStart = after;
                while (after < src.size() &&
                       (std::isalnum(static_cast<unsigned char>(src[after])) || src[after] == '_')) {
                    ++after;
                }
                if (after == nameStart) { pos = after + 1; continue; }
                std::string name = src.substr(nameStart, after - nameStart);
                // Whitespace, then '{' for a block; otherwise it's a
                // plain uniform declaration like `uniform float f`.
                std::size_t braceStart = after;
                while (braceStart < src.size() && std::isspace(static_cast<unsigned char>(src[braceStart]))) ++braceStart;
                if (braceStart >= src.size() || src[braceStart] != '{') {
                    pos = after;
                    continue;
                }
                // Walk to the matching close brace.
                int depth = 1;
                std::size_t bodyStart = braceStart + 1;
                std::size_t cur = bodyStart;
                while (cur < src.size() && depth > 0) {
                    if (src[cur] == '{') ++depth;
                    else if (src[cur] == '}') --depth;
                    ++cur;
                }
                if (depth != 0) break;
                std::size_t bodyEnd = cur - 1;
                BlockDecl decl;
                decl.blockName = std::move(name);
                // Extract member identifiers from the block body by
                // scanning for `;`-terminated statements.
                std::size_t mp = bodyStart;
                while (mp < bodyEnd) {
                    std::size_t semi = src.find(';', mp);
                    if (semi == std::string::npos || semi >= bodyEnd) break;
                    // Walk backwards from the semi, skipping only
                    // whitespace + optional array-subscript block
                    // `[ ... ]`. The block may contain digits and
                    // whitespace. Previously we blindly stripped any
                    // trailing digits, which truncated `temp2;` to
                    // `temp`.
                    std::size_t e = semi;
                    auto skipWs = [&](std::size_t& p) {
                        while (p > mp) {
                            unsigned char c = static_cast<unsigned char>(src[p - 1]);
                            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
                                --p;
                            } else break;
                        }
                    };
                    skipWs(e);
                    if (e > mp && src[e - 1] == ']') {
                        // Walk back through the array-subscript brackets.
                        // Just look for the matching `[` — anything between
                        // (digits, whitespace, identifiers for sized types
                        // or constants) is allowed by GLSL.
                        int depth = 1;
                        while (e > mp && depth > 0) {
                            --e;
                            if (src[e] == ']') ++depth;
                            else if (src[e] == '[') --depth;
                        }
                        skipWs(e);
                    }
                    std::size_t b = e;
                    while (b > mp) {
                        unsigned char c = static_cast<unsigned char>(src[b - 1]);
                        if (std::isalnum(c) || c == '_') {
                            --b;
                        } else {
                            break;
                        }
                    }
                    if (b < e) {
                        decl.memberNames.push_back(src.substr(b, e - b));
                    }
                    mp = semi + 1;
                }
                // Detect instance name immediately past the closing brace.
                std::size_t tail = cur;
                while (tail < src.size() && std::isspace(static_cast<unsigned char>(src[tail]))) ++tail;
                if (tail < src.size()) {
                    unsigned char c = static_cast<unsigned char>(src[tail]);
                    if (std::isalpha(c) || c == '_') decl.hasInstance = true;
                }
                blocks.push_back(std::move(decl));
                pos = tail;
            }
            return blocks;
        };
        // Scan for plain `uniform <type> <name>;` declarations (not blocks).
        auto findPlainUniforms = [](const std::string& src) -> std::vector<std::string> {
            std::vector<std::string> names;
            std::size_t pos = 0;
            while (pos < src.size()) {
                std::size_t kw = src.find("uniform", pos);
                if (kw == std::string::npos) break;
                if (kw > 0) {
                    unsigned char prev = static_cast<unsigned char>(src[kw - 1]);
                    if (std::isalnum(prev) || prev == '_') {
                        pos = kw + 7;
                        continue;
                    }
                }
                std::size_t after = kw + 7;
                while (after < src.size() && std::isspace(static_cast<unsigned char>(src[after]))) ++after;
                // Consume type identifier.
                std::size_t t0 = after;
                while (after < src.size() &&
                       (std::isalnum(static_cast<unsigned char>(src[after])) || src[after] == '_')) {
                    ++after;
                }
                if (after == t0) { pos = after + 1; continue; }
                while (after < src.size() && std::isspace(static_cast<unsigned char>(src[after]))) ++after;
                if (after < src.size() && src[after] == '{') {
                    // Block declaration — skip past it.
                    int d = 1;
                    ++after;
                    while (after < src.size() && d > 0) {
                        if (src[after] == '{') ++d;
                        else if (src[after] == '}') --d;
                        ++after;
                    }
                    pos = after;
                    continue;
                }
                // Parse the uniform name.
                std::size_t n0 = after;
                while (after < src.size() &&
                       (std::isalnum(static_cast<unsigned char>(src[after])) || src[after] == '_')) {
                    ++after;
                }
                if (n0 < after) {
                    names.push_back(src.substr(n0, after - n0));
                }
                pos = after;
            }
            return names;
        };

        std::unordered_map<std::string, std::vector<bool>> blockInstancePresence;
        std::unordered_map<std::string, std::vector<std::string>>
            noInstanceMemberNamesByBlock;
        std::unordered_set<std::string> plainUniformNames;
        for (GLuint shaderId : programObject->attachedShaders) {
            GLShaderObject* sh = impl_->objects->shaders().get(shaderId);
            if (sh == nullptr) continue;
            auto blocks = findUniformBlocks(sh->source);
            for (auto& b : blocks) {
                blockInstancePresence[b.blockName].push_back(b.hasInstance);
                if (!b.hasInstance) {
                    auto& list = noInstanceMemberNamesByBlock[b.blockName];
                    list.insert(list.end(), b.memberNames.begin(), b.memberNames.end());
                }
            }
            auto plain = findPlainUniforms(sh->source);
            for (auto& n : plain) plainUniformNames.insert(n);
        }

        // Rule 1: same block name across stages → instance presence must match.
        for (const auto& [bname, flags] : blockInstancePresence) {
            bool anyWithInstance = false, anyWithoutInstance = false;
            for (bool f : flags) {
                if (f) anyWithInstance = true; else anyWithoutInstance = true;
            }
            if (anyWithInstance && anyWithoutInstance) {
                programObject->linkLog = "uniform block '" + bname +
                    "' must use the same instance-name presence in every stage";
                programObject->linked = false;
                Runtime::shared().recordShaderTranslation({
                    programTag, "link", "", "", "", programObject->linkLog, "", false
                });
                return false;
            }
        }

        // Rule 2: no-instance-name block members collide with plain
        // uniforms of the same name (different stages count too).
        for (const auto& [bname, members] : noInstanceMemberNamesByBlock) {
            for (const auto& m : members) {
                if (plainUniformNames.count(m)) {
                    programObject->linkLog = "uniform block member '" + m +
                        "' (in block '" + bname +
                        "') collides with plain uniform of the same name";
                    programObject->linked = false;
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", programObject->linkLog, "", false
                    });
                    return false;
                }
            }
        }

        // Rule 3: different no-instance-name blocks must not share
        // member names (both promote members into the default scope).
        std::unordered_map<std::string, std::string> memberOwner;  // memberName → blockName
        for (const auto& [bname, members] : noInstanceMemberNamesByBlock) {
            for (const auto& m : members) {
                auto it = memberOwner.find(m);
                if (it != memberOwner.end() && it->second != bname) {
                    programObject->linkLog = "no-instance-name blocks '" +
                        it->second + "' and '" + bname +
                        "' both declare a member '" + m + "'";
                    programObject->linked = false;
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", programObject->linkLog, "", false
                    });
                    return false;
                }
                memberOwner[m] = bname;
            }
        }
    }
    // ─── End cross-stage uniform-block matching ───

    programObject->linked = true;
    programObject->linkLog = "ok";
    // Snapshot the separability request at link time. The query
    // `glGetProgramiv(program, GL_PROGRAM_SEPARABLE)` returns this
    // snapshot — it matches the program's *linked* binary, not the
    // request-level parameter. See GLProgramObject::separableLinked.
    programObject->separableLinked = programObject->separable;

    // Populate GL 4.3 program resource introspection tables from the
    // reflection data we already gathered above.
    programObject->resourceUniforms.clear();
    programObject->resourceUniformBlocks.clear();
    programObject->resourceInputs.clear();
    programObject->resourceOutputs.clear();
    programObject->resourceStorageBlocks.clear();
    programObject->resourceAtomicCounterBuffers.clear();
    programObject->resourceBufferVariables.clear();
    for (int s = 0; s < 6; ++s) {
        programObject->resourceSubroutines[s].clear();
        programObject->resourceSubroutineUniforms[s].clear();
    }
    programObject->ssboBindingRemap.clear();

    // Per-stage "referenced by" bitmask for program-resource
    // introspection. GL 4.6 Table 23.40 defines
    // GL_REFERENCED_BY_<stage>_SHADER as a query property;
    // glGetProgramResourceiv returns 1 iff the resource is
    // referenced by the named stage. Previously we hard-coded
    // VS+FS (0x03) on every uniform, which tripped CTS
    // `geometry_shader.program_resource.program_resource`
    // whenever a GS-attached program queried the
    // GEOMETRY_SHADER bit. Derive the bitmask from each
    // attached stage's declaredUniforms so every stage the
    // scanner saw contributes a bit, and we pick up GS / TCS /
    // TES / compute automatically.
    const GLbitfield kBitVertex   = 0x01;
    const GLbitfield kBitFragment = 0x02;
    const GLbitfield kBitGeometry = 0x04;
    const GLbitfield kBitTessCtrl = 0x08;
    const GLbitfield kBitTessEval = 0x10;
    const GLbitfield kBitCompute  = 0x20;
    auto stageBitFor = [&](GLenum stage) -> GLbitfield {
        switch (stage) {
            case GL_VERTEX_SHADER:          return kBitVertex;
            case GL_FRAGMENT_SHADER:        return kBitFragment;
            case GL_GEOMETRY_SHADER:        return kBitGeometry;
            case GL_TESS_CONTROL_SHADER:    return kBitTessCtrl;
            case GL_TESS_EVALUATION_SHADER: return kBitTessEval;
            case GL_COMPUTE_SHADER:         return kBitCompute;
            default:                        return 0;
        }
    };
    // Build a GS-side "actually referenced" uniform-name set by
    // walking the GS SPIR-V at link time. Needed because our
    // per-stage scanner records DECLARATIONS, not USAGE — shared
    // common headers that declare a uniform in every stage would
    // spuriously set the stage bit for every stage even when the
    // GLSL body never uses the uniform. For VS/FS we get usage
    // via SPIRV-Cross's `get_active_interface_variables()` at
    // block granularity; for plain uniforms (default block) and
    // per-member accuracy we fall back to this raw walk.
    std::unordered_set<std::string> gsRefSet;
    if (geometryShader != nullptr && !geometryShader->spirv.empty()) {
        gsRefSet = appgl::scanStageReferencedUniforms(geometryShader->spirv);
    }

    auto computeStageMask = [&](const std::string& name) -> GLbitfield {
        GLbitfield mask = 0;
        for (GLuint shaderId : programObject->attachedShaders) {
            GLShaderObject* shaderObject = impl_->objects->shaders().get(shaderId);
            if (shaderObject == nullptr) continue;
            const GLbitfield bit = stageBitFor(shaderObject->stage);
            if (bit == 0) continue;
            for (const auto& decl : shaderObject->declaredUniforms) {
                if (decl.name == name) {
                    // For the GS stage, narrow by actual usage —
                    // the scanner reports declarations (shared
                    // common headers), SPIR-V tells us what's
                    // used. Without this, CTS
                    // `program_resource.program_resource` saw
                    // `uni_model_view_projection` (declared in
                    // both VS and GS via common header, used only
                    // by VS) as GS-referenced.
                    if (shaderObject->stage == GL_GEOMETRY_SHADER) {
                        if (gsRefSet.empty() || gsRefSet.count(name) != 0) {
                            mask |= bit;
                        }
                    } else {
                        mask |= bit;
                    }
                    break;
                }
            }
        }
        // If the uniform wasn't declared anywhere (shouldn't
        // happen — it's in the linked program's uniform table)
        // fall back to the old conservative VS+FS default.
        if (mask == 0) mask = kBitVertex | kBitFragment;
        return mask;
    };

    for (const auto& u : programObject->uniforms) {
        GLProgramResourceEntry entry;
        // GL 4.6 §7.3.1: array uniforms report their name with the
        // "[0]" suffix in the resource interface — EVEN for
        // 1-element arrays. CTS `program_interface_query.uniform-
        // types` declares `uniform uvec2 c[3];` / `uniform mat2
        // g[8];` and CTS `no-locations` declares `in vec4 c[1];`
        // — both expect `glGetProgramResourceName(GL_UNIFORM, …)`
        // to return "c[0]" / "g[0]". The `isArray` flag
        // distinguishes array declarations from plain scalars
        // (`arraySize` alone can't, since both non-arrays and
        // 1-element arrays have arraySize==1).
        entry.name = u.isArray ? (u.name + "[0]") : u.name;
        entry.type = u.type;
        entry.location = u.location;
        entry.binding = u.explicitBinding;  // RC-D08
        entry.arraySize = u.arraySize;
        entry.isArray = u.isArray;
        entry.referencedBy = computeStageMask(u.name);
        if (u.type == GL_UNSIGNED_INT_ATOMIC_COUNTER) {
            // Offset defaults to 0 when the GLSL didn't carry
            // `layout(offset = N)` on the first counter of a binding
            // — this is close enough for CTS
            // `program_interface_query.atomic-counters` which always
            // supplies an explicit offset. atomicCounterBufferIndex
            // is filled in below after the ACB table is built.
            entry.atomicCounterOffset = u.explicitOffset >= 0 ? u.explicitOffset : 0;
        }
        programObject->resourceUniforms.push_back(std::move(entry));
    }

    // ─── Build GL_ATOMIC_COUNTER_BUFFER resource entries ────────────────
    // GL 4.6 §7.3.1 Table 7.12: the ATOMIC_COUNTER_BUFFER interface
    // exposes one resource per distinct `binding` index that any
    // atomic_uint uniform targets. For each buffer:
    //   BUFFER_BINDING      = binding index
    //   BUFFER_DATA_SIZE    = max(offset + sizeof(uint) * N) across
    //                          the counters in that binding
    //   NUM_ACTIVE_VARIABLES= number of atomic_uint uniforms that
    //                          target the binding
    //   ACTIVE_VARIABLES    = their indices into resourceUniforms
    //   REFERENCED_BY_*     = union of referencedBy bitmasks
    //                          of the participating uniforms
    // CTS `program_interface_query.atomic-counters` exercises this
    // interface end-to-end.
    {
        struct AcbAccumulator {
            GLint binding = 0;
            GLint dataSize = 0;                 // BUFFER_DATA_SIZE
            std::vector<GLint> activeVariables; // indices into resourceUniforms
            GLbitfield referencedBy = 0;
        };
        std::vector<AcbAccumulator> acbs;
        // Walk resourceUniforms (post-build) so we record the
        // post-"[0]"-suffix index of each atomic uniform.
        for (std::size_t i = 0; i < programObject->resourceUniforms.size(); ++i) {
            auto& ue = programObject->resourceUniforms[i];
            if (ue.type != GL_UNSIGNED_INT_ATOMIC_COUNTER) continue;
            const GLint bind = ue.binding < 0 ? 0 : ue.binding;
            const GLint off = ue.atomicCounterOffset >= 0 ? ue.atomicCounterOffset : 0;
            const GLint count = ue.arraySize > 0 ? ue.arraySize : 1;
            const GLint endByte = off + 4 * count;
            std::size_t bucket = acbs.size();
            for (std::size_t j = 0; j < acbs.size(); ++j) {
                if (acbs[j].binding == bind) { bucket = j; break; }
            }
            if (bucket == acbs.size()) {
                acbs.push_back(AcbAccumulator{});
                acbs.back().binding = bind;
            }
            auto& acb = acbs[bucket];
            if (endByte > acb.dataSize) acb.dataSize = endByte;
            acb.activeVariables.push_back(static_cast<GLint>(i));
            acb.referencedBy |= ue.referencedBy;
            ue.atomicCounterBufferIndex = static_cast<GLint>(bucket);
        }
        for (const auto& acb : acbs) {
            GLProgramResourceEntry be;
            // ATOMIC_COUNTER_BUFFER resources have no name; leave empty.
            be.name = "";
            be.binding = acb.binding;
            be.offset = acb.dataSize;          // reuse offset slot as BUFFER_DATA_SIZE
            be.activeVariables = acb.activeVariables;
            be.referencedBy = acb.referencedBy;
            programObject->resourceAtomicCounterBuffers.push_back(std::move(be));
        }
    }
    // ─── End ATOMIC_COUNTER_BUFFER build ────────────────────────────────
    for (const auto& a : programObject->attributes) {
        GLProgramResourceEntry entry;
        // GL 4.6 §7.3.1: for array inputs, the resource name ends
        // with "[0]" — even for 1-element arrays like `in vec4
        // c[1]`. `a.isArray` is the authoritative "declared with
        // array syntax" flag (`a.arraySize==1` alone can't
        // distinguish non-arrays from 1-element arrays).
        entry.name = a.isArray ? (a.name + "[0]") : a.name;
        entry.type = a.type;
        entry.location = a.location;
        entry.arraySize = a.arraySize;
        entry.isArray = a.isArray;
        entry.referencedBy = 0x01; // vertex
        programObject->resourceInputs.push_back(std::move(entry));
    }
    // Fragment outputs: populate from fragment shader declared outputs.
    for (GLuint shaderId : programObject->attachedShaders) {
        GLShaderObject* shaderObject = impl_->objects->shaders().get(shaderId);
        if (shaderObject == nullptr) continue;
        if (shaderObject->stage == GL_FRAGMENT_SHADER) {
            GLint nextOutputLoc = 0;
            for (const auto& output : shaderObject->declaredOutputs) {
                GLProgramResourceEntry entry;
                // GL 4.6 §7.3.1: array outputs report their name with
                // the "[0]" suffix (same convention as inputs). CTS
                // `output-types` expects "a[0]" / "c[0]" / "d[0]"
                // and `no-locations` has `out vec4 d[1]` which must
                // also report "d[0]" despite arraySize==1 — use
                // `isArray` to distinguish.
                entry.name = output.isArray
                    ? (output.name + "[0]") : output.name;
                entry.type = output.type;
                entry.arraySize = output.arraySize;
                entry.isArray = output.isArray;
                // Resolve location: per-name bind via
                // glBindFragDataLocation wins over the GLSL
                // `layout(location=…)` qualifier per GL 4.6 §15.2.
                // Only applied pre-link; the map is authoritative at
                // this point.
                GLint location = -1;
                auto bindIt = programObject->requestedFragDataLocations.find(output.name);
                if (bindIt != programObject->requestedFragDataLocations.end()) {
                    location = static_cast<GLint>(bindIt->second);
                } else if (output.explicitLocation >= 0) {
                    location = output.explicitLocation;
                } else {
                    location = nextOutputLoc;
                }
                entry.location = location;
                // Dual-source-blend index set by
                // glBindFragDataLocationIndexed OR the GLSL-side
                // `layout(index=N)` qualifier (GL 4.6 §15.2). API
                // binding wins when both are present pre-link.
                auto idxIt = programObject->requestedFragDataLocationIndices.find(output.name);
                if (idxIt != programObject->requestedFragDataLocationIndices.end()) {
                    entry.locationIndex = static_cast<GLint>(idxIt->second);
                } else if (output.explicitIndex >= 0) {
                    entry.locationIndex = output.explicitIndex;
                }
                entry.referencedBy = 0x02; // fragment
                // GL 4.6 §15.2: array outputs consume `arraySize`
                // consecutive locations.
                const GLint consumed = std::max<GLint>(1, output.arraySize);
                if (location + consumed > nextOutputLoc) {
                    nextOutputLoc = location + consumed;
                }
                programObject->resourceOutputs.push_back(std::move(entry));
            }
        }
    }

    // Built-in program input/output entries. GL 4.6 §7.3.1.1
    // treats built-ins used by the first-stage/last-stage as
    // program inputs/outputs respectively (e.g.
    // `gl_VertexID` / `gl_InstanceID` become GL_PROGRAM_INPUT
    // on a VS-first program, `gl_FragDepth` /
    // `gl_SampleMask[0]` become GL_PROGRAM_OUTPUT on an
    // FS-last program). User-declared inputs/outputs are
    // already populated above. A simple source-text scan
    // catches the common set used by CTS
    // `program_interface_query.input-built-in` /
    // `output-built-in`.
    {
        // Word-boundary presence check — avoids matching
        // "some_gl_VertexID_hack" or "// gl_VertexID" comments
        // by demanding the match lie between non-identifier
        // characters. CTS GLSL sources don't have such names
        // so a plain find() would also work for the test set,
        // but the word-boundary check costs nothing and
        // future-proofs.
        auto sourceUsesIdent = [](const std::string& src, const char* ident) {
            const std::size_t ilen = std::strlen(ident);
            std::size_t pos = 0;
            while ((pos = src.find(ident, pos)) != std::string::npos) {
                const bool leftBoundary = (pos == 0) ||
                    !(std::isalnum(static_cast<unsigned char>(src[pos - 1])) || src[pos - 1] == '_');
                const bool rightBoundary = (pos + ilen == src.size()) ||
                    !(std::isalnum(static_cast<unsigned char>(src[pos + ilen])) || src[pos + ilen] == '_');
                if (leftBoundary && rightBoundary) return true;
                pos += ilen;
            }
            return false;
        };
        // Helper: append a synthetic built-in entry if absent
        // from the table. Built-ins don't have user-visible
        // locations, so GL_LOCATION returns -1.
        auto addBuiltIn = [&](std::vector<GLProgramResourceEntry>& table,
                              const std::string& name, GLenum type,
                              GLbitfield referencedBy, bool isArray = false,
                              GLint arraySize = 1) {
            for (const auto& e : table) {
                if (e.name == name) return;  // already present
            }
            GLProgramResourceEntry entry;
            entry.name = name;
            entry.type = type;
            entry.location = -1;
            entry.arraySize = arraySize;
            entry.referencedBy = referencedBy;
            (void)isArray;   // array-ness is baked into the
                             // canonical name (e.g. "gl_SampleMask[0]")
            table.push_back(std::move(entry));
        };
        GLShaderObject* vsShader = nullptr;
        GLShaderObject* fsShader = nullptr;
        for (GLuint shaderId : programObject->attachedShaders) {
            GLShaderObject* s = impl_->objects->shaders().get(shaderId);
            if (s == nullptr) continue;
            if (s->stage == GL_VERTEX_SHADER)   vsShader = s;
            if (s->stage == GL_FRAGMENT_SHADER) fsShader = s;
        }
        if (vsShader != nullptr) {
            const auto& src = vsShader->source;
            if (sourceUsesIdent(src, "gl_VertexID")) {
                addBuiltIn(programObject->resourceInputs,
                    "gl_VertexID", GL_INT, 0x01 /*vertex*/);
            }
            if (sourceUsesIdent(src, "gl_InstanceID")) {
                addBuiltIn(programObject->resourceInputs,
                    "gl_InstanceID", GL_INT, 0x01);
            }
            if (sourceUsesIdent(src, "gl_DrawID")) {
                addBuiltIn(programObject->resourceInputs,
                    "gl_DrawID", GL_INT, 0x01);
            }
            if (sourceUsesIdent(src, "gl_BaseVertex")) {
                addBuiltIn(programObject->resourceInputs,
                    "gl_BaseVertex", GL_INT, 0x01);
            }
            if (sourceUsesIdent(src, "gl_BaseInstance")) {
                addBuiltIn(programObject->resourceInputs,
                    "gl_BaseInstance", GL_INT, 0x01);
            }
        }
        if (fsShader != nullptr) {
            const auto& src = fsShader->source;
            if (sourceUsesIdent(src, "gl_FragDepth")) {
                addBuiltIn(programObject->resourceOutputs,
                    "gl_FragDepth", GL_FLOAT, 0x02 /*fragment*/);
            }
            if (sourceUsesIdent(src, "gl_SampleMask")) {
                // `gl_SampleMask[0]` canonical name; array size
                // depends on MAX_SAMPLE_MASK_WORDS but is 1 on
                // most desktop / Apple Metal hardware.
                addBuiltIn(programObject->resourceOutputs,
                    "gl_SampleMask[0]", GL_INT, 0x02,
                    /*isArray=*/true, /*arraySize=*/1);
            }
        }
        // Separable FS: its `in` varyings become the program's
        // GL_PROGRAM_INPUT. For regular linked programs the FS
        // inputs are cross-stage varyings (consumed by linker, not
        // exposed as program inputs). But for a separable FS there's
        // no preceding-stage program, so the FS inputs ARE the
        // program inputs per GL 4.6 §7.3.1.1. CTS
        // `separate-programs-fragment` declares `in vec4 vs_color;`
        // and expects ACTIVE_RESOURCES=1 on GL_PROGRAM_INPUT.
        if (programObject->separable && vsShader == nullptr && fsShader != nullptr) {
            GLint nextInputLoc = 0;
            for (const auto& input : fsShader->declaredInputs) {
                GLProgramResourceEntry entry;
                entry.name = input.isArray
                    ? (input.name + "[0]") : input.name;
                entry.type = input.type;
                entry.arraySize = input.arraySize;
                entry.isArray = input.isArray;
                entry.location = input.explicitLocation >= 0
                    ? input.explicitLocation : nextInputLoc;
                entry.referencedBy = 0x02;  // fragment
                const GLint consumed = std::max<GLint>(1, input.arraySize);
                nextInputLoc = entry.location + consumed;
                programObject->resourceInputs.push_back(std::move(entry));
            }
        }
        // Separable GS / TCS / TES: their `in` interface blocks
        // (typically `in gl_PerVertex { … } gl_in[]`) become
        // GL_PROGRAM_INPUT. CTS `separate-programs-geometry`
        // declares `in gl_PerVertex { vec4 gl_Position; … } gl_in[];`
        // and queries `glGetProgramResourceIndex(GL_PROGRAM_INPUT,
        // "gl_PerVertex.gl_Position")`. Naming follows §7.3.1.1:
        // with an instance name (`gl_in` here, or bare), members
        // are prefixed with the block TYPE name.
        {
            GLShaderObject* firstNonVsStage = nullptr;
            if (programObject->separable && vsShader == nullptr && fsShader == nullptr) {
                for (GLuint shaderId : programObject->attachedShaders) {
                    GLShaderObject* s = impl_->objects->shaders().get(shaderId);
                    if (s == nullptr) continue;
                    if (s->stage == GL_GEOMETRY_SHADER ||
                        s->stage == GL_TESS_CONTROL_SHADER ||
                        s->stage == GL_TESS_EVALUATION_SHADER) {
                        firstNonVsStage = s;
                        break;
                    }
                }
            }
            if (firstNonVsStage != nullptr) {
                const GLbitfield stageBit =
                    (firstNonVsStage->stage == GL_GEOMETRY_SHADER)        ? 0x04 :
                    (firstNonVsStage->stage == GL_TESS_CONTROL_SHADER)    ? 0x08 :
                    (firstNonVsStage->stage == GL_TESS_EVALUATION_SHADER) ? 0x10 : 0;
                const std::string& src = firstNonVsStage->source;
                GLint nextInputLoc = 0;
                // Per-stage built-in inputs exposed on separable
                // programs. GL 4.6 §7.3.1.1 treats these as
                // GL_PROGRAM_INPUT when the stage is the first stage
                // of its own program. CTS
                // `separate-programs-tess-control` expects
                // `gl_InvocationID` in the input list (length 16).
                auto sourceUsesIdent2 = [](const std::string& s, const char* ident) {
                    const std::size_t ilen = std::strlen(ident);
                    std::size_t pos = 0;
                    while ((pos = s.find(ident, pos)) != std::string::npos) {
                        const bool lb = (pos == 0) ||
                            !(std::isalnum(static_cast<unsigned char>(s[pos - 1])) || s[pos - 1] == '_');
                        const bool rb = (pos + ilen == s.size()) ||
                            !(std::isalnum(static_cast<unsigned char>(s[pos + ilen])) || s[pos + ilen] == '_');
                        if (lb && rb) return true;
                        pos += ilen;
                    }
                    return false;
                };
                auto pushBuiltinInput = [&](const char* name, GLenum type) {
                    GLProgramResourceEntry entry;
                    entry.name = name;
                    entry.type = type;
                    entry.location = -1;
                    entry.arraySize = 1;
                    entry.referencedBy = stageBit;
                    programObject->resourceInputs.push_back(std::move(entry));
                };
                if (firstNonVsStage->stage == GL_TESS_CONTROL_SHADER ||
                    firstNonVsStage->stage == GL_TESS_EVALUATION_SHADER) {
                    if (sourceUsesIdent2(src, "gl_InvocationID")) {
                        pushBuiltinInput("gl_InvocationID", GL_INT);
                    }
                    if (sourceUsesIdent2(src, "gl_PatchVerticesIn")) {
                        pushBuiltinInput("gl_PatchVerticesIn", GL_INT);
                    }
                    if (sourceUsesIdent2(src, "gl_PrimitiveID")) {
                        pushBuiltinInput("gl_PrimitiveID", GL_INT);
                    }
                }
                if (firstNonVsStage->stage == GL_TESS_EVALUATION_SHADER) {
                    if (sourceUsesIdent2(src, "gl_TessCoord")) {
                        pushBuiltinInput("gl_TessCoord", GL_FLOAT_VEC3);
                    }
                    if (sourceUsesIdent2(src, "gl_TessLevelOuter")) {
                        pushBuiltinInput("gl_TessLevelOuter", GL_FLOAT);
                    }
                    if (sourceUsesIdent2(src, "gl_TessLevelInner")) {
                        pushBuiltinInput("gl_TessLevelInner", GL_FLOAT);
                    }
                }
                if (firstNonVsStage->stage == GL_GEOMETRY_SHADER) {
                    if (sourceUsesIdent2(src, "gl_PrimitiveIDIn")) {
                        pushBuiltinInput("gl_PrimitiveIDIn", GL_INT);
                    }
                    if (sourceUsesIdent2(src, "gl_InvocationID")) {
                        pushBuiltinInput("gl_InvocationID", GL_INT);
                    }
                }
                // Source-text scan for `in <BlockName> { <members> } [<inst>] ;`
                // — mirrors the output-block scan in the VS/TES/GS
                // separable output path below.
                const std::string inKw = "in ";
                std::size_t sp = 0;
                while ((sp = src.find(inKw, sp)) != std::string::npos) {
                    const bool lb = (sp == 0) ||
                        !(std::isalnum(static_cast<unsigned char>(src[sp - 1])) || src[sp - 1] == '_');
                    if (!lb) { sp += inKw.size(); continue; }
                    std::size_t p = sp + inKw.size();
                    while (p < src.size() && (src[p] == ' ' || src[p] == '\t')) ++p;
                    const std::size_t nameStart = p;
                    while (p < src.size() &&
                           (std::isalnum(static_cast<unsigned char>(src[p])) || src[p] == '_')) ++p;
                    const std::string blockName = src.substr(nameStart, p - nameStart);
                    if (blockName.empty()) { sp += inKw.size(); continue; }
                    while (p < src.size() &&
                           (src[p] == ' ' || src[p] == '\t' || src[p] == '\n' || src[p] == '\r')) ++p;
                    if (p >= src.size() || src[p] != '{') {
                        sp += inKw.size();
                        continue;
                    }
                    const std::size_t bodyStart = p + 1;
                    int depth = 1;
                    std::size_t q = bodyStart;
                    while (q < src.size() && depth > 0) {
                        if (src[q] == '{') ++depth;
                        else if (src[q] == '}') --depth;
                        ++q;
                    }
                    if (depth != 0) { sp = p + 1; continue; }
                    const std::string body = src.substr(bodyStart, q - 1 - bodyStart);
                    std::size_t stmtStart = 0;
                    while (stmtStart < body.size()) {
                        const std::size_t semi = body.find(';', stmtStart);
                        if (semi == std::string::npos) break;
                        std::string stmt = body.substr(stmtStart, semi - stmtStart);
                        stmtStart = semi + 1;
                        auto lstrip = [](std::string& s) {
                            std::size_t i = 0;
                            while (i < s.size() && std::isspace(static_cast<unsigned char>(s[i]))) ++i;
                            s.erase(0, i);
                        };
                        auto rstrip = [](std::string& s) {
                            while (!s.empty() && std::isspace(static_cast<unsigned char>(s.back()))) s.pop_back();
                        };
                        lstrip(stmt); rstrip(stmt);
                        if (stmt.empty()) continue;
                        // Parse "TYPE name[ array ]".
                        std::size_t ws = 0;
                        while (ws < stmt.size() && !std::isspace(static_cast<unsigned char>(stmt[ws]))) ++ws;
                        const std::string typeWord = stmt.substr(0, ws);
                        std::string rest = stmt.substr(ws);
                        lstrip(rest);
                        GLenum memberType = GL_FLOAT;
                        if (typeWord == "float")      memberType = GL_FLOAT;
                        else if (typeWord == "vec2")  memberType = GL_FLOAT_VEC2;
                        else if (typeWord == "vec3")  memberType = GL_FLOAT_VEC3;
                        else if (typeWord == "vec4")  memberType = GL_FLOAT_VEC4;
                        else if (typeWord == "int")   memberType = GL_INT;
                        else if (typeWord == "ivec2") memberType = GL_INT_VEC2;
                        else if (typeWord == "ivec3") memberType = GL_INT_VEC3;
                        else if (typeWord == "ivec4") memberType = GL_INT_VEC4;
                        else if (typeWord == "uint")  memberType = GL_UNSIGNED_INT;
                        else if (typeWord == "uvec2") memberType = GL_UNSIGNED_INT_VEC2;
                        else if (typeWord == "uvec3") memberType = GL_UNSIGNED_INT_VEC3;
                        else if (typeWord == "uvec4") memberType = GL_UNSIGNED_INT_VEC4;
                        else if (typeWord == "mat2")  memberType = GL_FLOAT_MAT2;
                        else if (typeWord == "mat3")  memberType = GL_FLOAT_MAT3;
                        else if (typeWord == "mat4")  memberType = GL_FLOAT_MAT4;
                        // Walk the rest token-by-token: comma-separated
                        // names, each optionally followed by `[size]`.
                        std::size_t namePos = 0;
                        while (namePos < rest.size()) {
                            while (namePos < rest.size() && std::isspace(static_cast<unsigned char>(rest[namePos]))) ++namePos;
                            std::size_t nameEnd = namePos;
                            while (nameEnd < rest.size() &&
                                   (std::isalnum(static_cast<unsigned char>(rest[nameEnd])) ||
                                    rest[nameEnd] == '_')) ++nameEnd;
                            if (nameEnd == namePos) break;
                            const std::string memberName = rest.substr(namePos, nameEnd - namePos);
                            namePos = nameEnd;
                            // Skip array subscript if present.
                            while (namePos < rest.size() && std::isspace(static_cast<unsigned char>(rest[namePos]))) ++namePos;
                            if (namePos < rest.size() && rest[namePos] == '[') {
                                int bd = 1; ++namePos;
                                while (namePos < rest.size() && bd > 0) {
                                    if (rest[namePos] == '[') ++bd;
                                    else if (rest[namePos] == ']') --bd;
                                    ++namePos;
                                }
                            }
                            GLProgramResourceEntry entry;
                            entry.name = blockName + "." + memberName;
                            entry.type = memberType;
                            entry.arraySize = 1;
                            entry.location = nextInputLoc++;
                            entry.referencedBy = stageBit;
                            programObject->resourceInputs.push_back(std::move(entry));
                            // Advance past any trailing `,`.
                            while (namePos < rest.size() &&
                                   (rest[namePos] == ' ' || rest[namePos] == '\t' ||
                                    rest[namePos] == ',')) ++namePos;
                        }
                    }
                    sp = q;
                }
            }
        }
        // Separable programs: the last vertex-processing stage's
        // outputs become the program's `GL_PROGRAM_OUTPUT`. For a
        // separable VS / GS / TES-only program those stages' built-in
        // `gl_Position` (and user-declared varyings / output blocks)
        // are the program outputs. CTS
        // `program_interface_query.separate-programs-vertex` declares
        // `out Color { float r, g, b; vec4 iLikePie; } vs_color;` and
        // `out gl_PerVertex { vec4 gl_Position; };` in the VS and
        // expects ACTIVE_RESOURCES=5 on GL_PROGRAM_OUTPUT.
        if (programObject->separable && fsShader == nullptr) {
            GLShaderObject* lastVsStage = nullptr;
            for (GLuint shaderId : programObject->attachedShaders) {
                GLShaderObject* s = impl_->objects->shaders().get(shaderId);
                if (s == nullptr) continue;
                if (s->stage == GL_VERTEX_SHADER ||
                    s->stage == GL_TESS_CONTROL_SHADER ||
                    s->stage == GL_TESS_EVALUATION_SHADER ||
                    s->stage == GL_GEOMETRY_SHADER) {
                    lastVsStage = s;
                }
            }
            if (lastVsStage != nullptr) {
                // `gl_Position` is always an output of the last vertex-
                // processing stage (GL 4.6 §11.1). Canonical name +
                // type, no location. For TCS/TES/GS the stage
                // re-declares `out gl_PerVertex { ... } gl_out[]`, so
                // spec §7.3.1.1 names the output `gl_PerVertex.gl_Position`
                // — see the output-block scan below.
                const GLbitfield stageBit =
                    (lastVsStage->stage == GL_VERTEX_SHADER) ? 0x01 :
                    (lastVsStage->stage == GL_TESS_CONTROL_SHADER) ? 0x08 :
                    (lastVsStage->stage == GL_TESS_EVALUATION_SHADER) ? 0x10 :
                    (lastVsStage->stage == GL_GEOMETRY_SHADER) ? 0x04 : 0;
                // Only VS exposes bare `gl_Position`; other stages
                // get the member named through the out-gl_PerVertex block.
                if (lastVsStage->stage == GL_VERTEX_SHADER) {
                    addBuiltIn(programObject->resourceOutputs,
                               "gl_Position", GL_FLOAT_VEC4, stageBit);
                }
                // User varyings declared as simple `out TYPE name;` in
                // VS are already picked up by the scanner's
                // declaredOutputs. We'd push them into resourceOutputs
                // below; but the existing FS loop skips non-FS stages.
                // Mirror it here for the VS-only separable case.
                GLint nextVaryingLoc = 0;
                // Pre-scan the stage source for `patch out ... NAME`
                // patterns so we can mark matching entries as
                // isPerPatch=true. TCS declares these for per-patch
                // outputs; TES can `patch in ...` but that's inputs.
                std::set<std::string> perPatchOutputNames;
                if (lastVsStage->stage == GL_TESS_CONTROL_SHADER) {
                    const std::string& s = lastVsStage->source;
                    const std::string patchKw = "patch ";
                    std::size_t pp = 0;
                    while ((pp = s.find(patchKw, pp)) != std::string::npos) {
                        const bool lb = (pp == 0) ||
                            !(std::isalnum(static_cast<unsigned char>(s[pp - 1])) || s[pp - 1] == '_');
                        if (!lb) { pp += patchKw.size(); continue; }
                        std::size_t q2 = pp + patchKw.size();
                        while (q2 < s.size() && std::isspace(static_cast<unsigned char>(s[q2]))) ++q2;
                        // Expect "out".
                        if (q2 + 3 < s.size() && s.compare(q2, 3, "out") == 0 &&
                            !(std::isalnum(static_cast<unsigned char>(s[q2 + 3])) || s[q2 + 3] == '_')) {
                            q2 += 3;
                            while (q2 < s.size() && std::isspace(static_cast<unsigned char>(s[q2]))) ++q2;
                            // Read the type identifier.
                            while (q2 < s.size() &&
                                   (std::isalnum(static_cast<unsigned char>(s[q2])) || s[q2] == '_')) ++q2;
                            while (q2 < s.size() && std::isspace(static_cast<unsigned char>(s[q2]))) ++q2;
                            // Read the variable name.
                            std::size_t nameStart = q2;
                            while (q2 < s.size() &&
                                   (std::isalnum(static_cast<unsigned char>(s[q2])) || s[q2] == '_')) ++q2;
                            if (q2 > nameStart) {
                                perPatchOutputNames.insert(s.substr(nameStart, q2 - nameStart));
                            }
                        }
                        pp = q2;
                    }
                }
                for (const auto& output : lastVsStage->declaredOutputs) {
                    GLProgramResourceEntry entry;
                    entry.name = output.isArray
                        ? (output.name + "[0]") : output.name;
                    entry.type = output.type;
                    entry.arraySize = output.arraySize;
                    entry.isArray = output.isArray;
                    entry.location = output.explicitLocation >= 0
                        ? output.explicitLocation : nextVaryingLoc;
                    entry.referencedBy = stageBit;
                    // GL 4.6 §7.3.1: GL_LOCATION_INDEX is meaningful
                    // only for fragment shader outputs (dual-source
                    // blend index). VS / GS / TES outputs report -1.
                    entry.locationIndex = -1;
                    entry.isPerPatch = perPatchOutputNames.count(output.name) != 0;
                    const GLint consumed = std::max<GLint>(1, output.arraySize);
                    nextVaryingLoc = entry.location + consumed;
                    programObject->resourceOutputs.push_back(std::move(entry));
                }
                // Output interface blocks — the scanner can't see
                // them through its brace-depth bug, so do a focused
                // source-text scan for `out BlockName { members } inst;`.
                // Per GL 4.6 §7.3.1.1, members of a block WITH an
                // instance name are named "BlockTypeName.member".
                const std::string& vsSrc = lastVsStage->source;
                const std::string outKw = "out ";
                std::size_t scanPos = 0;
                while ((scanPos = vsSrc.find(outKw, scanPos)) != std::string::npos) {
                    const bool leftBoundary = (scanPos == 0) ||
                        !(std::isalnum(static_cast<unsigned char>(vsSrc[scanPos - 1])) ||
                          vsSrc[scanPos - 1] == '_');
                    if (!leftBoundary) { scanPos += outKw.size(); continue; }
                    // Parse the next identifier (block type name).
                    std::size_t p = scanPos + outKw.size();
                    while (p < vsSrc.size() &&
                           (vsSrc[p] == ' ' || vsSrc[p] == '\t')) { ++p; }
                    const std::size_t nameStart = p;
                    while (p < vsSrc.size() &&
                           (std::isalnum(static_cast<unsigned char>(vsSrc[p])) || vsSrc[p] == '_')) { ++p; }
                    const std::string blockName = vsSrc.substr(nameStart, p - nameStart);
                    if (blockName.empty()) { scanPos += outKw.size(); continue; }
                    // Expect '{' (possibly after whitespace).
                    while (p < vsSrc.size() &&
                           (vsSrc[p] == ' ' || vsSrc[p] == '\t' ||
                            vsSrc[p] == '\n' || vsSrc[p] == '\r')) { ++p; }
                    if (p >= vsSrc.size() || vsSrc[p] != '{') {
                        scanPos += outKw.size();
                        continue;
                    }
                    // Skip `out gl_PerVertex { ... };` ONLY for VS —
                    // bare `gl_Position` was already added via the
                    // built-in path. For TCS/TES/GS the test expects
                    // `gl_PerVertex.gl_Position` (block-member naming).
                    if (blockName == "gl_PerVertex" &&
                        lastVsStage->stage == GL_VERTEX_SHADER) {
                        scanPos = p + 1;
                        continue;
                    }
                    const std::size_t bodyStart = p + 1;
                    int depth = 1;
                    std::size_t q = bodyStart;
                    while (q < vsSrc.size() && depth > 0) {
                        if (vsSrc[q] == '{') ++depth;
                        else if (vsSrc[q] == '}') --depth;
                        ++q;
                    }
                    if (depth != 0) { scanPos = p + 1; continue; }
                    // Detect instance name after the closing `}`. If
                    // `} inst;` or `} inst[N];` → members use block-type-
                    // name prefix. If `} ;` (no instance) → bare member
                    // names. Per GL 4.6 §7.3.1.1.
                    std::size_t afterClose = q;
                    while (afterClose < vsSrc.size() &&
                           std::isspace(static_cast<unsigned char>(vsSrc[afterClose]))) ++afterClose;
                    const bool hasInstance = afterClose < vsSrc.size() &&
                        (std::isalpha(static_cast<unsigned char>(vsSrc[afterClose])) ||
                         vsSrc[afterClose] == '_');
                    // Body is vsSrc[bodyStart, q-1). Split on ';'.
                    const std::string body = vsSrc.substr(bodyStart, q - 1 - bodyStart);
                    std::size_t stmtStart = 0;
                    while (stmtStart < body.size()) {
                        const std::size_t semi = body.find(';', stmtStart);
                        if (semi == std::string::npos) break;
                        std::string stmt = body.substr(stmtStart, semi - stmtStart);
                        stmtStart = semi + 1;
                        // Tokenize: strip leading/trailing ws.
                        auto lstrip = [](std::string& s) {
                            std::size_t i = 0;
                            while (i < s.size() &&
                                   (s[i] == ' ' || s[i] == '\t' || s[i] == '\n' || s[i] == '\r')) ++i;
                            s.erase(0, i);
                        };
                        auto rstrip = [](std::string& s) {
                            while (!s.empty() &&
                                   (s.back() == ' ' || s.back() == '\t' ||
                                    s.back() == '\n' || s.back() == '\r')) s.pop_back();
                        };
                        lstrip(stmt); rstrip(stmt);
                        if (stmt.empty()) continue;
                        // Parse "TYPE name1[, name2, ...]".
                        std::size_t sp = 0;
                        while (sp < stmt.size() &&
                               !(stmt[sp] == ' ' || stmt[sp] == '\t')) ++sp;
                        const std::string typeWord = stmt.substr(0, sp);
                        std::string rest = stmt.substr(sp);
                        lstrip(rest);
                        GLenum memberType = GL_FLOAT;
                        if (typeWord == "float")      memberType = GL_FLOAT;
                        else if (typeWord == "vec2")  memberType = GL_FLOAT_VEC2;
                        else if (typeWord == "vec3")  memberType = GL_FLOAT_VEC3;
                        else if (typeWord == "vec4")  memberType = GL_FLOAT_VEC4;
                        else if (typeWord == "int")   memberType = GL_INT;
                        else if (typeWord == "ivec2") memberType = GL_INT_VEC2;
                        else if (typeWord == "ivec3") memberType = GL_INT_VEC3;
                        else if (typeWord == "ivec4") memberType = GL_INT_VEC4;
                        else if (typeWord == "uint")  memberType = GL_UNSIGNED_INT;
                        else if (typeWord == "uvec2") memberType = GL_UNSIGNED_INT_VEC2;
                        else if (typeWord == "uvec3") memberType = GL_UNSIGNED_INT_VEC3;
                        else if (typeWord == "uvec4") memberType = GL_UNSIGNED_INT_VEC4;
                        else if (typeWord == "mat2")  memberType = GL_FLOAT_MAT2;
                        else if (typeWord == "mat3")  memberType = GL_FLOAT_MAT3;
                        else if (typeWord == "mat4")  memberType = GL_FLOAT_MAT4;
                        // Multiple comma-separated names.
                        std::size_t namePos = 0;
                        while (namePos < rest.size()) {
                            std::size_t nameEnd = namePos;
                            while (nameEnd < rest.size() &&
                                   (std::isalnum(static_cast<unsigned char>(rest[nameEnd])) ||
                                    rest[nameEnd] == '_')) ++nameEnd;
                            if (nameEnd == namePos) break;
                            const std::string memberName =
                                rest.substr(namePos, nameEnd - namePos);
                            GLProgramResourceEntry entry;
                            // With-instance blocks use block-type-
                            // name prefix per §7.3.1.1; no-instance
                            // blocks use bare member names.
                            entry.name = hasInstance
                                ? (blockName + "." + memberName)
                                : memberName;
                            entry.type = memberType;
                            entry.arraySize = 1;
                            entry.location = nextVaryingLoc++;
                            entry.referencedBy = stageBit;
                            // VS varying block members: LOCATION_INDEX
                            // is only meaningful for FS outputs.
                            entry.locationIndex = -1;
                            programObject->resourceOutputs.push_back(std::move(entry));
                            namePos = nameEnd;
                            // Skip whitespace + optional ',' or trailing.
                            while (namePos < rest.size() &&
                                   (rest[namePos] == ' ' || rest[namePos] == ',' ||
                                    rest[namePos] == '\t' || rest[namePos] == '\n')) ++namePos;
                        }
                    }
                    scanPos = q;
                }
            }
        }
    }

    // GL 4.0 subroutines — populate per-stage
    // `resourceSubroutines[stage]` / `resourceSubroutineUniforms[stage]`
    // from each attached shader's GLSL source. No SPIR-V path: we
    // don't emulate Metal-side subroutine dispatch yet, but
    // introspection queries work so `glGetSubroutineUniformLocation`
    // / `glGetActiveSubroutineUniformiv` / PIQ's
    // `GL_*_SUBROUTINE*` interfaces all report spec-correct metadata.
    // CTS `program_interface_query.subroutines-{vertex,tcs,tes,gs,fragment,compute}`
    // exercise these six stages independently.
    {
        auto stageIndex = [](GLenum st) -> int {
            switch (st) {
                case GL_VERTEX_SHADER:          return 0;
                case GL_TESS_CONTROL_SHADER:    return 1;
                case GL_TESS_EVALUATION_SHADER: return 2;
                case GL_GEOMETRY_SHADER:        return 3;
                case GL_FRAGMENT_SHADER:        return 4;
                case GL_COMPUTE_SHADER:         return 5;
                default:                        return -1;
            }
        };
        for (GLuint shaderId : programObject->attachedShaders) {
            GLShaderObject* sh = impl_->objects->shaders().get(shaderId);
            if (sh == nullptr) continue;
            const int si = stageIndex(sh->stage);
            if (si < 0) continue;
            scanSubroutineDeclarations(
                sh->source,
                programObject->resourceSubroutines[si],
                programObject->resourceSubroutineUniforms[si]);
        }
    }

    // Run SPIRV-Cross on each attached stage's cached SPIR-V (compiled by
    // GLContext::compileShader and stashed on the shader object). This is
    // best-effort: if translation fails the program still links and falls
    // back to the hardcoded solid-color draw path, but the diagnostic
    // record captures the SPIRV-Cross error so BAR sees what happened.
    programObject->hasTranslatedPipeline = false;
    programObject->vertexMSL.clear();
    programObject->fragmentMSL.clear();
    programObject->tessControlMSL.clear();
    programObject->tessEvalMSL.clear();
    programObject->tessVertexAsComputeMSL.clear();
    programObject->tessEvalAsComputeMSL.clear();
    programObject->computeMSL.clear();
    programObject->computeReflection = ShaderReflection{};
    // Zero default so glGetProgramiv(GL_COMPUTE_WORK_GROUP_SIZE) returns
    // (0,0,0) for non-compute programs (matches native drivers).
    // Overwritten by the Compute kind branch below with the shader's
    // local_size_{x,y,z} execution mode.
    programObject->computeLocalSizeX = 0;
    programObject->computeLocalSizeY = 0;
    programObject->computeLocalSizeZ = 0;
    programObject->metalPipelineState = nullptr;
    // Release the retained MTLComputePipelineState on relink.
    releaseRetainedMetalObject(programObject->metalComputePipelineState);
    programObject->metalComputePipelineState = nullptr;
    // Step 7-3 compute follow-up: release the retained MTLFunction.
    releaseRetainedMetalObject(programObject->metalComputeFunction);
    programObject->metalComputeFunction = nullptr;
    // Metal tess Phase 1: release the retained TCS-as-compute PSO built
    // by probeTessellationPipeline on the previous link.
    releaseRetainedMetalObject(programObject->metalTessControlPipelineState);
    programObject->metalTessControlPipelineState = nullptr;
    // Metal tess Phase 3: release the retained VS-as-compute PSO built
    // by probeTessellationPipeline (when the VS has outputs).
    releaseRetainedMetalObject(programObject->metalTessVertexPipelineState);
    programObject->metalTessVertexPipelineState = nullptr;
    // T4I [metal-tess-TF]: release per-VAO cached VS-compute PSOs.
    for (auto& entry : programObject->metalTessVertexPSOCache) {
        releaseRetainedMetalObject(entry.second);
    }
    programObject->metalTessVertexPSOCache.clear();
    programObject->metalTessVertexNeedsDescriptor = false;
    // Phase 3B [metal-tess-TF] groundwork: release the retained TES-as-
    // compute PSO (populated once the SPIRV-Cross fork patch lands).
    releaseRetainedMetalObject(programObject->metalTessEvalComputePipelineState);
    programObject->metalTessEvalComputePipelineState = nullptr;
    // Sprint 15 Q3-Option-B Phase 1 [metal-tf-vs]: release the
    // retained VS-as-compute PSO + clear the MSL/reflection/cache so a
    // relink under different env settings re-evaluates the gate
    // cleanly. Mirrors the metal-tess-TF VS-compute reset above.
    programObject->vsTfAsComputeMSL.clear();
    programObject->vsTfAsComputeReflection = ShaderReflection{};
    releaseRetainedMetalObject(programObject->metalVsTfComputePipelineState);
    programObject->metalVsTfComputePipelineState = nullptr;
    for (auto& entry : programObject->metalVsTfComputePSOCache) {
        releaseRetainedMetalObject(entry.second);
    }
    programObject->metalVsTfComputePSOCache.clear();
    programObject->metalVsTfNeedsDescriptor = false;
    programObject->metalVsTfTier = GLProgramObject::MetalVsTfTier::None;
    // Sprint 15 Q3-Option-B Phase 2 [metal-tf-vs]: clear the reflected
    // output struct layout + pre-resolved TF varying sources so the
    // relink-time gate produces a fresh layout (TF varying names may
    // have changed via glTransformFeedbackVaryings between links).
    programObject->vsTfOutputLayout = appgl::StageOutputLayout{};
    programObject->vsTfResolvedSources.clear();
    // Step 7-4: release cached graphics-stage MTLFunctions on relink.
    releaseRetainedMetalObject(programObject->metalVertexFunction);
    programObject->metalVertexFunction = nullptr;
    releaseRetainedMetalObject(programObject->metalFragmentFunction);
    programObject->metalFragmentFunction = nullptr;
    // Phase 8X Group 4d follow-up¹⁴ — release every cached pipeline
    // on relink so the map doesn't hold stale id<MTLRenderPipelineState>
    // pointers derived from the old MSL. The scalar `metalPipelineState`
    // slot above is cleared by assignment (not CFRelease'd) to match
    // the pre-follow-up¹⁴ leak-on-relink behavior; the map needs
    // explicit CFRelease because we retained each entry on insert.
    for (auto& entry : programObject->metalPipelineStateCache) {
        if (entry.second != nullptr) {
            CFRelease(entry.second);
        }
    }
    programObject->metalPipelineStateCache.clear();
    programObject->metalPipelineColorFormat = 0;
    // CPU GS emulation (docs/geometry-shader-emulation.md) — release
    // the parallel pipeline-state cache so relink rebuilds the
    // synthesised pass-through VS from the new GS SPIR-V instead of
    // serving stale pipelines. geometryEmulated / gsInputTopology /
    // etc. are recomputed by detectGeometryEmulatable a few lines
    // later when the VGF branch runs.
    for (auto& entry : programObject->gsPassThroughPipelineStateCache) {
        if (entry.second != nullptr) {
            CFRelease(entry.second);
        }
    }
    programObject->gsPassThroughPipelineStateCache.clear();
    programObject->gsPassThroughPipelineState = nullptr;
    programObject->gsPassThroughPipelineColorFormat = 0;
    programObject->gsPassThroughVertexMSL.clear();
    programObject->gsPassThroughReflection = ShaderReflection{};
    programObject->geometryEmulated = false;
    programObject->geometrySpirv.clear();
    programObject->vertexSpirv.clear();
    programObject->gsPresent = false;
    programObject->gsInputTopology = 0;
    programObject->gsOutputTopology = 0;
    programObject->gsMaxVertices = 0;
    programObject->gsInvocations = 1;
    // Sprint 17 Day 7+ Bank-Group-H Path B Component A1 — reset
    // `needsCullDistancePrepass` at relink. Recomputed below post
    // VS-stage SPIR-V availability + GS/tess-presence detection.
    programObject->needsCullDistancePrepass = false;

    ShaderTranslator translator;
    BindingMap bindings;

    auto spirvUsesStorageBuffers = [](const std::uint32_t* spirvData,
                                      std::size_t spirvWords) -> bool {
        if (spirvData == nullptr || spirvWords == 0) return false;
        try {
            spirv_cross::Compiler compiler(spirvData, spirvWords);
            return !compiler.get_shader_resources().storage_buffers.empty();
        } catch (...) {
            return false;
        }
    };

    // Translate one stage: spirvToMSL + reflect. Writes the result into the
    // provided output slots on success, records a diagnostic in both the
    // success and failure cases. Returns true iff MSL was produced.
    //
    // Phase 8X Group 4d follow-up⁵ — refactored to take SPIR-V data
    // directly (rather than reading `stage->spirv` from the shader object)
    // so the VS/FS path can pass the cross-stage-linked SPIR-V from
    // `compileGLSLProgram` instead of the per-stage cached blobs that
    // `compileShader` produced via independent `compileGLSL` invocations.
    // The other stages (compute, geometry, tess) still use the cached
    // per-stage SPIR-V — only VS+FS need cross-stage location coordination
    // for the Metal pipeline-state validator.
    auto translateStage = [&](const char* stageName,
                              const std::uint32_t* spirvData,
                              std::size_t spirvWords,
                              const std::string& sourceText,
                              std::string& mslOut,
                              ShaderReflection& reflectionOut,
                              const appgl::TranslatorOptions& optionsIn = {}) -> bool {
        if (spirvData == nullptr || spirvWords == 0) {
            return false;
        }
        const std::string stageTag = programTag + "-" + stageName;
        const std::string hash = quickHash(sourceText);

        // Sprint 17 Day 3+ BONUS-1 [clip_control]: snapshot the
        // current `glClipControl` depth mode into the per-link
        // translator options so SPIRV-Cross's `vertex.fixup_clipspace`
        // tracks GL state at link time. Caller-provided overrides
        // (e.g. tess opts, mesh-GS opts) preserved by copy-then-amend.
        appgl::TranslatorOptions options = optionsIn;
        options.clipDepthMode = impl_->state->clipDepthMode();

        // Phase 8X Group 4d follow-up²³ — sub-step marker + C++ exception
        // guard around spirvToMSL. SPIRV-Cross can throw `spirv_cross_error`
        // on ill-formed SPIR-V or unsupported decoration patterns; if that
        // escapes into this Objective-C++ frame unhandled, std::terminate
        // fires and the process SIGABRTs. Catch here so a throw becomes a
        // clean translation failure (MSL empty + diagnostic record) instead
        // of the fw²² Sky-program-28 crash signature.
        APPGL_LOG(SHADER, @"[GL] linkProgram-step=spirv-to-msl program=%u stage=%s", program, stageName);
        fflush(stderr);
        std::string mslLog;
        std::string msl;
        try {
            msl = translator.spirvToMSL(
                spirvData, spirvWords, bindings, &mslLog, options);
        } catch (const std::exception& e) {
            APPGL_LOG(SHADER, @"[GL] linkProgram-step=spirv-to-msl program=%u stage=%s THREW: %s",
                  program, stageName, e.what());
            fflush(stderr);
            Runtime::shared().recordShaderTranslation({
                stageTag, stageName, hash, linkVertexHash, linkFragmentHash,
                std::string("spirvToMSL threw std::exception: ") + e.what(),
                "", false
            });
            return false;
        } catch (...) {
            APPGL_LOG(SHADER, @"[GL] linkProgram-step=spirv-to-msl program=%u stage=%s THREW unknown exception",
                  program, stageName);
            fflush(stderr);
            Runtime::shared().recordShaderTranslation({
                stageTag, stageName, hash, linkVertexHash, linkFragmentHash,
                "spirvToMSL threw unknown exception", "", false
            });
            return false;
        }
        if (msl.empty()) {
            Runtime::shared().recordShaderTranslation({
                stageTag, stageName, hash, linkVertexHash, linkFragmentHash,
                mslLog.empty() ? "spirvToMSL returned empty MSL" : mslLog,
                "", false
            });
            return false;
        }

        // Phase 8X Group 4d follow-up²³ — sub-step marker + exception guard
        // around reflect. SPIRV-Cross reflection re-walks the SPIR-V and is
        // the other plausible throw site in the translator's critical path.
        APPGL_LOG(SHADER, @"[GL] linkProgram-step=reflect program=%u stage=%s", program, stageName);
        fflush(stderr);
        try {
            reflectionOut = translator.reflect(
                spirvData, spirvWords, bindings, nullptr, options);
        } catch (const std::exception& e) {
            APPGL_LOG(SHADER, @"[GL] linkProgram-step=reflect program=%u stage=%s THREW: %s",
                  program, stageName, e.what());
            fflush(stderr);
            Runtime::shared().recordShaderTranslation({
                stageTag, stageName, hash, linkVertexHash, linkFragmentHash,
                std::string("reflect threw std::exception: ") + e.what(),
                "", false
            });
            return false;
        } catch (...) {
            APPGL_LOG(SHADER, @"[GL] linkProgram-step=reflect program=%u stage=%s THREW unknown exception",
                  program, stageName);
            fflush(stderr);
            Runtime::shared().recordShaderTranslation({
                stageTag, stageName, hash, linkVertexHash, linkFragmentHash,
                "reflect threw unknown exception", "", false
            });
            return false;
        }
        mslOut = std::move(msl);
        // Phase 8X Group 4d follow-up⁵ — §6b: when the stage *succeeds*
        // we keep the 200-byte preview because the full MSL is large and
        // the translator records are only useful to humans on failure.
        // The matching failure-case mslPreview enlargement happens in the
        // pipeline-build branch (MetalFrameGraph.mm), where the rejected
        // MSL is what BAR actually wants to see — by which point the
        // pipeline-state NSError has already named the failing stage.
        Runtime::shared().recordShaderTranslation({
            stageTag, stageName, hash, linkVertexHash, linkFragmentHash,
            "ok", mslOut.substr(0, 200), true
        });
        return true;
    };

    // Helper: invoke translateStage against a per-stage cached SPIR-V blob
    // on a GLShaderObject. Used by every case below other than VS+FS, where
    // the VS+FS cross-stage-linked path takes over.
    auto translateCachedStage = [&](const char* stageName,
                                    GLShaderObject* stage,
                                    std::string& mslOut,
                                    ShaderReflection& reflectionOut,
                                    const appgl::TranslatorOptions& options = {}) -> bool {
        if (stage == nullptr) {
            return false;
        }
        return translateStage(stageName,
                              stage->spirv.data(), stage->spirv.size(),
                              stage->source, mslOut, reflectionOut, options);
    };

    // Phase 8X Group 4d follow-up⁵ — VS+FS cross-stage-linked SPIR-V path.
    // Produces both stage SPIR-V blobs from a single glslang::TProgram
    // link + mapIO pass so cross-stage varying locations get coordinated.
    // Returns the linked SPIR-V on success, or empty blobs on failure (in
    // which case the caller falls back to the per-stage cached SPIR-V on
    // the GLShaderObject — same path as pre-followup⁵).
    //
    // The source we pass in is the rewritten compat form, matching exactly
    // what `compileShader` already compiled per-stage: `compileShader`
    // runs `rewriteCompatShader` on `object->source` and feeds the result
    // to `compileGLSL`, but doesn't cache the rewritten string anywhere
    // — so we re-run the rewriter here. `rewriteCompatShader` is a cheap
    // string scan and is idempotent, so re-running it at link time is
    // free.
    auto compileLinkedVsFs = [&](GLShaderObject* vsStage,
                                  GLShaderObject* fsStage) -> LinkedProgramSpirv {
        if (vsStage == nullptr || fsStage == nullptr) {
            return {};
        }
        CompatShaderRewriteResult vsRewrite =
            rewriteCompatShader(vsStage->source, GL_VERTEX_SHADER);
        CompatShaderRewriteResult fsRewrite =
            rewriteCompatShader(fsStage->source, GL_FRAGMENT_SHADER);
        const std::string& vsLinkSource =
            vsRewrite.didRewrite ? vsRewrite.source : vsStage->source;
        const std::string& fsLinkSource =
            fsRewrite.didRewrite ? fsRewrite.source : fsStage->source;
        std::string vs420packLinkSource =
            rewrite420packImplicitConversionsForSpirv(vsLinkSource);
        std::string fs420packLinkSource =
            rewrite420packImplicitConversionsForSpirv(fsLinkSource);
        // Phase 8X Group 4d follow-up²³ — sub-step marker before the
        // glslang cross-stage link. First candidate on the abort-site ladder
        // is glslang's TProgram::link re-entry, since that's the first heavy
        // operation inside this lambda.
        APPGL_LOG(SHADER, @"[GL] linkProgram-step=compile-glsl-program program=%u", program);
        fflush(stderr);
        std::string linkErrorLog;
        LinkedProgramSpirv linked = translator.compileGLSLProgram(
            vs420packLinkSource, fs420packLinkSource, 330, &linkErrorLog);
        APPGL_LOG(SHADER, @"[GL] compileGLSLProgram: program=%u success=%d log=%s",
              program, linked.linkSucceeded ? 1 : 0,
              linkErrorLog.c_str());
        fflush(stderr);
        if (!linked.linkSucceeded) {
            // Record the cross-stage link failure so BAR can see why the
            // VS+FS path is degrading back to per-stage SPIR-V. The fall
            // back is intentional: the per-stage cached SPIR-V may still
            // produce usable MSL (and at worst surfaces the same Metal
            // varying-mismatch the pre-followup⁵ build was already
            // showing), so degrading is strictly no-worse than the prior
            // behaviour.
            //
            // No positive `link-spirv` record on success — the per-stage
            // vertex/fragment records that follow this lambda already
            // carry success=true, and the post-link
            // `[GL] linkProgram: ... translationOk=1` NSLog line covers
            // the "did the linked path run" question. Adding a success
            // record here would also break the
            // `phase-a.shader-program-lifecycle` scene's exact-count
            // assertion (it expects per-link pushes == 2, vertex +
            // fragment).
            Runtime::shared().recordShaderTranslation({
                programTag + "-link-spirv", "link",
                linkVertexHash, linkVertexHash, linkFragmentHash,
                linkErrorLog.empty()
                    ? "compileGLSLProgram failed (no log)"
                    : linkErrorLog,
                "", false
            });
        }
        return linked;
    };

    bool rasterTranslationOk = false;
    switch (kind) {
        case ProgramKind::VertexFragment: {
            // Run the cross-stage link first. On success, both stages
            // share the linked TProgram's coordinated SPIR-V; on failure,
            // each stage falls back to its per-stage cached SPIR-V —
            // EXCEPT for explicit GL-spec link-validation errors that
            // glslang's TProgram::link() detects and the per-stage path
            // can't recover from (cross-stage binding/location mismatch,
            // type mismatch on shared uniforms, etc.). For those, fail
            // glLinkProgram outright per GL 4.6 §7.3.
            LinkedProgramSpirv linked = compileLinkedVsFs(vertexShader, fragmentShader);
            // Sprint 8 B Cluster F F1 Day 7 (CKPT79): cross-stage link-
            // validation gating. When glslang's link() rejects with a
            // GL-spec qualifier mismatch, propagate as a real
            // glLinkProgram failure. The string-match below targets the
            // canonical glslang error message strings emitted by
            // mergeErrorCheck (linkValidate.cpp ~line 1497) so we don't
            // accidentally fail on recoverable mapIO inconsistencies.
            //
            // Required by KHR-GL46.layout_binding.*.binding_link_errors
            // sub-section: VS+FS declare same sampler name with
            // conflicting `layout(binding=N)` values; spec mandates
            // link failure.
            if (!linked.linkSucceeded && !linked.linkLog.empty()) {
                const auto& lg = linked.linkLog;
                const bool hasSpecMismatch =
                    lg.find("Layout binding qualifier must match") != std::string::npos ||
                    lg.find("Layout location qualifier must match") != std::string::npos ||
                    lg.find("Layout offset qualifier must match")   != std::string::npos ||
                    lg.find("Layout component qualifier must match") != std::string::npos ||
                    lg.find("Layout index qualifier must match")    != std::string::npos;
                if (hasSpecMismatch) {
                    APPGL_LOG(SHADER, @"[GL] linkProgram-fail program=%u reason=cross-stage-spec-mismatch log=%s",
                          program, lg.c_str());
                    programObject->linkLog = lg;
                    programObject->linked = false;
                    Runtime::shared().recordShaderTranslation({
                        programTag, "link", "", "", "", lg, "", false
                    });
                    return false;
                }
            }
            const std::uint32_t* vsSpirvData;
            std::size_t vsSpirvWords;
            const std::uint32_t* fsSpirvData;
            std::size_t fsSpirvWords;
            if (linked.linkSucceeded) {
                vsSpirvData = linked.vertexSpirv.data();
                vsSpirvWords = linked.vertexSpirv.size();
                fsSpirvData = linked.fragmentSpirv.data();
                fsSpirvWords = linked.fragmentSpirv.size();
            } else {
                vsSpirvData = vertexShader->spirv.data();
                vsSpirvWords = vertexShader->spirv.size();
                fsSpirvData = fragmentShader->spirv.data();
                fsSpirvWords = fragmentShader->spirv.size();
            }
            // Sprint 17 Day 7+ Bank-Group-H Path B Component A2: detect
            // VS cull-distance writes before VS translation so the
            // `disableCullDistanceClipRouting` option suppresses the
            // ShaderTranslator gl_CullDistance → [[clip_distance]] HW
            // routing for this program. CPU pre-pass at draw time
            // performs §14.6.3 culling instead. Phase 2 §1.1 confirmed
            // Option β (keep routing) refutation.
            const bool vsCullPrepass =
                appgl::vsSpirvWritesCullDistance(vsSpirvData, vsSpirvWords);
            // Sprint 18 Item42: graphics SSBOs use Metal argument buffers
            // to avoid direct buffer-index overflow when slot expansion
            // reaches past Metal's 0..30 range. Apply per-program so VS
            // and FS share one resource-binding mode.
            const bool forceRasterArgBuf =
                spirvUsesStorageBuffers(vsSpirvData, vsSpirvWords) ||
                spirvUsesStorageBuffers(fsSpirvData, fsSpirvWords);
            appgl::TranslatorOptions vsOptions;
            vsOptions.disableCullDistanceClipRouting = vsCullPrepass;
            vsOptions.forceArgumentBuffers = forceRasterArgBuf;
            appgl::TranslatorOptions fsOptions;
            fsOptions.forceArgumentBuffers = forceRasterArgBuf;

            ShaderReflection vsRefl, fsRefl;
            const bool vsOk = translateStage(
                "vertex", vsSpirvData, vsSpirvWords, vertexShader->source,
                programObject->vertexMSL, vsRefl, vsOptions);
            const bool fsOk = translateStage(
                "fragment", fsSpirvData, fsSpirvWords, fragmentShader->source,
                programObject->fragmentMSL, fsRefl, fsOptions);
            if (vsOk && fsOk) {
                programObject->vertexReflection = std::move(vsRefl);
                programObject->fragmentReflection = std::move(fsRefl);
                programObject->hasTranslatedPipeline = true;
                rasterTranslationOk = true;
            }
            // Sprint 7 #9 (CKPT65): preserve VS SPIR-V on the
            // VertexFragment program kind so the VS-only TF emulation
            // helper (drawArrays / drawElements) can run the VS on CPU
            // for transform-feedback capture. Without this, programs
            // with TF varyings + no GS/tess + non-separable VS+FS land
            // with `vertexSpirv.empty()` and the helper bails — TF
            // buffer stays at zero-init, breaking
            // `transform_feedback.{capture,query,discard}_vertex_*`.
            if (vertexShader != nullptr && !vertexShader->spirv.empty()) {
                programObject->vertexSpirv = vertexShader->spirv;
            }
            // Sprint 17 Day 7+ Bank-Group-H Path B Component A1: commit
            // the VS cull-distance flag detected above (pre-translation)
            // onto the program object. VertexFragment kind guarantees
            // !gsPresent && !hasTessellation here; if a later relink
            // attaches GS or tess, line 21430's reset clears this flag.
            programObject->needsCullDistancePrepass = vsCullPrepass;
            // Sprint 15 Q3-Option-B Phase 1 [metal-tf-vs]: VS-as-compute
            // MSL emit + PSO build for VS+FS+TF programs (no GS, no
            // tess). Sister-pattern reuse of the existing metal-tess-TF
            // VS-compute groundwork — `forceVertexForTessellation`
            // emits the VS as a Metal compute kernel that captures
            // per-vertex outputs into a buffer (Phase 2 will plumb the
            // TF buffer binding; Phase 3 will swap draw-time routing).
            //
            // Phase 1 lays groundwork only — no draw-time behaviour
            // change. CPU `emulateVsOnlyDrawForTf` remains the
            // authoritative TF capture path until Phase 3 routes
            // around it. Master gate: APPGL_ENABLE_METAL_TF_VS=1
            // (off by default, mirroring APPGL_ENABLE_METAL_TESS_TF's
            // conservative posture). Read once at link time so a
            // relink under different env settings re-evaluates cleanly.
            //
            // Pre-conditions:
            //   • VS+FS translation succeeded (vsOk && fsOk)
            //   • TF varyings declared via glTransformFeedbackVaryings
            //   • VS SPIR-V preserved (just stashed above)
            //   • impl_->frameGraph present (Metal device available)
            //
            // Outcomes:
            //   • tier=VsAsCompute + retained PSO: Phase 3 eligible
            //     directly (gl_VertexID-only VS, no [[stage_in]])
            //   • tier=VsAsCompute + metalVsTfNeedsDescriptor=true:
            //     Phase 3 builds per-VAO PSO at draw time via
            //     metalVsTfComputePSOCache
            //   • tier=None: gate skipped OR translation/build failed
            //     for non-descriptor reasons → CPU fallback preserved
            if (vsOk && fsOk &&
                !programObject->transformFeedbackVaryingNames.empty() &&
                !programObject->vertexSpirv.empty() &&
                impl_->frameGraph != nullptr &&
                std::getenv("APPGL_ENABLE_METAL_TF_VS") != nullptr) {
                appgl::TranslatorOptions vsTfOpts;
                vsTfOpts.forceVertexForTessellation = true;
                ShaderReflection vsTfRefl;
                std::string vsTfMSL;
                const bool vsTfTrOk = translateStage(
                    "vertex-tf-compute", vsSpirvData, vsSpirvWords,
                    vertexShader->source, vsTfMSL, vsTfRefl, vsTfOpts);
                if (vsTfTrOk && !vsTfMSL.empty()) {
                    programObject->vsTfAsComputeMSL = std::move(vsTfMSL);
                    programObject->vsTfAsComputeReflection =
                        std::move(vsTfRefl);
                    std::string vsTfPsoErr;
                    void* vsTfPSO =
                        impl_->frameGraph->buildComputePipelineState(
                            programObject->vsTfAsComputeMSL, &vsTfPsoErr,
                            nullptr, nullptr);
                    if (vsTfPSO != nullptr) {
                        programObject->metalVsTfComputePipelineState =
                            vsTfPSO;
                        programObject->metalVsTfTier =
                            GLProgramObject::MetalVsTfTier::VsAsCompute;
                    } else if (vsTfPsoErr.find("stage_in") !=
                               std::string::npos) {
                        // VS declares [[stage_in]] — defer PSO build to
                        // draw time when the bound VAO's
                        // MTLStageInputOutputDescriptor is known. Phase
                        // 3's draw-time path will lookup-or-build a
                        // per-VAO PSO via metalVsTfComputePSOCache.
                        programObject->metalVsTfNeedsDescriptor = true;
                        programObject->metalVsTfTier =
                            GLProgramObject::MetalVsTfTier::VsAsCompute;
                    } else {
                        // Compile failed for non-descriptor reasons —
                        // surface via diagnostic + leave tier=None so
                        // draw-time stays on the CPU helper.
                        Runtime::shared().recordShaderTranslation({
                            programTag + "-vs-tf-compute-pipeline",
                            "vertex",
                            quickHash(vertexShader->source),
                            linkVertexHash, linkFragmentHash,
                            std::string("metal-tf-vs PSO build failed: ")
                                + vsTfPsoErr,
                            "", false
                        });
                        programObject->vsTfAsComputeMSL.clear();
                        programObject->vsTfAsComputeReflection =
                            ShaderReflection{};
                    }
                    // Sprint 15 Q3-Option-B Phase 2 [metal-tf-vs]:
                    // reflect the VS-as-compute output struct layout +
                    // pre-resolve each declared TF varying name to a
                    // (struct-offset, GL-packed-bytes) pair. Done once
                    // at link time so Phase 3's draw-time TF writer
                    // doesn't repeat the name lookup per dispatch.
                    // Reflection runs whenever tier=VsAsCompute (both
                    // direct-PSO and deferred-descriptor branches);
                    // the layout is independent of stage_in attributes
                    // (those affect input descriptor, not output struct).
                    if (programObject->metalVsTfTier ==
                            GLProgramObject::MetalVsTfTier::VsAsCompute) {
                        programObject->vsTfOutputLayout =
                            translator.reflectStageOutputLayout(
                                vsSpirvData, vsSpirvWords, vsTfOpts);
                        const auto& layout =
                            programObject->vsTfOutputLayout;
                        const auto& tfNames =
                            programObject->transformFeedbackVaryingNames;
                        programObject->vsTfResolvedSources.clear();
                        programObject->vsTfResolvedSources.resize(
                            tfNames.size());
                        std::size_t resolvedCount = 0;
                        for (std::size_t i = 0; i < tfNames.size(); ++i) {
                            const std::string& name = tfNames[i];
                            for (const auto& m : layout.members) {
                                if (m.name == name ||
                                    (name == "gl_Position" &&
                                     m.isBuiltIn &&
                                     m.builtIn ==
                                         spv::BuiltInPosition)) {
                                    programObject
                                        ->vsTfResolvedSources[i] = {
                                        m.offset,
                                        m.glPackedBytes > 0
                                            ? m.glPackedBytes
                                            : m.size};
                                    ++resolvedCount;
                                    break;
                                }
                            }
                        }
                        // If any TF varying name failed to resolve, the
                        // gate stays in VsAsCompute tier but Phase 3's
                        // draw-time path will fall back to the CPU
                        // helper for safety (the name-mismatch could
                        // be a stripBuffer probe target, an extension
                        // syntax we don't reflect, or a true link
                        // error already caught by linkProgram). The
                        // diagnostic record makes the unresolved
                        // varying easy to find post-mortem.
                        if (resolvedCount < tfNames.size()) {
                            std::string unresolved;
                            for (std::size_t i = 0; i < tfNames.size();
                                 ++i) {
                                if (programObject->vsTfResolvedSources[i]
                                        .bytes == 0) {
                                    if (!unresolved.empty()) unresolved += ", ";
                                    unresolved += tfNames[i];
                                }
                            }
                            Runtime::shared().recordShaderTranslation({
                                programTag +
                                    "-vs-tf-varying-resolution",
                                "vertex",
                                quickHash(vertexShader->source),
                                linkVertexHash, linkFragmentHash,
                                std::string("metal-tf-vs unresolved "
                                            "TF varying(s): ") +
                                    unresolved,
                                "", false
                            });
                        }
                    }
                    if (std::getenv("APPGL_TRACE_TF_VS")) {
                        std::fprintf(stderr,
                            "[APPGL] tf-vs-probe program=%u "
                            "tfVaryings=%zu vsTfTier=%d "
                            "needsDescriptor=%d psoOk=%d "
                            "structSize=%zu members=%zu "
                            "resolved=%zu\n",
                            program,
                            programObject
                                ->transformFeedbackVaryingNames.size(),
                            (int)programObject->metalVsTfTier,
                            programObject->metalVsTfNeedsDescriptor
                                ? 1 : 0,
                            vsTfPSO != nullptr ? 1 : 0,
                            programObject->vsTfOutputLayout.structSize,
                            programObject->vsTfOutputLayout
                                .members.size(),
                            programObject->vsTfResolvedSources.size());
                    }
                }
            }
            break;
        }
        case ProgramKind::VertexOnly: {
            ShaderReflection vsRefl;
            appgl::TranslatorOptions vsOptions;
            if (vertexShader != nullptr) {
                vsOptions.forceArgumentBuffers = spirvUsesStorageBuffers(
                    vertexShader->spirv.data(), vertexShader->spirv.size());
            }
            const bool vsOk = translateCachedStage(
                "vertex", vertexShader, programObject->vertexMSL, vsRefl,
                vsOptions);
            if (vsOk) {
                programObject->vertexReflection = std::move(vsRefl);
                // A VS-only program is drawable when paired with
                // GL_RASTERIZER_DISCARD (no fragment stage required).
                // The CTS SSBO `*-vs` tests bind ONLY a vertex shader,
                // enable rasterizer discard, and read back SSBO writes
                // produced by the VS alone. Set hasTranslatedPipeline
                // = true and let encodeTranslatedDraw drop the FS when
                // info.rasterizerDiscard is true (the pipeline
                // descriptor will set fragmentFunction = nil +
                // rasterizationEnabled = NO at that point).
                programObject->hasTranslatedPipeline = true;
                rasterTranslationOk = true;
            }
            // β [metal-tess-TF]: preserve VS SPIR-V on separable VS so
            // a pipeline-bound tess draw can re-translate VS as compute
            // (`vertex_for_tessellation + capture_output_to_buffer`) at
            // pipeline-bind time. The link-time path here doesn't know
            // a TCS will eventually consume this VS, so it can't emit
            // the compute form alone; the orchestrator does it later.
            if (vertexShader != nullptr && !vertexShader->spirv.empty()) {
                programObject->vertexSpirv = vertexShader->spirv;
            }
            break;
        }
        case ProgramKind::FragmentOnly: {
            ShaderReflection fsRefl;
            appgl::TranslatorOptions fsOptions;
            if (fragmentShader != nullptr) {
                fsOptions.forceArgumentBuffers = spirvUsesStorageBuffers(
                    fragmentShader->spirv.data(), fragmentShader->spirv.size());
            }
            const bool fsOk = translateCachedStage(
                "fragment", fragmentShader, programObject->fragmentMSL, fsRefl,
                fsOptions);
            if (fsOk) {
                programObject->fragmentReflection = std::move(fsRefl);
                rasterTranslationOk = true;
            }
            break;
        }
        case ProgramKind::Compute: {
            // Translate compute to MSL + stash on the program object so
            // glDispatchCompute can encode against the cached pipeline.
            //
            // Compute uses a distinct BindingMap: SSBOs at slots [0..16),
            // UBOs at [16..31). This differs from the graphics pipeline
            // map (where slots [0..16) are reserved for VBOs) and lets
            // GL_MAX_COMPUTE_SHADER_STORAGE_BLOCKS honestly hit the spec
            // floor of 8 (actually 16). Scoped swap of `bindings` is safe
            // because translateStage captures by reference and compute
            // doesn't share the binding map with any other stage.
            const BindingMap savedBindings = bindings;
            bindings = makeComputeBindingMap();
            ShaderReflection csRefl;
            const bool csOk = translateCachedStage(
                "compute", computeShader, programObject->computeMSL, csRefl);
            bindings = savedBindings;
            if (csOk) {
                programObject->computeReflection = std::move(csRefl);
                // Extract local_size_{x,y,z} so dispatch knows the
                // threads-per-threadgroup dimensions.
                if (computeShader && !computeShader->spirv.empty()) {
                    auto modes = extractComputeModes(
                        computeShader->spirv.data(),
                        computeShader->spirv.size());
                    programObject->computeLocalSizeX = modes.localSizeX;
                    programObject->computeLocalSizeY = modes.localSizeY;
                    programObject->computeLocalSizeZ = modes.localSizeZ;
                }
                // Build + retain the MTLComputePipelineState. Failures
                // are logged but don't fail linkProgram — the dispatch
                // path will then fall back to the stub (returning true
                // with no GPU work).
                if (impl_->frameGraph != nullptr) {
                    std::string psoError;
                    // Step 7-3 compute follow-up: always request the
                    // MTLFunction too when argbuf is enabled. Released
                    // at relink alongside the PSO. The small retain
                    // cost is only paid under the env gate.
                    void* computeFn = nullptr;
                    const bool useArgBuf =
                        (std::getenv("APPGL_ENABLE_ARGUMENT_BUFFERS") != nullptr);
                    void* pso = impl_->frameGraph->buildComputePipelineState(
                        programObject->computeMSL, &psoError,
                        useArgBuf ? &computeFn : nullptr);
                    if (pso != nullptr) {
                        programObject->metalComputePipelineState = pso;
                        programObject->metalComputeFunction = computeFn;
                        APPGL_LOG(SHADER, @"[GL] linkProgram: compute pipeline built for program=%u "
                              @"localSize=[%u,%u,%u]",
                              program,
                              programObject->computeLocalSizeX,
                              programObject->computeLocalSizeY,
                              programObject->computeLocalSizeZ);
                    } else {
                        Runtime::shared().recordShaderTranslation({
                            programTag + "-compute-pipeline", "compute",
                            quickHash(computeShader ? computeShader->source : std::string()),
                            linkVertexHash, linkFragmentHash,
                            std::string("MTLComputePipelineState build failed: ") + psoError,
                            "", false
                        });
                    }
                }
            }
            break;
        }
        case ProgramKind::VertexGeometryFragment: {
            // Translate VS + FS (they're still usable even without the GS)
            // and attempt GS translation so SPIRV-Cross's reflection at
            // least reports what the geometry stage wants. Then record a
            // diagnostic flagging the emulation gap — Metal has no native
            // geometry-shader concept and our compute-stage emulation
            // lands in a follow-up cycle. BAR can read this record and
            // fall back to its non-geometry path.
            //
            // Phase 8X Group 4d follow-up⁵ — VS+FS still go through the
            // cross-stage-linked path even when a GS is present, because
            // the VS→FS varying interface is what Metal's pipeline-state
            // validator inspects. The GS emulation gap is unaffected.
            LinkedProgramSpirv linked = compileLinkedVsFs(vertexShader, fragmentShader);
            const std::uint32_t* vsSpirvData;
            std::size_t vsSpirvWords;
            const std::uint32_t* fsSpirvData;
            std::size_t fsSpirvWords;
            if (linked.linkSucceeded) {
                vsSpirvData = linked.vertexSpirv.data();
                vsSpirvWords = linked.vertexSpirv.size();
                fsSpirvData = linked.fragmentSpirv.data();
                fsSpirvWords = linked.fragmentSpirv.size();
            } else {
                vsSpirvData = vertexShader->spirv.data();
                vsSpirvWords = vertexShader->spirv.size();
                fsSpirvData = fragmentShader->spirv.data();
                fsSpirvWords = fragmentShader->spirv.size();
            }
            // Sprint 17 Day 9+ R13 sub-bank item_5 lines/triangles:
            // extend Path B (`needsCullDistancePrepass`) to GS-present
            // programs. When the VS writes gl_Clip/CullDistance and the
            // GS path doesn't emulate (the `programStoresClipOrCull`
            // stopgap at `GeometryShaderEmulator.cpp:4544` rejects to
            // avoid pixel-coverage gaps in GS-emul cull routing), the
            // legacy translated VS+FS pipeline runs with cull→clip
            // routing siblings driving HW clip — exactly the
            // mixed-sign over-clip case Path B was created to handle.
            // CPU pre-pass on the VS gives spec-correct §14.6.3
            // primitive-level culling for passthrough GS (VS values
            // flow through GS unchanged); non-passthrough GS that
            // modifies cull values is rare and falls outside this gate.
            const bool vsCullPrepassVgf =
                appgl::vsSpirvWritesCullDistance(vsSpirvData, vsSpirvWords);
            const bool forceRasterArgBufVgf =
                spirvUsesStorageBuffers(vsSpirvData, vsSpirvWords) ||
                spirvUsesStorageBuffers(fsSpirvData, fsSpirvWords);
            appgl::TranslatorOptions vsOptionsVgf;
            vsOptionsVgf.disableCullDistanceClipRouting = vsCullPrepassVgf;
            vsOptionsVgf.forceArgumentBuffers = forceRasterArgBufVgf;
            appgl::TranslatorOptions fsOptionsVgf;
            fsOptionsVgf.forceArgumentBuffers = forceRasterArgBufVgf;
            ShaderReflection vsRefl, fsRefl, gsRefl;
            const bool vsOk = translateStage(
                "vertex", vsSpirvData, vsSpirvWords, vertexShader->source,
                programObject->vertexMSL, vsRefl, vsOptionsVgf);
            const bool fsOk = translateStage(
                "fragment", fsSpirvData, fsSpirvWords, fragmentShader->source,
                programObject->fragmentMSL, fsRefl, fsOptionsVgf);
            // Sprint 17 Day 9+ R13 sub-bank item_5: commit
            // `needsCullDistancePrepass` for VertexGeometryFragment kind
            // when the VS writes gl_Clip/CullDistance. The drawArrays
            // dispatch site at line ~28344 already gates on `program->
            // needsCullDistancePrepass && program->hasTranslatedPipeline`
            // — both conditions hold here for VS+GS+FS programs whose
            // GS-emul rejects (GS-emul stopgap at GeometryShaderEmulator
            // .cpp:4544). For passthrough GS, VS-only Path B is
            // spec-correct because cull values flow through unchanged.
            programObject->needsCullDistancePrepass = vsCullPrepassVgf;
            std::string unusedGsMSL;
            (void)translateCachedStage("geometry", geometryShader, unusedGsMSL, gsRefl);
            // Keep the GS reflection so `GL_REFERENCED_BY_GEOMETRY_SHADER`
            // queries on block-scoped resources (uniform blocks, SSBOs,
            // buffer variables) can consult it for usage analysis.
            // SPIRV-Cross's reflection `active` field tells us whether
            // the block is live in the GS body.
            programObject->geometryReflection = gsRefl;
            // CPU GS emulation — step 2 hook. Copy the GS SPIR-V onto
            // the program so it survives shader detach/delete, then ask
            // the emulator whether it can handle this shader. Detection
            // only toggles the flag + topology/max_verts state; no
            // emulation runs here. drawArrays (step 3) branches on
            // programObject->geometryEmulated. See
            // docs/geometry-shader-emulation.md §4.2.
            if (geometryShader != nullptr && !geometryShader->spirv.empty()) {
                programObject->geometrySpirv = geometryShader->spirv;
                // Stash the VS SPIR-V too so the emulator's VS pre-pass
                // (runs on every draw) has a stable copy independent
                // of the shader's lifetime.
                if (vertexShader != nullptr && !vertexShader->spirv.empty()) {
                    programObject->vertexSpirv = vertexShader->spirv;
                }
                // Sprint 8 #8 β.3 (CKPT97): for 5-stage programs
                // (VS+TCS+TES+GS+FS) the kind is VertexGeometryFragment
                // — the same branch that handles 3-stage VS+GS+FS. Stash
                // the tess SPIR-V too so detectTessellationEmulatable
                // can run; without this, the tess detector never sees a
                // tess-shader SPIR-V for tess+GS programs and the
                // tess-emul path stays dormant at draw time.
                //
                // CKPT98 fix: also extract TCS execution modes
                // (OutputVertices) so per-invocation TCS run iterates
                // the right count. Without this, tess-emul ran only
                // invocation 0 and slot-1 user-block writes (e.g.
                // out_data[1].tc_position in data_pass_through) stayed
                // zero, surfacing as fail-shape "index [40] expected
                // [1,1,1,1] found [0,0,0,0]" downstream.
                if (tessControlShader != nullptr && !tessControlShader->spirv.empty()) {
                    programObject->tessControlSpirv = tessControlShader->spirv;
                    programObject->tessControlParsedModule.reset();
                    auto tcModes = appgl::extractTessellationModes(
                        tessControlShader->spirv.data(),
                        tessControlShader->spirv.size());
                    if (tcModes.outputVertices > 0) {
                        programObject->tessControlOutputVertices =
                            static_cast<GLint>(tcModes.outputVertices);
                    }
                }
                if (tessEvalShader != nullptr && !tessEvalShader->spirv.empty()) {
                    programObject->tessEvalSpirv = tessEvalShader->spirv;
                    programObject->tessEvalParsedModule.reset();
                    auto teModes = appgl::extractTessellationModes(
                        tessEvalShader->spirv.data(),
                        tessEvalShader->spirv.size());
                    if (teModes.genMode != 0) {
                        programObject->tessGenMode = teModes.genMode;
                    }
                    if (teModes.genSpacing != 0) {
                        programObject->tessGenSpacing = teModes.genSpacing;
                    }
                    if (teModes.genVertexOrder != 0) {
                        programObject->tessGenVertexOrder = teModes.genVertexOrder;
                    }
                    programObject->tessGenPointMode =
                        teModes.pointMode ? GL_TRUE : GL_FALSE;
                }
                (void)appgl::detectGeometryEmulatable(*programObject);
                if (programObject->hasTessellation) {
                    (void)appgl::detectTessellationEmulatable(*programObject);
                }
            }
            // Sprint 3 [metal-mesh-GS]: try the Metal mesh shader path
            // for GS programs whose shape fits the SPIRV-Cross
            // GS-as-mesh patch's MVP coverage. Gate is a 3-way
            // conjunction:
            //   (a) device supports mesh shaders
            //       (`MTLGPUFamilyMetal3` + `MTLGPUFamilyApple7`)
            //   (b) GS shape is mesh-MVP-supported (triangle/line/point
            //       output, no adjacency input, max_vertices ≤ 3,
            //       no streams)
            //   (c) GS SPIR-V successfully translates with
            //       `forceGeometryShaderAsMesh = true`
            // When all three hold, set metalGSTier = MeshShader and
            // stash the emitted MSL for later PSO build. Otherwise
            // fall back to the existing CPU GS interpreter
            // classification (`geometryEmulated`).
            if (geometryShader != nullptr && !geometryShader->spirv.empty() &&
                impl_->capabilities != nullptr &&
                impl_->capabilities->meshShaderSupported()) {
                // Shape gate: input topology, output topology,
                // max_vertices. detectGeometryEmulatable already
                // populated these fields on the program object.
                const bool inputOK =
                    programObject->gsInputTopology == GL_POINTS ||
                    programObject->gsInputTopology == GL_LINES ||
                    programObject->gsInputTopology == GL_TRIANGLES;
                // Adjacency variants are deferred per the SPIRV-Cross
                // patch's deferred-work list. CPU interpreter handles
                // them; selective routing keeps adjacency on CPU.
                const bool outputOK =
                    programObject->gsOutputTopology == GL_TRIANGLE_STRIP ||
                    programObject->gsOutputTopology == GL_LINE_STRIP ||
                    programObject->gsOutputTopology == GL_POINTS;
                // CKPT20 [Sprint 3 close]: gate widened from ≤3 to ≤4
                // to activate Path I (interface-block GS input
                // member population, fork 2a85276) on
                // `nonarray_input.nonarray_input` (max_vertices=4).
                // CKPT20 cluster verification: gate ≤4 preserves the
                // 121/136 default-on invariant with 0 regressions
                // (nonarray_input was already passing via legacy CPU
                // emul; now routes through mesh path with Path I
                // unblocking the interface-block input flow). The
                // layered_rendering family (max_vertices ≥ 16) +
                // `blending_support` (max=64) still fail at the
                // per-layer rasterization layer — separate gap class
                // carried forward to Sprint 4. Gate ≥5 is deferred
                // pending that cluster's diagnosis.
                const bool maxVerticesOK = programObject->gsMaxVertices <= 4u;
                const bool shapeOK = inputOK && outputOK && maxVerticesOK;
                if (shapeOK) {
                    appgl::TranslatorOptions gsMeshOpts;
                    gsMeshOpts.forceGeometryShaderAsMesh = true;
                    appgl::ShaderReflection meshGsRefl;
                    std::string meshGsMSL;
                    const bool meshOk = translateStage(
                        "geometry-as-mesh",
                        geometryShader->spirv.data(),
                        geometryShader->spirv.size(),
                        geometryShader->source,
                        meshGsMSL, meshGsRefl, gsMeshOpts);
                    if (meshOk && !meshGsMSL.empty()) {
                        programObject->geometryShaderAsMeshMSL = std::move(meshGsMSL);
                        programObject->metalGSTier =
                            GLProgramObject::MetalGSTier::MeshShader;
                    }
                }
            }
            // Sprint 3 Phase 2 [metal-mesh-GS]: link-time PSO build.
            // When tier=MeshShader, prepare the two pieces the draw-time
            // encoder needs:
            //   (1) VS-as-compute PSO — VS source re-translated with
            //       `vertex_for_tessellation + capture_output_to_buffer`
            //       so the per-vertex outputs land in a buffer the mesh
            //       function reads at [[buffer(22)]] (Path A's
            //       `spvVsOutputs`, ec354aa). Mirrors Phase-3 metal-tess
            //       VS-compute path; reuses `forceVertexForTessellation`.
            //   (2) Mesh function — the `geometryShaderAsMeshMSL`
            //       compiled to a retained `id<MTLFunction>`. The render
            //       PSO itself is FBO-format-keyed and built lazily at
            //       draw time.
            // Either (1) or (2) failing demotes tier back to None so the
            // CPU-interpreter fallback below picks the program up. Programs
            // whose VS uses [[stage_in]] would fail (1) here and fall back
            // — same handleability gate as the tess path. The 6 MVP
            // conversion targets are simple gl_VertexID-only VSes, well
            // inside this gate.
            if (programObject->metalGSTier ==
                    GLProgramObject::MetalGSTier::MeshShader &&
                impl_->frameGraph != nullptr) {
                bool meshLinkOk = true;
                // (1) VS-as-compute translation + PSO build.
                if (vertexShader != nullptr && !vertexShader->spirv.empty()) {
                    appgl::TranslatorOptions vsComputeOpts;
                    vsComputeOpts.forceVertexForTessellation = true;
                    // Path G [Checkpoint 15, fork f19ce45]: ACTUAL fix
                    // for the VS-as-compute kernel-doesn't-execute
                    // symptom. Apple's [[grid_size]] returns (0,0,0)
                    // on Apple Silicon — bounds check fires
                    // universally, all threads early-return.
                    // [[threads_per_grid]] returns the dispatched
                    // size correctly. Path E/E++/E+++ flags
                    // (barrier/volatile/atomic) preserved in the
                    // TranslatorOptions struct as historical
                    // record + optional defense-in-depth, but kept
                    // OFF here — Path G alone is sufficient.
                    vsComputeOpts.forceThreadsPerGridForStageInputSize = true;
                    appgl::ShaderReflection vsComputeRefl;
                    std::string vsComputeMSL;
                    const bool vsTrOk = translateStage(
                        "vertex-as-compute-for-mesh",
                        vertexShader->spirv.data(),
                        vertexShader->spirv.size(),
                        vertexShader->source,
                        vsComputeMSL, vsComputeRefl, vsComputeOpts);
                    if (vsTrOk && !vsComputeMSL.empty()) {
                        programObject->metalGSVsComputeMSL = vsComputeMSL;
                        std::string vsPsoErr;
                        void* vsPSO = impl_->frameGraph
                            ->buildComputePipelineState(vsComputeMSL,
                                                         &vsPsoErr,
                                                         nullptr);
                        if (vsPSO != nullptr) {
                            programObject->metalGSVsComputePipelineState = vsPSO;
                        } else {
                            meshLinkOk = false;
                        }
                    } else {
                        meshLinkOk = false;
                    }
                } else {
                    meshLinkOk = false;
                }
                // (2) Compile mesh function + FS function.
                if (meshLinkOk) {
                    std::string meshFnErr;
                    void* meshFn = impl_->frameGraph
                        ->compileMSLFunction(
                            programObject->geometryShaderAsMeshMSL,
                            &meshFnErr);
                    if (meshFn != nullptr) {
                        programObject->metalGSMeshFunction = meshFn;
                    } else {
                        meshLinkOk = false;
                    }
                }
                if (meshLinkOk && !programObject->fragmentMSL.empty()) {
                    std::string fsFnErr;
                    void* fsFn = impl_->frameGraph
                        ->compileMSLFunction(
                            programObject->fragmentMSL, &fsFnErr);
                    if (fsFn != nullptr) {
                        programObject->metalGSFragmentFunction = fsFn;
                    } else {
                        meshLinkOk = false;
                    }
                }
                // Demote on any failure so the CPU-interpreter fallback
                // picks the program up below.
                if (!meshLinkOk) {
                    programObject->metalGSTier =
                        GLProgramObject::MetalGSTier::None;
                }
            }
            if (programObject->metalGSTier == GLProgramObject::MetalGSTier::None &&
                programObject->geometryEmulated) {
                programObject->metalGSTier =
                    GLProgramObject::MetalGSTier::CPUInterpreter;
            }
            // Record the emulation outcome after the per-stage records
            // so BAR / trace logs see: [vertex:ok][fragment:ok][geometry:ok][gap-or-cpu-emulation].
            if (programObject->geometryEmulated) {
                Runtime::shared().recordShaderTranslation({
                    programTag + "-geometry-cpu-emulation", "geometry",
                    quickHash(geometryShader->source),
                    linkVertexHash, linkFragmentHash,
                    "geometry shader will run on the CPU emulator "
                    "(constant_expressions GS subset); drawArrays routes "
                    "expanded vertices through a synthesised pass-through VS",
                    "", true
                });
            } else {
                Runtime::shared().recordShaderTranslation({
                    programTag + "-geometry-emulation", "geometry",
                    quickHash(geometryShader->source),
                    linkVertexHash, linkFragmentHash,
                    "geometry shader outside the CPU-emulator's supported "
                    "SPIR-V subset (unsupported opcode or topology); program "
                    "falls back to VS+FS-only raster without GS",
                    "", false
                });
            }
            if (vsOk && fsOk) {
                programObject->vertexReflection = std::move(vsRefl);
                programObject->fragmentReflection = std::move(fsRefl);
                programObject->hasTranslatedPipeline = true;
                rasterTranslationOk = true;
            }
            break;
        }
        case ProgramKind::VertexGeometry: {
            // Sprint 15 Day 18 (CKPT191) — VS+GS no-FS combination. Mirrors
            // the VertexGeometryFragment branch's GS detection / emulation
            // setup but skips fragment translation entirely. The draw-time
            // pipeline path already handles `hasFragmentStage = false +
            // rasterizerDiscard = true` for VertexOnly tests; we reuse the
            // same nil-fragmentFunction + rasterizationEnabled=NO Metal
            // pipeline configuration. CTS targets:
            // shader_image_load_store.basic-allTargets-{loadStoreGS, atomicGS,
            // loadStoreVS, atomicVS} (the GS variants build VS+GS only with
            // image writes in the GS body; the VS variants don't reach this
            // case). Prior characterization at CKPT164 §3 estimated this as
            // multi-day infrastructure; the surgical scope ended up tractable
            // because VertexOnly already wired the no-FS pipeline path.
            ShaderReflection vsRefl, gsRefl;
            appgl::TranslatorOptions vsOptionsVg;
            if (vertexShader != nullptr) {
                vsOptionsVg.forceArgumentBuffers = spirvUsesStorageBuffers(
                    vertexShader->spirv.data(), vertexShader->spirv.size());
            }
            const bool vsOk = translateCachedStage(
                "vertex", vertexShader, programObject->vertexMSL, vsRefl,
                vsOptionsVg);
            std::string unusedGsMSL;
            (void)translateCachedStage("geometry", geometryShader, unusedGsMSL, gsRefl);
            programObject->geometryReflection = gsRefl;
            // CPU GS emulation hookup — copy GS SPIR-V onto the program
            // (survives shader detach/delete) and let the emulator decide
            // whether it can handle this shader. Mirrors VertexGeometryFragment.
            if (geometryShader != nullptr && !geometryShader->spirv.empty()) {
                programObject->geometrySpirv = geometryShader->spirv;
                if (vertexShader != nullptr && !vertexShader->spirv.empty()) {
                    programObject->vertexSpirv = vertexShader->spirv;
                }
                (void)appgl::detectGeometryEmulatable(*programObject);
            }
            // No mesh-shader path here: SILS GS targets need CPU emulation
            // for image opcodes; the mesh path doesn't gate on FS but the
            // SILS shape (image writes from GS body) lives entirely in the
            // CPU interpreter.
            if (programObject->metalGSTier == GLProgramObject::MetalGSTier::None &&
                programObject->geometryEmulated) {
                programObject->metalGSTier =
                    GLProgramObject::MetalGSTier::CPUInterpreter;
            }
            if (programObject->geometryEmulated) {
                Runtime::shared().recordShaderTranslation({
                    programTag + "-geometry-cpu-emulation-no-fs", "geometry",
                    quickHash(geometryShader->source),
                    linkVertexHash, "",
                    "VS+GS-no-FS program (CKPT191): geometry shader runs on "
                    "the CPU emulator; pipeline fragmentFunction = nil + "
                    "rasterizationEnabled = NO at draw time",
                    "", true
                });
            }
            if (vsOk) {
                programObject->vertexReflection = std::move(vsRefl);
                // Empty fragmentMSL signals the no-FS pipeline path. The
                // draw-time encoder treats this as legitimate when
                // rasterizerDiscard is set (matches VertexOnly behaviour).
                programObject->fragmentMSL.clear();
                programObject->hasTranslatedPipeline = true;
                rasterTranslationOk = true;
            }
            break;
        }
        case ProgramKind::VertexTessellationFragment: {
            // Same story as geometry: translate VS + FS and record a
            // diagnostic for the tess stages. Metal's tessellation model
            // is incompatible with GL's, so proper routing lands later.
            //
            // Phase 8X Group 4d follow-up⁵ — VS+FS use the cross-stage
            // linked path here too, for the same reason as VGF above.
            LinkedProgramSpirv linked = compileLinkedVsFs(vertexShader, fragmentShader);
            const std::uint32_t* vsSpirvData;
            std::size_t vsSpirvWords;
            const std::uint32_t* fsSpirvData;
            std::size_t fsSpirvWords;
            if (linked.linkSucceeded) {
                vsSpirvData = linked.vertexSpirv.data();
                vsSpirvWords = linked.vertexSpirv.size();
                fsSpirvData = linked.fragmentSpirv.data();
                fsSpirvWords = linked.fragmentSpirv.size();
            } else {
                vsSpirvData = vertexShader->spirv.data();
                vsSpirvWords = vertexShader->spirv.size();
                fsSpirvData = fragmentShader->spirv.data();
                fsSpirvWords = fragmentShader->spirv.size();
            }
            ShaderReflection vsRefl, fsRefl, tcRefl, teRefl;
            const bool forceRasterArgBufVtf =
                spirvUsesStorageBuffers(vsSpirvData, vsSpirvWords) ||
                spirvUsesStorageBuffers(fsSpirvData, fsSpirvWords);
            appgl::TranslatorOptions vsOptionsVtf;
            vsOptionsVtf.forceArgumentBuffers = forceRasterArgBufVtf;
            appgl::TranslatorOptions fsOptionsVtf;
            fsOptionsVtf.forceArgumentBuffers = forceRasterArgBufVtf;
            const bool vsOk = translateStage(
                "vertex", vsSpirvData, vsSpirvWords, vertexShader->source,
                programObject->vertexMSL, vsRefl, vsOptionsVtf);
            const bool fsOk = translateStage(
                "fragment", fsSpirvData, fsSpirvWords, fragmentShader->source,
                programObject->fragmentMSL, fsRefl, fsOptionsVtf);
            // Sprint 5 Phase 1: Phase 3 gate widening via passthrough TCS
            // synthesis at link time. When source program has TES + FS
            // (no TCS) — GL spec §11.2.4: TES-only programs use VS outputs
            // directly as TES inputs — synthesize a minimal passthrough
            // GLSL TCS, compile via existing toolchain, and use as if a
            // real TCS were attached. This unblocks the Phase 3 gate at
            // tryMetalTessellationDraw which requires `tessControlMSL`
            // non-empty. Affected tests: `tc2te.gl_PatchVerticesIn` iter 4
            // (TES_4 variant), `single.max_patch_vertices` Case 2,
            // `tc2te.gl_tessLevel` TES iters (3 of 6).
            //
            // Minimal TCS surface area for Sprint 5 Phase 1:
            //   - layout(vertices = 32) — covers up to MAX_PATCH_VERTICES
            //   - gl_Position passthrough
            //   - default tess levels = 1.0 (matches glPatchParameterfv
            //     default) — runtime override via uniforms TBD if test
            //     exercises non-default tess levels
            //
            // User-varying passthrough is NOT synthesized in this minimal
            // version. Tests that depend on per-CP user data (e.g.
            // max_patch_vertices Case 2's `for (i; i<gl_PatchVerticesIn;
            // i++) result_iv += inVertex[i].iv`) will still fail because
            // synthesized TCS doesn't copy user varyings from VS outputs.
            // Future iteration (post-CKPT29 follow-up) extends synthesis
            // to walk TES SPIR-V Inputs and emit matching TCS Outputs.
            std::vector<std::uint32_t> synthTcsSpirv;
            std::string synthTcsSource;
            GLShaderObject synthTcsShader;
            if (tessEvalShader != nullptr && tessControlShader == nullptr &&
                !tessEvalShader->spirv.empty()) {
                synthTcsSource =
                    "#version 410 core\n"
                    "#extension GL_EXT_tessellation_shader : enable\n"
                    "layout (vertices = 32) out;\n"
                    "void main() {\n"
                    "    gl_out[gl_InvocationID].gl_Position = "
                    "gl_in[gl_InvocationID].gl_Position;\n"
                    "    if (gl_InvocationID == 0) {\n"
                    "        gl_TessLevelOuter[0] = 1.0;\n"
                    "        gl_TessLevelOuter[1] = 1.0;\n"
                    "        gl_TessLevelOuter[2] = 1.0;\n"
                    "        gl_TessLevelOuter[3] = 1.0;\n"
                    "        gl_TessLevelInner[0] = 1.0;\n"
                    "        gl_TessLevelInner[1] = 1.0;\n"
                    "    }\n"
                    "}\n";
                std::string compileLog;
                synthTcsSpirv = translator.compileGLSL(
                    synthTcsSource, GL_TESS_CONTROL_SHADER, 410, &compileLog);
                if (!synthTcsSpirv.empty()) {
                    synthTcsShader.stage = GL_TESS_CONTROL_SHADER;
                    synthTcsShader.source = synthTcsSource;
                    synthTcsShader.spirv = synthTcsSpirv;
                    synthTcsShader.compiled = true;
                    tessControlShader = &synthTcsShader;
                    // Sprint 5 Phase 1: signal to encoder that this
                    // program's TCS was synthesized → host should
                    // populate factorBufFull from glPatchParameterfv
                    // state per draw to override synth's 1.0 defaults.
                    programObject->tessControlSynthesized = true;
                    APPGL_LOG(SHADER,
                        @"[GL] Sprint5 Phase 3 gate widening: synthesized "
                        @"passthrough TCS for TES-only program (program=%u, "
                        @"spirv_words=%zu)",
                        program, synthTcsSpirv.size());
                } else {
                    APPGL_LOG(SHADER,
                        @"[GL] Sprint5 Phase 3 gate widening: passthrough TCS "
                        @"compile failed: %s", compileLog.c_str());
                }
            }
            // Metal tess Phase 1: force SPIRV-Cross tess options on for
            // TCS/TES translation regardless of APPGL_ENABLE_METAL_TESS
            // env. The emitted MSL shape matches what the Metal tess
            // pipeline (TCS-as-compute + TES-as-vertex-function with
            // tessellationEnabled=YES) can consume. MSL is stashed on the
            // program so MetalFrameGraph can build the pipeline states.
            appgl::TranslatorOptions tessOpts;
            tessOpts.forceTessellation = true;
            // Sprint 5 Phase 1 — Path L Class 2A: full-precision tess
            // level shadow buffer. SPIRV-Cross fork emits TCS dual-write
            // (half + full) and TES read from full-precision buffer.
            // Avoids half-precision rounding error on tests like
            // `tc2te.gl_tessLevel` which expects ~exact float read-back.
            tessOpts.useFullPrecisionTessLevelBuffer = true;
            // Phase 7 [metal-tess-TF] (Track 2 scaffold): pass the linked
            // TES's SPIR-V to the TCS translation so spirvToMSL can call
            // add_msl_shader_output for each TES user-varying input. Closes
            // the per-CP buffer stride mismatch on shapes where TCS doesn't
            // write all the user varyings TES reads (cluster A / C). The
            // TES translation's spirvToMSL ignores this field — it's gated
            // on isTessControl inside the translator.
            if (tessEvalShader != nullptr && !tessEvalShader->spirv.empty()) {
                tessOpts.siblingTesInputSpirv = tessEvalShader->spirv.data();
                tessOpts.siblingTesInputWordCount = tessEvalShader->spirv.size();
            }
            // tc_barriers cluster — inverse-direction sibling so the TES
            // translation calls add_msl_shader_input for TCS outputs the
            // TES doesn't itself declare. Closes the per-CP buffer
            // stride mismatch when TCS uses its own outputs internally
            // (after barrier()) so SPIRV-Cross emits 48 B/CP for TCS
            // but 16 B/CP for TES → TES reads at the wrong offset.
            if (tessControlShader != nullptr && !tessControlShader->spirv.empty()) {
                tessOpts.siblingTcsOutputSpirv = tessControlShader->spirv.data();
                tessOpts.siblingTcsOutputWordCount = tessControlShader->spirv.size();
            }
            // T4I [metal-tess-TF]: extract TCS `layout(vertices=N)`
            // before TES translation so SPIRV-Cross can plumb the
            // patch CP count into TES MSL's `[[ patch(quad, N) ]]`
            // attribute and `gl_in = &spvIn[gl_PrimitiveID * N]`
            // stride. Without this, MSL emits `* 0` and every patch
            // reads spvIn[0..N-1] regardless of primitive id —
            // covering only the first patch's pixels.
            if (tessControlShader && !tessControlShader->spirv.empty()) {
                auto tcModes = extractTessellationModes(
                    tessControlShader->spirv.data(), tessControlShader->spirv.size());
                tessOpts.tesePatchVertices = tcModes.outputVertices;
            }
            (void)translateCachedStage("tess-control", tessControlShader,
                                       programObject->tessControlMSL, tcRefl,
                                       tessOpts);
            (void)translateCachedStage("tess-eval", tessEvalShader,
                                       programObject->tessEvalMSL, teRefl,
                                       tessOpts);
            // T4I [metal-tess-TF]: SPIRV-Cross emits the TES vertex
            // function with `[[patch(domain, execution.output_vertices)]]`,
            // but `execution.output_vertices` is 0 for TES (the
            // OutputVertices execution mode is set on TCS, not TES).
            // Metal needs the patch_control_point_count in the
            // attribute; with 0 it silently mis-fetches CP data and
            // every patch covers only the first control point's
            // pixels. Post-process the emitted MSL to substitute the
            // TCS output_vertices count.
            if (tessOpts.tesePatchVertices != 0 && !programObject->tessEvalMSL.empty()) {
                std::string& msl = programObject->tessEvalMSL;
                std::string oldNeedle1 = "[[ patch(quad, 0) ]]";
                std::string oldNeedle2 = "[[ patch(triangle, 0) ]]";
                std::string newRepl1 = "[[ patch(quad, " + std::to_string(tessOpts.tesePatchVertices) + ") ]]";
                std::string newRepl2 = "[[ patch(triangle, " + std::to_string(tessOpts.tesePatchVertices) + ") ]]";
                std::size_t p = msl.find(oldNeedle1);
                if (p != std::string::npos) {
                    msl.replace(p, oldNeedle1.size(), newRepl1);
                    if (std::getenv("APPGL_TRACE_TESS")) {
                        std::fprintf(stderr,
                            "[APPGL] T4I: TES patch_cp 0->%u (quad)\n",
                            tessOpts.tesePatchVertices);
                    }
                } else {
                    p = msl.find(oldNeedle2);
                    if (p != std::string::npos) {
                        msl.replace(p, oldNeedle2.size(), newRepl2);
                        if (std::getenv("APPGL_TRACE_TESS")) {
                            std::fprintf(stderr,
                                "[APPGL] T4I: TES patch_cp 0->%u (triangle)\n",
                                tessOpts.tesePatchVertices);
                        }
                    }
                }
            }
            programObject->tessControlReflection = tcRefl;
            // Metal tess Phase 3: compile VS as a compute kernel with
            // `vertex_for_tessellation + capture_output_to_buffer` so
            // the TCS compute dispatch can consume its outputs via
            // stage-input. Emits alongside the traditional `vertex`
            // form stored above — the Phase 3 pipeline probe + encode
            // paths read `tessVertexAsComputeMSL`, leaving
            // `vertexMSL` (the Phase-2 render path) untouched.
            appgl::TranslatorOptions vsComputeOpts;
            vsComputeOpts.forceVertexForTessellation = true;
            ShaderReflection vsComputeRefl;
            (void)translateStage(
                "vertex-for-tess", vsSpirvData, vsSpirvWords,
                vertexShader->source,
                programObject->tessVertexAsComputeMSL, vsComputeRefl,
                vsComputeOpts);
            programObject->tessVertexAsComputeReflection = vsComputeRefl;
            // SPIRV-Cross inserts a `[[grid_size]]`-based early-return
            // in VS-for-tessellation to guard against out-of-range
            // threads. On macOS Apple Silicon with `dispatchThreads`
            // the attribute reads as (0,0,0) for reasons I haven't yet
            // tracked — the whole kernel early-returns and nothing is
            // written. We dispatch exactly vertexCount threads so the
            // bounds check is redundant; strip it post-emit.
            if (!programObject->tessVertexAsComputeMSL.empty()) {
                std::string& mslRef = programObject->tessVertexAsComputeMSL;
                const std::string needle =
                    "if (any(gl_GlobalInvocationID >= spvStageInputSize))\n"
                    "        return;";
                const std::size_t pos = mslRef.find(needle);
                if (pos != std::string::npos) {
                    mslRef.replace(pos, needle.size(),
                                   "/* AppGL: grid_size early-return stripped */");
                    if (std::getenv("APPGL_TRACE_TESS")) {
                        std::fprintf(stderr,
                            "[APPGL] T4I: stripped grid_size early-return from VS-compute MSL\n");
                    }
                } else if (std::getenv("APPGL_TRACE_TESS")) {
                    std::fprintf(stderr,
                        "[APPGL] T4I: VS-compute MSL early-return needle NOT found\n");
                }
                // CKPT139 (Sprint 13 Phase 2 Day 3): γ2.1.F vs γ2.1.G
                // sentinel-encoding diagnostic. When APPGL_DIAG_TESS_SENTINEL
                // is set, override `out.gl_Position` write to encode
                // gl_GlobalInvocationID.{xyz} as float values, AND write a
                // fixed sentinel to other fields so we can identify which
                // thread populated each slot. Diagnostic-only; environment-gated.
                if (std::getenv("APPGL_DIAG_TESS_SENTINEL") != nullptr) {
                    const std::string oldPos =
                        "out.gl_Position = float4(float(int(gl_VertexIndex)));";
                    const std::string newPos =
                        "out.gl_Position = float4(float(gl_GlobalInvocationID.x), "
                        "float(gl_GlobalInvocationID.y), "
                        "float(gl_GlobalInvocationID.z), 42.0);";
                    const std::size_t posp = mslRef.find(oldPos);
                    if (posp != std::string::npos) {
                        mslRef.replace(posp, oldPos.size(), newPos);
                        std::fprintf(stderr,
                            "[APPGL] DIAG-SENTINEL: replaced gl_Position with thread-id encoding\n");
                    } else {
                        std::fprintf(stderr,
                            "[APPGL] DIAG-SENTINEL: gl_Position pattern NOT found\n");
                    }
                }
            }
            // Extract TCS output_vertices now (before TES-compute
            // translation) so we can plumb the per-patch CP count into
            // SPIRV-Cross — the TES's own SPIR-V has no
            // `output_vertices` execution mode, so without this the
            // emitted `gl_in` stride defaults to `gl_PrimitiveID * 0`
            // and every patch collapses to the TCS-output origin.
            programObject->hasTessellation = true;
            std::uint32_t tcsOutputVertices = 0;
            // Sprint 5 Phase 3 gate widening: for synthesized passthrough
            // TCS (TES-only programs), populate
            // `programObject->tessControlOutputVertices` from the synth
            // (so the Phase 3 gate passes) BUT force local
            // `tcsOutputVertices = 0` so `tesComputeOpts.tesePatchVertices
            // = 0` and Path K's runtime read of `spvIndirectParams[0]`
            // kicks in for TES-compute MSL emission. TES-only mode's
            // gl_PatchVerticesIn semantic is "PATCH_VERTICES from
            // glPatchParameteri" (runtime), not "TCS output_vertices"
            // (link-time bake from synth's `layout(vertices = 32)`).
            const bool isSynthPassthroughTcs =
                (tessControlShader == &synthTcsShader);
            if (tessControlShader && !tessControlShader->spirv.empty()) {
                auto tcModes = extractTessellationModes(
                    tessControlShader->spirv.data(), tessControlShader->spirv.size());
                programObject->tessControlOutputVertices = static_cast<GLint>(tcModes.outputVertices);
                if (!isSynthPassthroughTcs) {
                    tcsOutputVertices = tcModes.outputVertices;
                }
                // For synth case, tcsOutputVertices stays 0 → triggers
                // Path K runtime read in TES MSL.
            }

            // Phase 3B [metal-tess-TF] groundwork: also translate TES
            // with `forceTessEvalAsCompute` so the call path is wired
            // for the follow-up SPIRV-Cross patch that actually emits
            // a kernel. Today the output matches the render-path TES
            // (same flag semantics as forceTessellation alone) — the
            // resulting MSL is stashed but the probe doesn't yet build
            // a TES-compute PSO from it.
            appgl::TranslatorOptions tesComputeOpts;
            tesComputeOpts.forceTessellation = true;
            tesComputeOpts.forceTessEvalAsCompute = true;
            tesComputeOpts.tesePatchVertices = tcsOutputVertices;
            // Sprint 5 Phase 1 — Path L Class 2A: also enable on TES-
            // compute path so TES kernel reads gl_TessLevelOuter/Inner
            // from spvTessLevelFull (full-precision) instead of half-
            // precision spvTessLevel.
            tesComputeOpts.useFullPrecisionTessLevelBuffer = true;
            if (tessControlShader != nullptr && !tessControlShader->spirv.empty()) {
                tesComputeOpts.siblingTcsOutputSpirv = tessControlShader->spirv.data();
                tesComputeOpts.siblingTcsOutputWordCount = tessControlShader->spirv.size();
            }
            ShaderReflection tesComputeRefl;
            (void)translateCachedStage(
                "tess-eval-as-compute", tessEvalShader,
                programObject->tessEvalAsComputeMSL, tesComputeRefl,
                tesComputeOpts);
            programObject->tessEvalAsComputeReflection = tesComputeRefl;
            // Phase 3B.5 [metal-tess-TF]: reflect the TES output
            // struct layout under the same translator options so the
            // TF-capture encoder can locate each GL-declared TF
            // varying by name at draw time.
            if (tessEvalShader != nullptr && !tessEvalShader->spirv.empty()) {
                programObject->tessEvalOutputLayout =
                    translator.reflectStageOutputLayout(
                        tessEvalShader->spirv.data(),
                        tessEvalShader->spirv.size(),
                        tesComputeOpts);
            }
            if (tessEvalShader && !tessEvalShader->spirv.empty()) {
                auto teModes = extractTessellationModes(
                    tessEvalShader->spirv.data(), tessEvalShader->spirv.size());
                programObject->tessGenMode = teModes.genMode;
                programObject->tessGenSpacing = teModes.genSpacing;
                programObject->tessGenVertexOrder = teModes.genVertexOrder;
                programObject->tessGenPointMode = teModes.pointMode ? GL_TRUE : GL_FALSE;
            }

            Runtime::shared().recordShaderTranslation({
                programTag + "-tessellation-emulation", "tessellation",
                tessControlShader != nullptr
                    ? quickHash(tessControlShader->source)
                    : std::string(),
                linkVertexHash, linkFragmentHash,
                "tessellation emulation not yet available on Metal; "
                "program translated VS+FS only, falls back to raster-without-tess",
                "", false
            });
            if (vsOk && fsOk) {
                programObject->vertexReflection = std::move(vsRefl);
                programObject->fragmentReflection = std::move(fsRefl);
                programObject->hasTranslatedPipeline = true;
                rasterTranslationOk = true;
            }
            // Tessellation emulator detection (scaffolding — iter 162).
            // Mirrors the GS-emul pattern: copy SPIR-V onto the program
            // so draw-time emulation survives detach+delete, then call
            // the detector. The detector's `.tessellationEmulated` flag
            // stays false through iter 162 — subsequent iters flip it
            // on once the draw-time logic lands.
            if (vertexShader != nullptr && !vertexShader->spirv.empty()) {
                programObject->vertexSpirv = vertexShader->spirv;
            }
            if (tessControlShader != nullptr && !tessControlShader->spirv.empty()) {
                programObject->tessControlSpirv = tessControlShader->spirv;
                // Phase 3f-11: invalidate the parsed-module cache so
                // subsequent runTcsForVertex calls re-parse against
                // the new SPIR-V blob.
                programObject->tessControlParsedModule.reset();
            }
            if (tessEvalShader != nullptr && !tessEvalShader->spirv.empty()) {
                programObject->tessEvalSpirv = tessEvalShader->spirv;
                programObject->tessEvalParsedModule.reset();
            }
            (void)appgl::detectTessellationEmulatable(*programObject);

            // Metal tess Phase 1 probe — validate that the tess-MSL
            // stashed above compiles into Metal pipeline states. No
            // draw-time consumer yet; the CPU interpreter path still
            // handles every drawArrays(GL_PATCHES, ...) call. The
            // retained TCS compute PSO becomes Phase 2's input.
            // Detector point pre-A — catches programs that have tess
            // shaders but get skipped by the probe gate below. The
            // existing point A (after the probe runs) is silent for
            // gl_in-class shapes because the conventional vertex-form
            // TES MSL never gets generated, so this gate trips first.
            if (detectorEnabled() &&
                (tessControlShader != nullptr || tessEvalShader != nullptr)) {
                // Mirror the actual probe gate: accept either form of
                // TES MSL (conventional vertex or as-compute kernel).
                const bool gateOk = (impl_->frameGraph != nullptr &&
                    !programObject->tessControlMSL.empty() &&
                    (!programObject->tessEvalMSL.empty() ||
                     !programObject->tessEvalAsComputeMSL.empty()) &&
                    !programObject->fragmentMSL.empty());
                std::fprintf(stderr,
                    "APPGL_DETECTOR lift_translate program=%u "
                    "tcsMSL_empty=%d tesMSL_empty=%d fsMSL_empty=%d "
                    "tesAsComputeMSL_empty=%d vsAsComputeMSL_empty=%d "
                    "frameGraph_present=%d -> probe_gate_ok=%d\n",
                    program,
                    programObject->tessControlMSL.empty() ? 1 : 0,
                    programObject->tessEvalMSL.empty() ? 1 : 0,
                    programObject->fragmentMSL.empty() ? 1 : 0,
                    programObject->tessEvalAsComputeMSL.empty() ? 1 : 0,
                    programObject->tessVertexAsComputeMSL.empty() ? 1 : 0,
                    impl_->frameGraph != nullptr ? 1 : 0,
                    gateOk ? 1 : 0);
            }
            // Probe gate: post-isolines-compute-bypass-patch (SPIRV-Cross
            // commit 095c99c, 2026-04-26), TES isolines emits non-empty
            // `tessEvalAsComputeMSL` while `tessEvalMSL` (conventional
            // render-vertex form) stays empty because Metal's render
            // pipeline doesn't support isoline tessellation. Allow the
            // probe to run when EITHER form is available — the probe's
            // internals already gate the conventional render-PSO build
            // on `tesMSL` non-empty separately.
            const bool tessEvalAvailable =
                !programObject->tessEvalMSL.empty() ||
                !programObject->tessEvalAsComputeMSL.empty();
            if (impl_->frameGraph != nullptr &&
                !programObject->tessControlMSL.empty() &&
                tessEvalAvailable &&
                !programObject->fragmentMSL.empty()) {
                MetalFrameGraph::TessPipelineProbeResult probe =
                    impl_->frameGraph->probeTessellationPipeline(
                        programObject->tessControlMSL,
                        programObject->tessEvalMSL,
                        programObject->fragmentMSL,
                        programObject->tessGenMode,
                        programObject->tessGenSpacing,
                        programObject->tessGenVertexOrder,
                        programObject->tessVertexAsComputeMSL,
                        programObject->tessEvalAsComputeMSL);
                // Phase 3: stash the VS-as-compute PSO when the probe
                // built it. Non-fatal if it didn't (the simpler Phase-2
                // path still works for programs without VS→TCS flow).
                if (probe.vertexComputeOk) {
                    programObject->metalTessVertexPipelineState =
                        probe.vertexComputePipelineState;
                }
                // T4I [metal-tess-TF]: when the VS-as-compute MSL
                // declares `[[stage_in]]`, the PSO must be built at
                // draw time from the bound VAO's
                // MTLStageInputOutputDescriptor. Probe set the flag
                // when it caught the stage_in compile error.
                if (probe.vertexComputeNeedsDescriptor) {
                    programObject->metalTessVertexNeedsDescriptor = true;
                }
                // Phase 3B.4 [metal-tess-TF]: stash the TES-as-compute
                // PSO when the probe built it. Enables the 4-dispatch
                // TF-capture chain at draw time.
                if (probe.tessEvalComputeOk) {
                    programObject->metalTessEvalComputePipelineState =
                        probe.tessEvalComputePipelineState;
                }
                // Metal tess tier gate: classify the program against
                // the encoder capability matrix.
                //   Phase 2 — TCS MSL uses only factor (26) + indirect
                //     (29) buffers; TES has no per-CP/per-patch
                //     buffer inputs. Trivial VS (empty or no user
                //     outputs). Encoded by `encodeMetalTessellationDraw`.
                //   Phase 3 — TCS or TES declares VS-input
                //     (`spvIn [[buffer(22)]]` on TCS), per-CP output
                //     (`spvOut [[buffer(28)]]` on TCS), per-patch
                //     output (`spvPatchOut [[buffer(27)]]` on TCS),
                //     per-CP input (`spvIn [[buffer(22)]]` on TES), or
                //     per-patch input (`spvPatchIn [[buffer(20)]]` on
                //     TES). Requires VS-as-compute PSO from the probe.
                //     Encoded by `encodeMetalTessellationDrawPhase3`.
                //   None — probe failed OR Phase 3 needed but VS
                //     compute PSO couldn't build (VS uses
                //     [[stage_in]] without a descriptor). Falls
                //     through to the CPU tessellation interpreter.
                const bool needsPhase3 =
                    probe.computeOk && (
                        programObject->tessControlMSL.find("spvIn [[buffer(") != std::string::npos ||
                        programObject->tessControlMSL.find("spvOut [[buffer(") != std::string::npos ||
                        programObject->tessControlMSL.find("spvPatchOut [[buffer(") != std::string::npos ||
                        programObject->tessEvalMSL.find("spvIn [[buffer(") != std::string::npos ||
                        programObject->tessEvalMSL.find("spvPatchIn [[buffer(") != std::string::npos);
                // ----------------------------------------------------
                // APPGL_ENABLE_METAL_TESS_TF — master enable for the
                // Metal tess+TF compute chain. When set:
                //   • This link-time block sets metalTessTier for tess
                //     programs with TF varyings (Phase2 or Phase3) and
                //     stashes metalTessEvalComputePipelineState. Without
                //     it, tessBlockedByTF==true forces tier=None and
                //     every drawArrays(GL_PATCHES) routes to the CPU
                //     tess interpreter.
                //   • tryMetalTessellationDraw and the rasterizer-
                //     discard probe path also re-check this env (4
                //     read sites in this file plus the dispatch site
                //     in MetalFrameGraph.mm).
                // It pairs with APPGL_LIFT_TESS_UNIFORM_GUARD: that var
                // additionally relaxes the "tess uses uniforms → CPU
                // fallback" guard, but on its own does NOTHING because
                // the master enable above is required to even build the
                // PSOs at link time. Both must be set for the Metal
                // compute chain to engage on uniform-using tess shaders.
                // Default off — enabling produces measurable forward
                // motion (env-off→env-full vacuous→genuine transitions
                // landed 11 GENUINE_PASS in the 2026-04-25 baseline)
                // but also exposes byte-layout / kernel-emission gaps
                // (data_pass_through-class still fails verification).
                // Programs that declared TF varyings at link time must
                // source TES output into the bound TF buffer at draw
                // time. tessTFReady=true means: (a) probe built the TES
                // compute PSO, (b) reflection produced a TES output
                // layout, (c) APPGL_ENABLE_METAL_TESS_TF is set.
                const bool tessUsesTF =
                    !programObject->transformFeedbackVaryingNames.empty();
                const bool tessTFReady =
                    probe.tessEvalComputeOk &&
                    programObject->tessEvalOutputLayout.structSize > 0 &&
                    std::getenv("APPGL_ENABLE_METAL_TESS_TF") != nullptr;
                const bool tessBlockedByTF = tessUsesTF && !tessTFReady;
                if (probe.computeOk && !needsPhase3 && !tessBlockedByTF) {
                    programObject->metalTessTier =
                        GLProgramObject::MetalTessTier::Phase2;
                    programObject->metalTessControlPipelineState =
                        probe.computePipelineState;
                } else if (probe.computeOk && needsPhase3 && !tessBlockedByTF &&
                           (probe.vertexComputeOk || probe.vertexComputeNeedsDescriptor)) {
                    // T4I [metal-tess-TF]: Phase 3 is reachable when
                    // VS-compute either built directly (no stage_in)
                    // OR needs a descriptor at draw time. The encoder
                    // checks `metalTessVertexNeedsDescriptor` and
                    // builds-or-reuses a per-VAO PSO before dispatch.
                    programObject->metalTessTier =
                        GLProgramObject::MetalTessTier::Phase3;
                    programObject->metalTessControlPipelineState =
                        probe.computePipelineState;
                    // vertexComputePipelineState is already stashed
                    // above when probe.vertexComputeOk was true.
                } else if (probe.computeOk) {
                    // Phase 3 required (complex MSL) but VS-compute
                    // PSO didn't build — most commonly VS with
                    // [[stage_in]] attributes and no descriptor. CPU
                    // fallback until Phase 3.3 wires the descriptor.
                    releaseRetainedMetalObject(probe.computePipelineState);
                }
                if (std::getenv("APPGL_TRACE_TESS")) {
                    std::fprintf(stderr,
                        "[APPGL] tess-probe program=%u computeOk=%d renderOk=%d"
                        " vsComputeOk=%d tesComputeOk=%d tessTFReady=%d tier=%d"
                        " tesStructSize=%zu tfVaryings=%zu"
                        " genMode=0x%04X genSpacing=0x%04X"
                        " diag=%s\n",
                        program,
                        probe.computeOk ? 1 : 0,
                        probe.renderOk ? 1 : 0,
                        probe.vertexComputeOk ? 1 : 0,
                        probe.tessEvalComputeOk ? 1 : 0,
                        tessTFReady ? 1 : 0,
                        (int)programObject->metalTessTier,
                        programObject->tessEvalOutputLayout.structSize,
                        programObject->transformFeedbackVaryingNames.size(),
                        programObject->tessGenMode,
                        programObject->tessGenSpacing,
                        probe.diagnostic.c_str());
                }
                // Detector point A — link-time probe outcome paired with the
                // gate (B) and dispatch (C) lines so a single APPGL_DETECTOR_TF
                // invocation tells the full story.  diag escaping: keep the
                // string short (no newlines come from the probe diagnostic).
                if (detectorEnabled()) {
                    std::fprintf(stderr,
                        "APPGL_DETECTOR lift_probe program=%u computeOk=%d "
                        "vsComputeOk=%d tesComputeOk=%d tessTFReady=%d "
                        "tier=%d tesStructSize=%zu tfVaryings=%zu "
                        "genMode=0x%04X genSpacing=0x%04X diag=\"%s\"\n",
                        program,
                        probe.computeOk ? 1 : 0,
                        probe.vertexComputeOk ? 1 : 0,
                        probe.tessEvalComputeOk ? 1 : 0,
                        tessTFReady ? 1 : 0,
                        (int)programObject->metalTessTier,
                        programObject->tessEvalOutputLayout.structSize,
                        programObject->transformFeedbackVaryingNames.size(),
                        programObject->tessGenMode,
                        programObject->tessGenSpacing,
                        probe.diagnostic.c_str());
                }
                Runtime::shared().recordShaderTranslation({
                    programTag + "-tessellation-metal-probe", "tessellation",
                    tessControlShader != nullptr
                        ? quickHash(tessControlShader->source)
                        : std::string(),
                    linkVertexHash, linkFragmentHash,
                    probe.renderOk
                        ? std::string("Metal tess pipeline probe: compute + render both built")
                        : (probe.computeOk
                            ? std::string("Metal tess render pipeline failed: ") + probe.diagnostic
                            : std::string("Metal tess compute pipeline failed: ") + probe.diagnostic),
                    "",
                    probe.computeOk && probe.renderOk
                });
            }
            break;
        }
        case ProgramKind::GeometryOnly: {
            // Separable GS-only program (for use with program pipelines).
            // Translate to MSL so reflection populates; actual draw falls
            // back through the raster-without-GS path, same as VGF.
            std::string unusedGsMSL;
            ShaderReflection gsRefl;
            (void)translateCachedStage("geometry", geometryShader,
                                       unusedGsMSL, gsRefl);
            // CKPT163 (Sprint 14 Day 10): persist the GS reflection on
            // the program. Pre-fix it was captured into a local that
            // immediately fell out of scope, so the runtime
            // (buildStorageImageMap, buildSampledTextureMap, draw-path
            // resource resolution) saw an empty reflection on every
            // separable GS-only program. Sister to the VS+GS+FS path at
            // line 20668 which always persisted gsRefl.
            programObject->geometryReflection = gsRefl;
            // Sister-fix: translateCachedStage above bails before
            // reflect() if spirvToMSL fails or returns empty, which
            // happens for GS shaders that SPIRV-Cross can't fully
            // translate (e.g. complex EmitVertex / EmitStreamVertex
            // shapes used by CTS shader_image_size.basic-nonMS-gs-*).
            // Direct reflect-only fallback walks the SPIR-V again
            // and populates `storageImages`/`sampledTextures`/
            // `uniformBlocks`/`storageBuffers` even when MSL emit
            // failed — the GS interpreter doesn't need MSL anyway,
            // only the reflection metadata.
            if (geometryShader != nullptr && !geometryShader->spirv.empty()) {
                if (programObject->geometryReflection.storageImages.empty() &&
                    programObject->geometryReflection.sampledTextures.empty() &&
                    programObject->geometryReflection.uniformBlocks.empty()) {
                    try {
                        appgl::ShaderTranslator reflTranslator;
                        appgl::BindingMap reflBindings;  // defaults are fine
                                                          // for reflect-only.
                        programObject->geometryReflection =
                            reflTranslator.reflect(
                                geometryShader->spirv.data(),
                                geometryShader->spirv.size(),
                                reflBindings, nullptr);
                    } catch (...) {
                        // If reflect throws, leave the empty
                        // reflection in place — same end-state as
                        // pre-fix.
                    }
                }
                programObject->geometrySpirv = geometryShader->spirv;
                (void)appgl::detectGeometryEmulatable(*programObject);
            }
            rasterTranslationOk = true;
            break;
        }
        case ProgramKind::TessControlOnly: {
            // Separable TCS-only program (for use with program pipelines).
            // Translate to MSL for reflection + extract tessellation modes.
            // Metal tess Phase 1: force tess options so the stashed MSL
            // matches the Metal-native tess pipeline shape.
            appgl::TranslatorOptions tessOpts;
            tessOpts.forceTessellation = true;
            ShaderReflection tcRefl;
            (void)translateCachedStage("tess-control", tessControlShader,
                                       programObject->tessControlMSL, tcRefl,
                                       tessOpts);
            programObject->tessControlReflection = tcRefl;
            // Extract tessellation execution modes from SPIR-V.
            programObject->hasTessellation = true;
            if (!tessControlShader->spirv.empty()) {
                auto tcModes = extractTessellationModes(
                    tessControlShader->spirv.data(),
                    tessControlShader->spirv.size());
                programObject->tessControlOutputVertices =
                    static_cast<GLint>(tcModes.outputVertices);
            }
            // β [metal-tess-TF]: preserve TCS SPIR-V so the pipeline-time
            // orchestrator can re-translate with cross-stage info
            // (siblingTesInputSpirv) once a TES separable program is
            // also bound to the pipeline.
            if (tessControlShader != nullptr && !tessControlShader->spirv.empty()) {
                programObject->tessControlSpirv = tessControlShader->spirv;
                programObject->tessControlParsedModule.reset();
            }
            rasterTranslationOk = true;
            break;
        }
        case ProgramKind::TessEvalOnly: {
            // Separable TES-only program (for use with program pipelines).
            // Metal tess Phase 1: force tess options on.
            appgl::TranslatorOptions tessOpts;
            tessOpts.forceTessellation = true;
            ShaderReflection teRefl;
            (void)translateCachedStage("tess-eval", tessEvalShader,
                                       programObject->tessEvalMSL, teRefl,
                                       tessOpts);
            // Extract tessellation execution modes from SPIR-V.
            programObject->hasTessellation = true;
            if (!tessEvalShader->spirv.empty()) {
                auto teModes = extractTessellationModes(
                    tessEvalShader->spirv.data(),
                    tessEvalShader->spirv.size());
                programObject->tessGenMode = teModes.genMode;
                programObject->tessGenSpacing = teModes.genSpacing;
                programObject->tessGenVertexOrder = teModes.genVertexOrder;
                programObject->tessGenPointMode =
                    teModes.pointMode ? GL_TRUE : GL_FALSE;
            }
            // β [metal-tess-TF]: preserve TES SPIR-V so the pipeline-time
            // orchestrator can re-translate the compute form with
            // forceTessEvalAsCompute + tesePatchVertices plumbed.
            if (tessEvalShader != nullptr && !tessEvalShader->spirv.empty()) {
                programObject->tessEvalSpirv = tessEvalShader->spirv;
                programObject->tessEvalParsedModule.reset();
            }
            rasterTranslationOk = true;
            break;
        }
        case ProgramKind::Separable: {
            // Separable multi-stage combo — translate every attached
            // vertex-processing stage for introspection; actual draw
            // sourcing comes from the pipeline object later. For
            // `incomplete_program_objects` we just need link-status
            // == GL_TRUE; drawing this specific combination never
            // happens because the CTS test immediately discards the
            // program.
            auto translateSingle = [&](GLShaderObject* sh, GLenum stageEnum,
                                       std::string& outMSL,
                                       ShaderReflection& outRefl) {
                if (sh == nullptr || sh->spirv.empty()) return;
                BindingMap stageBindings;
                appgl::TranslatorOptions stageOptions;
                stageOptions.forceArgumentBuffers = spirvUsesStorageBuffers(
                    sh->spirv.data(), sh->spirv.size());
                outMSL = translator.spirvToMSL(sh->spirv.data(),
                    sh->spirv.size(), stageBindings, nullptr, stageOptions);
                outRefl = translator.reflect(sh->spirv.data(),
                    sh->spirv.size(), stageBindings, nullptr, stageOptions);
                (void)stageEnum;
            };
            translateSingle(vertexShader, GL_VERTEX_SHADER,
                            programObject->vertexMSL, programObject->vertexReflection);
            translateSingle(fragmentShader, GL_FRAGMENT_SHADER,
                            programObject->fragmentMSL, programObject->fragmentReflection);
            rasterTranslationOk = true;
            break;
        }
        case ProgramKind::Unknown:
            break;  // Already handled above; kept so -Wswitch stays happy.
    }

    APPGL_LOG(SHADER, @"[GL] linkProgram: program=%u kind=%d translationOk=%d "
          @"vertexInputs=%zu vsUniformBlocks=%zu fsUniformBlocks=%zu",
          program, static_cast<int>(kind), rasterTranslationOk ? 1 : 0,
          programObject->vertexReflection.vertexInputs.size(),
          programObject->vertexReflection.uniformBlocks.size(),
          programObject->fragmentReflection.uniformBlocks.size());
    fflush(stderr);  // Phase 8X Group 4d follow-up²³ — synchronous flush

    // ── Supplement scanner-discovered uniforms with SPIR-V reflection ──
    //
    // The lightweight GLSL scanner (GLSLReflection) can't parse struct-typed
    // uniforms, interface-block members, or other complex declarations.
    // SPIRV-Cross reflection IS authoritative for the _DefaultUniforms block
    // members — it sees every uniform that survived dead-code elimination.
    // Walk the _DefaultUniforms members from each stage's reflection and add
    // any that the scanner missed to the program's uniform list with fresh
    // locations and zero-seeded values.  This lets glGetUniformLocation /
    // glUniform* work for struct members (e.g. "s.a"), array-of-struct
    // elements ("s[0].a"), and any other uniform type the scanner can't parse.
    if (rasterTranslationOk || kind == ProgramKind::Compute) {
        // Build a set of names the scanner already discovered.
        std::unordered_set<std::string> knownUniformNames;
        for (const auto& u : programObject->uniforms) {
            knownUniformNames.insert(u.name);
        }

        // Find the next available auto-location (past all existing ones).
        GLint supplementNextLoc = 0;
        for (const auto& u : programObject->uniforms) {
            const GLint endLoc = u.location + std::max<GLint>(u.arraySize, 1);
            if (endLoc > supplementNextLoc) {
                supplementNextLoc = endLoc;
            }
        }

        // "Does this stage's source declare a uniform named
        // `topName` at the top level?" helper. Only stage-declared
        // uniforms may carry this stage's REFERENCED_BY bit in the
        // resource table. A naive word-boundary search of the whole
        // source produces false positives — a struct field with
        // the same name as a VS uniform would match (CTS
        // uniform-types has `struct U { bool a[3]; ... }` in the
        // FS and `uniform vec4 a;` in the VS). We want only the
        // `uniform X <topName>[...];` pattern. Walk each `uniform`
        // token (word-bounded) and inspect the identifier tokens
        // up to the next `;` or `{` — if `topName` appears as one
        // of them, treat it as declared.
        auto stageDeclaresTopUniform = [](const std::string& src, const std::string& topName) {
            if (topName.empty()) return false;
            const std::string uniformKw = "uniform";
            std::size_t pos = 0;
            while ((pos = src.find(uniformKw, pos)) != std::string::npos) {
                const bool leftBoundary = (pos == 0) ||
                    !(std::isalnum(static_cast<unsigned char>(src[pos - 1])) || src[pos - 1] == '_');
                const bool rightBoundary = (pos + uniformKw.size() < src.size()) &&
                    !(std::isalnum(static_cast<unsigned char>(src[pos + uniformKw.size()])) || src[pos + uniformKw.size()] == '_');
                if (!(leftBoundary && rightBoundary)) {
                    pos += uniformKw.size();
                    continue;
                }
                // Scan identifiers from pos+7 up to first ; or {.
                std::size_t scan = pos + uniformKw.size();
                while (scan < src.size() && src[scan] != ';' && src[scan] != '{') {
                    // Skip non-identifier chars.
                    while (scan < src.size() &&
                           !std::isalpha(static_cast<unsigned char>(src[scan])) &&
                           src[scan] != '_' &&
                           src[scan] != ';' && src[scan] != '{') {
                        ++scan;
                    }
                    if (scan >= src.size() || src[scan] == ';' || src[scan] == '{') break;
                    std::size_t identStart = scan;
                    while (scan < src.size() &&
                           (std::isalnum(static_cast<unsigned char>(src[scan])) || src[scan] == '_')) {
                        ++scan;
                    }
                    std::string ident = src.substr(identStart, scan - identStart);
                    if (ident == topName) return true;
                }
                pos = scan;
            }
            return false;
        };
        // Extract the top-level uniform name from a flattened member
        // name. `j.b` → `j`, `k.a[0].c` → `k`, `l[2].b[1].d[0]` → `l`.
        auto topLevelName = [](const std::string& flat) -> std::string {
            std::size_t cut = flat.size();
            for (std::size_t i = 0; i < flat.size(); ++i) {
                if (flat[i] == '.' || flat[i] == '[') { cut = i; break; }
            }
            return flat.substr(0, cut);
        };
        // Lambda: scan one stage's reflection for _DefaultUniforms members.
        // `stageBit` is the referencedBy bit for this stage so struct
        // members declared by the stage accumulate the right bit in the
        // resourceUniforms table. `stageSrc` is the stage's GLSL source
        // (used to gate the stage bit on whether this stage actually
        // declared the top-level uniform — glslang's cross-stage
        // linking copies every uniform into every stage's SPIR-V
        // _DefaultUniforms reflection, so "member is in this stage's
        // SPIR-V" is NOT a valid signal for "stage references it").
        // CTS `program_interface_query.uniform-types` declares
        // `uniform U j;` in the FS and expects
        // REFERENCED_BY_FRAGMENT_SHADER = 1 on every flattened leaf
        // (`j.b`, etc.) and REFERENCED_BY_VERTEX_SHADER = 0.
        auto supplementFromReflection = [&](const ShaderReflection& refl,
                                            GLbitfield stageBit,
                                            const std::string& stageSrc) {
            if (refl.uniformBlocks.empty()) return;
            // The _DefaultUniforms block is always at index 0 when present.
            const auto& block = refl.uniformBlocks[0];
            if (block.name != "_DefaultUniforms") return;
            for (const auto& member : block.members) {
                // Sprint 17 Day 7+ Bank-Group-C: skip synthetic
                // dispatch uniforms emitted by
                // `rewriteSubroutinesForSpirv` for v1 dynamic
                // dispatch. These are processed separately by
                // `processSubroutineDispatchUniforms` (above) for ALL
                // stages and exposed only via the side-channel
                // `subroutineDispatchUniformLocations`. Spec-correct:
                // subroutine uniforms are queryable via separate
                // GL_*_SUBROUTINE_UNIFORM interfaces only and must NOT
                // appear in glGetActiveUniform enumeration.
                if (member.name.compare(0, 11, "_appgl_sub_") == 0) {
                    continue;
                }
                // Skip the rewriter's bare-name reserved-keyword
                // validation stubs (`int <NAME>;` for each subroutine
                // uniform / type). These exist only to push the
                // user identifier through glslang's reserved-keyword
                // check (CTS CommonBugs.CommonBug_ReservedNames); they
                // would otherwise leak as bogus default-block int
                // uniforms with auto-assigned locations in
                // glGetUniformLocation / glGetActiveUniform output.
                {
                    bool isSubroutineStub = false;
                    for (int sIdx = 0; sIdx < 6 && !isSubroutineStub; ++sIdx) {
                        for (const auto& su : programObject->resourceSubroutineUniforms[sIdx]) {
                            if (su.name == member.name) { isSubroutineStub = true; break; }
                        }
                        if (isSubroutineStub) break;
                        for (const auto& sr : programObject->resourceSubroutines[sIdx]) {
                            if (sr.name == member.name) { isSubroutineStub = true; break; }
                        }
                    }
                    if (isSubroutineStub) continue;
                }
                // Gate this stage's referencedBy bit on whether the
                // stage's source actually declares the top-level
                // name as a uniform (see lambda comment above).
                // Without this filter every uniform gets both stages'
                // bits because glslang's cross-stage linker fills
                // every stage's _DefaultUniforms with the union.
                const std::string topName = topLevelName(member.name);
                const bool stageDeclares = stageDeclaresTopUniform(stageSrc, topName);
                const GLbitfield effStageBit = stageDeclares ? stageBit : 0;
                // GL 4.6 §7.3.1 canonical resource name for an array
                // uniform carries the "[0]" suffix even when the
                // member's SPIR-V name does not. Compute both forms
                // so we can match against `knownUniformNames`
                // (which already stores the canonical shape) and
                // resourceUniforms (which also stores canonical).
                const std::string canonicalName = member.isArray
                    ? (member.name + "[0]") : member.name;
                if (knownUniformNames.count(canonicalName) ||
                    knownUniformNames.count(member.name)) {
                    // Existing uniform (from scanner or previous
                    // stage) — just OR in this stage's referencedBy
                    // bit on its resourceUniforms entry.
                    for (auto& re : programObject->resourceUniforms) {
                        if (re.name == canonicalName || re.name == member.name) {
                            re.referencedBy |= effStageBit;
                            break;
                        }
                    }
                    continue;
                }
                // Skip members this stage doesn't declare — they'll
                // be added by the OTHER stage's supplement pass with
                // the correct referencedBy bit.
                if (!stageDeclares) continue;
                // New uniform discovered by SPIR-V but not by the scanner.
                GLProgramUniformInfo info;
                info.name = member.name;
                info.type = member.type;
                info.arraySize = (member.arraySize > 0)
                    ? static_cast<GLint>(member.arraySize) : 1;
                info.isArray = member.isArray;
                info.explicitLocation = -1;
                info.explicitBinding = -1;
                // GL 4.6 §7.6.2.2 — when the scanner already registered
                // the top-level parent uniform with an explicit location
                // (e.g. `layout(location = 2) uniform float u0[2][3]`),
                // the SPIRV-Cross-flattened members (`u0[0]`, `u0[1]`)
                // must be located at parent.explicitLocation + i*members
                // per element, NOT at supplementNextLoc (which would auto-
                // assign past every explicit location). CTS
                // `explicit_uniform_location.uniform-loc-arrays-of-arrays`
                // asserts `u0[0][0]` = 2 for `u0[2][3]` at location 2.
                const std::string memberTopName = topLevelName(member.name);
                const GLProgramUniformInfo* parent = nullptr;
                for (const auto& u : programObject->uniforms) {
                    if (u.name == memberTopName && u.explicitLocation >= 0) {
                        parent = &u;
                        break;
                    }
                }
                bool locationSet = false;
                if (parent != nullptr) {
                    // Parse the member name's subscript chain relative to the
                    // parent. `u0[i]` for a single-subscript member of an
                    // outer-dim-split array-of-arrays gives flattened offset
                    // i * inner_arraySize. `u0[i].field` for a struct array
                    // gives i * struct_size_in_locations + field_offset —
                    // but we don't track per-field offsets here, so fall
                    // through to supplementNextLoc for struct-member shapes.
                    const std::string tail = member.name.substr(memberTopName.size());
                    // Require pure `[i]` form; anything else (containing `.`
                    // or multiple brackets) is structurally complex and we
                    // fall back to auto-assignment.
                    if (tail.size() >= 3 && tail.front() == '[' && tail.back() == ']'
                        && tail.find('.') == std::string::npos
                        && std::count(tail.begin(), tail.end(), '[') == 1) {
                        const std::string idxText = tail.substr(1, tail.size() - 2);
                        char* endp = nullptr;
                        const long idx = std::strtol(idxText.c_str(), &endp, 10);
                        if (endp && *endp == '\0' && idx >= 0) {
                            const GLint perEntryLocs = std::max<GLint>(info.arraySize, 1);
                            info.location = parent->explicitLocation +
                                static_cast<GLint>(idx) * perEntryLocs;
                            locationSet = true;
                        }
                    }
                }
                if (!locationSet) {
                    info.location = supplementNextLoc;
                    supplementNextLoc += std::max<GLint>(info.arraySize, 1);
                }
                knownUniformNames.insert(canonicalName);

                // Zero-seed the uniform value.
                const GLint components = glslComponentCount(info.type)
                    * std::max<GLint>(info.arraySize, 1);
                const std::size_t cnt = static_cast<std::size_t>(components);
                GLProgramUniformValue value;
                value.type = info.type;
                value.arraySize = info.arraySize;
                switch (info.type) {
                    case GL_INT: case GL_INT_VEC2: case GL_INT_VEC3: case GL_INT_VEC4:
                    case GL_BOOL: case GL_BOOL_VEC2: case GL_BOOL_VEC3: case GL_BOOL_VEC4:
                        value.ints.assign(cnt, 0);
                        break;
                    case GL_UNSIGNED_INT: case GL_UNSIGNED_INT_VEC2:
                    case GL_UNSIGNED_INT_VEC3: case GL_UNSIGNED_INT_VEC4:
                        value.uints.assign(cnt, 0u);
                        break;
                    default:
                        value.floats.assign(cnt, 0.0f);
                        break;
                }
                programObject->uniformValues[info.location] = std::move(value);

                // Mirror into resourceUniforms as a default-block
                // uniform. GL 4.6 §7.3.1: default-block uniforms
                // have BLOCK_INDEX = OFFSET = ARRAY_STRIDE =
                // MATRIX_STRIDE = -1, IS_ROW_MAJOR = FALSE,
                // ATOMIC_COUNTER_BUFFER_INDEX = -1. REFERENCED_BY_*
                // carries just this stage's bit.
                GLProgramResourceEntry entry;
                entry.name = canonicalName;
                entry.type = info.type;
                entry.location = info.location;
                entry.binding = -1;
                entry.arraySize = info.arraySize;
                entry.isArray = info.isArray;
                entry.referencedBy = effStageBit;
                // Default-block uniforms: leave offset / blockIndex
                // / arrayStride / matrixStride at their default -1
                // sentinels so getResourceProperty reports -1.
                programObject->resourceUniforms.push_back(std::move(entry));

                programObject->uniforms.push_back(std::move(info));
            }
        };

        static const std::string kEmptySrc;
        const std::string& vsSrc2 = vertexShader ? vertexShader->source : kEmptySrc;
        const std::string& fsSrc2 = fragmentShader ? fragmentShader->source : kEmptySrc;
        supplementFromReflection(programObject->vertexReflection, 0x01, vsSrc2);
        supplementFromReflection(programObject->fragmentReflection, 0x02, fsSrc2);
        // Tess stages: source the reflection from whichever TES form
        // got translated (compute form for combined VertexTessellation
        // Fragment programs, vertex form would be similar but isn't
        // stashed today). TCS reflection is always stashed when the
        // stage was translated. Stage bits: TCS=0x08, TES=0x10
        // (mirror of glProgramInterfaceiv / GL_REFERENCED_BY_*).
        // Closes the
        //   single.ext_program_interface_query_dependency
        // failure where `glGetProgramResourceIndex(po, GL_UNIFORM,
        // "tc_uniform1")` returned `GL_INVALID_INDEX` because the
        // tess-stage default-block uniforms never made it into
        // `resourceUniforms`.
        const std::string& tcsSrc2 = tessControlShader ? tessControlShader->source : kEmptySrc;
        const std::string& tesSrc2 = tessEvalShader ? tessEvalShader->source : kEmptySrc;
        supplementFromReflection(programObject->tessControlReflection, 0x08, tcsSrc2);
        supplementFromReflection(programObject->tessEvalAsComputeReflection, 0x10, tesSrc2);

        // ── Sprint 17 Day 7+ Bank-Group-C: synthetic dispatch uniforms ──
        //
        // The compat rewriter `rewriteSubroutinesForSpirv` emits one
        // `uniform uint _appgl_sub_<UNI>;` per v1-eligible subroutine
        // uniform (void return, no params) so the inline if-else
        // dispatch chain emitted at call sites can branch on the
        // selected impl. These synthetic uniforms appear in EVERY
        // stage's `_DefaultUniforms` block (whichever stage declared
        // the subroutine). Unlike user uniforms, this processing runs
        // for ALL stages — including GS and CS, which
        // `supplementFromReflection` does NOT cover — because the
        // synthetic uniform must be locatable for the
        // `glUniformSubroutinesuiv` setter regardless of which stage
        // emitted it (CTS `viewport_index_subroutine` declares the
        // subroutine in GS only).
        //
        // Names are excluded from `programObject->resourceUniforms`
        // (so glGetActiveUniform / glGetProgramResource* enumeration
        // doesn't expose them — spec-correct: subroutine uniforms are
        // queryable via separate GL_*_SUBROUTINE_UNIFORM interfaces
        // only). The reflection filter at the top of the
        // `supplementFromReflection` member loop also skips them for
        // the VS/FS/TCS/TES paths.
        auto processSubroutineDispatchUniforms = [&](const ShaderReflection& refl) {
            if (refl.uniformBlocks.empty()) return;
            const auto& block = refl.uniformBlocks[0];
            if (block.name != "_DefaultUniforms") return;
            for (const auto& member : block.members) {
                if (member.name.compare(0, 11, "_appgl_sub_") != 0) continue;
                // Side-channel keyed by ORIGINAL subroutine-uniform
                // name (strip `_appgl_sub_` 11-char prefix).
                const std::string uniName = member.name.substr(11);
                // Reuse the scanner's pre-existing entry if present
                // (the lightweight GLSL reflector at reflectGLSL()
                // walks the rewritten source and picks up the
                // synthetic `uniform uint _appgl_sub_<UNI>;` decl
                // before this lambda runs); otherwise allocate a
                // fresh default-block slot. Either way the
                // side-channel must be populated so
                // glUniformSubroutinesuiv can locate the dispatch
                // uniform's value cell.
                GLint existingLoc = -1;
                for (const auto& u : programObject->uniforms) {
                    if (u.name == member.name) { existingLoc = u.location; break; }
                }
                GLint targetLoc = existingLoc;
                if (existingLoc < 0) {
                    GLProgramUniformInfo info;
                    info.name = member.name;
                    info.type = GL_UNSIGNED_INT;
                    info.arraySize = 1;
                    info.isArray = false;
                    info.explicitLocation = -1;
                    info.explicitBinding = -1;
                    info.location = supplementNextLoc;
                    supplementNextLoc += 1;
                    targetLoc = info.location;
                    knownUniformNames.insert(member.name);
                    programObject->uniforms.push_back(std::move(info));
                }
                // Ensure a zero-seeded value cell exists at the chosen
                // location (the scanner's appendDeclarationsAsUniforms
                // path doesn't seed values for uniforms it discovers
                // by source scanning — only the SPIR-V flatten path
                // does).
                auto& valueSlot = programObject->uniformValues[targetLoc];
                if (valueSlot.uints.empty()) {
                    valueSlot.type = GL_UNSIGNED_INT;
                    valueSlot.arraySize = 1;
                    valueSlot.uints.assign(1, 0u);
                }
                programObject->subroutineDispatchUniformLocations[uniName] = targetLoc;
                // Intentionally NOT pushed into resourceUniforms.
            }
        };
        processSubroutineDispatchUniforms(programObject->vertexReflection);
        processSubroutineDispatchUniforms(programObject->fragmentReflection);
        processSubroutineDispatchUniforms(programObject->geometryReflection);
        processSubroutineDispatchUniforms(programObject->tessControlReflection);
        processSubroutineDispatchUniforms(programObject->tessEvalAsComputeReflection);
        processSubroutineDispatchUniforms(programObject->computeReflection);
    }

    // ── Merge SPIRV-Cross uniform block reflection into the program's
    //    resource introspection tables ──
    //
    // The scanner doesn't see interface blocks (see 2d / GLSLReflection
    // brace-depth bug), so SPIRV-Cross reflection is the authoritative
    // source for UBO member metadata. Blocks that appear in both the
    // vertex and fragment reflection (BAR's per-view uniforms are shared
    // across stages) dedup by name, OR-ing the referencedBy bits together.
    //
    // Each block also pushes its members into resourceBufferVariables with
    // `blockIndex` pointing back to the block entry so
    // glGetProgramResourceiv(GL_BUFFER_VARIABLE, ...) can find them.
    if (rasterTranslationOk || kind == ProgramKind::Compute) {
        auto mergeBlocks = [&](const std::vector<ShaderReflection::ResourceBinding>& blocks,
                               GLbitfield stageBit,
                               const std::string& glslSource) {
            for (const auto& block : blocks) {
                // Skip glslang's synthesized default-block wrapper —
                // it's not a real user-declared UBO. `supplementFromReflection`
                // above already walked its members and added them as
                // default-block uniforms (BLOCK_INDEX=-1, OFFSET=-1).
                // Exposing it as a GL_UNIFORM_BLOCK resource would
                // inflate GL_ACTIVE_RESOURCES and tag every scalar
                // uniform with a bogus blockIndex. CTS
                // `program_interface_query.uniform-types` expects
                // default-block uniforms to report BLOCK_INDEX=-1
                // and OFFSET=-1.
                if (block.name == "_DefaultUniforms") {
                    continue;
                }
                // Only contribute this stage's REFERENCED_BY_*_SHADER
                // bit when the block is live in the stage's SPIR-V.
                // Declared-but-unused blocks still get an entry so
                // introspection lists them, but without the stage
                // bit. Same logic as mergeStorageBlocks below.
                const GLbitfield blockStageBit = block.active ? stageBit : 0;
                // SPIRV-Cross loses instance name info (varName == typeName
                // for both instanced and non-instanced blocks). Parse the
                // original GLSL source to recover it.
                const bool hasInstance =
                    glslBlockHasInstanceName(glslSource, block.name);
                // For an INSTANCED ARRAY block (`} e[2];`), narrow the
                // per-instance stage bit: only the elements actually
                // indexed in the stage's body are active in that stage.
                // CTS `program_interface_query.uniform-block-types`
                // declares `TrickyBlock e[2]` but only reads `e[0].…`,
                // so e[1] must report REFERENCED_BY_FRAGMENT_SHADER=0.
                const std::string instanceName = hasInstance
                    ? glslBlockInstanceName(glslSource, block.name)
                    : std::string();
                const std::set<int> usedInstanceIndices =
                    !instanceName.empty()
                        ? glslActiveInstanceIndices(glslSource, instanceName)
                        : std::set<int>();
                // If no `inst[N]` usage was found in the source (e.g.
                // the whole block is inactive, OR the instance is not
                // array-indexed), fall back to the block-level active
                // bit for all instances.
                const bool useInstanceNarrowing = !usedInstanceIndices.empty();

                // For array blocks (`uniform B { ... } b[N]`), create one
                // block entry per array element: "BlockName[0]", "BlockName[1]", ...
                // For non-array blocks, create a single entry: "BlockName".
                const int numInstances = (block.blockArraySize > 0)
                    ? static_cast<int>(block.blockArraySize) : 1;
                const bool isArray = (block.blockArraySize > 0);

                // Create block entries for each instance.
                GLint firstBlockIndex = -1;
                bool anyNewBlocks = false;
                GLbitfield firstInstStageBit = blockStageBit;  // used for member bit
                for (int inst = 0; inst < numInstances; ++inst) {
                    GLbitfield effStageBit = blockStageBit;
                    if (useInstanceNarrowing &&
                        usedInstanceIndices.count(inst) == 0) {
                        effStageBit = 0;
                    }
                    if (inst == 0) firstInstStageBit = effStageBit;
                    std::string entryName = block.name;
                    if (isArray) {
                        entryName += "[" + std::to_string(inst) + "]";
                    }
                    auto existing = std::find_if(
                        programObject->resourceUniformBlocks.begin(),
                        programObject->resourceUniformBlocks.end(),
                        [&](const GLProgramResourceEntry& e) { return e.name == entryName; });
                    if (existing != programObject->resourceUniformBlocks.end()) {
                        existing->referencedBy |= effStageBit;
                        if (inst == 0) {
                            firstBlockIndex = static_cast<GLint>(
                                existing - programObject->resourceUniformBlocks.begin());
                        }
                        continue;
                    }
                    anyNewBlocks = true;
                    GLProgramResourceEntry blockEntry;
                    blockEntry.name = entryName;
                    blockEntry.type = 0;  // blocks have no scalar type
                    // Sprint 8 B Cluster F F1 Day 2 (CKPT74):
                    // explicit-binding block arrays consume consecutive
                    // binding slots (b[0]=N, b[1]=N+1, ...). Implicit-
                    // binding (no layout(binding=N)) defaults to 0 for
                    // ALL instances. CTS layout_binding.block_layout_
                    // binding_block.binding_array_size hits this:
                    //   `layout(binding=81) uniform B { ... } b[2];`
                    //   expects b[0]=81, b[1]=82.
                    GLint instanceBinding = static_cast<GLint>(block.glBinding);
                    if (block.hasExplicitBinding && isArray) {
                        instanceBinding += inst;
                    }
                    blockEntry.location = instanceBinding;
                    blockEntry.offset = static_cast<GLint>(block.byteSize); // GL_UNIFORM_BLOCK_DATA_SIZE
                    blockEntry.arraySize = 1;
                    blockEntry.referencedBy = effStageBit;
                    programObject->resourceUniformBlocks.push_back(std::move(blockEntry));
                    if (inst == 0) {
                        firstBlockIndex = static_cast<GLint>(
                            programObject->resourceUniformBlocks.size() - 1);
                    }
                }

                // Skip member creation if this block was already processed
                // by an earlier stage (all entries deduped — no new blocks).
                if (!anyNewBlocks) continue;

                for (const auto& member : block.members) {
                    // Push into resourceUniforms — the CTS and
                    // glGetActiveUniform / glGetActiveUniformsiv enumerate
                    // ALL active uniforms including those inside blocks.
                    // Per GL spec §7.6, blocks WITHOUT an instance name use
                    // just "memberName"; blocks WITH one use "blockName.memberName".
                    GLProgramResourceEntry memberEntry;
                    std::string uniformName;
                    if (hasInstance) {
                        uniformName = block.name + "." + member.name;
                    } else {
                        uniformName = member.name;
                    }
                    // GL spec: array uniforms have "[0]" appended
                    // to name. Use `isArray` so even sized arrays
                    // with arraySize=1 pick up the suffix.
                    if (member.isArray) {
                        uniformName += "[0]";
                    }
                    memberEntry.name = std::move(uniformName);
                    memberEntry.type = member.type;
                    // SPIR-V represents bool in UBOs as uint — detect the
                    // original bool type from the GLSL source.
                    if (member.type == GL_UNSIGNED_INT ||
                        member.type == GL_UNSIGNED_INT_VEC2 ||
                        member.type == GL_UNSIGNED_INT_VEC3 ||
                        member.type == GL_UNSIGNED_INT_VEC4) {
                        GLenum boolType = detectBoolMemberType(
                            glslSource, block.name, member.name);
                        if (boolType != 0) {
                            memberEntry.type = boolType;
                        }
                    }
                    memberEntry.location = -1;  // not queryable via glGetUniformLocation
                    memberEntry.offset = static_cast<GLint>(member.offset);
                    // Keep SPIRV-Cross's raw arraySize (0 for
                    // non-arrays AND for unbounded arrays) and use
                    // the new `isArray` flag to distinguish them.
                    // getResourceProperty(GL_ARRAY_SIZE) reports 1
                    // for non-arrays, arraySize (maybe 0) for arrays.
                    memberEntry.arraySize = static_cast<GLint>(member.arraySize);
                    memberEntry.isArray = member.isArray;
                    memberEntry.blockIndex = firstBlockIndex;
                    // Members are indexed off the FIRST instance of a
                    // block array, so use that instance's effective
                    // stage bit (narrowed per-instance above).
                    memberEntry.referencedBy = firstInstStageBit;
                    memberEntry.isRowMajor = member.isRowMajor;
                    memberEntry.arrayStride = member.arrayStride;
                    memberEntry.matrixStride = member.matrixStride;
                    const GLint newUniformIndex =
                        static_cast<GLint>(programObject->resourceUniforms.size());
                    programObject->resourceUniforms.push_back(std::move(memberEntry));

                    // Record the member's index on the first-instance
                    // block entry so GL_NUM_ACTIVE_VARIABLES and
                    // GL_ACTIVE_VARIABLES queries on the UBO return
                    // this member list. SSBO path already does this
                    // (mergeStorageBlocks below); UBO path was missing it.
                    // CTS `program_interface_query.uniform-block-types`
                    // queries ACTIVE_VARIABLES on every UB entry.
                    if (firstBlockIndex >= 0 &&
                        static_cast<std::size_t>(firstBlockIndex) <
                            programObject->resourceUniformBlocks.size()) {
                        auto& blockEntry =
                            programObject->resourceUniformBlocks[firstBlockIndex];
                        if (std::find(blockEntry.activeVariables.begin(),
                                      blockEntry.activeVariables.end(),
                                      newUniformIndex) == blockEntry.activeVariables.end()) {
                            blockEntry.activeVariables.push_back(newUniformIndex);
                        }
                    }

                    // Also push into resourceBufferVariables for
                    // glGetProgramResourceiv(GL_BUFFER_VARIABLE, ...).
                    // NOTE: This is from a UBO merge — UBO members
                    // are technically not "buffer variables" (that's
                    // the SSBO-only interface per GL 4.6 §7.3.1.1).
                    // The push is preserved for backward compat with
                    // any caller that queries UBO members via the
                    // buffer-variable interface, but the GL spec
                    // separates them. When we see a real regression
                    // because of this overlap, drop it.
                    GLProgramResourceEntry bvEntry;
                    bvEntry.name = block.name + "." + member.name;
                    bvEntry.type = member.type;
                    bvEntry.location = -1;
                    bvEntry.offset = static_cast<GLint>(member.offset);
                    bvEntry.blockIndex = firstBlockIndex;
                    bvEntry.referencedBy = firstInstStageBit;
                    programObject->resourceBufferVariables.push_back(std::move(bvEntry));
                }
            }
        };
        static const std::string emptySource;
        const std::string& vsSrc = vertexShader ? vertexShader->source : emptySource;
        const std::string& fsSrc = fragmentShader ? fragmentShader->source : emptySource;
        const std::string& gsSrc = geometryShader ? geometryShader->source : emptySource;
        const std::string& csSrc = computeShader ? computeShader->source : emptySource;
        mergeBlocks(programObject->vertexReflection.uniformBlocks, 0x01, vsSrc);    // vertex
        mergeBlocks(programObject->fragmentReflection.uniformBlocks, 0x02, fsSrc);  // fragment
        // GS uniform blocks — SPIRV-Cross reflection captured from
        // translateCachedStage("geometry") above. Usage-based, so a
        // block declared in the GS source but never accessed in the
        // GS body won't appear and won't set the 0x04 bit. CTS
        // `program_resource.program_resource` needs this for
        // `uni_colors` (expected TRUE: GS reads uni_colors.red) vs
        // `uni_matrices` (expected FALSE: declared but unused).
        mergeBlocks(programObject->geometryReflection.uniformBlocks, 0x04, gsSrc);  // geometry
        // Tess stages — same gap as supplementFromReflection above:
        // TCS uniform_block resources need to flow through this merge
        // path so glGetProgramResourceIndex(po, GL_UNIFORM_BLOCK,
        // "tc_uniform_block1") finds them.
        const std::string& ubTcsSrc = tessControlShader ? tessControlShader->source : "";
        const std::string& ubTesSrc = tessEvalShader ? tessEvalShader->source : "";
        mergeBlocks(programObject->tessControlReflection.uniformBlocks, 0x08, ubTcsSrc);
        mergeBlocks(programObject->tessEvalAsComputeReflection.uniformBlocks, 0x10, ubTesSrc);
        // Compute UBOs — CTS `compute_shader.resource-ubo` declares
        // `uniform InputBuffer { … } g_in_buffer[12];` and queries
        // `glGetUniformBlockIndex("InputBuffer[0]")` + expects
        // `GL_UNIFORM_BLOCK_REFERENCED_BY_COMPUTE_SHADER = TRUE`.
        mergeBlocks(programObject->computeReflection.uniformBlocks, 0x20, csSrc);   // compute

        // Build resourceStorageBlocks from each stage's SSBO reflection so
        // glShaderStorageBlockBinding can look up a block by index and
        // update its effective binding. Dedup by name (an SSBO declared
        // in both VS and FS produces a single resource entry whose
        // `referencedBy` bits OR the stage flags). `location` starts at
        // the shader's `layout(binding=N)` value and is later overwritten
        // by glShaderStorageBlockBinding(program, index, newBinding);
        // resolveSSBOBindings consults this field as the authoritative
        // effective binding for each draw/dispatch. Without this list
        // glShaderStorageBlockBinding hits the range check in
        // shaderStorageBlockBinding() and silently drops the remap.
        auto mergeStorageBlocks = [&](const std::vector<ShaderReflection::ResourceBinding>& blocks,
                                       GLbitfield stageBit,
                                       const std::string& glslSource) {
            for (const auto& block : blocks) {
                // Track the per-stage referenced bit ONLY when the
                // block is live in this stage's SPIR-V — a declared-
                // but-unused SSBO still appears as a resource but
                // mustn't contribute the stage's bit. CTS
                // `program_resource.program_resource` expects
                // `Ids` (GS-declared, GS-unused) to have
                // GL_REFERENCED_BY_GEOMETRY_SHADER = FALSE.
                const GLbitfield blockStageBit = block.active ? stageBit : 0;
                const bool hasInstance =
                    glslBlockHasInstanceName(glslSource, block.name);
                const std::string instanceName = hasInstance
                    ? glslBlockInstanceName(glslSource, block.name)
                    : std::string();
                const std::set<int> usedInstanceIndices =
                    !instanceName.empty()
                        ? glslActiveInstanceIndices(glslSource, instanceName)
                        : std::set<int>();
                const bool useInstanceNarrowing = !usedInstanceIndices.empty();

                const int numInstances = (block.blockArraySize > 0)
                    ? static_cast<int>(block.blockArraySize) : 1;
                const bool isBlockArray = (block.blockArraySize > 0);

                // Create one block entry per array instance. For
                // non-array blocks, numInstances=1 and we keep the
                // plain name. CTS `ssb-types` declares
                // `TrickyBuffer ... } e[2];` and asserts both
                // `TrickyBuffer[0]` and `TrickyBuffer[1]` appear
                // in GL_SHADER_STORAGE_BLOCK.
                GLint firstBlockIdx = -1;
                GLbitfield firstInstStageBit = blockStageBit;
                bool anyNew = false;
                for (int inst = 0; inst < numInstances; ++inst) {
                    GLbitfield effStageBit = blockStageBit;
                    if (useInstanceNarrowing &&
                        usedInstanceIndices.count(inst) == 0) {
                        effStageBit = 0;
                    }
                    if (inst == 0) firstInstStageBit = effStageBit;
                    std::string entryName = block.name;
                    if (isBlockArray) {
                        entryName += "[" + std::to_string(inst) + "]";
                    }
                    auto existing = std::find_if(
                        programObject->resourceStorageBlocks.begin(),
                        programObject->resourceStorageBlocks.end(),
                        [&](const GLProgramResourceEntry& e) { return e.name == entryName; });
                    if (existing != programObject->resourceStorageBlocks.end()) {
                        existing->referencedBy |= effStageBit;
                        if (inst == 0) {
                            firstBlockIdx = static_cast<GLint>(
                                existing - programObject->resourceStorageBlocks.begin());
                        }
                        continue;
                    }
                    anyNew = true;
                    GLProgramResourceEntry entry;
                    entry.name = std::move(entryName);
                    entry.type = 0;
                    // Sprint 8 B Cluster F F1 Day 2 (CKPT74): same
                    // explicit-binding gate as UBO above. Pre-CKPT74
                    // the SSBO path UNCONDITIONALLY added `inst`,
                    // which is correct for explicit binding (b[i]=N+i)
                    // but wrong for implicit (all default to 0).
                    GLint instanceBinding = static_cast<GLint>(block.glBinding);
                    if (block.hasExplicitBinding && isBlockArray) {
                        instanceBinding += inst;
                    }
                    entry.location = instanceBinding;
                    entry.offset = static_cast<GLint>(block.byteSize);
                    entry.arraySize = 1;
                    entry.referencedBy = effStageBit;
                    programObject->resourceStorageBlocks.push_back(std::move(entry));
                    if (inst == 0) {
                        firstBlockIdx = static_cast<GLint>(
                            programObject->resourceStorageBlocks.size() - 1);
                    }
                }
                // Member-level merge runs every stage, even when the
                // block itself was registered by an earlier stage.
                // CTS `geometry_shader.program_resource` declares
                // `Positions` in both VS (writes) and GS (reads) —
                // the VS pass creates `Positions.position[0]` with
                // refby=0x01; the GS pass must still OR in 0x04 on
                // that existing entry so
                // GL_REFERENCED_BY_GEOMETRY_SHADER reports TRUE.
                (void)anyNew;

                // Populate buffer-variable entries for each SSBO member
                // so glGetProgramResourceiv(GL_BUFFER_VARIABLE, ...) can
                // find "BlockName.memberName" — per GL 4.6 §7.3.1.1 the
                // buffer-variable interface enumerates active SSBO
                // members. Names are prefixed with the block TYPE name
                // when the block declaration has an instance name
                // (`} e[2];` or `} d;`); otherwise bare member names.
                for (const auto& member : block.members) {
                    std::string bvName = hasInstance
                        ? (block.name + "." + member.name)
                        : member.name;
                    // GL 4.6 §7.3.1: array members (including
                    // unbounded `data[]` in SSBOs) get the "[0]"
                    // suffix. `member.isArray` covers both sized
                    // and unsized cases — `arraySize > 0` alone
                    // misses unbounded arrays.
                    if (member.isArray) bvName += "[0]";
                    auto bvIt = std::find_if(
                        programObject->resourceBufferVariables.begin(),
                        programObject->resourceBufferVariables.end(),
                        [&](const GLProgramResourceEntry& e) { return e.name == bvName; });
                    GLint bvIndex = -1;
                    if (bvIt != programObject->resourceBufferVariables.end()) {
                        bvIt->referencedBy |= firstInstStageBit;
                        bvIndex = static_cast<GLint>(bvIt - programObject->resourceBufferVariables.begin());
                    } else {
                        GLProgramResourceEntry bv;
                        bv.name = std::move(bvName);
                        bv.type = member.type;
                        bv.location = -1;
                        bv.offset = static_cast<GLint>(member.offset);
                        bv.arraySize = static_cast<GLint>(member.arraySize);
                        bv.isArray = member.isArray;
                        bv.blockIndex = firstBlockIdx;
                        bv.referencedBy = firstInstStageBit;
                        bv.isRowMajor = member.isRowMajor;
                        bv.arrayStride = member.arrayStride;
                        bv.matrixStride = member.matrixStride;
                        bv.topLevelArraySize = member.topLevelArraySize;
                        bv.topLevelArrayStride = member.topLevelArrayStride;
                        programObject->resourceBufferVariables.push_back(std::move(bv));
                        bvIndex = static_cast<GLint>(programObject->resourceBufferVariables.size() - 1);
                    }
                    // Record the member's index in the containing
                    // block's active-variables list so
                    // GL_NUM_ACTIVE_VARIABLES / GL_ACTIVE_VARIABLES
                    // queries on the block return the right data.
                    if (firstBlockIdx >= 0
                        && static_cast<std::size_t>(firstBlockIdx) < programObject->resourceStorageBlocks.size()) {
                        auto& blockEntry = programObject->resourceStorageBlocks[firstBlockIdx];
                        // De-dupe in case the same block gets
                        // merged from multiple stages.
                        if (std::find(blockEntry.activeVariables.begin(),
                                      blockEntry.activeVariables.end(),
                                      bvIndex) == blockEntry.activeVariables.end()) {
                            blockEntry.activeVariables.push_back(bvIndex);
                        }
                    }
                }
            }
        };
        static const std::string ssboEmptySrc;
        const std::string& ssboVsSrc = vertexShader ? vertexShader->source : ssboEmptySrc;
        const std::string& ssboFsSrc = fragmentShader ? fragmentShader->source : ssboEmptySrc;
        const std::string& ssboGsSrc = geometryShader ? geometryShader->source : ssboEmptySrc;
        const std::string& ssboCsSrc = computeShader ? computeShader->source : ssboEmptySrc;
        mergeStorageBlocks(programObject->vertexReflection.storageBuffers, 0x01, ssboVsSrc);
        mergeStorageBlocks(programObject->fragmentReflection.storageBuffers, 0x02, ssboFsSrc);
        mergeStorageBlocks(programObject->geometryReflection.storageBuffers, 0x04, ssboGsSrc);
        mergeStorageBlocks(programObject->computeReflection.storageBuffers, 0x20, ssboCsSrc);
        // Tess stages — symmetric to mergeBlocks above. TCS/TES SSBO
        // resources need this path so glGetProgramResourceIndex(po,
        // GL_SHADER_STORAGE_BLOCK, "tc_shader_storage_block1") finds
        // them.
        const std::string& ssboTcsSrc = tessControlShader ? tessControlShader->source : ssboEmptySrc;
        const std::string& ssboTesSrc = tessEvalShader ? tessEvalShader->source : ssboEmptySrc;
        mergeStorageBlocks(programObject->tessControlReflection.storageBuffers, 0x08, ssboTcsSrc);
        mergeStorageBlocks(programObject->tessEvalAsComputeReflection.storageBuffers, 0x10, ssboTesSrc);

        // GS reflection: the geometry shader is CPU-emulated — we
        // don't yet run SPIRV-Cross on it to produce a MSL
        // reflection struct, so block-scoped resources (uniform
        // blocks, SSBOs, buffer variables) can't yet tell us
        // "does the GS use this block". Scalar uniforms are
        // already handled via the per-stage scanner's
        // `declaredUniforms` (see computeStageMask above), which
        // gives us an accurate GEOMETRY_SHADER bit for those.
        // Block-scoped REFERENCED_BY_GEOMETRY_SHADER queries stay
        // conservative until GS reflection lands — the CTS
        // program_resource test carries that on the backlog.

        // Post-pass: fix any remaining uint→bool member types that weren't
        // detected during the stage that first created the members. This
        // happens when a linked SPIR-V includes a block in both stages but
        // the block is only declared in one stage's GLSL source.
        for (auto& u : programObject->resourceUniforms) {
            if (u.blockIndex < 0) continue;
            if (u.type != GL_UNSIGNED_INT && u.type != GL_UNSIGNED_INT_VEC2 &&
                u.type != GL_UNSIGNED_INT_VEC3 && u.type != GL_UNSIGNED_INT_VEC4) continue;
            // Find the block name for this uniform.
            const auto& blockEntry = programObject->resourceUniformBlocks[u.blockIndex];
            // Strip array suffix from block name for detection.
            std::string baseName = blockEntry.name;
            auto bracket = baseName.find('[');
            if (bracket != std::string::npos) baseName = baseName.substr(0, bracket);
            // Extract member name: for instanced blocks "Block.member" → "member",
            // for non-instanced blocks "member" stays as is.
            std::string memberName = u.name;
            // Strip trailing "[0]" from arrays
            if (memberName.size() > 3 && memberName.substr(memberName.size()-3) == "[0]") {
                memberName = memberName.substr(0, memberName.size()-3);
            }
            // For instanced blocks, strip "BlockName." prefix
            std::string prefix = baseName + ".";
            if (memberName.size() > prefix.size() &&
                memberName.substr(0, prefix.size()) == prefix) {
                memberName = memberName.substr(prefix.size());
            }
            // Try both VS and FS sources.
            GLenum boolType = detectBoolMemberType(vsSrc, baseName, memberName);
            if (boolType == 0) {
                boolType = detectBoolMemberType(fsSrc, baseName, memberName);
            }
            if (boolType != 0) {
                u.type = boolType;
            }
        }
    }

    return true;
}

bool GLContext::useProgram(GLuint program) {
    if (program != 0) {
        GLProgramObject* object = impl_->objects->programs().get(program);
        if (object == nullptr) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        if (!object->linked) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    // Sprint 9 Phase 1 (CKPT101): GL 4.6 §13.2.2 — UseProgram must
    // generate INVALID_OPERATION when transform feedback is active and
    // not paused on the currently-bound TF object. CTS
    // `transform_feedback.api_errors_test` plants beginTransformFeedback
    // then calls useProgram(0) and asserts the error is generated.
    const bool tfActive = isTransformFeedbackActive();
    const bool tfPaused = impl_->isTfPausedOnBoundImpl();
    if (tfActive && !tfPaused) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §7.3 deferred-delete protocol: if the outgoing current
    // program was already flagged deleteRequested by a prior
    // glDeleteProgram, this is the moment it actually gets erased —
    // "no longer part of any context's current state" is satisfied by
    // the upcoming state->useProgram() call. See deleteProgram for
    // the rationale. Skip when the outgoing program is the same as
    // the incoming program (redundant glUseProgram(N)→glUseProgram(N)).
    const GLuint outgoing = impl_->state->currentProgram();
    if (outgoing != 0 && outgoing != program) {
        GLProgramObject* outgoingObj = impl_->objects->programs().get(outgoing);
        if (outgoingObj != nullptr && outgoingObj->deleteRequested) {
            std::vector<GLuint> attached = outgoingObj->attachedShaders;
            for (GLuint shaderId : attached) {
                GLShaderObject* shaderObject = impl_->objects->shaders().get(shaderId);
                if (shaderObject == nullptr) {
                    continue;
                }
                if (shaderObject->attachmentCount > 0) {
                    --shaderObject->attachmentCount;
                }
                if (shaderObject->deleteRequested && shaderObject->attachmentCount == 0) {
                    impl_->objects->shaders().erase(shaderId);
                }
            }
            impl_->objects->programs().erase(outgoing);
        }
    }
    impl_->state->useProgram(program);
    return true;
}

bool GLContext::validateProgram(GLuint program) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    object->validated = object->linked;
    object->validateLog = object->linked ? "validation passed" : "program is not linked";
    return object->validated;
}

bool GLContext::getProgramiv(GLuint program, GLenum pname, GLint* params) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    switch (pname) {
        case GL_DELETE_STATUS:
            *params = object->deleteRequested ? GL_TRUE : GL_FALSE;
            return true;
        case GL_LINK_STATUS:
            *params = object->linked ? GL_TRUE : GL_FALSE;
            return true;
        case 0x91B1:   // GL_COMPLETION_STATUS_KHR / _ARB
            // Synchronous link — always complete post-glLinkProgram.
            // See matching case in getShaderiv for rationale.
            *params = GL_TRUE;
            return true;
        case GL_VALIDATE_STATUS:
            *params = object->validated ? GL_TRUE : GL_FALSE;
            return true;
        case GL_INFO_LOG_LENGTH: {
            const std::string& log = object->validateLog.empty() ? object->linkLog : object->validateLog;
            *params = static_cast<GLint>(log.size() + (log.empty() ? 0 : 1));
            return true;
        }
        case GL_ATTACHED_SHADERS:
            *params = static_cast<GLint>(object->attachedShaders.size());
            return true;
        case GL_ACTIVE_UNIFORMS:
            // GL spec: includes ALL active uniforms (bare + in-block).
            // resourceUniforms holds both; uniforms only holds bare ones.
            *params = static_cast<GLint>(
                object->resourceUniforms.empty()
                    ? object->uniforms.size()
                    : object->resourceUniforms.size());
            return true;
        case GL_ACTIVE_UNIFORM_MAX_LENGTH: {
            std::size_t maxLen = 0;
            if (!object->resourceUniforms.empty()) {
                for (const auto& u : object->resourceUniforms) {
                    maxLen = std::max(maxLen, u.name.size() + 1);
                }
            } else {
                for (const auto& u : object->uniforms) {
                    maxLen = std::max(maxLen, u.name.size() + 1);
                }
            }
            *params = static_cast<GLint>(maxLen);
            return true;
        }
        case GL_ACTIVE_ATTRIBUTES:
            *params = static_cast<GLint>(object->attributes.size());
            return true;
        case GL_ACTIVE_ATTRIBUTE_MAX_LENGTH: {
            std::size_t maxLen = 0;
            for (const auto& a : object->attributes) {
                maxLen = std::max(maxLen, a.name.size() + 1);
            }
            *params = static_cast<GLint>(maxLen);
            return true;
        }
        // Tessellation program queries (GL 4.0).
        case GL_TESS_CONTROL_OUTPUT_VERTICES:
            *params = object->tessControlOutputVertices;
            return true;
        case GL_TESS_GEN_MODE:
            *params = static_cast<GLint>(object->tessGenMode);
            return true;
        case GL_TESS_GEN_SPACING:
            *params = static_cast<GLint>(object->tessGenSpacing);
            return true;
        case GL_TESS_GEN_VERTEX_ORDER:
            *params = static_cast<GLint>(object->tessGenVertexOrder);
            return true;
        case GL_TESS_GEN_POINT_MODE:
            *params = static_cast<GLint>(object->tessGenPointMode);
            return true;
        // Uniform block queries (GL 3.1+)
        case GL_ACTIVE_UNIFORM_BLOCKS:
            *params = static_cast<GLint>(object->resourceUniformBlocks.size());
            return true;
        case GL_ACTIVE_UNIFORM_BLOCK_MAX_NAME_LENGTH: {
            std::size_t maxLen = 0;
            for (const auto& block : object->resourceUniformBlocks) {
                maxLen = std::max(maxLen, block.name.size() + 1);
            }
            *params = static_cast<GLint>(maxLen);
            return true;
        }
        // Compute shader queries (GL 4.3+)
        case GL_COMPUTE_WORK_GROUP_SIZE: {
            // GL 4.6 §7.13: INVALID_OPERATION if the program has not
            // been linked successfully, or has been linked but
            // contains no compute shader. Checked by
            // KHR-GL46.compute_shader.api-program. Otherwise returns
            // the shader's local_size_{x,y,z} as declared by the
            // `layout(local_size_x = N) in;` execution mode, populated
            // at link time via extractComputeModes.
            bool hasComputeStage = false;
            for (GLuint shaderId : object->attachedShaders) {
                const GLShaderObject* sh = impl_->objects->shaders().get(shaderId);
                if (sh != nullptr && sh->stage == GL_COMPUTE_SHADER) {
                    hasComputeStage = true;
                    break;
                }
            }
            if (!object->linked || !hasComputeStage) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            params[0] = static_cast<GLint>(object->computeLocalSizeX);
            params[1] = static_cast<GLint>(object->computeLocalSizeY);
            params[2] = static_cast<GLint>(object->computeLocalSizeZ);
            return true;
        }
        // Transform feedback queries (GL 3.0+)
        case GL_TRANSFORM_FEEDBACK_BUFFER_MODE:
            *params = static_cast<GLint>(object->transformFeedbackBufferMode);
            return true;
        case GL_TRANSFORM_FEEDBACK_VARYINGS:
            *params = static_cast<GLint>(object->transformFeedbackVaryingNames.size());
            return true;
        case GL_TRANSFORM_FEEDBACK_VARYING_MAX_LENGTH: {
            std::size_t maxLen = 0;
            for (const auto& v : object->transformFeedbackVaryingNames) {
                maxLen = std::max(maxLen, v.size() + 1);
            }
            *params = static_cast<GLint>(maxLen);
            return true;
        }
        // Geometry shader queries (GL 3.2+). GL 4.6 §7.13 "Program
        // Queries": GL_GEOMETRY_* pnames generate GL_INVALID_OPERATION
        // when the program has not been successfully linked with a
        // geometry shader stage. `gsPresent` is populated at link
        // time by `detectGeometryEmulatable` — it's true whenever the
        // linked program contains a GS, independent of whether the
        // CPU emulator can handle the shader body.
        case GL_GEOMETRY_VERTICES_OUT:
            if (!object->linked || !object->gsPresent) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            *params = static_cast<GLint>(object->gsMaxVertices);
            return true;
        case GL_GEOMETRY_INPUT_TYPE:
            if (!object->linked || !object->gsPresent) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            *params = static_cast<GLint>(object->gsInputTopology);
            return true;
        case GL_GEOMETRY_OUTPUT_TYPE:
            if (!object->linked || !object->gsPresent) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            *params = static_cast<GLint>(object->gsOutputTopology);
            return true;
        case GL_GEOMETRY_SHADER_INVOCATIONS:
            if (!object->linked || !object->gsPresent) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            *params = static_cast<GLint>(object->gsInvocations);
            return true;
        // Program binary / separable (GL 4.1+)
        case GL_PROGRAM_BINARY_LENGTH:
            *params = 0;  // No binary program support
            return true;
        case GL_PROGRAM_SEPARABLE:
            // Query returns the LINK-TIME snapshot, not the request
            // parameter. Before any successful link, this is FALSE
            // regardless of glProgramParameteri calls.
            *params = object->separableLinked ? GL_TRUE : GL_FALSE;
            return true;
        case GL_PROGRAM_BINARY_RETRIEVABLE_HINT:
            *params = GL_FALSE;
            return true;
        // Atomic counter buffers (GL 4.2+)
        case GL_ACTIVE_ATOMIC_COUNTER_BUFFERS:
            *params = static_cast<GLint>(object->resourceAtomicCounterBuffers.size());
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getProgramInfoLog(GLuint program, GLsizei bufSize, GLsizei* length, GLchar* infoLog) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const std::string& log = object->validateLog.empty() ? object->linkLog : object->validateLog;
    copyStringToBuffer(log, bufSize, length, infoLog);
    return true;
}

bool GLContext::getAttachedShaders(GLuint program, GLsizei maxCount, GLsizei* count, GLuint* shaders) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLsizei n = std::min<GLsizei>(maxCount, static_cast<GLsizei>(object->attachedShaders.size()));
    if (shaders != nullptr) {
        for (GLsizei i = 0; i < n; ++i) {
            shaders[i] = object->attachedShaders[static_cast<std::size_t>(i)];
        }
    }
    if (count != nullptr) {
        *count = n;
    }
    return true;
}

bool GLContext::bindAttribLocation(GLuint program, GLuint index, const GLchar* name) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr || name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    object->requestedAttribLocations[std::string(name)] = index;
    return true;
}

GLint GLContext::getAttribLocation(GLuint program, const GLchar* name) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr || name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return -1;
    }
    if (!object->linked) {
        pushError(GL_INVALID_OPERATION);
        return -1;
    }
    const std::string lookup = name;
    // GL 4.6 §7.3.1: if name includes `[N]` suffix, return base attribute's
    // location + N. Shaders can declare `in float clipdistance_data[8]` and
    // CTS looks up `clipdistance_data[0]` through `clipdistance_data[7]`
    // expecting consecutive locations — our reflection only records the
    // array's base name, so we need to parse the suffix and do the math.
    std::string baseName = lookup;
    int arrayIndex = 0;
    if (!lookup.empty() && lookup.back() == ']') {
        const auto bracketPos = lookup.rfind('[');
        if (bracketPos != std::string::npos) {
            const std::string idxStr = lookup.substr(bracketPos + 1,
                lookup.size() - bracketPos - 2);
            // Accept only non-negative decimal integers.
            bool ok = !idxStr.empty();
            for (char c : idxStr) {
                if (c < '0' || c > '9') { ok = false; break; }
            }
            if (ok) {
                arrayIndex = std::atoi(idxStr.c_str());
                baseName = lookup.substr(0, bracketPos);
            }
        }
    }
    for (const auto& attrib : object->attributes) {
        if (attrib.name == lookup) {
            return attrib.location;
        }
        if (attrib.name == baseName) {
            return attrib.location + arrayIndex;
        }
    }
    return -1;
}

bool GLContext::getActiveAttrib(GLuint program, GLuint index, GLsizei bufSize, GLsizei* length, GLint* size, GLenum* type, GLchar* name) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (index >= object->attributes.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const auto& attrib = object->attributes[index];
    if (size != nullptr) {
        *size = 1;
    }
    if (type != nullptr) {
        *type = attrib.type;
    }
    copyStringToBuffer(attrib.name, bufSize, length, name);
    return true;
}

GLint GLContext::getUniformLocation(GLuint program, const GLchar* name) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr || name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return -1;
    }
    if (!object->linked) {
        pushError(GL_INVALID_OPERATION);
        return -1;
    }
    const std::string lookup = name;
    for (const auto& uniform : object->uniforms) {
        if (uniform.name == lookup) {
            return uniform.location;
        }
    }
    // GL 4.6 §7.6.1: array-element lookup — `glGetUniformLocation(prog,
    // "u[k]")` for a uniform declared `uniform T u[N]` must return
    // `location(u) + k` when 0 <= k < N. Uniforms are stored by base name
    // ("u"), so the exact-match loop above misses. Parse the trailing
    // [k] subscript and index into the base.
    //
    // Use `rfind('[')` not `find('[')` so deeply-nested names like
    // `l[2].b[1].d[0]` split as base=`l[2].b[1].d`, idx=0 — not
    // base=`l`, idx=`2].b[1].d[0`. CTS
    // `program_interface_query.uniform-types` declares
    // `uniform UU l[3]` where UU contains `U b[2]` containing
    // `float d[2]`, and asserts
    // glGetUniformLocation("l[2].b[1].d[0]") finds the terminal leaf.
    //
    // Covers KHR-GL46.explicit_uniform_location.uniform-loc-arrays-*
    // which exercise `layout(location = N) uniform T arr[M]` and expect
    // u[0]=N, u[1]=N+1, …, u[M-1]=N+M-1.
    const auto openBracket = lookup.rfind('[');
    if (openBracket != std::string::npos && lookup.back() == ']') {
        const std::string baseName = lookup.substr(0, openBracket);
        const std::string indexStr = lookup.substr(openBracket + 1, lookup.size() - openBracket - 2);
        if (!baseName.empty() && !indexStr.empty()) {
            // Parse the subscript (decimal only; GLSL array subscripts are plain ints).
            char* endp = nullptr;
            const long idx = std::strtol(indexStr.c_str(), &endp, 10);
            if (endp && *endp == '\0' && idx >= 0) {
                for (const auto& uniform : object->uniforms) {
                    if (uniform.name == baseName && uniform.arraySize >= 1
                        && idx < static_cast<long>(uniform.arraySize)
                        && uniform.location >= 0) {
                        return uniform.location + static_cast<GLint>(idx);
                    }
                }
            }
        }
    }
    // Fallback: try with _appgl_ prefix reverse-mapping.
    // CompatShaderRewrite renames `sampler` → `_appgl_sampler` for glslang
    // compat; try the rewritten name if the original wasn't found.
    {
        std::string rewritten = lookup;
        const std::string from = "sampler";
        const std::string to = "_appgl_sampler";
        std::string::size_type pos = 0;
        bool changed = false;
        while ((pos = rewritten.find(from, pos)) != std::string::npos) {
            // Word-boundary check: don't replace inside sampler2D etc.
            bool leftOk = (pos == 0) || (!std::isalnum(static_cast<unsigned char>(rewritten[pos - 1])) && rewritten[pos - 1] != '_');
            std::size_t end = pos + from.size();
            bool rightOk = (end >= rewritten.size()) || (!std::isalnum(static_cast<unsigned char>(rewritten[end])) && rewritten[end] != '_');
            if (leftOk && rightOk) {
                rewritten.replace(pos, from.size(), to);
                pos += to.size();
                changed = true;
            } else {
                pos += 1;
            }
        }
        if (changed) {
            // Pass 1: exact match on rewritten name.
            for (const auto& uniform : object->uniforms) {
                if (uniform.name == rewritten) {
                    return uniform.location;
                }
            }
            // Pass 2: array-element subscript lookup on the rewritten name.
            // Mirrors the non-rewritten `lookup[k]` → `base + k` path above.
            // Needed when CTS asks for `sampler[0]` on a uniform declared
            // `uniform usampler2D sampler[N]` — `sampler` is a Metal reserved
            // word, CompatShaderRewrite renamed it to `_appgl_sampler`, so
            // the base-name subscript loop at the top of this function only
            // searches for base=`sampler` and finds nothing. The rewritten
            // form `_appgl_sampler[0]` matches base=`_appgl_sampler` here.
            const auto openBracketR = rewritten.rfind('[');
            if (openBracketR != std::string::npos && rewritten.back() == ']') {
                const std::string baseR = rewritten.substr(0, openBracketR);
                const std::string idxStrR = rewritten.substr(openBracketR + 1, rewritten.size() - openBracketR - 2);
                if (!baseR.empty() && !idxStrR.empty()) {
                    char* endpR = nullptr;
                    const long idxR = std::strtol(idxStrR.c_str(), &endpR, 10);
                    if (endpR && *endpR == '\0' && idxR >= 0) {
                        for (const auto& uniform : object->uniforms) {
                            if (uniform.name == baseR && uniform.arraySize >= 1
                                && idxR < static_cast<long>(uniform.arraySize)
                                && uniform.location >= 0) {
                                return uniform.location + static_cast<GLint>(idxR);
                            }
                        }
                    }
                }
            }
        }
    }
    return -1;
}

bool GLContext::getActiveUniform(GLuint program, GLuint index, GLsizei bufSize, GLsizei* length, GLint* size, GLenum* type, GLchar* name) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Prefer resourceUniforms (includes UBO members); fall back to bare
    // uniforms list for programs that never went through SPIRV-Cross.
    if (!object->resourceUniforms.empty()) {
        if (index >= static_cast<GLuint>(object->resourceUniforms.size())) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        const auto& u = object->resourceUniforms[index];
        if (size != nullptr) {
            *size = std::max<GLint>(u.arraySize, 1);
        }
        if (type != nullptr) {
            *type = u.type;
        }
        copyStringToBuffer(u.name, bufSize, length, name);
        return true;
    }
    if (index >= object->uniforms.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const auto& uniform = object->uniforms[index];
    if (size != nullptr) {
        *size = std::max<GLint>(uniform.arraySize, 1);
    }
    if (type != nullptr) {
        *type = uniform.type;
    }
    copyStringToBuffer(uniform.name, bufSize, length, name);
    return true;
}

namespace {

GLProgramUniformValue* lookupUniformValue(GLProgramObject* program, GLint location) {
    if (program == nullptr || location < 0) {
        return nullptr;
    }
    auto it = program->uniformValues.find(location);
    if (it != program->uniformValues.end()) {
        return &it->second;
    }
    // Array-element fallback: glUniform1i(loc+k, …) on a uniform declared
    // with arraySize > 1 hits locations [base+1, base+arraySize). The slot
    // lives at the base location; find it by walking the uniforms list.
    for (const auto& u : program->uniforms) {
        if (u.arraySize > 1 && location > u.location
            && location < u.location + u.arraySize) {
            auto base = program->uniformValues.find(u.location);
            if (base != program->uniformValues.end()) {
                return &base->second;
            }
            return nullptr;
        }
    }
    return nullptr;
}

// Resolve (slot, elementIndex) for a uniform location. elementIndex is the
// zero-based offset inside the array for array-element locations; 0 for the
// base location or a non-array uniform. Returns (nullptr, 0) if the location
// is invalid.
struct UniformSlotRef {
    GLProgramUniformValue* slot = nullptr;
    GLint elementIndex = 0;
    GLint arraySize = 1;
    GLenum type = 0;
};

UniformSlotRef resolveUniformSlot(GLProgramObject* program, GLint location) {
    UniformSlotRef r;
    if (program == nullptr || location < 0) {
        return r;
    }
    auto it = program->uniformValues.find(location);
    if (it != program->uniformValues.end()) {
        r.slot = &it->second;
        r.elementIndex = 0;
        r.arraySize = it->second.arraySize;
        r.type = it->second.type;
        return r;
    }
    for (const auto& u : program->uniforms) {
        if (u.arraySize > 1 && location > u.location
            && location < u.location + u.arraySize) {
            auto base = program->uniformValues.find(u.location);
            if (base != program->uniformValues.end()) {
                r.slot = &base->second;
                r.elementIndex = location - u.location;
                r.arraySize = u.arraySize;
                r.type = u.type;
            }
            return r;
        }
    }
    return r;
}

// Returns the number of scalar components a uniform of the given GLenum
// type contains (1 for scalar/sampler, 4 for vec4, 16 for mat4, etc.).
// Used by glGetUniform* to cap the memcpy at the real per-element width —
// without this, querying location+k of a sampler-array uniform would
// clobber the caller's single-int stack buffer (memcpy'd the full
// ints.size()). Observed as SIGSEGV in CTS layout_binding.sampler3D
// because the bumped per-stage tex cap made the test exercise a path
// that stressed the latent buffer overrun.
std::size_t uniformTypeComponentCount(GLenum type) {
    switch (type) {
        case GL_FLOAT_VEC2: case GL_INT_VEC2: case GL_UNSIGNED_INT_VEC2:
        case GL_BOOL_VEC2: case GL_DOUBLE_VEC2:
            return 2;
        case GL_FLOAT_VEC3: case GL_INT_VEC3: case GL_UNSIGNED_INT_VEC3:
        case GL_BOOL_VEC3: case GL_DOUBLE_VEC3:
            return 3;
        case GL_FLOAT_VEC4: case GL_INT_VEC4: case GL_UNSIGNED_INT_VEC4:
        case GL_BOOL_VEC4: case GL_DOUBLE_VEC4:
            return 4;
        case GL_FLOAT_MAT2: case GL_DOUBLE_MAT2:       return 4;
        case GL_FLOAT_MAT3: case GL_DOUBLE_MAT3:       return 9;
        case GL_FLOAT_MAT4: case GL_DOUBLE_MAT4:       return 16;
        case GL_FLOAT_MAT2x3: case GL_DOUBLE_MAT2x3:   return 6;
        case GL_FLOAT_MAT2x4: case GL_DOUBLE_MAT2x4:   return 8;
        case GL_FLOAT_MAT3x2: case GL_DOUBLE_MAT3x2:   return 6;
        case GL_FLOAT_MAT3x4: case GL_DOUBLE_MAT3x4:   return 12;
        case GL_FLOAT_MAT4x2: case GL_DOUBLE_MAT4x2:   return 8;
        case GL_FLOAT_MAT4x3: case GL_DOUBLE_MAT4x3:   return 12;
        default: return 1;  // scalars, samplers, images
    }
}

}  // namespace

bool GLContext::getUniformfv(GLuint program, GLint location, GLfloat* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §7.7: pass a shader handle → INVALID_OPERATION.
    if (impl_->objects->shaders().get(program) != nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* value = ref.slot;
    const std::size_t components = uniformTypeComponentCount(ref.type ? ref.type : value->type);
    const std::size_t offset = static_cast<std::size_t>(ref.elementIndex) * components;
    if (!value->floats.empty()) {
        const std::size_t avail = value->floats.size() > offset
            ? std::min(components, value->floats.size() - offset) : 0;
        if (avail > 0) {
            std::memcpy(params, value->floats.data() + offset, avail * sizeof(GLfloat));
        }
    } else if (!value->ints.empty()) {
        const std::size_t avail = value->ints.size() > offset
            ? std::min(components, value->ints.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLfloat>(value->ints[offset + i]);
        }
    } else if (!value->uints.empty()) {
        const std::size_t avail = value->uints.size() > offset
            ? std::min(components, value->uints.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLfloat>(value->uints[offset + i]);
        }
    }
    return true;
}

bool GLContext::getUniformiv(GLuint program, GLint location, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (impl_->objects->shaders().get(program) != nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* value = ref.slot;
    const std::size_t components = uniformTypeComponentCount(ref.type ? ref.type : value->type);
    const std::size_t offset = static_cast<std::size_t>(ref.elementIndex) * components;
    if (!value->ints.empty()) {
        const std::size_t avail = value->ints.size() > offset
            ? std::min(components, value->ints.size() - offset) : 0;
        if (avail > 0) {
            std::memcpy(params, value->ints.data() + offset, avail * sizeof(GLint));
        }
    } else if (!value->floats.empty()) {
        const std::size_t avail = value->floats.size() > offset
            ? std::min(components, value->floats.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLint>(value->floats[offset + i]);
        }
    } else if (!value->uints.empty()) {
        const std::size_t avail = value->uints.size() > offset
            ? std::min(components, value->uints.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLint>(value->uints[offset + i]);
        }
    }
    return true;
}

bool GLContext::getUniformuiv(GLuint program, GLint location, GLuint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (impl_->objects->shaders().get(program) != nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* value = ref.slot;
    const std::size_t components = uniformTypeComponentCount(ref.type ? ref.type : value->type);
    const std::size_t offset = static_cast<std::size_t>(ref.elementIndex) * components;
    if (!value->uints.empty()) {
        const std::size_t avail = value->uints.size() > offset
            ? std::min(components, value->uints.size() - offset) : 0;
        if (avail > 0) {
            std::memcpy(params, value->uints.data() + offset, avail * sizeof(GLuint));
        }
    } else if (!value->ints.empty()) {
        const std::size_t avail = value->ints.size() > offset
            ? std::min(components, value->ints.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLuint>(value->ints[offset + i]);
        }
    } else if (!value->floats.empty()) {
        const std::size_t avail = value->floats.size() > offset
            ? std::min(components, value->floats.size() - offset) : 0;
        for (std::size_t i = 0; i < avail; ++i) {
            params[i] = static_cast<GLuint>(value->floats[offset + i]);
        }
    }
    return true;
}

// GL 4.6 §7.6.1 — Sampler / image uniform validation shared by the
// in-context (glUniform*) and DSA (glProgramUniform*) paths.
// Returns `true` iff validation failed (caller should bail after
// pushError). `element` + `vectorSize` + first int slot of `values`
// are checked against the uniform's declared `utype`.
static bool sampleOrImageUniformValidationFailed(
    GLContext* ctx, GLenum utype, GLContext::UniformElementType element,
    GLint vectorSize, const void* values)
{
    auto isSamplerOrImage = [](GLenum t) {
        switch (t) {
            case GL_SAMPLER_1D: case GL_SAMPLER_2D: case GL_SAMPLER_3D:
            case GL_SAMPLER_CUBE: case GL_SAMPLER_1D_ARRAY:
            case GL_SAMPLER_2D_ARRAY: case GL_SAMPLER_1D_SHADOW:
            case GL_SAMPLER_2D_SHADOW: case GL_SAMPLER_1D_ARRAY_SHADOW:
            case GL_SAMPLER_2D_ARRAY_SHADOW: case GL_SAMPLER_CUBE_SHADOW:
            case GL_SAMPLER_2D_RECT: case GL_SAMPLER_2D_RECT_SHADOW:
            case GL_SAMPLER_BUFFER: case GL_SAMPLER_2D_MULTISAMPLE:
            case GL_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY_SHADOW:
            case GL_INT_SAMPLER_1D: case GL_INT_SAMPLER_2D:
            case GL_INT_SAMPLER_3D: case GL_INT_SAMPLER_CUBE:
            case GL_INT_SAMPLER_1D_ARRAY: case GL_INT_SAMPLER_2D_ARRAY:
            case GL_INT_SAMPLER_2D_RECT: case GL_INT_SAMPLER_BUFFER:
            case GL_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_1D:
            case GL_UNSIGNED_INT_SAMPLER_2D:
            case GL_UNSIGNED_INT_SAMPLER_3D:
            case GL_UNSIGNED_INT_SAMPLER_CUBE:
            case GL_UNSIGNED_INT_SAMPLER_1D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_RECT:
            case GL_UNSIGNED_INT_SAMPLER_BUFFER:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_IMAGE_1D: case GL_IMAGE_2D: case GL_IMAGE_3D:
            case GL_IMAGE_2D_RECT: case GL_IMAGE_CUBE:
            case GL_IMAGE_BUFFER: case GL_IMAGE_1D_ARRAY:
            case GL_IMAGE_2D_ARRAY: case GL_IMAGE_CUBE_MAP_ARRAY:
            case GL_IMAGE_2D_MULTISAMPLE:
            case GL_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_INT_IMAGE_1D: case GL_INT_IMAGE_2D:
            case GL_INT_IMAGE_3D: case GL_INT_IMAGE_2D_RECT:
            case GL_INT_IMAGE_CUBE: case GL_INT_IMAGE_BUFFER:
            case GL_INT_IMAGE_1D_ARRAY: case GL_INT_IMAGE_2D_ARRAY:
            case GL_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_INT_IMAGE_2D_MULTISAMPLE:
            case GL_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_1D:
            case GL_UNSIGNED_INT_IMAGE_2D:
            case GL_UNSIGNED_INT_IMAGE_3D:
            case GL_UNSIGNED_INT_IMAGE_2D_RECT:
            case GL_UNSIGNED_INT_IMAGE_CUBE:
            case GL_UNSIGNED_INT_IMAGE_BUFFER:
            case GL_UNSIGNED_INT_IMAGE_1D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
                return true;
            default:
                return false;
        }
    };
    if (!isSamplerOrImage(utype)) return false;
    if (element != GLContext::UniformElementType::Int || vectorSize != 1) {
        ctx->pushError(GL_INVALID_OPERATION);
        return true;
    }
    const GLint v = *static_cast<const GLint*>(values);
    if (v < 0) {
        ctx->pushError(GL_INVALID_VALUE);
        return true;
    }
    auto isImageType = [](GLenum t) {
        switch (t) {
            case GL_IMAGE_1D: case GL_IMAGE_2D: case GL_IMAGE_3D:
            case GL_IMAGE_2D_RECT: case GL_IMAGE_CUBE:
            case GL_IMAGE_BUFFER: case GL_IMAGE_1D_ARRAY:
            case GL_IMAGE_2D_ARRAY: case GL_IMAGE_CUBE_MAP_ARRAY:
            case GL_IMAGE_2D_MULTISAMPLE:
            case GL_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_INT_IMAGE_1D: case GL_INT_IMAGE_2D:
            case GL_INT_IMAGE_3D: case GL_INT_IMAGE_2D_RECT:
            case GL_INT_IMAGE_CUBE: case GL_INT_IMAGE_BUFFER:
            case GL_INT_IMAGE_1D_ARRAY: case GL_INT_IMAGE_2D_ARRAY:
            case GL_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_INT_IMAGE_2D_MULTISAMPLE:
            case GL_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_1D:
            case GL_UNSIGNED_INT_IMAGE_2D:
            case GL_UNSIGNED_INT_IMAGE_3D:
            case GL_UNSIGNED_INT_IMAGE_2D_RECT:
            case GL_UNSIGNED_INT_IMAGE_CUBE:
            case GL_UNSIGNED_INT_IMAGE_BUFFER:
            case GL_UNSIGNED_INT_IMAGE_1D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_IMAGE_2D_MULTISAMPLE_ARRAY:
                return true;
            default:
                return false;
        }
    };
    GLint maxUnit = 0;
    if (isImageType(utype)) {
        ctx->capabilities().queryInteger(GL_MAX_IMAGE_UNITS, &maxUnit);
    } else {
        ctx->capabilities().queryInteger(
            GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS, &maxUnit);
    }
    if (maxUnit > 0 && v >= maxUnit) {
        ctx->pushError(GL_INVALID_VALUE);
        return true;
    }
    return false;
}

bool GLContext::setUniformScalarVector(GLint location, UniformElementType element, GLint vectorSize, GLsizei count, const void* values) {
    if (location < 0) {
        return true;  // -1 silently no-ops per spec.
    }
    if (count < 0 || vectorSize < 1 || vectorSize > 4) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §7.3: glUniform* targets the current program; if no
    // current program but a pipeline is bound, target the pipeline's
    // active-shader-program (set by glActiveShaderProgram). CTS
    // `sepshaderobjs.ProgUniformAPI` exercises this fallback.
    GLuint targetProgram = impl_->state->currentProgram();
    if (targetProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) {
                targetProgram = ppo->activeShaderProgram;
            }
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(targetProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = ref.slot;

    if (sampleOrImageUniformValidationFailed(this, ref.type,
            element, vectorSize, values)) {
        return false;
    }

    // Clamp count so writes don't overflow the declared array. GL spec: the
    // effective update is min(count, arraySize - elementIndex).
    const GLint remaining = std::max<GLint>(ref.arraySize - ref.elementIndex, 1);
    const GLsizei effCount = std::min<GLsizei>(std::max<GLsizei>(count, 1), remaining);
    const std::size_t components = static_cast<std::size_t>(vectorSize);
    const std::size_t writeCount = components * static_cast<std::size_t>(effCount);
    const std::size_t fullCount  = components * static_cast<std::size_t>(std::max<GLint>(ref.arraySize, 1));
    const std::size_t writeOffset = components * static_cast<std::size_t>(ref.elementIndex);

    auto writeInto = [&](auto& dstVec, auto& otherA, auto& otherB, const auto* src) {
        using T = typename std::remove_reference<decltype(dstVec)>::type::value_type;
        // Size the destination to hold the full array; preserve existing
        // values where possible so per-element writes don't wipe siblings.
        if (dstVec.size() < fullCount) {
            dstVec.resize(fullCount, T{});
        }
        std::memcpy(dstVec.data() + writeOffset, src, writeCount * sizeof(T));
        otherA.clear();
        otherB.clear();
    };

    switch (element) {
        case UniformElementType::Float:
            writeInto(slot->floats, slot->ints, slot->uints, static_cast<const GLfloat*>(values));
            break;
        case UniformElementType::Int:
            writeInto(slot->ints, slot->floats, slot->uints, static_cast<const GLint*>(values));
            break;
        case UniformElementType::UnsignedInt:
            writeInto(slot->uints, slot->floats, slot->ints, static_cast<const GLuint*>(values));
            break;
    }
    return true;
}

bool GLContext::setUniformMatrix(GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLfloat* values) {
    if (location < 0) {
        return true;
    }
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // §7.3 active-shader-program fallback — same as setUniformScalarVector.
    GLuint currentProgram = impl_->state->currentProgram();
    if (currentProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) currentProgram = ppo->activeShaderProgram;
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(currentProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const std::size_t elements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols) *
                                 static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    slot->floats.assign(elements, 0.0f);
    if (transpose == GL_FALSE) {
        std::memcpy(slot->floats.data(), values, elements * sizeof(GLfloat));
    } else {
        const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
        for (GLsizei m = 0; m < std::max<GLsizei>(count, 1); ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) +
                                                 static_cast<std::size_t>(c);
                    const std::size_t dstIndex = static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) +
                                                 static_cast<std::size_t>(r);
                    slot->floats[dstIndex] = values[srcIndex];
                }
            }
        }
    }
    slot->ints.clear();
    slot->uints.clear();
    return true;
}

bool GLContext::setUniformDouble(GLint location, GLint vectorSize, GLsizei count, const GLdouble* values) {
    if (location < 0) {
        return true;
    }
    if (count < 0 || vectorSize < 1 || vectorSize > 4 || values == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // §7.3 active-shader-program fallback.
    GLuint currentProgram = impl_->state->currentProgram();
    if (currentProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) currentProgram = ppo->activeShaderProgram;
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(currentProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const std::size_t expected = static_cast<std::size_t>(vectorSize) *
                                 static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    // Shadow original doubles for lossless glGetUniformdv readback.
    slot->doubles.assign(values, values + expected);
    // Narrow to float for the Metal pipeline.
    slot->floats.resize(expected);
    for (std::size_t i = 0; i < expected; ++i) {
        slot->floats[i] = static_cast<GLfloat>(values[i]);
    }
    slot->ints.clear();
    slot->uints.clear();
    return true;
}

bool GLContext::setUniformDoubleMatrix(GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLdouble* values) {
    if (location < 0) {
        return true;
    }
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // §7.3 active-shader-program fallback.
    GLuint currentProgram = impl_->state->currentProgram();
    if (currentProgram == 0) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo = impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr) currentProgram = ppo->activeShaderProgram;
        }
    }
    GLProgramObject* object = impl_->objects->programs().get(currentProgram);
    if (object == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const std::size_t elements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols) *
                                 static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    // Shadow original doubles.
    slot->doubles.resize(elements);
    slot->floats.resize(elements);
    if (transpose == GL_FALSE) {
        for (std::size_t i = 0; i < elements; ++i) {
            slot->doubles[i] = values[i];
            slot->floats[i] = static_cast<GLfloat>(values[i]);
        }
    } else {
        const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
        for (GLsizei m = 0; m < std::max<GLsizei>(count, 1); ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) +
                                                 static_cast<std::size_t>(c);
                    const std::size_t dstIndex = static_cast<std::size_t>(m) * matrixElements +
                                                 static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) +
                                                 static_cast<std::size_t>(r);
                    slot->doubles[dstIndex] = values[srcIndex];
                    slot->floats[dstIndex] = static_cast<GLfloat>(values[srcIndex]);
                }
            }
        }
    }
    slot->ints.clear();
    slot->uints.clear();
    return true;
}

// --- GL 4.1: glProgramUniform* family — explicit program handle variants ---

bool GLContext::setUniformScalarVectorForProgram(GLuint program, GLint location, UniformElementType element, GLint vectorSize, GLsizei count, const void* values) {
    // GL 4.6 §7.6.1 — error codes for glProgramUniform*. Validate the
    // PROGRAM argument BEFORE checking location, because "not a valid
    // program" and "not linked" fire regardless of location (including
    // location=-1 which would otherwise be a silent no-op).
    //   - program not a program name returned from glCreateProgram → INVALID_VALUE
    //   - program not linked → INVALID_OPERATION
    // CTS `sepshaderobjs.ProgUniformAPI` exercises both paths with a
    // cached location=-1 from an unlinked-program glGetUniformLocation.
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) { pushError(GL_INVALID_VALUE); return false; }
    if (!object->linked) { pushError(GL_INVALID_OPERATION); return false; }
    if (location < 0) return true;
    if (count < 0 || vectorSize < 1 || vectorSize > 4) { pushError(GL_INVALID_VALUE); return false; }
    UniformSlotRef ref = resolveUniformSlot(object, location);
    if (ref.slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    if (sampleOrImageUniformValidationFailed(this, ref.type,
            element, vectorSize, values)) {
        return false;
    }
    GLProgramUniformValue* slot = ref.slot;
    const GLint remaining = std::max<GLint>(ref.arraySize - ref.elementIndex, 1);
    const GLsizei effCount = std::min<GLsizei>(std::max<GLsizei>(count, 1), remaining);
    const std::size_t components = static_cast<std::size_t>(vectorSize);
    const std::size_t writeCount = components * static_cast<std::size_t>(effCount);
    const std::size_t fullCount  = components * static_cast<std::size_t>(std::max<GLint>(ref.arraySize, 1));
    const std::size_t writeOffset = components * static_cast<std::size_t>(ref.elementIndex);
    auto writeInto = [&](auto& dstVec, auto& otherA, auto& otherB, const auto* src) {
        using T = typename std::remove_reference<decltype(dstVec)>::type::value_type;
        if (dstVec.size() < fullCount) dstVec.resize(fullCount, T{});
        std::memcpy(dstVec.data() + writeOffset, src, writeCount * sizeof(T));
        otherA.clear(); otherB.clear();
    };
    switch (element) {
        case UniformElementType::Float:
            writeInto(slot->floats, slot->ints, slot->uints, static_cast<const GLfloat*>(values)); break;
        case UniformElementType::Int:
            writeInto(slot->ints, slot->floats, slot->uints, static_cast<const GLint*>(values)); break;
        case UniformElementType::UnsignedInt:
            writeInto(slot->uints, slot->floats, slot->ints, static_cast<const GLuint*>(values)); break;
    }
    return true;
}

bool GLContext::setUniformMatrixForProgram(GLuint program, GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLfloat* values) {
    if (location < 0) return true;
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) { pushError(GL_INVALID_VALUE); return false; }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    const std::size_t elements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols) * static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    slot->floats.assign(elements, 0.0f);
    if (transpose == GL_FALSE) {
        std::memcpy(slot->floats.data(), values, elements * sizeof(GLfloat));
    } else {
        const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
        for (GLsizei m = 0; m < std::max<GLsizei>(count, 1); ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) + static_cast<std::size_t>(c);
                    const std::size_t dstIndex = static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) + static_cast<std::size_t>(r);
                    slot->floats[dstIndex] = values[srcIndex];
                }
            }
        }
    }
    slot->ints.clear(); slot->uints.clear();
    return true;
}

bool GLContext::setUniformDoubleForProgram(GLuint program, GLint location, GLint vectorSize, GLsizei count, const GLdouble* values) {
    if (location < 0) return true;
    if (count < 0 || vectorSize < 1 || vectorSize > 4 || values == nullptr) { pushError(GL_INVALID_VALUE); return false; }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    const std::size_t expected = static_cast<std::size_t>(vectorSize) * static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    slot->doubles.assign(values, values + expected);
    slot->floats.resize(expected);
    for (std::size_t i = 0; i < expected; ++i) { slot->floats[i] = static_cast<GLfloat>(values[i]); }
    slot->ints.clear(); slot->uints.clear();
    return true;
}

bool GLContext::setUniformDoubleMatrixForProgram(GLuint program, GLint location, GLint rows, GLint cols, GLsizei count, GLboolean transpose, const GLdouble* values) {
    if (location < 0) return true;
    if (count < 0 || rows < 2 || rows > 4 || cols < 2 || cols > 4 || values == nullptr) { pushError(GL_INVALID_VALUE); return false; }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    GLProgramUniformValue* slot = lookupUniformValue(object, location);
    if (slot == nullptr) { pushError(GL_INVALID_OPERATION); return false; }
    const std::size_t elements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols) * static_cast<std::size_t>(std::max<GLsizei>(count, 1));
    slot->doubles.resize(elements);
    slot->floats.resize(elements);
    if (transpose == GL_FALSE) {
        for (std::size_t i = 0; i < elements; ++i) { slot->doubles[i] = values[i]; slot->floats[i] = static_cast<GLfloat>(values[i]); }
    } else {
        const std::size_t matrixElements = static_cast<std::size_t>(rows) * static_cast<std::size_t>(cols);
        for (GLsizei m = 0; m < std::max<GLsizei>(count, 1); ++m) {
            for (GLint r = 0; r < rows; ++r) {
                for (GLint c = 0; c < cols; ++c) {
                    const std::size_t srcIndex = static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(r) * static_cast<std::size_t>(cols) + static_cast<std::size_t>(c);
                    const std::size_t dstIndex = static_cast<std::size_t>(m) * matrixElements + static_cast<std::size_t>(c) * static_cast<std::size_t>(rows) + static_cast<std::size_t>(r);
                    slot->doubles[dstIndex] = values[srcIndex];
                    slot->floats[dstIndex] = static_cast<GLfloat>(values[srcIndex]);
                }
            }
        }
    }
    slot->ints.clear(); slot->uints.clear();
    return true;
}

bool GLContext::getUniformdv(GLuint program, GLint location, GLdouble* params) {
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLProgramUniformValue* value = lookupUniformValue(object, location);
    if (value == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Prefer the lossless double shadow if available.
    if (!value->doubles.empty()) {
        std::memcpy(params, value->doubles.data(), value->doubles.size() * sizeof(GLdouble));
    } else if (!value->floats.empty()) {
        for (std::size_t i = 0; i < value->floats.size(); ++i) {
            params[i] = static_cast<GLdouble>(value->floats[i]);
        }
    } else if (!value->ints.empty()) {
        for (std::size_t i = 0; i < value->ints.size(); ++i) {
            params[i] = static_cast<GLdouble>(value->ints[i]);
        }
    } else if (!value->uints.empty()) {
        for (std::size_t i = 0; i < value->uints.size(); ++i) {
            params[i] = static_cast<GLdouble>(value->uints[i]);
        }
    }
    return true;
}

namespace {

// Build a correctly-laid-out uniform buffer for one shader stage by matching
// SPIRV-Cross struct members (with their std140 offsets/sizes) against the
// program's named GL uniform values.  Handles the mat3 column-padding case
// (GL stores 9 floats; Metal/std140 stores 3 columns × 4 floats = 12).
//
// ── OPT-7: precomputed uniform layout ──
// computeStageUniformLayout() runs once per program per stage, mapping each
// push-constant struct member to its GL uniform location.  This eliminates
// the O(N*M) string comparison from the per-draw packing path.
static void computeStageUniformLayout(
    std::vector<GLProgramObject::UniformLayoutEntry>& layout,
    const ShaderReflection& reflection,
    const std::vector<GLProgramUniformInfo>& uniforms)
{
    layout.clear();
    if (reflection.uniformBlocks.empty()) return;
    const auto& block = reflection.uniformBlocks[0];
    if (block.byteSize == 0) return;

    layout.reserve(block.members.size());
    for (const auto& member : block.members) {
        GLProgramObject::UniformLayoutEntry entry;
        entry.memberOffset = member.offset;
        entry.copyBytes = member.size;
        entry.location = -1;
        // Matrix column-padding: GL 4.6 allows tight-packed mat*x* data
        // via glUniformMatrix*fv, but MSL/std140 always aligns each
        // matrix column to 16 bytes. When the column width
        // (rows * 4 bytes) is < 16 we need to copy column-by-column,
        // leaving trailing-column bytes zero. Covers mat2/mat3 (square)
        // + mat2x3/mat3x2/mat4x3/mat4x2 (non-square). mat4/mat2x4/mat3x4
        // have 16-byte columns and can use the plain memcpy path.
        switch (member.type) {
            case GL_FLOAT_MAT2:
                entry.matPaddedCols = 2; entry.matPaddedRows = 2; break;
            case GL_FLOAT_MAT3:
                entry.matPaddedCols = 3; entry.matPaddedRows = 3; break;
            case GL_FLOAT_MAT2x3:
                entry.matPaddedCols = 2; entry.matPaddedRows = 3; break;
            case GL_FLOAT_MAT3x2:
                entry.matPaddedCols = 3; entry.matPaddedRows = 2; break;
            case GL_FLOAT_MAT4x2:
                entry.matPaddedCols = 4; entry.matPaddedRows = 2; break;
            case GL_FLOAT_MAT4x3:
                entry.matPaddedCols = 4; entry.matPaddedRows = 3; break;
            default: break;
        }
        // Only activate padding when the MSL buffer layout actually
        // allocates > cols*rows*4 bytes for the matrix (std140 with
        // col-stride=16). If an MSL backend packs mat2 tightly at 16
        // bytes (cols=2, col-stride=8) we'd double-copy; keep the
        // plain memcpy path in that case.
        if (entry.matPaddedCols > 0) {
            const std::size_t tightBytes = static_cast<std::size_t>(
                entry.matPaddedCols) * static_cast<std::size_t>(
                entry.matPaddedRows) * sizeof(float);
            if (member.size <= tightBytes) {
                entry.matPaddedCols = 0;
                entry.matPaddedRows = 0;
            }
        }

        // Array uniforms need per-element unpadding in std140 layout:
        // GL stores a float[3] as 12 packed bytes; std140 stores it as
        // 48 bytes (3 elements × 16-byte stride, only 4 used per). We
        // cache the stride and per-element GL byte count so the hot
        // packing loop iterates element-wise when arrayCount > 0.
        // KHR-GL46.explicit_uniform_location.uniform-loc-arrays-*
        // exercises this — declares `uniform float u0[3]` at location N
        // and expects each glUniform1f(N+i, …) to land at u0[i].
        if (member.arraySize > 1 && member.size > 0 && entry.matPaddedCols == 0) {
            entry.arrayCount = member.arraySize;
            entry.arrayStride = member.size / member.arraySize;
            // Compute the GL-packed element byte count from the element
            // type (array's declared type is the element type — for
            // arrays glslang reports the element type + arraySize > 0).
            auto scalarBytes = [](GLenum t) -> std::size_t {
                switch (t) {
                    case GL_FLOAT: case GL_FLOAT_VEC2: case GL_FLOAT_VEC3: case GL_FLOAT_VEC4:
                    case GL_INT: case GL_INT_VEC2: case GL_INT_VEC3: case GL_INT_VEC4:
                    case GL_UNSIGNED_INT: case GL_UNSIGNED_INT_VEC2: case GL_UNSIGNED_INT_VEC3: case GL_UNSIGNED_INT_VEC4:
                    case GL_BOOL:  case GL_BOOL_VEC2:  case GL_BOOL_VEC3:  case GL_BOOL_VEC4:
                        return 4;
                    case GL_DOUBLE: case GL_DOUBLE_VEC2: case GL_DOUBLE_VEC3: case GL_DOUBLE_VEC4:
                        return 8;
                    default:
                        return 4;
                }
            };
            auto componentCount = [](GLenum t) -> std::size_t {
                switch (t) {
                    case GL_FLOAT: case GL_INT: case GL_UNSIGNED_INT: case GL_DOUBLE: case GL_BOOL: return 1;
                    case GL_FLOAT_VEC2: case GL_INT_VEC2: case GL_UNSIGNED_INT_VEC2: case GL_DOUBLE_VEC2: case GL_BOOL_VEC2: return 2;
                    case GL_FLOAT_VEC3: case GL_INT_VEC3: case GL_UNSIGNED_INT_VEC3: case GL_DOUBLE_VEC3: case GL_BOOL_VEC3: return 3;
                    case GL_FLOAT_VEC4: case GL_INT_VEC4: case GL_UNSIGNED_INT_VEC4: case GL_DOUBLE_VEC4: case GL_BOOL_VEC4: return 4;
                    case GL_FLOAT_MAT2: return 4;
                    case GL_FLOAT_MAT3: return 9;
                    case GL_FLOAT_MAT4: return 16;
                    case GL_FLOAT_MAT2x3: case GL_FLOAT_MAT3x2: return 6;
                    case GL_FLOAT_MAT2x4: case GL_FLOAT_MAT4x2: return 8;
                    case GL_FLOAT_MAT3x4: case GL_FLOAT_MAT4x3: return 12;
                    default: return 1;
                }
            };
            entry.glElementBytes = componentCount(member.type) * scalarBytes(member.type);
        }

        // One-time name lookup: find the GL uniform location for this member.
        for (const auto& u : uniforms) {
            if (u.name == member.name) {
                entry.location = u.location;
                break;
            }
        }
        layout.push_back(entry);
    }
}

// The output is written into |outBuffer|, which is resized via assign().
// Callers should pass a thread-local vector so that the allocation persists
// across draw calls — after the first frame this is a zero-alloc operation.
//
// OPT-7: uses the precomputed layout to avoid per-draw string comparisons.
// The layout maps struct members directly to uniform locations.
// Push synthesized fixed-function matrix uniform values into the
// program's uniformValues map so the next buildStageUniformBuffer
// pack picks them up. Reads from the per-context MatrixStateMirror
// and writes only the slots that the link-time scan found in
// programObject->synthesizedMatrixSlots — slots whose original
// (compat-profile) shader source did not reference the corresponding
// gl_* identifier stay at -1 and get skipped. When no slots are set
// at all (the typical case for core-profile programs), this returns
// in O(1) and the per-draw cost is a single bool check.
static void pushSynthesizedMatrixUniforms(
    GLProgramObject& program,
    const MatrixStateMirror& matrixState)
{
    const auto& slots = program.synthesizedMatrixSlots;
    if (!slots.hasAny()) {
        return;
    }

    auto storeMat4 = [&](GLint loc, const Matrix4& matrix) {
        if (loc < 0) return;
        auto& value = program.uniformValues[loc];
        value.type = GL_FLOAT_MAT4;
        value.arraySize = 1;
        value.floats.assign(matrix.m.begin(), matrix.m.end());
    };
    auto storeMat3 = [&](GLint loc, const Matrix4& matrix) {
        if (loc < 0) return;
        auto& value = program.uniformValues[loc];
        value.type = GL_FLOAT_MAT3;
        value.arraySize = 1;
        // GL stores mat3 as 9 packed floats (3 columns × 3 rows). The
        // GPU side uses 3 vec4 columns; buildStageUniformBuffer's
        // matrix-column-padding path (matPaddedCols / matPaddedRows)
        // repacks 9 → 12 floats when the layout entry is flagged. We
        // store the 9-float canonical form here.
        value.floats.assign(9, 0.0f);
        for (int col = 0; col < 3; ++col) {
            for (int row = 0; row < 3; ++row) {
                value.floats[col * 3 + row] = matrix.m[col * 4 + row];
            }
        }
    };

    if (slots.modelView >= 0) {
        storeMat4(slots.modelView, matrixState.modelView());
    }
    if (slots.projection >= 0) {
        storeMat4(slots.projection, matrixState.projection());
    }
    if (slots.modelViewProjection >= 0) {
        storeMat4(slots.modelViewProjection, matrixState.modelViewProjection());
    }
    if (slots.modelViewInverse >= 0) {
        storeMat4(slots.modelViewInverse, matrixState.modelViewInverse());
    }
    if (slots.projectionInverse >= 0) {
        storeMat4(slots.projectionInverse, matrixState.projectionInverse());
    }
    if (slots.modelViewProjectionInverse >= 0) {
        storeMat4(slots.modelViewProjectionInverse,
                  matrixState.modelViewProjectionInverse());
    }
    if (slots.normal >= 0) {
        storeMat3(slots.normal, matrixState.normalMatrix());
    }
    if (slots.texture >= 0) {
        // Texture matrix is `mat4 appgl_TextureMatrix[N]`. The link
        // pass treats it as a single uniform whose value buffer holds
        // N * 16 packed floats. Fill all N entries from the per-unit
        // texture stack tops; unused units come back as identity from
        // MatrixStateMirror::textureMatrix() so the GPU-side array is
        // always fully populated.
        auto& value = program.uniformValues[slots.texture];
        value.type = GL_FLOAT_MAT4;
        value.arraySize = static_cast<GLint>(kSynthesizedTextureMatrixCount);
        value.floats.assign(
            static_cast<std::size_t>(kSynthesizedTextureMatrixCount) * 16, 0.0f);
        for (unsigned int i = 0; i < kSynthesizedTextureMatrixCount; ++i) {
            const Matrix4 m = matrixState.textureMatrix(i);
            std::memcpy(value.floats.data() + i * 16,
                        m.m.data(),
                        16 * sizeof(float));
        }
    }
}

static void buildStageUniformBuffer(
    std::vector<std::uint8_t>& outBuffer,
    const ShaderReflection& reflection,
    const std::unordered_map<GLint, GLProgramUniformValue>& uniformValues,
    const std::vector<GLProgramObject::UniformLayoutEntry>& layout)
{
    outBuffer.clear();
    if (reflection.uniformBlocks.empty()) return;
    const auto& block = reflection.uniformBlocks[0];
    if (block.byteSize == 0) return;

    const std::size_t paddedSize = (block.byteSize + 15u) & ~std::size_t(15u);
    outBuffer.assign(paddedSize, 0);

    for (const auto& entry : layout) {
        if (entry.location < 0) continue;

        auto it = uniformValues.find(entry.location);
        if (it == uniformValues.end()) continue;
        const auto& val = it->second;

        // Determine which data vector to use based on what's populated.
        const void* srcData = nullptr;
        std::size_t srcBytes = 0;
        if (!val.floats.empty()) {
            srcData = val.floats.data();
            srcBytes = val.floats.size() * sizeof(GLfloat);
        } else if (!val.ints.empty()) {
            srcData = val.ints.data();
            srcBytes = val.ints.size() * sizeof(GLint);
        } else if (!val.uints.empty()) {
            srcData = val.uints.data();
            srcBytes = val.uints.size() * sizeof(GLuint);
        } else {
            continue;
        }

        std::uint8_t* dst = outBuffer.data() + entry.memberOffset;

        // Matrix column-padding: GL packs matrix data as `cols*rows`
        // tight floats (column-major); MSL/std140 aligns each column
        // to 16 bytes. Copy per-column and leave trailing bytes zero.
        // Covers mat2 / mat3 / mat2x3 / mat3x2 / mat4x2 / mat4x3.
        // (mat4 / mat2x4 / mat3x4 have 16-byte columns so matPaddedCols
        // stays 0 and they fall through to the plain memcpy.)
        if (entry.matPaddedCols > 0 && entry.matPaddedRows > 0) {
            const std::size_t needed = static_cast<std::size_t>(
                entry.matPaddedCols) * static_cast<std::size_t>(
                entry.matPaddedRows);
            if (val.floats.size() >= needed) {
                const int cols = entry.matPaddedCols;
                const int rows = entry.matPaddedRows;
                for (int col = 0; col < cols; ++col) {
                    std::memcpy(
                        dst + col * 16,
                        val.floats.data() + col * rows,
                        static_cast<std::size_t>(rows) * sizeof(float));
                }
                continue;
            }
        }

        // Array element unpadding: GL stores element [k] at byte offset
        // k * glElementBytes (tight); std140 places it at k * arrayStride
        // (>= 16). Loop per element, memcpy the GL-packed element into
        // its std140 slot, leave padding bytes zero. Applies to arrays
        // of scalars (float arr[N], int arr[N]) and vec3 arrays which
        // have slightly-wasted but still padded layout.
        if (entry.arrayCount > 0 && entry.arrayStride > entry.glElementBytes) {
            const std::size_t perEl = entry.glElementBytes;
            const std::size_t stride = entry.arrayStride;
            const auto* srcBytesPtr = static_cast<const std::uint8_t*>(srcData);
            for (std::uint32_t k = 0; k < entry.arrayCount; ++k) {
                const std::size_t srcOff = static_cast<std::size_t>(k) * perEl;
                const std::size_t dstOff = static_cast<std::size_t>(k) * stride;
                if (srcOff + perEl > srcBytes) break;
                std::memcpy(dst + dstOff, srcBytesPtr + srcOff, perEl);
            }
            continue;
        }

        std::memcpy(dst, srcData, std::min(srcBytes, entry.copyBytes));
    }
}

// Phase A Group 7 — MVP draw path. Until the GLSL→MSL translator is wired up,
// the runtime supports one hand-written "solid color" pipeline: a single
// vec3 position attribute at location 0 plus a vec4 uniform named "uColor".
// Anything outside that envelope is rejected here so the caller can emit a
// debug message and bail cleanly instead of producing garbage pixels.
// Resolve the effective VBO name, stride, and byte offset for a vertex
// attribute, handling both classic (glVertexAttribPointer) and separated
// (GL 4.3/4.5 glVertexAttribFormat + glVertexArrayVertexBuffer) formats.
struct ResolvedVertexAttrib {
    GLuint bufferName = 0;
    std::size_t stride = 0;
    std::size_t offset = 0;
};

static ResolvedVertexAttrib resolveVertexAttrib(
    const GLVertexAttributeState& attr,
    const GLVertexArrayObject& vao)
{
    ResolvedVertexAttrib r;
    // GL 4.3 separated vertex format: attribute[i].bindingIndex = i by
    // default (see `GLObjectStore::initializeVertexArray`), and
    // `glBindVertexBuffer(s)` writes buffer/offset/stride to
    // `bindingPoints[N]` independently. An attribute can reach that
    // binding state WITHOUT a prior `glVertexAttribFormat` — the
    // default per-attribute format (size=4, type=GL_FLOAT,
    // relativeOffset=0) is always in effect. So we take the
    // binding-point path whenever a bound buffer is present there,
    // even when `useSeparatedFormat` is still false.
    //
    // Without this fallback, `multi_bind.draw_bind_vertex_buffers`
    // and similar "bindVertexBuffers + default-format-draw" tests
    // read zeros from every attribute — `attr.buffer` is 0
    // (VertexAttribPointer was never called), so the legacy branch
    // returned bufferName=0 and Metal fetched nothing.
    const bool hasSeparatedBinding =
        (attr.bindingIndex < vao.bindingPoints.size()) &&
        (vao.bindingPoints[attr.bindingIndex].buffer != 0);
    if (attr.useSeparatedFormat || hasSeparatedBinding) {
        if (attr.bindingIndex < vao.bindingPoints.size()) {
            const auto& bp = vao.bindingPoints[attr.bindingIndex];
            r.bufferName = bp.buffer;
            r.stride = bp.stride > 0
                ? static_cast<std::size_t>(bp.stride)
                : sizeof(GLfloat) * static_cast<std::size_t>(attr.size);
            r.offset = static_cast<std::size_t>(bp.offset)
                     + static_cast<std::size_t>(attr.relativeOffset);
            return r;
        }
    }
    r.bufferName = attr.buffer;
    r.stride = attr.stride > 0
        ? static_cast<std::size_t>(attr.stride)
        : sizeof(GLfloat) * static_cast<std::size_t>(attr.size);
    r.offset = static_cast<std::size_t>(attr.pointer);
    return r;
}

struct SolidColorDrawSetup {
    bool ok = false;
    MetalDrawInfo info;
    GLVertexArrayObject* vertexArray = nullptr;
    GLProgramObject* program = nullptr;
    const std::uint8_t* positionShadow = nullptr;
    std::size_t positionShadowSize = 0;
};

// Phase 8X Group 4d follow-up¹⁴ — common pipeline state plumbing for
// the translated-draw path. Centralises the depth/cull/front-face/
// wireframe/blend reads so every draw entry point captures the same
// snapshot without drifting. The blend fields come directly from
// `GLStateTracker::blendState()` — the getter already returns the RGB
// vs. alpha split, so we just mirror it into the TDI substruct and
// separately ask `isEnabled(GL_BLEND)` for the enable bit (which lives
// in `enabledCaps_`, not the blend struct itself).
static void populateTranslatedDrawFixedFunctionState(
    TranslatedDrawInfo& tdi, GLStateTracker& state)
{
    tdi.depthTestEnabled = state.isEnabled(GL_DEPTH_TEST);
    tdi.depthFunc = state.depthState().func;
    tdi.depthWriteMask = (state.depthState().writeMask != GL_FALSE);
    // Sprint 7 Phase 1 #11 (CKPT57): mirror GL stencil state into the
    // TDI so depthStencilStateForDraw can configure Metal's per-face
    // stencil descriptors. Without this, GL stencil-test+ops were
    // silently dropped at draw time (Metal default = Always + Keep,
    // which masquerades as "stencil-test always passes" but never
    // writes back, breaking primitive_coverage and any other test
    // that depends on stencil correctness).
    {
        const auto& gs = state.stencilState();
        tdi.stencilTestEnabled = state.isEnabled(GL_STENCIL_TEST);
        tdi.stencilFrontFunc = gs.front.func;
        tdi.stencilFrontRef = gs.front.ref;
        tdi.stencilFrontValueMask = gs.front.valueMask;
        tdi.stencilFrontFail = gs.front.fail;
        tdi.stencilFrontDepthFail = gs.front.depthFail;
        tdi.stencilFrontDepthPass = gs.front.depthPass;
        tdi.stencilFrontWriteMask = gs.front.writeMask;
        tdi.stencilBackFunc = gs.back.func;
        tdi.stencilBackRef = gs.back.ref;
        tdi.stencilBackValueMask = gs.back.valueMask;
        tdi.stencilBackFail = gs.back.fail;
        tdi.stencilBackDepthFail = gs.back.depthFail;
        tdi.stencilBackDepthPass = gs.back.depthPass;
        tdi.stencilBackWriteMask = gs.back.writeMask;
    }
    tdi.cullFaceEnabled = state.isEnabled(GL_CULL_FACE);
    tdi.cullFaceMode = state.rasterState().cullFaceMode;
    tdi.frontFace = state.rasterState().frontFace;
    tdi.wireframe = (state.rasterState().polygonFillMode == GL_LINE);
    tdi.rasterizerDiscard = state.isEnabled(GL_RASTERIZER_DISCARD);
    // Phase 6-1d: sample-shading snapshot. The Metal side uses this
    // to force per-sample FS invocation when the bound attachment
    // is MS; until that plumbing lands (6-1e+), the state is merely
    // captured so the correct values are available when we need them.
    tdi.sampleShadingEnabled = state.isEnabled(GL_SAMPLE_SHADING);
    tdi.minSampleShading = state.blendState().minSampleShading;

    // GL 4.6 §14.6.5 — polygon offset enabled under GL_POLYGON_OFFSET_FILL
    // (relevant for triangle rasterization) plus LINE / POINT variants.
    // If any of the three is enabled, thread factor/units/clamp into the
    // draw info so the render encoder applies depth bias before the draw.
    const bool anyOffsetEnabled = state.isEnabled(GL_POLYGON_OFFSET_FILL) ||
                                  state.isEnabled(GL_POLYGON_OFFSET_LINE) ||
                                  state.isEnabled(GL_POLYGON_OFFSET_POINT);
    tdi.polygonOffsetEnabled = anyOffsetEnabled;
    tdi.polygonOffsetFactor = state.rasterState().polygonOffsetFactor;
    tdi.polygonOffsetUnits = state.rasterState().polygonOffsetUnits;
    tdi.polygonOffsetClamp = state.rasterState().polygonOffsetClamp;

    const auto& gl = state.blendState();
    tdi.blend.enabled = state.isEnabled(GL_BLEND);
    tdi.blend.srcRGB = gl.srcRGB;
    tdi.blend.dstRGB = gl.dstRGB;
    tdi.blend.srcAlpha = gl.srcAlpha;
    tdi.blend.dstAlpha = gl.dstAlpha;
    tdi.blend.equationRGB = gl.equationRGB;
    tdi.blend.equationAlpha = gl.equationAlpha;
    tdi.blend.colorMaskR = (gl.colorMask[0] != GL_FALSE);
    tdi.blend.colorMaskG = (gl.colorMask[1] != GL_FALSE);
    tdi.blend.colorMaskB = (gl.colorMask[2] != GL_FALSE);
    tdi.blend.colorMaskA = (gl.colorMask[3] != GL_FALSE);

    // RC-A02: viewport state.
    const auto& vp = state.viewport();
    tdi.viewportX = vp.x;
    tdi.viewportY = vp.y;
    tdi.viewportWidth = vp.width;
    tdi.viewportHeight = vp.height;
    const auto& dr = state.depthRange();
    tdi.depthRangeNear = dr.nearValue;
    tdi.depthRangeFar = dr.farValue;
    // Sprint 17 Day 3+ BONUS-1 [clip_control]: snapshot the
    // current `glClipControl` origin into TranslatedDrawInfo so
    // MetalFrameGraph's viewport-Y-flip can gate on it
    // (`GL_UPPER_LEFT` → no flip, `GL_LOWER_LEFT` → flip as before).
    tdi.clipOrigin = state.clipOrigin();
    // Sprint 15 Q3-Option-B Day 8 [metal-viewport-array]: populate
    // per-index viewport array (GL 4.1 ARB_viewport_array). Bind
    // multi-viewport at the encoder when ANY indexed slot diverges
    // from slot 0 (i.e. the app has called glViewportIndexed* or
    // glViewportArrayv to set per-index state). Otherwise count=0 to
    // preserve the single-viewport encoder path.
    //
    // Sprint 16 Day 19 (CKPT228): also bind the array when only the
    // *scissor* array diverges (`glScissorIndexed*` /
    // `glScissorArrayv`). CTS `viewport_array.scissor` /
    // `viewport_array.scissor_clear` set 16 per-index scissor rects
    // but never touch glViewportArrayv — every indexed viewport
    // stays at slot 0's value, so the prior viewport-only divergence
    // check stayed false, the encoder used the single-viewport
    // single-scissor path, and Metal applied the same default
    // scissor to every fragment regardless of the per-vertex
    // `gl_ViewportIndex` the GS emitted. Detecting scissor divergence
    // routes the draw through `setViewports:count:N` +
    // `setScissorRects:count:N` even when viewport[1..N-1] match
    // slot 0, which is what the scissor tests need.
    {
        appgl::GLStateTracker::IndexedViewportEntry vparr[
            appgl::TranslatedDrawInfo::kMaxDrawViewports];
        std::size_t got = 0;
        state.getViewportArray(vparr,
            appgl::TranslatedDrawInfo::kMaxDrawViewports, &got);
        appgl::GLStateTracker::IndexedScissorEntry scarr_pre[
            appgl::TranslatedDrawInfo::kMaxDrawViewports];
        std::size_t scgot_pre = 0;
        state.getScissorArray(scarr_pre,
            appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot_pre);
        bool anyDiverge = false;
        for (std::size_t i = 1; i < got; ++i) {
            if (vparr[i].x != vparr[0].x ||
                vparr[i].y != vparr[0].y ||
                vparr[i].width != vparr[0].width ||
                vparr[i].height != vparr[0].height ||
                vparr[i].depthNear != vparr[0].depthNear ||
                vparr[i].depthFar != vparr[0].depthFar) {
                anyDiverge = true;
                break;
            }
        }
        if (!anyDiverge) {
            for (std::size_t i = 1; i < scgot_pre; ++i) {
                if (scarr_pre[i].x != scarr_pre[0].x ||
                    scarr_pre[i].y != scarr_pre[0].y ||
                    scarr_pre[i].width != scarr_pre[0].width ||
                    scarr_pre[i].height != scarr_pre[0].height ||
                    scarr_pre[i].enabled != scarr_pre[0].enabled) {
                    anyDiverge = true;
                    break;
                }
            }
        }
        if (anyDiverge) {
            for (std::size_t i = 0; i < got; ++i) {
                tdi.viewportArray[i].originX = vparr[i].x;
                tdi.viewportArray[i].originY = vparr[i].y;
                tdi.viewportArray[i].width = vparr[i].width;
                tdi.viewportArray[i].height = vparr[i].height;
                tdi.viewportArray[i].depthNear = vparr[i].depthNear;
                tdi.viewportArray[i].depthFar = vparr[i].depthFar;
            }
            tdi.viewportArrayCount = got;
            // Sprint 16 Day 3 [viewport_array]: pair the indexed scissor
            // array. When viewport array is bound, Metal requires a
            // matching scissor count (otherwise viewports 1..N-1 see
            // an undefined scissor and clip every fragment).
            appgl::GLStateTracker::IndexedScissorEntry scarr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t scgot = 0;
            state.getScissorArray(scarr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot);
            const std::size_t cap = std::min(got, scgot);
            for (std::size_t i = 0; i < cap; ++i) {
                tdi.scissorArray[i].x = scarr[i].x;
                tdi.scissorArray[i].y = scarr[i].y;
                tdi.scissorArray[i].width = scarr[i].width;
                tdi.scissorArray[i].height = scarr[i].height;
                tdi.scissorArray[i].enabled = scarr[i].enabled;
            }
        }
    }

    // GL 4.6 §14.5.1 — scissor state.
    tdi.scissorTestEnabled = state.isEnabled(GL_SCISSOR_TEST);
    const auto& sc = state.scissor();
    tdi.scissorX = sc.x;
    tdi.scissorY = sc.y;
    tdi.scissorWidth = sc.width;
    tdi.scissorHeight = sc.height;
}

// Phase 8X Group 4d follow-up¹⁴ — VAO → VertexAttributeLayout field
// copy. The GL `glVertexAttribPointer` (and `glVertexAttribIPointer` /
// `glVertexAttribFormat`) parameters are the *source of truth* for the
// MTLVertexFormat of each attribute, not `ShaderReflection::vertexInputs
// [i].type`. Prior to follow-up¹⁴ the vertex descriptor derived
// attribute formats from the shader-reflected scalar type, which
// produced `Float4` for any `in vec4 color` input even when the VBO
// layout stored 4×UBYTE normalized colors (see followup¹³-verification
// §Smoking-Gun). Capturing these four fields end-to-end lets
// `encodeTranslatedDraw` call `vaoTypeToMTLFormat` with the real VBO
// layout instead of the shader-reflected placeholder.
static void populateVertexAttributeLayoutVAOFields(
    TranslatedDrawInfo::VertexAttributeLayout& layout,
    const GLVertexAttributeState& attr)
{
    layout.glType = attr.type;
    layout.glComponentCount = attr.size;
    layout.glNormalized = attr.normalized;
    layout.glIsInteger = attr.integer;
}

SolidColorDrawSetup buildSolidColorDrawSetup(GLStateTracker& state, GLObjectStore& objects, GLenum mode, const char* debugLabel) {
    SolidColorDrawSetup setup;

    if (mode != GL_TRIANGLES && mode != GL_TRIANGLE_STRIP && mode != GL_TRIANGLE_FAN) {
        return setup;
    }

    const GLuint vaoName = state.boundVertexArray();
    if (vaoName == 0) {
        return setup;
    }
    GLVertexArrayObject* vao = objects.vertexArrays().get(vaoName);
    if (vao == nullptr) {
        return setup;
    }
    if (vao->attributes.empty()) {
        objects.initializeVertexArray(*vao);
        if (vao->attributes.empty()) {
            return setup;
        }
    }

    const GLuint programName = state.currentProgram();
    if (programName == 0) {
        return setup;
    }
    GLProgramObject* program = objects.programs().get(programName);
    if (program == nullptr || !program->linked) {
        return setup;
    }

    const auto& positionAttr = vao->attributes[0];
    if (!positionAttr.enabled || positionAttr.type != GL_FLOAT || positionAttr.size != 3) {
        return setup;
    }
    // Resolve through binding point for GL 4.3+ separated vertex format,
    // falling back to legacy attribute fields for classic glVertexAttribPointer.
    ResolvedVertexAttrib resolved = resolveVertexAttrib(positionAttr, *vao);
    if (resolved.bufferName == 0) {
        return setup;
    }
    GLBufferObject* vbo = objects.buffers().get(resolved.bufferName);
    if (vbo == nullptr || vbo->shadowBytes.empty()) {
        return setup;
    }
    const std::size_t positionStride = resolved.stride;
    if (resolved.offset > vbo->shadowBytes.size()) {
        return setup;
    }

    setup.info.mode = mode;
    setup.info.positions = vbo->shadowBytes.data() + resolved.offset;
    setup.info.positionByteCount = vbo->shadowBytes.size() - resolved.offset;
    setup.info.positionStride = positionStride;
    setup.info.positionComponents = 3;
    setup.positionShadow = vbo->shadowBytes.data();
    setup.positionShadowSize = vbo->shadowBytes.size();

    // Default to opaque white, then override from the "uColor" uniform if the
    // linked program has one. This mirrors what the hand-written fragment
    // shader expects at fragment buffer index 0.
    setup.info.uniformColor[0] = 1.0f;
    setup.info.uniformColor[1] = 1.0f;
    setup.info.uniformColor[2] = 1.0f;
    setup.info.uniformColor[3] = 1.0f;
    for (const auto& uniform : program->uniforms) {
        if (uniform.name == "uColor" && uniform.type == GL_FLOAT_VEC4 && uniform.location >= 0) {
            auto it = program->uniformValues.find(uniform.location);
            if (it != program->uniformValues.end() && it->second.floats.size() >= 4) {
                setup.info.uniformColor[0] = it->second.floats[0];
                setup.info.uniformColor[1] = it->second.floats[1];
                setup.info.uniformColor[2] = it->second.floats[2];
                setup.info.uniformColor[3] = it->second.floats[3];
            }
            break;
        }
    }

    setup.info.depthTestEnabled = state.isEnabled(GL_DEPTH_TEST);
    setup.info.depthFunc = state.depthState().func;
    setup.info.depthWriteMask = (state.depthState().writeMask != GL_FALSE);
    setup.info.cullFaceEnabled = state.isEnabled(GL_CULL_FACE);
    setup.info.cullFaceMode = state.rasterState().cullFaceMode;
    setup.info.frontFace = state.rasterState().frontFace;
    setup.info.wireframe = (state.rasterState().polygonFillMode == GL_LINE);
    // Sprint 7 Phase 1 #11 (CKPT57): stencil state for solid-color path.
    {
        const auto& gs = state.stencilState();
        setup.info.stencilTestEnabled = state.isEnabled(GL_STENCIL_TEST);
        setup.info.stencilFrontFunc = gs.front.func;
        setup.info.stencilFrontRef = gs.front.ref;
        setup.info.stencilFrontValueMask = gs.front.valueMask;
        setup.info.stencilFrontFail = gs.front.fail;
        setup.info.stencilFrontDepthFail = gs.front.depthFail;
        setup.info.stencilFrontDepthPass = gs.front.depthPass;
        setup.info.stencilFrontWriteMask = gs.front.writeMask;
        setup.info.stencilBackFunc = gs.back.func;
        setup.info.stencilBackRef = gs.back.ref;
        setup.info.stencilBackValueMask = gs.back.valueMask;
        setup.info.stencilBackFail = gs.back.fail;
        setup.info.stencilBackDepthFail = gs.back.depthFail;
        setup.info.stencilBackDepthPass = gs.back.depthPass;
        setup.info.stencilBackWriteMask = gs.back.writeMask;
    }
    if (debugLabel != nullptr) {
        setup.info.debugLabel = debugLabel;
    }

    setup.vertexArray = vao;
    setup.program = program;
    setup.ok = true;
    return setup;
}

}  // namespace

namespace {
// GL 4.6 §11.3.1: when the program has a geometry shader, the draw
// call's primitive mode must match the GS's input primitive type.
// Returns false + GL_INVALID_OPERATION pushed by the caller when the
// mode is incompatible. Programs without a GS always return true
// (mode validation for those lives in the standard draw-mode check).
bool isDrawModeCompatibleWithGs(GLenum drawMode, GLenum gsInputTopo) {
    switch (gsInputTopo) {
        case GL_POINTS:
            return drawMode == GL_POINTS;
        case GL_LINES:
            return drawMode == GL_LINES || drawMode == GL_LINE_STRIP ||
                   drawMode == GL_LINE_LOOP;
        case GL_LINES_ADJACENCY:
            return drawMode == GL_LINES_ADJACENCY ||
                   drawMode == GL_LINE_STRIP_ADJACENCY;
        case GL_TRIANGLES:
            return drawMode == GL_TRIANGLES || drawMode == GL_TRIANGLE_STRIP ||
                   drawMode == GL_TRIANGLE_FAN;
        case GL_TRIANGLES_ADJACENCY:
            return drawMode == GL_TRIANGLES_ADJACENCY ||
                   drawMode == GL_TRIANGLE_STRIP_ADJACENCY;
        default:
            return true;   // unknown GS topology: don't reject
    }
}
}  // namespace

// Defined after the anonymous namespace with populateTranslatedDraw-
// FixedFunctionState / computeStageUniformLayout / buildStageUniform-
// Buffer so those helpers are visible.
GLProgramObject* GLContext::Impl::resolvePipelineEmulationProgram(
    GLuint currentProgramName, GLuint& outProgramName)
{
    // Fast path: a current program is bound (glUseProgram), use it
    // directly. Don't touch pipeline state even if a pipeline is
    // also bound — GL 4.6 §7.3 says the current program shadows
    // any pipeline binding.
    if (currentProgramName != 0) {
        outProgramName = currentProgramName;
        return objects->programs().get(currentProgramName);
    }
    // No current program; check the pipeline for a GS program.
    const GLuint pipelineName = state->currentProgramPipeline();
    if (pipelineName == 0) return nullptr;
    GLProgramPipelineObject* ppo = objects->programPipelines().get(pipelineName);
    if (ppo == nullptr || ppo->geometryProgram == 0) return nullptr;
    GLProgramObject* gsProg = objects->programs().get(ppo->geometryProgram);
    if (gsProg == nullptr || !gsProg->geometryEmulated) return nullptr;
    // Copy the VS program's vertexSpirv onto the GS program so
    // emulateGeometryDraw's pre-pass runs against the pipeline's
    // actual VS. Idempotent when the same pipeline draws multiple
    // times — we overwrite to stay in sync even if the pipeline's
    // stages were swapped via useProgramStages between draws.
    if (ppo->vertexProgram != 0) {
        GLProgramObject* vsProg = objects->programs().get(ppo->vertexProgram);
        if (vsProg != nullptr) {
            gsProg->vertexSpirv = vsProg->vertexSpirv;
            // Carry the VS uniform layout too so indirect uniform-
            // buffer lookups (not used by createShaderProgramv,
            // but needed by more complex tests) see the right
            // binding slots.
            // Leaving vertexReflection/vertexMSL alone — the GS
            // emulator builds a synth VS from the EmulatedDraw,
            // not the VS's own MSL.
        }
    }
    // Copy the FS program's fragmentMSL + reflection for the
    // encoder's pipeline build. When absent (FS program missing
    // or not linked), encodeEmulatedGsDraw will fail and the draw
    // falls back — same behaviour as before this patch.
    if (ppo->fragmentProgram != 0) {
        GLProgramObject* fsProg = objects->programs().get(ppo->fragmentProgram);
        if (fsProg != nullptr) {
            gsProg->fragmentMSL = fsProg->fragmentMSL;
            gsProg->fragmentReflection = fsProg->fragmentReflection;
        }
    }
    outProgramName = ppo->geometryProgram;
    return gsProg;
}

GLProgramObject* GLContext::Impl::resolveDrawProgram(GLuint& programName) {
    // Fast path: a current program is bound (glUseProgram), use it
    // directly. GL 4.6 §7.3 says current program shadows any pipeline.
    if (programName != 0) {
        return objects->programs().get(programName);
    }
    // No current program — check for an active program pipeline and
    // synthesise a merged VS+FS container on the pipeline's VS.
    const GLuint pipelineName = state->currentProgramPipeline();
    if (pipelineName == 0) return nullptr;
    GLProgramPipelineObject* ppo = objects->programPipelines().get(pipelineName);
    if (ppo == nullptr || ppo->vertexProgram == 0) return nullptr;
    GLProgramObject* vsProg = objects->programs().get(ppo->vertexProgram);
    if (vsProg == nullptr || !vsProg->hasTranslatedPipeline) return nullptr;
    // Splice pipeline's FS MSL + reflection onto the VS container so
    // the downstream translated-draw path sees a single program with
    // both stages populated. Overwrite every call — cheap, keeps a
    // stage swap between draws in sync. The pipeline state cache is
    // keyed on the MSL contents so a real swap invalidates itself.
    if (ppo->fragmentProgram != 0) {
        GLProgramObject* fsProg = objects->programs().get(ppo->fragmentProgram);
        if (fsProg != nullptr) {
            vsProg->fragmentMSL = fsProg->fragmentMSL;
            vsProg->fragmentReflection = fsProg->fragmentReflection;
            // The translated-draw path caches uniform layouts on the
            // container program. If we merged a new FS shape we need
            // the layout recomputed, otherwise the vertex and fragment
            // uniform buffers get built from stale reflection.
            vsProg->uniformLayoutComputed = false;
        }
    } else {
        // No FS stage on the pipeline — clear the container's fragment
        // data so we don't accidentally render with a stale FS left
        // over from a previous pipeline that did have one.
        vsProg->fragmentMSL.clear();
        vsProg->fragmentReflection = ShaderReflection{};
        vsProg->uniformLayoutComputed = false;
    }
    programName = ppo->vertexProgram;
    return vsProg;
}

GLProgramObject* GLContext::Impl::ensurePipelineTessSynthesizedProgram(
    GLProgramPipelineObject& ppo) {
    // β [metal-tess-TF] orchestrator. Mirrors the link-time tess flow
    // in linkProgram (~line 19101-19228) but sources SPIR-V from the
    // pipeline's separable VS+TCS+TES+FS programs and re-translates
    // with cross-stage info (siblingTesInputSpirv on TCS, force
    // VertexForTessellation on VS, force TessEvalAsCompute +
    // tesePatchVertices on TES). Step 2 lands translation only; the
    // probeTessellationPipeline call (which builds the Metal PSOs and
    // sets metalTessTier) lands in step 3, gated behind a
    // `frameGraph != nullptr` check there. Step-2-only return: a
    // synth program with all MSL strings set but metalTessTier still
    // None, so the caller's tier check fails and we fall through to
    // the existing CPU emulator path — same behaviour as today, just
    // with the translation step proven and instrumented.
    const GLuint vsName = ppo.vertexProgram;
    const GLuint tcsName = ppo.tessControlProgram;
    const GLuint tesName = ppo.tessEvalProgram;
    const GLuint fsName = ppo.fragmentProgram;

    if (tcsName == 0 || tesName == 0) {
        return nullptr;
    }

    const bool snapshotMatches =
        ppo.syntheticTessVsSnapshot == vsName &&
        ppo.syntheticTessTcsSnapshot == tcsName &&
        ppo.syntheticTessTesSnapshot == tesName &&
        ppo.syntheticTessFsSnapshot == fsName;
    if (snapshotMatches && ppo.syntheticTessProbeAttempted) {
        return ppo.syntheticTessProgram.get();
    }

    // Snapshot drift (or first visit). Release the previous synth's
    // retained Metal PSOs before reset — same fields linkProgram
    // releases on relink (~line 18594-18610). Without this, a
    // useProgramStages swap leaks one set of MTLComputePipelineStates
    // per swap.
    if (ppo.syntheticTessProgram != nullptr) {
        GLProgramObject* old = ppo.syntheticTessProgram.get();
        releaseRetainedMetalObject(old->metalTessControlPipelineState);
        old->metalTessControlPipelineState = nullptr;
        releaseRetainedMetalObject(old->metalTessVertexPipelineState);
        old->metalTessVertexPipelineState = nullptr;
        for (auto& entry : old->metalTessVertexPSOCache) {
            releaseRetainedMetalObject(entry.second);
        }
        old->metalTessVertexPSOCache.clear();
        old->metalTessVertexNeedsDescriptor = false;
        releaseRetainedMetalObject(old->metalTessEvalComputePipelineState);
        old->metalTessEvalComputePipelineState = nullptr;
    }
    ppo.syntheticTessProgram.reset();
    ppo.syntheticTessVsSnapshot = vsName;
    ppo.syntheticTessTcsSnapshot = tcsName;
    ppo.syntheticTessTesSnapshot = tesName;
    ppo.syntheticTessFsSnapshot = fsName;
    ppo.syntheticTessProbeAttempted = true;

    GLProgramObject* vsProg = (vsName != 0) ? objects->programs().get(vsName) : nullptr;
    GLProgramObject* tcsProg = objects->programs().get(tcsName);
    GLProgramObject* tesProg = objects->programs().get(tesName);
    GLProgramObject* fsProg = (fsName != 0) ? objects->programs().get(fsName) : nullptr;

    if (tcsProg == nullptr || tesProg == nullptr) {
        if (detectorEnabled()) {
            std::fprintf(stderr,
                "APPGL_DETECTOR lift_pipe_synth abort_no_program "
                "tcs=%u(prog=%p) tes=%u(prog=%p)\n",
                tcsName, (void*)tcsProg, tesName, (void*)tesProg);
        }
        return nullptr;
    }
    if (tcsProg->tessControlSpirv.empty() || tesProg->tessEvalSpirv.empty()) {
        // Separable programs linked before β was introduced (or via a
        // path that didn't preserve SPIR-V). The translation can't
        // proceed; fall back to the CPU path.
        if (detectorEnabled()) {
            std::fprintf(stderr,
                "APPGL_DETECTOR lift_pipe_synth abort_no_spirv "
                "tcs=%u(words=%zu) tes=%u(words=%zu)\n",
                tcsName, tcsProg->tessControlSpirv.size(),
                tesName, tesProg->tessEvalSpirv.size());
        }
        return nullptr;
    }

    // Plumb TCS output_vertices into the TES-as-compute translation
    // (mirrors linkProgram's tcsOutputVertices extraction at
    // ~line 19186). Without this the emitted gl_in stride is 0 and
    // every patch collapses to the buffer origin.
    auto tcsModes = extractTessellationModes(
        tcsProg->tessControlSpirv.data(),
        tcsProg->tessControlSpirv.size());

    ShaderTranslator translator;
    BindingMap bindings;  // graphics-stage default; tess stages live in this layout

    auto synth = std::make_unique<GLProgramObject>();
    synth->hasTessellation = true;
    synth->tessControlOutputVertices = static_cast<GLint>(tcsModes.outputVertices);
    synth->tessGenMode = tesProg->tessGenMode;
    synth->tessGenSpacing = tesProg->tessGenSpacing;
    synth->tessGenVertexOrder = tesProg->tessGenVertexOrder;
    synth->tessGenPointMode = tesProg->tessGenPointMode;

    // 1) TCS — compile with siblingTesInputSpirv so SPIRV-Cross's
    //    helper-API closure walks TES's INPUT interface and
    //    add_msl_shader_outputs the matching slots on TCS's main0_out.
    //    Closes the per-CP buffer stride mismatch (Phase 7 / cluster A).
    {
        TranslatorOptions opts;
        opts.forceTessellation = true;
        opts.siblingTesInputSpirv = tesProg->tessEvalSpirv.data();
        opts.siblingTesInputWordCount = tesProg->tessEvalSpirv.size();
        try {
            std::string log;
            synth->tessControlMSL = translator.spirvToMSL(
                tcsProg->tessControlSpirv.data(),
                tcsProg->tessControlSpirv.size(),
                bindings, &log, opts);
            synth->tessControlReflection = translator.reflect(
                tcsProg->tessControlSpirv.data(),
                tcsProg->tessControlSpirv.size(),
                bindings, nullptr);
        } catch (...) {
            synth->tessControlMSL.clear();
        }
    }

    // 2) TES vertex form — kept for parity with the link-time path
    //    even though the post-isolines-patch compute-only flow only
    //    reads tessEvalAsComputeMSL.
    {
        TranslatorOptions opts;
        opts.forceTessellation = true;
        // tc_barriers cluster: pad TES main0_in to mirror TCS main0_out
        // when TCS uses internal-output reads after barrier(). Without
        // this, per-CP buffer stride mismatches and TES reads at the
        // wrong offset.
        opts.siblingTcsOutputSpirv = tcsProg->tessControlSpirv.data();
        opts.siblingTcsOutputWordCount = tcsProg->tessControlSpirv.size();
        try {
            synth->tessEvalMSL = translator.spirvToMSL(
                tesProg->tessEvalSpirv.data(),
                tesProg->tessEvalSpirv.size(),
                bindings, nullptr, opts);
        } catch (...) {
            synth->tessEvalMSL.clear();
        }
    }

    // 3) VS-as-compute. Required for Phase3 — captures per-vertex VS
    //    output into a buffer the TCS dispatch reads via stage-input.
    //    Skipped if the separable VS didn't preserve SPIR-V (e.g. it
    //    was linked before β added the preservation in step 1a).
    if (vsProg != nullptr && !vsProg->vertexSpirv.empty()) {
        TranslatorOptions opts;
        opts.forceVertexForTessellation = true;
        try {
            std::string log;
            synth->tessVertexAsComputeMSL = translator.spirvToMSL(
                vsProg->vertexSpirv.data(),
                vsProg->vertexSpirv.size(),
                bindings, &log, opts);
            synth->tessVertexAsComputeReflection = translator.reflect(
                vsProg->vertexSpirv.data(),
                vsProg->vertexSpirv.size(),
                bindings, nullptr);
            // Strip the grid_size early-return — `dispatchThreads`
            // produces (0,0,0) for spvStageInputSize on macOS Apple
            // Silicon and the kernel would no-op every thread. Same
            // patch the link-time path applies (~line 19167).
            if (!synth->tessVertexAsComputeMSL.empty()) {
                std::string& mslRef = synth->tessVertexAsComputeMSL;
                const std::string needle =
                    "if (any(gl_GlobalInvocationID >= spvStageInputSize))\n"
                    "        return;";
                const std::size_t pos = mslRef.find(needle);
                if (pos != std::string::npos) {
                    mslRef.replace(pos, needle.size(),
                        "/* AppGL: grid_size early-return stripped */");
                }
            }
        } catch (...) {
            synth->tessVertexAsComputeMSL.clear();
        }
    }

    // 4) TES-as-compute with tesePatchVertices. The compute kernel
    //    consumes a domain-coord buffer + a per-CP VS-output buffer
    //    and writes its output into a TF-capture buffer.
    {
        TranslatorOptions opts;
        opts.forceTessellation = true;
        opts.forceTessEvalAsCompute = true;
        opts.tesePatchVertices = static_cast<std::uint32_t>(tcsModes.outputVertices);
        // tc_barriers cluster: same per-CP stride alignment as the
        // vertex-form translation above — applies to compute form too.
        opts.siblingTcsOutputSpirv = tcsProg->tessControlSpirv.data();
        opts.siblingTcsOutputWordCount = tcsProg->tessControlSpirv.size();
        try {
            synth->tessEvalAsComputeMSL = translator.spirvToMSL(
                tesProg->tessEvalSpirv.data(),
                tesProg->tessEvalSpirv.size(),
                bindings, nullptr, opts);
            synth->tessEvalAsComputeReflection = translator.reflect(
                tesProg->tessEvalSpirv.data(),
                tesProg->tessEvalSpirv.size(),
                bindings, nullptr);
            // Reflect the TES output struct layout for the TF writer.
            synth->tessEvalOutputLayout =
                translator.reflectStageOutputLayout(
                    tesProg->tessEvalSpirv.data(),
                    tesProg->tessEvalSpirv.size(),
                    opts);
        } catch (...) {
            synth->tessEvalAsComputeMSL.clear();
        }
    }

    // 5) FS + VS render-form MSL — copy from separable programs (already
    //    translated at separable-link time). Mirror the resolveDrawProgram
    //    pattern for non-tess pipeline-bound draws.
    if (fsProg != nullptr) {
        synth->fragmentMSL = fsProg->fragmentMSL;
        synth->fragmentReflection = fsProg->fragmentReflection;
    }
    if (vsProg != nullptr) {
        synth->vertexMSL = vsProg->vertexMSL;
        synth->vertexReflection = vsProg->vertexReflection;
    }

    // Carry SPIR-V onto the synth program so any downstream emulator
    // path that wants it (TessellationEmulator parsed-module cache,
    // CPU TF writer counter formulas) can find it without reaching
    // back across separable program boundaries.
    synth->vertexSpirv = vsProg ? vsProg->vertexSpirv : std::vector<std::uint32_t>{};
    synth->tessControlSpirv = tcsProg->tessControlSpirv;
    synth->tessEvalSpirv = tesProg->tessEvalSpirv;

    // TF varying names live on the TES separable program (linked
    // there via glTransformFeedbackVaryings or in-shader xfb_buffer
    // qualifiers). The Metal TF writer reads this list to find each
    // varying inside the TES output struct.
    synth->transformFeedbackVaryingNames = tesProg->transformFeedbackVaryingNames;
    synth->transformFeedbackBufferMode = tesProg->transformFeedbackBufferMode;

    // Step 3 — run the same Metal tess probe linkProgram does, but
    // against the synthesised cross-stage MSL. Stash retained PSOs +
    // metalTessTier so the caller's gate (line ~23011) engages and
    // `tryMetalTessellationDraw` runs the encoder against this synth
    // program.
    bool probeOk = false;
    int probeVcOk = 0, probeTecOk = 0, probeRenderOk = 0;
    std::string probeDiag;
    if (frameGraph != nullptr &&
        !synth->tessControlMSL.empty() &&
        (!synth->tessEvalMSL.empty() ||
         !synth->tessEvalAsComputeMSL.empty()) &&
        !synth->fragmentMSL.empty()) {
        MetalFrameGraph::TessPipelineProbeResult probe =
            frameGraph->probeTessellationPipeline(
                synth->tessControlMSL,
                synth->tessEvalMSL,
                synth->fragmentMSL,
                synth->tessGenMode,
                synth->tessGenSpacing,
                synth->tessGenVertexOrder,
                synth->tessVertexAsComputeMSL,
                synth->tessEvalAsComputeMSL);
        probeVcOk = probe.vertexComputeOk ? 1 : 0;
        probeTecOk = probe.tessEvalComputeOk ? 1 : 0;
        probeRenderOk = probe.renderOk ? 1 : 0;
        probeDiag = probe.diagnostic;

        if (probe.vertexComputeOk) {
            synth->metalTessVertexPipelineState = probe.vertexComputePipelineState;
        }
        if (probe.tessEvalComputeOk) {
            synth->metalTessEvalComputePipelineState = probe.tessEvalComputePipelineState;
        }
        // Mirror linkProgram's tier classification (line ~19378). The
        // pipeline-bound tess path is always Phase3 — the test surface
        // (gl_MaxPatchVertices / data_pass_through / etc.) declares
        // VS-input, per-CP, or per-patch buffers that the Phase-2 code
        // path can't carry. Use the same handleability scan as
        // linkProgram.
        const bool needsPhase3 =
            probe.computeOk && (
                synth->tessControlMSL.find("spvIn [[buffer(") != std::string::npos ||
                synth->tessControlMSL.find("spvOut [[buffer(") != std::string::npos ||
                synth->tessControlMSL.find("spvPatchOut [[buffer(") != std::string::npos ||
                synth->tessEvalMSL.find("spvIn [[buffer(") != std::string::npos ||
                synth->tessEvalMSL.find("spvPatchIn [[buffer(") != std::string::npos);

        if (probe.computeOk && needsPhase3 && probe.vertexComputeOk) {
            synth->metalTessTier = GLProgramObject::MetalTessTier::Phase3;
            synth->metalTessControlPipelineState = probe.computePipelineState;
            probeOk = true;
        } else if (probe.computeOk && !needsPhase3) {
            synth->metalTessTier = GLProgramObject::MetalTessTier::Phase2;
            synth->metalTessControlPipelineState = probe.computePipelineState;
            probeOk = true;
        } else if (probe.computeOk) {
            // Phase3 needed but VS-compute PSO didn't build. Release
            // the orphan TCS PSO so we don't leak. Synth's
            // metalTessTier stays None → caller's gate fails → CPU
            // path runs (same as combined-program failure mode).
            releaseRetainedMetalObject(probe.computePipelineState);
        }
    } else if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_pipe_synth probe_skipped "
            "frameGraph=%d tcsMSL=%d teMSL=%d teCompMSL=%d fsMSL=%d\n",
            frameGraph != nullptr ? 1 : 0,
            synth->tessControlMSL.empty() ? 0 : 1,
            synth->tessEvalMSL.empty() ? 0 : 1,
            synth->tessEvalAsComputeMSL.empty() ? 0 : 1,
            synth->fragmentMSL.empty() ? 0 : 1);
    }

    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_pipe_synth translate "
            "vs=%u tcs=%u tes=%u fs=%u "
            "msl_sizes=[v=%zu,tc=%zu,te=%zu,fs=%zu,vc=%zu,tec=%zu] "
            "tcs_outputVertices=%d tessGenMode=0x%04X "
            "outLayout_struct=%zu tfVaryings=%zu "
            "probe=[ok=%d vcOk=%d tecOk=%d renderOk=%d tier=%d] diag=\"%.120s\"\n",
            vsName, tcsName, tesName, fsName,
            synth->vertexMSL.size(),
            synth->tessControlMSL.size(),
            synth->tessEvalMSL.size(),
            synth->fragmentMSL.size(),
            synth->tessVertexAsComputeMSL.size(),
            synth->tessEvalAsComputeMSL.size(),
            (int)tcsModes.outputVertices,
            (unsigned)synth->tessGenMode,
            synth->tessEvalOutputLayout.structSize,
            synth->transformFeedbackVaryingNames.size(),
            probeOk ? 1 : 0,
            probeVcOk, probeTecOk, probeRenderOk,
            (int)synth->metalTessTier,
            probeDiag.c_str());
    }

    ppo.syntheticTessProgram = std::move(synth);
    return ppo.syntheticTessProgram.get();
}

bool GLContext::Impl::tryMetalTessellationDraw(GLProgramObject& program,
                                                GLuint programName,
                                                GLenum mode,
                                                GLsizei count,
                                                GLint first,
                                                GLsizei instanceCount,
                                                GLuint baseInstance)
{
    (void)first;
    if (mode != GL_PATCHES) return false;
    if (program.metalTessControlPipelineState == nullptr) return false;
    // Widened post-isolines-compute-bypass (SPIRV-Cross 095c99c): allow
    // empty `tessEvalMSL` (conventional render-vertex form) when the
    // as-compute form is present. Isolines TES emits valid kernel MSL
    // but no render form because Metal doesn't support isoline tess in
    // the render pipeline. The compute chain doesn't need the render
    // form — it dispatches TES-as-compute directly into the TF buffer.
    if (program.tessControlMSL.empty() ||
        (program.tessEvalMSL.empty() && program.tessEvalAsComputeMSL.empty()) ||
        program.fragmentMSL.empty()) {
        return false;
    }
    if (program.tessControlOutputVertices <= 0) return false;

    // Phase 3B.5 [metal-tess-TF]: transform feedback on tess draws
    // is wired when (a) the env flag is set, (b) the program has a
    // built TES-compute PSO, and (c) the TES output layout was
    // reflected. If those conditions hold, the Metal path runs the
    // full compute chain + deposits TF bytes on CPU. Otherwise we
    // defer to the CPU tessellation interpreter.
    // Phase 4 [metal-tess-TF]: isolines domain-gen is live, but the
    // invariance + vertex_spacing tests probe correctness beyond the
    // per-patch vertex count (symmetry around axis, exact fractional
    // spacing rounding, …). Our domain-gen isn't exact enough yet —
    // keep uniform-using programs on the CPU tessellator to preserve
    // 3B.5's wins until the tess correctness gap closes.
    const bool tessUsesUniforms =
        program.tessControlMSL.find("_DefaultUniforms") != std::string::npos ||
        program.tessEvalAsComputeMSL.find("_DefaultUniforms") != std::string::npos ||
        program.tessVertexAsComputeMSL.find("_DefaultUniforms") != std::string::npos;
    // Phase 5 probe-only env: APPGL_LIFT_TESS_UNIFORM_GUARD routes
    // uniform-using tess programs through Metal instead of the CPU
    // fallback. Net delta with this env on is -13 (6 invariance +
    // 8 vertex_spacing regress, 1 tessellation_shader_tessellation
    // win) because our Metal domain-gen output disagrees with CTS
    // counter-program probe counts for several (mode, spacing,
    // level) combinations. Off by default — Phase 5 proper needs a
    // tess-spec-exact rewrite of `spvGenTessDomain` + counter-
    // program routing to match. Left in for future ratcheting.
    const bool liftUniformGuard = std::getenv("APPGL_LIFT_TESS_UNIFORM_GUARD") != nullptr;
    const bool tessTFActive =
        transformFeedbackActive &&
        program.metalTessEvalComputePipelineState != nullptr &&
        program.tessEvalOutputLayout.structSize > 0 &&
        (liftUniformGuard || !tessUsesUniforms) &&
        std::getenv("APPGL_ENABLE_METAL_TESS_TF") != nullptr;
    // Detector point B — gate-evaluation instrumentation paired with link
    // probe (A) and dispatch (C). Logs every reach of this gate plus the
    // tier classification + rasterizer-discard state so post-processors
    // can answer: "did the LIFT path actually engage, and if not, why?"
    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_gate prog=%u mode=0x%04X count=%d tier=%d "
            "tessUsesUniforms=%d liftGuard=%d enableMetalTF=%d "
            "compPSO=%d tesOutSize=%zu tfActive=%d rasterDiscard=%d "
            "-> tessTFActive=%d\n",
            static_cast<unsigned int>(programName),
            static_cast<unsigned int>(mode),
            static_cast<int>(count),
            static_cast<int>(program.metalTessTier),
            tessUsesUniforms ? 1 : 0,
            liftUniformGuard ? 1 : 0,
            std::getenv("APPGL_ENABLE_METAL_TESS_TF") != nullptr ? 1 : 0,
            program.metalTessEvalComputePipelineState != nullptr ? 1 : 0,
            program.tessEvalOutputLayout.structSize,
            transformFeedbackActive ? 1 : 0,
            state->isEnabled(GL_RASTERIZER_DISCARD) ? 1 : 0,
            tessTFActive ? 1 : 0);
    }
    if (transformFeedbackActive && !tessTFActive) {
        return false;
    }
    // Rasterizer-discard is usually paired with TF. When the TF-
    // capture chain is wired, we still run it (the render pass
    // below is skipped naturally because the test is side-effect
    // only). When unwired, defer to CPU.
    //
    // Phase 5 probe: with APPGL_LIFT_TESS_UNIFORM_GUARD, the CTS
    // tess vertex-counter program's probe drawArrays (DISCARD on,
    // TF off, PRIMITIVES_GENERATED query active) needs to take the
    // same Metal compute chain so its count matches the subsequent
    // Metal TF-capture draw. Otherwise counter goes CPU, main goes
    // Metal, buffer sized by CPU count, Metal overflow = TF_WRITTEN
    // comes back 0.
    const bool keepMetalForDiscardProbe = liftUniformGuard &&
        program.metalTessEvalComputePipelineState != nullptr &&
        std::getenv("APPGL_ENABLE_METAL_TESS_TF") != nullptr;
    if (state->isEnabled(GL_RASTERIZER_DISCARD) && !tessTFActive &&
        !keepMetalForDiscardProbe) {
        return false;
    }

    const GLint pv = state->tessellationState().patchVertices;
    if (pv <= 0 || count < pv) return false;
    const GLsizei patchCount = count / pv;
    if (patchCount <= 0) return false;

    MetalTessDrawInfo info;
    info.tessControlPipelineState = program.metalTessControlPipelineState;
    if (program.metalTessTier == GLProgramObject::MetalTessTier::Phase3) {
        info.vertexComputePipelineState = program.metalTessVertexPipelineState;
    }

    // T4I [metal-tess-TF]: when the VS-as-compute MSL declares
    // `[[stage_in]]`, build/cache the PSO from the bound VAO's
    // descriptor before encode. Per-program, per-VAO-hash cache so
    // VAO swaps don't pay the build cost twice.
    if (program.metalTessTier == GLProgramObject::MetalTessTier::Phase3 &&
        program.metalTessVertexNeedsDescriptor &&
        info.vertexComputePipelineState == nullptr) {
        const GLuint vaoName = state->boundVertexArray();
        GLVertexArrayObject* vao = objects->vertexArrays().get(vaoName);
        if (vao == nullptr) {
            return false;
        }
        appgl::MetalVertexDescriptorBuildResult buildResult =
            appgl::buildMetalStageInputOutputDescriptor(*vao);
        if (buildResult.descriptor == nullptr) {
            return false;
        }
        void* vsPSO = nullptr;
        auto cached = program.metalTessVertexPSOCache.find(buildResult.hash);
        if (cached != program.metalTessVertexPSOCache.end()) {
            vsPSO = cached->second;
        } else {
            std::string err;
            vsPSO = frameGraph->buildComputePipelineState(
                program.tessVertexAsComputeMSL, &err, nullptr,
                buildResult.descriptor);
            if (vsPSO != nullptr) {
                program.metalTessVertexPSOCache[buildResult.hash] = vsPSO;
            } else if (std::getenv("APPGL_TRACE_TESS")) {
                std::fprintf(stderr,
                    "[APPGL] T4I draw-time VS-compute PSO build failed: %s\n",
                    err.c_str());
            }
        }
        appgl::releaseMetalStageInputOutputDescriptor(buildResult.descriptor);
        if (vsPSO == nullptr) {
            return false;
        }
        info.vertexComputePipelineState = vsPSO;
        // Resolve buffer bindings for the encoder.
        for (const auto& binding : buildResult.vertexBufferBindings) {
            GLBufferObject* vbo = objects->buffers().get(binding.glBuffer);
            if (vbo == nullptr || vbo->metalBuffer == nullptr) {
                if (std::getenv("APPGL_TRACE_TESS")) {
                    std::fprintf(stderr,
                        "[APPGL] T4I draw-time VBO resolve failed: glBuffer=%u\n",
                        binding.glBuffer);
                }
                return false;
            }
            MetalTessVertexBufferBinding ent;
            ent.metalBuffer = vbo->metalBuffer;
            ent.offset = 0;
            ent.metalSlot = binding.metalSlot;
            info.vertexComputeBufferBindings.push_back(ent);
        }
        if (std::getenv("APPGL_TRACE_TESS")) {
            std::fprintf(stderr,
                "[APPGL] T4I draw-time vsPSO=%p hash=%s bindings=%zu\n",
                vsPSO, buildResult.hash.c_str(),
                info.vertexComputeBufferBindings.size());
            for (const auto& b : info.vertexComputeBufferBindings) {
                std::fprintf(stderr,
                    "[APPGL] T4I   binding slot=%u buf=%p\n",
                    b.metalSlot, b.metalBuffer);
            }
        }
    }
    // Phase 3B.4 [metal-tess-TF]: forward the TES-as-compute PSO if
    // the link-time probe built one. The encoder only runs the
    // domain-gen + TES-compute dispatches when
    // `APPGL_ENABLE_METAL_TESS_TF` is set; without that env the PSO
    // slot is ignored and the render path runs unchanged.
    info.tessEvalComputePipelineState =
        program.metalTessEvalComputePipelineState;
    info.tessEvalMSL = &program.tessEvalMSL;
    info.fragmentMSL = &program.fragmentMSL;
    info.patchCount = patchCount;
    info.patchVertices = pv;
    // Sprint 5 Phase 1 — synth TCS host-populate signal: snapshot
    // glPatchParameterfv state for the encoder to override synth TCS's
    // 1.0 defaults in factorBufFull.
    info.tessControlSynthesized = program.tessControlSynthesized;
    if (program.tessControlSynthesized) {
        const auto& tessState = state->tessellationState();
        for (int i = 0; i < 4; ++i)
            info.defaultOuterLevel[i] = tessState.defaultOuterLevel[i];
        for (int i = 0; i < 2; ++i)
            info.defaultInnerLevel[i] = tessState.defaultInnerLevel[i];
    }
    info.tessControlOutputVertices = program.tessControlOutputVertices;
    info.genMode = program.tessGenMode;
    info.genSpacing = program.tessGenSpacing;
    info.genVertexOrder = program.tessGenVertexOrder;
    info.pointMode = (program.tessGenPointMode == GL_TRUE);
    info.instanceCount = instanceCount > 0 ? instanceCount : 1;
    info.baseInstance = baseInstance;
    info.program = programName;

    // Phase 4 [metal-tess-TF]: pack default uniforms for each tess
    // compute stage so the TCS / VS-compute / TES-compute kernels
    // read glUniform* values. Layout is computed lazily once per
    // program. Only runs when the program actually references
    // _DefaultUniforms in its compute MSL — otherwise we skip the
    // per-draw pack cost.
    // Phase 5 opt-in path: when APPGL_LIFT_TESS_UNIFORM_GUARD is
    // set, pack the default uniforms so the Metal path feeds the
    // right tess factors to TCS/VS-compute/TES-compute.
    thread_local std::vector<std::uint8_t> tcsUniformScratch;
    thread_local std::vector<std::uint8_t> vsComputeUniformScratch;
    thread_local std::vector<std::uint8_t> tesComputeUniformScratch;
    // Phase 5 probe: pack uniforms for ANY Metal-routed tess draw
    // when env lifted, not just TF-active ones. The CTS counter
    // probe is non-TF but still needs accurate tess factors or its
    // PRIMITIVES_GENERATED count won't match the subsequent TF
    // draws.
    const bool packUniformsForThisDraw = liftUniformGuard && tessUsesUniforms &&
        program.metalTessEvalComputePipelineState != nullptr &&
        program.tessEvalOutputLayout.structSize > 0 &&
        std::getenv("APPGL_ENABLE_METAL_TESS_TF") != nullptr;
    if (packUniformsForThisDraw) {
        if (program.tessControlUniformLayout.empty() &&
            !program.tessControlReflection.uniformBlocks.empty()) {
            computeStageUniformLayout(program.tessControlUniformLayout,
                program.tessControlReflection, program.uniforms);
        }
        if (program.tessVertexAsComputeUniformLayout.empty() &&
            !program.tessVertexAsComputeReflection.uniformBlocks.empty()) {
            computeStageUniformLayout(program.tessVertexAsComputeUniformLayout,
                program.tessVertexAsComputeReflection, program.uniforms);
        }
        if (program.tessEvalAsComputeUniformLayout.empty() &&
            !program.tessEvalAsComputeReflection.uniformBlocks.empty()) {
            computeStageUniformLayout(program.tessEvalAsComputeUniformLayout,
                program.tessEvalAsComputeReflection, program.uniforms);
        }
        if (!program.tessControlUniformLayout.empty()) {
            buildStageUniformBuffer(tcsUniformScratch,
                program.tessControlReflection, program.uniformValues,
                program.tessControlUniformLayout);
            info.tessControlUniformData = tcsUniformScratch.data();
            info.tessControlUniformSize = tcsUniformScratch.size();
            if (std::getenv("APPGL_DUMP_TESOUT")) {
                std::fprintf(stderr,
                    "APPGL_DETECTOR tcs_uniform_pack prog=%u size=%zu",
                    (unsigned)programName, tcsUniformScratch.size());
                const std::size_t kPrintBytes =
                    tcsUniformScratch.size() < 64u
                        ? tcsUniformScratch.size() : 64u;
                std::fprintf(stderr, " bytes=");
                for (std::size_t i = 0; i + 4 <= kPrintBytes; i += 4) {
                    float f;
                    std::memcpy(&f, tcsUniformScratch.data() + i, sizeof(f));
                    std::fprintf(stderr, "%.4f ", f);
                }
                std::fprintf(stderr, "\n");
            }
        }
        if (!program.tessVertexAsComputeUniformLayout.empty()) {
            buildStageUniformBuffer(vsComputeUniformScratch,
                program.tessVertexAsComputeReflection, program.uniformValues,
                program.tessVertexAsComputeUniformLayout);
            info.tessVertexAsComputeUniformData = vsComputeUniformScratch.data();
            info.tessVertexAsComputeUniformSize = vsComputeUniformScratch.size();
        }
        if (!program.tessEvalAsComputeUniformLayout.empty()) {
            buildStageUniformBuffer(tesComputeUniformScratch,
                program.tessEvalAsComputeReflection, program.uniformValues,
                program.tessEvalAsComputeUniformLayout);
            info.tessEvalAsComputeUniformData = tesComputeUniformScratch.data();
            info.tessEvalAsComputeUniformSize = tesComputeUniformScratch.size();
        }
    }

    // Fixed-function state snapshot (mirrors
    // populateTranslatedDrawFixedFunctionState but scoped to the
    // minimum Phase 2 needs).
    info.depthTestEnabled = state->isEnabled(GL_DEPTH_TEST);
    info.depthFunc = state->depthState().func;
    info.depthWriteMask = (state->depthState().writeMask != GL_FALSE);
    info.cullFaceEnabled = state->isEnabled(GL_CULL_FACE);
    info.cullFaceMode = state->rasterState().cullFaceMode;
    info.frontFace = state->rasterState().frontFace;
    // Sprint 7 Phase 1 #11 (CKPT57): tess Phase-2 render encoder
    // stencil state — required for primitive_coverage's two-phase
    // stencil-replace + stencil-notequal pattern. Same shape as the
    // translated-draw populator.
    {
        const auto& gs = state->stencilState();
        info.stencilTestEnabled = state->isEnabled(GL_STENCIL_TEST);
        info.stencilFrontFunc = gs.front.func;
        info.stencilFrontRef = gs.front.ref;
        info.stencilFrontValueMask = gs.front.valueMask;
        info.stencilFrontFail = gs.front.fail;
        info.stencilFrontDepthFail = gs.front.depthFail;
        info.stencilFrontDepthPass = gs.front.depthPass;
        info.stencilFrontWriteMask = gs.front.writeMask;
        info.stencilBackFunc = gs.back.func;
        info.stencilBackRef = gs.back.ref;
        info.stencilBackValueMask = gs.back.valueMask;
        info.stencilBackFail = gs.back.fail;
        info.stencilBackDepthFail = gs.back.depthFail;
        info.stencilBackDepthPass = gs.back.depthPass;
        info.stencilBackWriteMask = gs.back.writeMask;
    }

    const auto& vp = state->viewport();
    info.viewportX = vp.x;
    info.viewportY = vp.y;
    info.viewportWidth = vp.width;
    info.viewportHeight = vp.height;
    const auto& dr = state->depthRange();
    info.depthRangeNear = dr.nearValue;
    info.depthRangeFar = dr.farValue;

    info.scissorTestEnabled = state->isEnabled(GL_SCISSOR_TEST);
    const auto& sc = state->scissor();
    info.scissorX = sc.x;
    info.scissorY = sc.y;
    info.scissorWidth = sc.width;
    info.scissorHeight = sc.height;

    // FBO target resolution — reuse the same helper the translated
    // draw path uses. Phase 2 ignores MRT + layered + slice state
    // because winding.triangles_ccw draws to a single-attachment FBO.
    GLsizei fboW = 0, fboH = 0;
    void* fboDSTex = nullptr;
    void* fboColTex = resolveFBOColorTarget(fboW, fboH, fboDSTex);
    if (fboColTex != nullptr || fboDSTex != nullptr) {
        info.fboColorTexture = fboColTex;
        info.fboDepthStencilTexture = fboDSTex;
    }

    // Phase 3B.5 [metal-tess-TF]: when the Metal tess-TF path is
    // active and the program has a TES-compute PSO, wire the
    // encoder's out-params so we can walk the produced vertex
    // buffer + deposit TF bytes after the encode completes.
    std::uint32_t tfGeneratedVerts = 0;
    void* tfRetainedOutBuf = nullptr;
    // NOTE: this intentionally fires on ANY tess draw that reaches
    // this point with the compute chain wired — including non-TF
    // draws — because `writeTessTFAndUpdateCounters` below updates
    // PRIMITIVES_GENERATED from the domain-gen vertex count, and
    // CTS tests compare that count against expected vs actual
    // iteration counts (invariance_rule*, vertex_spacing_*). When
    // TF is inactive the internal `doTF` check still skips the
    // actual TF buffer write.
    const bool runTessTFWrite =
        program.metalTessEvalComputePipelineState != nullptr &&
        program.tessEvalOutputLayout.structSize > 0 &&
        std::getenv("APPGL_ENABLE_METAL_TESS_TF") != nullptr;
    if (runTessTFWrite) {
        info.outGeneratedVertCount = &tfGeneratedVerts;
        info.outTesComputeOutBuf = &tfRetainedOutBuf;
    }
    // T4F bail-trace: log the runTessTFWrite inputs at the gate so we
    // can pinpoint where the pipeline-path main draw bails on its way
    // from lift_gate to writeTessTFAndUpdateCounters. For pipeline-
    // resolved program (resolveDrawProgram returns VS container), the
    // tess metadata fields may be null/empty — runTessTFWrite collapses
    // to false, encoder runs but writeTessTFAndUpdateCounters is never
    // called → TF buffer stays at zero-init.
    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_pre_encode prog=%u "
            "metalTessEvalComputePSO_present=%d tesOutSize=%zu "
            "enableMetalTF=%d -> runTessTFWrite=%d\n",
            (unsigned)programName,
            program.metalTessEvalComputePipelineState != nullptr ? 1 : 0,
            program.tessEvalOutputLayout.structSize,
            std::getenv("APPGL_ENABLE_METAL_TESS_TF") != nullptr ? 1 : 0,
            runTessTFWrite ? 1 : 0);
    }

    const bool encodeOk = frameGraph->encodeMetalTessellationDraw(info);

    if (detectorEnabled()) {
        std::fprintf(stderr,
            "APPGL_DETECTOR lift_post_encode prog=%u encodeOk=%d "
            "tfGeneratedVerts=%u tfRetainedOutBuf_present=%d "
            "-> writeTess_will_fire=%d\n",
            (unsigned)programName,
            encodeOk ? 1 : 0,
            (unsigned)tfGeneratedVerts,
            tfRetainedOutBuf != nullptr ? 1 : 0,
            (runTessTFWrite && tfGeneratedVerts > 0 && tfRetainedOutBuf != nullptr) ? 1 : 0);
    }

    if (runTessTFWrite && tfGeneratedVerts > 0 && tfRetainedOutBuf != nullptr) {
        id<MTLBuffer> tesOut =
            (id<MTLBuffer>)CFBridgingRelease(tfRetainedOutBuf);
        const std::uint8_t* bytes =
            static_cast<const std::uint8_t*>([tesOut contents]);
        // Per-vertex slot size = reflected struct size. The TES
        // compute kernel writes `spvOut[gl_GlobalInvocationID.x]`
        // with this stride (Metal lays out arrays of structs packed
        // at `sizeof(main0_out)`); the 256-byte over-allocation in
        // the encoder just sizes the total buffer, not the stride.
        const std::size_t kTesComputeSlotBytes =
            program.tessEvalOutputLayout.structSize;
        // Topology from TES genMode: point_mode→GL_POINTS,
        // isolines→GL_LINES, else GL_TRIANGLES.
        GLenum topo = GL_TRIANGLES;
        if (program.tessGenPointMode == GL_TRUE) {
            topo = GL_POINTS;
        } else if (program.tessGenMode == GL_ISOLINES) {
            topo = GL_LINES;
        }
        writeTessTFAndUpdateCounters(program, bytes,
                                      tfGeneratedVerts,
                                      kTesComputeSlotBytes, topo);
        (void)tesOut;  // released by __bridge_transfer at scope exit
    }

    return encodeOk;
}

bool GLContext::Impl::tryMetalMeshGSDraw(GLProgramObject& program,
                                          GLuint programName,
                                          GLenum mode,
                                          GLsizei count,
                                          GLint first)
{
    (void)programName;
    (void)first;
    // MVP envelope guard. Phase 2 currently handles GL_POINTS draws
    // only — covers all 6 conversion-target failing tests
    // (gl_pointsize_value + 5 limits/api point-output cases). Lines
    // and triangles input land in a follow-up once point flow is
    // proven end-to-end.
    if (mode != GL_POINTS) return false;
    if (count <= 0) return false;
    if (program.metalGSTier != GLProgramObject::MetalGSTier::MeshShader) {
        return false;
    }
    if (program.metalGSVsComputePipelineState == nullptr ||
        program.metalGSMeshFunction == nullptr ||
        program.metalGSFragmentFunction == nullptr) {
        return false;
    }
    if (std::getenv("APPGL_TRACE_MESH_GS") != nullptr) {
        std::fprintf(stderr,
            "[MESH_GS] tryMetalMeshGSDraw enter: prog=%u mode=0x%X count=%d\n",
            programName, mode, count);
        std::fflush(stderr);
    }

    // Resolve current FBO color + depth/stencil targets. Mirrors the
    // pattern used by encodeTranslatedDraw at the drawArrays call site.
    GLsizei fboW = 0, fboH = 0;
    void* fboDSTex = nullptr;
    std::uint32_t fboArrayLen = 0;
    void* fboColTex = resolveFBOColorTarget(fboW, fboH, fboDSTex, &fboArrayLen);
    if (fboColTex == nullptr) return false;

    appgl::MetalFrameGraph::MetalMeshGSDrawInfo info;
    info.vertexComputePipelineState = program.metalGSVsComputePipelineState;
    info.meshFunction = program.metalGSMeshFunction;
    info.fragmentFunction = program.metalGSFragmentFunction;
    info.meshPipelineStateInOut = &program.metalGSMeshPipelineState;
    info.vertexCount = static_cast<std::uint32_t>(count);
    info.primitiveCount = static_cast<std::uint32_t>(count);
    info.inputVerticesPerPrimitive = 1;
    info.outputTopologyMTLPrimitiveType = MTLPrimitiveTypePoint;
    info.vsOutputStrideBytes = 256;
    info.fboColorTexture = fboColTex;
    info.fboDepthStencilTexture = fboDSTex;
    info.fboWidth = static_cast<std::uint32_t>(fboW);
    info.fboHeight = static_cast<std::uint32_t>(fboH);
    info.fboColorArrayLength = fboArrayLen;

    // Per-stage default-uniform buffers. Compute the per-stage
    // layouts lazily (cached on the program) and write the current
    // uniform values through `buildStageUniformBuffer` — same path
    // the legacy translated-draw site uses (GLContext.mm:23992-23996).
    // For Phase-2 MVP the 6 conversion-target GS bodies don't
    // reference _DefaultUniforms (verified against the emitted mesh
    // MSL: no `constant _DefaultUniforms&` parameter), so meshUniform*
    // stays nullptr; if a future target does reference defaults from
    // the GS the same plumbing extends to the geometry stage.
    if (!program.uniformLayoutComputed) {
        computeStageUniformLayout(program.vertexUniformLayout,
            program.vertexReflection, program.uniforms);
        computeStageUniformLayout(program.fragmentUniformLayout,
            program.fragmentReflection, program.uniforms);
        program.uniformLayoutComputed = true;
    }
    thread_local std::vector<std::uint8_t> meshGsVtxUniformScratch;
    thread_local std::vector<std::uint8_t> meshGsFragUniformScratch;
    pushSynthesizedMatrixUniforms(program, matrixState);
    buildStageUniformBuffer(meshGsVtxUniformScratch,
        program.vertexReflection, program.uniformValues,
        program.vertexUniformLayout);
    buildStageUniformBuffer(meshGsFragUniformScratch,
        program.fragmentReflection, program.uniformValues,
        program.fragmentUniformLayout);
    info.vsUniformData = meshGsVtxUniformScratch.data();
    info.vsUniformSize = meshGsVtxUniformScratch.size();
    info.fsUniformData = meshGsFragUniformScratch.data();
    info.fsUniformSize = meshGsFragUniformScratch.size();
    info.meshUniformData = nullptr;
    info.meshUniformSize = 0;

    // GL render state — mirror encodeTranslatedDraw's tdi setup
    // (GLContext.mm:22172-22217) for the fields the mesh-render
    // encoder applies. Sourced from the same `state` (GLStateTracker)
    // accessor the legacy path uses.
    info.depthTestEnabled = state->isEnabled(GL_DEPTH_TEST);
    info.depthFunc = state->depthState().func;
    info.depthWriteMask = (state->depthState().writeMask != GL_FALSE);
    // Sprint 7 Phase 1 #11 (CKPT57): stencil state for mesh-GS path.
    {
        const auto& gs = state->stencilState();
        info.stencilTestEnabled = state->isEnabled(GL_STENCIL_TEST);
        info.stencilFrontFunc = gs.front.func;
        info.stencilFrontRef = gs.front.ref;
        info.stencilFrontValueMask = gs.front.valueMask;
        info.stencilFrontFail = gs.front.fail;
        info.stencilFrontDepthFail = gs.front.depthFail;
        info.stencilFrontDepthPass = gs.front.depthPass;
        info.stencilFrontWriteMask = gs.front.writeMask;
        info.stencilBackFunc = gs.back.func;
        info.stencilBackRef = gs.back.ref;
        info.stencilBackValueMask = gs.back.valueMask;
        info.stencilBackFail = gs.back.fail;
        info.stencilBackDepthFail = gs.back.depthFail;
        info.stencilBackDepthPass = gs.back.depthPass;
        info.stencilBackWriteMask = gs.back.writeMask;
    }
    info.cullFaceEnabled = state->isEnabled(GL_CULL_FACE);
    info.cullFaceMode = state->rasterState().cullFaceMode;
    info.frontFace = state->rasterState().frontFace;
    info.wireframe = (state->rasterState().polygonFillMode == GL_LINE);
    info.polygonOffsetEnabled =
        state->isEnabled(GL_POLYGON_OFFSET_FILL) ||
        state->isEnabled(GL_POLYGON_OFFSET_LINE) ||
        state->isEnabled(GL_POLYGON_OFFSET_POINT);
    info.polygonOffsetFactor = state->rasterState().polygonOffsetFactor;
    info.polygonOffsetUnits = state->rasterState().polygonOffsetUnits;
    info.polygonOffsetClamp = state->rasterState().polygonOffsetClamp;
    {
        const auto& vp = state->viewport();
        info.viewportX = vp.x;
        info.viewportY = vp.y;
        info.viewportWidth = vp.width;
        info.viewportHeight = vp.height;
    }
    {
        const auto& dr = state->depthRange();
        info.depthRangeNear = dr.nearValue;
        info.depthRangeFar = dr.farValue;
    }
    info.scissorTestEnabled = state->isEnabled(GL_SCISSOR_TEST);
    {
        const auto& sc = state->scissor();
        info.scissorX = sc.x;
        info.scissorY = sc.y;
        info.scissorWidth = sc.width;
        info.scissorHeight = sc.height;
    }
    // Sprint 17 Day 3+ BONUS-1 [clip_control]: snapshot
    // glClipControl origin for the mesh-GS path's viewport-Y-flip
    // gate. Sister to TranslatedDrawInfo's clipOrigin set in the
    // legacy path.
    info.clipOrigin = static_cast<std::uint32_t>(state->clipOrigin());

    const bool ok = frameGraph->encodeMetalMeshGSDraw(info);
    if (std::getenv("APPGL_TRACE_MESH_GS") != nullptr) {
        std::fprintf(stderr,
            "[MESH_GS] encodeMetalMeshGSDraw rc=%d diag=\"%s\"\n",
            ok ? 1 : 0, info.diagnostic.c_str());
        std::fflush(stderr);
    }
    return ok;
}

bool GLContext::Impl::encodeEmulatedGsDraw(GLProgramObject& program,
                                           GLuint programName,
                                           const appgl::EmulatedDraw& ed)
{
    // Resolve the FBO's layered-attachment state before we decide
    // whether the synth VS should emit `[[render_target_array_index]]`.
    // A GS that writes gl_Layer but targets a non-layered FBO
    // must NOT emit the render-target-array-index slot — Metal
    // rejects the combination of MSL writing that slot while
    // renderTargetArrayLength=0 and drops every fragment.
    GLsizei preFboW = 0, preFboH = 0;
    void* preFboDSTex = nullptr;
    std::uint32_t preFboArrayLen = 0;
    void* preFboColTex = resolveFBOColorTarget(preFboW, preFboH, preFboDSTex, &preFboArrayLen);
    const bool fboIsLayered = (preFboColTex != nullptr && preFboArrayLen > 0);
    const bool routeLayer = ed.hasLayer && fboIsLayered;
    // Sprint 15 Day 10 [metal-viewport-array]: detect multi-viewport
    // binding (state divergence from slot 0). Originally env-gated on
    // `APPGL_ENABLE_METAL_VIEWPORT_INDEX` per CKPT181 because
    // unconditional emission regressed `viewport_array.provoking_vertex`.
    //
    // Sprint 16 Day 16 (CKPT225) traced the regression to the
    // 2-bug-cancellation phenomenon: provoking_vertex passed
    // pre-Sprint-16 with viewport routing OFF *because* the missing
    // Y-flip in `glGetTexImage` hid the wrong-viewport-region by
    // reading raw Metal-storage rows. With both bugs fixed together
    // (Day 17: re-enable viewport routing + Y-flip the readback in
    // `glGetTexImage`), the per-vertex `gl_ViewportIndex` actually
    // routes to the right rectangle and the readback agrees with
    // OpenGL Y-up convention.
    //
    // The state-divergence guard (only emit when at least one entry
    // 1..N differs from slot 0) stays in place — Metal pipelines that
    // never need multi-viewport stay on the cheap single-viewport
    // path.
    // Sprint 16 Day 19 (CKPT228) — also bind on scissor-array
    // divergence. CTS `viewport_array.scissor` /
    // `viewport_array.scissor_clear` set 16 per-index scissor rects
    // without ever calling glViewportArrayv, so the viewport-only
    // divergence check below stayed false. The encoder then took
    // the single-viewport / single-scissor path and dropped every
    // GS-emitted gl_ViewportIndex into slot 0. Mirroring the check
    // for scissor[1..N-1] vs scissor[0] routes those tests through
    // the array path so the `[[viewport_array_index]]` rasteriser
    // walk picks up the matching scissor rect.
    const bool routeViewportIndex = ed.hasViewportIndex &&
        [this]() -> bool {
            appgl::GLStateTracker::IndexedViewportEntry vparr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t got = 0;
            this->state->getViewportArray(vparr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &got);
            for (std::size_t i = 1; i < got; ++i) {
                if (vparr[i].x != vparr[0].x ||
                    vparr[i].y != vparr[0].y ||
                    vparr[i].width != vparr[0].width ||
                    vparr[i].height != vparr[0].height ||
                    vparr[i].depthNear != vparr[0].depthNear ||
                    vparr[i].depthFar != vparr[0].depthFar) {
                    return true;
                }
            }
            appgl::GLStateTracker::IndexedScissorEntry scarr[
                appgl::TranslatedDrawInfo::kMaxDrawViewports];
            std::size_t scgot = 0;
            this->state->getScissorArray(scarr,
                appgl::TranslatedDrawInfo::kMaxDrawViewports, &scgot);
            for (std::size_t i = 1; i < scgot; ++i) {
                if (scarr[i].x != scarr[0].x ||
                    scarr[i].y != scarr[0].y ||
                    scarr[i].width != scarr[0].width ||
                    scarr[i].height != scarr[0].height ||
                    scarr[i].enabled != scarr[0].enabled) {
                    return true;
                }
            }
            return false;
        }();

    // Sprint 17 Day 1 (CKPT236) [A.2 narrow gate]: mark the bound
    // draw-FBO's colour attachments as viewport-rendered-to ONLY
    // when this draw will engage the viewport-flipped Metal write
    // path (`routeViewportIndex == true`). Replaces the over-broad
    // binding-time set in `framebufferTexture` (Sprint 16 Day 17 /
    // CKPT226) — that set fired for DSA multisample storage and
    // texture_barrier tests that bind a texture as colour
    // attachment but never engage the viewport-flipped write,
    // causing 58 false-positive Y-flips on `glGetTexImage`
    // readback (CKPT236 bisect).
    //
    // Single-viewport draws (where `routeViewportIndex == false`)
    // do NOT set the flag here; their writes either don't happen
    // (DSA storage allocation), don't apply viewport flip
    // (texture_barrier render-to-self with single viewport), or
    // are otherwise opaque-byte-pattern preserved. The 4 +4
    // viewport_array DUAL-FIX wins all use multi-viewport draws,
    // so they DO engage `routeViewportIndex` and DO set the flag,
    // preserving the +4 wins via correct Y-flip on readback.
    // Sprint 17 Day 3+ BONUS-1 [clip_control]: also gate on
    // `state->clipOrigin() == GL_LOWER_LEFT`. The flag's contract is
    // "this texture has Y-flipped contents that need readback-unflip"
    // — but under `glClipControl(GL_UPPER_LEFT, _)` the viewport
    // descriptor's Y-flip is OFF (BONUS-1.2 gate at MetalFrameGraph
    // viewport-bind sites), so the texture's Metal storage is already
    // top-down and `glGetTexImage` should return it unflipped.
    // Setting the flag in that case would trigger a spurious readback
    // flip and corrupt the result on UPPER_LEFT draws.
    if (routeViewportIndex && state->clipOrigin() == GL_LOWER_LEFT) {
        const GLuint fboName = state->boundDrawFramebuffer();
        if (fboName != 0) {
            if (const GLFramebufferObject* fbo =
                    objects->framebuffers().get(fboName)) {
                for (const auto& kv : fbo->attachments) {
                    if (!isColorAttachment(kv.first)) continue;
                    if (kv.second.kind !=
                            GLFramebufferAttachment::Kind::Texture) continue;
                    if (GLTextureObject* mut =
                            objects->textures().get(kv.second.object)) {
                        mut->wasViewportRenderedTo = true;
                    }
                }
            }
        }
    }

    // Invalidate the cached synth VS when its layered-ness doesn't
    // match the current draw. Metal won't accept swapping the
    // `[[render_target_array_index]]` declaration on an existing
    // pipeline, so we rebuild from scratch. The pipeline cache
    // flushed too (same rebuild-on-next-draw path).
    if (!program.gsPassThroughVertexMSL.empty() &&
        (program.gsPassThroughVertexMSLLayered != routeLayer ||
         program.gsPassThroughVertexMSLViewportArray != routeViewportIndex)) {
        program.gsPassThroughVertexMSL.clear();
        program.gsPassThroughPipelineStateCache.clear();
        program.gsPassThroughPipelineState = nullptr;
        program.gsPassThroughPipelineColorFormat = 0;
        // Also invalidate the FS rewrite: its primitive-id input
        // location is derived from the synth-VS output layout; if
        // the VS rebuilds, the FS has to follow so MSL's
        // user(locnN) linkage stays in sync.
        program.gsPassThroughFragmentMSL.clear();
        program.gsPassThroughFragmentMSLActive = false;
    }

    // Synthesise the pass-through VS once per program (cache on
    // the program object — the layout/widths/locations are fixed
    // at link time by the GS SPIR-V, which doesn't change draw-to-
    // draw). Matching reflection + attribute layout built from the
    // same `ed` so Metal's vertex descriptor picks the right formats.
    if (program.gsPassThroughVertexMSL.empty()) {
        program.gsPassThroughVertexMSL = appgl::synthesisePassThroughVertexMSL(
            ed, routeLayer, routeViewportIndex);
        program.gsPassThroughVertexMSLLayered = routeLayer;
        program.gsPassThroughVertexMSLViewportArray = routeViewportIndex;
        if (std::getenv("APPGL_GS_DUMP_MSL") != nullptr) {
            std::fprintf(stderr, "\n[GS] synth VS MSL (routeLayer=%d hasLayer=%d clipLen=%u cullLen=%u):\n%s\n",
                (int)routeLayer, (int)ed.hasLayer, ed.clipDistanceLen, ed.cullDistanceLen,
                program.gsPassThroughVertexMSL.c_str());
        }
        program.gsPassThroughReflection = ShaderReflection{};
        {
            ShaderReflection::VertexInput pos;
            pos.location = 0;
            pos.type = GL_FLOAT_VEC4;
            pos.name = "vsin_position";
            program.gsPassThroughReflection.vertexInputs.push_back(pos);
        }
        for (std::size_t i = 0; i < ed.varyingWidths.size(); ++i) {
            ShaderReflection::VertexInput vi;
            vi.location = static_cast<GLuint>(i + 1);
            const std::uint8_t bt = (i < ed.varyingBaseType.size())
                ? ed.varyingBaseType[i] : 0;
            const std::uint32_t w = ed.varyingWidths[i];
            if (bt == 1) {
                switch (w) {
                    case 1: vi.type = GL_INT;      break;
                    case 2: vi.type = GL_INT_VEC2; break;
                    case 3: vi.type = GL_INT_VEC3; break;
                    case 4: vi.type = GL_INT_VEC4; break;
                    default: vi.type = GL_INT;     break;
                }
            } else if (bt == 2) {
                switch (w) {
                    case 1: vi.type = GL_UNSIGNED_INT;      break;
                    case 2: vi.type = GL_UNSIGNED_INT_VEC2; break;
                    case 3: vi.type = GL_UNSIGNED_INT_VEC3; break;
                    case 4: vi.type = GL_UNSIGNED_INT_VEC4; break;
                    default: vi.type = GL_UNSIGNED_INT;     break;
                }
            } else {
                switch (w) {
                    case 1: vi.type = GL_FLOAT;      break;
                    case 2: vi.type = GL_FLOAT_VEC2; break;
                    case 3: vi.type = GL_FLOAT_VEC3; break;
                    case 4: vi.type = GL_FLOAT_VEC4; break;
                    default: vi.type = GL_FLOAT;     break;
                }
            }
            vi.name = "vsin_v" + std::to_string(i);
            program.gsPassThroughReflection.vertexInputs.push_back(vi);
        }
        // Clip + cull distance input attributes, one float per slot.
        // Stored immediately after the last user varying in the same
        // packed vertex buffer. Location indices (for reflection)
        // follow the varying block; Metal attribute indices are
        // allocated the same way in the synth VS MSL so these match.
        const GLuint clipBaseLoc =
            static_cast<GLuint>(ed.varyingWidths.size() + 1);
        for (std::uint32_t i = 0; i < ed.clipDistanceLen; ++i) {
            ShaderReflection::VertexInput vi;
            vi.location = clipBaseLoc + i;
            vi.type = GL_FLOAT;
            vi.name = "vsin_clip" + std::to_string(i);
            program.gsPassThroughReflection.vertexInputs.push_back(vi);
        }
        const GLuint cullBaseLoc = clipBaseLoc + ed.clipDistanceLen;
        for (std::uint32_t i = 0; i < ed.cullDistanceLen; ++i) {
            ShaderReflection::VertexInput vi;
            vi.location = cullBaseLoc + i;
            vi.type = GL_FLOAT;
            vi.name = "vsin_cull" + std::to_string(i);
            program.gsPassThroughReflection.vertexInputs.push_back(vi);
        }
        // Sprint 7 Phase 1 #6 (CKPT58): trailing per-vertex slots
        // (gl_Layer, gl_PointSize, gl_PrimitiveID) used to be exposed
        // as `[[attribute(N)]]` stage_in entries here, but Metal's
        // 31-attribute hardware cap made the synth-VS pipeline
        // silently drop the 32nd attribute when GS uses the GL spec-
        // floor MAX_GEOMETRY_OUTPUT_COMPONENTS = 128 (30 ivec4 varyings
        // + position + pointSize = 32 attributes). The synth-VS now
        // reads these slots directly from the packed buffer at slot 0
        // via `gs_packed[vid * stride + offset]`, which keeps the
        // per-vertex byte layout unchanged but saves up to 3 stage_in
        // attribute slots. We intentionally do NOT push reflection /
        // attribute-layout entries for them here.
        (void)cullBaseLoc;
    }

    TranslatedDrawInfo tdi;
    tdi.mode = ed.topology;
    tdi.vertexCount = static_cast<GLsizei>(ed.vertexCount);
    tdi.vertexData = ed.expandedVertexData.data();
    tdi.vertexDataByteCount = ed.expandedVertexData.size() * sizeof(float);
    tdi.vertexStride = ed.floatsPerVertex * sizeof(float);

    {
        std::size_t offset = 0;
        {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = 0;
            la.offset = offset;
            la.glType = GL_FLOAT;
            la.glComponentCount = 4;
            tdi.vertexAttributeLayouts.push_back(la);
            offset += 4 * sizeof(float);
        }
        for (std::size_t i = 0; i < ed.varyingWidths.size(); ++i) {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = static_cast<GLuint>(i + 1);
            la.offset = offset;
            const std::uint8_t bt = (i < ed.varyingBaseType.size())
                ? ed.varyingBaseType[i] : 0;
            if (bt == 1) {
                la.glType = GL_INT;
                la.glIsInteger = true;
            } else if (bt == 2) {
                la.glType = GL_UNSIGNED_INT;
                la.glIsInteger = true;
            } else {
                la.glType = GL_FLOAT;
            }
            la.glComponentCount = static_cast<GLint>(ed.varyingWidths[i]);
            tdi.vertexAttributeLayouts.push_back(la);
            offset += ed.varyingWidths[i] * sizeof(float);
        }
        // Clip / cull distance attribute layouts, in order, one float
        // per slot. They share the same packed buffer with the other
        // attributes; the encoder's vertex-descriptor builder reads
        // TranslatedDrawInfo::vertexAttributeLayouts to set up
        // MTLVertexDescriptor's per-attribute format + offset.
        const GLuint clipBaseLoc =
            static_cast<GLuint>(ed.varyingWidths.size() + 1);
        for (std::uint32_t i = 0; i < ed.clipDistanceLen; ++i) {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = clipBaseLoc + i;
            la.offset = offset;
            la.glType = GL_FLOAT;
            la.glComponentCount = 1;
            tdi.vertexAttributeLayouts.push_back(la);
            offset += sizeof(float);
        }
        const GLuint cullBaseLoc = clipBaseLoc + ed.clipDistanceLen;
        for (std::uint32_t i = 0; i < ed.cullDistanceLen; ++i) {
            TranslatedDrawInfo::VertexAttributeLayout la;
            la.location = cullBaseLoc + i;
            la.offset = offset;
            la.glType = GL_FLOAT;
            la.glComponentCount = 1;
            tdi.vertexAttributeLayouts.push_back(la);
            offset += sizeof(float);
        }
        // Sprint 7 Phase 1 #6 (CKPT58): no vertex attribute layouts
        // for the trailing gl_Layer / gl_PointSize / gl_PrimitiveID
        // slots — synth-VS reads them via direct buffer access. The
        // per-vertex stride must STILL include their bytes (the
        // packed buffer layout is unchanged), so advance `offset`
        // through the trailing slots without pushing layouts. This
        // keeps `tdi.vertexStride` matching the actual per-vertex
        // byte count and the manual buffer reads point at the right
        // position.
        if (ed.hasLayer)        offset += sizeof(std::int32_t);
        if (ed.hasPointSize)    offset += sizeof(float);
        if (ed.hasPrimitiveID)  offset += sizeof(std::int32_t);
    }

    populateTranslatedDrawFixedFunctionState(tdi, *state);
    tdi.markColorAttachmentReadbackFlip =
        routeViewportIndex && tdi.clipOrigin == GL_LOWER_LEFT;
    tdi.vertexMSL = &program.gsPassThroughVertexMSL;
    // Post-process the FS MSL to redirect `gl_PrimitiveID` reads
    // to a user varying when the GS wrote BuiltInPrimitiveId.
    // Rebuild when the primitive-id location changed (e.g. if
    // the user varying layout shifted between draws — currently
    // impossible for a linked program but guard for safety).
    if (ed.hasPrimitiveID) {
        if (program.gsPassThroughFragmentMSL.empty()
            || program.gsPassThroughFragmentMSLPrimIdLoc != ed.primitiveIDLocation) {
            program.gsPassThroughFragmentMSL =
                appgl::rewriteFragmentMSLForPrimitiveID(program.fragmentMSL, ed);
            program.gsPassThroughFragmentMSLPrimIdLoc = ed.primitiveIDLocation;
            program.gsPassThroughFragmentMSLActive = true;
            // Rebuilding FS invalidates any cached pipeline state.
            program.gsPassThroughPipelineStateCache.clear();
            program.gsPassThroughPipelineState = nullptr;
            program.gsPassThroughPipelineColorFormat = 0;
            if (std::getenv("APPGL_GS_DUMP_MSL") != nullptr) {
                std::fprintf(stderr, "\n[GS] rewritten FS MSL (primIdLoc=%u, %zu bytes)\n",
                    ed.primitiveIDLocation, program.gsPassThroughFragmentMSL.size());
            }
        }
        tdi.fragmentMSL = &program.gsPassThroughFragmentMSL;
    } else {
        tdi.fragmentMSL = &program.fragmentMSL;
    }
    tdi.vertexReflection = &program.gsPassThroughReflection;
    tdi.fragmentReflection = &program.fragmentReflection;
    tdi.pipelineStateOut = &program.gsPassThroughPipelineState;
    tdi.pipelineColorFormatOut = &program.gsPassThroughPipelineColorFormat;
    tdi.pipelineStateCacheOut = &program.gsPassThroughPipelineStateCache;
    tdi.program = programName;

    if (!program.uniformLayoutComputed) {
        computeStageUniformLayout(program.vertexUniformLayout,
            program.vertexReflection, program.uniforms);
        computeStageUniformLayout(program.fragmentUniformLayout,
            program.fragmentReflection, program.uniforms);
        program.uniformLayoutComputed = true;
    }
    thread_local std::vector<std::uint8_t> gsFragUniformScratch;
    buildStageUniformBuffer(gsFragUniformScratch,
        program.fragmentReflection, program.uniformValues,
        program.fragmentUniformLayout);
    tdi.vertexUniformData = nullptr;
    tdi.vertexUniformSize = 0;
    tdi.fragmentUniformData = gsFragUniformScratch.data();
    tdi.fragmentUniformSize = gsFragUniformScratch.size();

    resolveSamplerBindings(program, tdi);
    resolveUBOBindings(program, tdi);
    resolveSSBOBindings(program, tdi);
    resolveImageBindings(program, tdi);

    if (preFboColTex != nullptr || preFboDSTex != nullptr) {
        tdi.fboColorTexture = preFboColTex;
        tdi.fboDepthStencilTexture = preFboDSTex;
        tdi.fboWidth = preFboW;
        tdi.fboHeight = preFboH;
        // Only honour layered-attachment routing when the emulated
        // GS actually wrote gl_Layer AND the FBO is layered. In
        // the GS-wrote but non-layered case the synth VS didn't
        // emit [[render_target_array_index]] (see routeLayer
        // branch at function entry), so we must leave
        // renderTargetArrayLength at 0 to match.
        if (routeLayer) {
            tdi.fboColorArrayLength = preFboArrayLen;
            // Sprint 17 Day 1 (CKPT236) [Probe A 2DMSArray clamp]:
            // forward GS-emul-tracked max emitted layer so
            // `encodeTranslatedDraw` can clamp `renderTargetArrayLength`
            // for MS-array attachments (h2DM-3 AGX assertion fix).
            tdi.maxEmittedLayer = ed.maxEmittedLayer;
        }
    }

    thread_local std::string gsPipelineBuildError;
    gsPipelineBuildError.clear();
    tdi.pipelineBuildErrorOut = &gsPipelineBuildError;

    const bool ok = encodeTranslatedDrawAndMarkFbo(tdi);
    return ok;
}

// Sprint 17 Day 7+ Bank-Group-H Path B Component D-γ — see header
// comment on the Impl method declaration. Sister-pattern leverage
// (Item 26 LIVE 18th-instance) with the drawElements internal
// translated-pipeline setup at GLContext::drawElements (~line 29291);
// kept as a separate function rather than a refactor of drawElements
// to minimise regression-test surface on the existing path.
bool GLContext::Impl::dispatchCullFilteredDraw(
        GLProgramObject& program,
        GLVertexArrayObject& vao,
        GLuint programName,
        GLenum mode,
        const std::vector<std::uint32_t>& filteredIndices) {
    if (filteredIndices.empty()) {
        return true;
    }
    if (!program.hasTranslatedPipeline) {
        return false;
    }
    if (vao.attributes.empty() || frameGraph == nullptr) {
        return false;
    }

    // Find primary enabled attribute for primary-VBO detection. Mirror
    // of the drawArrays primaryIdx scan — cull_distance CTS tests use
    // attribute 0 unused with bindings at locations 1..9.
    std::size_t primaryIdx = 0;
    bool foundEnabled = false;
    for (std::size_t ai = 0; ai < vao.attributes.size(); ++ai) {
        if (vao.attributes[ai].enabled) {
            primaryIdx = ai;
            foundEnabled = true;
            break;
        }
    }
    if (!foundEnabled) {
        return false;
    }
    const auto& posAttr = vao.attributes[primaryIdx];
    auto resolved = resolveVertexAttrib(posAttr, vao);
    GLBufferObject* vbo = (resolved.bufferName != 0)
        ? objects->buffers().get(resolved.bufferName) : nullptr;
    if (vbo == nullptr || vbo->shadowBytes.empty()) {
        return false;
    }
    const std::size_t posStride = resolved.stride;
    const std::size_t startOff = resolved.offset;
    if (startOff > vbo->shadowBytes.size()) {
        return false;
    }

    TranslatedDrawInfo tdi;
    tdi.mode = mode;
    tdi.vertexCount = static_cast<GLsizei>(filteredIndices.size());
    tdi.vertexData = vbo->shadowBytes.data() + startOff;
    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
    tdi.vertexStride = posStride;
    tdi.metalVertexBuffer = vbo->metalBuffer;
    tdi.metalVertexBufferOffset = startOff;
    // Filtered indices fed as UINT32 client-side index array;
    // encodeTranslatedDraw stages them into a Metal ring buffer.
    tdi.indices = filteredIndices.data();
    tdi.indexCount = static_cast<GLsizei>(filteredIndices.size());
    tdi.indexType = GL_UNSIGNED_INT;

    populateTranslatedDrawFixedFunctionState(tdi, *state);
    tdi.markColorAttachmentReadbackFlip =
        (tdi.clipOrigin == GL_LOWER_LEFT);
    tdi.vertexMSL = &program.vertexMSL;
    tdi.fragmentMSL = &program.fragmentMSL;
    tdi.vertexReflection = &program.vertexReflection;
    tdi.fragmentReflection = &program.fragmentReflection;
    tdi.pipelineStateOut = &program.metalPipelineState;
    tdi.pipelineColorFormatOut = &program.metalPipelineColorFormat;
    tdi.pipelineStateCacheOut = &program.metalPipelineStateCache;
    tdi.metalVertexFunction = program.metalVertexFunction;
    tdi.metalFragmentFunction = program.metalFragmentFunction;
    tdi.metalVertexFunctionOut = &program.metalVertexFunction;
    tdi.metalFragmentFunctionOut = &program.metalFragmentFunction;
    tdi.program = programName;

    // VAO-grouped attribute layout — mirror of drawElements grouping.
    {
        struct CPGroupKey {
            GLuint bufferName;
            std::size_t stride;
            bool operator==(const CPGroupKey& o) const {
                return bufferName == o.bufferName && stride == o.stride;
            }
        };
        struct CPGroupKeyHash {
            std::size_t operator()(const CPGroupKey& k) const {
                return std::hash<GLuint>()(k.bufferName)
                     ^ (std::hash<std::size_t>()(k.stride) << 16);
            }
        };
        std::unordered_map<CPGroupKey, std::size_t, CPGroupKeyHash> cpExtraMap;
        for (std::size_t ai = 0; ai < vao.attributes.size(); ++ai) {
            const auto& attr = vao.attributes[ai];
            if (!attr.enabled) continue;
            auto attrRes = resolveVertexAttrib(attr, vao);
            TranslatedDrawInfo::VertexAttributeLayout layout;
            layout.location = static_cast<GLuint>(ai);
            populateVertexAttributeLayoutVAOFields(layout, attr);
            if (attrRes.bufferName == resolved.bufferName
                && attrRes.stride == posStride) {
                layout.offset = attrRes.offset - resolved.offset;
                tdi.vertexAttributeLayouts.push_back(layout);
            } else {
                GLBufferObject* extraVbo =
                    objects->buffers().get(attrRes.bufferName);
                if (extraVbo == nullptr || extraVbo->shadowBytes.empty()) continue;
                CPGroupKey key{attrRes.bufferName, attrRes.stride};
                auto it = cpExtraMap.find(key);
                std::size_t idx;
                if (it == cpExtraMap.end()) {
                    idx = tdi.extraVertexBuffers.size();
                    cpExtraMap[key] = idx;
                    TranslatedDrawInfo::ExtraVertexBuffer evb;
                    evb.data = extraVbo->shadowBytes.data();
                    evb.byteCount = extraVbo->shadowBytes.size();
                    evb.stride = attrRes.stride;
                    evb.divisor = 0;
                    evb.metalBuffer = extraVbo->metalBuffer;
                    evb.metalBufferOffset = 0;
                    tdi.extraVertexBuffers.push_back(std::move(evb));
                } else {
                    idx = it->second;
                }
                layout.offset = attrRes.offset;
                tdi.extraVertexBuffers[idx].attributes.push_back(layout);
            }
        }
    }

    if (!program.uniformLayoutComputed) {
        computeStageUniformLayout(program.vertexUniformLayout,
            program.vertexReflection, program.uniforms);
        computeStageUniformLayout(program.fragmentUniformLayout,
            program.fragmentReflection, program.uniforms);
        program.uniformLayoutComputed = true;
    }
    thread_local std::vector<std::uint8_t> cpVtxUniform;
    thread_local std::vector<std::uint8_t> cpFragUniform;
    pushSynthesizedMatrixUniforms(program, matrixState);
    buildStageUniformBuffer(cpVtxUniform,
        program.vertexReflection, program.uniformValues,
        program.vertexUniformLayout);
    buildStageUniformBuffer(cpFragUniform,
        program.fragmentReflection, program.uniformValues,
        program.fragmentUniformLayout);
    tdi.vertexUniformData = cpVtxUniform.data();
    tdi.vertexUniformSize = cpVtxUniform.size();
    tdi.fragmentUniformData = cpFragUniform.data();
    tdi.fragmentUniformSize = cpFragUniform.size();

    resolveSamplerBindings(program, tdi);
    resolveUBOBindings(program, tdi);
    resolveSSBOBindings(program, tdi);
    resolveImageBindings(program, tdi);

    {
        GLsizei fboW = 0, fboH = 0;
        void* fboDSTex = nullptr;
        std::array<void*, 7> extraColTex = {};
        std::array<std::uint32_t, 8> colSlices = {};
        void* fboColTex = resolveFBOColorTarget(
            fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
        if (fboColTex != nullptr || fboDSTex != nullptr) {
            tdi.fboColorTexture = fboColTex;
            tdi.fboAdditionalColorTextures = extraColTex;
            tdi.fboColorSlices = colSlices;
            tdi.fboDepthStencilTexture = fboDSTex;
            tdi.fboWidth = fboW;
            tdi.fboHeight = fboH;
        }
    }

    thread_local std::string cpPipelineBuildErr;
    cpPipelineBuildErr.clear();
    tdi.pipelineBuildErrorOut = &cpPipelineBuildErr;

    return encodeTranslatedDrawAndMarkFbo(tdi);
}

// Sprint 17 Day 7+ Bank-Group-H Path B Phase 3 day 4 — see header
// comment at the Impl method declaration. Item 26 LIVE 19th-instance
// candidate: sister-pattern leverage at the call-site-wrapper level.
bool GLContext::Impl::encodeTranslatedDrawAndMarkFbo(TranslatedDrawInfo& tdi) {
    const bool ok = frameGraph->encodeTranslatedDraw(tdi);
    if (ok) {
        const GLuint fboName = state->boundDrawFramebuffer();
        if (fboName != 0) {
            if (GLFramebufferObject* fbo =
                    objects->framebuffers().get(fboName)) {
                // Split the two color-texture readback contracts:
                // ordinary LOWER_LEFT FBO draws mark framebuffer readback
                // only, while viewport-routed GS/cull paths also mark the
                // narrower glGetTexImage Y-unflip flag.
                if (tdi.clipOrigin == GL_LOWER_LEFT ||
                    tdi.markColorAttachmentReadbackFlip) {
                    for (const auto& kv : fbo->attachments) {
                        if (!isColorAttachment(kv.first)) continue;
                        if (kv.second.kind !=
                                GLFramebufferAttachment::Kind::Texture) continue;
                        if (GLTextureObject* tex =
                                objects->textures().get(kv.second.object)) {
                            if (tdi.clipOrigin == GL_LOWER_LEFT) {
                                tex->wasFramebufferRenderedTo = true;
                            }
                            if (tdi.markColorAttachmentReadbackFlip) {
                                tex->wasViewportRenderedTo = true;
                            }
                        }
                    }
                }
                // Sprint 17 Day 9+ Bank-Group-A-1 narrow-gate
                // (regression-debt #1+#2): mark depth-renderbuffer
                // attachments as Metal-rendered so subsequent
                // glReadPixels(GL_DEPTH_COMPONENT) prefers the Metal-
                // texture readback path (Bank-Group-A-1 `6ba6aad`).
                // Not gated on clipOrigin: depth tracking is about
                // render-pass-target-validity, not Y-flip orientation.
                auto markDepthAttachment = [&](GLenum attEnum) {
                    auto it = fbo->attachments.find(attEnum);
                    if (it == fbo->attachments.end()) return;
                    if (it->second.kind !=
                            GLFramebufferAttachment::Kind::Renderbuffer) return;
                    if (GLRenderbufferObject* rb =
                            objects->renderbuffers().get(it->second.object)) {
                        rb->wasMetalDepthRendered = true;
                    }
                };
                markDepthAttachment(GL_DEPTH_ATTACHMENT);
                markDepthAttachment(GL_DEPTH_STENCIL_ATTACHMENT);
                auto markStencilAttachment = [&](GLenum attEnum) {
                    auto it = fbo->attachments.find(attEnum);
                    if (it == fbo->attachments.end()) return;
                    if (it->second.kind !=
                            GLFramebufferAttachment::Kind::Renderbuffer) return;
                    if (GLRenderbufferObject* rb =
                            objects->renderbuffers().get(it->second.object)) {
                        rb->wasMetalStencilRendered = true;
                    }
                };
                markStencilAttachment(GL_STENCIL_ATTACHMENT);
                markStencilAttachment(GL_DEPTH_STENCIL_ATTACHMENT);
                auto markDepthStencilTextureAttachment = [&](GLenum attEnum) {
                    auto it = fbo->attachments.find(attEnum);
                    if (it == fbo->attachments.end()) return;
                    if (it->second.kind !=
                            GLFramebufferAttachment::Kind::Texture) return;
                    if (GLTextureObject* tex =
                            objects->textures().get(it->second.object)) {
                        if (tdi.clipOrigin == GL_LOWER_LEFT) {
                            tex->wasFramebufferRenderedTo = true;
                            tex->wasViewportRenderedTo = true;
                            tex->swizzleDirty = true;
                        }
                    }
                };
                markDepthStencilTextureAttachment(GL_DEPTH_ATTACHMENT);
                markDepthStencilTextureAttachment(GL_STENCIL_ATTACHMENT);
                markDepthStencilTextureAttachment(GL_DEPTH_STENCIL_ATTACHMENT);
            }
        }
    }
    return ok;
}

// GL 4.6 §10.1 Table 10.1 — the full set of primitive modes that
// glDraw*/glMultiDraw* accept. Anything else raises
// GL_INVALID_ENUM. Shared by every draw entry.
static bool isValidDrawMode(GLenum mode) {
    switch (mode) {
        case GL_POINTS:
        case GL_LINES:
        case GL_LINE_STRIP:
        case GL_LINE_LOOP:
        case GL_LINES_ADJACENCY:
        case GL_LINE_STRIP_ADJACENCY:
        case GL_TRIANGLES:
        case GL_TRIANGLE_STRIP:
        case GL_TRIANGLE_FAN:
        case GL_TRIANGLES_ADJACENCY:
        case GL_TRIANGLE_STRIP_ADJACENCY:
        case GL_PATCHES:
            return true;
        default:
            return false;
    }
}

bool GLContext::drawArrays(GLenum mode, GLint first, GLsizei count) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate. Skipped draws
    // do not advance query counters.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }

    // GL 4.6 §11.3.1 — GS input topology / draw mode compatibility.
    // When the linked program has a GS, rejecting mismatched draw
    // modes with GL_INVALID_OPERATION is required by the CTS
    // `geometry_shader.api.incompatible_draw_call_mode` test.
    //
    // Spec caveat (§10.1 / §11.2.3) — when a tessellation stage is
    // between VS and GS, the GS receives the TES output topology
    // (triangles/quads/isolines), NOT the draw mode. The raw draw
    // mode is GL_PATCHES for tess, which would never match the GS's
    // input topology under the naive check. Skip the GS-mode-compat
    // gate when tess is present; the TES's declared output topology
    // controls what the GS sees.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        const GLProgramObject* p = nullptr;
        if (progName != 0) {
            p = impl_->objects->programs().get(progName);
        }
        if (p != nullptr && p->gsPresent && !p->hasTessellation &&
            !isDrawModeCompatibleWithGs(mode, p->gsInputTopology)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL 4.6 §7.3 & §11 — when no program is currently in use,
        // drawing requires a program pipeline whose vertex stage is
        // non-zero and linked. CTS
        // geometry_shader.api.{fs_gs_draw_call,
        // pipeline_program_without_active_vs} exercises this.
        if (progName == 0) {
            const GLProgramPipelineObject* ppo = (pipelineName != 0)
                ? impl_->objects->programPipelines().get(pipelineName)
                : nullptr;
            const GLuint vsProg = ppo ? ppo->vertexProgram : 0;
            if (vsProg == 0) {
                pushError(GL_INVALID_OPERATION);
                return false;
            }
            // Check GS stage topology compatibility too — a pipeline
            // with a GS program follows the same §11.3.1 rule.
            const GLuint gsProg = ppo ? ppo->geometryProgram : 0;
            if (gsProg != 0) {
                const GLProgramObject* gsP = impl_->objects->programs().get(gsProg);
                // Tess-in-pipeline suppression: if any other stage
                // program in the pipeline declares a tess stage,
                // skip this check (same reasoning as the in-program
                // case above).
                bool pipelineHasTess = false;
                if (ppo != nullptr) {
                    for (GLuint ps : {ppo->tessControlProgram, ppo->tessEvalProgram}) {
                        if (ps == 0) continue;
                        const GLProgramObject* tsP = impl_->objects->programs().get(ps);
                        if (tsP != nullptr && tsP->hasTessellation) {
                            pipelineHasTess = true; break;
                        }
                    }
                }
                if (gsP != nullptr && gsP->gsPresent && !pipelineHasTess &&
                    !isDrawModeCompatibleWithGs(mode, gsP->gsInputTopology)) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
            }
        }
    }

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    // Make sure the drawable and depth targets are sized for the current
    // viewport BEFORE we flush the pending clear. Resizing invalidates any
    // unflushed command buffer, so doing it after the clear would drop the
    // clear on the floor and leave the offscreen attachment uninitialized.
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    // Flush any pending clear before we start the draw render pass; otherwise
    // the draw would run against an uncleared default attachment.
    impl_->encodePendingWork();

    // Try the translated shader pipeline first (GPU-side vertex processing).
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);
    APPGL_LOG(DRAW, @"drawArrays: mode=0x%X count=%d program=%u hasTranslated=%d",
              mode, count, programName, program ? (int)program->hasTranslatedPipeline : -1);

    // CPU TES emulation — phase-3e-3 hook. Metal has no tessellation
    // stage; for programs whose TES body matches a recognised
    // passthrough/affine shape (matchTessEvalPassthrough in
    // TessellationEmulator.cpp), we generate the domain on the CPU
    // and render the expanded-vertex buffer through the same synth-
    // VS path the GS emulator uses.
    //
    // Detection happened at link time. If detectTessellationEmulatable
    // returned false (or APPGL_ENABLE_TESS_EMUL=0 was set), the flag
    // stays false and this branch is a no-op — the draw falls through
    // to the legacy translated path (which doesn't actually tessellate,
    // same behaviour as before the emulator existed).
    //
    // GS+TES together: if a program has both emulable stages, skip
    // the tess path here and let the GS emulator run. Combining the
    // two is phase 6+ work.
    // Metal-native tessellation path. Tier is set at link time:
    //   Phase2 — factor + indirect only (winding.* shape). Goes
    //     through the Phase-2 code path in `encodeMetalTessellationDraw`.
    //   Phase3 — VS-as-compute + TCS with per-CP / per-patch
    //     buffers. Same encoder, Phase-3 code path.
    //   None   — CPU tessellation interpreter.
    // Programs that need transform feedback or rasterizer-discard
    // side effects get downgraded to None at link time (TF-varyings
    // guard in linkProgram) + at draw time (transformFeedbackActive
    // guard in tryMetalTessellationDraw). GS-after-tess is also gated
    // off here; Phase 5 will extend the Metal path to consume TES
    // output through the GS emulator.
    // T4F fix: when pipeline-bound (currentProgram=0 and
    // resolveDrawProgram returned the VS container), tess metadata
    // lives on the SEPARABLE TES program — not on the resolved VS
    // container. Look up the pipeline's TES program (BeginTF chain:
    // GS > TES > VS, same as 26d056a) and use it for the gate decision
    // + tryMetalTessellationDraw. Without this, gl_MaxPatchVertices_*
    // pipeline-path main draws bail at this gate (VS container has
    // hasTessellation=false / metalTessTier=None) → fall through to
    // CPU emulator → TF buffer remains zero → verifier fails on
    // result_position_data.size() != 1.
    // β [metal-tess-TF]: when a pipeline with separable VS+TCS+TES+FS
    // is bound (currentProgram=0, resolveDrawProgram returned the VS
    // container which lacks tess metadata), ask the pipeline-time
    // orchestrator to synthesise a Metal-tess-ready combined program.
    // For step-1 scaffold this returns nullptr and we fall through to
    // the CPU emulator (existing behaviour) — step 2/3 fill in the
    // cross-stage translation + probe so the synthesised program is
    // tier=Phase3 with all PSOs built.
    GLProgramObject* tessProgram = program;
    GLuint tessProgramName = programName;
    if (impl_->state->currentProgram() == 0) {
        const GLuint ppoId = impl_->state->currentProgramPipeline();
        if (ppoId != 0) {
            if (GLProgramPipelineObject* ppo =
                    impl_->objects->programPipelines().get(ppoId)) {
                if (GLProgramObject* synth =
                        impl_->ensurePipelineTessSynthesizedProgram(*ppo)) {
                    tessProgram = synth;
                    tessProgramName = 0;  // synthetic — no GL program name
                }
            }
        }
    }
    if (tessProgram != nullptr &&
        tessProgram->hasTessellation &&
        tessProgram->metalTessTier != GLProgramObject::MetalTessTier::None &&
        !tessProgram->geometryEmulated) {
        const bool preferCpuTessSsboSideEffects =
            tessProgram == program &&
            (tessProgram->tessControlInterpreted ||
             tessProgram->tessellationInterpreted) &&
            (!tessProgram->tessControlReflection.storageBuffers.empty() ||
             !tessProgram->tessEvalAsComputeReflection.storageBuffers.empty());
        // TCS-SSBO routing: the Metal tess encoder currently binds only
        // its internal tess buffers (factors, per-CP/per-patch, indirect
        // params). Keep interpreted SSBO side effects on the CPU path,
        // sister to the GS-emul SSBO resolver, until arbitrary tess-stage
        // storage-buffer slots are plumbed through Metal.
        if (preferCpuTessSsboSideEffects) {
            APPGL_LOG(SHADER, @"drawArrays metal-tess skipped for interpreted tess SSBO side effects");
        } else {
            if (impl_->tryMetalTessellationDraw(
                    *tessProgram, tessProgramName, mode, count, first)) {
                APPGL_LOG(DRAW, @"drawArrays metal-tess ok: count=%d first=%d",
                          count, first);
                return true;
            }
            APPGL_LOG(SHADER, @"drawArrays metal-tess encode failed — falling back to CPU interpreter");
        }
    }

    if (program != nullptr &&
        (program->tessellationEmulated || program->tessellationInterpreted) &&
        !program->geometryEmulated) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* tvao = (vaoName != 0)
            ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (tvao != nullptr) {
            // Sprint 16 Day 6 (CKPT215) — Tess OpImage gap. Build
            // per-stage sampler/storage-image maps so TCS/TES bodies
            // that call texture()/imageLoad()/imageStore() resolve
            // through real bindings instead of the empty-map fallback.
            // Sister-pattern to the GS-stage resolver at GLContext.mm:
            // 26265 (resolveSamplerBindings/resolveImageBindings).
            // tessControlReflection is the TCS reflection; the TES
            // reflection data lives in tessEvalAsComputeReflection
            // (legacy naming — also used by pure CPU emul path).
            appgl::SampledTextureMap tcsSamMap, tcsImgMap, tesSamMap, tesImgMap;
            if (!program->tessControlSpirv.empty()) {
                tcsSamMap = impl_->buildSampledTextureMap(
                    program->tessControlSpirv,
                    &program->tessControlReflection, *program);
                tcsImgMap = impl_->buildStorageImageMap(
                    program->tessControlSpirv,
                    &program->tessControlReflection, *program);
            }
            if (!program->tessEvalSpirv.empty()) {
                tesSamMap = impl_->buildSampledTextureMap(
                    program->tessEvalSpirv,
                    &program->tessEvalAsComputeReflection, *program);
                tesImgMap = impl_->buildStorageImageMap(
                    program->tessEvalSpirv,
                    &program->tessEvalAsComputeReflection, *program);
            }
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *program, *tvao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                /*instanceCount=*/1, /*baseInstance=*/0,
                tcsSamMap.empty() ? nullptr : &tcsSamMap,
                tcsImgMap.empty() ? nullptr : &tcsImgMap,
                tesSamMap.empty() ? nullptr : &tesSamMap,
                tesImgMap.empty() ? nullptr : &tesImgMap);
            if (ted.ok) {
                // Phase 3f-7: transform-feedback capture + rasterizer-
                // discard early-out. The helper walks
                // program.transformFeedbackVaryingNames against
                // ted.varyingNames, writes per-vertex bytes to the
                // bound TF buffers, and updates PRIMITIVES_GENERATED /
                // TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN queries. When
                // rasterDiscard is enabled it returns true so we skip
                // the Metal encode. Same helper the GS-emul path uses;
                // tess-emul's EmulatedDraw layout (position + varying
                // floats per vertex) is byte-compatible with what the
                // helper expects.
                if (impl_->writeGsXfbAndCheckDiscard(*program, ted)) {
                    return true;
                }
                if (ted.vertexCount == 0) {
                    APPGL_LOG(DRAW, @"drawArrays tess-emul: zero verts");
                    return true;
                }
                if (impl_->encodeEmulatedGsDraw(*program, programName, ted)) {
                    APPGL_LOG(DRAW, @"drawArrays tess-emul ok: verts=%zu topo=0x%X",
                              ted.vertexCount, ted.topology);
                    return true;
                }
                APPGL_LOG(SHADER, @"drawArrays tess-emul encode failed");
                // Fall through to legacy path if encode fails.
            } else if (!ted.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArrays tess-emul: %s", ted.diagnostic.c_str());
            }
        }
    }

    // CPU GS emulation — step 3 hook. Metal has no geometry-shader
    // stage; for the narrow subset in KHR-GL46.constant_expressions.
    // *_geometry we run the GS on the CPU (see
    // docs/geometry-shader-emulation.md §4) and draw the expanded
    // vertex buffer through a synthesised pass-through VS (step 4).
    //
    // Detection happened at link time. If detectGeometryEmulatable
    // returned false, geometryEmulated is false and the draw falls
    // through to the normal translated path (which emits a VS+FS
    // pipeline without the GS effect — same behaviour as before the
    // emulator existed). If true, we call emulateGeometryDraw to
    // produce the expanded vertex buffer; .ok == false still falls
    // through so a runtime diagnostic on any single vertex doesn't
    // abort the frame.
    // Handle separable-pipeline GS emulation too. When no current
    // program is bound (glUseProgram(0) or never called), but a
    // pipeline object has a GS program marked emulable, the helper
    // merges the pipeline's VS vertexSpirv + FS fragmentMSL onto
    // the GS program and returns it as the emulation target.
    // Sprint 7 Phase 2 #7 (CKPT59): pass `state->currentProgram()` (not
    // the local `programName`, which `resolveDrawProgram` may have
    // overwritten with the pipeline's VS program name) so the helper's
    // glUseProgram-vs-pipeline disambiguation works correctly. Without
    // this, the helper hit its `currentProgramName != 0` fast path with
    // the resolved-VS name and returned the VS program, completely
    // bypassing the GS-only separable program in the pipeline. The
    // failing test for this path is `KHR-GL46.geometry_shader.api.
    // program_pipeline_vs_gs_capture`, which builds a separable VS-only
    // + GS-only pair joined via glUseProgramStages and calls
    // glUseProgram(0) before drawing.
    const GLuint glUseProgramName = impl_->state->currentProgram();
    GLuint emulProgramName = (glUseProgramName != 0) ? programName : 0;
    GLProgramObject* emulProgram = impl_->resolvePipelineEmulationProgram(
        glUseProgramName, emulProgramName);
    // Sprint 3 Step 2 Phase 2 [metal-mesh-GS]: try the mesh-shader path
    // first when the program's tier classifies as MeshShader. Default-on
    // post Path G+H verification (CKPT17 closed Phase 2 with +1 net gain
    // `gl_pointsize_value`, zero regressions, default-off invariant
    // 120/136 held, tess invariant 117/140 held). The previous
    // APPGL_ENABLE_MESH_GS env-gate is removed — encoder failure still
    // returns false → existing CPU GS interpreter path runs (natural
    // fallback) for any program that can't be mesh-tier-handled.
    // Sprint 7 prep (CKPT52 fix-path A): condition mesh-GS on
    // !transformFeedbackActive. The mesh-GS encoder writes to render
    // targets, not TF buffers; routing TF-active draws through it
    // silently zeros the TF capture. CPU GS-emul has full TF capture
    // support via writeGsXfbAndCheckDiscard. With TF active, fall
    // through to CPU emul.
    if (emulProgram != nullptr &&
        emulProgram->metalGSTier == GLProgramObject::MetalGSTier::MeshShader &&
        !impl_->transformFeedbackActive) {
        if (impl_->tryMetalMeshGSDraw(*emulProgram, emulProgramName,
                                       mode, count, first)) {
            APPGL_LOG(DRAW, @"drawArrays mesh-GS ok: count=%d", count);
            return true;
        }
        APPGL_LOG(SHADER, @"drawArrays mesh-GS encode failed — falling back to CPU emulator");
    }
    if (emulProgram != nullptr && emulProgram->geometryEmulated) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr) {
            // Sprint 6 P1 sub-task 3 day 3 (CKPT43): build VS + GS
            // sampler-texture maps so CPU emul can sample real texel
            // values via OpImageSampleExplicitLod.
            const auto vsTexMap = impl_->buildSampledTextureMap(
                emulProgram->vertexSpirv,
                &emulProgram->vertexReflection, *emulProgram);
            const auto gsTexMap = impl_->buildSampledTextureMap(
                emulProgram->geometrySpirv,
                &emulProgram->geometryReflection, *emulProgram);
            // Sprint 7 Phase 1 #4 (CKPT54): same shape, storage-image
            // counterpart for OpImageRead in GS-emul.
            const auto vsImgMap = impl_->buildStorageImageMap(
                emulProgram->vertexSpirv,
                &emulProgram->vertexReflection, *emulProgram);
            const auto gsImgMap = impl_->buildStorageImageMap(
                emulProgram->geometrySpirv,
                &emulProgram->geometryReflection, *emulProgram);
            // Sprint 8 #8 β.3 (CKPT97): tess+GS plumbing. When the
            // program has BOTH tess and GS emulation enabled, run the
            // tess-emul stage first to produce per-vertex post-tess
            // output, then feed that into the GS-emul as
            // priorStageOutput. Without this, the GS-emul's VS pre-pass
            // bypasses tess entirely and the GS reads garbage from
            // gl_in[].tc_position (CTS data_pass_through tests fail
            // with "expected [1,1,1,1] found [0,0,0,0]" at odd indices
            // where the GS's `+1` pass-through modification didn't run).
            appgl::EmulatedDraw priorStage;
            const bool hasTess = emulProgram->tessellationEmulated ||
                                 emulProgram->tessellationInterpreted;
            if (hasTess) {
                // Sprint 16 Day 6 (CKPT215) — Tess OpImage gap; build
                // TCS/TES sampler+image maps for tess+GS path too.
                appgl::SampledTextureMap _tcsSam, _tcsImg, _tesSam, _tesImg;
                if (!emulProgram->tessControlSpirv.empty()) {
                    _tcsSam = impl_->buildSampledTextureMap(
                        emulProgram->tessControlSpirv,
                        &emulProgram->tessControlReflection, *emulProgram);
                    _tcsImg = impl_->buildStorageImageMap(
                        emulProgram->tessControlSpirv,
                        &emulProgram->tessControlReflection, *emulProgram);
                }
                if (!emulProgram->tessEvalSpirv.empty()) {
                    _tesSam = impl_->buildSampledTextureMap(
                        emulProgram->tessEvalSpirv,
                        &emulProgram->tessEvalAsComputeReflection, *emulProgram);
                    _tesImg = impl_->buildStorageImageMap(
                        emulProgram->tessEvalSpirv,
                        &emulProgram->tessEvalAsComputeReflection, *emulProgram);
                }
                priorStage = appgl::emulateTessellationDraw(
                    *emulProgram, *vao, *impl_->objects, *impl_->state,
                    mode, count, first, /*elementIndices=*/nullptr,
                    /*instanceCount=*/1, /*baseInstance=*/0,
                    _tcsSam.empty() ? nullptr : &_tcsSam,
                    _tcsImg.empty() ? nullptr : &_tcsImg,
                    _tesSam.empty() ? nullptr : &_tesSam,
                    _tesImg.empty() ? nullptr : &_tesImg);
                if (!priorStage.ok && !priorStage.diagnostic.empty()) {
                    APPGL_LOG(SHADER, @"drawArrays tess+GS: tess-emul: %s",
                              priorStage.diagnostic.c_str());
                }
            }
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *emulProgram, *vao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                /*instanceCount=*/1, /*baseInstance=*/0,
                vsTexMap.empty() ? nullptr : &vsTexMap,
                gsTexMap.empty() ? nullptr : &gsTexMap,
                vsImgMap.empty() ? nullptr : &vsImgMap,
                gsImgMap.empty() ? nullptr : &gsImgMap,
                (hasTess && priorStage.ok) ? &priorStage : nullptr);
            if (ed.ok) {
                // XFB capture + rasterDiscard early-out lives in a
                // shared helper so drawElements can run the same path.
                if (impl_->writeGsXfbAndCheckDiscard(*emulProgram, ed)) {
                    return true;
                }
                // GS ran successfully but emitted zero output
                // primitives (e.g. a triangle_strip body with
                // fewer than 3 EmitVertex calls). Consume the draw
                // here instead of falling through to the legacy
                // VS+FS pipeline — that path would render the VS's
                // raw gl_Position as a point and scribble fragments
                // the test explicitly expects to stay cleared.
                if (ed.vertexCount == 0) {
                    APPGL_LOG(DRAW, @"drawArrays GS-emul: zero primitives");
                    return true;
                }
                if (impl_->encodeEmulatedGsDraw(*emulProgram, emulProgramName, ed)) {
                    APPGL_LOG(DRAW, @"drawArrays GS-emul ok: verts=%zu topo=0x%X",
                              ed.vertexCount, ed.topology);
                    return true;
                }
                APPGL_LOG(SHADER, @"drawArrays GS-emul encode failed");
                // Fall through to the legacy path if encode fails —
                // better to render without the GS effect than to
                // drop the draw entirely.
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArrays GS-emul: %s", ed.diagnostic.c_str());
            }
        }
    }

    // Sprint 7 Phase 2 #7 (CKPT59): VS-only TF emulation. When TF is
    // active, the program has TF varyings, no GS is in the pipeline,
    // and no tess emulation applies, run the VS on CPU per vertex and
    // write captures via the shared writeGsXfbAndCheckDiscard helper.
    // Required for separable VS-only programs (CTS
    // `program_pipeline_vs_gs_capture` pass 2 detaches the GS via
    // glUseProgramStages(GS_BIT, 0) and expects subsequent draws to
    // capture VS outputs to TF).
    // Sprint 8 #9-C (CKPT68): the original CKPT59 gate restricted to
    // `emulProgram == nullptr` to scope VS-only-TF to separable VS-only
    // programs. That over-restricts: any program with no GS/tess emul
    // (regardless of separable status) needs VS-only-TF capture during
    // active TF. Relax to `(emulProgram == nullptr || !emulProgram->
    // geometryEmulated)` — the GS-emul block at line ~24508 only runs
    // when emulProgram->geometryEmulated, so guarding on that condition
    // here mirrors that block's gate exactly. CTS draw_xfb_instanced_test
    // uses a non-separable VS+FS program with TF varyings; without this
    // relaxation, emulProgram is non-null (set to the same program) but
    // doesn't have geometryEmulated, and VS-only-TF skipped → no
    // capturedVertexCount accumulation → glDrawTransformFeedbackInstanced
    // gets count=0 → test fails.
    if (program != nullptr &&
        isTransformFeedbackActive() &&  // CKPT85: per-bound-object
        !program->transformFeedbackVaryingNames.empty() &&
        (emulProgram == nullptr || !emulProgram->geometryEmulated) &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted) {
        const GLuint vaoName2 = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName2 != 0) ? impl_->objects->vertexArrays().get(vaoName2) : nullptr;
        if (vao != nullptr && !program->vertexSpirv.empty()) {
            // Sprint 15 Q3-Option-B Phase 3a [metal-tf-vs]: GPU
            // compute-dispatch path. Replaces the CPU
            // `emulateVsOnlyDrawForTf` SPIR-V interpreter with a Metal
            // VS-as-compute dispatch when the program has a built
            // VS-compute PSO + a reflected output struct + all TF
            // varyings resolved at link time. Day 4 constraint: only
            // attributeless VS programs (`metalVsTfNeedsDescriptor==
            // false`) AND no default-uniform-block usage AND no UBOs
            // (Phase 3a doesn't bind uniforms; Phase 3b adds that).
            // Phase 3c (Day 6+) extends to VAO-bound stage_in
            // programs via `metalVsTfComputePSOCache`.
            //
            // Phase 3a is groundwork-only: gated behind the secondary
            // `APPGL_ENABLE_METAL_TF_VS_DISPATCH=1` env so it stays
            // off by default until Phase 3b lands proper uniform
            // binding. With only the primary gate
            // `APPGL_ENABLE_METAL_TF_VS=1` set, Phase 1+2 link-time
            // reflection runs but draw-time still routes via the
            // CPU helper (preserves CKPT173+CKPT174 behaviour).
            //
            // Falls back to CPU helper on any precondition mismatch
            // OR encoder failure — preserving correctness.
            const bool dispatchGateOn =
                std::getenv("APPGL_ENABLE_METAL_TF_VS_DISPATCH") != nullptr;
            // Phase 3a doesn't yet bind uniform-block bytes — skip
            // GPU path when the VS uses any uniform block (default or
            // named). Phase 3b (Day 5) will populate the uniform
            // bytes from `program->uniformValues` per
            // `vsTfAsComputeReflection`. The VS-as-compute MSL embeds
            // its own default-uniform-block as a UBO at slot 16 (per
            // SPIRV-Cross's tess emit convention), which is exactly
            // what `program.uniforms` feeds when populated.
            // Sprint 15 Day 27 (CKPT200): Phase 3b proper Component A —
            // relax the noUniforms gate and pack uniform bytes from
            // program.uniformValues into the compute encoder at slot
            // 16. Sister-pattern reuse from tess Phase 3 uniform path
            // (line ~25584-25590, `tessVertexAsComputeUniformLayout`
            // + `buildStageUniformBuffer`). The cached layout on the
            // program object survives across draws (link-time stable);
            // packing the byte buffer per draw is cheap.
            bool gpuTfHandled = false;
            if (dispatchGateOn &&
                program->metalVsTfTier ==
                    GLProgramObject::MetalVsTfTier::VsAsCompute &&
                program->metalVsTfComputePipelineState != nullptr &&
                !program->metalVsTfNeedsDescriptor &&
                program->vsTfOutputLayout.structSize > 0 &&
                !program->vsTfResolvedSources.empty() &&
                impl_->frameGraph != nullptr &&
                count > 0 && first >= 0) {
                // Verify every TF varying name resolved (skip GPU
                // path otherwise — CPU helper covers exotic varying
                // shapes more robustly).
                bool allResolved = true;
                for (const auto& s : program->vsTfResolvedSources) {
                    if (s.bytes == 0) { allResolved = false; break; }
                }
                if (allResolved) {
                    const std::size_t perVertexBytes =
                        program->vsTfOutputLayout.structSize;
                    std::vector<std::uint8_t> outBytes(
                        perVertexBytes * static_cast<std::size_t>(count));
                    // Phase 3b Component A: pack uniform bytes when
                    // the VS reflection reports any uniform blocks.
                    // Lazy layout-cache build on first dispatch.
                    thread_local std::vector<std::uint8_t> vsTfUniformScratch;
                    const std::uint8_t* uniformBytesPtr = nullptr;
                    std::size_t uniformBytesLen = 0;
                    if (!program->vsTfAsComputeReflection.uniformBlocks.empty()) {
                        if (program->vsTfAsComputeUniformLayout.empty()) {
                            computeStageUniformLayout(
                                program->vsTfAsComputeUniformLayout,
                                program->vsTfAsComputeReflection,
                                program->uniforms);
                        }
                        if (!program->vsTfAsComputeUniformLayout.empty()) {
                            buildStageUniformBuffer(
                                vsTfUniformScratch,
                                program->vsTfAsComputeReflection,
                                program->uniformValues,
                                program->vsTfAsComputeUniformLayout);
                            uniformBytesPtr = vsTfUniformScratch.data();
                            uniformBytesLen = vsTfUniformScratch.size();
                        }
                    }
                    const bool encodeOk =
                        impl_->frameGraph->encodeVsTfComputeDraw(
                            program->metalVsTfComputePipelineState,
                            static_cast<std::uint32_t>(count),
                            perVertexBytes,
                            uniformBytesPtr,
                            uniformBytesLen,
                            outBytes.data());
                    if (encodeOk) {
                        impl_->writeVsTfFromComputeOutput(
                            *program, outBytes.data(),
                            static_cast<std::uint32_t>(count),
                            perVertexBytes, mode);
                        if (impl_->state->isEnabled(GL_RASTERIZER_DISCARD)) {
                            return true;
                        }
                        // Without rasterizer-discard, fall through to
                        // the regular Metal-side draw so the FS still
                        // runs. TF buffer is already populated above.
                        gpuTfHandled = true;
                    }
                }
            }
            if (!gpuTfHandled) {
                appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                    *program, *vao, *impl_->objects, *impl_->state,
                    mode, count, first);
                if (ed.ok) {
                    if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) {
                        return true;
                    }
                    // VS-only-TF without rasterizer-discard: fall
                    // through to the regular Metal-side draw so the
                    // FS still runs. The TF buffer was already
                    // populated.
                } else if (!ed.diagnostic.empty()) {
                    APPGL_LOG(SHADER, @"drawArrays VS-only-TF: %s",
                              ed.diagnostic.c_str());
                }
            }
        }
    }

    // Sprint 17 Day 7+ Bank-Group-H Path B Component B (drawArrays):
    // VS+FS programs that write gl_CullDistance get a CPU pre-pass +
    // Metal indexed-draw routing. Phase 2 §1.2 confirmed this is gated
    // on `needsCullDistancePrepass` (link-time A1 detect: VS writes
    // CullDistance && !gsPresent && !hasTessellation) + line/triangle
    // topology. Component E (Phase 3 day 5) handles TF coordination.
    if (program != nullptr && program->needsCullDistancePrepass &&
        program->hasTranslatedPipeline) {
        const bool isLineOrTri =
            (mode == GL_POINTS || mode == GL_LINES || mode == GL_TRIANGLES ||
             mode == GL_LINE_STRIP || mode == GL_LINE_LOOP ||
             mode == GL_TRIANGLE_STRIP || mode == GL_TRIANGLE_FAN);
        if (isLineOrTri) {
            const GLuint vaoNameCP = impl_->state->boundVertexArray();
            GLVertexArrayObject* vaoCP = (vaoNameCP != 0)
                ? impl_->objects->vertexArrays().get(vaoNameCP) : nullptr;
            if (vaoCP != nullptr) {
                std::vector<std::uint32_t> filteredIdx;
                std::string cullDiag;
                const bool prepassOk = appgl::emulateVsCullPrepass(
                    *program, *vaoCP, *impl_->objects, *impl_->state,
                    mode, count, first, /*elementIndices=*/nullptr,
                    /*instanceCount=*/1, /*baseInstance=*/0,
                    filteredIdx, &cullDiag);
                if (prepassOk) {
                    if (filteredIdx.empty()) {
                        // GL §14.6.3 — all primitives culled. Count
                        // input primitives and short-circuit. Legacy
                        // path is bypassed so do the counter update
                        // here (its own update would otherwise run
                        // in the fall-through case below).
                        if (!program->gsPresent) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                    if (impl_->dispatchCullFilteredDraw(
                            *program, *vaoCP, programName, mode,
                            filteredIdx)) {
                        if (!program->gsPresent) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                    // Fall through to legacy path on encode failure
                    // (legacy path runs its own counter update).
                } else if (!cullDiag.empty()) {
                    APPGL_LOG(SHADER, @"drawArrays cull-prepass: %s",
                              cullDiag.c_str());
                }
            }
        }
    }

    if (program != nullptr && program->hasTranslatedPipeline) {
        // GL 4.6 §22.1 / §22.3 — non-GS draws credit the
        // PRIMITIVES_GENERATED and TRANSFORM_FEEDBACK_PRIMITIVES_-
        // WRITTEN counters with the input-primitive count. GS-
        // emulated draws already counted post-GS primitives inside
        // writeGsXfbAndCheckDiscard, so skip this path to avoid
        // double-counting.
        if (!program->gsPresent) {
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1);
        }
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        // Phase 8X Group 4d follow-up³ — name each fall-through gate to BAR's log.
        const bool gateEmpty = (vao == nullptr || vao->attributes.empty());
        // Attributeless draw path: vertex shader has no vertex inputs
        // (generates its own vertices via gl_VertexID / [[vertex_id]]).
        const bool attributelessDraw = (vao != nullptr &&
            program->vertexReflection.vertexInputs.empty());
        if (attributelessDraw) {
            TranslatedDrawInfo tdi;
            tdi.mode = mode;
            tdi.vertexCount = count;
            // No vertex data — shader uses gl_VertexID / [[vertex_id]].
            tdi.vertexData = nullptr;
            tdi.vertexDataByteCount = 0;
            tdi.vertexStride = 0;
            populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
            tdi.vertexMSL = &program->vertexMSL;
            tdi.fragmentMSL = &program->fragmentMSL;
            tdi.vertexReflection = &program->vertexReflection;
            tdi.fragmentReflection = &program->fragmentReflection;
            tdi.pipelineStateOut = &program->metalPipelineState;
            tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
            tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
            tdi.metalVertexFunction = program->metalVertexFunction;
            tdi.metalFragmentFunction = program->metalFragmentFunction;
            tdi.metalVertexFunctionOut = &program->metalVertexFunction;
            tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
            tdi.program = programName;

            // Uniform layout (cached).
            if (!program->uniformLayoutComputed) {
                computeStageUniformLayout(program->vertexUniformLayout,
                    program->vertexReflection, program->uniforms);
                computeStageUniformLayout(program->fragmentUniformLayout,
                    program->fragmentReflection, program->uniforms);
                program->uniformLayoutComputed = true;
            }
            thread_local std::vector<std::uint8_t> vtxUniformScratch;
            thread_local std::vector<std::uint8_t> fragUniformScratch;
            pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
            buildStageUniformBuffer(vtxUniformScratch,
                program->vertexReflection, program->uniformValues,
                program->vertexUniformLayout);
            buildStageUniformBuffer(fragUniformScratch,
                program->fragmentReflection, program->uniformValues,
                program->fragmentUniformLayout);
            tdi.vertexUniformData = vtxUniformScratch.data();
            tdi.vertexUniformSize = vtxUniformScratch.size();
            tdi.fragmentUniformData = fragUniformScratch.data();
            tdi.fragmentUniformSize = fragUniformScratch.size();

            impl_->resolveSamplerBindings(*program, tdi);
            impl_->resolveUBOBindings(*program, tdi);
            impl_->resolveSSBOBindings(*program, tdi);
            impl_->resolveImageBindings(*program, tdi);

            // RC-A02: resolve FBO render target.
            {
                GLsizei fboW = 0, fboH = 0;
                void* fboDSTex = nullptr;
                std::array<void*, 7> extraColTex = {};
                std::array<std::uint32_t, 8> colSlices = {};
                void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
                if (fboColTex != nullptr || fboDSTex != nullptr) {
                    tdi.fboColorTexture = fboColTex;
                    tdi.fboAdditionalColorTextures = extraColTex;
                    tdi.fboColorSlices = colSlices;
                    tdi.fboDepthStencilTexture = fboDSTex;
                    tdi.fboWidth = fboW;
                    tdi.fboHeight = fboH;
                }
            }

            thread_local std::string pipelineBuildError;
            pipelineBuildError.clear();
            tdi.pipelineBuildErrorOut = &pipelineBuildError;

            const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
            if (ok) {
                return true;
            }
            // Fall through to solid-color path on failure.
        }
        if (vao == nullptr) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawArrays",
                vaoName, 0, 0, 0);
        }
        if (vao != nullptr && !vao->attributes.empty()) {
            // Find the first ENABLED attribute for primary-VBO detection.
            // Shaders that bind via `layout(location=N)` with N > 0 leave
            // attribute 0 disabled — cull_distance CTS tests (9 attributes
            // at locations 1..9, attribute 0 unused) were silently
            // skipping the encodeTranslatedDraw path entirely because the
            // unused attribute 0 has bufferName=0.
            std::size_t primaryIdx = 0;
            for (std::size_t ai = 0; ai < vao->attributes.size(); ++ai) {
                if (vao->attributes[ai].enabled) { primaryIdx = ai; break; }
            }
            const auto& posAttr = vao->attributes[primaryIdx];
            auto resolved = resolveVertexAttrib(posAttr, *vao);
            GLBufferObject* vbo = (resolved.bufferName != 0)
                ? impl_->objects->buffers().get(resolved.bufferName) : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawArrays",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawArrays",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = resolved.stride;
                const std::size_t firstOff = static_cast<std::size_t>(first) * posStride;
                const std::size_t startOff = resolved.offset + firstOff;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawArrays",
                        vaoName, vao->attributes.size(), resolved.bufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo tdi;
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    // OPT-5: pass pre-uploaded Metal buffer for direct bind.
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    // Phase 8X Group 4d follow-up¹⁴ — centralised fixed-
                    // function state snapshot (depth/cull/front-face/
                    // wireframe/blend). Replaces the prior inline reads
                    // so drawArrays / drawArraysInstanced / drawElements
                    // all capture identical state.
                    populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
                    tdi.vertexMSL = &program->vertexMSL;
                    tdi.fragmentMSL = &program->fragmentMSL;
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    // Phase 8X Group 4d follow-up¹⁴ — map-based cache
                    // so spring's 15×/frame blend toggle doesn't thrash
                    // the single-slot scalar cache above.
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    // Phase 8X Group 4d follow-up⁸ — diagnostic-only
                    // program identifier used by encodeTranslatedDraw's
                    // first-draw-per-program NSLog. Non-owning, no
                    // correctness impact; zero is a valid placeholder.
                    tdi.program = programName;

                    // Collect per-attribute layout from the VAO.  Attributes
                    // sharing the primary VBO AND the primary stride go into
                    // vertexAttributeLayouts (Metal buffer 0).  Attributes in a
                    // different VBO or with a different effective stride are
                    // placed into extraVertexBuffers (Metal buffer 1+) so each
                    // group gets its own MTLVertexDescriptor layout stride.
                    //
                    // Phase 8X Group 4d follow-up¹⁴ — the VAO fields
                    // (`glType/glComponentCount/glNormalized/glIsInteger`)
                    // are now carried end-to-end so encodeTranslatedDraw
                    // can derive the real MTLVertexFormat from the VBO
                    // layout rather than the shader-reflected scalar type.
                    //
                    // The extra-buffer grouping key is (bufferName, stride).
                    // A helper map collects non-primary groups; after the loop
                    // each group becomes one ExtraVertexBuffer entry.
                    struct ExtraGroupKey {
                        GLuint bufferName;
                        std::size_t stride;
                        bool operator==(const ExtraGroupKey& o) const {
                            return bufferName == o.bufferName && stride == o.stride;
                        }
                    };
                    struct ExtraGroupKeyHash {
                        std::size_t operator()(const ExtraGroupKey& k) const {
                            return std::hash<GLuint>()(k.bufferName) ^ (std::hash<std::size_t>()(k.stride) << 16);
                        }
                    };
                    std::unordered_map<ExtraGroupKey, std::size_t, ExtraGroupKeyHash> extraGroupIndex;
                    for (std::size_t ai = 0; ai < vao->attributes.size(); ++ai) {
                        const auto& attr = vao->attributes[ai];
                        if (!attr.enabled) continue;
                        auto attrRes = resolveVertexAttrib(attr, *vao);
                        TranslatedDrawInfo::VertexAttributeLayout layout;
                        layout.location = static_cast<GLuint>(ai);
                        populateVertexAttributeLayoutVAOFields(layout, attr);

                        if (attrRes.bufferName == resolved.bufferName &&
                            attrRes.stride == posStride) {
                            // Primary group: same VBO + same stride → buffer 0.
                            layout.offset = attrRes.offset - resolved.offset;
                            tdi.vertexAttributeLayouts.push_back(layout);
                        } else {
                            // Different VBO or different stride → extra buffer.
                            ExtraGroupKey key{attrRes.bufferName, attrRes.stride};
                            auto it = extraGroupIndex.find(key);
                            std::size_t idx;
                            if (it == extraGroupIndex.end()) {
                                idx = tdi.extraVertexBuffers.size();
                                extraGroupIndex[key] = idx;
                                GLBufferObject* extraVbo =
                                    impl_->objects->buffers().get(attrRes.bufferName);
                                TranslatedDrawInfo::ExtraVertexBuffer evb;
                                evb.stride = attrRes.stride;
                                evb.divisor = 0;
                                if (extraVbo != nullptr && !extraVbo->shadowBytes.empty()) {
                                    const std::size_t extraFirstOff =
                                        static_cast<std::size_t>(first) * attrRes.stride;
                                    evb.data = extraVbo->shadowBytes.data();
                                    evb.byteCount = extraVbo->shadowBytes.size();
                                    evb.metalBuffer = extraVbo->metalBuffer;
                                    evb.metalBufferOffset = extraFirstOff;
                                }
                                tdi.extraVertexBuffers.push_back(std::move(evb));
                            } else {
                                idx = it->second;
                            }
                            layout.offset = attrRes.offset;
                            tdi.extraVertexBuffers[idx].attributes.push_back(layout);
                        }
                    }

                    // OPT-7: compute uniform layout once, reuse every draw.
                    if (!program->uniformLayoutComputed) {
                        computeStageUniformLayout(program->vertexUniformLayout,
                            program->vertexReflection, program->uniforms);
                        computeStageUniformLayout(program->fragmentUniformLayout,
                            program->fragmentReflection, program->uniforms);
                        program->uniformLayoutComputed = true;
                    }

                    // Build per-stage uniform buffers using the cached layout.
                    // Thread-local scratch buffers retain their allocation
                    // across draw calls — zero heap allocs after warmup.
                    thread_local std::vector<std::uint8_t> vtxUniformScratch;
                    thread_local std::vector<std::uint8_t> fragUniformScratch;
                    // Push synthesized fixed-function matrix uniforms into
                    // program->uniformValues for compat-rewritten shaders.
                    // Early-out for the common (core-profile) case.
                    pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
                    buildStageUniformBuffer(vtxUniformScratch,
                        program->vertexReflection, program->uniformValues,
                        program->vertexUniformLayout);
                    buildStageUniformBuffer(fragUniformScratch,
                        program->fragmentReflection, program->uniformValues,
                        program->fragmentUniformLayout);
                    tdi.vertexUniformData = vtxUniformScratch.data();
                    tdi.vertexUniformSize = vtxUniformScratch.size();
                    tdi.fragmentUniformData = fragUniformScratch.data();
                    tdi.fragmentUniformSize = fragUniformScratch.size();

                    // Phase 8X Group 4d follow-up⁷ — resolve each sampler
                    // uniform in the program to the Metal texture + sampler
                    // state currently bound to its GL texture unit, then
                    // append the pairs to the TranslatedDrawInfo binding
                    // vectors. See `Impl::resolveSamplerBindings` for the
                    // resolution rules. This is the structural hole behind
                    // the smeared-glyph observation from followup⁶
                    // verification §Visual — prior to this round,
                    // encodeTranslatedDraw bound zero textures/samplers
                    // and the fragment shader sampled from an unbound
                    // slot.
                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target when a user FBO is bound.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    // Phase 8X Group 4d follow-up⁴ — scratch buffer for the
                    // pipeline-build error text plumbed out of the encode-failed
                    // path. Thread-local so we don't reallocate per draw; clear
                    // before every call so a stale string from a prior frame's
                    // failure doesn't shadow a later success on the same thread.
                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawArrays",
                            vaoName, vao->attributes.size(), resolved.bufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                    // Fall through to solid-color path on failure.
                }
            }
        }
    }

    // Fallback: solid-color draw path (hardcoded appgl_solid pipeline).
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(*impl_->state, *impl_->objects, mode, "glDrawArrays");
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawArrays: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        return false;
    }

    setup.info.vertexCount = count;
    setup.info.baseVertex = first;
    const std::size_t stride = setup.info.positionStride;
    const std::size_t firstOffset = static_cast<std::size_t>(first) * stride;
    const std::size_t startOffset = static_cast<std::size_t>(setup.vertexArray->attributes[0].pointer) + firstOffset;
    if (startOffset > setup.positionShadowSize) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    setup.info.positions = setup.positionShadow + startOffset;
    setup.info.positionByteCount = setup.positionShadowSize - startOffset;
    setup.info.indices = nullptr;
    setup.info.indexCount = 0;
    setup.info.indexType = 0;

    const bool ok = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (!ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawArrays: MetalFrameGraph failed to encode draw"
        );
    }
    return ok;
}

bool GLContext::drawArraysInstanced(GLenum mode, GLint first, GLsizei count, GLsizei instancecount) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    // GL 4.6 §11.3.1: draw-mode / GS-input-topology compat applies
    // to EVERY draw entry that targets a GS-linked program, not just
    // glDrawArrays. CTS `draw_indirect.negative-gshIncompatible-arrays`
    // calls `glDrawArraysIndirect(GL_POINTS, 0)` on a program with a
    // `layout(triangles) in` GS and expects INVALID_OPERATION. The
    // indirect path decomposes to drawArraysInstancedBaseInstance →
    // this function, so the gate lives here.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        // Same tess-in-pipeline escape as drawArrays — see the
        // longer comment at the top of drawArrays's matching check.
        if (p != nullptr && p->gsPresent && !p->hasTessellation &&
            !isDrawModeCompatibleWithGs(mode, p->gsInputTopology)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update for
        // non-GS draws. GS-emulated paths credit via
        // writeGsXfbAndCheckDiscard instead.
        if (p == nullptr || !p->gsPresent) {
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, instancecount);
        }
    }
    if (impl_->frameGraph == nullptr) {
        return false;
    }
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Translated shader pipeline with instancing.
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);

    // Phase 3f-16: tess-emul hook for instanced drawArrays. The
    // interpreter currently treats every instance identically (the
    // VS pre-pass ignores instance — gl_InstanceID seeding lives
    // in runVsForVertex but isn't stepped here). Correct for tess
    // tests that don't read gl_InstanceID in the VS; CTS uses
    // instancing primarily for attribute-divisor checks that the
    // passthrough matcher path handles correctly.
    if (program != nullptr &&
        (program->tessellationEmulated || program->tessellationInterpreted) &&
        !program->geometryEmulated && count > 0 && instancecount > 0) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* tvao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (tvao != nullptr) {
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *program, *tvao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                instancecount, /*baseInstance=*/0);
            if (ted.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ted)) return true;
                if (ted.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ted)) return true;
            }
        }
    }

    // GS emul hook for instanced draws.
    if (program != nullptr && program->geometryEmulated && count > 0 && instancecount > 0) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr) {
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, first, /*elementIndices=*/nullptr,
                instancecount, /*baseInstance=*/0);
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) return true;
                if (ed.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) return true;
            }
        }
    }

    if (program != nullptr &&
        isTransformFeedbackActive() &&
        !program->transformFeedbackVaryingNames.empty() &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted &&
        count > 0 && instancecount > 0) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0)
            ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        if (vao != nullptr && !program->vertexSpirv.empty()) {
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, first, instancecount, /*baseInstance=*/0,
                /*elementIndices=*/nullptr);
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) {
                    return true;
                }
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawArraysInstanced VS-only-TF: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    if (program != nullptr && program->hasTranslatedPipeline) {
        const GLuint vaoName = impl_->state->boundVertexArray();
        GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
        // Attributeless instanced draw path: vertex shader has no vertex inputs.
        const bool attributelessInstDraw = (vao != nullptr &&
            program->vertexReflection.vertexInputs.empty());
        if (attributelessInstDraw) {
            TranslatedDrawInfo tdi;
            tdi.mode = mode;
            tdi.vertexCount = count;
            tdi.instanceCount = instancecount;
            tdi.vertexData = nullptr;
            tdi.vertexDataByteCount = 0;
            tdi.vertexStride = 0;
            populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
            tdi.vertexMSL = &program->vertexMSL;
            tdi.fragmentMSL = &program->fragmentMSL;
            tdi.vertexReflection = &program->vertexReflection;
            tdi.fragmentReflection = &program->fragmentReflection;
            tdi.pipelineStateOut = &program->metalPipelineState;
            tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
            tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
            tdi.metalVertexFunction = program->metalVertexFunction;
            tdi.metalFragmentFunction = program->metalFragmentFunction;
            tdi.metalVertexFunctionOut = &program->metalVertexFunction;
            tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
            tdi.program = programName;
            if (!program->uniformLayoutComputed) {
                computeStageUniformLayout(program->vertexUniformLayout,
                    program->vertexReflection, program->uniforms);
                computeStageUniformLayout(program->fragmentUniformLayout,
                    program->fragmentReflection, program->uniforms);
                program->uniformLayoutComputed = true;
            }
            thread_local std::vector<std::uint8_t> vtxUniformScratch;
            thread_local std::vector<std::uint8_t> fragUniformScratch;
            pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
            buildStageUniformBuffer(vtxUniformScratch,
                program->vertexReflection, program->uniformValues,
                program->vertexUniformLayout);
            buildStageUniformBuffer(fragUniformScratch,
                program->fragmentReflection, program->uniformValues,
                program->fragmentUniformLayout);
            tdi.vertexUniformData = vtxUniformScratch.data();
            tdi.vertexUniformSize = vtxUniformScratch.size();
            tdi.fragmentUniformData = fragUniformScratch.data();
            tdi.fragmentUniformSize = fragUniformScratch.size();
            impl_->resolveSamplerBindings(*program, tdi);
            impl_->resolveUBOBindings(*program, tdi);
            impl_->resolveSSBOBindings(*program, tdi);
            impl_->resolveImageBindings(*program, tdi);
            {
                GLsizei fboW = 0, fboH = 0;
                void* fboDSTex = nullptr;
                std::array<void*, 7> extraColTex = {};
                std::array<std::uint32_t, 8> colSlices = {};
                void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
                if (fboColTex != nullptr || fboDSTex != nullptr) {
                    tdi.fboColorTexture = fboColTex;
                    tdi.fboAdditionalColorTextures = extraColTex;
                    tdi.fboColorSlices = colSlices;
                    tdi.fboDepthStencilTexture = fboDSTex;
                    tdi.fboWidth = fboW;
                    tdi.fboHeight = fboH;
                }
            }
            thread_local std::string pipelineBuildError;
            pipelineBuildError.clear();
            tdi.pipelineBuildErrorOut = &pipelineBuildError;
            const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
            if (ok) {
                return true;
            }
        }
        if (vao == nullptr) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawArraysInstanced",
                vaoName, 0, 0, 0);
        }
        if (vao != nullptr && !vao->attributes.empty()) {
            // Find the first ENABLED attribute for primary-VBO detection.
            // Shaders that bind via `layout(location=N)` with N > 0 leave
            // attribute 0 disabled — cull_distance CTS tests (9 attributes
            // at locations 1..9, attribute 0 unused) were silently
            // skipping the encodeTranslatedDraw path entirely because the
            // unused attribute 0 has bufferName=0.
            std::size_t primaryIdx = 0;
            for (std::size_t ai = 0; ai < vao->attributes.size(); ++ai) {
                if (vao->attributes[ai].enabled) { primaryIdx = ai; break; }
            }
            const auto& posAttr = vao->attributes[primaryIdx];
            auto resolved = resolveVertexAttrib(posAttr, *vao);
            GLBufferObject* vbo = (resolved.bufferName != 0)
                ? impl_->objects->buffers().get(resolved.bufferName) : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawArraysInstanced",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawArraysInstanced",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = resolved.stride;
                const std::size_t firstOff = static_cast<std::size_t>(first) * posStride;
                const std::size_t startOff = resolved.offset + firstOff;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawArraysInstanced",
                        vaoName, vao->attributes.size(), resolved.bufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo tdi;
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.instanceCount = instancecount;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    // OPT-5: pass pre-uploaded Metal buffer for direct bind.
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    // Phase 8X Group 4d follow-up¹⁴ — centralised fixed-
                    // function state snapshot. See drawArrays.
                    populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
                    tdi.vertexMSL = &program->vertexMSL;
                    tdi.fragmentMSL = &program->fragmentMSL;
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    // Phase 8X Group 4d follow-up¹⁴ — map-based cache
                    // so spring's 15×/frame blend toggle doesn't thrash
                    // the single-slot scalar cache above.
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    // Phase 8X Group 4d follow-up⁸ — diagnostic-only
                    // program identifier used by encodeTranslatedDraw's
                    // first-draw-per-program NSLog. Non-owning, no
                    // correctness impact; zero is a valid placeholder.
                    tdi.program = programName;

                    // Gather vertex attributes — group by (VBO, stride, divisor).
                    // Primary group: same VBO + same stride + divisor=0 → buffer 0.
                    // Everything else → extraVertexBuffers (buffer 1+).
                    //
                    // Phase 8X Group 4d follow-up¹⁴ — propagate VAO format
                    // fields (`glType/glComponentCount/glNormalized/
                    // glIsInteger`) for both the primary-buffer path and
                    // the extra-buffer path so encodeTranslatedDraw can
                    // derive the real MTLVertexFormat.
                    struct InstGroupKey {
                        GLuint bufferName;
                        std::size_t stride;
                        GLuint divisor;
                        bool operator==(const InstGroupKey& o) const {
                            return bufferName == o.bufferName
                                && stride == o.stride
                                && divisor == o.divisor;
                        }
                    };
                    struct InstGroupKeyHash {
                        std::size_t operator()(const InstGroupKey& k) const {
                            return std::hash<GLuint>()(k.bufferName)
                                 ^ (std::hash<std::size_t>()(k.stride) << 16)
                                 ^ (std::hash<GLuint>()(k.divisor) << 24);
                        }
                    };
                    std::unordered_map<InstGroupKey, std::size_t, InstGroupKeyHash> extraBufferMap;

                    for (std::size_t ai = 0; ai < vao->attributes.size(); ++ai) {
                        const auto& attr = vao->attributes[ai];
                        if (!attr.enabled) continue;

                        auto attrRes = resolveVertexAttrib(attr, *vao);
                        GLuint attrDivisor = attr.useSeparatedFormat
                            ? (attr.bindingIndex < vao->bindingPoints.size()
                                ? vao->bindingPoints[attr.bindingIndex].divisor
                                : attr.divisor)
                            : attr.divisor;

                        TranslatedDrawInfo::VertexAttributeLayout layout;
                        layout.location = static_cast<GLuint>(ai);
                        populateVertexAttributeLayoutVAOFields(layout, attr);

                        if (attrRes.bufferName == resolved.bufferName
                            && attrRes.stride == posStride
                            && attrDivisor == 0) {
                            // Same VBO + same stride + per-vertex → buffer 0.
                            layout.offset = attrRes.offset - resolved.offset;
                            tdi.vertexAttributeLayouts.push_back(layout);
                        } else {
                            GLBufferObject* extraVbo = impl_->objects->buffers().get(attrRes.bufferName);
                            if (extraVbo == nullptr || extraVbo->shadowBytes.empty()) continue;

                            InstGroupKey key{attrRes.bufferName, attrRes.stride, attrDivisor};
                            auto it = extraBufferMap.find(key);
                            std::size_t idx;
                            if (it == extraBufferMap.end()) {
                                idx = tdi.extraVertexBuffers.size();
                                extraBufferMap[key] = idx;

                                TranslatedDrawInfo::ExtraVertexBuffer evb;
                                evb.data = extraVbo->shadowBytes.data();
                                evb.byteCount = extraVbo->shadowBytes.size();
                                evb.stride = attrRes.stride;
                                evb.divisor = attrDivisor;
                                evb.metalBuffer = extraVbo->metalBuffer;
                                evb.metalBufferOffset =
                                    static_cast<std::size_t>(first) * attrRes.stride;
                                tdi.extraVertexBuffers.push_back(std::move(evb));
                            } else {
                                idx = it->second;
                            }

                            layout.offset = attrRes.offset;
                            tdi.extraVertexBuffers[idx].attributes.push_back(layout);
                        }
                    }

                    // OPT-7: compute uniform layout once, reuse every draw.
                    if (!program->uniformLayoutComputed) {
                        computeStageUniformLayout(program->vertexUniformLayout,
                            program->vertexReflection, program->uniforms);
                        computeStageUniformLayout(program->fragmentUniformLayout,
                            program->fragmentReflection, program->uniforms);
                        program->uniformLayoutComputed = true;
                    }

                    thread_local std::vector<std::uint8_t> vtxUniformScratch;
                    thread_local std::vector<std::uint8_t> fragUniformScratch;
                    // Push synthesized fixed-function matrix uniforms (compat
                    // shader path). Early-out for the common core-profile case.
                    pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
                    buildStageUniformBuffer(vtxUniformScratch,
                        program->vertexReflection, program->uniformValues,
                        program->vertexUniformLayout);
                    buildStageUniformBuffer(fragUniformScratch,
                        program->fragmentReflection, program->uniformValues,
                        program->fragmentUniformLayout);
                    tdi.vertexUniformData = vtxUniformScratch.data();
                    tdi.vertexUniformSize = vtxUniformScratch.size();
                    tdi.fragmentUniformData = fragUniformScratch.data();
                    tdi.fragmentUniformSize = fragUniformScratch.size();

                    // Phase 8X Group 4d follow-up⁷ — see matching comment in
                    // drawArrays for rationale; the instanced draw path
                    // needs identical sampler resolution.
                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    // Phase 8X Group 4d follow-up⁴ — scratch buffer for the
                    // pipeline-build error text plumbed out of the encode-failed
                    // path. See the matching comment in drawArrays for rationale.
                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawArraysInstanced",
                            vaoName, vao->attributes.size(), resolved.bufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                }
            }
        }
    }

    // Instanced drawing has no solid-color fallback.
    emitDebugMessage(
        GL_DEBUG_SOURCE_API,
        GL_DEBUG_TYPE_OTHER,
        0,
        GL_DEBUG_SEVERITY_LOW,
        "glDrawArraysInstanced: no translated pipeline available"
    );
    return false;
}

bool GLContext::drawElements(GLenum mode, GLsizei count, GLenum type, const void* indices) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update for non-GS
    // indexed draws. GS path is handled by writeGsXfbAndCheckDiscard.
    // Sprint 8 #9-A (CKPT67): VS-only TF capture path (CKPT59 helper)
    // also calls writeGsXfbAndCheckDiscard which advances queries
    // with TF-buffer-bounded primsWritten. Skip the unconditional
    // pre-update when the VS-only-TF helper will engage downstream
    // (transformFeedbackActive + TF varyings + no GS/tess emul) so
    // the bounded primsWritten doesn't double-count atop the
    // unbounded `count`-based pre-update.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        const bool willHitVsOnlyTf =
            p != nullptr &&
            isTransformFeedbackActive() &&  // CKPT85: per-bound-object
            !p->transformFeedbackVaryingNames.empty() &&
            !p->geometryEmulated &&
            !p->tessellationEmulated &&
            !p->tessellationInterpreted;
        if ((p == nullptr || !p->gsPresent) && !willHitVsOnlyTf) {
            const GLsizei restartSkip = impl_->countRestartIndices(type, indices, count);
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1, restartSkip);
        }
    }

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    // Size the drawable before flushing the clear — see glDrawArrays for the
    // rationale.
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Resolve element buffer early — needed by both translated and solid paths.
    const GLuint vaoName = impl_->state->boundVertexArray();
    GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
    if (vao == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLuint elementBufferName = vao->elementArrayBuffer;
    GLenum effectiveType = type;
    const void* effectivePtr = nullptr;
    GLBufferObject* elementBuffer = nullptr;
    std::size_t indexOffset = 0;

    // Sprint 7 #9 (CKPT65): GL 2.x compatibility — when no
    // GL_ELEMENT_ARRAY_BUFFER is bound, the `indices` parameter is a
    // client-side pointer to `count` indices in CPU memory (not a
    // buffer offset). Materialize the data into a thread-local scratch
    // buffer, applying GL_UNSIGNED_BYTE→GL_UNSIGNED_SHORT promotion
    // the same way the buffer-bound path does. CTS
    // `transform_feedback.{capture,query,discard}_vertex_*` tests use
    // this pattern with a stack-allocated GLuint[] passed directly to
    // glDrawElements.
    thread_local std::vector<std::uint8_t> clientIndexScratch;
    if (elementBufferName == 0) {
        if (count > 0 && indices == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        if (count > 0) {
            IndexExpansionResult result = expandElementIndices(count, type, indices);
            if (!result.ok) {
                pushError(result.error);
                return false;
            }
            clientIndexScratch = std::move(result.bytes);
            effectivePtr = clientIndexScratch.data();
            effectiveType = result.outputType;
        }
        // elementBuffer stays nullptr; indexOffset stays 0. Downstream
        // Metal-buffer-pass-through gates on `elementBuffer != nullptr`
        // so the client-side path naturally falls into the
        // CPU-staging-buffer branch.
    } else {
        elementBuffer = impl_->objects->buffers().get(elementBufferName);
        if (elementBuffer == nullptr || elementBuffer->shadowBytes.empty()) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }

        indexOffset = reinterpret_cast<std::uintptr_t>(indices);
        if (indexOffset > elementBuffer->shadowBytes.size()) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        const void* indexPtr = elementBuffer->shadowBytes.data() + indexOffset;

        // GL_UNSIGNED_BYTE is not supported natively by Metal; expandElementIndices
        // promotes to GL_UNSIGNED_SHORT. For UINT16/UINT32 we can pass through.
        //
        // ADV-10: cache the expanded index buffer on the GLBufferObject so
        // repeated drawElements calls with the same element buffer don't
        // re-allocate and re-widen on every draw.  The cache covers the
        // entire shadowBytes range (not per-offset subsets) and is
        // invalidated when the buffer data changes via glBufferData /
        // glBufferSubData (generation counter bump).
        effectivePtr = indexPtr;
        if (elementIndexTypeNeedsExpansion(type)) {
            // Rebuild cache if stale or absent.
            if (elementBuffer->cachedExpansionGeneration != elementBuffer->indexExpansionGeneration
                || elementBuffer->cachedExpandedIndices.empty()) {
                const GLsizei totalIndices = static_cast<GLsizei>(elementBuffer->shadowBytes.size());
                IndexExpansionResult result = expandElementIndices(
                    totalIndices, type, elementBuffer->shadowBytes.data());
                if (!result.ok) {
                    pushError(result.error);
                    return false;
                }
                elementBuffer->cachedExpandedIndices = std::move(result.bytes);
                elementBuffer->cachedExpansionGeneration = elementBuffer->indexExpansionGeneration;
            }
            effectiveType = GL_UNSIGNED_SHORT;
            // Recompute offset: each source byte becomes 2 bytes (uint16).
            const std::size_t expandedOffset = indexOffset * sizeof(GLushort);
            effectivePtr = elementBuffer->cachedExpandedIndices.data() + expandedOffset;
        }
    }

    // Try the translated shader pipeline first (GPU-side vertex processing).
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);

    // Phase 3f-16: CPU TES emulation hook for drawElements. Mirrors
    // the drawArrays block but feeds the resolved index buffer into
    // emulateTessellationDraw so the VS pre-pass reads the indexed
    // VBO slots. Same short-circuit shape: rasterDiscard /
    // zero-vertex / encode. On ok=false (interpreter bailed per
    // 3f-15 or classifier rejected) we fall through to the GS-emul
    // path below, which in turn falls through to the legacy
    // translated pipeline.
    if (program != nullptr &&
        (program->tessellationEmulated || program->tessellationInterpreted) &&
        !program->geometryEmulated && count > 0) {
        std::vector<std::uint32_t> idx32;
        if (effectiveType == GL_UNSIGNED_INT) {
            idx32.assign(count, 0);
            std::memcpy(idx32.data(), effectivePtr, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            idx32.assign(count, 0);
            const std::uint16_t* src16 =
                static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        }
        if (!idx32.empty()) {
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, idx32.data());
            if (ted.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ted)) return true;
                if (ted.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ted)) return true;
            }
        }
    }

    // CPU GS emulation hook — mirrors drawArrays, but resolves
    // indices through the element buffer so vertex `i` reads VBO
    // slot `elementIndices[i]` instead of `first + i`. Scoped to
    // the TF-capture / rasterizer-discard case for now (that's
    // what KHR-GL46.geometry_shader.adjacency.*_indiced and the
    // primitive_counter tests exercise); a drawElements GS-emul
    // encode path with synthesised pass-through VS is a follow-up.
    if (program != nullptr && program->geometryEmulated && count > 0) {
        // Resolve effectivePtr (uint16 / uint32) into a uint32 vector
        // scoped to this draw. Small allocation cost — CTS draws
        // never exceed a few hundred indices.
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            const std::uint32_t* src32 = static_cast<const std::uint32_t*>(effectivePtr);
            std::memcpy(idx32.data(), src32, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 = static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            // GL_UNSIGNED_BYTE never reaches here — elementIndex-
            // TypeNeedsExpansion promotes it to uint16 above.
            // Any other type falls through to the legacy draw path.
            idx32.clear();
        }

        if (!idx32.empty()) {
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, idx32.data());
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) {
                    return true;
                }
                if (ed.vertexCount == 0) return true;
                // Non-discard path — the expanded vertex buffer is
                // already flat, so the encode is identical to
                // drawArrays. This covers CTS rendering tests that
                // use DRAW_ELEMENTS* variants.
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) {
                    return true;
                }
            }
        }
    }

    // Sprint 7 #9 (CKPT65): VS-only TF emulation for drawElements,
    // mirroring the drawArrays hook at GLContext.mm:24590 (CKPT59).
    // When TF is active, the program has TF varyings, no GS in pipeline,
    // and no tess emulation applies, run the VS on CPU per indexed
    // vertex and write captures via the shared writeGsXfbAndCheckDiscard
    // helper. Required for CTS `transform_feedback.{capture,query,
    // discard}_vertex_*` tests which use client-side index arrays
    // with `glDrawElements` to drive TF capture without a bound
    // GL_ELEMENT_ARRAY_BUFFER.
    if (program != nullptr &&
        isTransformFeedbackActive() &&  // CKPT85: per-bound-object
        !program->transformFeedbackVaryingNames.empty() &&
        !program->geometryEmulated &&
        !program->tessellationEmulated &&
        !program->tessellationInterpreted &&
        count > 0 &&
        effectivePtr != nullptr) {
        // Resolve effectivePtr (uint16 / uint32) into a uint32 vector
        // matching the new emulateVsOnlyDrawForTf elementIndices param
        // shape. Small allocation cost — CTS draws never exceed a few
        // hundred indices for these tests.
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            std::memcpy(idx32.data(), effectivePtr, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 =
                static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            idx32.clear();
        }
        // Sprint 7 #9 (CKPT65): topology-decompose strip / loop / fan
        // input into discrete-primitive vertex streams for TF capture.
        // GL 4.6 §13.2: TF captures one entry per re-assembled
        // primitive vertex. So GL_LINE_LOOP with 4 indices captures
        // 8 verts (4 segs × 2 endpoints), GL_LINE_STRIP with 4 captures
        // 6, GL_TRIANGLE_STRIP / _FAN with 4 captures 6, etc. POINTS /
        // LINES / TRIANGLES are already discrete and pass through.
        std::vector<std::uint32_t> capIdx;
        if (!idx32.empty()) {
            const std::size_t n = idx32.size();
            switch (mode) {
                case GL_POINTS:
                case GL_LINES:
                case GL_TRIANGLES:
                    capIdx = idx32;
                    break;
                case GL_LINE_STRIP:
                    if (n >= 2) {
                        capIdx.reserve(2 * (n - 1));
                        for (std::size_t i = 0; i + 1 < n; ++i) {
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[i + 1]);
                        }
                    }
                    break;
                case GL_LINE_LOOP:
                    if (n >= 2) {
                        capIdx.reserve(2 * n);
                        for (std::size_t i = 0; i < n; ++i) {
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[(i + 1) % n]);
                        }
                    }
                    break;
                case GL_TRIANGLE_STRIP:
                    if (n >= 3) {
                        capIdx.reserve(3 * (n - 2));
                        for (std::size_t i = 0; i + 2 < n; ++i) {
                            // GL 4.6 §10.1.12 strip alternation: even
                            // tri (i, i+1, i+2); odd tri (i+1, i, i+2)
                            // so consistent winding survives strip
                            // decomposition.
                            if ((i & 1u) == 0u) {
                                capIdx.push_back(idx32[i]);
                                capIdx.push_back(idx32[i + 1]);
                                capIdx.push_back(idx32[i + 2]);
                            } else {
                                capIdx.push_back(idx32[i + 1]);
                                capIdx.push_back(idx32[i]);
                                capIdx.push_back(idx32[i + 2]);
                            }
                        }
                    }
                    break;
                case GL_TRIANGLE_FAN:
                    if (n >= 3) {
                        capIdx.reserve(3 * (n - 2));
                        for (std::size_t i = 1; i + 1 < n; ++i) {
                            capIdx.push_back(idx32[0]);
                            capIdx.push_back(idx32[i]);
                            capIdx.push_back(idx32[i + 1]);
                        }
                    }
                    break;
                default:
                    capIdx.clear();
                    break;
            }
        }
        if (!capIdx.empty() && !program->vertexSpirv.empty()) {
            // The reassembled discrete-primitive topology fed to
            // writeGsXfbAndCheckDiscard via EmulatedDraw.topology.
            const GLenum capTopology =
                (mode == GL_POINTS) ? GL_POINTS :
                (mode == GL_LINES || mode == GL_LINE_STRIP || mode == GL_LINE_LOOP) ? GL_LINES :
                GL_TRIANGLES;
            appgl::EmulatedDraw ed = appgl::emulateVsOnlyDrawForTf(
                *program, *vao, *impl_->objects, *impl_->state,
                capTopology, static_cast<GLsizei>(capIdx.size()), /*first=*/0,
                /*instanceCount=*/1, /*baseInstance=*/0,
                capIdx.data());
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) {
                    return true;
                }
                // VS-only-TF without rasterizer-discard: fall through
                // to the regular Metal-side draw so the FS still runs.
                // The TF buffer was already populated.
            } else if (!ed.diagnostic.empty()) {
                APPGL_LOG(SHADER, @"drawElements VS-only-TF: %s",
                          ed.diagnostic.c_str());
            }
        }
    }

    // Sprint 17 Day 7+ Bank-Group-H Path B Component B (drawElements):
    // sister of drawArrays B branch. Expand effectivePtr to UINT32 and
    // route through emulateVsCullPrepass + dispatchCullFilteredDraw.
    if (program != nullptr && program->needsCullDistancePrepass &&
        program->hasTranslatedPipeline && vao != nullptr &&
        count > 0 && effectivePtr != nullptr) {
        const bool isLineOrTriDE =
            (mode == GL_POINTS || mode == GL_LINES || mode == GL_TRIANGLES ||
             mode == GL_LINE_STRIP || mode == GL_LINE_LOOP ||
             mode == GL_TRIANGLE_STRIP || mode == GL_TRIANGLE_FAN);
        if (isLineOrTriDE) {
            std::vector<std::uint32_t> cpIdx32(static_cast<std::size_t>(count));
            bool idxOk = true;
            if (effectiveType == GL_UNSIGNED_INT) {
                std::memcpy(cpIdx32.data(), effectivePtr,
                            static_cast<std::size_t>(count) * sizeof(std::uint32_t));
            } else if (effectiveType == GL_UNSIGNED_SHORT) {
                const std::uint16_t* src16 =
                    static_cast<const std::uint16_t*>(effectivePtr);
                for (GLsizei i = 0; i < count; ++i) cpIdx32[i] = src16[i];
            } else if (effectiveType == GL_UNSIGNED_BYTE) {
                const std::uint8_t* src8 =
                    static_cast<const std::uint8_t*>(effectivePtr);
                for (GLsizei i = 0; i < count; ++i) cpIdx32[i] = src8[i];
            } else {
                idxOk = false;
            }
            if (idxOk) {
                std::vector<std::uint32_t> filteredIdx;
                std::string cullDiag;
                const bool prepassOk = appgl::emulateVsCullPrepass(
                    *program, *vao, *impl_->objects, *impl_->state,
                    mode, count, /*first=*/0, cpIdx32.data(),
                    /*instanceCount=*/1, /*baseInstance=*/0,
                    filteredIdx, &cullDiag);
                if (prepassOk) {
                    if (filteredIdx.empty()) {
                        if (!program->gsPresent &&
                            !impl_->transformFeedbackActive) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                    if (impl_->dispatchCullFilteredDraw(
                            *program, *vao, programName, mode,
                            filteredIdx)) {
                        if (!program->gsPresent &&
                            !impl_->transformFeedbackActive) {
                            impl_->updatePrimitiveCountersForNonGsDraw(
                                mode, count, 1);
                        }
                        return true;
                    }
                } else if (!cullDiag.empty()) {
                    APPGL_LOG(SHADER, @"drawElements cull-prepass: %s",
                              cullDiag.c_str());
                }
            }
        }
    }

    // Sprint 8 #9-A (CKPT67): attribute-less drawElements path. Mirror
    // of the drawArrays attribute-less path at line ~24670. CTS
    // `transform_feedback.{capture,query}_vertex_*` tests use a VS
    // that reads only `gl_VertexID` (no per-vertex inputs) and call
    // glDrawElements with client-side index arrays. Without this
    // hook the existing `vao->attributes.empty()` branch in the
    // hasTranslatedPipeline block records a fallback diagnostic and
    // skips the encode entirely — pixels stay at zero-init.
    // Gate mirrors drawArrays attributeless path at line ~24670:
    // shader-reflection-based, not VAO-attributes-based. Our VAO
    // initialization resizes `attributes` to `count` default-
    // constructed (disabled) entries, so `vao->attributes.empty()`
    // returns false even when nothing is actually bound. The shader
    // reflection's `vertexInputs.empty()` is the correct indicator
    // for an attribute-less draw.
    if (program != nullptr && program->hasTranslatedPipeline &&
        vao != nullptr &&
        program->vertexReflection.vertexInputs.empty() &&
        count > 0 && effectivePtr != nullptr) {
        TranslatedDrawInfo tdi;
        tdi.mode = mode;
        tdi.vertexCount = count;
        tdi.vertexData = nullptr;
        tdi.vertexDataByteCount = 0;
        tdi.vertexStride = 0;
        // Index data — CPU-side scratch from client-side index array
        // OR shadow-bytes from bound element buffer. encodeTranslated
        // Draw's `info.indices != nullptr && info.indexCount > 0`
        // gate stages it into a Metal ring buffer.
        tdi.indices = effectivePtr;
        tdi.indexCount = count;
        tdi.indexType = effectiveType;
        if (elementBuffer != nullptr && !elementIndexTypeNeedsExpansion(type) &&
            elementBuffer->metalBuffer != nullptr) {
            tdi.metalIndexBuffer = elementBuffer->metalBuffer;
            tdi.metalIndexBufferOffset = indexOffset;
        }
        populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
        tdi.vertexMSL = &program->vertexMSL;
        tdi.fragmentMSL = &program->fragmentMSL;
        tdi.vertexReflection = &program->vertexReflection;
        tdi.fragmentReflection = &program->fragmentReflection;
        tdi.pipelineStateOut = &program->metalPipelineState;
        tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
        tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
        tdi.metalVertexFunction = program->metalVertexFunction;
        tdi.metalFragmentFunction = program->metalFragmentFunction;
        tdi.metalVertexFunctionOut = &program->metalVertexFunction;
        tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
        tdi.program = programName;

        // Uniform layout (cached).
        if (!program->uniformLayoutComputed) {
            computeStageUniformLayout(program->vertexUniformLayout,
                program->vertexReflection, program->uniforms);
            computeStageUniformLayout(program->fragmentUniformLayout,
                program->fragmentReflection, program->uniforms);
            program->uniformLayoutComputed = true;
        }
        thread_local std::vector<std::uint8_t> vtxUniformScratchDE;
        thread_local std::vector<std::uint8_t> fragUniformScratchDE;
        pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
        buildStageUniformBuffer(vtxUniformScratchDE,
            program->vertexReflection, program->uniformValues,
            program->vertexUniformLayout);
        buildStageUniformBuffer(fragUniformScratchDE,
            program->fragmentReflection, program->uniformValues,
            program->fragmentUniformLayout);
        tdi.vertexUniformData = vtxUniformScratchDE.data();
        tdi.vertexUniformSize = vtxUniformScratchDE.size();
        tdi.fragmentUniformData = fragUniformScratchDE.data();
        tdi.fragmentUniformSize = fragUniformScratchDE.size();

        impl_->resolveSamplerBindings(*program, tdi);
        impl_->resolveUBOBindings(*program, tdi);
        impl_->resolveSSBOBindings(*program, tdi);
        impl_->resolveImageBindings(*program, tdi);

        // FBO render target.
        {
            GLsizei fboW = 0, fboH = 0;
            void* fboDSTex = nullptr;
            std::array<void*, 7> extraColTex = {};
            std::array<std::uint32_t, 8> colSlices = {};
            void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
            if (fboColTex != nullptr || fboDSTex != nullptr) {
                tdi.fboColorTexture = fboColTex;
                tdi.fboAdditionalColorTextures = extraColTex;
                tdi.fboColorSlices = colSlices;
                tdi.fboDepthStencilTexture = fboDSTex;
                tdi.fboWidth = fboW;
                tdi.fboHeight = fboH;
            }
        }

        thread_local std::string pipelineBuildErrorDE;
        pipelineBuildErrorDE.clear();
        tdi.pipelineBuildErrorOut = &pipelineBuildErrorDE;

        const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
        if (ok) {
            // Sprint 8 #9-A (CKPT67): primitive counter update is
            // handled by the VS-only-TF helper at the earlier hook
            // point (line ~25655) when transform feedback is active.
            // For non-TF draws on this attributeless path, mirror
            // drawArrays' attributeless-success path: update counters
            // here. CTS `query_vertex_*` tests have TF active during
            // the query, so the VS-only-TF helper already advanced
            // GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN; advancing
            // here AGAIN would double-count. Gate accordingly.
            if (!program->gsPresent && !impl_->transformFeedbackActive) {
                impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1);
            }
            return true;
        }
        // Fall through to solid-color path on failure.
    }
    if (program != nullptr && program->hasTranslatedPipeline) {
        // Phase 8X Group 4d follow-up³ — name each fall-through gate to BAR's log.
        if (vao->attributes.empty()) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawElements",
                vaoName, 0, 0, 0);
        }
        if (!vao->attributes.empty()) {
            const auto& posAttr = vao->attributes[0];
            auto resolved = resolveVertexAttrib(posAttr, *vao);
            GLBufferObject* vbo = (resolved.bufferName != 0)
                ? impl_->objects->buffers().get(resolved.bufferName) : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawElements",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawElements",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = resolved.stride;
                const std::size_t startOff = resolved.offset;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawElements",
                        vaoName, vao->attributes.size(), resolved.bufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo tdi;
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    // OPT-5: pass pre-uploaded Metal buffer for direct bind.
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    tdi.indices = effectivePtr;
                    tdi.indexCount = count;
                    tdi.indexType = effectiveType;
                    // OPT-5: pass Metal index buffer when indices weren't
                    // expanded (UINT16/UINT32 pass-through from element VBO).
                    // ADV-10: use the type check instead of the old local vector.
                    if (!elementIndexTypeNeedsExpansion(type) && elementBuffer->metalBuffer != nullptr) {
                        tdi.metalIndexBuffer = elementBuffer->metalBuffer;
                        tdi.metalIndexBufferOffset = indexOffset;
                    }
                    // Phase 8X Group 4d follow-up¹⁴ — centralised fixed-
                    // function state snapshot. See drawArrays.
                    populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
                    tdi.vertexMSL = &program->vertexMSL;
                    tdi.fragmentMSL = &program->fragmentMSL;
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    // Phase 8X Group 4d follow-up¹⁴ — map-based cache
                    // so spring's 15×/frame blend toggle doesn't thrash
                    // the single-slot scalar cache above.
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    // Phase 8X Group 4d follow-up⁸ — diagnostic-only
                    // program identifier used by encodeTranslatedDraw's
                    // first-draw-per-program NSLog. Non-owning, no
                    // correctness impact; zero is a valid placeholder.
                    tdi.program = programName;

                    // Collect per-attribute layout from the VAO — group
                    // by (VBO, stride) so attributes with different strides
                    // get separate Metal buffer indices.
                    //
                    // Phase 8X Group 4d follow-up¹⁴ — propagate VAO
                    // format fields so encodeTranslatedDraw derives
                    // the real MTLVertexFormat from the VBO layout.
                    {
                        struct DEGroupKey {
                            GLuint bufferName;
                            std::size_t stride;
                            bool operator==(const DEGroupKey& o) const {
                                return bufferName == o.bufferName && stride == o.stride;
                            }
                        };
                        struct DEGroupKeyHash {
                            std::size_t operator()(const DEGroupKey& k) const {
                                return std::hash<GLuint>()(k.bufferName)
                                     ^ (std::hash<std::size_t>()(k.stride) << 16);
                            }
                        };
                        std::unordered_map<DEGroupKey, std::size_t, DEGroupKeyHash> deExtraMap;
                        for (std::size_t ai = 0; ai < vao->attributes.size(); ++ai) {
                            const auto& attr = vao->attributes[ai];
                            if (!attr.enabled) continue;
                            auto attrRes = resolveVertexAttrib(attr, *vao);
                            TranslatedDrawInfo::VertexAttributeLayout layout;
                            layout.location = static_cast<GLuint>(ai);
                            populateVertexAttributeLayoutVAOFields(layout, attr);
                            if (attrRes.bufferName == resolved.bufferName
                                && attrRes.stride == posStride) {
                                layout.offset = attrRes.offset - resolved.offset;
                                tdi.vertexAttributeLayouts.push_back(layout);
                            } else {
                                GLBufferObject* extraVbo =
                                    impl_->objects->buffers().get(attrRes.bufferName);
                                if (extraVbo == nullptr || extraVbo->shadowBytes.empty())
                                    continue;
                                DEGroupKey key{attrRes.bufferName, attrRes.stride};
                                auto it = deExtraMap.find(key);
                                std::size_t idx;
                                if (it == deExtraMap.end()) {
                                    idx = tdi.extraVertexBuffers.size();
                                    deExtraMap[key] = idx;
                                    TranslatedDrawInfo::ExtraVertexBuffer evb;
                                    evb.data = extraVbo->shadowBytes.data();
                                    evb.byteCount = extraVbo->shadowBytes.size();
                                    evb.stride = attrRes.stride;
                                    evb.divisor = 0;
                                    evb.metalBuffer = extraVbo->metalBuffer;
                                    evb.metalBufferOffset = 0;
                                    tdi.extraVertexBuffers.push_back(std::move(evb));
                                } else {
                                    idx = it->second;
                                }
                                layout.offset = attrRes.offset;
                                tdi.extraVertexBuffers[idx].attributes.push_back(layout);
                            }
                        }
                    }

                    // OPT-7: compute uniform layout once, reuse every draw.
                    if (!program->uniformLayoutComputed) {
                        computeStageUniformLayout(program->vertexUniformLayout,
                            program->vertexReflection, program->uniforms);
                        computeStageUniformLayout(program->fragmentUniformLayout,
                            program->fragmentReflection, program->uniforms);
                        program->uniformLayoutComputed = true;
                    }

                    thread_local std::vector<std::uint8_t> vtxUniformScratch;
                    thread_local std::vector<std::uint8_t> fragUniformScratch;
                    pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
                    buildStageUniformBuffer(vtxUniformScratch,
                        program->vertexReflection, program->uniformValues,
                        program->vertexUniformLayout);
                    buildStageUniformBuffer(fragUniformScratch,
                        program->fragmentReflection, program->uniformValues,
                        program->fragmentUniformLayout);
                    tdi.vertexUniformData = vtxUniformScratch.data();
                    tdi.vertexUniformSize = vtxUniformScratch.size();
                    tdi.fragmentUniformData = fragUniformScratch.data();
                    tdi.fragmentUniformSize = fragUniformScratch.size();

                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    // Phase 8X Group 4d follow-up⁴ — scratch buffer for the
                    // pipeline-build error text plumbed out of the encode-failed
                    // path. See the matching comment in drawArrays for rationale.
                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawElements",
                            vaoName, vao->attributes.size(), resolved.bufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                    // Fall through to solid-color path on failure.
                }
            }
        }
    }

    // Fallback: solid-color draw path (hardcoded appgl_solid pipeline).
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(*impl_->state, *impl_->objects, mode, "glDrawElements");
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawElements: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        return false;
    }

    setup.info.vertexCount = count;
    setup.info.baseVertex = 0;
    setup.info.indices = effectivePtr;
    setup.info.indexCount = count;
    setup.info.indexType = effectiveType;

    const bool ok = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (!ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawElements: MetalFrameGraph failed to encode draw"
        );
    }
    return ok;
}

// ---------------------------------------------------------------------------
// GL 3.2 — Base-vertex indexed drawing (ARB_draw_elements_base_vertex)
// ---------------------------------------------------------------------------

bool GLContext::drawElementsBaseVertex(GLenum mode, GLsizei count, GLenum type, const void* indices, GLint basevertex) {
    // GL 4.6 §10.5: mode must be a valid primitive-assembly enum.
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update for
    // non-GS indexed draws. GS path is handled via
    // writeGsXfbAndCheckDiscard below.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        if (p == nullptr || !p->gsPresent) {
            const GLsizei restartSkip = impl_->countRestartIndices(type, indices, count);
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, 1, restartSkip);
        }
    }

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Resolve element buffer — same as drawElements.
    const GLuint vaoName = impl_->state->boundVertexArray();
    GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
    if (vao == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLuint elementBufferName = vao->elementArrayBuffer;
    if (elementBufferName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* elementBuffer = impl_->objects->buffers().get(elementBufferName);
    if (elementBuffer == nullptr || elementBuffer->shadowBytes.empty()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    const std::size_t indexOffset = reinterpret_cast<std::uintptr_t>(indices);
    if (indexOffset > elementBuffer->shadowBytes.size()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const void* indexPtr = elementBuffer->shadowBytes.data() + indexOffset;

    // Handle GL_UNSIGNED_BYTE expansion (same as drawElements).
    GLenum effectiveType = type;
    const void* effectivePtr = indexPtr;
    if (elementIndexTypeNeedsExpansion(type)) {
        if (elementBuffer->cachedExpansionGeneration != elementBuffer->indexExpansionGeneration
            || elementBuffer->cachedExpandedIndices.empty()) {
            const GLsizei totalIndices = static_cast<GLsizei>(elementBuffer->shadowBytes.size());
            IndexExpansionResult result = expandElementIndices(
                totalIndices, type, elementBuffer->shadowBytes.data());
            if (!result.ok) {
                pushError(result.error);
                return false;
            }
            elementBuffer->cachedExpandedIndices = std::move(result.bytes);
            elementBuffer->cachedExpansionGeneration = elementBuffer->indexExpansionGeneration;
        }
        effectiveType = GL_UNSIGNED_SHORT;
        const std::size_t expandedOffset = indexOffset * sizeof(GLushort);
        effectivePtr = elementBuffer->cachedExpandedIndices.data() + expandedOffset;
    }

    // Try translated shader pipeline first.
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);

    // GS emul hook for base-vertex indexed draws (drawRangeElements
    // funnels here too).
    if (program != nullptr && program->geometryEmulated && count > 0) {
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            const std::uint32_t* src32 = static_cast<const std::uint32_t*>(effectivePtr);
            std::memcpy(idx32.data(), src32, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 = static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            idx32.clear();
        }
        if (!idx32.empty()) {
            if (basevertex != 0) {
                for (auto& v : idx32) v = static_cast<std::uint32_t>(
                    static_cast<std::int32_t>(v) + basevertex);
            }
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, idx32.data());
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) return true;
                if (ed.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) return true;
            }
        }
    }

    if (program != nullptr && program->hasTranslatedPipeline) {
        if (vao->attributes.empty()) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawElementsBaseVertex",
                vaoName, 0, 0, 0);
        }
        if (!vao->attributes.empty()) {
            const auto& posAttr = vao->attributes[0];
            auto resolved = resolveVertexAttrib(posAttr, *vao);
            GLBufferObject* vbo = (resolved.bufferName != 0)
                ? impl_->objects->buffers().get(resolved.bufferName) : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawElementsBaseVertex",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawElementsBaseVertex",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = resolved.stride;
                const std::size_t startOff = resolved.offset;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawElementsBaseVertex",
                        vaoName, vao->attributes.size(), resolved.bufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo tdi;
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.baseVertex = basevertex;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    tdi.indices = effectivePtr;
                    tdi.indexCount = count;
                    tdi.indexType = effectiveType;
                    if (!elementIndexTypeNeedsExpansion(type) && elementBuffer->metalBuffer != nullptr) {
                        tdi.metalIndexBuffer = elementBuffer->metalBuffer;
                        tdi.metalIndexBufferOffset = indexOffset;
                    }
                    populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
                    tdi.vertexMSL = &program->vertexMSL;
                    tdi.fragmentMSL = &program->fragmentMSL;
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    tdi.program = programName;

                    for (std::size_t ai = 0; ai < vao->attributes.size(); ++ai) {
                        const auto& attr = vao->attributes[ai];
                        if (!attr.enabled) continue;
                        auto attrRes = resolveVertexAttrib(attr, *vao);
                        if (attrRes.bufferName != resolved.bufferName) continue;
                        TranslatedDrawInfo::VertexAttributeLayout layout;
                        layout.location = static_cast<GLuint>(ai);
                        layout.offset = attrRes.offset - resolved.offset;
                        populateVertexAttributeLayoutVAOFields(layout, attr);
                        tdi.vertexAttributeLayouts.push_back(layout);
                    }

                    if (!program->uniformLayoutComputed) {
                        computeStageUniformLayout(program->vertexUniformLayout,
                            program->vertexReflection, program->uniforms);
                        computeStageUniformLayout(program->fragmentUniformLayout,
                            program->fragmentReflection, program->uniforms);
                        program->uniformLayoutComputed = true;
                    }

                    thread_local std::vector<std::uint8_t> vtxUniformScratch;
                    thread_local std::vector<std::uint8_t> fragUniformScratch;
                    pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
                    buildStageUniformBuffer(vtxUniformScratch,
                        program->vertexReflection, program->uniformValues,
                        program->vertexUniformLayout);
                    buildStageUniformBuffer(fragUniformScratch,
                        program->fragmentReflection, program->uniformValues,
                        program->fragmentUniformLayout);
                    tdi.vertexUniformData = vtxUniformScratch.data();
                    tdi.vertexUniformSize = vtxUniformScratch.size();
                    tdi.fragmentUniformData = fragUniformScratch.data();
                    tdi.fragmentUniformSize = fragUniformScratch.size();

                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawElementsBaseVertex",
                            vaoName, vao->attributes.size(), resolved.bufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                }
            }
        }
    }

    // Fallback: solid-color draw path.
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(*impl_->state, *impl_->objects, mode, "glDrawElementsBaseVertex");
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawElementsBaseVertex: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        return false;
    }

    setup.info.vertexCount = count;
    setup.info.baseVertex = basevertex;
    setup.info.indices = effectivePtr;
    setup.info.indexCount = count;
    setup.info.indexType = effectiveType;

    const bool solidOk = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (!solidOk) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawElementsBaseVertex: MetalFrameGraph failed to encode draw"
        );
    }
    return solidOk;
}

bool GLContext::drawRangeElementsBaseVertex(GLenum mode, GLuint start, GLuint end, GLsizei count, GLenum type, const void* indices, GLint basevertex) {
    // Per the GL spec, start/end are range hints only. The spec says we MAY
    // use them for validation but MUST NOT reject draws where indices fall
    // outside [start, end]. We validate the basic constraints and delegate
    // to drawElementsBaseVertex for the actual draw.
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (end < start) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    return drawElementsBaseVertex(mode, count, type, indices, basevertex);
}

bool GLContext::drawElementsInstancedBaseVertex(GLenum mode, GLsizei count, GLenum type, const void* indices, GLsizei instancecount, GLint basevertex) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!impl_->state->validateForDraw()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.6 §2.3.3 — conditional render predicate.
    if (impl_->shouldSkipDrawForConditionalRender()) {
        return true;
    }
    // GL 4.6 §11.3.1: draw-mode / GS-input-topology compat. See
    // drawArraysInstanced for the rationale — the drawElements
    // indirect path lands here so the gate must live at this level
    // to catch `draw_indirect.negative-gshIncompatible-elements`.
    {
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName != 0
            ? impl_->objects->programs().get(progName)
            : nullptr;
        // Tess-in-pipeline escape — see drawArrays for rationale.
        if (p != nullptr && p->gsPresent && !p->hasTessellation &&
            !isDrawModeCompatibleWithGs(mode, p->gsInputTopology)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        // GL 4.6 §22.1 / §22.3 — pipeline-stats counter update.
        if (p == nullptr || !p->gsPresent) {
            const GLsizei restartSkip = impl_->countRestartIndices(type, indices, count);
            impl_->updatePrimitiveCountersForNonGsDraw(mode, count, instancecount, restartSkip);
        }
    }

    if (impl_->frameGraph == nullptr) {
        return false;
    }
    impl_->frameGraph->resizeDrawable(impl_->drawableSurfaceWidth(), impl_->drawableSurfaceHeight());
    impl_->encodePendingWork();

    // Resolve element buffer.
    const GLuint vaoName = impl_->state->boundVertexArray();
    GLVertexArrayObject* vao = (vaoName != 0) ? impl_->objects->vertexArrays().get(vaoName) : nullptr;
    if (vao == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLuint elementBufferName = vao->elementArrayBuffer;
    if (elementBufferName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* elementBuffer = impl_->objects->buffers().get(elementBufferName);
    if (elementBuffer == nullptr || elementBuffer->shadowBytes.empty()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    const std::size_t indexOffset = reinterpret_cast<std::uintptr_t>(indices);
    if (indexOffset > elementBuffer->shadowBytes.size()) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const void* indexPtr = elementBuffer->shadowBytes.data() + indexOffset;

    GLenum effectiveType = type;
    const void* effectivePtr = indexPtr;
    if (elementIndexTypeNeedsExpansion(type)) {
        if (elementBuffer->cachedExpansionGeneration != elementBuffer->indexExpansionGeneration
            || elementBuffer->cachedExpandedIndices.empty()) {
            const GLsizei totalIndices = static_cast<GLsizei>(elementBuffer->shadowBytes.size());
            IndexExpansionResult result = expandElementIndices(
                totalIndices, type, elementBuffer->shadowBytes.data());
            if (!result.ok) {
                pushError(result.error);
                return false;
            }
            elementBuffer->cachedExpandedIndices = std::move(result.bytes);
            elementBuffer->cachedExpansionGeneration = elementBuffer->indexExpansionGeneration;
        }
        effectiveType = GL_UNSIGNED_SHORT;
        const std::size_t expandedOffset = indexOffset * sizeof(GLushort);
        effectivePtr = elementBuffer->cachedExpandedIndices.data() + expandedOffset;
    }

    // Try translated shader pipeline first.
    // GL 4.6 §7.4 — prefer glUseProgram's program; fall back to the
    // active program pipeline's VS+FS merged onto its VS container
    // when only a pipeline is bound. Covers the CTS VAB tests that
    // drive separable programs through glCreateShaderProgramv +
    // glUseProgramStages without ever calling glUseProgram.
    GLuint programName = impl_->state->currentProgram();
    GLProgramObject* program = impl_->resolveDrawProgram(programName);

    // Phase 3f-16: tess-emul for instanced indexed draws. Mirrors
    // the GS path below; the only shared code is the idx32 expand
    // + optional basevertex bias. Kept as a separate block so the
    // passthrough/interpreter precedence over GS-emul (they're
    // mutually exclusive via !geometryEmulated) is preserved.
    if (program != nullptr &&
        (program->tessellationEmulated || program->tessellationInterpreted) &&
        !program->geometryEmulated && count > 0 && instancecount > 0) {
        std::vector<std::uint32_t> tidx32;
        if (effectiveType == GL_UNSIGNED_INT) {
            tidx32.assign(count, 0);
            std::memcpy(tidx32.data(), effectivePtr, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            tidx32.assign(count, 0);
            const std::uint16_t* src16 =
                static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) tidx32[i] = src16[i];
        }
        if (!tidx32.empty()) {
            if (basevertex != 0) {
                for (auto& v : tidx32) v = static_cast<std::uint32_t>(
                    static_cast<std::int32_t>(v) + basevertex);
            }
            appgl::EmulatedDraw ted = appgl::emulateTessellationDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, tidx32.data(),
                instancecount, /*baseInstance=*/0);
            if (ted.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ted)) return true;
                if (ted.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ted)) return true;
            }
        }
    }

    // GS emul hook for instanced indexed draws. See drawElements
    // and drawArraysInstanced for the sibling paths.
    if (program != nullptr && program->geometryEmulated && count > 0 && instancecount > 0) {
        std::vector<std::uint32_t> idx32(static_cast<std::size_t>(count));
        if (effectiveType == GL_UNSIGNED_INT) {
            const std::uint32_t* src32 = static_cast<const std::uint32_t*>(effectivePtr);
            std::memcpy(idx32.data(), src32, count * sizeof(std::uint32_t));
        } else if (effectiveType == GL_UNSIGNED_SHORT) {
            const std::uint16_t* src16 = static_cast<const std::uint16_t*>(effectivePtr);
            for (GLsizei i = 0; i < count; ++i) idx32[i] = src16[i];
        } else {
            idx32.clear();
        }
        if (!idx32.empty()) {
            // basevertex applied per GL 4.6 §10.6.3: each element
            // index gets `basevertex` added before VBO fetch.
            if (basevertex != 0) {
                for (auto& v : idx32) v = static_cast<std::uint32_t>(
                    static_cast<std::int32_t>(v) + basevertex);
            }
            appgl::EmulatedDraw ed = appgl::emulateGeometryDraw(
                *program, *vao, *impl_->objects, *impl_->state,
                mode, count, /*first=*/0, idx32.data(),
                instancecount, /*baseInstance=*/0);
            if (ed.ok) {
                if (impl_->writeGsXfbAndCheckDiscard(*program, ed)) return true;
                if (ed.vertexCount == 0) return true;
                if (impl_->encodeEmulatedGsDraw(*program, programName, ed)) return true;
            }
        }
    }

    if (program != nullptr && program->hasTranslatedPipeline) {
        if (vao->attributes.empty()) {
            reportTranslatedFallbackOnce(program, programName,
                TranslatedFallbackGate::EmptyAttributes, "drawElementsInstancedBaseVertex",
                vaoName, 0, 0, 0);
        }
        if (!vao->attributes.empty()) {
            const auto& posAttr = vao->attributes[0];
            auto resolved = resolveVertexAttrib(posAttr, *vao);
            GLBufferObject* vbo = (resolved.bufferName != 0)
                ? impl_->objects->buffers().get(resolved.bufferName) : nullptr;
            if (vbo == nullptr) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::NullVBO, "drawElementsInstancedBaseVertex",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            } else if (vbo->shadowBytes.empty()) {
                reportTranslatedFallbackOnce(program, programName,
                    TranslatedFallbackGate::ShadowBytesEmpty, "drawElementsInstancedBaseVertex",
                    vaoName, vao->attributes.size(), resolved.bufferName, 0);
            }
            if (vbo != nullptr && !vbo->shadowBytes.empty()) {
                const std::size_t posStride = resolved.stride;
                const std::size_t startOff = resolved.offset;

                if (startOff > vbo->shadowBytes.size()) {
                    reportTranslatedFallbackOnce(program, programName,
                        TranslatedFallbackGate::OffsetOverflow, "drawElementsInstancedBaseVertex",
                        vaoName, vao->attributes.size(), resolved.bufferName,
                        vbo->shadowBytes.size());
                }
                if (startOff <= vbo->shadowBytes.size()) {
                    TranslatedDrawInfo tdi;
                    tdi.mode = mode;
                    tdi.vertexCount = count;
                    tdi.baseVertex = basevertex;
                    tdi.instanceCount = instancecount;
                    tdi.vertexData = vbo->shadowBytes.data() + startOff;
                    tdi.vertexDataByteCount = vbo->shadowBytes.size() - startOff;
                    tdi.vertexStride = posStride;
                    tdi.metalVertexBuffer = vbo->metalBuffer;
                    tdi.metalVertexBufferOffset = startOff;
                    tdi.indices = effectivePtr;
                    tdi.indexCount = count;
                    tdi.indexType = effectiveType;
                    if (!elementIndexTypeNeedsExpansion(type) && elementBuffer->metalBuffer != nullptr) {
                        tdi.metalIndexBuffer = elementBuffer->metalBuffer;
                        tdi.metalIndexBufferOffset = indexOffset;
                    }
                    populateTranslatedDrawFixedFunctionState(tdi, *impl_->state);
                    tdi.vertexMSL = &program->vertexMSL;
                    tdi.fragmentMSL = &program->fragmentMSL;
                    tdi.vertexReflection = &program->vertexReflection;
                    tdi.fragmentReflection = &program->fragmentReflection;
                    tdi.pipelineStateOut = &program->metalPipelineState;
                    tdi.pipelineColorFormatOut = &program->metalPipelineColorFormat;
                    tdi.pipelineStateCacheOut = &program->metalPipelineStateCache;
                    tdi.metalVertexFunction = program->metalVertexFunction;
                    tdi.metalFragmentFunction = program->metalFragmentFunction;
                    tdi.metalVertexFunctionOut = &program->metalVertexFunction;
                    tdi.metalFragmentFunctionOut = &program->metalFragmentFunction;
                    tdi.program = programName;

                    // Gather vertex attributes — group by (VBO, stride, divisor).
                    // Primary group: same VBO + same stride + divisor=0 → buffer 0.
                    // Everything else → extraVertexBuffers (buffer 1+).
                    struct DrawElemGroupKey {
                        GLuint bufferName;
                        std::size_t stride;
                        GLuint divisor;
                        bool operator==(const DrawElemGroupKey& o) const {
                            return bufferName == o.bufferName
                                && stride == o.stride
                                && divisor == o.divisor;
                        }
                    };
                    struct DrawElemGroupKeyHash {
                        std::size_t operator()(const DrawElemGroupKey& k) const {
                            return std::hash<GLuint>()(k.bufferName)
                                 ^ (std::hash<std::size_t>()(k.stride) << 16)
                                 ^ (std::hash<GLuint>()(k.divisor) << 24);
                        }
                    };
                    std::unordered_map<DrawElemGroupKey, std::size_t, DrawElemGroupKeyHash> extraBufferMap;

                    for (std::size_t ai = 0; ai < vao->attributes.size(); ++ai) {
                        const auto& attr = vao->attributes[ai];
                        if (!attr.enabled) continue;

                        auto attrRes = resolveVertexAttrib(attr, *vao);
                        GLuint attrDivisor = attr.useSeparatedFormat
                            ? (attr.bindingIndex < vao->bindingPoints.size()
                                ? vao->bindingPoints[attr.bindingIndex].divisor
                                : attr.divisor)
                            : attr.divisor;

                        TranslatedDrawInfo::VertexAttributeLayout layout;
                        layout.location = static_cast<GLuint>(ai);
                        populateVertexAttributeLayoutVAOFields(layout, attr);

                        if (attrRes.bufferName == resolved.bufferName
                            && attrRes.stride == posStride
                            && attrDivisor == 0) {
                            layout.offset = attrRes.offset - resolved.offset;
                            tdi.vertexAttributeLayouts.push_back(layout);
                        } else {
                            GLBufferObject* extraVbo = impl_->objects->buffers().get(attrRes.bufferName);
                            if (extraVbo == nullptr || extraVbo->shadowBytes.empty()) continue;

                            DrawElemGroupKey key{attrRes.bufferName, attrRes.stride, attrDivisor};
                            auto it = extraBufferMap.find(key);
                            std::size_t idx;
                            if (it == extraBufferMap.end()) {
                                idx = tdi.extraVertexBuffers.size();
                                extraBufferMap[key] = idx;

                                TranslatedDrawInfo::ExtraVertexBuffer evb;
                                evb.data = extraVbo->shadowBytes.data();
                                evb.byteCount = extraVbo->shadowBytes.size();
                                evb.stride = attrRes.stride;
                                evb.divisor = attrDivisor;
                                evb.metalBuffer = extraVbo->metalBuffer;
                                evb.metalBufferOffset = 0;
                                tdi.extraVertexBuffers.push_back(std::move(evb));
                            } else {
                                idx = it->second;
                            }

                            layout.offset = attrRes.offset;
                            tdi.extraVertexBuffers[idx].attributes.push_back(layout);
                        }
                    }

                    if (!program->uniformLayoutComputed) {
                        computeStageUniformLayout(program->vertexUniformLayout,
                            program->vertexReflection, program->uniforms);
                        computeStageUniformLayout(program->fragmentUniformLayout,
                            program->fragmentReflection, program->uniforms);
                        program->uniformLayoutComputed = true;
                    }

                    thread_local std::vector<std::uint8_t> vtxUniformScratch;
                    thread_local std::vector<std::uint8_t> fragUniformScratch;
                    pushSynthesizedMatrixUniforms(*program, impl_->matrixState);
                    buildStageUniformBuffer(vtxUniformScratch,
                        program->vertexReflection, program->uniformValues,
                        program->vertexUniformLayout);
                    buildStageUniformBuffer(fragUniformScratch,
                        program->fragmentReflection, program->uniformValues,
                        program->fragmentUniformLayout);
                    tdi.vertexUniformData = vtxUniformScratch.data();
                    tdi.vertexUniformSize = vtxUniformScratch.size();
                    tdi.fragmentUniformData = fragUniformScratch.data();
                    tdi.fragmentUniformSize = fragUniformScratch.size();

                    impl_->resolveSamplerBindings(*program, tdi);
                    impl_->resolveUBOBindings(*program, tdi);
                    impl_->resolveSSBOBindings(*program, tdi);
                    impl_->resolveImageBindings(*program, tdi);

                    // RC-A02: resolve FBO render target.
                    {
                        GLsizei fboW = 0, fboH = 0;
                        void* fboDSTex = nullptr;
                        std::array<void*, 7> extraColTex = {};
                        std::array<std::uint32_t, 8> colSlices = {};
                        void* fboColTex = impl_->resolveFBOColorTarget(fboW, fboH, fboDSTex, nullptr, &extraColTex, &colSlices);
                        if (fboColTex != nullptr || fboDSTex != nullptr) {
                            tdi.fboColorTexture = fboColTex;
                            tdi.fboAdditionalColorTextures = extraColTex;
                            tdi.fboColorSlices = colSlices;
                            tdi.fboDepthStencilTexture = fboDSTex;
                            tdi.fboWidth = fboW;
                            tdi.fboHeight = fboH;
                        }
                    }

                    thread_local std::string pipelineBuildError;
                    pipelineBuildError.clear();
                    tdi.pipelineBuildErrorOut = &pipelineBuildError;

                    const bool ok = impl_->encodeTranslatedDrawAndMarkFbo(tdi);
                    if (ok) {
                        return true;
                    }
                    if (reportTranslatedFallbackOnce(program, programName,
                            TranslatedFallbackGate::EncodeFailed, "drawElementsInstancedBaseVertex",
                            vaoName, vao->attributes.size(), resolved.bufferName,
                            vbo->shadowBytes.size())) {
                        recordPipelineBuildFailureOnce(program, programName, pipelineBuildError);
                    }
                }
            }
        }
    }

    // Fallback: solid-color draw path (no instancing support in solid-color).
    SolidColorDrawSetup setup = buildSolidColorDrawSetup(*impl_->state, *impl_->objects, mode, "glDrawElementsInstancedBaseVertex");
    if (!setup.ok) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_OTHER,
            0,
            GL_DEBUG_SEVERITY_LOW,
            "glDrawElementsInstancedBaseVertex: draw skipped (no translated pipeline and solid-color path unsupported)"
        );
        return false;
    }

    setup.info.vertexCount = count;
    setup.info.baseVertex = basevertex;
    setup.info.indices = effectivePtr;
    setup.info.indexCount = count;
    setup.info.indexType = effectiveType;

    const bool solidOk = impl_->frameGraph->encodeSolidColorDraw(setup.info);
    if (!solidOk) {
        emitDebugMessage(
            GL_DEBUG_SOURCE_API,
            GL_DEBUG_TYPE_ERROR,
            0,
            GL_DEBUG_SEVERITY_HIGH,
            "glDrawElementsInstancedBaseVertex: MetalFrameGraph failed to encode draw"
        );
    }
    return solidOk;
}

bool GLContext::multiDrawElementsBaseVertex(GLenum mode, const GLsizei* count, GLenum type, const void* const* indices, GLsizei drawcount, const GLint* basevertex) {
    if (!isValidDrawMode(mode)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isSupportedElementIndexType(type)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §10.5: per-sub-draw count must be non-negative. Check
    // ALL entries up-front so an out-of-bounds value doesn't silently
    // drop some sub-draws before the error is reported. CTS
    // `draw_elements_base_vertex_tests.invalid_count_argument` asserts
    // INVALID_VALUE.
    if (count != nullptr) {
        for (GLsizei i = 0; i < drawcount; ++i) {
            if (count[i] < 0) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
        }
    }
    // Multi-draw decomposes into individual draws per the GL spec.
    for (GLsizei i = 0; i < drawcount; ++i) {
        if (count[i] > 0) {
            drawElementsBaseVertex(mode, count[i], type, indices[i], basevertex[i]);
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Memory Barriers
// ---------------------------------------------------------------------------

bool GLContext::memoryBarrier(GLbitfield barriers) {
    // All valid GL 4.2/4.3/4.4 barrier bits. 4.4 added
    // `GL_CLIENT_MAPPED_BUFFER_BARRIER_BIT` (ARB_buffer_storage) —
    // without it here, `buffer_storage.map_persistent_read_pixels`
    // raises INVALID_VALUE on its post-readback barrier.
    constexpr GLbitfield kValidBarrierBits =
        GL_VERTEX_ATTRIB_ARRAY_BARRIER_BIT |
        GL_ELEMENT_ARRAY_BARRIER_BIT |
        GL_UNIFORM_BARRIER_BIT |
        GL_TEXTURE_FETCH_BARRIER_BIT |
        GL_SHADER_IMAGE_ACCESS_BARRIER_BIT |
        GL_COMMAND_BARRIER_BIT |
        GL_PIXEL_BUFFER_BARRIER_BIT |
        GL_TEXTURE_UPDATE_BARRIER_BIT |
        GL_BUFFER_UPDATE_BARRIER_BIT |
        GL_FRAMEBUFFER_BARRIER_BIT |
        GL_TRANSFORM_FEEDBACK_BARRIER_BIT |
        GL_ATOMIC_COUNTER_BARRIER_BIT |
        GL_SHADER_STORAGE_BARRIER_BIT |
        GL_CLIENT_MAPPED_BUFFER_BARRIER_BIT;

    if (barriers != GL_ALL_BARRIER_BITS && (barriers & ~kValidBarrierBits) != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // For CPU-visible barrier bits (BUFFER_UPDATE | TEXTURE_UPDATE |
    // PIXEL_BUFFER | CLIENT_MAPPED_BUFFER) we need to commit + wait so
    // subsequent glMapBuffer* / glGetTexImage / glReadPixels calls see
    // the GPU writes. Metal handles GPU-to-GPU ordering implicitly but
    // there's no implicit sync to CPU, and SSBO writes via a VS under
    // GL_RASTERIZER_DISCARD (CTS shader_storage_buffer_object.*-vs)
    // are only readable after the draw's command buffer completes.
    constexpr GLbitfield kCpuVisibleBarriers =
        GL_BUFFER_UPDATE_BARRIER_BIT |
        GL_TEXTURE_UPDATE_BARRIER_BIT |
        GL_PIXEL_BUFFER_BARRIER_BIT |
        GL_CLIENT_MAPPED_BUFFER_BARRIER_BIT;
    const bool requiresCpuSync =
        (barriers == GL_ALL_BARRIER_BITS) ||
        (barriers & kCpuVisibleBarriers) != 0;
    if (requiresCpuSync && impl_->frameGraph != nullptr) {
        impl_->frameGraph->flushForReadback();
    }
    // GPU-to-GPU barriers (UNIFORM / TEXTURE_FETCH / SHADER_STORAGE / etc.)
    // are implicit on Metal's command queue — same-queue ordering is
    // preserved so the next pipeline's reads see the previous pipeline's
    // writes without an explicit fence.
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Compute Shaders
// ---------------------------------------------------------------------------

bool GLContext::dispatchCompute(GLuint num_groups_x, GLuint num_groups_y, GLuint num_groups_z) {
    constexpr GLuint kMaxWorkGroups = 65535;

    if (num_groups_x == 0 || num_groups_y == 0 || num_groups_z == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (num_groups_x > kMaxWorkGroups || num_groups_y > kMaxWorkGroups || num_groups_z > kMaxWorkGroups) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // GL 4.6 §22.4 — credit COMPUTE_SHADER_INVOCATIONS for every
    // active query by the total workgroup-invocation count
    // (groups × local-size). Done before dispatch so the counter
    // advances even if pipeline encode fails.
    impl_->objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
        if (!q.active || q.target != GL_COMPUTE_SHADER_INVOCATIONS) return;
        const GLuint progName = impl_->state->currentProgram();
        const GLProgramObject* p = progName == 0 ? nullptr
            : impl_->objects->programs().get(progName);
        if (p == nullptr) {
            q.result += 1;
            return;
        }
        const GLuint64 local = static_cast<GLuint64>(p->computeLocalSizeX) *
                               static_cast<GLuint64>(p->computeLocalSizeY) *
                               static_cast<GLuint64>(p->computeLocalSizeZ);
        const GLuint64 groups = static_cast<GLuint64>(num_groups_x) *
                                static_cast<GLuint64>(num_groups_y) *
                                static_cast<GLuint64>(num_groups_z);
        q.result += groups * (local == 0 ? 1 : local);
    });

    // Resolve the currently-bound program. GL 4.6 §17.1 requires
    // GL_INVALID_OPERATION when there's no active program OR when
    // the active program doesn't contain a compute shader. We detect
    // both by checking whether `metalComputePipelineState` is non-null
    // — linkProgram only populates it for programs with ProgramKind
    // ::Compute. This surfaces the compute-shader.api-no-active-program
    // / api-program negative tests as spec-correct failures.
    //
    // CKPT119: when the current program is 0 but a program pipeline is
    // bound with a compute stage (glUseProgramStages(...,
    // GL_COMPUTE_SHADER_BIT, prog)), use the pipeline's compute slot.
    // CTS shader_image_size.basic-nonMS-cs-* relies on this path.
    GLuint progName = impl_->state->currentProgram();
    GLProgramObject* programObject = progName == 0 ? nullptr
        : impl_->objects->programs().get(progName);
    if (programObject == nullptr || !programObject->linked
        || programObject->metalComputePipelineState == nullptr) {
        const GLuint pipelineName = impl_->state->currentProgramPipeline();
        if (pipelineName != 0) {
            GLProgramPipelineObject* ppo =
                impl_->objects->programPipelines().get(pipelineName);
            if (ppo != nullptr && ppo->computeProgram != 0) {
                GLProgramObject* csProg =
                    impl_->objects->programs().get(ppo->computeProgram);
                if (csProg != nullptr && csProg->linked
                    && csProg->metalComputePipelineState != nullptr) {
                    programObject = csProg;
                    progName = ppo->computeProgram;
                }
            }
        }
        if (programObject == nullptr || !programObject->linked
            || programObject->metalComputePipelineState == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    if (impl_->frameGraph == nullptr) {
        // Pipeline was built but the frame graph is torn down — no
        // dispatch is possible. Treat as a silent no-op to avoid
        // spurious errors during teardown paths.
        return true;
    }

    ComputeDispatchInfo info;
    info.metalComputePipelineState = programObject->metalComputePipelineState;
    info.metalComputeFunction = programObject->metalComputeFunction;
    info.needsSSBOSizeBuffer =
        programObject->computeMSL.find("spvBufferSizeConstants") != std::string::npos;
    info.groupsX = num_groups_x;
    info.groupsY = num_groups_y;
    info.groupsZ = num_groups_z;
    info.localX = programObject->computeLocalSizeX;
    info.localY = programObject->computeLocalSizeY;
    info.localZ = programObject->computeLocalSizeZ;

    // Pack default uniforms (bare GL uniforms in the _DefaultUniforms
    // block) for the compute stage. Mirrors the graphics-stage path:
    // lazy layout compute + per-dispatch rebuild of the byte buffer
    // from uniformValues. Without this, location-based glUniform*
    // updates for a compute program never reach the MSL kernel.
    // KHR-GL46.explicit_uniform_location.* with a compute variant
    // specifically relies on this.
    thread_local std::vector<std::uint8_t> computeUniformScratch;
    if (!programObject->uniformLayoutComputed
        || programObject->computeUniformLayout.empty()) {
        // Only (re)build the layout vector when we haven't seen this
        // program before OR the compute-side layout is still empty on
        // a program that previously had graphics stages computed.
        computeStageUniformLayout(programObject->computeUniformLayout,
            programObject->computeReflection, programObject->uniforms);
        programObject->uniformLayoutComputed = true;
    }
    pushSynthesizedMatrixUniforms(*programObject, impl_->matrixState);
    buildStageUniformBuffer(computeUniformScratch,
        programObject->computeReflection, programObject->uniformValues,
        programObject->computeUniformLayout);
    if (!computeUniformScratch.empty()) {
        info.computeUniformData = computeUniformScratch.data();
        info.computeUniformSize = computeUniformScratch.size();
    }

    // Resolve shader-storage buffer bindings. For each SSBO the shader
    // declares, look up whatever buffer the app has bound to
    // GL_SHADER_STORAGE_BUFFER at its layout(binding=N) slot via
    // glBindBufferBase / glBindBufferRange, and forward the Metal
    // buffer + offset into the dispatch info. SSBOs with no binding
    // are simply omitted — Metal's unbound-slot behaviour is undefined
    // but won't crash, and the test will fail verification cleanly.
    // Sprint 17 Day 4+ BONUS-2 Phase 2-r [gpu_shader5 ssbo_array_indexing]:
    // SSBO array element iteration. SPIRV-Cross emits a GLSL SSBO array
    // (`buffer B { ... } b[N]`) as N separate `[[buffer(M)]] / [[buffer(
    // M+1)]] ... [[buffer(M+N-1)]]` slots — same shape as the UBO array
    // emit. Each element binds independently at GL slot
    // (effectiveBinding+inst) and Metal slot (ssbo.metalBinding+inst).
    // Sister to the UBO array iteration loop further below (line 29871+,
    // CKPT143 lineage) and the graphics-path resolveUBOBindings array
    // iteration (line 5111+).
    for (const auto& ssbo : programObject->computeReflection.storageBuffers) {
        // Effective binding may be remapped by glShaderStorageBlockBinding;
        // consult resourceStorageBlocks (same pattern as the graphics
        // path's resolveSSBOBindings).
        GLuint effectiveBinding = ssbo.glBinding;
        for (const auto& rb : programObject->resourceStorageBlocks) {
            if (rb.name == ssbo.name && rb.location >= 0) {
                effectiveBinding = static_cast<GLuint>(rb.location);
                break;
            }
        }
        const int numInstances = (ssbo.blockArraySize > 0)
            ? static_cast<int>(ssbo.blockArraySize) : 1;
        const bool isArray = (ssbo.blockArraySize > 0);
        for (int inst = 0; inst < numInstances; ++inst) {
            // Build the lookup name: "B" or "B[0]"/"B[1]"… so
            // glShaderStorageBlockBinding-driven binding overrides on a
            // specific element honor the resourceStorageBlocks map.
            std::string lookupName = ssbo.name;
            if (isArray) lookupName += "[" + std::to_string(inst) + "]";
            // Default per-element binding is effectiveBinding+inst
            // (consecutive slots, GL 4.6 §7.8). Override with
            // resourceStorageBlocks location if remapped.
            GLuint glBindingPoint = effectiveBinding + static_cast<GLuint>(inst);
            for (const auto& rb : programObject->resourceStorageBlocks) {
                if (rb.name == lookupName && rb.location >= 0) {
                    glBindingPoint = static_cast<GLuint>(rb.location);
                    break;
                }
            }
            const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
                GL_SHADER_STORAGE_BUFFER, glBindingPoint);
            if (binding.buffer == 0) continue;
            const GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
            if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;

            ComputeDispatchInfo::BufferBinding bb;
            bb.metalBuffer = bufObj->metalBuffer;
            bb.offset = static_cast<std::size_t>(binding.offset);
            if (binding.size > 0) {
                bb.size = static_cast<std::size_t>(binding.size);
            } else if (binding.offset >= 0 && bufObj->size > binding.offset) {
                bb.size = static_cast<std::size_t>(bufObj->size - binding.offset);
            }
            bb.metalSlot = ssbo.metalBinding + static_cast<std::uint32_t>(inst);
            info.buffers.push_back(bb);
        }
    }

    // Resolve uniform-block bindings for the compute stage. Compute
    // shaders rarely use UBOs (the CTS compute tests almost always go
    // through SSBOs exclusively) but the path is symmetric with the
    // graphics uboBindings resolver — walk each reflected block,
    // look up the bound buffer via glBindBufferBase, forward it.
    //
    // CKPT143 (Sprint 13 Day 7): UBO array support. SPIRV-Cross emits a
    // UBO array (`uniform B { ... } b[N]`) as N separate `[[buffer(M)]]`
    // / `[[buffer(M+1)]]` … `[[buffer(M+N-1)]]` slots. CTS
    // shading_language_420pack.binding_uniform_block_array binds 14
    // separate UBOs to GL slots 2..15 and expects each shader element
    // `goku[i]` to read from the bound buffer at GL slot 2+i. Pre-fix
    // only the first element resolved; the other 13 stayed unbound and
    // returned zero, failing the per-element verification. Mirrors the
    // graphics-path resolveUBOBindings array iteration at line 5111+.
    for (const auto& ubo : programObject->computeReflection.uniformBlocks) {
        if (ubo.name == "_DefaultUniforms") continue;
        const int numInstances = (ubo.blockArraySize > 0)
            ? static_cast<int>(ubo.blockArraySize) : 1;
        const bool isArray = (ubo.blockArraySize > 0);
        for (int inst = 0; inst < numInstances; ++inst) {
            // Build the lookup name: "B" or "B[0]", "B[1]" … so
            // glUniformBlockBinding-driven binding overrides on a
            // specific element honor the resourceUniformBlocks map.
            std::string lookupName = ubo.name;
            if (isArray) {
                lookupName += "[" + std::to_string(inst) + "]";
            }
            // Default per-element binding is glBinding+inst (consecutive
            // slots, GL 4.6 §7.6.2). Override with resourceUniformBlocks
            // location if the app has called glUniformBlockBinding.
            GLuint glBindingPoint = ubo.glBinding + static_cast<GLuint>(inst);
            for (std::size_t bi = 0; bi < programObject->resourceUniformBlocks.size(); ++bi) {
                if (programObject->resourceUniformBlocks[bi].name == lookupName) {
                    GLint bp = programObject->resourceUniformBlocks[bi].location;
                    if (bp >= 0) {
                        glBindingPoint = static_cast<GLuint>(bp);
                    }
                    break;
                }
            }
            const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
                GL_UNIFORM_BUFFER, glBindingPoint);
            if (binding.buffer == 0) continue;
            const GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
            if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;

            ComputeDispatchInfo::BufferBinding bb;
            bb.metalBuffer = bufObj->metalBuffer;
            bb.offset = static_cast<std::size_t>(binding.offset);
            bb.metalSlot = ubo.metalBinding + static_cast<std::uint32_t>(inst);
            info.buffers.push_back(bb);
        }
    }

    // Sprint 17 Day 4+ BONUS-2 Phase 3-r [gpu_shader5 atomic_counters_array_indexing]:
    // atomic counter buffer binding for compute. SPIRV-Cross emits AC
    // as `volatile device gl_AtomicCounterBlock_<N>& [[buffer(N)]]`
    // (atomic counter binding maps directly to a Metal buffer slot at
    // the GL binding value, sister to UBO mapping at slot N+kUniform-
    // BufferBase but distinct in SPIRV-Cross's atomic-counter emit
    // path). Walk the program's atomic-counter buffer resource list
    // (populated at link time from glslang's reflection) and bind
    // each GL_ATOMIC_COUNTER_BUFFER-bound buffer at the matching
    // Metal slot. Without this binding, atomicCounter* operations
    // execute against an unbound MTLBuffer and produce undefined
    // (typically zero) reads.
    for (const auto& ac : programObject->resourceAtomicCounterBuffers) {
        if (ac.binding < 0) continue;
        const GLuint glBinding = static_cast<GLuint>(ac.binding);
        const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
            GL_ATOMIC_COUNTER_BUFFER, glBinding);
        if (binding.buffer == 0) continue;
        const GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
        if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;

        ComputeDispatchInfo::BufferBinding bb;
        bb.metalBuffer = bufObj->metalBuffer;
        bb.offset = static_cast<std::size_t>(binding.offset);
        // SPIRV-Cross atomic counter Metal slot mapping: GL binding
        // value used directly (verified via APPGL_DUMP_MSL output for
        // `gpu_shader5.atomic_counters_array_indexing`:
        // `[[buffer(0)]]` for `layout(binding=0)`).
        bb.metalSlot = glBinding;
        info.buffers.push_back(bb);
    }

    // Texture/sampler bindings for compute stage. Less common than
    // SSBOs but real — image-processing compute shaders sample from
    // textures. Walk each reflected sampler uniform, resolve the
    // texture unit via the shader's sampler uniform value, and bind
    // the resulting (texture, sampler) pair at the reflected slot.
    // The logic mirrors resolveSamplerBindings but targets the
    // compute slot space.
    // CKPT144 (Sprint 13 Day 8): sampler-type-aware texture target lookup
    // for compute. The pre-fix code probed GL_TEXTURE_2D first then fell
    // back to boundTextureOnUnitAny — which iterates targets in
    // {2D, 2D_ARRAY, CUBE_MAP, …, 1D, 1D_ARRAY, …} order and returns the
    // first non-zero binding. CTS shading_language_420pack.binding_samplers_
    // texture_type_{1D,1D_array,2D_array,2D_rect,3D,cube} declares the
    // sampler with a non-2D type. gluStateReset binds a default texture
    // (name 0) to every (unit, target) pair before each test, so the
    // unit always has a 2D entry. Pre-fix: a `sampler1D` lookup hit the
    // GL_TEXTURE_2D probe first and returned the default-2D texture
    // (which Metal then refused to bind to a `texture1d` slot, or
    // sampling returned zeros). Mirrors the graphics-path resolveSamplerBindings
    // sampler-type → preferredTarget mapping at line 4607+.
    auto preferredTargetForSamplerType = [](GLenum samplerGLType) -> GLenum {
        switch (samplerGLType) {
            case GL_SAMPLER_1D:
            case GL_INT_SAMPLER_1D:
            case GL_UNSIGNED_INT_SAMPLER_1D:
            case GL_SAMPLER_1D_SHADOW:
                return GL_TEXTURE_1D;
            case GL_SAMPLER_2D:
            case GL_INT_SAMPLER_2D:
            case GL_UNSIGNED_INT_SAMPLER_2D:
            case GL_SAMPLER_2D_SHADOW:
                return GL_TEXTURE_2D;
            case GL_SAMPLER_3D:
            case GL_INT_SAMPLER_3D:
            case GL_UNSIGNED_INT_SAMPLER_3D:
                return GL_TEXTURE_3D;
            case GL_SAMPLER_CUBE:
            case GL_INT_SAMPLER_CUBE:
            case GL_UNSIGNED_INT_SAMPLER_CUBE:
            case GL_SAMPLER_CUBE_SHADOW:
                return GL_TEXTURE_CUBE_MAP;
            case GL_SAMPLER_1D_ARRAY:
            case GL_INT_SAMPLER_1D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_1D_ARRAY:
            case GL_SAMPLER_1D_ARRAY_SHADOW:
                return GL_TEXTURE_1D_ARRAY;
            case GL_SAMPLER_2D_ARRAY:
            case GL_INT_SAMPLER_2D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_ARRAY:
            case GL_SAMPLER_2D_ARRAY_SHADOW:
                return GL_TEXTURE_2D_ARRAY;
            case GL_SAMPLER_2D_RECT:
            case GL_INT_SAMPLER_2D_RECT:
            case GL_UNSIGNED_INT_SAMPLER_2D_RECT:
            case GL_SAMPLER_2D_RECT_SHADOW:
                return GL_TEXTURE_RECTANGLE;
            case GL_SAMPLER_BUFFER:
            case GL_INT_SAMPLER_BUFFER:
            case GL_UNSIGNED_INT_SAMPLER_BUFFER:
                return GL_TEXTURE_BUFFER;
            case GL_SAMPLER_CUBE_MAP_ARRAY:
            case GL_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_SAMPLER_CUBE_MAP_ARRAY_SHADOW:
                return GL_TEXTURE_CUBE_MAP_ARRAY;
            case GL_SAMPLER_2D_MULTISAMPLE:
            case GL_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE:
                return GL_TEXTURE_2D_MULTISAMPLE;
            case GL_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
                return GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            default:
                return 0;
        }
    };

    const bool traceCompSamp = std::getenv("APPGL_TRACE_COMP_SAMP") != nullptr;
    for (const auto& samp : programObject->computeReflection.sampledTextures) {
        // Find the matching uniform to read its texture-unit value AND
        // its sampler GL type (drives preferredTarget below).
        GLint uniformLoc = -1;
        GLenum samplerGLType = 0;
        GLint samplerArraySize = 1;
        for (const auto& u : programObject->uniforms) {
            if (u.name == samp.name) {
                uniformLoc = u.location;
                samplerGLType = u.type;
                samplerArraySize = std::max<GLint>(u.arraySize, 1);
                break;
            }
        }
        if (uniformLoc < 0) {
            if (traceCompSamp) std::fprintf(stderr, "[CMP-SAMP] name=%s SKIP=no_uniform\n", samp.name.c_str());
            continue;
        }
        auto uvIt = programObject->uniformValues.find(uniformLoc);
        const GLProgramUniformValue* samplerValue =
            (uvIt != programObject->uniformValues.end()) ? &uvIt->second : nullptr;

        GLenum preferredTarget = preferredTargetForSamplerType(samplerGLType);

        // CKPT145 (Sprint 13 Day 9): sampler array iteration. SPIRV-Cross
        // emits a sampler array (`uniform sampler2D goku[7]`) as N
        // separate `[[texture(M+i)]]` slots. CTS shading_language_420pack.
        // binding_sampler_array binds 7 distinct textures at GL units 1..7
        // and expects each shader element `goku[i]` to read from the bound
        // texture at GL unit 1+i. Pre-fix: only goku[0] resolved (compute
        // path read `ints[0]` once); goku[1..6] unbound → wrong values.
        // Mirrors the graphics-path resolveSamplerBindings array iteration
        // at GLContext.mm:4683+.
        for (GLint arrayElement = 0; arrayElement < samplerArraySize; ++arrayElement) {
            GLuint unit = 0;
            if (samplerValue != nullptr &&
                static_cast<std::size_t>(arrayElement) < samplerValue->ints.size()) {
                unit = static_cast<GLuint>(samplerValue->ints[arrayElement]);
            }

            // Probe the sampler-type-derived target FIRST. Falls back to
            // GL_TEXTURE_2D probe + any-target if the preferred target has
            // no binding.
            GLenum discoveredTarget = preferredTarget != 0 ? preferredTarget : GL_TEXTURE_2D;
            GLuint texName = preferredTarget != 0
                ? impl_->state->boundTextureOnUnit(unit, preferredTarget) : 0;
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnit(unit, GL_TEXTURE_2D);
                if (texName != 0) discoveredTarget = GL_TEXTURE_2D;
            }
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnitAny(unit, &discoveredTarget);
            }
            if (traceCompSamp) {
                std::fprintf(stderr, "[CMP-SAMP] name=%s[%d] loc=%d type=0x%X unit=%u prefTgt=0x%X tex=%u tgt=0x%X metalSlot=%u",
                    samp.name.c_str(), arrayElement, uniformLoc, samplerGLType, unit, preferredTarget,
                    texName, discoveredTarget, samp.metalBinding + arrayElement);
            }
            if (texName == 0) {
                if (traceCompSamp) std::fprintf(stderr, " SKIP=no_texture\n");
                continue;
            }

            GLTextureObject* texObj = impl_->objects->textures().get(texName);
            if (texObj == nullptr || texObj->metalTexture == nullptr) {
                if (traceCompSamp) std::fprintf(stderr, " SKIP=null_metalTexture\n");
                continue;
            }
            // Build the sampler state if dirty.
            if (texObj->samplerDirty) {
                impl_->rebuildTextureSamplerState(texName, *texObj);
            }

            ComputeDispatchInfo::TextureBinding tb;
            tb.metalTexture = texObj->metalTexture;
            tb.metalSamplerState = texObj->metalSampler;
            tb.metalSlot = samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
            info.textures.push_back(tb);
            if (traceCompSamp) std::fprintf(stderr, " BOUND\n");
        }
    }

    // Storage images (imageLoad/imageStore). Bound via
    // glBindImageTexture(unit, …) rather than a sampler uniform. The
    // shader's `layout(binding=N)` is the DEFAULT image unit; GL 4.6
    // §7.6 allows glUniform1i(loc, K) to change the effective image
    // unit to K at runtime (same mechanism as sampler uniforms). CTS
    // shading_language_420pack.binding_images_* relies on this — only
    // one of the three images has an explicit layout binding, and the
    // others rely on glUniform1i to set the unit.
    for (const auto& img : programObject->computeReflection.storageImages) {
        // CKPT145 (Sprint 13 Day 9): storage image array iteration. SPIRV-
        // Cross emits an image array (`uniform image2D goku[7]`) as N
        // separate `[[texture(M+i)]]` slots. Pre-fix: only goku[0] resolved;
        // goku[1..N-1] unbound → wrong values. CTS shading_language_420pack.
        // binding_image_array exercises this with 7 elements.
        // Look up the matching uniform to read array size + per-element
        // uniform-value (glUniform1i overrides).
        GLint imageArraySize = 1;
        const GLProgramUniformValue* imageValue = nullptr;
        for (const auto& u : programObject->uniforms) {
            if (u.name == img.name) {
                imageArraySize = std::max<GLint>(u.arraySize, 1);
                auto uvIt = programObject->uniformValues.find(u.location);
                if (uvIt != programObject->uniformValues.end()) {
                    imageValue = &uvIt->second;
                }
                break;
            }
        }
        for (GLint arrayElement = 0; arrayElement < imageArraySize; ++arrayElement) {
            // GL 4.6 §7.6: per-element effective unit. Default is
            // glBinding+arrayElement (consecutive layout). Override per
            // element via glUniform1i(loc[i], K).
            GLuint effectiveUnit = img.glBinding + static_cast<GLuint>(arrayElement);
            if (imageValue != nullptr &&
                static_cast<std::size_t>(arrayElement) < imageValue->ints.size()) {
                effectiveUnit = static_cast<GLuint>(imageValue->ints[arrayElement]);
            }
            if (effectiveUnit >= Impl::kMaxImageUnits) continue;
            auto& ib = impl_->imageBindings[effectiveUnit];
            if (ib.texture == 0) continue;
            GLTextureObject* texObj = impl_->objects->textures().get(ib.texture);
            if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
            ComputeDispatchInfo::TextureBinding tb;
            // CKPT119: level-restricted view when ib.level > 0.
            tb.metalTexture = impl_->resolveImageMetalTexture(ib, texObj);
            tb.metalSamplerState = nullptr;  // no sampler for storage images
            tb.metalSlot = img.metalBinding + static_cast<std::uint32_t>(arrayElement);
            info.textures.push_back(tb);
        }
    }

    (void)impl_->frameGraph->encodeComputeDispatch(info);
    return true;
}

bool GLContext::dispatchComputeIndirect(GLintptr indirect) {
    if (indirect < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((indirect % 4) != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // GL 4.6 §17.2: GL_INVALID_OPERATION when no active compute program
    // (matches dispatchCompute's spec-correct check below). Without
    // this, the compute_shader.api-indirect / api-no-active-program
    // negative tests see GL_NO_ERROR and fail.
    const GLuint progName = impl_->state->currentProgram();
    GLProgramObject* programObject = progName == 0 ? nullptr
        : impl_->objects->programs().get(progName);
    if (programObject == nullptr || !programObject->linked
        || programObject->metalComputePipelineState == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §17.2: also INVALID_OPERATION when no buffer is bound
    // to the GL_DISPATCH_INDIRECT_BUFFER target, or when the command
    // would read past the end of the bound buffer.
    const GLuint dispatchBufName = impl_->state->boundBuffer(GL_DISPATCH_INDIRECT_BUFFER);
    if (dispatchBufName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const GLBufferObject* dispatchBuf = impl_->objects->buffers().get(dispatchBufName);
    if (dispatchBuf == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Three GLuints (x, y, z work-group counts) at `indirect`.
    constexpr GLsizeiptr kIndirectDispatchSize = 3 * sizeof(GLuint);
    if (indirect > dispatchBuf->size
        || kIndirectDispatchSize > dispatchBuf->size - indirect) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §22.4 — credit COMPUTE_SHADER_INVOCATIONS for every
    // active query, mirroring the direct-dispatch path above. The
    // indirect buffer is CPU-mapped on Apple silicon so we can read
    // the (x, y, z) groups for a real count; if that read fails we
    // fall back to local-size × 1-group to satisfy EQUAL_OR_GREATER.
    // CTS `pipeline_statistics_query_tests_ARB.functional_compute_
    // shader_invocations` runs the query over dispatchCompute +
    // dispatchComputeIndirect and expects result >= 1 on both.
    {
        GLuint64 groups = 0;
        if (dispatchBuf->metalBuffer != nullptr) {
            id<MTLBuffer> mtl = (__bridge id<MTLBuffer>)dispatchBuf->metalBuffer;
            const void* ptr = [mtl contents];
            if (ptr != nullptr) {
                const GLuint* args = reinterpret_cast<const GLuint*>(
                    reinterpret_cast<const std::uint8_t*>(ptr) +
                    static_cast<std::size_t>(indirect));
                groups = static_cast<GLuint64>(args[0]) *
                         static_cast<GLuint64>(args[1]) *
                         static_cast<GLuint64>(args[2]);
            }
        }
        if (groups == 0) groups = 1;
        const GLuint64 local = static_cast<GLuint64>(programObject->computeLocalSizeX) *
                               static_cast<GLuint64>(programObject->computeLocalSizeY) *
                               static_cast<GLuint64>(programObject->computeLocalSizeZ);
        const GLuint64 invocations = groups * (local == 0 ? 1 : local);
        impl_->objects->queries().forEach([&](GLuint /*id*/, GLQueryObject& q) {
            if (!q.active || q.target != GL_COMPUTE_SHADER_INVOCATIONS) return;
            q.result += invocations;
        });
    }

    // Route the indirect dispatch through the same encoder as the
    // direct path. Metal reads the (groupsX, groupsY, groupsZ) triple
    // out of the buffer at dispatch time via
    // dispatchThreadgroupsWithIndirectBuffer — we just hand it the
    // MTLBuffer + offset.
    if (impl_->frameGraph == nullptr) {
        return true;  // teardown — silently no-op, same as direct path
    }
    ComputeDispatchInfo info;
    info.metalComputePipelineState = programObject->metalComputePipelineState;
    info.metalComputeFunction = programObject->metalComputeFunction;
    info.needsSSBOSizeBuffer =
        programObject->computeMSL.find("spvBufferSizeConstants") != std::string::npos;
    info.localX = programObject->computeLocalSizeX;
    info.localY = programObject->computeLocalSizeY;
    info.localZ = programObject->computeLocalSizeZ;
    info.indirectBuffer = dispatchBuf->metalBuffer;
    info.indirectOffset = static_cast<std::size_t>(indirect);

    // Same resource plumbing as the direct dispatch path: SSBOs, UBOs,
    // default-uniform push constants, sampled textures. Keep in sync
    // with GLContext::dispatchCompute.
    for (const auto& ssbo : programObject->computeReflection.storageBuffers) {
        const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
            GL_SHADER_STORAGE_BUFFER, ssbo.glBinding);
        if (binding.buffer == 0) continue;
        const GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
        if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
        ComputeDispatchInfo::BufferBinding bb;
        bb.metalBuffer = bufObj->metalBuffer;
        bb.offset = static_cast<std::size_t>(binding.offset);
        if (binding.size > 0) {
            bb.size = static_cast<std::size_t>(binding.size);
        } else if (binding.offset >= 0 && bufObj->size > binding.offset) {
            bb.size = static_cast<std::size_t>(bufObj->size - binding.offset);
        }
        bb.metalSlot = ssbo.metalBinding;
        info.buffers.push_back(bb);
    }
    // CKPT143 (Sprint 13 Day 7): UBO array support — see direct-dispatch
    // path above for full rationale. Mirror here for dispatchComputeIndirect.
    for (const auto& ubo : programObject->computeReflection.uniformBlocks) {
        if (ubo.name == "_DefaultUniforms") continue;
        const int numInstances = (ubo.blockArraySize > 0)
            ? static_cast<int>(ubo.blockArraySize) : 1;
        const bool isArray = (ubo.blockArraySize > 0);
        for (int inst = 0; inst < numInstances; ++inst) {
            std::string lookupName = ubo.name;
            if (isArray) {
                lookupName += "[" + std::to_string(inst) + "]";
            }
            GLuint glBindingPoint = ubo.glBinding + static_cast<GLuint>(inst);
            for (std::size_t bi = 0; bi < programObject->resourceUniformBlocks.size(); ++bi) {
                if (programObject->resourceUniformBlocks[bi].name == lookupName) {
                    GLint bp = programObject->resourceUniformBlocks[bi].location;
                    if (bp >= 0) {
                        glBindingPoint = static_cast<GLuint>(bp);
                    }
                    break;
                }
            }
            const GLIndexedBufferBinding binding = impl_->state->indexedBufferBinding(
                GL_UNIFORM_BUFFER, glBindingPoint);
            if (binding.buffer == 0) continue;
            const GLBufferObject* bufObj = impl_->objects->buffers().get(binding.buffer);
            if (bufObj == nullptr || bufObj->metalBuffer == nullptr) continue;
            ComputeDispatchInfo::BufferBinding bb;
            bb.metalBuffer = bufObj->metalBuffer;
            bb.offset = static_cast<std::size_t>(binding.offset);
            bb.metalSlot = ubo.metalBinding + static_cast<std::uint32_t>(inst);
            info.buffers.push_back(bb);
        }
    }
    thread_local std::vector<std::uint8_t> computeUniformScratchIndirect;
    if (!programObject->uniformLayoutComputed
        || programObject->computeUniformLayout.empty()) {
        computeStageUniformLayout(programObject->computeUniformLayout,
            programObject->computeReflection, programObject->uniforms);
        programObject->uniformLayoutComputed = true;
    }
    pushSynthesizedMatrixUniforms(*programObject, impl_->matrixState);
    buildStageUniformBuffer(computeUniformScratchIndirect,
        programObject->computeReflection, programObject->uniformValues,
        programObject->computeUniformLayout);
    if (!computeUniformScratchIndirect.empty()) {
        info.computeUniformData = computeUniformScratchIndirect.data();
        info.computeUniformSize = computeUniformScratchIndirect.size();
    }
    // CKPT144 (Sprint 13 Day 8): sampler-type-aware target lookup —
    // see direct-dispatch path above for full rationale. Indirect mirror.
    auto preferredTargetForSamplerType2 = [](GLenum samplerGLType) -> GLenum {
        switch (samplerGLType) {
            case GL_SAMPLER_1D: case GL_INT_SAMPLER_1D: case GL_UNSIGNED_INT_SAMPLER_1D:
            case GL_SAMPLER_1D_SHADOW: return GL_TEXTURE_1D;
            case GL_SAMPLER_2D: case GL_INT_SAMPLER_2D: case GL_UNSIGNED_INT_SAMPLER_2D:
            case GL_SAMPLER_2D_SHADOW: return GL_TEXTURE_2D;
            case GL_SAMPLER_3D: case GL_INT_SAMPLER_3D: case GL_UNSIGNED_INT_SAMPLER_3D:
                return GL_TEXTURE_3D;
            case GL_SAMPLER_CUBE: case GL_INT_SAMPLER_CUBE: case GL_UNSIGNED_INT_SAMPLER_CUBE:
            case GL_SAMPLER_CUBE_SHADOW: return GL_TEXTURE_CUBE_MAP;
            case GL_SAMPLER_1D_ARRAY: case GL_INT_SAMPLER_1D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_1D_ARRAY: case GL_SAMPLER_1D_ARRAY_SHADOW:
                return GL_TEXTURE_1D_ARRAY;
            case GL_SAMPLER_2D_ARRAY: case GL_INT_SAMPLER_2D_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_ARRAY: case GL_SAMPLER_2D_ARRAY_SHADOW:
                return GL_TEXTURE_2D_ARRAY;
            case GL_SAMPLER_2D_RECT: case GL_INT_SAMPLER_2D_RECT:
            case GL_UNSIGNED_INT_SAMPLER_2D_RECT: case GL_SAMPLER_2D_RECT_SHADOW:
                return GL_TEXTURE_RECTANGLE;
            case GL_SAMPLER_BUFFER: case GL_INT_SAMPLER_BUFFER:
            case GL_UNSIGNED_INT_SAMPLER_BUFFER: return GL_TEXTURE_BUFFER;
            case GL_SAMPLER_CUBE_MAP_ARRAY: case GL_INT_SAMPLER_CUBE_MAP_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_CUBE_MAP_ARRAY: case GL_SAMPLER_CUBE_MAP_ARRAY_SHADOW:
                return GL_TEXTURE_CUBE_MAP_ARRAY;
            case GL_SAMPLER_2D_MULTISAMPLE: case GL_INT_SAMPLER_2D_MULTISAMPLE:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE: return GL_TEXTURE_2D_MULTISAMPLE;
            case GL_SAMPLER_2D_MULTISAMPLE_ARRAY: case GL_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
            case GL_UNSIGNED_INT_SAMPLER_2D_MULTISAMPLE_ARRAY:
                return GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
            default: return 0;
        }
    };
    // CKPT145 (Sprint 13 Day 9): sampler array iteration — see direct
    // dispatch path for full rationale. Indirect mirror.
    for (const auto& samp : programObject->computeReflection.sampledTextures) {
        GLint uniformLoc = -1;
        GLenum samplerGLType = 0;
        GLint samplerArraySize = 1;
        for (const auto& u : programObject->uniforms) {
            if (u.name == samp.name) {
                uniformLoc = u.location;
                samplerGLType = u.type;
                samplerArraySize = std::max<GLint>(u.arraySize, 1);
                break;
            }
        }
        if (uniformLoc < 0) continue;
        auto uvIt = programObject->uniformValues.find(uniformLoc);
        const GLProgramUniformValue* samplerValue =
            (uvIt != programObject->uniformValues.end()) ? &uvIt->second : nullptr;
        GLenum preferredTarget = preferredTargetForSamplerType2(samplerGLType);
        for (GLint arrayElement = 0; arrayElement < samplerArraySize; ++arrayElement) {
            GLuint unit = 0;
            if (samplerValue != nullptr &&
                static_cast<std::size_t>(arrayElement) < samplerValue->ints.size()) {
                unit = static_cast<GLuint>(samplerValue->ints[arrayElement]);
            }
            GLenum discoveredTarget = preferredTarget != 0 ? preferredTarget : GL_TEXTURE_2D;
            GLuint texName = preferredTarget != 0
                ? impl_->state->boundTextureOnUnit(unit, preferredTarget) : 0;
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnit(unit, GL_TEXTURE_2D);
                if (texName != 0) discoveredTarget = GL_TEXTURE_2D;
            }
            if (texName == 0) {
                texName = impl_->state->boundTextureOnUnitAny(unit, &discoveredTarget);
            }
            if (texName == 0) continue;
            GLTextureObject* texObj = impl_->objects->textures().get(texName);
            if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
            if (texObj->samplerDirty) {
                impl_->rebuildTextureSamplerState(texName, *texObj);
            }
            ComputeDispatchInfo::TextureBinding tb;
            tb.metalTexture = texObj->metalTexture;
            tb.metalSamplerState = texObj->metalSampler;
            tb.metalSlot = samp.metalBinding + static_cast<std::uint32_t>(arrayElement);
            info.textures.push_back(tb);
        }
    }
    // Storage images for the indirect path — mirror the direct path.
    for (const auto& img : programObject->computeReflection.storageImages) {
        if (img.glBinding >= Impl::kMaxImageUnits) continue;
        auto& ib = impl_->imageBindings[img.glBinding];
        if (ib.texture == 0) continue;
        GLTextureObject* texObj = impl_->objects->textures().get(ib.texture);
        if (texObj == nullptr || texObj->metalTexture == nullptr) continue;
        ComputeDispatchInfo::TextureBinding tb;
        // CKPT119: level-restricted view when ib.level > 0.
        tb.metalTexture = impl_->resolveImageMetalTexture(ib, texObj);
        tb.metalSamplerState = nullptr;
        tb.metalSlot = img.metalBinding;
        info.textures.push_back(tb);
    }

    (void)impl_->frameGraph->encodeComputeDispatch(info);
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Image Load/Store
// ---------------------------------------------------------------------------

bool GLContext::bindImageTexture(GLuint unit, GLuint texture, GLint level, GLboolean layered, GLint layer, GLenum access, GLenum format) {
    if (unit >= Impl::kMaxImageUnits) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (access != GL_READ_ONLY && access != GL_WRITE_ONLY && access != GL_READ_WRITE) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Validate format — accept the common image load/store formats.
    switch (format) {
        case GL_RGBA32F:
        case GL_RGBA16F:
        case GL_RG32F:
        case GL_RG16F:
        case GL_R11F_G11F_B10F:
        case GL_R32F:
        case GL_R16F:
        case GL_RGBA32UI:
        case GL_RGBA16UI:
        case GL_RGB10_A2UI:
        case GL_RGBA8UI:
        case GL_RG32UI:
        case GL_RG16UI:
        case GL_RG8UI:
        case GL_R32UI:
        case GL_R16UI:
        case GL_R8UI:
        case GL_RGBA32I:
        case GL_RGBA16I:
        case GL_RGBA8I:
        case GL_RG32I:
        case GL_RG16I:
        case GL_RG8I:
        case GL_R32I:
        case GL_R16I:
        case GL_R8I:
        case GL_RGBA16:
        case GL_RGB10_A2:
        case GL_RGBA8:
        case GL_RG16:
        case GL_RG8:
        case GL_R16:
        case GL_R8:
        case GL_RGBA16_SNORM:
        case GL_RGBA8_SNORM:
        case GL_RG16_SNORM:
        case GL_RG8_SNORM:
        case GL_R16_SNORM:
        case GL_R8_SNORM:
            break;
        default:
            pushError(GL_INVALID_VALUE);
            return false;
    }

    auto& binding = impl_->imageBindings[unit];
    // CKPT119: invalidate the cached per-level texture view if the
    // binding's identity (texture or level) changes, so the next
    // `resolveImageMetalTexture` call re-creates a fresh view.
    if (binding.metalLevelView != nullptr &&
        (binding.cachedViewTexture != texture ||
         binding.cachedViewLevel != level)) {
        releaseRetainedMetalObject(binding.metalLevelView);
        binding.metalLevelView = nullptr;
        binding.cachedViewTexture = 0;
        binding.cachedViewLevel = -1;
    }
    binding.texture = texture;
    binding.level = level;
    binding.layered = layered;
    binding.layer = layer;
    binding.access = access;
    binding.format = format;
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Atomic Counter Buffer Queries
// ---------------------------------------------------------------------------

bool GLContext::getActiveAtomicCounterBufferiv(GLuint program, GLuint bufferIndex, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLProgramObject* object = impl_->objects->programs().get(program);
    if (object == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Metal has no native atomic counters. Programs will never report any
    // active atomic counter buffers, so any bufferIndex is out of range.
    // However, for applications that query speculatively we return sensible
    // defaults when bufferIndex == 0 to avoid error spam, and GL_INVALID_VALUE
    // otherwise.
    if (bufferIndex > 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    switch (pname) {
        case GL_ATOMIC_COUNTER_BUFFER_BINDING:
            *params = 0;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_DATA_SIZE:
            *params = 0;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_ACTIVE_ATOMIC_COUNTERS:
            *params = 0;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_VERTEX_SHADER:
            *params = GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_FRAGMENT_SHADER:
            *params = GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_GEOMETRY_SHADER:
            *params = GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_TESS_CONTROL_SHADER:
            *params = GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_TESS_EVALUATION_SHADER:
            *params = GL_FALSE;
            return true;
        case GL_ATOMIC_COUNTER_BUFFER_REFERENCED_BY_COMPUTE_SHADER:
            *params = GL_FALSE;
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

// ---------------------------------------------------------------------------
// GL 4.3 — Program Resource Introspection (ARB_program_interface_query)
// ---------------------------------------------------------------------------

namespace {

const std::vector<GLProgramResourceEntry>* getResourceTable(const GLProgramObject& prog, GLenum programInterface) {
    switch (programInterface) {
        case GL_UNIFORM:                      return &prog.resourceUniforms;
        case GL_UNIFORM_BLOCK:                return &prog.resourceUniformBlocks;
        case GL_PROGRAM_INPUT:                return &prog.resourceInputs;
        case GL_PROGRAM_OUTPUT:               return &prog.resourceOutputs;
        case GL_SHADER_STORAGE_BLOCK:         return &prog.resourceStorageBlocks;
        case GL_ATOMIC_COUNTER_BUFFER:        return &prog.resourceAtomicCounterBuffers;
        case GL_BUFFER_VARIABLE:              return &prog.resourceBufferVariables;
        case GL_TRANSFORM_FEEDBACK_VARYING:   return &prog.resourceTransformFeedbackVaryings;
        case GL_TRANSFORM_FEEDBACK_BUFFER:    return &prog.resourceTransformFeedbackBuffers;
        // GL 4.0 subroutine interfaces — per-stage (VS=0, TCS=1,
        // TES=2, GS=3, FS=4, CS=5).
        case GL_VERTEX_SUBROUTINE:               return &prog.resourceSubroutines[0];
        case GL_TESS_CONTROL_SUBROUTINE:         return &prog.resourceSubroutines[1];
        case GL_TESS_EVALUATION_SUBROUTINE:      return &prog.resourceSubroutines[2];
        case GL_GEOMETRY_SUBROUTINE:             return &prog.resourceSubroutines[3];
        case GL_FRAGMENT_SUBROUTINE:             return &prog.resourceSubroutines[4];
        case GL_COMPUTE_SUBROUTINE:              return &prog.resourceSubroutines[5];
        case GL_VERTEX_SUBROUTINE_UNIFORM:       return &prog.resourceSubroutineUniforms[0];
        case GL_TESS_CONTROL_SUBROUTINE_UNIFORM: return &prog.resourceSubroutineUniforms[1];
        case GL_TESS_EVALUATION_SUBROUTINE_UNIFORM: return &prog.resourceSubroutineUniforms[2];
        case GL_GEOMETRY_SUBROUTINE_UNIFORM:     return &prog.resourceSubroutineUniforms[3];
        case GL_FRAGMENT_SUBROUTINE_UNIFORM:     return &prog.resourceSubroutineUniforms[4];
        case GL_COMPUTE_SUBROUTINE_UNIFORM:      return &prog.resourceSubroutineUniforms[5];
        default: return nullptr;
    }
}

GLint getResourceProperty(const GLProgramResourceEntry& entry, GLenum prop) {
    switch (prop) {
        case GL_NAME_LENGTH:       return static_cast<GLint>(entry.name.size() + 1);
        case GL_TYPE:              return static_cast<GLint>(entry.type);
        case GL_ARRAY_SIZE:
            // GL 4.6 §7.3.1: scalar/vector uniforms report 1, N-
            // element arrays report N, unbounded arrays report 0.
            // Scanner uniforms set arraySize=1 for scalars directly;
            // block-member reflection keeps SPIRV-Cross's raw
            // arraySize (0 for both scalars and unbounded) and sets
            // isArray. Use isArray to split the 0-case.
            return entry.isArray ? entry.arraySize : std::max<GLint>(entry.arraySize, 1);
        case GL_OFFSET:            return entry.offset;
        case GL_BLOCK_INDEX:       return entry.blockIndex;
        case GL_LOCATION:          return entry.location;
        // `referencedBy` is a bitmask: 0x01 VS / 0x02 FS /
        // 0x04 GS / 0x08 TCS / 0x10 TES / 0x20 CS. Prior code
        // read GS / TCS / TES as always-FALSE and incorrectly
        // mapped the 0x04 bit to COMPUTE, so GS-stage queries
        // all reported zero even after the per-resource
        // referencedBy derivation started setting them.
        case GL_REFERENCED_BY_VERTEX_SHADER:   return (entry.referencedBy & 0x01) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_FRAGMENT_SHADER: return (entry.referencedBy & 0x02) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_GEOMETRY_SHADER: return (entry.referencedBy & 0x04) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_TESS_CONTROL_SHADER: return (entry.referencedBy & 0x08) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_TESS_EVALUATION_SHADER: return (entry.referencedBy & 0x10) ? GL_TRUE : GL_FALSE;
        case GL_REFERENCED_BY_COMPUTE_SHADER:  return (entry.referencedBy & 0x20) ? GL_TRUE : GL_FALSE;
        case GL_BUFFER_BINDING:    return entry.binding >= 0 ? entry.binding : entry.location;
        case GL_BUFFER_DATA_SIZE:
            // Only valid on block interfaces. For UBOs it's the
            // std140/std430 byte size; we stored it in `offset`.
            // SSBOs with trailing unbounded arrays legitimately
            // have byteSize=0, which the spec accepts.
            return entry.offset >= 0 ? entry.offset : 0;
        case GL_NUM_ACTIVE_VARIABLES:
            return static_cast<GLint>(entry.activeVariables.size());
        case GL_ACTIVE_VARIABLES:
            // Single-value accessor; the real
            // `glGetProgramResourceiv` read path copies the full
            // list via the props iteration. Return the first
            // element (or 0 if empty) — not fully spec-correct
            // but unblocks tests that just check
            // NUM_ACTIVE_VARIABLES and the first entry.
            return entry.activeVariables.empty()
                ? 0 : entry.activeVariables.front();
        case GL_IS_ROW_MAJOR:      return entry.isRowMajor ? GL_TRUE : GL_FALSE;
        // GL 4.6 §7.3.1: GL_MATRIX_STRIDE / GL_ARRAY_STRIDE
        // return the byte stride between matrix columns/rows
        // and between array elements respectively, for block
        // members. -1 when the variable isn't a member of a
        // buffer-backed block. The reflection-captured stride
        // propagates via `entry.matrixStride` / `entry.arrayStride`.
        case GL_MATRIX_STRIDE:
            return entry.blockIndex >= 0 ? entry.matrixStride : -1;
        case GL_ARRAY_STRIDE:
            return entry.blockIndex >= 0 ? entry.arrayStride : -1;
        case GL_ATOMIC_COUNTER_BUFFER_INDEX:
            // Set on uniform entries whose type is
            // GL_UNSIGNED_INT_ATOMIC_COUNTER at link time;
            // -1 on any non-atomic uniform.
            return entry.atomicCounterBufferIndex;
        case GL_TOP_LEVEL_ARRAY_SIZE:
            // Only meaningful on GL_BUFFER_VARIABLE entries; spec
            // returns 1 for non-buffer-variable queries (never
            // reached since propInterfaceCompatible restricts this
            // prop to GL_BUFFER_VARIABLE).
            return entry.topLevelArraySize;
        case GL_TOP_LEVEL_ARRAY_STRIDE: return entry.topLevelArrayStride;
        case GL_NUM_COMPATIBLE_SUBROUTINES:
            // On GL_*_SUBROUTINE_UNIFORM entries, number of subroutine
            // impls compatible with this uniform's declared type.
            // Populated at link time into `activeVariables`.
            return static_cast<GLint>(entry.activeVariables.size());
        case GL_COMPATIBLE_SUBROUTINES:
            // Single-value fallback — the real multi-value read path
            // in `getProgramResourceiv` already handles ACTIVE_VARIABLES-
            // style expansion. Return the first compatible subroutine
            // index (or 0 if empty) for any caller that invokes
            // `getResourceProperty` directly.
            return entry.activeVariables.empty()
                ? 0 : entry.activeVariables.front();
        case GL_LOCATION_INDEX:
            // Built-in outputs like `gl_FragDepth` have no user-
            // assignable location — LOCATION_INDEX is -1 there
            // (the spec language is ambiguous but CTS expects
            // this). `entry.location == -1` is our signal.
            return entry.location < 0 ? -1 : entry.locationIndex;
        case GL_IS_PER_PATCH:           return entry.isPerPatch ? GL_TRUE : GL_FALSE;
        case GL_LOCATION_COMPONENT:     return 0;
        default: return 0;
    }
}

}  // anonymous namespace

bool GLContext::getProgramInterfaceiv(GLuint program, GLenum programInterface, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        // GL 4.6 §7.3.1: shader-name → INVALID_OPERATION,
        // other bogus names → INVALID_VALUE. See
        // getProgramResourceIndex for the same distinguishing
        // logic. Required by CTS
        // `program_interface_query.invalid-operation` Case 1.
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return false;
    }
    // CTS program_interface_query.empty-shaders constructs a program
    // with no shaders attached, never links it, and queries every
    // interface — expecting ACTIVE_RESOURCES=0 and MAX_NAME_LENGTH=0
    // without an error. A strict GL_INVALID_OPERATION on unlinked
    // programs makes 39/43 of program_interface_query fail; instead
    // the empty-program path returns 0 for numeric pnames and still
    // rejects unknown pnames with INVALID_ENUM. Linked programs go
    // through the normal resource-table path.
    const bool isLinked = prog->linked;
    const auto* table = isLinked ? getResourceTable(*prog, programInterface) : nullptr;
    // Validate programInterface enum even if not linked (unknown
    // interfaces should still raise INVALID_ENUM). The accepted set
    // mirrors getResourceTable.
    if (!isLinked) {
        switch (programInterface) {
            case GL_UNIFORM:
            case GL_UNIFORM_BLOCK:
            case GL_PROGRAM_INPUT:
            case GL_PROGRAM_OUTPUT:
            case GL_SHADER_STORAGE_BLOCK:
            case GL_ATOMIC_COUNTER_BUFFER:
            case GL_BUFFER_VARIABLE:
            case GL_TRANSFORM_FEEDBACK_VARYING:
            case GL_TRANSFORM_FEEDBACK_BUFFER:
            case GL_VERTEX_SUBROUTINE:
            case GL_TESS_CONTROL_SUBROUTINE:
            case GL_TESS_EVALUATION_SUBROUTINE:
            case GL_GEOMETRY_SUBROUTINE:
            case GL_FRAGMENT_SUBROUTINE:
            case GL_COMPUTE_SUBROUTINE:
            case GL_VERTEX_SUBROUTINE_UNIFORM:
            case GL_TESS_CONTROL_SUBROUTINE_UNIFORM:
            case GL_TESS_EVALUATION_SUBROUTINE_UNIFORM:
            case GL_GEOMETRY_SUBROUTINE_UNIFORM:
            case GL_FRAGMENT_SUBROUTINE_UNIFORM:
            case GL_COMPUTE_SUBROUTINE_UNIFORM:
                break;
            default:
                pushError(GL_INVALID_ENUM);
                return false;
        }
    } else if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    switch (pname) {
        case GL_ACTIVE_RESOURCES:
            *params = isLinked ? static_cast<GLint>(table->size()) : 0;
            return true;
        case GL_MAX_NAME_LENGTH: {
            if (!isLinked) {
                *params = 0;
                return true;
            }
            GLint maxLen = 0;
            for (const auto& entry : *table) {
                GLint len = static_cast<GLint>(entry.name.size() + 1);
                if (len > maxLen) maxLen = len;
            }
            *params = maxLen;
            return true;
        }
        case GL_MAX_NUM_ACTIVE_VARIABLES:
            // GL 4.6 §7.3.1 table: this pname is only valid on
            // the interfaces that expose an active-variables
            // list (UNIFORM_BLOCK, ATOMIC_COUNTER_BUFFER,
            // SHADER_STORAGE_BLOCK, TRANSFORM_FEEDBACK_BUFFER).
            // CTS `program_interface_query.invalid-operation`
            // passes GL_PROGRAM_INPUT and expects
            // INVALID_OPERATION. Value is max of activeVariables
            // counts across all block entries on the interface.
            switch (programInterface) {
                case GL_UNIFORM_BLOCK:
                case GL_ATOMIC_COUNTER_BUFFER:
                case GL_SHADER_STORAGE_BLOCK:
                case GL_TRANSFORM_FEEDBACK_BUFFER: {
                    GLint maxN = 0;
                    if (table != nullptr) {
                        for (const auto& entry : *table) {
                            GLint n = static_cast<GLint>(entry.activeVariables.size());
                            if (n > maxN) maxN = n;
                        }
                    }
                    *params = maxN;
                    return true;
                }
                default:
                    pushError(GL_INVALID_OPERATION);
                    return false;
            }
        case GL_MAX_NUM_COMPATIBLE_SUBROUTINES:
            // GL 4.6 §7.3.1: only valid on the *_SUBROUTINE_UNIFORM
            // interfaces. Value = max(count of compatible subroutines
            // across all subroutine uniforms on this interface).
            switch (programInterface) {
                case GL_VERTEX_SUBROUTINE_UNIFORM:
                case GL_TESS_CONTROL_SUBROUTINE_UNIFORM:
                case GL_TESS_EVALUATION_SUBROUTINE_UNIFORM:
                case GL_GEOMETRY_SUBROUTINE_UNIFORM:
                case GL_FRAGMENT_SUBROUTINE_UNIFORM:
                case GL_COMPUTE_SUBROUTINE_UNIFORM: {
                    GLint maxN = 0;
                    if (table != nullptr) {
                        for (const auto& e : *table) {
                            GLint n = static_cast<GLint>(e.activeVariables.size());
                            if (n > maxN) maxN = n;
                        }
                    }
                    *params = maxN;
                    return true;
                }
                default:
                    pushError(GL_INVALID_OPERATION);
                    return false;
            }
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getProgramResourceiv(GLuint program, GLenum programInterface, GLuint index, GLsizei propCount, const GLenum* props, GLsizei count, GLsizei* length, GLint* params) {
    // Always defensively-zero the caller's length output first. CTS tests
    // (e.g. program_interface_query.subroutines-vertex) declare
    // `GLsizei length` uninitialized on the stack, call us with the
    // address, and then use `length` as a for-loop bound — if we return
    // without writing it, the loop runs against stack garbage and reads
    // past the end of its `param[1000]` buffer, producing a deterministic
    // SIGBUS once the stack happens to carry a large value at that offset
    // (observed at test #12648 of a full CTS sweep).
    if (length != nullptr) {
        *length = 0;
    }
    // GL 4.6 §7.3.1: propCount > 0 is required; propCount <= 0 is
    // INVALID_VALUE. But `count` (bufSize) of 0 or a NULL `params`
    // is valid — "no data is written." CTS
    // `program_interface_query.buff-length` calls with count=0 and
    // expects no error + no writes (we'd previously push
    // INVALID_VALUE and scribble `length` = 0 which is itself fine).
    if (propCount <= 0 || props == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // `count` < 0 is explicitly invalid per §7.3.1. CTS
    // `program_interface_query.invalid-value` passes -100 and expects
    // INVALID_VALUE.
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        // Shader-name-vs-unknown-name: same rule as
        // getProgramResourceIndex.
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return false;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §7.3.1 lists the valid prop enums for
    // getProgramResourceiv. Anything outside this set yields
    // GL_INVALID_ENUM. CTS `program_interface_query.invalid-enum`
    // passes `GL_TEXTURE_1D` as a prop and expects the error.
    auto isValidProp = [](GLenum p) {
        switch (p) {
            case GL_ACTIVE_VARIABLES:
            case GL_BUFFER_BINDING:
            case GL_BUFFER_DATA_SIZE:
            case GL_NUM_ACTIVE_VARIABLES:
            case GL_ARRAY_SIZE:
            case GL_ARRAY_STRIDE:
            case GL_BLOCK_INDEX:
            case GL_IS_ROW_MAJOR:
            case GL_MATRIX_STRIDE:
            case GL_ATOMIC_COUNTER_BUFFER_INDEX:
            case GL_NUM_COMPATIBLE_SUBROUTINES:
            case GL_COMPATIBLE_SUBROUTINES:
            case GL_IS_PER_PATCH:
            case GL_LOCATION:
            case GL_LOCATION_COMPONENT:
            case GL_LOCATION_INDEX:
            case GL_NAME_LENGTH:
            case GL_OFFSET:
            case GL_REFERENCED_BY_VERTEX_SHADER:
            case GL_REFERENCED_BY_TESS_CONTROL_SHADER:
            case GL_REFERENCED_BY_TESS_EVALUATION_SHADER:
            case GL_REFERENCED_BY_GEOMETRY_SHADER:
            case GL_REFERENCED_BY_FRAGMENT_SHADER:
            case GL_REFERENCED_BY_COMPUTE_SHADER:
            case GL_TOP_LEVEL_ARRAY_SIZE:
            case GL_TOP_LEVEL_ARRAY_STRIDE:
            case GL_TRANSFORM_FEEDBACK_BUFFER_INDEX:
            case GL_TRANSFORM_FEEDBACK_BUFFER_STRIDE:
            case GL_TYPE:
                return true;
            default:
                return false;
        }
    };
    for (GLsizei i = 0; i < propCount; ++i) {
        if (!isValidProp(props[i])) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
    }
    // GL 4.6 §7.3.1 table: each prop is only valid on a subset of
    // interfaces. Using a prop that doesn't apply to the queried
    // interface yields INVALID_OPERATION. Only the most common
    // incompatibilities are enforced here; the full matrix would
    // add ~30 cases. CTS
    // `program_interface_query.invalid-operation` Case 3 passes
    // GL_OFFSET to GL_PROGRAM_INPUT — spec says that's an
    // INVALID_OPERATION.
    auto propInterfaceCompatible = [](GLenum prop, GLenum iface) {
        switch (prop) {
            case GL_OFFSET:
            case GL_BLOCK_INDEX:
            case GL_ARRAY_STRIDE:
            case GL_MATRIX_STRIDE:
            case GL_IS_ROW_MAJOR:
            case GL_ATOMIC_COUNTER_BUFFER_INDEX:
                return iface == GL_UNIFORM || iface == GL_BUFFER_VARIABLE
                    || iface == GL_TRANSFORM_FEEDBACK_VARYING;
            case GL_TOP_LEVEL_ARRAY_SIZE:
            case GL_TOP_LEVEL_ARRAY_STRIDE:
                return iface == GL_BUFFER_VARIABLE;
            case GL_BUFFER_BINDING:
            case GL_BUFFER_DATA_SIZE:
            case GL_NUM_ACTIVE_VARIABLES:
            case GL_ACTIVE_VARIABLES:
                return iface == GL_UNIFORM_BLOCK
                    || iface == GL_ATOMIC_COUNTER_BUFFER
                    || iface == GL_SHADER_STORAGE_BLOCK
                    || iface == GL_TRANSFORM_FEEDBACK_BUFFER;
            case GL_TRANSFORM_FEEDBACK_BUFFER_INDEX:
            case GL_TRANSFORM_FEEDBACK_BUFFER_STRIDE:
                return iface == GL_TRANSFORM_FEEDBACK_VARYING
                    || iface == GL_TRANSFORM_FEEDBACK_BUFFER;
            case GL_LOCATION_INDEX:
                return iface == GL_PROGRAM_OUTPUT;
            case GL_IS_PER_PATCH:
                return iface == GL_PROGRAM_INPUT || iface == GL_PROGRAM_OUTPUT;
            case GL_LOCATION:
            case GL_LOCATION_COMPONENT:
                return iface == GL_UNIFORM
                    || iface == GL_PROGRAM_INPUT
                    || iface == GL_PROGRAM_OUTPUT
                    || iface == GL_VERTEX_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_CONTROL_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_EVALUATION_SUBROUTINE_UNIFORM
                    || iface == GL_GEOMETRY_SUBROUTINE_UNIFORM
                    || iface == GL_FRAGMENT_SUBROUTINE_UNIFORM
                    || iface == GL_COMPUTE_SUBROUTINE_UNIFORM;
            case GL_NUM_COMPATIBLE_SUBROUTINES:
            case GL_COMPATIBLE_SUBROUTINES:
                return iface == GL_VERTEX_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_CONTROL_SUBROUTINE_UNIFORM
                    || iface == GL_TESS_EVALUATION_SUBROUTINE_UNIFORM
                    || iface == GL_GEOMETRY_SUBROUTINE_UNIFORM
                    || iface == GL_FRAGMENT_SUBROUTINE_UNIFORM
                    || iface == GL_COMPUTE_SUBROUTINE_UNIFORM;
            default:
                // GL_NAME_LENGTH / GL_TYPE / GL_ARRAY_SIZE /
                // GL_REFERENCED_BY_* apply broadly — accept.
                return true;
        }
    };
    for (GLsizei i = 0; i < propCount; ++i) {
        if (!propInterfaceCompatible(props[i], programInterface)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
    }
    if (index >= table->size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const auto& entry = (*table)[index];
    GLsizei written = 0;
    if (params != nullptr) {
        for (GLsizei i = 0; i < propCount && written < count; ++i) {
            // GL 4.6 §7.3.1: GL_ACTIVE_VARIABLES and
            // GL_COMPATIBLE_SUBROUTINES both write an ARRAY of
            // integers — the next NUM_ACTIVE_VARIABLES (or
            // NUM_COMPATIBLE_SUBROUTINES) slots, one per active
            // member. Every other prop writes a single integer.
            // CTS `program_interface_query.atomic-counters` reads
            // NUM_ACTIVE_VARIABLES via a separate call, then
            // reads the full ACTIVE_VARIABLES list with bufSize
            // large enough to hold all N entries; we must write
            // them all, not just the first.
            if (props[i] == GL_ACTIVE_VARIABLES ||
                props[i] == GL_COMPATIBLE_SUBROUTINES) {
                // GL_COMPATIBLE_SUBROUTINES uses the same
                // activeVariables vector on subroutine-uniform entries,
                // so share the multi-value path.
                for (GLint idx : entry.activeVariables) {
                    if (written >= count) break;
                    params[written++] = idx;
                }
                continue;
            }
            params[written++] = getResourceProperty(entry, props[i]);
        }
    }
    if (length != nullptr) {
        *length = written;
    }
    return true;
}

bool GLContext::getProgramResourceName(GLuint program, GLenum programInterface, GLuint index, GLsizei bufSize, GLsizei* length, GLchar* name) {
    // Defensively zero length first (see getProgramResourceiv for rationale).
    if (length != nullptr) {
        *length = 0;
    }
    // GL 4.6 §7.3.1: `bufSize` < 0 is invalid. CTS
    // `program_interface_query.invalid-value` passes -100 and expects
    // INVALID_VALUE.
    if (bufSize < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §7.3.1: `GL_ATOMIC_COUNTER_BUFFER` /
    // `GL_TRANSFORM_FEEDBACK_BUFFER` buffers carry no names; queries
    // generate INVALID_ENUM.
    if (programInterface == GL_ATOMIC_COUNTER_BUFFER ||
        programInterface == GL_TRANSFORM_FEEDBACK_BUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return false;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (index >= table->size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const auto& entry = (*table)[index];
    if (name != nullptr && bufSize > 0) {
        std::size_t toCopy = std::min(static_cast<std::size_t>(bufSize - 1), entry.name.size());
        std::memcpy(name, entry.name.c_str(), toCopy);
        name[toCopy] = '\0';
        if (length != nullptr) {
            *length = static_cast<GLsizei>(toCopy);
        }
    } else if (length != nullptr) {
        *length = 0;
    }
    return true;
}

GLuint GLContext::getProgramResourceIndex(GLuint program, GLenum programInterface, const GLchar* name) {
    if (name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return GL_INVALID_INDEX;
    }
    // GL 4.6 §7.3.1: `GL_ATOMIC_COUNTER_BUFFER` buffers have no
    // names, so this entry point is invalid on that interface.
    // `GL_TRANSFORM_FEEDBACK_BUFFER` is similarly unnamed.
    if (programInterface == GL_ATOMIC_COUNTER_BUFFER ||
        programInterface == GL_TRANSFORM_FEEDBACK_BUFFER) {
        pushError(GL_INVALID_ENUM);
        return GL_INVALID_INDEX;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        // GL 4.6 §7.3.1 differentiates "name refers to a shader
        // object (INVALID_OPERATION)" from "name is not a generated
        // program name (INVALID_VALUE)". Distinguish here by
        // checking the shader table. CTS
        // `program_interface_query.invalid-operation` calls these
        // entry points with a shader name and expects the specific
        // INVALID_OPERATION error.
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return GL_INVALID_INDEX;
    }
    // Unlinked program: silently return INVALID_INDEX (no match).
    // CTS empty-shaders queries resource indices on an unlinked
    // program and asserts no error is raised; strict
    // INVALID_OPERATION makes that subcase fail.
    if (!prog->linked) {
        return GL_INVALID_INDEX;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        pushError(GL_INVALID_ENUM);
        return GL_INVALID_INDEX;
    }
    // GL 4.6 §7.3.1.1: `glGetProgramResourceIndex` cannot be used to
    // retrieve the index of the built-in transform-feedback markers
    // (`gl_NextBuffer` / `gl_SkipComponentsN`). They still appear in
    // the resource table and can be walked by index via
    // `glGetProgramResourceName`, but lookup-by-name returns
    // INVALID_INDEX. CTS
    // `program_interface_query.transform-feedback-built-in` verifies.
    if (programInterface == GL_TRANSFORM_FEEDBACK_VARYING) {
        const std::string q = name;
        if (q == "gl_NextBuffer" ||
            (q.size() == 18 && q.compare(0, 17, "gl_SkipComponents") == 0)) {
            return GL_INVALID_INDEX;
        }
    }
    for (std::size_t i = 0; i < table->size(); ++i) {
        if ((*table)[i].name == name) {
            return static_cast<GLuint>(i);
        }
    }
    // Array-input lookup tolerance: GL 4.6 §7.3.1 says
    // getProgramResourceIndex("arr") should find the same entry as
    // "arr[0]" for an array input, and vice versa. Table entries
    // follow the "[0]"-suffixed convention for arrays
    // (`c` → "c[0]"); queries with bare base name should still
    // match. CTS `program_interface_query.input-types` queries
    // "d" where the table stores "d[0]".
    const std::string query = name;
    // Bare query → find a "<name>[0]" entry.
    {
        const std::string suffixed = query + "[0]";
        for (std::size_t i = 0; i < table->size(); ++i) {
            if ((*table)[i].name == suffixed) {
                return static_cast<GLuint>(i);
            }
        }
    }
    // "<base>[0]"-suffixed query → find a bare "<base>" entry.
    if (query.size() >= 3 && query.compare(query.size() - 3, 3, "[0]") == 0) {
        const std::string baseOnly = query.substr(0, query.size() - 3);
        for (std::size_t i = 0; i < table->size(); ++i) {
            if ((*table)[i].name == baseOnly) {
                return static_cast<GLuint>(i);
            }
        }
    }
    return GL_INVALID_INDEX;
}

GLint GLContext::getProgramResourceLocation(GLuint program, GLenum programInterface, const GLchar* name) {
    if (name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return -1;
    }
    // GL 4.6 §7.3.1 valid interfaces: UNIFORM, PROGRAM_INPUT,
    // PROGRAM_OUTPUT, and the six *_SUBROUTINE_UNIFORM interfaces.
    // The last set lets CTS `subroutines-*` query the subroutine
    // uniform's location via `glGetProgramResourceLocation` (same
    // value `glGetSubroutineUniformLocation` returns).
    if (programInterface != GL_UNIFORM && programInterface != GL_PROGRAM_INPUT &&
        programInterface != GL_PROGRAM_OUTPUT &&
        programInterface != GL_VERTEX_SUBROUTINE_UNIFORM &&
        programInterface != GL_TESS_CONTROL_SUBROUTINE_UNIFORM &&
        programInterface != GL_TESS_EVALUATION_SUBROUTINE_UNIFORM &&
        programInterface != GL_GEOMETRY_SUBROUTINE_UNIFORM &&
        programInterface != GL_FRAGMENT_SUBROUTINE_UNIFORM &&
        programInterface != GL_COMPUTE_SUBROUTINE_UNIFORM) {
        pushError(GL_INVALID_ENUM);
        return -1;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return -1;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return -1;
    }
    const auto* table = getResourceTable(*prog, programInterface);
    if (table == nullptr) {
        return -1;
    }
    const std::string lookup = name;
    // Direct match — but skip entries with location=-1. SPIRV-Cross
    // reflection sometimes emits both "u0" (the real base with valid
    // location) and "u0[0]" (a per-element duplicate that was never
    // assigned a location). Without the -1 guard the direct match
    // would hit the duplicate first and short-circuit to -1.
    for (const auto& entry : *table) {
        if (entry.name == lookup && entry.location >= 0) {
            return entry.location;
        }
    }
    // Array-element lookup parity with getUniformLocation: "u[k]"
    // resolves to location(u) + k when u is declared as an array of
    // size > k. GL 4.6 §7.3.1 says both entry points return the same
    // thing for the same name — including array subscript syntax.
    // Entries in the resource table may be stored under either a
    // bare base name ("u") or a "[0]"-suffixed canonical form ("u[0]"
    // for arrays — GL 4.6 §7.3.1 mandate). Match both shapes here.
    auto stripBracketZero = [](const std::string& n) -> std::string {
        if (n.size() >= 3 && n.compare(n.size() - 3, 3, "[0]") == 0) {
            return n.substr(0, n.size() - 3);
        }
        return n;
    };
    // GL 4.6 §7.3.1 (spec for array-subscript names in uniform /
    // resource lookups): only strictly-formatted decimal integers
    // are accepted. Rejected forms: leading/trailing whitespace
    // (`"a[ 0]"`, `"a[0 ]"`), embedded whitespace or arithmetic
    // (`"a[0 + 0]"`, `"a[0+0]"`), alternate whitespace
    // (`"a[\t0]"`, `"a[\n0]"`), leading zero (`"a[01]"`,
    // `"a[00]"`). strtol alone accepts all of these; we pre-validate
    // by scanning the index substring.
    auto isStrictNonNegIndex = [](const std::string& s, long& out) {
        if (s.empty()) return false;
        if (s[0] == '0' && s.size() > 1) return false;   // leading zero
        for (char c : s) {
            if (c < '0' || c > '9') return false;
        }
        // strtol is safe now — string is non-empty digits only.
        char* endp = nullptr;
        out = std::strtol(s.c_str(), &endp, 10);
        return out >= 0;
    };
    const auto openBracket = lookup.find('[');
    if (openBracket != std::string::npos && !lookup.empty() && lookup.back() == ']') {
        const std::string baseName = lookup.substr(0, openBracket);
        const std::string indexStr = lookup.substr(openBracket + 1, lookup.size() - openBracket - 2);
        long idx = 0;
        if (!baseName.empty() && isStrictNonNegIndex(indexStr, idx)) {
            for (const auto& entry : *table) {
                if (stripBracketZero(entry.name) == baseName && entry.arraySize >= 1
                    && idx < static_cast<long>(entry.arraySize)
                    && entry.location >= 0) {
                    return entry.location + static_cast<GLint>(idx);
                }
            }
        }
    }
    // Bare base-name lookup against a "[0]"-suffixed entry: GL 4.6
    // §7.3.1 says `getProgramResourceLocation("arr")` equals
    // `getProgramResourceLocation("arr[0]")` for array inputs.
    for (const auto& entry : *table) {
        if (stripBracketZero(entry.name) == lookup && entry.location >= 0) {
            return entry.location;
        }
    }
    return -1;
}

GLint GLContext::getProgramResourceLocationIndex(GLuint program, GLenum programInterface, const GLchar* name) {
    if (name == nullptr) {
        pushError(GL_INVALID_VALUE);
        return -1;
    }
    if (programInterface != GL_PROGRAM_OUTPUT) {
        pushError(GL_INVALID_ENUM);
        return -1;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr) {
        if (impl_->objects->shaders().contains(program)) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return -1;
    }
    if (!prog->linked) {
        pushError(GL_INVALID_OPERATION);
        return -1;
    }
    // Fragment output location index (dual-source blending) —
    // comes from `glBindFragDataLocationIndexed`'s `index` arg
    // (0 = primary, 1 = second source). Stored on the entry.
    // Array outputs canonicalised to "<name>[0]" per GL 4.6
    // §7.3.1 — match both bare and suffixed query shapes.
    // Built-in outputs (no user location, e.g. gl_FragDepth)
    // report LOCATION_INDEX = -1 per CTS
    // `output-built-in` expectations.
    auto indexFor = [](const GLProgramResourceEntry& e) {
        return e.location < 0 ? -1 : e.locationIndex;
    };
    const std::string query = name;
    for (const auto& entry : prog->resourceOutputs) {
        if (entry.name == query) return indexFor(entry);
    }
    for (const auto& entry : prog->resourceOutputs) {
        if (entry.name == query + "[0]") return indexFor(entry);
    }
    if (query.size() >= 3 && query.compare(query.size() - 3, 3, "[0]") == 0) {
        const std::string baseOnly = query.substr(0, query.size() - 3);
        for (const auto& entry : prog->resourceOutputs) {
            if (entry.name == baseOnly) return indexFor(entry);
        }
    }
    return -1;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Shader Storage Block Binding
// ---------------------------------------------------------------------------

bool GLContext::shaderStorageBlockBinding(GLuint program, GLuint storageBlockIndex, GLuint storageBlockBinding) {
    // GL 4.3 §7.6.1: INVALID_OPERATION when `program` names a
    // shader (not a program). Must run before the programs().get()
    // null-fallback or we'd return INVALID_VALUE instead.
    if (impl_->objects->shaders().get(program) != nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLProgramObject* prog = impl_->objects->programs().get(program);
    if (prog == nullptr || !prog->linked) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (storageBlockIndex >= prog->resourceStorageBlocks.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.3 §7.6.1: storageBlockBinding must be less than
    // GL_MAX_SHADER_STORAGE_BUFFER_BINDINGS. CTS
    // `shader_storage_buffer_object.negative-api-blockBinding`
    // plants `binding = MAX_BINDINGS` and expects INVALID_VALUE.
    {
        GLint maxBindings = 8;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(GL_MAX_SHADER_STORAGE_BUFFER_BINDINGS, &maxBindings);
        }
        if (storageBlockBinding >= static_cast<GLuint>(maxBindings)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
    }
    prog->ssboBindingRemap[storageBlockIndex] = storageBlockBinding;
    // Also update the resource entry's location field so queries reflect the remap.
    prog->resourceStorageBlocks[storageBlockIndex].location = static_cast<GLint>(storageBlockBinding);
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Advanced Instanced Drawing with Base Instance
// ---------------------------------------------------------------------------

bool GLContext::drawArraysInstancedBaseInstance(GLenum mode, GLint first, GLsizei count, GLsizei instancecount, GLuint baseinstance) {
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true; // valid no-op
    }
    // Delegate to the instanced path; baseinstance is threaded through the
    // TranslatedDrawInfo for Metal's baseInstance parameter.
    // For now, we ignore baseinstance (it requires MTLGPUFamily Apple3+ to use
    // non-zero base instance). The basic instanced draw still works.
    return drawArraysInstanced(mode, first, count, instancecount);
}

bool GLContext::drawElementsInstancedBaseInstance(GLenum mode, GLsizei count, GLenum type, const void* indices, GLsizei instancecount, GLuint baseinstance) {
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_UNSIGNED_BYTE && type != GL_UNSIGNED_SHORT && type != GL_UNSIGNED_INT) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    // Delegate to the instanced+baseVertex path; baseinstance is ignored for now
    // (requires MTLGPUFamily Apple3+ for non-zero base instance).
    return drawElementsInstancedBaseVertex(mode, count, type, indices, instancecount, 0);
}

bool GLContext::drawElementsInstancedBaseVertexBaseInstance(GLenum mode, GLsizei count, GLenum type, const void* indices, GLsizei instancecount, GLint basevertex, GLuint baseinstance) {
    if (count < 0 || instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_UNSIGNED_BYTE && type != GL_UNSIGNED_SHORT && type != GL_UNSIGNED_INT) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count == 0 || instancecount == 0) {
        return true;
    }
    // Delegate to the instanced+baseVertex path; baseinstance is ignored for now
    // (requires MTLGPUFamily Apple3+ for non-zero base instance).
    return drawElementsInstancedBaseVertex(mode, count, type, indices, instancecount, basevertex);
}

// ---------------------------------------------------------------------------
// GL 4.0/4.3 — Indirect Draw Helpers
// ---------------------------------------------------------------------------

GLuint GLContext::getBoundVertexArray() const {
    return impl_->state->boundVertexArray();
}

bool GLContext::readIndirectBuffer(GLenum target, const void* indirect, std::size_t size, void* out) {
    const GLuint bufName = impl_->state->boundBuffer(target);
    if (bufName != 0) {
        // `indirect` is a byte offset into the bound buffer.
        const auto offset = reinterpret_cast<uintptr_t>(indirect);
        GLBufferObject* buf = impl_->objects->buffers().get(bufName);
        if (buf == nullptr || !buf->instantiated) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        if (offset + size > static_cast<std::size_t>(buf->size)) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        if (buf->shadowBytes.size() >= offset + size) {
            std::memcpy(out, buf->shadowBytes.data() + offset, size);
        } else {
            // Shadow copy not available — zero-fill as a safe fallback.
            std::memset(out, 0, size);
        }
    } else {
        // No buffer bound — `indirect` is a client pointer.
        if (indirect == nullptr) {
            pushError(GL_INVALID_OPERATION);
            return false;
        }
        std::memcpy(out, indirect, size);
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Multi-Draw Indirect
// ---------------------------------------------------------------------------

bool GLContext::multiDrawArraysIndirect(GLenum mode, const void* indirect, GLsizei drawcount, GLsizei stride) {
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (stride != 0 && stride < 16) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Core profile: drawing with default VAO (0) is INVALID_OPERATION.
    if (impl_->state->boundVertexArray() == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Offset into the indirect buffer must be 4-byte aligned.
    if (reinterpret_cast<uintptr_t>(indirect) % 4 != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // DrawArraysIndirectCommand layout: { count, instanceCount, first, baseInstance }
    struct DrawArraysIndirectCommand {
        GLuint count;
        GLuint instanceCount;
        GLuint first;
        GLuint baseInstance;
    };
    const GLsizei effectiveStride = (stride == 0) ? static_cast<GLsizei>(sizeof(DrawArraysIndirectCommand)) : stride;

    // GL 4.6 §10.5: pre-validate the indirect-buffer range. See
    // multiDrawElementsIndirect for the full rationale — the check
    // must fire BEFORE any sub-draw so we don't push a cascade of
    // per-draw errors when the buffer has stack-garbage trailer bytes.
    if (drawcount > 0) {
        const GLuint indirectBuf = impl_->state->boundBuffer(GL_DRAW_INDIRECT_BUFFER);
        if (indirectBuf != 0) {
            GLBufferObject* bo = impl_->objects->buffers().get(indirectBuf);
            if (bo != nullptr) {
                const uintptr_t endOffset =
                    reinterpret_cast<uintptr_t>(indirect) +
                    static_cast<uintptr_t>(drawcount) * static_cast<uintptr_t>(effectiveStride);
                if (endOffset > static_cast<uintptr_t>(bo->size)) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
            }
        }
    }
    for (GLsizei i = 0; i < drawcount; ++i) {
        const void* cmdPtr = reinterpret_cast<const void*>(
            reinterpret_cast<uintptr_t>(indirect) + static_cast<uintptr_t>(i) * static_cast<uintptr_t>(effectiveStride));
        DrawArraysIndirectCommand cmd{};
        if (!readIndirectBuffer(GL_DRAW_INDIRECT_BUFFER, cmdPtr, sizeof(cmd), &cmd)) {
            return false;
        }
        if (cmd.count == 0 || cmd.instanceCount == 0) {
            continue;  // valid no-op for this sub-draw
        }
        drawArraysInstancedBaseInstance(mode, static_cast<GLint>(cmd.first),
                                        static_cast<GLsizei>(cmd.count),
                                        static_cast<GLsizei>(cmd.instanceCount),
                                        cmd.baseInstance);
    }
    return true;
}

bool GLContext::multiDrawElementsIndirect(GLenum mode, GLenum type, const void* indirect, GLsizei drawcount, GLsizei stride) {
    if (drawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (type != GL_UNSIGNED_BYTE && type != GL_UNSIGNED_SHORT && type != GL_UNSIGNED_INT) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (stride != 0 && stride < 20) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Core profile: drawing with default VAO (0) is INVALID_OPERATION.
    if (impl_->state->boundVertexArray() == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Offset into the indirect buffer must be 4-byte aligned.
    if (reinterpret_cast<uintptr_t>(indirect) % 4 != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // DrawElementsIndirectCommand layout: { count, instanceCount, firstIndex, baseVertex, baseInstance }
    struct DrawElementsIndirectCommand {
        GLuint count;
        GLuint instanceCount;
        GLuint firstIndex;
        GLuint baseVertex;
        GLuint baseInstance;
    };
    const GLsizei effectiveStride = (stride == 0) ? static_cast<GLsizei>(sizeof(DrawElementsIndirectCommand)) : stride;
    const GLsizei indexSize = (type == GL_UNSIGNED_INT) ? 4 : (type == GL_UNSIGNED_SHORT) ? 2 : 1;

    // GL 4.6 §10.5: the INVALID_OPERATION check for "reading beyond
    // the end of the draw-indirect buffer" must fire BEFORE any
    // sub-draw is issued. Otherwise a partial loop can push a
    // cascade of per-draw errors (e.g. a garbage cmd at i=N-1
    // followed by the OOB at i=N), leaving the error queue with
    // more than one entry and breaking spec-exact error tests.
    if (drawcount > 0) {
        const GLuint indirectBuf = impl_->state->boundBuffer(GL_DRAW_INDIRECT_BUFFER);
        if (indirectBuf != 0) {
            GLBufferObject* bo = impl_->objects->buffers().get(indirectBuf);
            if (bo != nullptr) {
                const uintptr_t endOffset =
                    reinterpret_cast<uintptr_t>(indirect) +
                    static_cast<uintptr_t>(drawcount) * static_cast<uintptr_t>(effectiveStride);
                if (endOffset > static_cast<uintptr_t>(bo->size)) {
                    pushError(GL_INVALID_OPERATION);
                    return false;
                }
            }
        }
    }
    for (GLsizei i = 0; i < drawcount; ++i) {
        const void* cmdPtr = reinterpret_cast<const void*>(
            reinterpret_cast<uintptr_t>(indirect) + static_cast<uintptr_t>(i) * static_cast<uintptr_t>(effectiveStride));
        DrawElementsIndirectCommand cmd{};
        if (!readIndirectBuffer(GL_DRAW_INDIRECT_BUFFER, cmdPtr, sizeof(cmd), &cmd)) {
            return false;
        }
        if (cmd.count == 0 || cmd.instanceCount == 0) {
            continue;
        }
        const void* indexOffset = reinterpret_cast<const void*>(
            static_cast<uintptr_t>(cmd.firstIndex) * static_cast<uintptr_t>(indexSize));
        drawElementsInstancedBaseVertexBaseInstance(mode,
            static_cast<GLsizei>(cmd.count), type, indexOffset,
            static_cast<GLsizei>(cmd.instanceCount),
            static_cast<GLint>(cmd.baseVertex),
            cmd.baseInstance);
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Buffer Clear
// ---------------------------------------------------------------------------

// Figure out the width-in-bytes of the clear-data tuple for glClearBuffer*.
// Spec §6.6: the pattern is `N` bytes where N is the data size of the
// (format, type) pair — e.g. GL_R8 + GL_RED + GL_UNSIGNED_BYTE is 1 byte,
// GL_RGBA8 + GL_RGBA + GL_UNSIGNED_BYTE is 4 bytes, GL_RG32F + GL_RG +
// GL_FLOAT is 8 bytes. Caller replicates the pattern for every element.
static std::size_t bufferClearPatternBytes(GLenum format, GLenum type) {
    std::size_t components = 1;
    switch (format) {
        case GL_RED: case GL_RED_INTEGER: case GL_GREEN: case GL_BLUE:
        case GL_GREEN_INTEGER: case GL_BLUE_INTEGER: components = 1; break;
        case GL_RG: case GL_RG_INTEGER: components = 2; break;
        case GL_RGB: case GL_BGR: case GL_RGB_INTEGER: case GL_BGR_INTEGER: components = 3; break;
        case GL_RGBA: case GL_BGRA: case GL_RGBA_INTEGER: case GL_BGRA_INTEGER: components = 4; break;
        case GL_DEPTH_COMPONENT: components = 1; break;
        case GL_STENCIL_INDEX: components = 1; break;
        default: components = 1; break;
    }
    std::size_t bytesPerComponent = 1;
    switch (type) {
        case GL_UNSIGNED_BYTE: case GL_BYTE: bytesPerComponent = 1; break;
        case GL_UNSIGNED_SHORT: case GL_SHORT: case GL_HALF_FLOAT: bytesPerComponent = 2; break;
        case GL_UNSIGNED_INT: case GL_INT: case GL_FLOAT: bytesPerComponent = 4; break;
        // Packed types: one packed element covers all components.
        case GL_UNSIGNED_BYTE_3_3_2:
        case GL_UNSIGNED_BYTE_2_3_3_REV: return 1;
        case GL_UNSIGNED_SHORT_5_6_5:
        case GL_UNSIGNED_SHORT_5_6_5_REV:
        case GL_UNSIGNED_SHORT_4_4_4_4:
        case GL_UNSIGNED_SHORT_4_4_4_4_REV:
        case GL_UNSIGNED_SHORT_5_5_5_1:
        case GL_UNSIGNED_SHORT_1_5_5_5_REV: return 2;
        case GL_UNSIGNED_INT_8_8_8_8:
        case GL_UNSIGNED_INT_8_8_8_8_REV:
        case GL_UNSIGNED_INT_10_10_10_2:
        case GL_UNSIGNED_INT_2_10_10_10_REV:
        case GL_UNSIGNED_INT_10F_11F_11F_REV:
        case GL_UNSIGNED_INT_5_9_9_9_REV: return 4;
        default: bytesPerComponent = 4; break;
    }
    return components * bytesPerComponent;
}

// Apply a clear pattern to the buffer's shadow AND to its Metal buffer
// (when present). GL 4.6 §6.6 treats the (format, type) tuple as a single
// pattern element whose width determines the replication stride. Prior
// implementation hard-coded 4 bytes — that worked for RGBA8 but corrupted
// R8 / RG16F / etc., and also skipped the Metal-buffer sync so subsequent
// readPixels / map paths saw stale data.
static void fillBufferClearPattern(std::uint8_t* dst, std::size_t bytes,
                                    const void* data, std::size_t patternBytes) {
    if (patternBytes == 0) {
        std::memset(dst, 0, bytes);
        return;
    }
    if (data == nullptr) {
        std::memset(dst, 0, bytes);
        return;
    }
    for (std::size_t i = 0; i < bytes; i += patternBytes) {
        const std::size_t remaining = std::min(patternBytes, bytes - i);
        std::memcpy(dst + i, data, remaining);
    }
}

// GL 4.4 §6.7: valid sized internal formats for {Named,}BufferData
// clear operations. Accepting only the 32-enum subset the spec defines.
static bool isValidClearBufferInternalFormat(GLenum fmt) {
    switch (fmt) {
        case GL_R8: case GL_R16: case GL_R16F: case GL_R32F:
        case GL_R8I: case GL_R16I: case GL_R32I:
        case GL_R8UI: case GL_R16UI: case GL_R32UI:
        case GL_RG8: case GL_RG16: case GL_RG16F: case GL_RG32F:
        case GL_RG8I: case GL_RG16I: case GL_RG32I:
        case GL_RG8UI: case GL_RG16UI: case GL_RG32UI:
        case GL_RGB32F: case GL_RGB32I: case GL_RGB32UI:
        case GL_RGBA8: case GL_RGBA16: case GL_RGBA16F: case GL_RGBA32F:
        case GL_RGBA8I: case GL_RGBA16I: case GL_RGBA32I:
        case GL_RGBA8UI: case GL_RGBA16UI: case GL_RGBA32UI:
            return true;
        default:
            return false;
    }
}

// GL 4.4 §8.4: valid pixel-transfer format enum for clear-buffer ops.
static bool isValidClearBufferFormat(GLenum fmt) {
    switch (fmt) {
        case GL_RED: case GL_RG: case GL_RGB: case GL_BGR:
        case GL_RGBA: case GL_BGRA:
        case GL_RED_INTEGER: case GL_RG_INTEGER:
        case GL_RGB_INTEGER: case GL_BGR_INTEGER:
        case GL_RGBA_INTEGER: case GL_BGRA_INTEGER:
        case GL_STENCIL_INDEX: case GL_DEPTH_COMPONENT: case GL_DEPTH_STENCIL:
            return true;
        default:
            return false;
    }
}

// GL 4.4 §8.4.4: valid pixel-transfer type enum for clear-buffer ops.
// Note: the CTS buffers_errors test's error message lists the subset
// of types required by the spec's ValidateBufferData error handler,
// but the functional test (buffers_clear) additionally uses
// GL_HALF_FLOAT for clearing R16F / RGBA16F and similar. Include
// HALF_FLOAT so both paths agree.
static bool isValidClearBufferType(GLenum t) {
    switch (t) {
        case GL_UNSIGNED_BYTE: case GL_BYTE:
        case GL_UNSIGNED_SHORT: case GL_SHORT:
        case GL_UNSIGNED_INT: case GL_INT:
        case GL_HALF_FLOAT: case GL_FLOAT:
        case GL_UNSIGNED_BYTE_3_3_2: case GL_UNSIGNED_BYTE_2_3_3_REV:
        case GL_UNSIGNED_SHORT_5_6_5: case GL_UNSIGNED_SHORT_5_6_5_REV:
        case GL_UNSIGNED_SHORT_4_4_4_4: case GL_UNSIGNED_SHORT_4_4_4_4_REV:
        case GL_UNSIGNED_SHORT_5_5_5_1: case GL_UNSIGNED_SHORT_1_5_5_5_REV:
        case GL_UNSIGNED_INT_8_8_8_8: case GL_UNSIGNED_INT_8_8_8_8_REV:
        case GL_UNSIGNED_INT_10_10_10_2: case GL_UNSIGNED_INT_2_10_10_10_REV:
            return true;
        default:
            return false;
    }
}

bool GLContext::clearBufferData(GLenum target, GLenum internalformat, GLenum format, GLenum type, const void* data) {
    // GL 4.4 §6.7 validation — order matters; CTS
    // `direct_state_access.buffers_errors` asserts every condition.
    if (!isValidClearBufferInternalFormat(internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!isValidClearBufferFormat(format)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isValidClearBufferType(type)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLuint boundBuffer = impl_->state->boundBuffer(target);
    if (boundBuffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* buffer = impl_->objects->buffers().get(boundBuffer);
    if (buffer == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.7: INVALID_OPERATION when the buffer is mapped
    // without MAP_PERSISTENT_BIT.
    if (buffer->mapped && (buffer->mapAccessFlags & GL_MAP_PERSISTENT_BIT) == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (buffer->size == 0) {
        return true; // valid no-op
    }
    // Fill the shadow bytes with the clear value (or zero if data is null).
    if (buffer->shadowBytes.size() < static_cast<std::size_t>(buffer->size)) {
        buffer->shadowBytes.resize(static_cast<std::size_t>(buffer->size), 0);
    }
    const std::size_t patternBytes = bufferClearPatternBytes(format, type);
    fillBufferClearPattern(buffer->shadowBytes.data(), buffer->shadowBytes.size(),
                            data, patternBytes);
    // Sync into the Metal buffer so getBufferSubData / glMap paths see the
    // cleared pattern rather than whatever the Metal buffer previously held
    // (the readback helper prefers Metal contents when the object has a
    // Metal buffer backing it).
    id<MTLBuffer> metalBuffer = (__bridge id<MTLBuffer>)buffer->metalBuffer;
    if (metalBuffer != nil) {
        std::uint8_t* metalBytes = static_cast<std::uint8_t*>([metalBuffer contents]);
        if (metalBytes != nullptr) {
            fillBufferClearPattern(metalBytes, buffer->shadowBytes.size(),
                                    data, patternBytes);
        }
    }
    return true;
}

bool GLContext::clearBufferSubData(GLenum target, GLenum internalformat, GLintptr offset, GLsizeiptr size, GLenum format, GLenum type, const void* data) {
    // Same GL 4.4 §6.7 validation as clearBufferData plus range +
    // alignment constraints.
    if (!isValidClearBufferInternalFormat(internalformat)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (!isValidClearBufferFormat(format)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!isValidClearBufferType(type)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (offset < 0 || size < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.4 §6.7: offset and size must be multiples of the
    // internal-format byte size. CTS exercises `internalformat=RGBA8`
    // (= 4 bytes) with size=1 and asserts INVALID_VALUE.
    const std::size_t formatBytes = bufferClearPatternBytes(format, type);
    if (formatBytes > 0 &&
        ((offset % static_cast<GLintptr>(formatBytes)) != 0 ||
         (size % static_cast<GLsizeiptr>(formatBytes)) != 0)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLuint boundBuffer = impl_->state->boundBuffer(target);
    if (boundBuffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* buffer = impl_->objects->buffers().get(boundBuffer);
    if (buffer == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (buffer->mapped && (buffer->mapAccessFlags & GL_MAP_PERSISTENT_BIT) == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (offset + size > buffer->size) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (size == 0) {
        return true;
    }
    if (buffer->shadowBytes.size() < static_cast<std::size_t>(buffer->size)) {
        buffer->shadowBytes.resize(static_cast<std::size_t>(buffer->size), 0);
    }
    const std::size_t patternBytes = bufferClearPatternBytes(format, type);
    fillBufferClearPattern(buffer->shadowBytes.data() + offset,
                            static_cast<std::size_t>(size), data, patternBytes);
    id<MTLBuffer> metalBuffer = (__bridge id<MTLBuffer>)buffer->metalBuffer;
    if (metalBuffer != nil) {
        std::uint8_t* metalBytes = static_cast<std::uint8_t*>([metalBuffer contents]);
        if (metalBytes != nullptr) {
            fillBufferClearPattern(metalBytes + offset,
                                    static_cast<std::size_t>(size), data, patternBytes);
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Framebuffer Parameters
// ---------------------------------------------------------------------------

bool GLContext::framebufferParameteri(GLenum target, GLenum pname, GLint param) {
    if (target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER && target != GL_FRAMEBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §9.2.1: FramebufferParameteri operates on the user FBO
    // currently bound at `target`. The default FB (name = 0) rejects
    // every FRAMEBUFFER_DEFAULT_* pname with INVALID_OPERATION because
    // its defaults are fixed by the window system.
    const GLuint fbName = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    if (fbName == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLFramebufferObject* fb = impl_->objects->framebuffers().get(fbName);
    if (fb == nullptr || !fb->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Per-pname value-range guards. GL 4.6 §9.2.1 table 9.1: negative
    // widths/heights/layers/samples are INVALID_VALUE; upper bounds
    // match the matching implementation limits reported by caps.
    const auto rangeCheckCap = [&](GLenum capPname, GLint& storage) -> bool {
        GLint maxVal = 0;
        if (impl_->capabilities != nullptr) {
            impl_->capabilities->queryInteger(capPname, &maxVal);
        }
        if (param < 0 || (maxVal > 0 && param > maxVal)) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        storage = param;
        return true;
    };
    switch (pname) {
        case GL_FRAMEBUFFER_DEFAULT_WIDTH:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_WIDTH, fb->defaultWidth);
        case GL_FRAMEBUFFER_DEFAULT_HEIGHT:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_HEIGHT, fb->defaultHeight);
        case GL_FRAMEBUFFER_DEFAULT_LAYERS:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_LAYERS, fb->defaultLayers);
        case GL_FRAMEBUFFER_DEFAULT_SAMPLES:
            return rangeCheckCap(GL_MAX_FRAMEBUFFER_SAMPLES, fb->defaultSamples);
        case GL_FRAMEBUFFER_DEFAULT_FIXED_SAMPLE_LOCATIONS:
            fb->defaultFixedSampleLocations = param != 0 ? GL_TRUE : GL_FALSE;
            return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

bool GLContext::getFramebufferParameteriv(GLenum target, GLenum pname, GLint* params) {
    if (params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (target != GL_DRAW_FRAMEBUFFER && target != GL_READ_FRAMEBUFFER && target != GL_FRAMEBUFFER) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.6 §9.4: pname sets differ between the default framebuffer
    // and user FBOs. Routing DSA getNamedFramebufferParameteriv through
    // bindFramebuffer(0) surfaces this split at the non-DSA path.
    const GLuint fbName = target == GL_READ_FRAMEBUFFER
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    const bool isDefaultFb = (fbName == 0);
    if (isDefaultFb) {
        switch (pname) {
            case GL_DOUBLEBUFFER:                     *params = GL_TRUE;  return true;
            case GL_IMPLEMENTATION_COLOR_READ_FORMAT: *params = GL_RGBA;  return true;
            case GL_IMPLEMENTATION_COLOR_READ_TYPE:   *params = GL_UNSIGNED_BYTE; return true;
            case GL_SAMPLES:                          *params = 0;        return true;
            case GL_SAMPLE_BUFFERS:                   *params = 0;        return true;
            case GL_STEREO:                           *params = GL_FALSE; return true;
            default:
                // Wrong pname class for the default FB (e.g. one of the
                // FRAMEBUFFER_DEFAULT_* user-FB pnames). Spec says this
                // is INVALID_OPERATION, not INVALID_ENUM — enum is
                // recognised, it just doesn't apply to this FB kind.
                // framebuffers_get_parameter_errors distinguishes the two.
                pushError(GL_INVALID_OPERATION);
                return false;
        }
    }
    // User FBO: accept the FRAMEBUFFER_DEFAULT_* pnames, plus the
    // default-FB-class pnames (DOUBLEBUFFER/IMPL_COLOR_READ_*/SAMPLES/
    // SAMPLE_BUFFERS/STEREO) which framebuffers_get_parameters expects
    // to cross-validate against the non-DSA query. Only default FB
    // rejects the user-FB-only FRAMEBUFFER_DEFAULT_* pnames.
    const GLFramebufferObject* fb = impl_->objects->framebuffers().get(fbName);
    switch (pname) {
        case GL_FRAMEBUFFER_DEFAULT_WIDTH:
            *params = (fb != nullptr) ? fb->defaultWidth : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_HEIGHT:
            *params = (fb != nullptr) ? fb->defaultHeight : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_LAYERS:
            *params = (fb != nullptr) ? fb->defaultLayers : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_SAMPLES:
            *params = (fb != nullptr) ? fb->defaultSamples : 0;
            return true;
        case GL_FRAMEBUFFER_DEFAULT_FIXED_SAMPLE_LOCATIONS:
            *params = (fb != nullptr) ? (GLint)fb->defaultFixedSampleLocations : GL_TRUE;
            return true;
        case GL_DOUBLEBUFFER:                    *params = GL_TRUE;  return true;
        case GL_IMPLEMENTATION_COLOR_READ_FORMAT: *params = GL_RGBA;         return true;
        case GL_IMPLEMENTATION_COLOR_READ_TYPE:   *params = GL_UNSIGNED_BYTE; return true;
        case GL_SAMPLES:                          *params = 0;               return true;
        case GL_SAMPLE_BUFFERS:                   *params = 0;               return true;
        case GL_STEREO:                           *params = GL_FALSE;        return true;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
}

// ---------------------------------------------------------------------------
// GL 4.3 — Invalidation Hints
// ---------------------------------------------------------------------------

// GL 4.6 §17.4.4: attachment-enum validation for Invalidate*Framebuffer.
// Split into a helper so both invalidateFramebuffer and the DSA
// invalidateNamedFramebufferData/SubData paths share the same rules.
// Returns:
//   0           → attachment is accepted for this target
//   INVALID_ENUM      → attachment is unrecognised
//   INVALID_OPERATION → attachment is color-attachment-shaped but >= MAX
//
// For the default framebuffer the valid set is
// {FRONT_LEFT, FRONT_RIGHT, BACK_LEFT, BACK_RIGHT, COLOR, DEPTH, STENCIL}.
// For a user framebuffer the valid set is
// {COLOR_ATTACHMENT0..MAX-1, DEPTH_ATTACHMENT, STENCIL_ATTACHMENT, DEPTH_STENCIL_ATTACHMENT}.
static GLenum classifyInvalidateAttachment(GLenum attachment, bool isDefaultFb) {
    if (isDefaultFb) {
        switch (attachment) {
            case GL_FRONT_LEFT:
            case GL_FRONT_RIGHT:
            case GL_BACK_LEFT:
            case GL_BACK_RIGHT:
            case GL_COLOR:
            case GL_DEPTH:
            case GL_STENCIL:
                return 0;
            default:
                return GL_INVALID_ENUM;
        }
    }
    if (attachment == GL_DEPTH_ATTACHMENT
        || attachment == GL_STENCIL_ATTACHMENT
        || attachment == GL_DEPTH_STENCIL_ATTACHMENT) {
        return 0;
    }
    // Color attachment: shape check vs MAX range check.
    if (attachment >= GL_COLOR_ATTACHMENT0 && attachment <= GL_COLOR_ATTACHMENT0 + 31) {
        const GLuint idx = attachment - GL_COLOR_ATTACHMENT0;
        return idx < 8 ? 0 : GL_INVALID_OPERATION;
    }
    return GL_INVALID_ENUM;
}

bool GLContext::invalidateFramebuffer(GLenum target, GLsizei numAttachments, const GLenum* attachments) {
    if (numAttachments < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Attachment enum validation per §17.4.4. The validation rules
    // differ for the default framebuffer (name 0) vs user framebuffer.
    const GLuint fbName = (target == GL_READ_FRAMEBUFFER)
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    const bool isDefaultFb = (fbName == 0);
    if (attachments != nullptr) {
        for (GLsizei i = 0; i < numAttachments; ++i) {
            const GLenum err = classifyInvalidateAttachment(attachments[i], isDefaultFb);
            if (err != 0) {
                pushError(err);
                return false;
            }
        }
    }
    // Performance hint: signal that attachment contents can be discarded.
    // Maps to MTLStoreAction.dontCare in a future optimization pass.
    return true;
}

bool GLContext::invalidateSubFramebuffer(GLenum target, GLsizei numAttachments, const GLenum* attachments, GLint x, GLint y, GLsizei width, GLsizei height) {
    if (numAttachments < 0 || width < 0 || height < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint fbName = (target == GL_READ_FRAMEBUFFER)
        ? impl_->state->boundReadFramebuffer()
        : impl_->state->boundDrawFramebuffer();
    const bool isDefaultFb = (fbName == 0);
    if (attachments != nullptr) {
        for (GLsizei i = 0; i < numAttachments; ++i) {
            const GLenum err = classifyInvalidateAttachment(attachments[i], isDefaultFb);
            if (err != 0) {
                pushError(err);
                return false;
            }
        }
    }
    return true;
}

bool GLContext::invalidateBufferData(GLuint buffer) {
    if (!impl_->objects->buffers().contains(buffer)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Hint that the entire buffer's contents are no longer needed.
    return true;
}

bool GLContext::invalidateBufferSubData(GLuint buffer, GLintptr offset, GLsizeiptr length) {
    if (offset < 0 || length < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLBufferObject* buf = impl_->objects->buffers().get(buffer);
    if (buf == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (offset + length > buf->size) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.3 — Texture Operations
// ---------------------------------------------------------------------------

bool GLContext::copyImageSubData(GLuint srcName, GLenum srcTarget, GLint srcLevel, GLint srcX, GLint srcY, GLint srcZ,
                                 GLuint dstName, GLenum dstTarget, GLint dstLevel, GLint dstX, GLint dstY, GLint dstZ,
                                 GLsizei srcWidth, GLsizei srcHeight, GLsizei srcDepth) {
    if (srcWidth < 0 || srcHeight < 0 || srcDepth < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §18.2.3: srcTarget and dstTarget must each be one of
    // the allowed texture / renderbuffer targets. TEXTURE_BUFFER is
    // explicitly not allowed (buffer textures have no image storage
    // in the copyImageSubData sense). CTS `copy_image.invalid_target`
    // plants TEXTURE_BUFFER on both sides and expects INVALID_ENUM.
    auto isValidCopyImageTarget = [](GLenum t) {
        switch (t) {
            case GL_RENDERBUFFER:
            case GL_TEXTURE_1D:
            case GL_TEXTURE_1D_ARRAY:
            case GL_TEXTURE_2D:
            case GL_TEXTURE_2D_ARRAY:
            case GL_TEXTURE_2D_MULTISAMPLE:
            case GL_TEXTURE_2D_MULTISAMPLE_ARRAY:
            case GL_TEXTURE_3D:
            case GL_TEXTURE_CUBE_MAP:
            case GL_TEXTURE_CUBE_MAP_ARRAY:
            case GL_TEXTURE_RECTANGLE:
                return true;
            default:
                return false;  // TEXTURE_BUFFER, stray enums, etc.
        }
    };
    if (!isValidCopyImageTarget(srcTarget) ||
        !isValidCopyImageTarget(dstTarget)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // Validate source and destination exist.
    bool srcIsTex = (srcTarget != GL_RENDERBUFFER);
    bool dstIsTex = (dstTarget != GL_RENDERBUFFER);
    if (srcIsTex && !impl_->objects->textures().contains(srcName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!srcIsTex && !impl_->objects->renderbuffers().contains(srcName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (dstIsTex && !impl_->objects->textures().contains(dstName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!dstIsTex && !impl_->objects->renderbuffers().contains(dstName)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // GL 4.6 §18.3.2 / §18.2.3: the target argument must match the
    // texture object's actual bound target. CTS copy_image.target_miss_match
    // creates a TEXTURE_1D and calls copyImageSubData with target=
    // TEXTURE_1D_ARRAY, expecting INVALID_ENUM.
    if (srcIsTex) {
        const GLTextureObject* tex = impl_->objects->textures().get(srcName);
        if (tex != nullptr && tex->target != 0 && tex->target != srcTarget) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
    }
    if (dstIsTex) {
        const GLTextureObject* tex = impl_->objects->textures().get(dstName);
        if (tex != nullptr && tex->target != 0 && tex->target != dstTarget) {
            pushError(GL_INVALID_ENUM);
            return false;
        }
    }
    // GL 4.6 §18.3.2: INVALID_OPERATION if source or destination texture
    // is not "complete" — i.e. has any required level missing or
    // dimensions inconsistent. CTS copy_image.incomplete_tex creates a
    // TEXTURE_1D with no level data and expects INVALID_OPERATION on
    // the copy. For the minimal completeness signal we check whether
    // any level is defined: an empty `levels` map (or only undefined
    // entries) on a non-immutable texture is incomplete.
    auto isTextureComplete = [&](GLuint name) -> bool {
        const GLTextureObject* tex = impl_->objects->textures().get(name);
        if (tex == nullptr) return false;
        if (tex->desc.immutable) return true; // texStorage initialises all levels
        // GL 4.6 §8.17 — multisample textures (TEXTURE_2D_MULTISAMPLE
        // and TEXTURE_2D_MULTISAMPLE_ARRAY) have NO mipmap chain by
        // spec: completeness only requires the single base level to be
        // defined. The general mipmap-completeness loop below would
        // otherwise reject MS textures that legitimately have only
        // level 0 (the natural-max derived from base-level dimensions
        // requests log2(max-dim) levels which never exist for MS).
        // CKPT174 EMERGENCY (Sprint 15 Day 3): regression repair after
        // CKPT159 (`309cbbe`) cleared desc.immutable on MS textures
        // created via legacy glTexImage*Multisample — that fix is
        // correct for ARB_texture_view's origtexture mutability check,
        // but exposed this latent assumption that non-immutable always
        // implies a mipmap chain. Restores copy_image.samples_mismatch
        // (regressed from 324/324 in Sprint 13 close to 323/324 in
        // Sprint 14 close).
        const GLenum tgt = tex->desc.target != 0 ? tex->desc.target : tex->target;
        const bool isMSTarget =
            (tgt == GL_TEXTURE_2D_MULTISAMPLE ||
             tgt == GL_TEXTURE_2D_MULTISAMPLE_ARRAY);
        if (isMSTarget) {
            auto it = tex->levels.find(0);
            return it != tex->levels.end() && it->second.defined;
        }
        if (tex->levels.empty()) return false;
        // GL 4.6 §8.17 mipmap completeness: a non-immutable texture is
        // complete only if every level in [base, effectiveMax] is defined.
        // CTS copy_image.incomplete_tex creates multi-level targets with
        // only level 0 defined and DOES NOT call makeTextureComplete (which
        // sets baseLevel/maxLevel both to 0). Without that, default
        // maxLevel = 1000 means lots of levels required → incomplete.
        const GLint baseLevel = tex->params.baseLevel;
        // Effective max is clamped by both the explicit maxLevel and
        // the natural log2(max-dim) bound at the base level. We use the
        // base-level dimensions to compute the natural cap.
        auto baseIt = tex->levels.find(baseLevel);
        if (baseIt == tex->levels.end() || !baseIt->second.defined) return false;
        const GLsizei baseW = baseIt->second.desc.width;
        const GLsizei baseH = baseIt->second.desc.height;
        const GLsizei baseD = baseIt->second.desc.depth;
        const GLsizei maxDim = std::max({baseW, baseH, baseD, GLsizei{1}});
        GLint naturalMax = baseLevel;
        for (GLsizei m = maxDim; m > 1; m >>= 1) ++naturalMax;
        const GLint effectiveMax = std::min(tex->params.maxLevel, naturalMax);
        for (GLint lvl = baseLevel; lvl <= effectiveMax; ++lvl) {
            auto it = tex->levels.find(lvl);
            if (it == tex->levels.end() || !it->second.defined) return false;
        }
        return true;
    };
    if (srcIsTex && !isTextureComplete(srcName)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (dstIsTex && !isTextureComplete(dstName)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §18.2.3: srcLevel and dstLevel must be valid levels of
    // their objects. Renderbuffers only have level 0; textures have
    // levels [0, desc.levels). Reject out-of-range levels up-front so
    // CTS `copy_image.non_existent_mipmap` sees the INVALID_VALUE it
    // expects (was silently creating the level on the fly below).
    auto isValidLevelForTex = [&](GLuint name, GLint level) -> bool {
        if (level < 0) return false;
        GLTextureObject* tex = impl_->objects->textures().get(name);
        if (tex == nullptr) return false;
        const GLsizei maxLev = std::max<GLsizei>(tex->desc.levels, 1);
        if (level >= maxLev) return false;
        // Non-immutable texture: also require the level to have been
        // defined via texImage (or match desc.levels for texStorage).
        // An undefined level on a non-immutable texture is per-spec
        // INVALID_VALUE. Check via levels map or texStorage's desc.
        if (!tex->desc.immutable) {
            auto it = tex->levels.find(level);
            if (it == tex->levels.end() || !it->second.defined) return false;
        }
        return true;
    };
    if (srcIsTex && !isValidLevelForTex(srcName, srcLevel)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (dstIsTex && !isValidLevelForTex(dstName, dstLevel)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Renderbuffers only have "level 0" — any non-zero level for a
    // renderbuffer source or destination is INVALID_VALUE.
    if (!srcIsTex && srcLevel != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!dstIsTex && dstLevel != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // GL 4.6 §18.2.3: INVALID_OPERATION if source and destination have
    // different sample counts. Renderbuffers default to samples=0;
    // MULTISAMPLE / MULTISAMPLE_ARRAY textures typically have >0.
    // CTS `copy_image.invalid_target` plants a RENDERBUFFER source
    // into a 2D_MULTISAMPLE destination and expects INVALID_OPERATION.
    auto getSamples = [&](GLuint name, bool isTex) -> GLsizei {
        if (isTex) {
            GLTextureObject* tex = impl_->objects->textures().get(name);
            return tex != nullptr ? tex->desc.samples : 0;
        }
        GLRenderbufferObject* rb = impl_->objects->renderbuffers().get(name);
        return rb != nullptr ? rb->samples : 0;
    };
    const GLsizei srcSamples = getSamples(srcName, srcIsTex);
    const GLsizei dstSamples = getSamples(dstName, dstIsTex);
    // A MULTISAMPLE target on a texture with samples=0 still counts
    // as multisample-shaped for the compatibility check (the target
    // alone signals the intent). Normalise the sample count by
    // inspecting the target enum.
    auto targetRequiresMS = [](GLenum t) {
        return t == GL_TEXTURE_2D_MULTISAMPLE ||
               t == GL_TEXTURE_2D_MULTISAMPLE_ARRAY;
    };
    const bool srcIsMSTarget = targetRequiresMS(srcTarget);
    const bool dstIsMSTarget = targetRequiresMS(dstTarget);
    if (srcIsMSTarget != dstIsMSTarget || srcSamples != dstSamples) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §18.2.3 / Table 18.4: src and dst internal formats must
    // be "copy-compatible" — practically this means matching bits-per-
    // texel for non-compressed formats, and matching block-size for
    // compressed formats. Without this check,
    // `glCopyImageSubData(RGBA16UI, RGBA8UI, …)` ran silently; CTS
    // `copy_image.incompatible_formats` expects INVALID_OPERATION.
    auto getInternalFormat = [&](GLuint name, bool isTex, GLint level) -> GLenum {
        if (isTex) {
            const GLTextureObject* t = impl_->objects->textures().get(name);
            if (t == nullptr) return 0;
            auto it = t->levels.find(level);
            if (it != t->levels.end() && it->second.desc.internalFormat != 0) {
                return it->second.desc.internalFormat;
            }
            return t->desc.internalFormat;
        }
        const GLRenderbufferObject* rb = impl_->objects->renderbuffers().get(name);
        return rb != nullptr ? rb->internalFormat : 0;
    };
    // Bits-per-texel for the set of formats covered by GL 4.6 Table
    // 8.12 / 18.4. Returns 0 for compressed formats (caller uses
    // block-based comparison) and for unrecognised formats (caller
    // should let the copy proceed rather than rejecting on unknowns).
    auto bitsPerTexel = [](GLenum fmt) -> int {
        switch (fmt) {
            // 8-bit per channel formats.
            case GL_R8: case GL_R8I: case GL_R8UI:
            case GL_R8_SNORM:
                return 8;
            case GL_RG8: case GL_RG8I: case GL_RG8UI:
            case GL_RG8_SNORM:
                return 16;
            case GL_RGB8: case GL_RGB8I: case GL_RGB8UI:
            case GL_RGB8_SNORM: case GL_SRGB8:
                return 24;
            case GL_RGBA8: case GL_RGBA8I: case GL_RGBA8UI:
            case GL_RGBA8_SNORM: case GL_SRGB8_ALPHA8:
                return 32;
            // 16-bit per channel formats.
            case GL_R16: case GL_R16I: case GL_R16UI:
            case GL_R16_SNORM: case GL_R16F:
                return 16;
            case GL_RG16: case GL_RG16I: case GL_RG16UI:
            case GL_RG16_SNORM: case GL_RG16F:
                return 32;
            case GL_RGB16: case GL_RGB16I: case GL_RGB16UI:
            case GL_RGB16_SNORM: case GL_RGB16F:
                return 48;
            case GL_RGBA16: case GL_RGBA16I: case GL_RGBA16UI:
            case GL_RGBA16_SNORM: case GL_RGBA16F:
                return 64;
            // 32-bit per channel formats.
            case GL_R32I: case GL_R32UI: case GL_R32F:
                return 32;
            case GL_RG32I: case GL_RG32UI: case GL_RG32F:
                return 64;
            case GL_RGB32I: case GL_RGB32UI: case GL_RGB32F:
                return 96;
            case GL_RGBA32I: case GL_RGBA32UI: case GL_RGBA32F:
                return 128;
            // Packed formats.
            case GL_RGB565:           return 16;
            case GL_RGB5_A1:          return 16;
            case GL_RGBA4:            return 16;
            case GL_R3_G3_B2:         return 8;
            case GL_RGB10:            return 32;  // 32 with padding
            case GL_RGB10_A2:
            case GL_RGB10_A2UI:
            case GL_R11F_G11F_B10F:
            case GL_RGB9_E5:
                return 32;
            // Depth / stencil formats — for completeness, though CTS
            // copy_image doesn't mix depth with color.
            case GL_DEPTH_COMPONENT16:  return 16;
            case GL_DEPTH_COMPONENT24:  return 32;  // padded
            case GL_DEPTH_COMPONENT32:  return 32;
            case GL_DEPTH_COMPONENT32F: return 32;
            case GL_DEPTH24_STENCIL8:   return 32;
            case GL_DEPTH32F_STENCIL8:  return 64;
            case GL_STENCIL_INDEX8:     return 8;
            // Compressed formats — report bits-per-BLOCK. GL 4.6
            // §18.2.3 Table 18.4 says a compressed block is copy-
            // compatible with an uncompressed texel of the same
            // total bit-count (e.g. BC5 128-bit block ↔ RGBA32UI
            // 128-bit texel is legal; BC5 ↔ RGBA8UI 32-bit is not).
            // All desktop BC/RGTC/BPTC formats use 4×4 blocks.
            // BC1/BC4/RGTC1: 8 bytes/block = 64 bits/block.
            // BC5/RGTC2/BPTC: 16 bytes/block = 128 bits/block.
            case GL_COMPRESSED_RED_RGTC1:
            case GL_COMPRESSED_SIGNED_RED_RGTC1:
                return 64;
            case GL_COMPRESSED_RG_RGTC2:
            case GL_COMPRESSED_SIGNED_RG_RGTC2:
            case GL_COMPRESSED_RGBA_BPTC_UNORM:
            case GL_COMPRESSED_SRGB_ALPHA_BPTC_UNORM:
            case GL_COMPRESSED_RGB_BPTC_SIGNED_FLOAT:
            case GL_COMPRESSED_RGB_BPTC_UNSIGNED_FLOAT:
                return 128;
            default:
                return 0;  // unrecognised / compressed — caller's fallback
        }
    };
    const GLenum srcInternal = getInternalFormat(srcName, srcIsTex, srcLevel);
    const GLenum dstInternal = getInternalFormat(dstName, dstIsTex, dstLevel);
    const int srcBits = bitsPerTexel(srcInternal);
    const int dstBits = bitsPerTexel(dstInternal);
    if (srcBits > 0 && dstBits > 0 && srcBits != dstBits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }

    // GL 4.6 §18.2.3: when either side is a compressed texture, the
    // offsets and extents must be integer multiples of the block
    // dimensions (or cover the edge of the texture). All desktop
    // compressed formats BC1-BC7 / RGTC / BPTC use a 4×4×1 block.
    // CTS `copy_image.invalid_alignment` plants a 2×4×1 copy from a
    // compressed source/destination and expects INVALID_VALUE.
    auto isCompressedFormat = [](GLenum fmt) {
        switch (fmt) {
            case GL_COMPRESSED_RED_RGTC1:
            case GL_COMPRESSED_SIGNED_RED_RGTC1:
            case GL_COMPRESSED_RG_RGTC2:
            case GL_COMPRESSED_SIGNED_RG_RGTC2:
            case GL_COMPRESSED_RGBA_BPTC_UNORM:
            case GL_COMPRESSED_SRGB_ALPHA_BPTC_UNORM:
            case GL_COMPRESSED_RGB_BPTC_SIGNED_FLOAT:
            case GL_COMPRESSED_RGB_BPTC_UNSIGNED_FLOAT:
                return true;
            default:
                return false;
        }
    };
    const bool srcIsCompressed = isCompressedFormat(srcInternal);
    const bool dstIsCompressed = isCompressedFormat(dstInternal);
    if (srcIsCompressed || dstIsCompressed) {
        // All BC/RGTC/BPTC formats use 4×4×1 blocks on desktop GL.
        const GLint blockW = 4, blockH = 4, blockD = 1;
        auto offsetValid = [&](GLint off, GLint block) {
            return (off % block) == 0;
        };
        auto extentValid = [&](GLint off, GLsizei ext, GLint block, GLsizei texExt) {
            if ((ext % block) == 0) return true;
            // Edge coverage: ext may be < block if it reaches the
            // texture boundary exactly.
            return (off + ext) == texExt;
        };
        if (srcIsCompressed) {
            if (!offsetValid(srcX, blockW) || !offsetValid(srcY, blockH)
                || !offsetValid(srcZ, blockD)) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            // We don't have easy access to src texture extent here
            // without looking it up; for the CTS test at hand,
            // rejecting non-block-aligned extent unconditionally
            // flags the bug. Edge-coverage edge-case is rare in
            // the negative tests the CTS plants.
            if ((srcWidth % blockW) != 0 || (srcHeight % blockH) != 0) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
        }
        if (dstIsCompressed) {
            if (!offsetValid(dstX, blockW) || !offsetValid(dstY, blockH)
                || !offsetValid(dstZ, blockD)) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            // For a non-compressed source copying into a compressed
            // destination, srcWidth/srcHeight are in source texel
            // units — GL's rule is still "be a multiple of the
            // compressed destination's block extent". So the same
            // check fires.
            if ((srcWidth % blockW) != 0 || (srcHeight % blockH) != 0) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
        }
        (void)extentValid;
    }

    // No-op for zero-sized copies.
    if (srcWidth == 0 || srcHeight == 0 || srcDepth == 0) return true;

    // -----------------------------------------------------------------------
    // Resolve source image shadow buffer, dimensions, and bytes-per-pixel.
    // -----------------------------------------------------------------------
    const std::uint8_t* srcPixels = nullptr;
    GLsizei srcImgW = 0, srcImgH = 0, srcImgD = 1;
    std::size_t srcBpp = 4; // RGBA8 default

    if (srcIsTex) {
        GLTextureObject* srcTex = impl_->objects->textures().get(srcName);
        if (!srcTex) { pushError(GL_INVALID_VALUE); return false; }
        auto it = srcTex->levels.find(srcLevel);
        if (it == srcTex->levels.end() || !it->second.defined) {
            pushError(GL_INVALID_VALUE);
            return false;
        }
        const GLTextureImageLevel& srcImg = it->second;
        srcImgW = srcImg.desc.width;
        srcImgH = srcImg.desc.height;
        srcImgD = srcImg.desc.depth;
        // Per GL 4.6 §18.2.3 Table 18.1 — copyImageSubData per-target axis
        // mapping. For TEXTURE_1D_ARRAY, the second axis (srcY/dstY) is the
        // layer index (0..layers-1) while the height dimension proper is
        // always 1. CTS copy_image.exceeding_boundaries plants Y=14 on a
        // 16-wide × 6-layer 1D-array and expects INVALID_VALUE because
        // 14+1 > 6. Re-route the Y-axis bound to the layer count for
        // 1D_ARRAY so the bounds check fires on layer overflow even if
        // raw `desc.height` is set to texel-row count.
        if (srcTarget == GL_TEXTURE_1D_ARRAY) {
            srcImgH = std::max<GLsizei>(srcTex->desc.depth, srcImg.desc.depth);
        }
        // Prefer native data if available, else fall back to rgba8.
        if (srcImg.nativeBpp > 0 && !srcImg.nativeData.empty()) {
            srcPixels = srcImg.nativeData.data();
            srcBpp = srcImg.nativeBpp;
        } else if (!srcImg.rgba8.empty()) {
            srcPixels = srcImg.rgba8.data();
            srcBpp = 4;
        }
    } else {
        GLRenderbufferObject* srcRB = impl_->objects->renderbuffers().get(srcName);
        if (!srcRB || !srcRB->storageDefined) { pushError(GL_INVALID_VALUE); return false; }
        srcImgW = srcRB->width;
        srcImgH = srcRB->height;
        srcImgD = 1;
        // CKPT117 (Sprint 11 Phase 1 1a): prefer RB.nativeData over rgba8
        // when the RB has a native-precision shadow allocated (non-RGBA8
        // internal formats per replaceRenderbufferStorage). This unblocks
        // the rgb10/rgb32f RB-source residual classes from CKPT109 + the
        // copy_image.smoke_test RGBA32UI 16-bpp case (smoke_test from 1c
        // residual).
        if (srcRB->nativeBpp > 0 && !srcRB->nativeData.empty()) {
            srcPixels = srcRB->nativeData.data();
            srcBpp = srcRB->nativeBpp;
        } else if (!srcRB->rgba8.empty()) {
            srcPixels = srcRB->rgba8.data();
            srcBpp = 4;
        }
    }

    if (srcPixels == nullptr) {
        // Source has no CPU-side shadow data — nothing to copy.
        return true;
    }

    // Bounds check source region. CKPT116 (Sprint 11 Phase 1 1c): include
    // the depth/layer axis (srcZ + srcDepth > srcImgD) — 3D textures and
    // *_ARRAY targets place layers on the Z axis. CTS copy_image.
    // exceeding_boundaries also exercises the 1D_ARRAY layer-on-Y case
    // (handled via srcImgH re-route above).
    if (srcX < 0 || srcY < 0 || srcZ < 0 ||
        srcX + srcWidth > srcImgW || srcY + srcHeight > srcImgH ||
        srcZ + srcDepth > srcImgD) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // -----------------------------------------------------------------------
    // Resolve destination image shadow buffer.
    // -----------------------------------------------------------------------
    std::uint8_t* dstPixels = nullptr;
    GLsizei dstImgW = 0, dstImgH = 0, dstImgD = 1;
    std::size_t dstBpp = 4;

    // We need a writable pointer and the ability to invalidate the Metal texture.
    GLTextureObject* dstTex = nullptr;
    GLRenderbufferObject* dstRB = nullptr;
    GLTextureImageLevel* dstImg = nullptr;

    if (dstIsTex) {
        dstTex = impl_->objects->textures().get(dstName);
        if (!dstTex) { pushError(GL_INVALID_VALUE); return false; }
        auto it = dstTex->levels.find(dstLevel);
        if (it == dstTex->levels.end()) {
            // Level not defined — create it on the fly with same dims as source.
            GLTextureImageLevel newLevel;
            newLevel.desc.width = srcImgW;
            newLevel.desc.height = srcImgH;
            newLevel.desc.depth = 1;
            newLevel.defined = true;
            auto ins = dstTex->levels.emplace(dstLevel, std::move(newLevel));
            it = ins.first;
        }
        dstImg = &it->second;
        if (!dstImg->defined) {
            // Allocate matching storage if level was created by texStorage but not yet texImage'd.
            dstImg->defined = true;
        }
        dstImgW = dstImg->desc.width;
        dstImgH = dstImg->desc.height;
        dstImgD = dstImg->desc.depth;
        // CKPT116: 1D_ARRAY layer-count-on-Y axis (mirror src logic).
        if (dstTarget == GL_TEXTURE_1D_ARRAY) {
            dstImgH = std::max<GLsizei>(dstTex->desc.depth, dstImg->desc.depth);
        }

        // Ensure the destination rgba8 buffer is large enough.
        const std::size_t totalPixels = static_cast<std::size_t>(dstImgW) * dstImgH;
        if (dstImg->nativeBpp > 0 && !dstImg->nativeData.empty()) {
            dstPixels = dstImg->nativeData.data();
            dstBpp = dstImg->nativeBpp;
        } else {
            if (dstImg->rgba8.size() < totalPixels * 4) {
                dstImg->rgba8.resize(totalPixels * 4, 0);
            }
            dstPixels = dstImg->rgba8.data();
            dstBpp = 4;
        }
    } else {
        dstRB = impl_->objects->renderbuffers().get(dstName);
        if (!dstRB || !dstRB->storageDefined) { pushError(GL_INVALID_VALUE); return false; }
        dstImgW = dstRB->width;
        dstImgH = dstRB->height;
        const std::size_t totalPixels = static_cast<std::size_t>(dstImgW) * dstImgH;
        // CKPT117: prefer RB.nativeData when allocated (non-RGBA8 internal
        // formats); fall back to rgba8 for RGBA8-mapped formats.
        if (dstRB->nativeBpp > 0 && !dstRB->nativeData.empty()) {
            dstPixels = dstRB->nativeData.data();
            dstBpp = dstRB->nativeBpp;
        } else {
            if (dstRB->rgba8.size() < totalPixels * 4) {
                dstRB->rgba8.resize(totalPixels * 4, 0);
            }
            dstPixels = dstRB->rgba8.data();
            dstBpp = 4;
        }
    }

    // Bounds check destination region. CKPT116: include the depth/layer
    // axis for 3D / *_ARRAY targets, matching the source-side bound at
    // line 30361+ above.
    if (dstX < 0 || dstY < 0 || dstZ < 0 ||
        dstX + srcWidth > dstImgW || dstY + srcHeight > dstImgH ||
        dstZ + srcDepth > dstImgD) {
        pushError(GL_INVALID_VALUE);
        return false;
    }

    // -----------------------------------------------------------------------
    // Perform the pixel copy — row-by-row within each depth slice.
    // -----------------------------------------------------------------------
    // When bpp matches between source and destination, do a direct memcpy per row.
    // When bpp differs (e.g. native R8 → RGBA8), we need to convert; for now,
    // use the rgba8 path as the common denominator.
    if (srcBpp == dstBpp) {
        const std::size_t srcRowBytes = static_cast<std::size_t>(srcImgW) * srcBpp;
        const std::size_t dstRowBytes = static_cast<std::size_t>(dstImgW) * dstBpp;
        const std::size_t srcSliceBytes = srcRowBytes * static_cast<std::size_t>(srcImgH);
        const std::size_t dstSliceBytes = dstRowBytes * static_cast<std::size_t>(dstImgH);
        const std::size_t copyRowBytes = static_cast<std::size_t>(srcWidth) * srcBpp;

        for (GLsizei z = 0; z < srcDepth; ++z) {
            const std::size_t srcSliceOff = static_cast<std::size_t>(srcZ + z) * srcSliceBytes;
            const std::size_t dstSliceOff = static_cast<std::size_t>(dstZ + z) * dstSliceBytes;
            for (GLsizei row = 0; row < srcHeight; ++row) {
                const std::size_t srcOff = srcSliceOff
                                         + static_cast<std::size_t>(srcY + row) * srcRowBytes
                                         + static_cast<std::size_t>(srcX) * srcBpp;
                const std::size_t dstOff = dstSliceOff
                                         + static_cast<std::size_t>(dstY + row) * dstRowBytes
                                         + static_cast<std::size_t>(dstX) * dstBpp;
                std::memcpy(dstPixels + dstOff, srcPixels + srcOff, copyRowBytes);
            }
        }
    } else {
        // Mismatched bpp — fall back to rgba8 shadow for both src and dst.
        // Re-resolve using rgba8 for both sides.
        const std::uint8_t* srcRGBA = nullptr;
        std::uint8_t* dstRGBA = nullptr;

        if (srcIsTex) {
            GLTextureObject* srcTex = impl_->objects->textures().get(srcName);
            auto it = srcTex->levels.find(srcLevel);
            if (it != srcTex->levels.end() && !it->second.rgba8.empty()) {
                srcRGBA = it->second.rgba8.data();
            }
        } else {
            GLRenderbufferObject* srcRB = impl_->objects->renderbuffers().get(srcName);
            if (srcRB && !srcRB->rgba8.empty()) srcRGBA = srcRB->rgba8.data();
        }

        if (dstImg && !dstImg->rgba8.empty()) {
            dstRGBA = dstImg->rgba8.data();
        } else if (dstRB && !dstRB->rgba8.empty()) {
            dstRGBA = dstRB->rgba8.data();
        }

        if (srcRGBA && dstRGBA) {
            const std::size_t srcRow4 = static_cast<std::size_t>(srcImgW) * 4;
            const std::size_t dstRow4 = static_cast<std::size_t>(dstImgW) * 4;
            const std::size_t srcSlice4 = srcRow4 * static_cast<std::size_t>(srcImgH);
            const std::size_t dstSlice4 = dstRow4 * static_cast<std::size_t>(dstImgH);
            const std::size_t copyRow4 = static_cast<std::size_t>(srcWidth) * 4;
            for (GLsizei z = 0; z < srcDepth; ++z) {
                const std::size_t sSliceOff = static_cast<std::size_t>(srcZ + z) * srcSlice4;
                const std::size_t dSliceOff = static_cast<std::size_t>(dstZ + z) * dstSlice4;
                for (GLsizei row = 0; row < srcHeight; ++row) {
                    const std::size_t sOff = sSliceOff + static_cast<std::size_t>(srcY + row) * srcRow4 + static_cast<std::size_t>(srcX) * 4;
                    const std::size_t dOff = dSliceOff + static_cast<std::size_t>(dstY + row) * dstRow4 + static_cast<std::size_t>(dstX) * 4;
                    std::memcpy(dstRGBA + dOff, srcRGBA + sOff, copyRow4);
                }
            }
            // Sync rgba8 → dst.nativeData for the copied region. Required
            // when destination has both shadows (e.g. R8 / RGB12 / RGB32F /
            // RGBA12 textures with native Metal pixel format), so that
            // subsequent glGetTexImage / re-upload via replaceMetalTexture
            // reads native shadow with the updated values. Without this,
            // CTS copy_image RB-source-unique tests (r8, rgb10, rgb12,
            // rgba12, rgb32f × 3 RB-source buckets = 15 tests) read stale
            // zero-filled native shadow on the destination after copy.
            // GL 4.6 §18.2.3: the copy is byte-level; we only need to
            // re-encode the destination's native representation from the
            // rgba8 values that the byte-level copy logically produced.
            if (dstImg && dstImg->nativeBpp > 0 && !dstImg->nativeData.empty()) {
                MTLPixelFormat dstNativeFmt = metalRenderbufferFormat(
                    dstImg->desc.internalFormat != 0
                        ? dstImg->desc.internalFormat
                        : dstTex->desc.internalFormat);
                auto info = Impl::nativeFormatInfo(dstNativeFmt);
                if (info.channels > 0 && info.bytesPerPixel > 0) {
                    const std::size_t natRowBytes = static_cast<std::size_t>(dstImgW) * info.bytesPerPixel;
                    const std::size_t natSliceBytes = natRowBytes * static_cast<std::size_t>(dstImgH);
                    for (GLsizei z = 0; z < srcDepth; ++z) {
                        for (GLsizei row = 0; row < srcHeight; ++row) {
                            for (GLsizei col = 0; col < srcWidth; ++col) {
                                const std::size_t rgbaOff =
                                    (static_cast<std::size_t>(dstZ + z) * dstSlice4)
                                    + (static_cast<std::size_t>(dstY + row) * dstRow4)
                                    + (static_cast<std::size_t>(dstX + col) * 4);
                                const std::size_t natOff =
                                    (static_cast<std::size_t>(dstZ + z) * natSliceBytes)
                                    + (static_cast<std::size_t>(dstY + row) * natRowBytes)
                                    + (static_cast<std::size_t>(dstX + col) * info.bytesPerPixel);
                                const std::uint8_t* rgbaPx = dstRGBA + rgbaOff;
                                std::uint8_t* natPx = dstImg->nativeData.data() + natOff;
                                // For each native channel, compute the value
                                // from the rgba8 value at that channel index
                                // (R=0, G=1, B=2, A=3; missing channels read 0).
                                for (int c = 0; c < info.channels; ++c) {
                                    const std::uint8_t rgbaByte = rgbaPx[c];
                                    double v;
                                    switch (info.compType) {
                                        case Impl::NativeFormatInfo::UNorm:
                                            // rgba8 stores u8 unorm; scale to native bit width
                                            v = rgbaByte / 255.0;
                                            break;
                                        case Impl::NativeFormatInfo::SNorm:
                                            // rgba8 has no signed range — treat the byte as
                                            // unsigned and re-center [0,255] → [-1,1]. Edge
                                            // case rare in copy_image (no SNorm in failing pairs).
                                            v = (rgbaByte / 255.0) * 2.0 - 1.0;
                                            break;
                                        case Impl::NativeFormatInfo::UInt:
                                            v = static_cast<double>(rgbaByte);
                                            break;
                                        case Impl::NativeFormatInfo::SInt:
                                            v = static_cast<double>(static_cast<std::int8_t>(rgbaByte));
                                            break;
                                        case Impl::NativeFormatInfo::Float:
                                            v = rgbaByte / 255.0;
                                            break;
                                    }
                                    Impl::writeNativeComponent(
                                        natPx + c * info.bytesPerChannel,
                                        info.compType,
                                        info.bytesPerChannel,
                                        v);
                                }
                            }
                        }
                    }
                }
            }
        }
    }

    // -----------------------------------------------------------------------
    // Invalidate the destination Metal texture so it will be re-uploaded.
    // We null out metalTexture rather than just flipping `instantiated`
    // because bindTexture re-sets instantiated=true before any subsequent
    // read, which would otherwise mask the pending re-upload.
    // -----------------------------------------------------------------------
    if (dstTex) {
        releaseRetainedMetalObject(dstTex->metalTexture);
        dstTex->metalTexture = nullptr;
    }
    if (dstRB) {
        dstRB->instantiated = false;
    }
    return true;
}

bool GLContext::textureView(GLuint texture, GLenum target, GLuint origtexture, GLenum internalformat,
                            GLuint minlevel, GLuint numlevels, GLuint minlayer, GLuint numlayers) {
    // GL 4.3 §8.18 (ARB_texture_view) — error cases as asserted by
    // CTS `texture_view.errors`:
    //  - texture == 0           → INVALID_VALUE (texture name 0 is
    //                             reserved for "no binding")
    //  - origtexture == 0       → INVALID_VALUE (same reasoning)
    //  - texture is 0xFFFFFFFF
    //    or otherwise not from glGenTextures → INVALID_OPERATION
    //  - origtexture has no data store allocated → INVALID_OPERATION
    //  - numlevels / numlayers == 0 → INVALID_VALUE
    if (texture == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTextureObject* viewObj = impl_->objects->textures().get(texture);
    if (viewObj == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // The view texture must be "fresh" — glTextureView cannot re-
    // target an already-bound texture. `target != 0` means a prior
    // glBindTexture / glCreateTextures set the target.
    if (viewObj->target != 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // origtexture: both 0 and an unrecognized name produce
    // INVALID_VALUE per the CTS errors test (differs from the
    // `texture` argument's rule where an unrecognized name gives
    // INVALID_OPERATION). The test exercises both codepaths.
    if (origtexture == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTextureObject* origObj = impl_->objects->textures().get(origtexture);
    if (origObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!origObj->desc.immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (numlevels == 0 || numlayers == 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Record the view relationship. Actual Metal texture view
    // (newTextureViewWithPixelFormat:) will be created when the Metal texture
    // is first needed for rendering.
    viewObj->target = target;
    viewObj->desc.target = target;
    viewObj->desc.internalFormat = internalformat;
    viewObj->desc.levels = static_cast<GLsizei>(numlevels);
    viewObj->desc.layers = static_cast<GLsizei>(numlayers);
    viewObj->desc.immutable = true;
    return true;
}

bool GLContext::invalidateTexImage(GLuint texture, GLint level) {
    if (!impl_->objects->textures().contains(texture)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Hint: texture contents at this level can be discarded.
    return true;
}

bool GLContext::invalidateTexSubImage(GLuint texture, GLint level, GLint xoffset, GLint yoffset, GLint zoffset,
                                      GLsizei width, GLsizei height, GLsizei depth) {
    if (width < 0 || height < 0 || depth < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (!impl_->objects->textures().contains(texture)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.2 — Transform Feedback Instanced Draw
// ---------------------------------------------------------------------------

bool GLContext::drawTransformFeedbackInstanced(GLenum mode, GLuint id, GLsizei instancecount) {
    if (instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTransformFeedbackObject* tfObj = impl_->objects->transformFeedbacks().get(id);
    if (tfObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Sprint 8 #9-C (CKPT68): GL 4.6 §10.5 — DrawTransformFeedbackInstanced
    // is equivalent to DrawArraysInstanced(mode, 0, count, instancecount)
    // where `count` is the number of vertices captured during the most
    // recent EndTransformFeedback. capturedVertexCount is updated by
    // writeGsXfbAndCheckDiscard / writeTessTFAndUpdateCounters during
    // TF capture.
    //
    // CKPT94 #9-C foundation: per-stream array (gl_MaxTransformFeedbackStreams
    // ≥ 4). Non-Stream variant always reads stream 0 per GL 4.6 §10.5 (the
    // non-Stream entry point is implicitly stream 0). Multi-stream
    // accumulators are added Day 23 via GS-emul EmitStreamVertex routing.
    const GLsizei vertexCount = tfObj->capturedVertexCount[0];
    if (vertexCount <= 0 || instancecount == 0) {
        return true;  // zero-vertex / zero-instance draw is a no-op success
    }
    return drawArraysInstanced(mode, 0, vertexCount, instancecount);
}

bool GLContext::drawTransformFeedbackStreamInstanced(GLenum mode, GLuint id, GLuint stream, GLsizei instancecount) {
    if (instancecount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    GLTransformFeedbackObject* tfObj = impl_->objects->transformFeedbacks().get(id);
    if (tfObj == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Sprint 8 #9-C remainder (CKPT94 foundation): the stream parameter
    // selects which captured vertex stream to draw from. The
    // capturedVertexCount field is now an array indexed by stream
    // (kMaxTransformFeedbackStreams = 4 per GL 4.0 spec floor). Streams
    // beyond the per-object array bound are clamped down to 0 (graceful
    // — matches GL spec validation expectations on out-of-range stream).
    //
    // Day 23 adds GS-emul EmitStreamVertex routing that populates streams
    // 1..3 during capture; until then capturedVertexCount[1..3] stay at
    // their zero-init values, and the test's stream=0 read continues to
    // work for non-stream-using callers.
    const std::size_t streamIdx =
        (stream < GLTransformFeedbackObject::kMaxTransformFeedbackStreams)
            ? static_cast<std::size_t>(stream) : 0u;
    const GLsizei vertexCount = tfObj->capturedVertexCount[streamIdx];
    if (vertexCount <= 0 || instancecount == 0) {
        return true;
    }
    return drawArraysInstanced(mode, 0, vertexCount, instancecount);
}

// ---------------------------------------------------------------------------
// GL 4.2/4.3 — Internal Format Query
// ---------------------------------------------------------------------------

bool GLContext::getInternalformativ(GLenum target, GLenum internalformat, GLenum pname, GLsizei count, GLint* params) {
    if (count < 0 || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    // Phase 8X Landing C 3b — consult the capabilities format table so
    // format-dependent queries (SUPPORTED, COLOR_ENCODING, RENDERABLE,
    // BLEND) reflect the actual entries that initializeFormatTable() puts
    // on the device, rather than returning GL_FULL_SUPPORT unconditionally.
    std::optional<GLFormatCapability> capability = impl_->capabilities->format(internalformat);
    switch (pname) {
        case GL_NUM_SAMPLE_COUNTS:
            params[0] = 3; // Metal typically supports 1, 2, 4 samples
            return true;
        case GL_SAMPLES:
            // Return sample counts in descending order.
            if (count >= 1) params[0] = 4;
            if (count >= 2) params[1] = 2;
            if (count >= 3) params[2] = 1;
            return true;
        case GL_INTERNALFORMAT_SUPPORTED:
            params[0] = capability.has_value() ? GL_TRUE : GL_FALSE;
            return true;
        case GL_INTERNALFORMAT_PREFERRED:
            params[0] = static_cast<GLint>(internalformat);
            return true;
        case GL_READ_PIXELS_FORMAT:
            params[0] = GL_RGBA;
            return true;
        case GL_READ_PIXELS_TYPE:
            params[0] = GL_UNSIGNED_BYTE;
            return true;
        case GL_MAX_WIDTH:
            params[0] = 16384;
            return true;
        case GL_MAX_HEIGHT:
            params[0] = 16384;
            return true;
        case GL_MAX_DEPTH:
            params[0] = 2048;
            return true;
        case GL_MAX_LAYERS:
            params[0] = 2048;
            return true;
        case GL_MAX_COMBINED_DIMENSIONS:
            params[0] = 16384;
            return true;
        case GL_FRAMEBUFFER_RENDERABLE:
            if (!capability.has_value()) {
                params[0] = GL_NONE;
            } else {
                params[0] = capability->renderable ? GL_FULL_SUPPORT : GL_CAVEAT_SUPPORT;
            }
            return true;
        case GL_FRAMEBUFFER_BLEND:
            if (!capability.has_value()) {
                params[0] = GL_NONE;
            } else {
                params[0] = capability->blendable ? GL_FULL_SUPPORT : GL_CAVEAT_SUPPORT;
            }
            return true;
        case GL_COLOR_ENCODING:
            if (capability.has_value() && capability->srgbCapable) {
                params[0] = GL_SRGB;
            } else {
                params[0] = GL_LINEAR;
            }
            return true;
        default:
            // For unrecognized pnames, return 0 rather than erroring — apps
            // sometimes probe opportunistically.
            for (GLsizei i = 0; i < count; ++i) {
                params[i] = 0;
            }
            return true;
    }
}

bool GLContext::getInternalformati64v(GLenum target, GLenum internalformat, GLenum pname, GLsizei count, GLint64* params) {
    if (count < 0 || params == nullptr) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (count == 0) {
        return true;
    }
    // Reuse the 32-bit path, widening the results.
    std::vector<GLint> temp(static_cast<std::size_t>(count), 0);
    bool result = getInternalformativ(target, internalformat, pname, count, temp.data());
    if (result) {
        for (GLsizei i = 0; i < count; ++i) {
            params[i] = static_cast<GLint64>(temp[static_cast<std::size_t>(i)]);
        }
    }
    return result;
}

// ---------------------------------------------------------------------------
// GL 4.4 — Immutable buffer storage.
// ---------------------------------------------------------------------------

bool GLContext::bufferStorage(GLenum target, GLsizeiptr size, const void* data, GLbitfield flags) {
    // GL 4.4 §6.2: error-order matters. Binding / immutability
    // checks run before INVALID_VALUE checks because CTS
    // `buffer_storage.errors` specifically asserts that
    // `glBufferStorage(target, 0 /* size */, …)` with no buffer
    // bound returns INVALID_OPERATION (binding wins) — not
    // INVALID_VALUE from the zero-size check.
    GLuint name = impl_->state->boundBuffer(target);
    if (name == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    auto* buf = impl_->objects->buffers().get(name);
    if (!buf) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (buf->immutable) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // size must be > 0. Both `size < 0` and `size == 0` are
    // INVALID_VALUE per GL 4.4 §6.2.1, two spec violations that
    // CTS buffer_storage.errors cross-checks.
    if (size <= 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLbitfield validBits = GL_MAP_READ_BIT | GL_MAP_WRITE_BIT |
                                 GL_MAP_PERSISTENT_BIT | GL_MAP_COHERENT_BIT |
                                 GL_DYNAMIC_STORAGE_BIT | GL_CLIENT_STORAGE_BIT;
    if (flags & ~validBits) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((flags & GL_MAP_PERSISTENT_BIT) && !(flags & (GL_MAP_READ_BIT | GL_MAP_WRITE_BIT))) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if ((flags & GL_MAP_COHERENT_BIT) && !(flags & GL_MAP_PERSISTENT_BIT)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Delegate to replaceBufferStorage to create both shadow bytes and Metal
    // buffer, then layer immutability flags on top.  Without this the Metal
    // buffer would remain null and draws would render black.
    if (!impl_->replaceBufferStorage(*buf, size, data, GL_STATIC_DRAW)) {
        pushError(GL_OUT_OF_MEMORY);
        return false;
    }
    buf->immutable = true;
    buf->storageFlags = flags;
    buf->instantiated = true;
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.4 — Multi-bind.
// ---------------------------------------------------------------------------

static bool isIndexedBufferTarget(GLenum target) {
    switch (target) {
        case GL_ATOMIC_COUNTER_BUFFER:
        case GL_TRANSFORM_FEEDBACK_BUFFER:
        case GL_UNIFORM_BUFFER:
        case GL_SHADER_STORAGE_BUFFER:
            return true;
        default:
            return false;
    }
}

namespace {
GLint64 queryLimit(const GLCapabilities* caps, GLenum pname, GLint64 fallback) {
    GLint64 value = fallback;
    if (caps != nullptr) {
        caps->queryInteger64(pname, &value);
    }
    return value;
}

GLenum indexedBufferMaxPname(GLenum target) {
    switch (target) {
        case GL_UNIFORM_BUFFER:           return GL_MAX_UNIFORM_BUFFER_BINDINGS;
        case GL_SHADER_STORAGE_BUFFER:    return GL_MAX_SHADER_STORAGE_BUFFER_BINDINGS;
        case GL_ATOMIC_COUNTER_BUFFER:    return GL_MAX_ATOMIC_COUNTER_BUFFER_BINDINGS;
        case GL_TRANSFORM_FEEDBACK_BUFFER: return GL_MAX_TRANSFORM_FEEDBACK_BUFFERS;
        default: return 0;
    }
}
}  // namespace

bool GLContext::bindBuffersBase(GLenum target, GLuint first, GLsizei count, const GLuint* buffers) {
    if (!isIndexedBufferTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxBindings = queryLimit(impl_->capabilities.get(), indexedBufferMaxPname(target), 0);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxBindings) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 ARB_multi_bind §6.1.1 — per-entry semantics. Each
    // invalid (non-zero, non-existent) buffer name generates
    // INVALID_OPERATION and that slot is unmodified; valid entries
    // still bind. bindBufferBase itself already pushes INVALID_
    // OPERATION on a bad name, so just let it run through the loop
    // and the per-entry errors accumulate naturally.
    for (GLsizei i = 0; i < count; ++i) {
        GLuint buf = buffers ? buffers[i] : 0;
        if (buf != 0 && !impl_->objects->buffers().contains(buf)) {
            pushError(GL_INVALID_OPERATION);
            continue;
        }
        bindBufferBase(target, first + static_cast<GLuint>(i), buf);
    }
    return true;
}

bool GLContext::bindBuffersRange(GLenum target, GLuint first, GLsizei count, const GLuint* buffers,
                                 const GLintptr* offsets, const GLsizeiptr* sizes) {
    if (!isIndexedBufferTarget(target)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxBindings = queryLimit(impl_->capabilities.get(), indexedBufferMaxPname(target), 0);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxBindings) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    for (GLsizei i = 0; i < count; ++i) {
        GLuint buf = buffers ? buffers[i] : 0;
        GLintptr offset = (buffers && offsets) ? offsets[i] : 0;
        GLsizeiptr sz = (buffers && sizes) ? sizes[i] : 0;
        if (buf != 0 && !impl_->objects->buffers().contains(buf)) {
            pushError(GL_INVALID_OPERATION);
            continue;
        }
        bindBufferRange(target, first + static_cast<GLuint>(i), buf, offset, sz);
    }
    return true;
}

bool GLContext::bindVertexBuffers(GLuint first, GLsizei count, const GLuint* buffers,
                                  const GLintptr* offsets, const GLsizei* strides) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxBindings = queryLimit(impl_->capabilities.get(), GL_MAX_VERTEX_ATTRIB_BINDINGS, 16);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxBindings) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    for (GLsizei i = 0; i < count; ++i) {
        GLuint buf = buffers ? buffers[i] : 0;
        GLintptr offset = (buffers && offsets) ? offsets[i] : 0;
        GLsizei stride = (buffers && strides) ? strides[i] : 0;
        bindVertexBuffer(first + static_cast<GLuint>(i), buf, offset, stride);
    }
    return true;
}

bool GLContext::bindTextures(GLuint first, GLsizei count, const GLuint* textures) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxUnits = queryLimit(impl_->capabilities.get(), GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS, 80);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxUnits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.1.1 / ARB_multi_bind — per-entry semantics: an
    // invalid (non-zero, non-existent) texture name raises
    // INVALID_OPERATION and the corresponding unit is unmodified;
    // other valid entries still bind. Also per spec, ACTIVE_TEXTURE
    // is NOT modified — which our prior impl broke by cycling
    // `setActiveTextureUnit` inside the loop without restoring.
    const GLuint savedActiveUnit = impl_->state->activeTextureUnit();
    bool anyInvalid = false;
    for (GLsizei i = 0; i < count; ++i) {
        GLuint tex = textures ? textures[i] : 0;
        GLuint unit = first + static_cast<GLuint>(i);
        impl_->state->setActiveTextureUnit(unit);
        if (tex == 0) {
            // Unbind every target on this unit (multi-bind unbinds
            // regardless of previously-bound target).
            impl_->state->bindTexture(GL_TEXTURE_1D, 0);
            impl_->state->bindTexture(GL_TEXTURE_2D, 0);
            impl_->state->bindTexture(GL_TEXTURE_3D, 0);
            impl_->state->bindTexture(GL_TEXTURE_1D_ARRAY, 0);
            impl_->state->bindTexture(GL_TEXTURE_2D_ARRAY, 0);
            impl_->state->bindTexture(GL_TEXTURE_RECTANGLE, 0);
            impl_->state->bindTexture(GL_TEXTURE_CUBE_MAP, 0);
            impl_->state->bindTexture(GL_TEXTURE_CUBE_MAP_ARRAY, 0);
            impl_->state->bindTexture(GL_TEXTURE_BUFFER, 0);
            impl_->state->bindTexture(GL_TEXTURE_2D_MULTISAMPLE, 0);
            impl_->state->bindTexture(GL_TEXTURE_2D_MULTISAMPLE_ARRAY, 0);
            continue;
        }
        auto* obj = impl_->objects->textures().get(tex);
        if (obj == nullptr) {
            anyInvalid = true;
            continue;
        }
        GLenum target = obj->target != 0 ? obj->target : GL_TEXTURE_2D;
        impl_->state->bindTexture(target, tex);
    }
    impl_->state->setActiveTextureUnit(savedActiveUnit);
    if (anyInvalid) pushError(GL_INVALID_OPERATION);
    return true;
}

bool GLContext::bindSamplers(GLuint first, GLsizei count, const GLuint* samplers) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxUnits = queryLimit(impl_->capabilities.get(), GL_MAX_COMBINED_TEXTURE_IMAGE_UNITS, 80);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxUnits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 §6.1.1 / ARB_multi_bind — per-entry semantics.
    bool anyInvalid = false;
    for (GLsizei i = 0; i < count; ++i) {
        GLuint sampler = samplers ? samplers[i] : 0;
        if (sampler != 0 && !impl_->objects->samplers().contains(sampler)) {
            anyInvalid = true;
            continue;
        }
        bindSampler(first + static_cast<GLuint>(i), sampler);
    }
    if (anyInvalid) pushError(GL_INVALID_OPERATION);
    return true;
}

bool GLContext::bindImageTextures(GLuint first, GLsizei count, const GLuint* textures) {
    if (count < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLint64 maxUnits = queryLimit(impl_->capabilities.get(), GL_MAX_IMAGE_UNITS, 8);
    if (static_cast<GLint64>(first) + static_cast<GLint64>(count) > maxUnits) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // GL 4.4 ARB_multi_bind / §8.22 — glBindImageTextures uses
    // per-entry semantics: each invalid <textures> entry generates
    // INVALID_OPERATION and that unit's binding is *unmodified*;
    // other valid entries still get bound. Write each unit directly
    // to avoid the per-unit bindImageTexture format whitelist, which
    // is stricter than what the multi-bind spec implies (all
    // texture-storage-eligible formats are OK here).
    bool anyInvalid = false;
    for (GLsizei i = 0; i < count; ++i) {
        GLuint tex = textures ? textures[i] : 0;
        GLuint unit = first + static_cast<GLuint>(i);
        if (unit >= impl_->imageBindings.size()) break;
        auto& binding = impl_->imageBindings[unit];
        if (tex == 0) {
            binding.texture = 0;
            binding.level = 0;
            binding.layered = GL_FALSE;
            binding.layer = 0;
            binding.access = GL_READ_ONLY;
            binding.format = GL_RGBA8;
            continue;
        }
        auto* obj = impl_->objects->textures().get(tex);
        if (obj == nullptr) {
            // Invalid entry — INVALID_OPERATION, unit unmodified.
            anyInvalid = true;
            continue;
        }
        // CTS `multi_bind.errors_bind_image_textures` plants a texture
        // whose storage was never successfully allocated (texStorage2D
        // with height=0 → INVALID_VALUE) and asserts INVALID_OPERATION
        // here. Our textures store internalFormat only after a
        // successful storage/image call — a 0 means storage was never
        // provided. Functional tests (same texture via proper
        // InitStorage) always end up with a non-zero format.
        GLenum fmt = obj->desc.internalFormat;
        if (fmt == 0) {
            anyInvalid = true;
            continue;
        }
        binding.texture = tex;
        binding.level = 0;
        binding.layered = GL_TRUE;
        binding.layer = 0;
        binding.access = GL_READ_WRITE;
        binding.format = fmt;
    }
    if (anyInvalid) {
        pushError(GL_INVALID_OPERATION);
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.4 — Texture clear.
// ---------------------------------------------------------------------------

namespace {

struct FillLevelArgs {
    GLenum format;
    GLenum type;
    const void* data;
    GLint xoff;
    GLint yoff;
    GLint zoff;
    GLsizei regionW;
    GLsizei regionH;
    GLsizei regionD;
};

}  // namespace

// Helper: fill an existing level's rgba8 + native-format buffers with
// a single `data` texel (or zeros). `data==nullptr` means GL-spec-zero
// (RGBA8 {0,0,0,0}, native zero-fill; alpha defaults to 1 for formats
// that have an alpha channel, matching GL 4.6 §8.19).
// Declared as free-file-scope function to keep the clearTexImage body
// compact; delegates format/native conversion back into `impl_` via the
// public `Impl*` pointer passed in.
template <typename ImplT>
static void fillLevelWithClearValue_T(ImplT* impl, GLTextureObject& tex,
                                      GLTextureImageLevel& img,
                                      GLint xoff, GLint yoff, GLint zoff,
                                      GLsizei regionW, GLsizei regionH, GLsizei regionD,
                                      GLenum format, GLenum type, const void* data)
{
    // RGBA8 shadow fill — drop to 8-bit per channel, used for sampling
    // paths that fall back to rgba8.
    std::uint8_t clearRGBA[4] = {0, 0, 0, 0};
    if (data != nullptr) {
        const std::size_t components = componentCountForFormat(format);
        for (std::size_t c = 0; c < components && c < 4; ++c) {
            clearRGBA[c] = ImplT::readComponentAsU8(
                static_cast<const std::uint8_t*>(data), type, c);
        }
    }
    // For a full-level clear (region == image size, offsets == 0), just
    // fill the whole backing store. Otherwise, fill per-pixel over the
    // specified rectangle.
    const std::size_t levelW = static_cast<std::size_t>(img.desc.width);
    const std::size_t levelH = static_cast<std::size_t>(img.desc.height);
    const std::size_t levelD = std::max<std::size_t>(1, img.desc.depth);
    const bool wholeLevel = (xoff == 0 && yoff == 0 && zoff == 0 &&
                             static_cast<std::size_t>(regionW) == levelW &&
                             static_cast<std::size_t>(regionH) == levelH &&
                             static_cast<std::size_t>(regionD) == levelD);

    // Clamp region to level bounds defensively.
    const std::size_t x0 = std::min<std::size_t>(static_cast<std::size_t>(xoff), levelW);
    const std::size_t y0 = std::min<std::size_t>(static_cast<std::size_t>(yoff), levelH);
    const std::size_t z0 = std::min<std::size_t>(static_cast<std::size_t>(zoff), levelD);
    const std::size_t x1 = std::min<std::size_t>(x0 + static_cast<std::size_t>(regionW), levelW);
    const std::size_t y1 = std::min<std::size_t>(y0 + static_cast<std::size_t>(regionH), levelH);
    const std::size_t z1 = std::min<std::size_t>(z0 + static_cast<std::size_t>(regionD), levelD);

    if (!img.rgba8.empty()) {
        if (wholeLevel) {
            for (std::size_t j = 0; j + 4 <= img.rgba8.size(); j += 4) {
                std::memcpy(img.rgba8.data() + j, clearRGBA, 4);
            }
        } else {
            for (std::size_t z = z0; z < z1; ++z) {
                for (std::size_t y = y0; y < y1; ++y) {
                    for (std::size_t x = x0; x < x1; ++x) {
                        const std::size_t idx = ((z * levelH) + y) * levelW + x;
                        if (idx * 4 + 4 <= img.rgba8.size()) {
                            std::memcpy(img.rgba8.data() + idx * 4, clearRGBA, 4);
                        }
                    }
                }
            }
        }
    }

    // Native-format fill — build a 1×1×1 native pixel via buildNativeUpload,
    // then replicate across the native buffer. This is required for
    // non-RGBA8 formats where glGetTexImage reads from nativeData.
    if (img.nativeBpp > 0 && !img.nativeData.empty()) {
        std::vector<std::uint8_t> singlePixel;
        std::size_t pixelBpp = 0;
        bool built = false;
        if (data != nullptr) {
            built = impl->buildNativeUpload(img.desc.internalFormat,
                                            1, 1, 1,
                                            format, type, data,
                                            singlePixel, pixelBpp);
        }
        if (!built || singlePixel.size() != img.nativeBpp) {
            // Null `data` or non-representable → zero-fill, matching GL spec.
            singlePixel.assign(img.nativeBpp, 0);
            pixelBpp = img.nativeBpp;
        }
        if (wholeLevel) {
            for (std::size_t j = 0; j + img.nativeBpp <= img.nativeData.size(); j += img.nativeBpp) {
                std::memcpy(img.nativeData.data() + j, singlePixel.data(), img.nativeBpp);
            }
        } else {
            for (std::size_t z = z0; z < z1; ++z) {
                for (std::size_t y = y0; y < y1; ++y) {
                    for (std::size_t x = x0; x < x1; ++x) {
                        const std::size_t idx = ((z * levelH) + y) * levelW + x;
                        const std::size_t byteIdx = idx * img.nativeBpp;
                        if (byteIdx + img.nativeBpp <= img.nativeData.size()) {
                            std::memcpy(img.nativeData.data() + byteIdx,
                                        singlePixel.data(), img.nativeBpp);
                        }
                    }
                }
            }
        }
    }

    (void)tex;
}

bool GLContext::clearTexImage(GLuint texture, GLint level, GLenum format, GLenum type, const void* data) {
    auto* tex = impl_->objects->textures().get(texture);
    if (!tex) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // If level is -1, clear all defined levels to zero.
    if (level < 0) {
        for (auto& [lvl, img] : tex->levels) {
            if (img.defined) {
                fillLevelWithClearValue_T(impl_.get(), *tex, img,
                                          0, 0, 0,
                                          img.desc.width, img.desc.height, img.desc.depth,
                                          format, type, data);
            }
        }
        if (tex->metalTexture != nullptr) {
            impl_->replaceMetalTexture(*tex);
        }
        return true;
    }
    auto it = tex->levels.find(level);
    if (it == tex->levels.end() || !it->second.defined) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    fillLevelWithClearValue_T(impl_.get(), *tex, it->second,
                            0, 0, 0,
                            it->second.desc.width,
                            it->second.desc.height,
                            it->second.desc.depth,
                            format, type, data);
    if (tex->metalTexture != nullptr) {
        impl_->replaceMetalTexture(*tex);
    }
    return true;
}

bool GLContext::clearTexSubImage(GLuint texture, GLint level,
                                 GLint xoffset, GLint yoffset, GLint zoffset,
                                 GLsizei width, GLsizei height, GLsizei depth,
                                 GLenum format, GLenum type, const void* data) {
    auto* tex = impl_->objects->textures().get(texture);
    if (!tex) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    auto it = tex->levels.find(level);
    if (it == tex->levels.end() || !it->second.defined) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // Zero-dimension sub-image is a no-op per GL spec — accept and return.
    if (width == 0 || height == 0 || depth == 0) return true;
    fillLevelWithClearValue_T(impl_.get(), *tex, it->second,
                            xoffset, yoffset, zoffset,
                            width, height, depth,
                            format, type, data);
    if (tex->metalTexture != nullptr) {
        impl_->replaceMetalTexture(*tex);
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.5 — DSA object creation.
// ---------------------------------------------------------------------------

bool GLContext::createBuffers(GLsizei n, GLuint* buffers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        buffers[i] = impl_->objects->buffers().reserveName();
        auto* obj = impl_->objects->buffers().get(buffers[i]);
        if (obj) obj->instantiated = true;
    }
    return true;
}

bool GLContext::createTextures(GLenum target, GLsizei n, GLuint* textures) {
    // GL 4.5 §8.1: target must be one of the allowed texture-object
    // target enums. CTS `direct_state_access.textures_creation_errors`
    // plants an invalid target and expects INVALID_ENUM.
    switch (target) {
        case GL_TEXTURE_1D: case GL_TEXTURE_2D: case GL_TEXTURE_3D:
        case GL_TEXTURE_1D_ARRAY: case GL_TEXTURE_2D_ARRAY:
        case GL_TEXTURE_RECTANGLE: case GL_TEXTURE_BUFFER:
        case GL_TEXTURE_CUBE_MAP: case GL_TEXTURE_CUBE_MAP_ARRAY:
        case GL_TEXTURE_2D_MULTISAMPLE:
        case GL_TEXTURE_2D_MULTISAMPLE_ARRAY:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        textures[i] = impl_->objects->textures().reserveName();
        // DSA textures know their target from creation and are immediately usable.
        auto* obj = impl_->objects->textures().get(textures[i]);
        if (obj) {
            obj->target = target;
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::createSamplers(GLsizei n, GLuint* samplers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    // DSA createSamplers immediately allocates an object — `instantiated`
    // must be true so glSamplerParameter / glGetSamplerParameter don't
    // raise GL_INVALID_OPERATION (unlike glGenSamplers which only reserves
    // the name and requires a subsequent glBindSampler to materialise).
    for (GLsizei i = 0; i < n; ++i) {
        samplers[i] = impl_->objects->samplers().reserveName();
        if (auto* obj = impl_->objects->samplers().get(samplers[i])) {
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::createFramebuffers(GLsizei n, GLuint* framebuffers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        framebuffers[i] = impl_->objects->framebuffers().reserveName();
        auto* obj = impl_->objects->framebuffers().get(framebuffers[i]);
        if (obj) obj->instantiated = true;
    }
    return true;
}

bool GLContext::createRenderbuffers(GLsizei n, GLuint* renderbuffers) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        renderbuffers[i] = impl_->objects->renderbuffers().reserveName();
        auto* obj = impl_->objects->renderbuffers().get(renderbuffers[i]);
        if (obj) obj->instantiated = true;
    }
    return true;
}

bool GLContext::createVertexArrays(GLsizei n, GLuint* arrays) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        arrays[i] = impl_->objects->vertexArrays().reserveName();
        if (auto* obj = impl_->objects->vertexArrays().get(arrays[i])) {
            obj->instantiated = true;
            // GL 4.5 §10.3.1 — glCreateVertexArrays instantiates the
            // object up-front (unlike glGenVertexArrays which defers
            // to first bind). DSA state queries like
            // glGetVertexArrayIndexediv / glVertexArrayAttribFormat
            // are callable immediately after createVertexArrays, so
            // the attribute + binding-point vectors need to carry
            // their spec-defined defaults (SIZE=4, TYPE=GL_FLOAT,
            // bindingIndex=i, binding stride=16). Without this
            // init, the default test queries return 0 for SIZE /
            // TYPE because the attributes vector is empty.
            impl_->objects->initializeVertexArray(*obj);
        }
    }
    return true;
}

bool GLContext::createTransformFeedbacks(GLsizei n, GLuint* ids) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        ids[i] = impl_->objects->transformFeedbacks().reserveName();
        auto* obj = impl_->objects->transformFeedbacks().get(ids[i]);
        if (obj) {
            // DSA glCreateTransformFeedbacks instantiates up-front
            // per GL 4.5 §13.2 (no first-bind required).
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::createProgramPipelines(GLsizei n, GLuint* pipelines) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    for (GLsizei i = 0; i < n; ++i) {
        pipelines[i] = impl_->objects->programPipelines().reserveName();
        auto* obj = impl_->objects->programPipelines().get(pipelines[i]);
        if (obj) {
            // DSA glCreateProgramPipelines instantiates up-front.
            obj->instantiated = true;
        }
    }
    return true;
}

bool GLContext::createQueries(GLenum target, GLsizei n, GLuint* ids) {
    if (n < 0) { pushError(GL_INVALID_VALUE); return false; }
    // GL 4.5 §4.2.1: INVALID_ENUM if target is not one of the accepted query
    // targets. Without this, CTS direct_state_access.queries_errors hangs
    // indefinitely in the post-fail drain loop
    // `while (error == gl.getError()) ;` because it captured GL_NO_ERROR
    // (since we silently accepted the invalid target and set no error).
    switch (target) {
        case GL_SAMPLES_PASSED:
        case GL_ANY_SAMPLES_PASSED:
        case GL_ANY_SAMPLES_PASSED_CONSERVATIVE:
        case GL_PRIMITIVES_GENERATED:
        case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
        case GL_TIME_ELAPSED:
        case GL_TIMESTAMP:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    for (GLsizei i = 0; i < n; ++i) {
        ids[i] = impl_->objects->queries().reserveName();
        auto* obj = impl_->objects->queries().get(ids[i]);
        if (obj) {
            obj->target = target;
            // DSA glCreateQueries creates fully-instantiated query
            // objects — glIsQuery returns TRUE immediately without
            // a subsequent glBeginQuery.
            obj->instantiated = true;
        }
    }
    return true;
}

// ---------------------------------------------------------------------------
// GL 4.5 — DSA buffer operations.
// All delegate to existing bind-target implementations via save/restore.
// ---------------------------------------------------------------------------

bool GLContext::namedBufferStorage(GLuint buffer, GLsizeiptr size, const void* data, GLbitfield flags) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = bufferStorage(target, size, data, flags);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

bool GLContext::namedBufferData(GLuint buffer, GLsizeiptr size, const void* data, GLenum usage) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = bufferData(target, size, data, usage);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

bool GLContext::namedBufferSubData(GLuint buffer, GLintptr offset, GLsizeiptr size, const void* data) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLenum target = GL_COPY_WRITE_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = bufferSubData(target, offset, size, data);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

bool GLContext::copyNamedBufferSubData(GLuint readBuffer, GLuint writeBuffer, GLintptr readOffset, GLintptr writeOffset, GLsizeiptr size) {
    if (!impl_->objects->buffers().get(readBuffer)) { pushError(GL_INVALID_OPERATION); return false; }
    if (!impl_->objects->buffers().get(writeBuffer)) { pushError(GL_INVALID_OPERATION); return false; }
    GLuint prevRead = impl_->state->boundBuffer(GL_COPY_READ_BUFFER);
    GLuint prevWrite = impl_->state->boundBuffer(GL_COPY_WRITE_BUFFER);
    impl_->state->bindBuffer(GL_COPY_READ_BUFFER, readBuffer);
    impl_->state->bindBuffer(GL_COPY_WRITE_BUFFER, writeBuffer);
    bool ok = copyBufferSubData(GL_COPY_READ_BUFFER, GL_COPY_WRITE_BUFFER, readOffset, writeOffset, size);
    impl_->state->bindBuffer(GL_COPY_READ_BUFFER, prevRead);
    impl_->state->bindBuffer(GL_COPY_WRITE_BUFFER, prevWrite);
    return ok;
}

bool GLContext::mapNamedBuffer(GLuint buffer, GLenum access, void** result) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); *result = nullptr; return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    *result = mapBuffer(target, access);
    impl_->state->bindBuffer(target, prev);
    return true;
}

bool GLContext::mapNamedBufferRange(GLuint buffer, GLintptr offset, GLsizeiptr length, GLbitfield access, void** result) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); *result = nullptr; return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    *result = mapBufferRange(target, offset, length, access);
    impl_->state->bindBuffer(target, prev);
    return true;
}

bool GLContext::unmapNamedBuffer(GLuint buffer, GLboolean* result) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); *result = GL_FALSE; return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    *result = unmapBuffer(target);
    impl_->state->bindBuffer(target, prev);
    return true;
}

bool GLContext::flushMappedNamedBufferRange(GLuint buffer, GLintptr offset, GLsizeiptr length) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = flushMappedBufferRange(target, offset, length);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

bool GLContext::clearNamedBufferData(GLuint buffer, GLenum internalformat, GLenum format, GLenum type, const void* data) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = clearBufferData(target, internalformat, format, type, data);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

bool GLContext::clearNamedBufferSubData(GLuint buffer, GLenum internalformat, GLintptr offset, GLsizeiptr size, GLenum format, GLenum type, const void* data) {
    auto* obj = impl_->objects->buffers().get(buffer);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    GLenum target = GL_ARRAY_BUFFER;
    GLuint prev = impl_->state->boundBuffer(target);
    impl_->state->bindBuffer(target, buffer);
    bool ok = clearBufferSubData(target, internalformat, offset, size, format, type, data);
    impl_->state->bindBuffer(target, prev);
    return ok;
}

