bool GLContext::textureParameterIuiv(GLuint texture, GLenum pname, const GLuint* params) {
    DSA_TEX_WRAP(texture, {
        if (dsaIsSamplerStateOnMultisampleTarget(_target, pname)) {
            pushError(GL_INVALID_OPERATION);
            return false;
