}

bool GLContext::getTextureParameterIuiv(GLuint texture, GLenum pname, GLuint* params) {
    DSA_TEX_WRAP(texture, {
        if (!isParameterQueryableTarget(_target)) {
            pushError(GL_INVALID_OPERATION);
            return false;
