bool GLContext::getVertexArrayiv(GLuint vaobj, GLenum pname, GLint* param) {
    DSA_VAO_CHECK(vaobj)
    // GL 4.5 §10.3.12: pname is restricted to
    // GL_ELEMENT_ARRAY_BUFFER_BINDING for `glGetVertexArrayiv`
    // (no other enum is accepted at the per-VAO level). CTS
    // `direct_state_access.vertex_arrays_get_vertex_array_errors`
    // plants a bogus pname and asserts INVALID_ENUM.
    if (pname != GL_ELEMENT_ARRAY_BUFFER_BINDING) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (param) {
        *param = static_cast<GLint>(_vao->elementArrayBuffer);
    }
    return true;
}

// GL 4.5 §10.3.12: accepted pnames for glGetVertexArrayIndexed{,64}iv.
static bool isValidVertexArrayIndexedPname(GLenum pname) {
    switch (pname) {
        case GL_VERTEX_ATTRIB_ARRAY_ENABLED:
        case GL_VERTEX_ATTRIB_ARRAY_SIZE:
        case GL_VERTEX_ATTRIB_ARRAY_STRIDE:
        case GL_VERTEX_ATTRIB_ARRAY_TYPE:
        case GL_VERTEX_ATTRIB_ARRAY_NORMALIZED:
        case GL_VERTEX_ATTRIB_ARRAY_INTEGER:
        case GL_VERTEX_ATTRIB_ARRAY_LONG:
        case GL_VERTEX_ATTRIB_ARRAY_DIVISOR:
        case GL_VERTEX_ATTRIB_RELATIVE_OFFSET:
            return true;
        default:
            return false;
    }
}

bool GLContext::getVertexArrayIndexediv(GLuint vaobj, GLuint index, GLenum pname, GLint* param) {
    DSA_VAO_CHECK(vaobj)
    if (!isValidVertexArrayIndexedPname(pname)) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    // GL 4.5 §10.3.12: `index` is an attribute index for the
    // per-attribute pnames; GL_INVALID_VALUE if out of range.
    if (index >= _vao->attributes.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param == nullptr) return true;
    const auto& attr = _vao->attributes[index];
    switch (pname) {
        case GL_VERTEX_ATTRIB_ARRAY_ENABLED:
            *param = attr.enabled ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_SIZE:
            *param = attr.size;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_STRIDE:
            // GL 4.6 Table 22.3 per-attribute state — independent from
            // VERTEX_BINDING_STRIDE (Table 22.4 per-binding state).
            // Returns the stride set via glVertexAttribPointer or
            // glVertexAttribIPointer, default 0. CTS
            // `vertex_arrays_get_vertex_array_indexed` asserts 0 on a
            // fresh VAO even though the binding-point stride defaults
            // to 16.
            *param = attr.stride;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_TYPE:
            *param = static_cast<GLint>(attr.type);
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_NORMALIZED:
            *param = attr.normalized ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_INTEGER:
            *param = attr.integer ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_LONG:
            *param = attr.longData ? GL_TRUE : GL_FALSE;
            return true;
        case GL_VERTEX_ATTRIB_ARRAY_DIVISOR:
            if (attr.bindingIndex < _vao->bindingPoints.size()) {
                *param = static_cast<GLint>(_vao->bindingPoints[attr.bindingIndex].divisor);
            } else {
                *param = static_cast<GLint>(attr.divisor);
            }
            return true;
        case GL_VERTEX_ATTRIB_RELATIVE_OFFSET:
            *param = static_cast<GLint>(attr.relativeOffset);
            return true;
    }
    // Should be unreachable — isValidVertexArrayIndexedPname gated.
    *param = 0;
    return true;
}

bool GLContext::getVertexArrayIndexed64iv(GLuint vaobj, GLuint index, GLenum pname, GLint64* param) {
    DSA_VAO_CHECK(vaobj)
    // GL 4.5 §10.3.12: The 64-bit form only accepts
    // GL_VERTEX_BINDING_OFFSET — it's the 64-bit buffer offset from
    // the attribute's binding point.
    if (pname != GL_VERTEX_BINDING_OFFSET) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (index >= _vao->attributes.size()) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param == nullptr) return true;
    const auto& attr = _vao->attributes[index];
    if (attr.bindingIndex < _vao->bindingPoints.size()) {
        *param = static_cast<GLint64>(_vao->bindingPoints[attr.bindingIndex].offset);
    } else {
        *param = 0;
    }
    return true;
}

#undef DSA_VAO_WRAP
#undef DSA_VAO_CHECK

// ---------------------------------------------------------------------------
// GL 4.5 — DSA transform feedback operations.
// ---------------------------------------------------------------------------

bool GLContext::transformFeedbackBufferBase(GLuint xfb, GLuint index, GLuint buffer) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    if (index >= GLTransformFeedbackObject::kMaxTfBuffers) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Record the per-TF-object binding for the DSA getter queries
    // (getTransformFeedbacki_v / getTransformFeedbacki64_v).
    obj->bufferBindings[index] = {buffer, 0, 0};
    // Also mirror into the global indexed binding so draw-time
    // consumers of the currently-bound TF see the update (CTS's
    // DSA xfb tests chain a Bind after Buffer* to observe the
    // global state consistent with the per-object state).
    bindBufferBase(GL_TRANSFORM_FEEDBACK_BUFFER, index, buffer);
    return true;
}

bool GLContext::transformFeedbackBufferRange(GLuint xfb, GLuint index, GLuint buffer, GLintptr offset, GLsizeiptr size) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    if (index >= GLTransformFeedbackObject::kMaxTfBuffers) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    obj->bufferBindings[index] = {buffer, offset, size};
    bindBufferRange(GL_TRANSFORM_FEEDBACK_BUFFER, index, buffer, offset, size);
    return true;
}

bool GLContext::getTransformFeedbackiv(GLuint xfb, GLenum pname, GLint* param) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    // GL 4.5 §13.2.4: pname restricted to the boolean state enums.
    // CTS `direct_state_access.xfb_errors` plants a bogus pname and
    // asserts INVALID_ENUM; any write to the output buffer on the
    // error path is forbidden.
    if (pname != GL_TRANSFORM_FEEDBACK_ACTIVE &&
        pname != GL_TRANSFORM_FEEDBACK_PAUSED) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    if (param) {
        if (pname == GL_TRANSFORM_FEEDBACK_ACTIVE) *param = obj->active ? GL_TRUE : GL_FALSE;
        else *param = obj->paused ? GL_TRUE : GL_FALSE;
    }
    return true;
}

bool GLContext::getTransformFeedbacki_v(GLuint xfb, GLenum pname, GLuint index, GLint* param) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    // GL 4.5 §13.2.4: indexed 32-bit query only accepts
    // TRANSFORM_FEEDBACK_BUFFER_BINDING.
    if (pname != GL_TRANSFORM_FEEDBACK_BUFFER_BINDING) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLint64 maxXfbBuffers = 4;
    if (impl_->capabilities != nullptr) {
        impl_->capabilities->queryInteger64(
            GL_MAX_TRANSFORM_FEEDBACK_BUFFERS, &maxXfbBuffers);
    }
    if (index >= static_cast<GLuint>(maxXfbBuffers)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param) {
        if (index < GLTransformFeedbackObject::kMaxTfBuffers) {
            *param = static_cast<GLint>(obj->bufferBindings[index].buffer);
        } else {
            *param = 0;
        }
    }
    return true;
}

bool GLContext::getTransformFeedbacki64_v(GLuint xfb, GLenum pname, GLuint index, GLint64* param) {
    auto* obj = impl_->objects->transformFeedbacks().get(xfb);
    if (!obj) { pushError(GL_INVALID_OPERATION); return false; }
    // GL 4.5 §13.2.4: 64-bit indexed query accepts
    // TRANSFORM_FEEDBACK_BUFFER_{START, SIZE}.
    if (pname != GL_TRANSFORM_FEEDBACK_BUFFER_START &&
        pname != GL_TRANSFORM_FEEDBACK_BUFFER_SIZE) {
        pushError(GL_INVALID_ENUM);
        return false;
    }
    GLint64 maxXfbBuffers = 4;
    if (impl_->capabilities != nullptr) {
        impl_->capabilities->queryInteger64(
            GL_MAX_TRANSFORM_FEEDBACK_BUFFERS, &maxXfbBuffers);
    }
    if (index >= static_cast<GLuint>(maxXfbBuffers)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (param) {
        if (index < GLTransformFeedbackObject::kMaxTfBuffers) {
            const auto& bind = obj->bufferBindings[index];
            if (pname == GL_TRANSFORM_FEEDBACK_BUFFER_START) {
                *param = static_cast<GLint64>(bind.offset);
            } else {  // GL_TRANSFORM_FEEDBACK_BUFFER_SIZE
                *param = static_cast<GLint64>(bind.size);
            }
        } else {
            *param = 0;
        }
    }
    return true;
}

