// GL 4.5 §4.2 / §4.2.1 shared validation for glGetQueryBufferObject*iv
// and the 64-bit variants. CTS
// `direct_state_access.queries_errors` walks every spec violation
// in sequence:
//   (a) id is not an existing query name              → INVALID_OPERATION
//   (b) query object `id` is still active             → INVALID_OPERATION
//   (c) pname not one of the accepted result enums    → INVALID_ENUM
//   (d) buffer offset + sizeof(result) > buffer size  → INVALID_OPERATION
//   (e) offset < 0 or not aligned to sizeof(result)   → INVALID_VALUE
// All four getQueryBufferObject* flavors share the same logic and
// differ only in the result-element byte size.
//
bool GLContext::validateQueryBufferObjectGet(
    GLuint id, GLuint buffer, GLenum pname, GLintptr offset,
    std::size_t resultBytes) {
    auto* buf = impl_->objects->buffers().get(buffer);
    if (!buf) { pushError(GL_INVALID_OPERATION); return false; }
    auto* q = impl_->objects->queries().get(id);
    if (!q || !q->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (q->active) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    switch (pname) {
        case GL_QUERY_RESULT:
        case GL_QUERY_RESULT_AVAILABLE:
        case GL_QUERY_RESULT_NO_WAIT:
        case GL_QUERY_TARGET:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    if (offset < 0 ||
        (resultBytes > 0 && (offset % static_cast<GLintptr>(resultBytes)) != 0)) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    if (offset + static_cast<GLintptr>(resultBytes) > buf->size) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    return true;
}

// GL 4.5 §4.2.1: on success, glGetQueryBufferObject* writes the
// parameter value into the target buffer at `offset`. CTS
// `direct_state_access.queries_functional` then glMapBuffer's the
// QUERY_BUFFER and compares against expected values — so the write
// must actually happen (the prior stub only validated).
//
// Result semantic per pname (mirrors non-DSA glGetQueryObject*v):
//   GL_QUERY_RESULT / GL_QUERY_RESULT_NO_WAIT → query->result
//   GL_QUERY_RESULT_AVAILABLE → GL_FALSE when still active, else GL_TRUE
//   GL_QUERY_TARGET → query->target
// Result is cast to the caller's integer width (truncation is
// acceptable per spec — GL 4.5 §4.2.1 note: the counter is copied
// "as if" via the matching scalar write).
template <typename T>
bool GLContext::writeQueryBufferObject(GLuint id, GLuint buffer, GLenum pname, GLintptr offset) {
    if (!validateQueryBufferObjectGet(id, buffer, pname, offset, sizeof(T))) {
        return false;
    }
    auto* buf = impl_->objects->buffers().get(buffer);
    auto* q = impl_->objects->queries().get(id);
    if (!buf || !q) return false;
    GLuint64 raw = 0;
    switch (pname) {
        case GL_QUERY_RESULT:
        case GL_QUERY_RESULT_NO_WAIT:
            raw = q->result;
            break;
        case GL_QUERY_RESULT_AVAILABLE:
            raw = q->active ? GL_FALSE : GL_TRUE;
            break;
        case GL_QUERY_TARGET:
            raw = static_cast<GLuint64>(q->target);
            break;
        default:
            return false;
    }
    T value = static_cast<T>(raw);
    auto& shadow = buf->shadowBytes;
    if (shadow.size() < static_cast<std::size_t>(offset) + sizeof(T)) {
        shadow.resize(static_cast<std::size_t>(buf->size));
    }
    std::memcpy(shadow.data() + static_cast<std::size_t>(offset),
                &value, sizeof(T));
    impl_->syncMetalFromShadow(*buf, offset,
                               static_cast<GLsizeiptr>(sizeof(T)));
    return true;
}

bool GLContext::getQueryBufferObjectiv(GLuint id, GLuint buffer, GLenum pname, GLintptr offset) {
    return writeQueryBufferObject<GLint>(id, buffer, pname, offset);
}

bool GLContext::getQueryBufferObjectuiv(GLuint id, GLuint buffer, GLenum pname, GLintptr offset) {
    return writeQueryBufferObject<GLuint>(id, buffer, pname, offset);
}

bool GLContext::getQueryBufferObjecti64v(GLuint id, GLuint buffer, GLenum pname, GLintptr offset) {
    return writeQueryBufferObject<GLint64>(id, buffer, pname, offset);
}

bool GLContext::getQueryBufferObjectui64v(GLuint id, GLuint buffer, GLenum pname, GLintptr offset) {
    return writeQueryBufferObject<GLuint64>(id, buffer, pname, offset);
}

// ---------------------------------------------------------------------------
// GL 4.6 — Indirect count draws, SPIR-V specialization, polygon offset clamp
// ---------------------------------------------------------------------------

// GL 4.6 §10.5 validation for glMultiDraw{Arrays,Elements}IndirectCount.
// Common gate: drawcount (offset into PARAMETER_BUFFER) must be aligned
// to 4 bytes; PARAMETER_BUFFER must be bound; the referenced count +
// maxdrawcount entries must fit in the parameter buffer.
bool GLContext::validateIndirectCount(GLintptr drawcount, GLsizei maxdrawcount) {
    if (maxdrawcount < 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // drawcount is a byte offset; must be a multiple of sizeof(GLsizei)=4.
    if ((drawcount % 4) != 0) {
        pushError(GL_INVALID_VALUE);
        return false;
    }
    const GLuint paramBuffer =
        impl_->state->boundBuffer(GL_PARAMETER_BUFFER);
    if (paramBuffer == 0) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    GLBufferObject* bo = impl_->objects->buffers().get(paramBuffer);
    if (bo == nullptr) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // The parameter buffer must contain at least
    // drawcount + 4 (one GLsizei) bytes — enough to read the
    // sub-draw count. Note: the spec does NOT require space for
    // the full maxdrawcount entries; only the count itself.
    if (drawcount + static_cast<GLintptr>(sizeof(GLsizei)) >
        static_cast<GLintptr>(bo->size)) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    return true;
}

// GL 3.0 §2.14 / GL 4.5 ARB_conditional_render_inverted:
// begin/end a conditional draw block. `id` must be a live query object;
// `mode` must be one of the eight accepted modes. The state lives on
// Impl; the draw paths consult `shouldSkipDraw` below.
bool GLContext::beginConditionalRender(GLuint id, GLenum mode) {
    if (impl_->conditionalRenderMode != 0) {
        // Already active — GL 4.6 §2.3.3 requires INVALID_OPERATION.
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    switch (mode) {
        case GL_QUERY_WAIT:
        case GL_QUERY_NO_WAIT:
        case GL_QUERY_BY_REGION_WAIT:
        case GL_QUERY_BY_REGION_NO_WAIT:
        case GL_QUERY_WAIT_INVERTED:
        case GL_QUERY_NO_WAIT_INVERTED:
        case GL_QUERY_BY_REGION_WAIT_INVERTED:
        case GL_QUERY_BY_REGION_NO_WAIT_INVERTED:
            break;
        default:
            pushError(GL_INVALID_ENUM);
            return false;
    }
    auto* q = impl_->objects->queries().get(id);
    if (q == nullptr || !q->instantiated) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // §2.3.3: if the query is currently active, INVALID_OPERATION.
    if (q->active) {
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    // §2.3.3: accepted query targets for conditional render.
    switch (q->target) {
        case GL_SAMPLES_PASSED:
        case GL_ANY_SAMPLES_PASSED:
        case GL_ANY_SAMPLES_PASSED_CONSERVATIVE:
        case GL_PRIMITIVES_GENERATED:
        case GL_TRANSFORM_FEEDBACK_PRIMITIVES_WRITTEN:
        case GL_TRANSFORM_FEEDBACK_OVERFLOW:
        case GL_TRANSFORM_FEEDBACK_STREAM_OVERFLOW:
            break;
        default:
            pushError(GL_INVALID_OPERATION);
            return false;
    }
    impl_->conditionalRenderQueryId = id;
    impl_->conditionalRenderMode = mode;
    return true;
}

void GLContext::endConditionalRender() {
    if (impl_->conditionalRenderMode == 0) {
        pushError(GL_INVALID_OPERATION);
        return;
    }
    impl_->conditionalRenderQueryId = 0;
    impl_->conditionalRenderMode = 0;
}

bool GLContext::multiDrawArraysIndirectCount(GLenum mode, const void* indirect,
                                              GLintptr drawcount, GLsizei maxdrawcount, GLsizei stride) {
    if (!validateIndirectCount(drawcount, maxdrawcount)) return false;
    // Delegates to the non-count variant with maxdrawcount as the
    // conservative upper bound. A real GPU-sourced count readback
    // would require staging the parameter buffer at draw time.
    return multiDrawArraysIndirect(mode, indirect, maxdrawcount, stride);
}

bool GLContext::multiDrawElementsIndirectCount(GLenum mode, GLenum type, const void* indirect,
                                                GLintptr drawcount, GLsizei maxdrawcount, GLsizei stride) {
    if (!validateIndirectCount(drawcount, maxdrawcount)) return false;
    return multiDrawElementsIndirect(mode, type, indirect, maxdrawcount, stride);
}

bool GLContext::specializeShader(GLuint shader, const GLchar* pEntryPoint,
                                  GLuint numSpecializationConstants,
                                  const GLuint* pConstantIndex, const GLuint* pConstantValue) {
    // GL_ARB_gl_spirv / GL 4.6 §7.2 — promote a SPIR-V binary that was
    // loaded via glShaderBinary into a compiled shader object. We
    // already use SPIR-V as our internal representation (via glslang
    // for the GLSL path), so intake is a matter of validation +
    // marking the object compiled. Real specialization-constant
    // substitution is handled at MSL translation time by
    // `CompilerMSL::set_constant` — for now we record the (index,
    // value) pairs on the shader so downstream SPIRV-Cross calls can
    // consume them.
    GLShaderObject* object = impl_->objects->shaders().get(shader);
    if (object == nullptr) {
        // GL 4.6 §7.2 distinguishes two cases:
        //  * name refers to a program object → INVALID_OPERATION
        //  * name is not a shader or a program → INVALID_VALUE
        if (impl_->objects->programs().get(shader) != nullptr) {
            pushError(GL_INVALID_OPERATION);
        } else {
            pushError(GL_INVALID_VALUE);
        }
        return false;
    }
    // GL 4.6 §7.2: "INVALID_OPERATION is generated if <shader> is not
    // the name of a shader with a SPIR_V_BINARY_ARB state of TRUE"
    // — covers both "no SPIR-V loaded" and "already compiled from
    // GLSL via glCompileShader".
    if (!object->isSpirvBinary || object->spirv.empty()) {
        object->compileLog = "glSpecializeShader: SPIR_V_BINARY_ARB is FALSE on this shader";
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    if (object->compiled) {
        // Specialization may only be done once — reinvoking returns
        // INVALID_OPERATION per GL 4.6 §7.2.
        pushError(GL_INVALID_OPERATION);
        return false;
    }
    const char* entry = (pEntryPoint != nullptr) ? pEntryPoint : "main";
    // Minimal SPIR-V validation: the 5-word header must start with
    // the magic number 0x07230203 (little-endian).
    if (object->spirv.size() < 5 || object->spirv[0] != 0x07230203u) {
        object->compileLog = "glSpecializeShader: SPIR-V magic number missing";
        pushError(GL_INVALID_VALUE);
        return false;
    }
    // Entry-point + specialization-constant validation. SPIRV-Cross's
    // base Compiler class can walk the module and enumerate entry
    // points and declared spec-constant IDs without a backend. We
    // construct one temporarily here; the real MSL translation
    // (link-time) builds its own CompilerMSL anyway.
    try {
        spirv_cross::Compiler introspect(object->spirv.data(), object->spirv.size());
        const auto entries = introspect.get_entry_points_and_stages();
        bool entryOK = false;
        for (const auto& e : entries) {
            if (e.name == entry) { entryOK = true; break; }
        }
        if (!entryOK) {
            object->compileLog = std::string("glSpecializeShader: entry point '")
                                 + entry + "' not found in SPIR-V module";
            pushError(GL_INVALID_VALUE);
            return false;
        }
        // GL 4.6 §7.2 errors: INVALID_VALUE when a spec-constant index
        // in pConstantIndex doesn't correspond to a SpecId in the
        // module. Collect declared IDs once, then check each caller
        // entry against the set.
        if (numSpecializationConstants > 0) {
            if (pConstantIndex == nullptr || pConstantValue == nullptr) {
                pushError(GL_INVALID_VALUE);
                return false;
            }
            const auto specConsts = introspect.get_specialization_constants();
            std::unordered_set<std::uint32_t> declaredIds;
            for (const auto& sc : specConsts) {
                declaredIds.insert(sc.constant_id);
            }
            for (GLuint i = 0; i < numSpecializationConstants; ++i) {
                if (declaredIds.find(pConstantIndex[i]) == declaredIds.end()) {
                    object->compileLog = "glSpecializeShader: specialization "
                                         "constant ID not declared in module";
                    pushError(GL_INVALID_VALUE);
                    return false;
                }
            }
            // TODO: hand the (index, value) pairs through to the
            // translator via a side-channel on GLShaderObject so
            // CompilerMSL::set_constant can apply them before emit.
            // Currently we accept the values but don't yet forward
            // them — tests that rely on specialization-constant
            // substitution will see default values. Commits that
            // wire this up can land separately.
        }
    } catch (const spirv_cross::CompilerError& e) {
        object->compileLog = std::string("glSpecializeShader: SPIR-V parse failed: ")
                             + e.what();
        pushError(GL_INVALID_VALUE);
        return false;
    }
    object->compiled = true;
    object->compileLog.clear();
    return true;
}

bool GLContext::polygonOffsetClamp(GLfloat factor, GLfloat units, GLfloat clamp) {
    // Extends glPolygonOffset with a clamp value. Store factor/units/clamp via
    // the state tracker for Metal's setDepthBias:slopeScale:clamp:.
    impl_->state->setPolygonOffsetClamp(factor, units, clamp);
    return true;
}

// Phase 3f-3: tess-emul CPU interpreter hook. Given a void* handle
// stored in `GLBufferObject::metalBuffer`, return the CPU-visible
// contents pointer. Apple Silicon's unified memory exposes MTLBuffer
// contents as a writable CPU pointer when the buffer is created in
// storage mode Shared (the default for every buffer AppGL creates
// for GL_ARRAY_BUFFER / GL_SHADER_STORAGE_BUFFER / …). nullptr on
// nil inputs so the caller can short-circuit cleanly.
void* metalBufferContents(void* metalBuffer) {
    id<MTLBuffer> buf = (__bridge id<MTLBuffer>)metalBuffer;
    if (buf == nil) return nullptr;
    return [buf contents];
}

}  // namespace appgl
